PERSONA_MARKER_USER_PREFIX = "[Persona switched to: "
PERSONA_MARKER_ASSISTANT_PREFIX = "Understood — staying in character as "

# (MOSS_MODEL_ID moved to the USER CONFIGURATION section near the top of this file.)
