# dev40: a first-pass rock/punk genre that the genre check replaced. The listening model's
# opening description is the first thing the writer reads; on a pop track it
# called the song a "Pop-Punk anthem" four times, and the writer then told the
# user the act is "often filed as pop-punk".
_GENRE_SUPERSEDED_RE = re.compile(
    r"RECOMMENDED GENRE FOR DISCUSSION: ([^\n]+?)\. Reasoning: MOSS-Music GENRE_RANKED led "
    r"with '([^'\n]+)' \(rock/punk family\)"
)
_GENRE_CHECK_HEAD = "GENRE CHECK (read before the description below):"
_HYPHENS_RE = re.compile(r"[\s\-\u2010\u2011\u2012\u2013\u2014]+")


# dev47: the genre check can also replace a rock/punk top with a pop/dance
# label from the listening model's own ranked list ("MOSS-Music ranked 'pop rock' first and 'dance-pop'
# among its next choices"). That is the same kind of replacement.
_GENRE_SUPERSEDED_ALT_RE = re.compile(
    r"RECOMMENDED GENRE FOR DISCUSSION: ([^\n]+?)\. Reasoning: MOSS-Music ranked '([^'\n]+)' first and '"
)


def _genre_superseded_pair(text):
    """(recommended, replaced first-pass label) for the last genre-check
    replacement of a rock/punk label in the notes, or None."""
    t = str(text or "")
    cands = [(m.start(), m.group(1).strip(), m.group(2).strip())
             for m in _GENRE_SUPERSEDED_RE.finditer(t)]
    if GENRE_CHECK_FIRM:
        for m in _GENRE_SUPERSEDED_ALT_RE.finditer(t):
            rec, old = m.group(1).strip(), m.group(2).strip()
            if _genre_family(old) == "rockish" and _genre_family(rec) != "rockish":
                cands.append((m.start(), rec, old))
    if not cands:
        return None
    _pos, rec, old = max(cands, key=lambda c: c[0])
    if not rec or not old or _HYPHENS_RE.sub(" ", rec.lower()) == _HYPHENS_RE.sub(" ", old.lower()):
        return None
    return rec, old


def _stem_prominence_ranks(text):
    """{stem: (rank, band)} from the STEM ACTIVITY / PROMINENCE block, or {}."""
    t = str(text or "")
    i = t.find("STEM ACTIVITY / PROMINENCE (ranked")
    if i < 0:
        return {}
    e = t.find("\n\n", i)
    ranks = {}
    for m in re.finditer(r"(?m)^(\d+)\) (\w+): ([a-z /]+?) \(RMS", t[i:e if e >= 0 else len(t)]):
        ranks.setdefault(m.group(2), (int(m.group(1)), m.group(3).strip()))
    return ranks


def _guitar_stem_reading(text):
    """How the separated guitar stem sits in the measured balance:
    (leads, detail). leads is True when the guitar stem is an active part
    ranked above the drums or the bass stem, False when it is quiet or ranked
    below both, None when no stem ranking is in the notes."""
    ranks = _stem_prominence_ranks(text)
    if not ranks:
        return None, ""
    n = len(ranks)
    g = ranks.get("guitar")
    if not g:
        return False, "there is no separated guitar part in the stem balance"
    if g[1] in ("silent/negligible", "low / background"):
        return False, f"the separated guitar stem is {g[1]} (#{g[0]} of {n} stems by prominence)"
    rhythm = [(s, ranks[s][0]) for s in ("drums", "bass") if s in ranks]
    if not rhythm:
        return None, ""
    if any(g[0] < r for _s, r in rhythm):
        return True, f"the separated guitar stem is {g[1]} and ranks #{g[0]} of {n} stems by prominence"
    above = [s for s, (r, _b) in sorted(ranks.items(), key=lambda kv: kv[1][0]) if r < g[0]]
    above_s = (", ".join(above[:-1]) + " and " + above[-1]) if len(above) > 1 else "".join(above)
    return False, (f"the separated guitar stem ranks #{g[0]} of {n} stems by prominence, "
                   f"below the {above_s}")


# dev56: the reverse replacement -- an electronic/pop first impression framed
# as rock (GENRE_DEV55 (a), GENRE_DEV56).
_GENRE_ROCKFLIP_RE = re.compile(
    r"RECOMMENDED GENRE FOR DISCUSSION: ([^\n]+?)\. Reasoning: MOSS-Music's ranked list named only "
    r"electronic/pop labels \('([^'\n]+)' first\)"
)


def _genre_rockflip_pair(text):
    """dev56: (recommended, [replaced first-pass labels]) when the genre
    check framed an electronic/pop first impression as rock, else None."""
    if not (GENRE_DEV55 and GENRE_DEV56):
        return None
    t = str(text or "")
    found = list(_GENRE_ROCKFLIP_RE.finditer(t))
    if not found:
        return None
    rec, top = found[-1].group(1).strip(), found[-1].group(2).strip()
    if not rec or _genre_family(rec) != "rockish":
        return None
    olds = [lab for lab in extract_genre_ranked_labels(t, max_n=5) if _genre_family(lab) != "rockish"]
    if not olds or _HYPHENS_RE.sub(" ", olds[0].lower()) != _HYPHENS_RE.sub(" ", top.lower()):
        olds = [top] + [x for x in olds if x != top]
    return rec, olds[:4]


def _label_list(labels, conj="or"):
    labels = [str(x) for x in labels if x]
    if len(labels) <= 1:
        return "".join(labels)
    return ", ".join(labels[:-1]) + f" {conj} " + labels[-1]


def _genre_rockflip_note(text):
    """dev56: GENRE CHECK line for an electronic/pop first impression the
    genre check replaced with a rock label, or ""."""
    pair = _genre_rockflip_pair(text)
    if not pair:
        return ""
    rec, olds = pair
    return (
        f"{_GENRE_CHECK_HEAD} the listening model's first-pass genre ranking at the top of these "
        f"notes led with '{olds[0]}'"
        + (f" (then {_label_list(olds[1:], 'and')})" if len(olds) > 1 else "")
        + ". That was its first impression of a clean, steady, drum-machine-like production; the "
        f"genre check against independent measurements replaced it with '{rec}' (see RECOMMENDED "
        f"GENRE FOR DISCUSSION). Describe the track as {rec} in every answer -- genre, era (including "
        "blind 'when does it sound like it's from?' answers), instrumentation, drums and comparisons "
        "alike -- and take the instruments from the measured stems, not from that first impression. "
        f"Do not call the track {_label_list(olds)}, do not describe it as club or dance-floor music, "
        "and never present those labels as how this track or its artist is usually filed, classed or "
        "known; the electronic quality is a secondary flavour."
    )


# Sentence of the dev33+ genre-check reasoning that the writer turned into
# "pop with a secondary pop-punk/rock flavour" and then "comfortable to call it
# a pop-rock song".
_GENRE_MINOR_FLAVOUR_OLD = "mention rock/punk only as a minor secondary flavour if still audible."
_GENRE_MINOR_FLAVOUR_NEW = (
    "do not call it rock, pop-rock or pop-punk (see the GENRE CHECK line at the top of these "
    "notes); a guitar-like layer, where audible, is one colour inside this production."
)


def _rock_label_list(old, conj="or", with_rock=True):
    """'rock, pop-rock or pop-punk' without repeats ("pop rock" and "pop-rock"
    are one label)."""
    out, seen = [], set()
    for lab in ((["rock"] if with_rock else []) + ["pop-rock", str(old or "").strip()]):
        k = _HYPHENS_RE.sub(" ", lab.lower()).strip()
        if lab and k not in seen:
            seen.add(k)
            out.append(lab)
    if len(out) == 1:
        return out[0]
    return ", ".join(out[:-1]) + f" {conj} " + out[-1]


def _genre_supersession_note(text):
    """A GENRE CHECK line naming the first-pass label the genre check replaced,
    or "" when nothing was replaced."""
    t = str(text or "")
    pair = _genre_superseded_pair(t)
    if not pair:
        return ""
    rec, old = pair
    # The opening description is the text before the first report heading.
    cut = len(t)
    for mk in ("\n\nLYRICS:", "\n\n11. ERA / RELEASE PERIOD", "\n\nVOCAL / SINGER PROFILE",
               "[Independent signal-processing report"):
        k = t.find(mk)
        if 0 <= k < cut:
            cut = k
    toks = [re.escape(w) for w in _HYPHENS_RE.split(old) if w]
    m = None
    if toks:
        pat = re.compile(r"(?<![\w])" + _HYPHENS_RE.pattern.join(toks) + r"(?![\w])", re.IGNORECASE)
        m = pat.search(t[:cut])
    where = (f"the opening description calls it '{m.group(0)}'" if m
             else f"the listening model's first-pass genre ranking led with '{old}'")
    if GENRE_CHECK_FIRM:
        leads, detail = _guitar_stem_reading(t)
        rock_names = _rock_label_list(old)
        if leads:
            guitar = (
                f"Measured from the stems, {detail}, so a guitar-rock edge may be named as a "
                f"secondary flavour -- but lead with {rec}. Asked whether it is {rock_names}: it is "
                f"{rec} first; with the guitar this prominent a pop-rock edge is a fair secondary "
                "description, not the main label."
            )
        else:
            basis = (f"Measured from the stems, {detail}, so" if detail
                     else "Unless the measured stems show a leading guitar part,")
            guitar = (
                f"{basis} any guitar-like midrange layer (guitar or a guitar-like synth) is one "
                "colour inside the production, not a rock band: do not call the track "
                f"{rock_names}, and do not describe its backing as a rock or pop-rock band. "
                f"Asked whether it is {rock_names}: no -- it is {rec}, with at most a light guitar "
                "colour."
            )
        return (
            f"{_GENRE_CHECK_HEAD} {where}. That was the listening model's first impression; the "
            f"genre check against independent measurements replaced it with '{rec}' (see "
            f"RECOMMENDED GENRE FOR DISCUSSION). Describe the track as {rec} in every answer -- "
            "genre, era (including blind 'when does it sound like it's from?' answers), "
            "instrumentation, drums and comparisons alike. The descriptions' other wording built "
            f"on that first impression (a {_rock_label_list(old, 'or', with_rock=True)} band, power "
            f"chords, punk energy, a {_rock_label_list(old, 'or', with_rock=False)} era wave) "
            "belongs to the same discarded guess: take the "
            "instruments, groove and production from the measured blocks instead (stems, "
            f"instrument tags, beat grid, loudness). {guitar} Never present '{old}' as how this "
            "track or its artist is usually filed, classed or known."
        )
    return (
        f"{_GENRE_CHECK_HEAD} {where}. That was the listening model's first impression; the "
        f"genre check against independent measurements replaced it with '{rec}' (see "
        f"RECOMMENDED GENRE FOR DISCUSSION). Describe the track as {rec}. Mention {old} at most "
        f"as a minor flavour where the notes support it, and never present '{old}' as how this "
        f"track or its artist is usually filed, classed or known."
    )


# dev60: see INSTRUMENT_REED_TAG_CHECK.
_REED_TAGS = (("accordion", "an accordion"), ("harmonium", "a harmonium"), ("bandoneon", "a bandoneon"),
              ("concertina", "a concertina"), ("harmonica", "a harmonica"), ("melodica", "a melodica"))
_REED_PLAUSIBLE_GENRES = re.compile(
    r"\b(?:folk|country|blues|bluegrass|americana|cajun|zydeco|tango|polka|world|celtic|irish|"
    r"scottish|latin|cumbia|norte\w*|tex-?mex|vallenato|musette|chanson|klezmer|forr[oó]|"
    r"tejano|conjunto|sea shanty|shanty|gypsy|balkan|french|italian|ranchera|singer-songwriter|"
    r"roots|skiffle|harmonica)\b", re.IGNORECASE)
_INSTR_CHECK_HEAD = "INSTRUMENT CHECK (read before the instrument tags below):"


def _listening_model_spans(text):
    """dev60: the listening model's own words in the notes -- its opening
    report and its era, vocal and confirmation passes -- not the tagger
    lines or measurements."""
    t = str(text or "")
    # Check lines added on top of the notes (GENRE CHECK, ARRANGEMENT CHECK,
    # ...) are not the listening model's words.
    while re.match(r"[A-Z][A-Z /-]+ CHECK \(", t) or t.startswith("CHECKS (corrections"):
        k = t.find("\n\n")
        if k < 0:
            break
        t = t[k + 2:]
    cut = len(t)
    for mk in ("\n\nLYRICS", "[Independent signal-processing report", "\nRECOMMENDED TEMPO FOR DISCUSSION",
               "\n\nVOCAL DECISION AUDIT"):
        k = t.find(mk)
        if 0 <= k < cut:
            cut = k
    spans = [t[:cut]]
    for head in ("11. ERA / RELEASE PERIOD", "VOCAL / SINGER PROFILE", "VOCAL CONFIRMATION PASS"):
        k = t.find(head)
        if k >= 0:
            e = t.find("\n\n", k + len(head) + 2)
            spans.append(t[k:e if e >= 0 else len(t)])
    return "\n".join(spans)


def _reed_tag_check_note(text):
    """dev60: an INSTRUMENT CHECK line for unconfirmed free-reed tags, or ""."""
    if not INSTRUMENT_REED_TAG_CHECK:
        return ""
    t = str(text or "")
    tag_lines = [ln for ln in t.splitlines()
                 if "instrument tag (" in ln or re.match(r"\s+[a-z][\w /()-]* \((?:\w+) stem\):", ln)]
    if not tag_lines:
        return ""
    tagged = "\n".join(tag_lines).lower()
    own = _listening_model_spans(t).lower()
    genre_txt = " ".join(m.group(1) for m in _RECOMMENDED_GENRE_RE.finditer(t))
    genre_txt += " " + " ".join(extract_genre_ranked_labels(t, max_n=5))
    if _REED_PLAUSIBLE_GENRES.search(genre_txt):
        return ""
    found = []
    for word, art in _REED_TAGS:
        if re.search(r"\b" + word + r"\b", tagged) and not re.search(r"\b" + word, own):
            found.append((word, art))
    if not found:
        return ""
    strong = []
    if INSTRUMENT_REED_STRONG_LEAD:
        for w, a in found:
            info = _strong_reed_reading(t, w) if w == "harmonica" else None
            if info:
                strong.append((w, a, info))
        found = [(w, a) for w, a in found if w not in {x[0] for x in strong}]
    lead_s = ""
    if strong:
        w, _a, (pct, n_on, n_all, stem) = strong[0]
        lead_s = (f"the instrument tagger hears a steady reedy lead{' on the ' + stem + ' stem' if stem else ''}: "
                  f"'{w}' at {pct}% in {n_on} of {n_all} windows -- too strong and too sustained to dismiss, "
                  "although the listening model does not mention it. Treat it as a real lead or riff "
                  "instrument with a reedy tone: a harmonica, or a horn such as a saxophone or trumpet (that "
                  "classifier also calls a saxophone 'harmonica'). Describe it by that sound and role, as a "
                  "harmonica-like or brassy lead, without asserting which; name it exactly only if the user "
                  "confirms it. A lead line the descriptions give to another instrument may be this part.")
        if not found:
            return f"{_INSTR_CHECK_HEAD} {lead_s}"
    stems = sorted(set(re.findall(r"(?m)^\s+(?:" + "|".join(w for w, _a in found)
                                  + r")\b[^\n(]*\((\w+) stem\):", t)))
    where = (f"heard on the {' and '.join(stems)} stem{'s' if len(stems) > 1 else ''}" if stems
             else "from the separated stems")
    names = [f"'{w}'" for w, _a in found]
    names_s = names[0] if len(names) == 1 else ", ".join(names[:-1]) + " and " + names[-1]
    arts = [a for _w, a in found]
    arts_s = arts[0] if len(arts) == 1 else ", ".join(arts[:-1]) + " or " + arts[-1]
    likely = []
    for pat, label in ((r"\bsax(?:ophone)?s?\b", "saxophone"), (r"\bsynth(?:esizer)?s?\b|\bsynth[- ]", "synths"),
                       (r"\b(?:pads?|synth pads?)\b", "pads"), (r"\borgans?\b", "organ"),
                       (r"\bkeyboards?\b|\bkeys\b", "keyboards"), (r"\bstrings?\b", "strings"),
                       (r"\bhorns?\b|\bbrass\b", "horns")):
        if re.search(pat, own):
            likely.append(label)
    likely_s = ""
    if likely:
        likely_s = (" The listening model itself names " + (likely[0] if len(likely) == 1 else
                    ", ".join(likely[:-1]) + " and " + likely[-1]) + " on this track -- the likelier source.")
    describe = "(a reedy synth pad, sustained keyboard chords, a sax or lead line)"
    poly = _other_stem_polyphony(t) if INSTRUMENT_REED_STRONG_LEAD and stems == ["other"] else None
    if poly is not None and poly >= REED_PAD_MIN_POLYPHONY and not re.search(
            r"\bsax(?:ophone)?s?\b|\bhorns?\b|\bbrass\b|\btrumpets?\b|\btrombones?\b", own):
        describe = (f"(most likely a synth pad or sustained keyboard chords: the other stem it was heard on "
                    f"plays chords of about {poly:g} notes at once)")
    body = (
        f"the instrument tagger's {names_s} label{'s' if len(found) > 1 else ''} "
        f"({where}) {'are' if len(found) > 1 else 'is'} not confirmed by anything else: the listening "
        f"model never mentions {arts_s}, and that classifier routinely gives these names to sustained, "
        "reedy synth pads, organ-like synths and reed or horn leads such as saxophone." + likely_s
        + f" Do not say the track has {arts_s}; describe that part by its sound and role {describe}. "
        "Name the instrument only if the user confirms it."
    )
    if lead_s:
        return f"{_INSTR_CHECK_HEAD} {lead_s} Separately, {body}"
    return f"{_INSTR_CHECK_HEAD} {body}"


def _strong_reed_reading(text, word):
    """(percent, windows on, windows in all, stem) for a strong, steady,
    not-weak tagger reading of `word` in the per-stem tag lines, else None."""
    for blk in re.finditer(r"(?m)^\[(\w+) stem\]\n", text):
        e = text.find("\n\n", blk.end())
        seg = text[blk.end():e if e >= 0 else len(text)]
        for ln in seg.splitlines():
            if not ln.lstrip().startswith("instrument tag ("):
                continue
            for m in re.finditer(r"\b" + word + r" \((\d+)%[^)]*\) \[([^\]]*)\]", ln):
                if m.group(2).lstrip().startswith("weak"):
                    continue
                w = re.search(r"(\d+)/(\d+) windows", m.group(2))
                if not w:
                    continue
                pct, n_on, n_all = int(m.group(1)), int(w.group(1)), int(w.group(2))
                if (pct >= REED_STRONG_LEAD_MIN_PCT and n_all
                        and n_on >= REED_STRONG_LEAD_MIN_WINDOW_SHARE * n_all):
                    return pct, n_on, n_all, blk.group(1).lower()
    return None


def _other_stem_polyphony(text):
    t = str(text or "")
    j = t.find("[OTHER stem]")
    if j < 0:
        return None
    k = t.find("\n\n", j)
    m = re.search(r"average simultaneous notes: (\d+(?:\.\d+)?)", t[j:k if k >= 0 else len(t)])
    return float(m.group(1)) if m else None


_SEMI_ACOUSTIC_ITEM = ("possible second guitar (clean, lightly amplified or semi-acoustic in tone; the "
                       "guitar stem reads acoustic throughout and nothing reads a distorted electric guitar)")
_GUITAR_CHECK_HEAD = "GUITAR CHECK (measured from the separated stems; read before the descriptions below):"
_ELECTRIC_GUITAR_RE = re.compile(r"(?i)\belectric[ -]?guitars?\b")
_ELECTRIC_NEGATED_RE = re.compile(r"(?i)\b(?:no|without|absence of|not)\s+(?:\w+\s+){0,2}$")


def _acoustic_only_guitar(text):
    """True when the tagger reads the guitar stem as acoustic guitar in every
    section and no section, stem or whole-mix tag reads an electric guitar."""
    t = str(text or "")
    if not re.search(r"(?m)^\s+acoustic guitar \(guitar stem\): throughout\b", t):
        return False
    if re.search(r"(?m)^\s+electric guitar\b[^\n]*\(\w+ stem\):", t):
        return False
    if re.search(r"(?m)^instrument tag \([^\n]*\belectric guitar \(\d+%", t):
        return False
    i = t.find("WHOLE-MIX INSTRUMENT TAGS")
    if i >= 0:
        e = t.find("\n\n", i)
        if "electric guitar" in t[i:e if e >= 0 else len(t)].split("\n", 1)[-1]:
            return False
    return True


def _asserts_electric_guitar(text):
    s = str(text or "")
    return any(not _ELECTRIC_NEGATED_RE.search(s[max(0, m.start() - 40):m.start()])
               for m in _ELECTRIC_GUITAR_RE.finditer(s))


def _acoustic_guitar_check_note(text):
    """A GUITAR CHECK line when the listening model names an electric guitar
    on a track whose guitar stem reads acoustic throughout, else ""."""
    if not ACOUSTIC_GUITAR_CHECK:
        return ""
    t = str(text or "")
    if not _acoustic_only_guitar(t) or not _asserts_electric_guitar(_listening_model_spans(t)):
        return ""
    return (
        f"{_GUITAR_CHECK_HEAD} the instrument tagger reads the separated guitar stem as acoustic guitar "
        "in every section, and no section, stem or whole-mix tag reads an electric guitar. Any "
        "electric guitar the descriptions mention is at most a clean, lightly amplified or "
        "semi-acoustic-sounding guitar alongside the acoustic one: describe it that way, never as "
        "a distorted, overdriven or rock electric guitar, and keep the acoustic guitar as the main "
        "guitar sound."
    )


_CHD_PC = {"C": 0, "C#": 1, "Db": 1, "D": 2, "D#": 3, "Eb": 3, "E": 4, "F": 5, "F#": 6, "Gb": 6, "G": 7,
           "G#": 8, "Ab": 8, "A": 9, "A#": 10, "Bb": 10, "B": 11, "Cb": 11, "Fb": 4, "E#": 5, "B#": 0}
_CHD_SHARP = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]
_CHD_FLAT = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]
_CHD_MODES = {"major": (0, 2, 4, 5, 7, 9, 11), "ionian": (0, 2, 4, 5, 7, 9, 11), "minor": (0, 2, 3, 5, 7, 8, 10),
              "aeolian": (0, 2, 3, 5, 7, 8, 10), "dorian": (0, 2, 3, 5, 7, 9, 10), "phrygian": (0, 1, 3, 5, 7, 8, 10),
              "lydian": (0, 2, 4, 6, 7, 9, 11), "mixolydian": (0, 2, 4, 5, 7, 9, 10), "locrian": (0, 1, 3, 5, 6, 8, 10)}
_CHD_REL = {"major": 0, "ionian": 0, "minor": 9, "aeolian": 9, "dorian": 2, "phrygian": 4, "lydian": 5,
            "mixolydian": 7, "locrian": 11}
_CHD_TOKEN_RE = re.compile(r"^([A-G])(#|b|\u266f|\u266d)?((?:maj|min|m|dim|aug|sus|add|M)?[0-9]*(?:b5|#5|b9|#9|#11|b13)?"
                           r"(?:sus[24])?(?:add[0-9]+)?)(?:/([A-G](?:#|b|\u266f|\u266d)?))?$")
_CHORDS_MEASURED_MARK = "(measured from the separated instruments"
_CHORDS_NONE_MEASURED = "no clear chords measured"
_CHORDS_HEARD_LABEL = "heard by the listening model:"


def _chd_key(text):
    """(root pc, mode, display, flats?) of RECOMMENDED KEY FOR DISCUSSION, or None."""
    m = re.search(r"RECOMMENDED KEY FOR DISCUSSION: ([A-G](?:#|b|\u266f|\u266d)?)\s+(major|minor|ionian|dorian|phrygian|"
                  r"lydian|mixolydian|aeolian|locrian)\b", str(text or ""), re.I)
    if not m:
        return None
    r = m.group(1).replace("\u266f", "#").replace("\u266d", "b")
    mode = m.group(2).lower()
    if r not in _CHD_PC:
        return None
    if "#" in r:
        flats = False
    elif r.endswith("b"):
        flats = True
    else:
        flats = ((_CHD_PC[r] - _CHD_REL[mode]) % 12) in (5, 10, 3, 8, 1, 6)
    disp = f"{r} {mode}" if mode in ("major", "minor") else f"{r} {mode.capitalize()}"
    return _CHD_PC[r], mode, disp, flats


def _chd_measured(text, key):
    """Measured chords from the guitar / piano / other stems' common harmonic
    clusters: triads, and root-fifth dyads as power chords (X5) on roots with
    no triad; most common first, at least 5 hits and 15% of the top count,
    at most six."""
    t = str(text or "")
    counts = {}
    for stem in ("GUITAR", "PIANO", "OTHER"):
        i = t.find(f"[{stem} stem]")
        if i < 0:
            continue
        j = t.find("\n[", i + 5)
        m = re.search(r"common harmonic clusters: ([^\n]+)", t[i:j if j > 0 else len(t)])
        if not m:
            continue
        for it in m.group(1).split(";"):
            it = it.strip()
            mm = re.match(r"([A-G]#?) (major|minor) x(\d+)", it)
            if mm:
                k = (_CHD_PC[mm.group(1)], "m" if mm.group(2) == "minor" else "")
                counts[k] = counts.get(k, 0) + int(mm.group(3))
                continue
            mm = re.match(r"([A-G]#?)\+([A-G]#?) x(\d+)$", it)
            if mm:
                a, b = _CHD_PC[mm.group(1)], _CHD_PC[mm.group(2)]
                root = a if (b - a) % 12 == 7 else (b if (a - b) % 12 == 7 else None)
                if root is not None:
                    counts[(root, "5")] = counts.get((root, "5"), 0) + int(mm.group(3))
    triad_roots = {r for (r, q) in counts if q in ("", "m")}
    items = sorted(((c, k) for k, c in counts.items() if not (k[1] == "5" and k[0] in triad_roots)),
                   key=lambda x: -x[0])
    if not items:
        return []
    top = items[0][0]
    names = _CHD_FLAT if (key and key[3]) else _CHD_SHARP
    return [names[k[0]] + k[1] for c, k in items if c >= max(5, 0.15 * top)][:6]


def _chd_heard(value):
    """The listening model's chords from its CHORDS answer, each once, in
    order of first appearance (section labels, timestamps and prose dropped)."""
    v = str(value or "").strip()
    if not v or re.match(r"(?i)^(uncertain|none|n/?a|unknown)\b", v):
        return []
    toks = re.split(r"[\s,;:()\[\]\u2192>\-\u2010-\u2015|]+", v)
    prose = sum(1 for x in toks if re.match(r"^[a-z]{3,}$", x)) > 8
    out = []
    for x in toks:
        x = x.strip(".")
        if not _CHD_TOKEN_RE.match(x) or (prose and len(x) == 1):
            continue
        c = x.replace("\u266f", "#").replace("\u266d", "b")
        if c not in out:
            out.append(c)
    return out


def _chd_fits(chord, key):
    """True when the chord belongs to the key (diatonic root and triad quality;
    also bVII major in a major key and V major in a minor key)."""
    if not key:
        return True
    root, mode = key[0], key[1]
    scale = [(root + i) % 12 for i in _CHD_MODES[mode]]
    m = _CHD_TOKEN_RE.match(chord)
    if not m:
        return True
    pc = _CHD_PC.get(m.group(1) + (m.group(2) or "").replace("\u266f", "#").replace("\u266d", "b"))
    if pc is None:
        return True
    q = m.group(3) or ""
    if re.match(r"^(5|sus)", q):
        qual = None
    elif "dim" in q or "m7b5" in q:
        qual = "dim"
    elif re.match(r"^(m(?!aj)|min)", q):
        qual = "m"
    else:
        qual = ""
    if pc in scale:
        if qual is None:
            return True
        d = scale.index(pc)
        third = (scale[(d + 2) % 7] - pc) % 12
        fifth = (scale[(d + 4) % 7] - pc) % 12
        want = "dim" if (third == 3 and fifth == 6) else ("m" if third == 3 else "")
        return qual == want
    if mode in ("major", "ionian") and pc == (root + 10) % 12 and qual in ("", None):
        return True
    if mode in ("minor", "aeolian") and pc == (root + 7) % 12 and qual in ("", None):
        return True
    return False


def _chd_outside_note(chords, key):
    out = [c for c in chords if not _chd_fits(c, key)]
    if not key or not out:
        return ""
    if len(out) * 2 > len(chords):
        return f" (most of these are outside the measured key of {key[2]}; not reliable)"
    return f" ({', '.join(out)} outside the measured key of {key[2]})"


def _chords_line_value(old_value, text):
    """See CHORDS_MEASURED_LINE. The new CHORDS value, or old_value when it
    is already in this format."""
    old = str(old_value or "")
    if _CHORDS_HEARD_LABEL in old:
        return old_value
    key = _chd_key(text)
    meas = _chd_measured(text, key)
    heard = _chd_heard(old)
    ms = ((", ".join(meas) + f" {_CHORDS_MEASURED_MARK}, most common first)" + _chd_outside_note(meas, key))
          if meas else _CHORDS_NONE_MEASURED)
    if heard:
        shown = heard[:8]
        hs = (f"{_CHORDS_HEARD_LABEL} " + ", ".join(shown) + (", …" if len(heard) > 8 else "")
              + _chd_outside_note(shown, key))
    else:
        hs = f"{_CHORDS_HEARD_LABEL} none given"
    return ms + "; " + hs


_INSTR_SPAN_ITEM_RE = re.compile(r"^\s*(?P<name>[^():;\n]+?)\s*\(\s*\d+(?:\.\d+)?\s*s\s*[\u2010-\u2015\-]\s*\d+(?:\.\d+)?\s*s\s*\)"
                                 r"\s*(?::\s*(?P<desc>.*))?$")
_INSTR_JOINED = {"electricguitar": "electric guitar", "acousticguitar": "acoustic guitar",
                 "electricbass": "electric bass", "basguitar": "bass guitar", "bassguitar": "bass guitar"}


def _instrumentation_collapse_spans(value):
    """See INSTRUMENTATION_COLLAPSE_SPANS. A list in which most items carry a
    time span, with each instrument once; anything else unchanged."""
    v = str(value or "")
    if not INSTRUMENTATION_COLLAPSE_SPANS or "\n" in v:
        return value
    items = [x for x in v.split(";") if x.strip()]
    ms = [_INSTR_SPAN_ITEM_RE.match(x) for x in items]
    if sum(1 for m in ms if m) < 2 or sum(1 for m in ms if m) * 2 < len(items):
        return value
    order, desc, extra = [], {}, []
    for x, m in zip(items, ms):
        if m:
            nm = m.group("name").strip()
            k = re.sub(r"\s+", "", nm.lower())
            if k not in desc:
                order.append((k, _INSTR_JOINED.get(k, nm)))
                desc[k] = (m.group("desc") or "").strip()
            elif not desc[k] and m.group("desc"):
                desc[k] = m.group("desc").strip()
        else:
            k0 = re.sub(r"[\s(]+", "", re.split(r"\(", x, 1)[0].lower())
            if k0 and (k0 in desc or (len(k0) >= 3 and any(k.startswith(k0) for k in desc))):
                continue            # a repeat cut off mid-item ("drums (25.", "synthes")
            extra.append(x.strip())
    out = [(f"{nm}: {desc[k]}" if desc[k] else nm) for k, nm in order] + extra
    return "; ".join(out)


def _report_line_repairs(text):
    """CHORDS and INSTRUMENTATION in a saved scan's report, in the current
    format (load time; idempotent)."""
    t = str(text or "")
    try:
        if CHORDS_MEASURED_LINE:
            m = re.search(r"(?m)^(CHORDS=)([^\n]*)$", t)
            if m:
                nv = _chords_line_value(m.group(2), t)
                if nv != m.group(2):
                    t = t[:m.start()] + m.group(1) + nv + t[m.end():]
        if INSTRUMENTATION_COLLAPSE_SPANS:
            m = re.search(r"(?m)^(INSTRUMENTATION=)([^\n]*)$", t)
            if m:
                nv = _instrumentation_collapse_spans(m.group(2))
                if nv != m.group(2):
                    t = t[:m.start()] + m.group(1) + nv + t[m.end():]
    except Exception:
        return str(text or "")
    return t


