_CP_QUALITY = {"maj": "", "min": "m", "7": "7", "maj7": "maj7", "min7": "m7", "dim": "dim", "aug": "aug",
               "sus2": "sus2", "sus4": "sus4", "sus4(b7)": "7sus4", "9": "9", "maj9": "maj9", "min9": "m9",
               "11": "11", "13": "13", "dim7": "dim7", "hdim7": "m7b5", "maj6": "6", "min6": "m6"}
_CP_MINORISH = {"min", "min7", "min9", "dim", "dim7", "hdim7", "min6"}
_CP_BASS_INTERVAL = {"2": 2, "b3": 3, "3": 4, "4": 5, "b5": 6, "5": 7, "#5": 8, "b6": 8, "6": 9, "bb7": 9,
                     "b7": 10, "7": 11, "9": 2}
_CP_ROMAN = {0: "I", 1: "bII", 2: "II", 3: "bIII", 4: "III", 5: "IV", 6: "#IV", 7: "V", 8: "bVI", 9: "VI",
             10: "bVII", 11: "VII"}
_CP_DIATONIC = {"major": {0: "maj", 2: "min", 4: "min", 5: "maj", 7: "maj", 9: "min", 11: "dim"},
                "minor": {0: "min", 2: "dim", 3: "maj", 5: "min", 7: "min", 8: "maj", 10: "maj"}}
_CP_ALSO_IN_KEY = {"minor": {7: "maj", 11: "dim"}}        # the harmonic-minor V and vii
_CP_SHARP = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"]
_CP_FLAT = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]
_CP_FLAT_KEYS = {("major", 5), ("major", 10), ("major", 3), ("major", 8), ("major", 1), ("major", 6),
                 ("minor", 2), ("minor", 7), ("minor", 0), ("minor", 5), ("minor", 10), ("minor", 3)}
_CP_ROOT_PC = {"C": 0, "C#": 1, "Db": 1, "D": 2, "D#": 3, "Eb": 3, "E": 4, "F": 5, "F#": 6, "Gb": 6, "G": 7,
               "G#": 8, "Ab": 8, "A": 9, "A#": 10, "Bb": 10, "B": 11, "Cb": 11, "Fb": 4, "E#": 5, "B#": 0}
_MK_DEGREE = {0: "1", 1: "b2", 2: "2", 3: "b3", 4: "3", 5: "4", 6: "#4", 7: "5", 8: "b6", 9: "6", 10: "b7",
              11: "7"}


def chord_segments_for(audio_path):
    """[[start, end, label]] from lv-chordia ("A:maj", "D:maj/3", "N"), or [] when
    disabled, not installed or failed. CPU only; never raises. A first failure to
    import or load is not retried in this session."""
    if not ENABLE_CHORD_PROGRESSION or not audio_path or str(audio_path).startswith(("http://", "https://")):
        return []
    if _CHORD_REC_STATE["unavailable"]:
        return []
    try:
        with _CHORD_REC_LOCK:
            try:
                import importlib
                _lvc = importlib.import_module("lv_chordia.chord_recognition")   # the module, not the function
            except Exception as e:
                _CHORD_REC_STATE["unavailable"] = str(e) or type(e).__name__
                print("  (chord progressions skipped for this session -- install the chord model once with "
                      f"'pip install lv-chordia': {_CHORD_REC_STATE['unavailable'][:160]})")
                return []
            _lvc.print = lambda *a, **k: None        # its per-model progress lines
            res = _lvc.chord_recognition(os.path.abspath(str(audio_path)), CHORD_PROGRESSION_DICTIONARY)
        out = []
        for x in res or []:
            try:
                s, e, lab = float(x["start_time"]), float(x["end_time"]), str(x["chord"])
            except Exception:
                continue
            if e > s:
                out.append([round(s, 2), round(e, 2), lab])
        return out
    except Exception as e:
        print(f"  (chord progressions skipped: {str(e).strip()[:160] or type(e).__name__})")
        return []


def _chord_remember(track_path, segs):
    if not segs or not track_path:
        return
    _CHORD_RESULTS[str(track_path)] = segs
    _CHORD_RESULTS.move_to_end(str(track_path))
    while len(_CHORD_RESULTS) > 16:
        _CHORD_RESULTS.popitem(last=False)


def _chord_segments_for_save(segs, track_key=None):
    """The saved form ([[start, end, label]]), from `segs` or the remembered result."""
    src = segs if segs else (_CHORD_RESULTS.get(str(track_key)) if track_key else None)
    out = []
    for it in src or []:
        try:
            out.append([round(float(it[0]), 2), round(float(it[1]), 2), str(it[2])])
        except Exception:
            continue
    return out


def _cp_parse(label):
    """(root pc, quality, bass pc or None) from "A:maj/3"; None for no chord."""
    lab = str(label or "").strip()
    if not lab or lab in ("N", "X") or ":" not in lab:
        return None
    root, _, rest = lab.partition(":")
    pc = _CP_ROOT_PC.get(root)
    if pc is None:
        return None
    qual, _, bass = rest.partition("/")
    if qual not in _CP_QUALITY:
        return None
    bpc = None
    if bass:
        iv = _CP_BASS_INTERVAL.get(bass)
        if iv is not None and iv != 0:
            bpc = (pc + iv) % 12
    return (pc, qual, bpc)


def _cp_key(key_text):
    k = _parse_key_root_quality(key_text) if key_text else None
    return k  # (root pc, "major"/"minor") or None


def _cp_name(ch, key):
    names = _CP_FLAT if key and (key[1], key[0]) in _CP_FLAT_KEYS else _CP_SHARP
    pc, qual, bpc = ch
    s = names[pc] + _CP_QUALITY.get(qual, "")
    return s + ("/" + names[bpc] if bpc is not None else "")


def _cp_roman(ch, key):
    pc, qual, _b = ch
    iv = (pc - key[0]) % 12
    r = _CP_ROMAN[iv]
    head = r.lstrip("b#")
    acc = r[: len(r) - len(head)]
    if qual in _CP_MINORISH:
        head = head.lower()
    suf = {"dim": "o", "dim7": "o7", "hdim7": "ø7", "aug": "+", "7": "7",
           "maj7": "maj7", "min7": "7", "9": "9", "maj9": "maj9", "min9": "9", "11": "11", "13": "13",
           "sus2": "sus2", "sus4": "sus4", "sus4(b7)": "7sus4", "maj6": "6", "min6": "6"}.get(qual, "")
    return acc + head + suf


def _cp_in_key(ch, key):
    pc, qual, _b = ch
    iv = (pc - key[0]) % 12
    want = _CP_DIATONIC[key[1]].get(iv) or _CP_ALSO_IN_KEY.get(key[1], {}).get(iv)
    if want is None:
        return False
    if qual.startswith("sus") or qual in ("aug",):
        return True
    fam = "dim" if qual in ("dim", "dim7", "hdim7") else ("min" if qual in _CP_MINORISH else "maj")
    if want == "dim":
        return fam in ("dim", "min")
    return fam == want or (key[1] == "minor" and iv in _CP_ALSO_IN_KEY["minor"])


def _cp_section_seq(segs, a, b, beat):
    """[(chord, duration)] in time order inside [a, b): repeats merged, slivers dropped."""
    pieces = []
    for s, e, ch in segs:
        if e <= a or s >= b:
            continue
        s2, e2 = max(s, a), min(e, b)
        if e2 - s2 >= 0.15:
            pieces.append([ch, e2 - s2])
    short = max(0.35, 0.5 * beat)
    for _ in range(2):
        merged = []
        for ch, d in pieces:
            if merged and merged[-1][0] == ch:
                merged[-1][1] += d
            else:
                merged.append([ch, d])
        pieces = [p for p in merged if p[1] >= short] if len(merged) > 1 else merged
    merged = []
    for ch, d in pieces:
        if merged and merged[-1][0] == ch:
            merged[-1][1] += d
        else:
            merged.append([ch, d])
    return [(ch, d) for ch, d in merged]


def _cp_loop(seq):
    """(pattern, repeats) for the shortest chord cycle covering 80%+ of the
    sequence at least twice, else None."""
    n = len(seq)
    for k in range(1, min(8, n // 2) + 1):
        best = None
        for off in range(k):
            pat = seq[off:off + k]
            if len(pat) < k:
                continue
            hits = sum(1 for i in range(n) if seq[i] == pat[(i - off) % k])
            if best is None or hits > best[0]:
                best = (hits, pat, off)
        if best and best[0] / float(n) >= 0.8 and n / float(k) >= 2:
            pat, off = best[1], best[2]
            if off:          # show the cycle from its first full statement
                pat = seq[off:off + k]
            return pat, int(round(n / float(k)))
    return None


def _cp_rhythm(durs, bar):
    if not durs or not bar:
        return ""
    r = float(np.median(durs)) / bar
    if r < 0.4:
        return "the chords change every beat or two"
    if r < 0.75:
        return "about two chords per bar"
    if r < 1.5:
        return "about one chord per bar"
    if r < 3.0:
        return "about one chord every two bars"
    return "long, held chords"


_CP_TIMES = {2: "twice", 3: "three times", 4: "four times", 5: "five times", 6: "six times", 7: "seven times",
             8: "eight times"}


def build_chord_progression_block(segments, sections, key_text=None, bpm=None):
    """See ENABLE_CHORD_PROGRESSION. "" when there is nothing to say. Never raises."""
    try:
        if not segments or not sections:
            return ""
        key = _cp_key(key_text)
        segs = []
        for it in segments:
            try:
                ch = _cp_parse(it[2])
                if ch:
                    segs.append((float(it[0]), float(it[1]), ch))
            except Exception:
                continue
        if len(segs) < 2:
            return ""
        beat = 60.0 / float(bpm) if bpm and float(bpm) > 0 else 0.5
        bar = 4 * beat
        lines, loops = [], []
        for sec in sections:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            name = str(sec.get("name") or "").strip() or "Section"
            if b - a < 3.0 or name.lower().startswith("silence"):
                continue
            seq = _cp_section_seq(segs, a, b, beat)
            if not seq:
                lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): no clear chords")
                continue
            chords = [c for c, _d in seq]
            durs = [d for _c, d in seq]
            lp = _cp_loop(chords)
            shown = lp[0] if lp else chords[:8]
            names = " - ".join(_cp_name(c, key) for c in shown)
            if lp and len(lp[0]) == 1:
                desc = f"stays on {names}"
            elif lp:
                desc = f"{names}, {_CP_TIMES.get(lp[1], str(lp[1]) + ' times')}"
            else:
                desc = names + (" ..." if len(chords) > 8 else "")
            if key:
                desc += " (" + " - ".join(_cp_roman(c, key) for c in shown) + (" ..." if not lp and len(chords) > 8
                                                                              else "") + ")"
            parts = [desc]
            rh = _cp_rhythm(durs, bar)
            if rh and len(chords) > 1:
                parts.append(rh)
            if key:
                out = []
                for c in dict.fromkeys(chords):
                    if not _cp_in_key(c, key):
                        out.append(f"{_cp_name(c, key)} ({_cp_roman(c, key)})")
                if out:
                    tot = sum(durs)
                    od = sum(d for c, d in seq if not _cp_in_key(c, key))
                    if tot and od / tot >= 0.6:
                        parts.append("most chords here lie outside the key (a key change or a modal passage)")
                    else:
                        parts.append("outside the key: " + ", ".join(out[:4]))
            if lp and len(lp[0]) > 1:
                loops.append(tuple(lp[0]))
            lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): " + "; ".join(parts))
        if not lines:
            return ""
        head = (f"{_CP_HEAD} (measured with a chord-recognition model on the full mix, in TIME ORDER -- unlike the "
                "ranked chord lists elsewhere, this IS the progression; repeats of one cycle are folded into "
                "'..., N times'" + (f"; Roman numerals are against the recommended key, {key_text}" if key else "")
                + "; chord names can be off on dense or distorted mixes, so treat extensions such as 7ths and "
                "sus chords as likely rather than certain):")
        summary = ""
        if loops:
            canon = {}
            for lp in loops:
                rots = [lp[i:] + lp[:i] for i in range(len(lp))]
                c = min(rots, key=lambda r: [x[0] for x in r])
                canon.setdefault(c, []).append(lp)
            best = max(canon.items(), key=lambda kv: len(kv[1]))
            if len(best[1]) >= 2:
                lp = max(set(best[1]), key=best[1].count)
                summary = ("\n  Most common cycle: " + " - ".join(_cp_name(c, key) for c in lp)
                           + (" (" + " - ".join(_cp_roman(c, key) for c in lp) + ")" if key else "")
                           + f", in {len(best[1])} sections")
        return head + summary + "\n" + "\n".join(lines)
    except Exception:
        return ""


def _mk_phrases(lead):
    """Phrases (lists of (onset, midi)) from (onset, dur, midi) notes: very short notes
    dropped, a gap of 0.45 s or more starts a new phrase."""
    notes = sorted((on, d, m) for on, d, m in lead if d >= 0.08)
    out, cur, last_end = [], [], None
    for on, d, m in notes:
        if cur and last_end is not None and on - last_end >= 0.45:
            out.append(cur)
            cur = []
        cur.append((on, int(round(m))))
        last_end = on + d
    if cur:
        out.append(cur)
    return out


def _mk_degrees(phrase, tonic):
    seq = []
    for _on, m in phrase:
        dg = _MK_DEGREE[(m - tonic) % 12]
        if not seq or seq[-1] != dg:
            seq.append(dg)
    return seq


_MK_SCALE = {"major": {0, 2, 4, 5, 7, 9, 11}, "minor": {0, 2, 3, 5, 7, 8, 10}}
_MK_END_WORDS = {"1": "1 (the tonic: settled, finished-sounding)", "5": "5 (the fifth: open, unresolved)",
                 "3": "3 (the third: warm but not final)", "b3": "b3 (the minor third: unsettled)"}


def _build_melody_in_key_by_section(sections, stem_notes, key=None, instrumental=False, context_text=""):
    """See MELODY_IN_KEY_BY_SECTION. "" when there is nothing to say. Never raises.
    Only statements that survive transcription slips are made: the degrees the
    held notes centre on, where phrases come to rest and the highest note."""
    if not MELODY_IN_KEY_BY_SECTION or not sections or not stem_notes or not key:
        return ""
    try:
        kq = _parse_key_root_quality(key)
        if not kq:
            return ""
        tonic = kq[0]
        scale = _MK_SCALE[kq[1]]
        pitched = {s_: _hm_pitched(stem_notes.get(s_)) for s_ in ("vocals", "bass") + _HM_ACC_STEMS}
        vocal_absent = _hm_vocal_absent(context_text)
        lines = []
        for sec in sections:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            name = str(sec.get("name") or "").strip() or "Section"
            if b - a < 3.0 or name.lower().startswith("silence"):
                continue
            lead_stem, lead = _hm_lead(pitched, a, b, instrumental, vocal_absent)
            if not lead:
                continue
            # Short notes, and short notes outside the key above all, are mostly transcription slips
            # (on the scanned library 69% of notes under 0.15 s fit the key, 90% of held ones).
            clean = [x for x in lead if x[1] >= 0.15 and (x[1] >= 0.25 or (int(round(x[2])) - tonic) % 12 in scale)]
            held = [x for x in clean if x[1] >= 0.25]
            if len(held) < 6:
                continue
            parts = ["the voice" if lead_stem == "vocals" else f"the {lead_stem} stem"]
            w = {}
            for on, d, m in held:
                dg = _MK_DEGREE[(int(round(m)) - tonic) % 12]
                w[dg] = w.get(dg, 0.0) + d
            tot = sum(w.values())
            fit = sum(d for _on, d, m in held if (int(round(m)) - tonic) % 12 in scale) / tot if tot else 0.0
            if fit < MELODY_IN_KEY_MIN_FIT:
                lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): {parts[0]}; its held notes "
                             "do not sit clearly in the key here (a passing modulation, or an unreliable "
                             "transcription) -- describe this part by its contour only")
                continue
            top = [dg for dg, v in sorted(w.items(), key=lambda kv: -kv[1])[:3] if v / tot >= 0.15][:2]
            if top:
                parts.append("its held notes centre on " + " and ".join(top))
            ends = []
            for p in _mk_phrases(clean):
                if len(p) >= 3:
                    ends.append(_MK_DEGREE[(p[-1][1] - tonic) % 12])
            if len(ends) >= 3:
                tdg, cnt = max(((e, ends.count(e)) for e in set(ends)), key=lambda x: (x[1], x[0] == "1"))
                if cnt / float(len(ends)) >= 0.4:
                    parts.append("phrases mostly end on " + _MK_END_WORDS.get(tdg, tdg))
                elif ends.count("1") / float(len(ends)) < 0.15:
                    parts.append("phrases rarely come to rest on the key note")
            hi = max(held, key=lambda x: x[2])
            parts.append(f"peaks on {_MK_DEGREE[(int(round(hi[2])) - tonic) % 12]} ({_hm_name(hi[2])})")
            lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): " + "; ".join(parts))
        if not lines or sum(1 for ln in lines if "do not sit clearly" not in ln) < max(1, len(lines) // 2):
            return ""          # most parts do not fit the key: the key or the transcription is in doubt
        root_name = (_CP_FLAT if (kq[1], kq[0]) in _CP_FLAT_KEYS else _CP_SHARP)[tonic]
        head = (f"{_MK_HEAD} (the lead line against the key, {key}: 1 = {root_name}; degrees are numbered against "
                "the major scale, so b3, b6 and b7 are the minor-key notes; from the longer, held notes of this "
                "recording's transcription -- short notes, often transcription slips, are left out -- so these are "
                "the line's resting points and peaks, not a note-by-note score):")
        return head + "\n" + "\n".join(lines)
    except Exception:
        return ""


# dev45 MELODICISM_MEASURED: how melodic the lead line is, from two measured
# things that separate sung from rhythm-led delivery on the scanned library:
# the word rate of the timed lyric lines and the share of long, held notes in
# the vocal transcription (library means/spreads below, from 185 scans).
_ML_HEAD = "MELODICISM BY SECTION (measured)"
_ML_WPS_MEAN, _ML_WPS_SD = 2.046, 0.699
_ML_HELD_MEAN, _ML_HELD_SD = 0.1585, 0.0616


def _ml_chunk_times(c):
    try:
        if isinstance(c, dict):
            if "timestamp" in c and c["timestamp"]:
                a, b = c["timestamp"][0], c["timestamp"][1]
            else:
                a, b = c.get("start"), c.get("end")
            return float(a), float(b), str(c.get("text") or "")
    except Exception:
        return None
    return None


def _ml_wps(chunks, a=None, b=None):
    """(words per second, seconds of timed lyrics) for lines whose middle is in [a, b)."""
    words = secs = 0.0
    for c in chunks or []:
        t = _ml_chunk_times(c)
        if not t:
            continue
        s, e, txt = t
        if e <= s or e - s > 12:
            continue
        mid = (s + e) / 2.0
        if a is not None and not (a <= mid < b):
            continue
        words += len(re.findall(r"[^\W\d_]+(?:'[^\W\d_]+)?", txt))
        secs += e - s
    return (words / secs if secs else None), secs


def _ml_range_words(st):
    if st <= 4:
        return "a narrow range (a few neighbouring notes)"
    if st <= 7:
        return "a moderate range (about a fourth to a fifth)"
    if st <= 11:
        return "a wide range (most of an octave)"
    return "a very wide range (an octave or more)"


def _ml_held_words(h):
    if h < 0.10:
        return "few held notes (short, clipped syllables)"
    if h <= 0.20:
        return "some held notes"
    return "many long, held notes"


def _ml_rate_words(w):
    if w >= 2.8:
        return "a fast, rap-like word rate"
    if w >= 2.2:
        return "a brisk word rate"
    if w >= 1.6:
        return "a moderate word rate"
    return "an unhurried word rate"


def _ml_band(score):
    if score <= -1.5:
        return "mostly rhythm-led: a fast, rapped, chanted or spoken delivery with few held notes"
    if score <= -0.5:
        return "partly melodic: a brisk, wordy delivery with some sung, held lines"
    if score <= 0.8:
        return "melodic: a sung line at a moderate pace"
    return "strongly melodic: unhurried singing with many long, held notes"


def _ml_stats(notes):
    v = [x for x in notes if x[1] >= 0.08]
    if len(v) < 12:
        return None
    r = np.round([x[2] for x in v]).astype(int)
    d = np.array([x[1] for x in v])
    return {"range": float(np.percentile(r, 90) - np.percentile(r, 10)), "held": float(np.mean(d >= 0.4)),
            "notes": len(v)}


def _build_melodicism_block(sections, stem_notes, lyric_chunks=None, instrumental=False, context_text=""):
    """See MELODICISM_MEASURED. "" when there is nothing to say. Never raises."""
    if not MELODICISM_MEASURED or not stem_notes or instrumental:
        return ""
    try:
        voc = _hm_pitched(stem_notes.get("vocals"))
        whole = _ml_stats(voc)
        if not whole or whole["notes"] < 40:
            return ""
        wps, wsecs = _ml_wps(lyric_chunks)
        if wps is not None and wsecs < 20:
            wps = None
        parts = [_ml_range_words(whole["range"]), _ml_held_words(whole["held"])]
        if wps is not None:
            parts.append(_ml_rate_words(wps))
            score = -(wps - _ML_WPS_MEAN) / _ML_WPS_SD + (whole["held"] - _ML_HELD_MEAN) / _ML_HELD_SD
            overall = f"Overall: {_ml_band(score)} -- " + ", ".join(parts) + "."
        else:
            overall = ("Overall: " + ", ".join(parts) + " (no timed lyrics, so the word rate -- the clearest sign of "
                       "sung versus rapped delivery -- is unknown; do not judge how melodic it is from this alone).")
        lines, ranked = [], []
        vocal_absent = _hm_vocal_absent(context_text)
        for sec in sections or []:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            name = str(sec.get("name") or "").strip() or "Section"
            if b - a < 6.0 or name.lower().startswith("silence"):
                continue
            if f"{_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}" in vocal_absent:
                continue
            st = _ml_stats([x for x in voc if a <= x[0] < b])
            if not st:
                continue
            sp = [_ml_range_words(st["range"]).split(" (")[0], _ml_held_words(st["held"]).split(" (")[0]]
            sw, ss = _ml_wps(lyric_chunks, a, b)
            if sw is not None and ss >= 4:
                sp.append(_ml_rate_words(sw))
                sc = -(sw - _ML_WPS_MEAN) / _ML_WPS_SD + (st["held"] - _ML_HELD_MEAN) / _ML_HELD_SD
                ranked.append((sc, name))
                sp.insert(0, _ml_band(sc).split(":")[0])
            lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): " + ", ".join(sp))
        contrast = ""
        if len(ranked) >= 2:
            hi, lo = max(ranked), min(ranked)
            if hi[0] - lo[0] >= 1.0:
                contrast = (f"\n  Most melodic part: {hi[1]}; most rhythm-led part: {lo[1]}.")
        head = (f"{_ML_HEAD} (from the lead vocal's transcribed notes -- their range and how many are long, held "
                "notes -- and the word rate of the timed lyric lines; together these separated sung from rapped or "
                "chanted songs on the scanned library: 9 of 11 rap tracks fall in the rhythm-led band and none of "
                "9 ballads do. Judged on the voice only; a song can still be melodic in its instruments):")
        return head + "\n  " + overall + contrast + ("\n" + "\n".join(lines) if lines else "")
    except Exception:
        return ""


def _saved_analysis_with_instrument_check(analysis):
    """dev60: the analysis with its INSTRUMENT CHECK line at the top, as the
    writer is shown it, or unchanged when there is none."""
    t = str(analysis or "")
    if not INSTRUMENT_REED_TAG_CHECK or not t or _INSTR_CHECK_HEAD in t:
        return analysis
    try:
        note = _reed_tag_check_note(t)
        out = (note + "\n\n" + t) if note else t
        gc = _acoustic_guitar_check_note(t) if _GUITAR_CHECK_HEAD not in t else ""
        if gc:
            out = gc + "\n\n" + out
        return out if (note or gc) else analysis
    except Exception:
        return analysis


_CHECKS_BLOCK_HEAD = "CHECKS (corrections to read before the report below):"
_CHECK_PARA_RE = re.compile(r"[A-Z][A-Z /-]+ CHECK \(")


_MOSS_FIRST_PASS_BY_TRACK = {}


def _remember_moss_first_pass(track, first_pass):
    """dev64: keep the listening model's first pass for the save-time layout
    (REPORT_FIXED_LAYOUT). Never raises."""
    try:
        if track is not None and first_pass:
            _MOSS_FIRST_PASS_BY_TRACK[str(track)] = str(first_pass)
    except Exception:
        pass


def _structure_field_text(sections):
    parts = [f"  {s_['name']} | {_seconds_to_mmss(s_['start'])}-{_seconds_to_mmss(s_['end'])}"
             for s_ in sections]
    return "STRUCTURE=[\n" + "\n".join(parts) + "\n]"


# dev66: fill the report fields the listening model left out (see REPORT_FILL_FROM_EVIDENCE).
_FILL_TOPICS = (
    # field, words (a sentence's score is how many of these it contains)
    ("LYRIC_SUBJECT", r"lyric|lyrics|lyrical|lyrically|theme|themes|thematic|subject|storytelling|narrat|chorus chants|hook “|refrain"),
    ("LEAD_VOCAL_CHARACTERISTICS", r"vocal|vocals|vocalist|singer|voice|tenor|baritone|alto|soprano|falsetto|sung|singing|croon|rasp"),
    ("DRUMS", r"drum|drums|kick|snare|hi-hat|hi‑hat|hihat|hats|cymbal|percussion|backbeat|4/4|groove|fills"),
    ("CHORDS", r"chord|chords|progression|harmonic|harmony|voicings|cadence"),
    ("INSTRUMENTATION", r"guitar|guitars|bass|synth|synths|synthesizer|keyboard|keyboards|piano|organ|saxophone|sax|horn|horns|brass|strings|violin|cello|pad|pads|instrument|instrumentation|arrangement|accordion|harmonica|trumpet|flute"),
    ("TIMBRE", r"production|produced|mix|mixed|stereo|reverb|delay|compression|compressed|eq|polished|fidelity|sheen|texture|textures|timbre|tone|tones|bright|warm|crisp|gritty|lo-fi|clean"),
    ("MELODICISM", r"melody|melodies|melodic|hook|hooks|catchy|riff|riffs|motif"),
    ("MELODIC_CONTOUR", r"contour|rises|rising|falls|falling|ascend|ascending|descend|descending|arch|arching|stepwise|leaps"),
    ("MOOD_VIBE", r"mood|atmosphere|vibe|feel|feeling|exudes|energy|energetic|melanchol|upbeat|wistful|emotional|uplifting|dark|brooding|joyful|rebellious|introspective|reflective|bittersweet|sorrow|sorrowful|sad|sadness|longing|nostalgi|hopeful|tense|tension-filled|playful|dreamy|calm|somber|sombre|yearning|defiant|euphoric|aggressive|mournful|tender"),
    # a sentence about the song's sections is not used (STRUCTURE is the measured map)
    ("_SECTIONS", r"intro|verse|verses|chorus|choruses|pre-chorus|pre\u2011chorus|bridge|outro|structur|section|sections|solo|breakdown|fade-out|fade\u2011out"),
)
_FILL_HEADINGS = (
    ("_SECTIONS", r"structure|section|\bform\b"),
    ("LYRIC_SUBJECT", r"lyric"), ("LEAD_VOCAL_CHARACTERISTICS", r"vocal"), ("DRUMS", r"drum|rhythm section"),
    ("INSTRUMENTATION", r"instrument|arrangement"), ("TIMBRE", r"production|sound"), ("MOOD_VIBE", r"mood|aesthetic|vibe"),
    ("MELODICISM", r"melod"), ("CHORDS", r"harmon|chord"),
    ("_SECTIONS", r"intro|verse|chorus|bridge|outro|solo|structure|section|build"),
)
# Sentences that date the track, name a genre, or give a key or tempo are left
# out: those have their own measured blocks and checks.
_FILL_SKIP_RE = re.compile(
    r"\b(?:1[89]|20)\d0['’]?s\b|\b[2-9]0['’]?s\b|\bmodern\b|\bcontemporary\b|\bvintage\b|\bretro\b|"
    r"\bera\b|\bdecade|\bgenre|\bsub-?genre|\bBPM\b|\btempo\b|\b[A-G][#♯♭b]?\s+(?:major|minor)\b|"
    r"\bduration of the piece\b|\bSTRUCTURE=|\b\d{1,2}:\d{2}\b|"
    r"^(?:The|This) (?:track|song|piece|recording|tune|number) is an? ", re.I)
# "Indie Pop / Synth-Pop", "Classic Rock / Hard Rock": genre labels (case matters here,
# so "baritone/tenor" is not one)
_FILL_GENRE_PAIR_RE = re.compile(r"\b[A-Z][\w\u2011-]+ ?/ ?[A-Z][\w\u2011-]+")
# ... and statements of absence ("No synths ... are evident"): not a description.
_FILL_NEGATIVE_RE = re.compile(
    r"^\s*(?:No|Not|Nor|Without|There (?:is|are) no)\b|\bno (?:additional|other|obvious|audible)\b|"
    r"\b(?:is|are) (?:not|absent)\b|\bnot (?:evident|present|audible)\b", re.I)


_FILL_TRAIL_SPLIT_RE = re.compile(
    r",\s+(?=(?:channeling|channelling|while|blending|recalling|evoking|reminiscent|typical|"
    r"situating|placing|harking|harkening|in the (?:style|vein|tradition))\b)", re.I)


def _fill_clean(sent):
    """The sentence, or its opening clause when only a trailing clause dates
    the track or names a genre ("... an uplifting atmosphere, channeling the
    spirit of 1970s classic rock"); None when it cannot be used."""
    if _FILL_NEGATIVE_RE.search(sent) or _FILL_GENRE_PAIR_RE.search(sent):
        return None
    if not _FILL_SKIP_RE.search(sent):
        return sent
    lead = _FILL_TRAIL_SPLIT_RE.split(sent, maxsplit=1)[0].strip()
    if lead != sent and len(lead) >= 25 and not _FILL_SKIP_RE.search(lead):
        return lead.rstrip(",;:") + "."
    return None


def _fill_clause(sent, pat):
    """The part of a long sentence that is about one field (its list item
    with the most of the field's words), or None."""
    pieces = []
    for p in re.split(r"(?:,\s+(?:and\s+|while\s+)?|:\s+)(?=(?:a|an|the)\b)", sent):
        pieces += re.split(r"\s+(?:that\s+\w+\s+(?:in\s+)?with|alongside|against)\s+(?=(?:a|an|the)\b)", p)
    if len(pieces) < 2:
        return None
    best, best_sc = None, 0
    for p in pieces:
        sc = len(re.findall(r"\b(?:" + pat + r")", p.lower()))
        if sc > best_sc:
            best, best_sc = p.strip(), sc
    if best is None or best_sc < 1:
        return None
    best = best[:1].upper() + best[1:]
    return best if best.endswith((".", "!", "?")) else best.rstrip(",;:") + "."


def _fill_identity(text):
    """(gender, age) of the saved SINGER_IDENTITY decision, or (None, None)."""
    m = re.findall(r"(?m)^SINGER_IDENTITY=(\S+)", str(text or ""))
    if not m:
        return None, None
    c = m[-1].lower()
    if "mixed" in c or "uncertain" in c or "unknown" in c:
        return None, None
    g = "female" if "female" in c else ("male" if "male" in c else None)
    a = ("young" if re.search(r"adolescent|pre_?puberty|child|boy|girl", c)
         else ("adult" if re.search(r"post_?puberty|adult", c) else None))
    return g, a


def _fill_identity_conflict(sent, ident):
    """True when a sentence about the voice contradicts the saved singer
    decision (a "female" voice for a male singer, "adult" for an unbroken
    voice ...): the decision wins, so such a sentence is not copied up."""
    g, a = ident or (None, None)
    low = sent.lower()
    fem = re.search(r"\b(?:female|woman|women|girl|girls|she|her|hers|herself)\b", low)
    mal = re.search(r"\b(?:male|man|men|boy|boys|he|him|his|himself)\b", low)
    if g == "male" and fem or g == "female" and mal:
        return True
    if a == "young" and re.search(r"\b(?:adult|man|woman|men|women|mature)\b", low):
        return True
    if a == "adult" and re.search(r"\b(?:child|children|kid|boy|girl|prepubescent|pre-pubescent|prepubertal)\b", low):
        return True
    return False


def _fill_sentences(prose):
    """(heading-topic, sentence) units from the listening model's prose. A
    heading ("Instrumentation & production:", "Vocal Characteristics -- ...",
    "- Drums: ...") gives its topic to the sentences under / after it."""
    out = []
    topic = None
    for raw in str(prose or "").split("\n"):
        ln = raw.strip()
        if not ln:
            continue
        ln = re.sub(r"\s*\[(?:measured|the listening model)[^\]]*\]", "", ln)
        if re.match(r"^[-\u2022* ]*[A-Za-z][A-Za-z_ ]{1,30}=", ln):
            continue  # a FIELD=value line (CONFIDENCE=, EVIDENCE=, Genre_Related= ...)
        bullet = ln[:1] in "-\u2022*"
        body = ln.lstrip("-\u2022* ").strip()
        unit_topic = topic
        hm = re.match(r"^([A-Z][A-Za-z &/,\u2011-]{2,40}?)\s*(?::|\u2013|\u2014| - )\s*(.*)$", body)
        if hm and len(hm.group(1).split()) <= 5:
            t = None
            for f, pat in _FILL_HEADINGS:
                if re.search(pat, hm.group(1).lower()):
                    t = f
                    break
            if bullet:
                unit_topic = t or topic
                if t is not None or not hm.group(2).strip():
                    body = hm.group(2).strip()
            else:
                topic = unit_topic = t
                body = hm.group(2).strip()
            if not body:
                continue
        for sent in re.split(r"(?<=[.!?])\s+(?=[A-Z\u201c\"])", body):
            sent = sent.strip()
            if len(sent) >= 12 and not sent.endswith(":"):
                out.append((unit_topic, sent[:1].upper() + sent[1:], sent))
    return out


def _fill_from_prose(prose, wanted, ident=None, moved=None, already=""):
    """{field: text} for the wanted fields, from the listening model's own
    sentences: each sentence goes to the field whose words it uses most (its
    heading counts double), at most three sentences / ~420 characters each,
    and no sentence is used twice (dev67). A field still empty may then take
    an unused sentence, or the part of a used one that is about it ("a
    powerful drum kit featuring punchy kick, snappy snare ..." inside the
    instrumentation sentence). `moved`, when given, collects the original
    text of every sentence copied up whole."""
    units = []
    for topic, s, raw in _fill_sentences(prose):
        c = _fill_clean(s)
        if not c:
            continue
        whole = c == s
        s = c
        low = s.lower()
        best, best_score, scores = None, 0, []
        for f, pat in _FILL_TOPICS:
            sc = len(re.findall(r"\b(?:" + pat + r")", low))
            if topic == f:
                sc += 2
            scores.append(sc)
            if sc > best_score:
                best, best_score = f, sc
        if best_score == 1 and scores.count(1) > 1:
            best = None  # one word for each of several fields: not clearly about any
        if scores[-1] >= 3 or scores[-1] >= 2 and scores[-1] >= max(scores[:-1]):
            best = "_SECTIONS"  # walks through the song's sections: not used
        if ident and (best == "LEAD_VOCAL_CHARACTERISTICS" or best is None or
                      re.search(r"\b(?:" + dict(_FILL_TOPICS)["LEAD_VOCAL_CHARACTERISTICS"] + r")", low)) \
                and _fill_identity_conflict(s, ident):
            continue
        if any(u[0] == s for u in units):
            continue  # the same sentence again (report prose and era pass)
        if already and s in already:
            continue  # already in one of the report's fields
        if s[:1] in "\u201c\"" and best != "LYRIC_SUBJECT":
            continue  # a quoted lyric line describes the lyrics, nothing else
        units.append((s, best, raw if whole else None))
    got, used = {}, set()
    for s, best, raw in units:
        if best is None or best not in wanted:
            continue
        cur = got.setdefault(best, [])
        words = set(re.findall(r"[a-z]{4,}", s.lower()))
        if any(len(words & set(re.findall(r"[a-z]{4,}", x.lower()))) > 0.6 * max(1, len(words)) for x in cur):
            continue  # says the same as a sentence already there
        if len(cur) < 3 and sum(len(x) for x in cur) + len(s) <= 420 or not cur:
            cur.append(s)
            used.add(s)
            if moved is not None and raw:
                moved.add(raw)
    for f, pat in _FILL_TOPICS:
        if f not in wanted or got.get(f):
            continue
        for s, best, raw in units:
            n_words = len(re.findall(r"\b(?:" + pat + r")", s.lower()))
            # a sentence no field kept needs one of this field's words; one
            # already used elsewhere lends only its part about this field
            if best == "_SECTIONS" or n_words < (1 if s not in used else 2):
                continue
            if s[:1] in "\u201c\"" and f != "LYRIC_SUBJECT":
                continue
            if s in used or len(s) > 200:
                c = _fill_clause(s, pat)
                if not c or c in used:
                    continue
            else:
                c = s
            got[f] = [c]
            used.add(c)
            if moved is not None and raw and c == s:
                moved.add(raw)
            break
    return {f: " ".join(v) for f, v in got.items() if v and not f.startswith("_")}


def _fill_era_prose(text):
    m = re.search(r"(?ms)^11\. ERA / RELEASE PERIOD \([^\n]*\):\n(.*?)(?=\n\n(?:VOCAL / SINGER PROFILE|[A-Z][A-Z /&-]{6,}[:(])|\Z)", text)
    return m.group(1) if m else ""


def _note_reading_range(text):
    """'lead vocal A3-G4 (median D4)' from a VOCAL NOTE PITCH line (the vocal
    stem's transcribed notes), or None."""
    m = re.search(r"VOCAL NOTE PITCH[^\n]*?median \d+ Hz \(([A-G][#♯♭b]?\d)\); 10-90%: [0-9]+-[0-9]+ Hz "
                  r"\(([A-G][#♯♭b]?\d) to ([A-G][#♯♭b]?\d)\)", str(text or ""))
    if not m or m.group(2) == m.group(3):
        return None
    return f"lead vocal {m.group(2)}-{m.group(3)} (median {m.group(1)})"


def _fill_measured(text):
    """{field: value} measured elsewhere in the saved analysis."""
    got = {}
    m = re.search(r"RECOMMENDED KEY FOR DISCUSSION:\s*([^\n]+?)\.\s+Reasoning", text)
    if m and not re.search(r"uncertain|unknown|ambiguous", m.group(1), re.I):
        got["KEY"] = m.group(1).strip()
    m = re.search(r"RECOMMENDED TEMPO FOR DISCUSSION:\s*(?:about\s+|~)?(\d+(?:\.\d+)?)\s*BPM\.", text)
    if m:
        got["TEMPO_BPM"] = m.group(1)
    vp = re.findall(r"(?m)^VOCALS_PRESENT=(yes|no)\b[^\n]*#\s*from\b", text)
    if not vp:
        vp = re.findall(r"(?m)^VOCAL PRESENCE:\s*(yes|no)\b", text)
    if not vp and VOCAL_ARBITRATION_MARKER not in text:
        # The dedicated vocal pass's own answer (MOSS-Music writes it as a
        # field), when no arbitration overruled it.
        m = re.search(r"(?m)^VOCAL / SINGER PROFILE \(isolated dedicated pass\):\n"
                      r"(?:[^\n]*\n){0,3}?VOCALS_PRESENT=(yes|no)\b", text)
        if m:
            vp = [m.group(1)]
    if vp:
        got["VOCALS_PRESENT"] = vp[-1]
    if got.get("VOCALS_PRESENT") != "no" and not re.search(r"(?m)^VOCALS_PRESENT=no\b", text):
        m = re.search(r"(?ms)^LYRICS HEARD IN AUDIO[^\n]*:\n(.*?)(?:\n\n|\Z)", text)
        words = re.findall(r"[A-Za-z']+", re.sub(r"\[[^\]]*\]", " ", m.group(1))) if m else []
        if len(words) >= 20 or re.search(r"(?m)^LYRICS: reliable lyrics are present", text):
            got["LYRICS_PRESENT"] = "yes"
        m = re.search(r"VOCAL PITCH REPORT[^\n]*\n(?:[^\n]*\n){0,12}?\s*- practical range in notes:\s*([A-G][#♯♭b]?\d\s+to\s+[A-G][#♯♭b]?\d)", text)
        _nr = _note_reading_range(text) if re.search(r"pyin pitch reading confidence: LOW", text) else None
        if _nr:
            # The pyin reading is marked LOW confidence and the notes say to
            # prefer the note reading: take the range from that.
            got["MELODIC_RANGE"] = _nr
            m = None
        if m and len(set(m.group(1).split(" to "))) == 2:
            med = re.search(r"VOCAL PITCH REPORT[^\n]*\n(?:[^\n]*\n){0,4}?\s*- approximate median note:\s*([A-G][#♯♭b]?\d)", text)
            got["MELODIC_RANGE"] = ("lead vocal " + m.group(1).replace(" to ", "-")
                                    + (f" (median {med.group(1)})" if med else ""))
        m = re.search(r"(?ms)^MELODY PER SECTION \(vocals stem\)[^\n]*\n(.*?)(?:\n\n|\n(?=[A-Z][A-Z /]{3,}[(:])|\Z)", text)
        if m:
            groups = {}
            for sec, contour in re.findall(r"(?m)^\s*([^\n(]+?) \([0-9:]+-[0-9:]+\): melody[^\n]*?; contour: ([^;\n]+)", m.group(1)):
                groups.setdefault(contour.strip(), []).append(sec.strip())
            if groups:
                got["MELODIC_CONTOUR"] = "vocal stem, per section: " + "; ".join(
                    f"{c} ({', '.join(v)})" for c, v in groups.items())
    return got


_LVC_NO_VOICE_RE = re.compile(
    r"(?i)^\s*(?:none|no\b|n/?a\b|not applicable|no (?:lead )?vocals?|instrumental)")


def _drop_no_vocal_sentences(text):
    """`text` without its sentences that say the recording has no voice
    (_INSTRUMENTAL_PROSE_RE: "absence of vocals", "there are no vocals",
    "an instrumental track" ...)."""
    t = str(text or "")
    if not _INSTRUMENTAL_PROSE_RE.search(t):
        return t
    parts = re.split(r"(?<=[.!?])\s+", t)
    return " ".join(x for x in parts if not _INSTRUMENTAL_PROSE_RE.search(x)).strip()


def _report_unsettled_vocal_fields(head, fields, tail):
    """(head, fields) with the report's VOCALS_PRESENT set to "uncertain" when
    it is neither yes nor no ("uncertain (vocal texture present but lyrics
    unclear)", "high (lead and backing vocals present throughout)", "mostly
    yes") and the vocal measurements elsewhere in the notes settle it, so the
    fill below writes the settled answer. When the voice is settled as
    present, a LEAD_VOCAL_CHARACTERISTICS of "none (no lead vocal)" is set to
    "uncertain" the same way, to be filled from the model's own description
    or left uncertain -- never left saying there is no voice."""
    try:
        # A run of fields with one answer pasted into each (_moss_copied_fields)
        # is not an answer for any of them.
        _items = [(k, v_) for k, v_ in fields.items() if k not in ("REPORT_NOTE",)]
        _copied = _moss_copied_fields(_items) | _moss_no_content_fields(_items)
        for _n in _copied:
            if _n == "DESCRIPTION":
                head = re.sub(r"(?m)^DESCRIPTION=.*$", "DESCRIPTION=(none given)", head, count=1)
                fields = dict(fields, DESCRIPTION="(none given)")
            elif _n != "STRUCTURE":
                head = re.sub(r"(?m)^" + re.escape(_n) + r"=.*$", _n + "=uncertain", head, count=1)
                fields = dict(fields, **{_n: "uncertain"})
        _meas = _fill_measured(tail)
        # MELODIC_RANGE / MELODIC_CONTOUR: the measured vocal range and the
        # per-section vocal contour, whenever they exist, as in every scan
        # the previous listening model made (it left both out). MOSS-Music
        # writes both, mostly by repeating the prompt's examples ("C4-G5",
        # "stepwise ascending in verse, leap up in chorus" on six of
        # eighteen scans); its answers are kept only where nothing was measured.
        for _n in ("MELODIC_RANGE", "MELODIC_CONTOUR"):
            _cur = str(fields.get(_n, "")).strip()
            if _meas.get(_n) and _cur and _cur != "uncertain" and _cur != _meas[_n]:
                head = re.sub(r"(?m)^" + _n + r"=.*$", _n + "=uncertain", head, count=1)
                fields = dict(fields, **{_n: "uncertain"})
        # KEY / TEMPO_BPM: the script's decided key and tempo (RECOMMENDED KEY
        # / TEMPO FOR DISCUSSION) when the report's own value disagrees.
        # MOSS-Music writes its own here -- "Eb major (confidence: high)" or
        # "Ab minor" on most tracks, or the prompt's instruction text ("Am
        # (best-supported tonal centre ...") -- which contradicted the decided
        # values and was repeated in DESCRIPTION.
        _k = str(fields.get("KEY", "")).strip()
        if _meas.get("KEY") and _k and _k != "uncertain":
            _kn = _normalize_key_for_compare(_k) or _normalize_key_for_compare(
                (re.search(r"\b([A-G](?:#|b|♯|♭)?m?(?:\s*(?:major|minor))?)\b", _k) or [None, ""])[1])
            if _kn != _normalize_key_for_compare(_meas["KEY"]):
                head = re.sub(r"(?m)^KEY=.*$", "KEY=uncertain", head, count=1)
                fields = dict(fields, KEY="uncertain")
        _tv = str(fields.get("TEMPO_BPM", "")).strip()
        if _meas.get("TEMPO_BPM") and _tv and _tv != "uncertain":
            _tm = re.search(r"\d+(?:\.\d+)?", _tv)
            try:
                if not _tm or abs(float(_tm.group(0)) - float(_meas["TEMPO_BPM"])) > 2.0:
                    head = re.sub(r"(?m)^TEMPO_BPM=.*$", "TEMPO_BPM=uncertain", head, count=1)
                    fields = dict(fields, TEMPO_BPM="uncertain")
            except ValueError:
                pass
        # DRUM STEM NOTE: there is no kit, whatever the report's DRUMS and
        # INSTRUMENTATION say (MOSS-Music described "soft kick ... brushed
        # snare" on an acoustic guitar track).
        if "DRUM STEM NOTE:" in tail:
            _dr = str(fields.get("DRUMS", "")).strip()
            if _dr and not re.match(r"(?i)^none\b", _dr):
                head = re.sub(r"(?m)^DRUMS=.*$", "DRUMS=none (no drum kit; see DRUM STEM NOTE)", head, count=1)
                fields = dict(fields, DRUMS="none (no drum kit; see DRUM STEM NOTE)")
            _ins = str(fields.get("INSTRUMENTATION", ""))
            if _ins and "\n" not in _ins:
                _items = [x for x in _ins.split(";") if x.strip()]
                _keep = [x for x in _items if not re.match(
                    r"(?i)^\s*(?:\(?\d+\)?\s*)?(?:drums?|drum\s*kit|percussion|kick|snare|hi-?hats?)\b", x)]
                if _keep and len(_keep) < len(_items):
                    _new = ";".join(_keep).strip()
                    head = re.sub(r"(?m)^INSTRUMENTATION=.*$", lambda _m: "INSTRUMENTATION=" + _new, head, count=1)
                    fields = dict(fields, INSTRUMENTATION=_new)
        # GUITAR CHECK: acoustic guitar throughout and no electric reading
        # anywhere -- an "electric guitar" item is the listening model's guess.
        if ACOUSTIC_GUITAR_CHECK and _acoustic_only_guitar(tail):
            _ins = str(fields.get("INSTRUMENTATION", ""))
            if _ins and "\n" not in _ins:
                _items = [x for x in _ins.split(";") if x.strip()]
                _el = re.compile(r"(?i)^\s*(?:\(?\d+\)?\s*)?electric[ -]?guitars?\b")
                _keep = [(" " if i else "") + _SEMI_ACOUSTIC_ITEM if _el.match(x) else x
                         for i, x in enumerate(_items)]
                if _keep != _items:
                    _new = ";".join(_keep).strip()
                    head = re.sub(r"(?m)^INSTRUMENTATION=.*$", lambda _m: "INSTRUMENTATION=" + _new, head, count=1)
                    fields = dict(fields, INSTRUMENTATION=_new)
        vp_meas = _meas.get("VOCALS_PRESENT")
        v = str(fields.get("VOCALS_PRESENT", "")).strip()
        if vp_meas and v and v != "uncertain" and not re.match(r"(?i)^(?:yes|no)\b", v):
            head = re.sub(r"(?m)^VOCALS_PRESENT=.*$", "VOCALS_PRESENT=uncertain", head, count=1)
            fields = dict(fields, VOCALS_PRESENT="uncertain")
            v = "uncertain"
        voiced = vp_meas == "yes" or (not vp_meas and re.match(r"(?i)^yes\b", v))
        lvc = str(fields.get("LEAD_VOCAL_CHARACTERISTICS", "")).strip()
        if voiced and lvc and lvc != "uncertain" and (_LVC_NO_VOICE_RE.match(lvc)
                                                      or _INSTRUMENTAL_PROSE_RE.search(lvc)):
            head = re.sub(r"(?m)^LEAD_VOCAL_CHARACTERISTICS=.*$", "LEAD_VOCAL_CHARACTERISTICS=uncertain",
                          head, count=1)
            fields = dict(fields, LEAD_VOCAL_CHARACTERISTICS="uncertain")
    except Exception:
        pass
    return head, fields


def _report_fill_from_evidence(out, structure_given=False):
    """dev66: see REPORT_FILL_FROM_EVIDENCE. `out` is a laid-out analysis
    (_moss_canonical_report); fields that are still "uncertain" are filled and
    REPORT_NOTE says where every filled value came from."""
    if not REPORT_FILL_FROM_EVIDENCE:
        return out
    try:
        cut = _moss_report_head_end(out)
        head, tail = out[:cut], out[cut:]
        fields, _ = _moss_parse_report(head)
        head, fields = _report_unsettled_vocal_fields(head, fields, tail)
        missing = [n for n in _MOSS_CANONICAL_FIELDS
                   if n != "STRUCTURE" and str(fields.get(n, "")).strip() in ("uncertain", "")]
        desc = str(fields.get("DESCRIPTION", "")).strip()
        era = _fill_era_prose(tail)
        filled_model, filled_measured = {}, {}
        moved = set()
        if missing:
            meas = _fill_measured(tail)
            for n in ("KEY", "TEMPO_BPM", "VOCALS_PRESENT", "LYRICS_PRESENT", "MELODIC_RANGE"):
                if n in missing and meas.get(n):
                    filled_measured[n] = meas[n]
            if "MELODIC_CONTOUR" in missing and meas.get("MELODIC_CONTOUR"):
                filled_measured["MELODIC_CONTOUR"] = meas["MELODIC_CONTOUR"]
            wanted = [n for n in missing if n not in filled_measured
                      and n not in ("GENRE_RANKED", "GENRE_ADJACENT", "GENRE_RULED_OUT", "KEY", "TEMPO_BPM",
                                    "VOCALS_PRESENT", "LYRICS_PRESENT")]
            vp = str(filled_measured.get("VOCALS_PRESENT") or fields.get("VOCALS_PRESENT") or "").strip().lower()
            if vp.startswith("no"):
                # decided instrumental: no singer or lyric description is copied up
                wanted = [n for n in wanted if n not in ("LEAD_VOCAL_CHARACTERISTICS", "LYRIC_SUBJECT")]
            if wanted:
                d2 = desc if desc and desc != "(none given)" else ""
                d2 = re.sub(r"\s+-\s+(?=[A-Z])", "\n- ", d2)
                d2 = re.sub(r"(?<=[.!?\u201d\"])\s+(?=[A-Z][A-Za-z &/\u2011-]{2,40}?\s?[\u2013\u2014:]\s)", "\n", d2)
                src = d2 + "\n" + era
                if vp.startswith("yes"):
                    # a voice is settled as present: no "absence of vocals"
                    # sentence may be copied into a vocal field
                    src = _drop_no_vocal_sentences(src)
                _have = "\n".join(v for k, v in fields.items() if k not in ("DESCRIPTION", "REPORT_NOTE"))
                filled_model = _fill_from_prose(src, set(wanted), ident=_fill_identity(tail), moved=moved,
                                                already=_have)
                if ("LEAD_VOCAL_CHARACTERISTICS" in wanted and not filled_model.get("LEAD_VOCAL_CHARACTERISTICS")
                        and vp.startswith("yes") and VOCAL_ARBITRATION_MARKER not in tail):
                    # The dedicated vocal pass's own description of the voice
                    # (MOSS-Music writes it as fields) when the report gave none.
                    _vb = re.search(r"(?ms)^VOCAL / SINGER PROFILE \(isolated dedicated pass\):\n(.*?)(?:\n\n|\Z)", tail)
                    if _vb:
                        _vparts = []
                        for _f in ("LEAD_PROFILE_NOTE", "TIMBRE_NOTE", "DELIVERY_NOTE"):
                            _m = re.search(r"(?m)^" + _f + r"=(.+)$", _vb.group(1))
                            _v = _m.group(1).strip() if _m else ""
                            if _v and _v.lower() not in ("none", "uncertain", "n/a") and \
                                    not _INSTRUMENTAL_PROSE_RE.search(_v):
                                _vparts.append(_v)
                        if _vparts:
                            filled_model["LEAD_VOCAL_CHARACTERISTICS"] = "; ".join(_vparts)
        new_desc = None
        in_fields = " ".join(list(filled_model.values()) + [v for k, v in fields.items()
                                                             if k not in ("DESCRIPTION", "REPORT_NOTE")])
        if desc in ("", "(none given)") and era:
            ident = _fill_identity(tail)
            sents = []
            for _t, s0, _r in _fill_sentences(era):
                c = _fill_clean(s0)
                if not c or _fill_identity_conflict(c, ident) or c in in_fields or c[:1] in "\u201c\"":
                    continue  # dev67: a sentence already in a field (or a quoted lyric line) is not repeated here
                if len(re.findall(r"\b(?:" + dict(_FILL_TOPICS)["_SECTIONS"] + r")", c.lower())) >= 2:
                    continue
                sents.append(c)
            if sents:
                new_desc = " ".join(sents[:2])
        elif desc and desc != "(none given)" and moved and REPORT_FIXED_BLOCKS:
            # dev67: sentences of the report's own prose that now sit in a
            # field are moved there, not repeated in DESCRIPTION.
            d3 = desc
            for raw in sorted(moved, key=len, reverse=True):
                d3 = d3.replace(raw, " ")
            _hd = r"[A-Z][A-Za-z &/\u2011-]{2,40}?\s?[\u2013\u2014:]"
            for _ in range(3):
                d3 = re.sub(r"(?:(?<=\s)|^)" + _hd + r"\s*(?=(?:" + _hd + r"\s)|$)", " ", d3)
                d3 = re.sub(r"(?:(?<=\s)|^)-\s+(?=-\s|$)", " ", d3)
            d3 = re.sub(r"\s{2,}", " ", d3).strip()
            if d3 != desc:
                new_desc = d3 if len(re.findall(r"[A-Za-z]", d3)) >= 12 else \
                    "(the listening model's description is in the fields above)"
        # A voice settled as present: the model's own sentences saying there
        # is none ("Despite the absence of vocals in this recording ...") are
        # left out of DESCRIPTION too.
        _vp_now = str(filled_measured.get("VOCALS_PRESENT") or fields.get("VOCALS_PRESENT") or "").strip().lower()
        if _vp_now.startswith("yes"):
            _dbase = new_desc if new_desc is not None else desc
            if _dbase and _dbase != "(none given)":
                _dscr = _drop_no_vocal_sentences(_dbase)
                if _dscr != _dbase:
                    new_desc = _dscr or "(none given)"
        old_note = re.search(r"(?m)^REPORT_NOTE=(.*)$", head)
        struct_in_note = bool(old_note and structure_given and re.search(
            r"(?:first pass[^;]*|not given[^;]*)\bSTRUCTURE\b", old_note.group(1)))
        if not (filled_model or filled_measured or new_desc or struct_in_note):
            # CHORDS / INSTRUMENTATION in the current format (the same repair
            # as at load time, so saved and loaded scans read alike).
            return _report_line_repairs(out)

        def _sub(name, value):
            nonlocal head
            head = re.sub(r"(?m)^" + name + r"=uncertain$", lambda _m: f"{name}={value}", head, count=1)

        for n, v in filled_measured.items():
            if v:
                _sub(n, v)
        for n, v in filled_model.items():
            if v:
                _sub(n, v.replace("\n", " "))
        if new_desc:
            head = re.sub(r"(?m)^DESCRIPTION=.*$", lambda _m: "DESCRIPTION=" + new_desc, head, count=1)
        # REPORT_NOTE: where each value came from.
        old = re.search(r"(?m)^REPORT_NOTE=(.*)$", head)
        first = []
        if old:
            m1 = re.search(r"from the listening model's first pass \([^)]*\): ([^;]*)", old.group(1))
            if m1:
                first = [x.strip() for x in m1.group(1).split(",") if x.strip() and x.strip() != "STRUCTURE"]
        prev_model, prev_meas, prev_desc = [], [], []
        if old:
            mm = re.search(r"from the listening model's own description further down \(its report left them out\): ([^;]*)", old.group(1))
            prev_model = [x.strip() for x in mm.group(1).split(",")] if mm else []
            # a field reset to uncertain above no longer comes from there
            prev_model = [x for x in prev_model
                          if x in filled_model or str(fields.get(x, "")).strip() != "uncertain"]
            mm = re.search(r"measured, not the listening model's words: ([^;]*)", old.group(1))
            prev_meas = [x.strip() for x in mm.group(1).split(",")] if mm else []
            prev_desc = [p for p in old.group(1).split("; ") if p.startswith("DESCRIPTION ")]
        filled_model = dict(filled_model)
        for k in prev_model:
            filled_model.setdefault(k, "")
        filled_measured = dict(filled_measured)
        for k in prev_meas:
            filled_measured.setdefault(k, "")
        done = set(filled_model) | set(filled_measured)
        still = [n for n in missing if n not in done]
        parts = []
        if first:
            parts.append("from the listening model's first pass (its self-check reply left them out): " + ", ".join(first))
        if filled_model:
            parts.append("from the listening model's own description further down (its report left them out): "
                         + ", ".join(n for n in _MOSS_CANONICAL_FIELDS if n in filled_model))
        if not new_desc and prev_desc:
            parts.extend(prev_desc)
        elif new_desc and desc in ("", "(none given)"):
            parts.append("DESCRIPTION from the listening model's era-pass description")
        elif new_desc:
            parts.append("DESCRIPTION keeps the rest of the report's own prose (sentences moved into the fields "
                         "above are not repeated)")
        if filled_measured:
            parts.append("measured, not the listening model's words: "
                         + ", ".join(n for n in _MOSS_CANONICAL_FIELDS if n in filled_measured))
        if structure_given:
            parts.append("STRUCTURE is the measured section map")
        if still:
            parts.append("not given by the listening model: " + ", ".join(still))
        if not (first or filled_model or filled_measured or new_desc or still):
            parts.insert(0, "all fields from the listening model's self-check")
        if old:
            head = head[:old.start(1)] + "; ".join(parts) + head[old.end(1):]
        return _report_line_repairs(head + tail)
    except Exception:
        return out


# dev67: the same blocks in the same places in every saved file (see REPORT_FIXED_BLOCKS).
_COVER_NONE_TEXT = "none -- this file has no embedded cover art, so there is no visual evidence for this track."
_COVER_NONE_RECORDED = "none recorded for this file's artwork."
_PROD_TAGS_NONE = ("production-character tags (audio classifier, supporting evidence only): "
                   "none above the detection threshold.")
_PROD_SECTION_TITLES = (
    "STEREO IMAGE / MIX WIDTH (objective)", "MASTERING: TRUE PEAK / CLIPPING (objective)",
    "BANDWIDTH / SOURCE PROVENANCE (objective)", "BEAT-SYNCHRONOUS DYNAMICS / PUMPING (objective)",
    "AMBIENCE / REVERB CHARACTER (objective proxy)", "WHOLE-TRACK SPECTRAL BALANCE (objective)",
    "PRODUCTION-CHARACTER TAGS",
)


def _has_cover_observations(text):
    """True when the analysis carries real cover-art observations (the dev67
    "none" placeholder does not count)."""
    t = str(text or "")
    if "COVER ART OBSERVATIONS" not in t:
        return False
    return not re.search(r"COVER ART OBSERVATIONS:\n(?:" + re.escape(_COVER_NONE_TEXT) + "|"
                         + re.escape(_COVER_NONE_RECORDED) + r")", t) or t.count("COVER ART OBSERVATIONS") > 1


def _fixed_blocks_production_tags(t):
    i = t.find("\n\nPRODUCTION / MIX MEASUREMENTS")
    if i < 0 or "\nPRODUCTION-CHARACTER TAGS\n" in t:
        return t
    # walk the production report's own sub-sections; the tags go after the last one
    end = t.find("\n\n", i + 2)
    while end >= 0:
        nxt = t[end + 2:t.find("\n", end + 2) if t.find("\n", end + 2) >= 0 else len(t)]
        if nxt.strip() in _PROD_SECTION_TITLES:
            e2 = t.find("\n\n", end + 2)
            if e2 < 0:
                end = len(t)
                break
            end = e2
            continue
        break
    if end < 0:
        end = len(t)
    return t[:end] + "\n\nPRODUCTION-CHARACTER TAGS\n" + _PROD_TAGS_NONE + t[end:]


def _fixed_blocks_cover(t, has_cover):
    if "COVER ART OBSERVATIONS" in t:
        return t
    block = "COVER ART OBSERVATIONS:\n" + (_COVER_NONE_RECORDED if has_cover else _COVER_NONE_TEXT)
    m = re.search(r"\n\nSINGER IDENTITY RESOLUTION \(", t)
    if m is None:
        m = re.search(r"\n\nACOUSTIC VOCAL READING \(", t)
    if m is None:
        m = re.search(r"\n\nRECOMMENDED STRUCTURE FOR DISCUSSION", t)
    if m is None:
        return t.rstrip("\n") + "\n\n" + block
    return t[:m.start()] + "\n\n" + block + t[m.start():]


def _fixed_blocks_structure_copy(t):
    """The measured section map's second copy (the one below the report) as
    its own STRUCTURE=[...] block right after the era pass, wherever the
    analysis step had put it ("Song STRUCTURE=" inside the era description,
    or after the vocal-onset check)."""
    rn = re.search(r"(?m)^REPORT_NOTE=[^\n]*$", t)
    if not rn:
        return t
    start = rn.end()
    pat = re.compile(r"(?ms)(^(?:Song )?STRUCTURE=\[\n.*?\n\][ \t]*\n?)")
    copies = [m for m in pat.finditer(t, start)]
    if not copies:
        return t
    body = re.sub(r"^Song ", "", copies[0].group(1)).rstrip("\n")
    if any(re.sub(r"^Song ", "", m.group(1)).rstrip("\n") != body for m in copies):
        return t  # copies that disagree are left exactly as they are
    anchor = re.search(r"\n\nVOCAL / SINGER PROFILE", t[start:])
    if anchor is None:
        return t
    out, pos = [], 0
    for m in copies:
        out.append(t[pos:m.start()])
        pos = m.end()
    out.append(t[pos:])
    u = "".join(out)
    u = re.sub(r"\n{3,}", "\n\n", u[start:])
    u = t[:start] + u
    a2 = re.search(r"\n\nVOCAL / SINGER PROFILE", u[start:])
    if a2 is None:
        return t
    k = start + a2.start()
    pre = u[:k].rstrip("\n")
    return pre + "\n\n" + body + u[k:]


def _saved_analysis_fixed_blocks(analysis, has_cover=False):
    """dev67: see REPORT_FIXED_BLOCKS."""
    if not REPORT_FIXED_BLOCKS:
        return analysis
    try:
        t = str(analysis or "")
        if not t:
            return analysis
        t = _fixed_blocks_production_tags(t)
        t = _fixed_blocks_cover(t, has_cover)
        t = _fixed_blocks_structure_copy(t)
        return t
    except Exception:
        return analysis


_DESC_TIDY_NOTE = ("DESCRIPTION leaves out the listening model's own section times, chord lists, "
                   "field fragments and key or tempo statements that disagree with KEY / TEMPO_BPM")
_ENUM_PREFIX_RE = re.compile(r"^\s*(?:\(?\d{1,2}[).]\s*)+")
_DESC_TIME_RE = re.compile(r"\b\d{1,2}:\d{2}\b")
_DESC_SECTION_TIME_RE = re.compile(r"\(\s*\d{1,2}:\d{2}\s*[‐-―\-−‑]")
_DESC_HEADER_RE = re.compile(r"^[A-Z][A-Za-z]+(?:\s+(?:&|and)?\s*[A-Za-z]+){0,3}\s*:\s")
_DESC_FIELD_RE = re.compile(r"^\s*[A-Za-z][A-Za-z_]{2,30}\s*=")
_KEY_NAME_RE = r"([A-G])[\s  ]*([#b♯♭]?)(?:[\s  ]*(major|minor))?"
_DESC_KEY_CLAIM_RE = re.compile(
    r"(?i:rooted in|in the key of|key of|diatonic to|cent(?:re|er)d? (?:on|in|around)|"
    r"tonal cent(?:re|er)(?: of| on| in| is)?|tonic)\s*\(?(?:the\s+)?" + _KEY_NAME_RE + r"(?![a-z0-9])")
_PC = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}


def _key_pc_mode(letter, acc, mode):
    pc = _PC[letter.upper()] + (1 if acc in ("#", "♯") else -1 if acc in ("b", "♭") else 0)
    return pc % 12, (mode or "").lower()


def _first_key(text):
    m = re.search(r"\b" + _KEY_NAME_RE + r"(?![a-z0-9])", str(text or ""))
    return _key_pc_mode(m.group(1), m.group(2), m.group(3)) if m and m.group(3) else None


def _first_bpm(text):
    m = re.search(r"(\d{2,3}(?:\.\d+)?)", str(text or ""))
    return float(m.group(1)) if m else None


def _tidy_description(desc, keys, tempos):
    """dev73: DESCRIPTION without what contradicts or duplicates the
    measured fields: the listening model's own section walkthrough with its
    own times (the measured map is STRUCTURE), chord-arrow lists, field-like
    fragments ("Genre_Related=..."), and sentences naming a key or a tempo
    that agrees with neither the report's KEY / TEMPO_BPM nor the
    recommended figure. Returns (text, removed_anything)."""
    units = [u for u in re.split(r"(?<=[.!?])\s+|\s+(?=-\s+[A-Z])", str(desc or "").strip()) if u.strip()]
    keep, decided, removed, walk = [], [], False, False
    for u in units:
        s = u.strip()
        drop = False
        if walk and (s.startswith("- ") or not _DESC_HEADER_RE.match(s)):
            drop = True              # rest of a section walkthrough
        else:
            walk = False
        if not drop and _DESC_TIME_RE.search(s):
            drop = True
            walk = bool(_DESC_SECTION_TIME_RE.search(s))
        if not drop and (len(re.findall("→|->", s)) >= 6 or re.match(r"(?i)chord progression\b", s)
                         or "STRUCTURE=[" in s or _DESC_FIELD_RE.match(s)):
            drop = True
        if not drop and keys:
            for m in _DESC_KEY_CLAIM_RE.finditer(s):
                pc, mode = _key_pc_mode(m.group(1), m.group(2), m.group(3))
                if not any(pc == k_pc and (not mode or mode == k_mode) for k_pc, k_mode in keys):
                    drop = True
                    break
        if not drop and tempos:
            for m in re.finditer(r"(\d{2,3}(?:\.\d+)?)\s*BPM", s):
                b = float(m.group(1))
                if not any(abs(b - x * f) <= 4.0 for x in tempos for f in (0.5, 1.0, 2.0)):
                    drop = True
                    break
        if drop:
            removed = True
        decided.append((s, drop))
    # a heading left with nothing under it ("Song structure & dynamics:")
    for i, (s, drop) in enumerate(decided):
        if drop:
            continue
        if re.fullmatch(r"[A-Z][^.!?:]{0,60}:", s) and (i + 1 >= len(decided) or decided[i + 1][1]):
            removed = True
            continue
        keep.append(s)
    return " ".join(keep).strip(), removed


def _saved_report_tidy(text):
    """dev73: in a saved analysis's report, (1) GENRE_RANKED written once per
    item -- a numbered "Genre: 1) a; 2) b" line had been numbered again
    ("1) 1) a; 2) 2) b"); the labels are unchanged, as the genre code
    already read past the extra numbers -- and (2) DESCRIPTION tidied by
    _tidy_description, with a REPORT_NOTE line saying so. Idempotent."""
    if not REPORT_TIDY_SAVED:
        return text
    t = str(text or "")
    try:
        cut = _moss_report_head_end(t)
        head, tail = t[:cut], t[cut:]
        if not re.search(r"(?m)^REPORT_NOTE=", head):
            return text

        def _gr(m):
            items = [x.strip() for x in m.group(1).split(";")]
            if not any(re.match(r"^\s*(?:\(?\d{1,2}[).]\s*){2}", x) for x in items):
                return m.group(0)
            items = [_ENUM_PREFIX_RE.sub("", x).strip() for x in items]
            items = [x for x in items if x]
            return "GENRE_RANKED=" + "; ".join(f"{i + 1}) {x}" for i, x in enumerate(items))
        head = re.sub(r"(?m)^GENRE_RANKED=(.*)$", _gr, head, count=1)

        dm = re.search(r"(?m)^DESCRIPTION=(.*)$", head)
        if dm and dm.group(1).strip() not in ("", "(none given)"):
            keys = []
            kf = re.search(r"(?m)^KEY=(.*)$", head)
            rk = re.search(r"RECOMMENDED KEY FOR DISCUSSION:\s*([^\n.]*)", tail)
            for src in ((kf.group(1) if kf else ""), (rk.group(1) if rk else "")):
                k = _first_key(src)
                if k and k not in keys:
                    keys.append(k)
            tempos = []
            tf = re.search(r"(?m)^TEMPO_BPM=(.*)$", head)
            rt = re.search(r"RECOMMENDED TEMPO FOR DISCUSSION:\s*([^\n]*)", tail)
            for src in ((tf.group(1) if tf else ""), (rt.group(1) if rt else "")):
                b = _first_bpm(src)
                if b and b not in tempos:
                    tempos.append(b)
            new, removed = _tidy_description(dm.group(1), keys, tempos)
            if removed:
                head = head[:dm.start()] + "DESCRIPTION=" + (new or "(none given)") + head[dm.end():]
                nm = re.search(r"(?m)^REPORT_NOTE=(.*)$", head)
                if nm and _DESC_TIDY_NOTE not in nm.group(1):
                    head = head[:nm.end()] + "; " + _DESC_TIDY_NOTE + head[nm.end():]
        return head + tail
    except Exception:
        return text


def _saved_report_tidy_then_fill(text, structure_sections=None):
    """dev73: _saved_report_tidy, and when that left DESCRIPTION empty, the
    dev66 fill once more so the description it would give an empty field on
    the next save is given now (saving stays idempotent)."""
    t = _saved_report_tidy(text)
    if t == text or not REPORT_FILL_FROM_EVIDENCE:
        return t
    if re.search(r"(?m)^DESCRIPTION=\(none given\)$", t[:_moss_report_head_end(t)]):
        t = _saved_report_tidy(_report_fill_from_evidence(t, structure_given=bool(structure_sections)))
    return t


def _saved_analysis_fixed_layout(analysis, track_key=None, structure_sections=None):
    """dev64: see REPORT_FIXED_LAYOUT. The listening model's report at the top
    of the analysis in the fixed layout, with the measured section map in
    STRUCTURE=. Correction notes already on top are kept on top; an analysis
    already in the layout (it has REPORT_NOTE=) is left as it is."""
    if not REPORT_FIXED_LAYOUT:
        return analysis
    try:
        t = str(analysis or "")
        if not t:
            return analysis
        lead = ""
        if t.startswith(_CHECKS_BLOCK_HEAD):
            k = t.find("\n\n")
            lead, t = t[:k + 2], t[k + 2:]
        while _CHECK_PARA_RE.match(t):
            k = t.find("\n\n")
            if k < 0:
                break
            lead, t = lead + t[:k + 2], t[k + 2:]
        if re.search(r"(?m)^REPORT_NOTE=", t[:_moss_report_head_end(t)]):
            if not REPORT_FILL_FROM_EVIDENCE:
                return analysis
            t2 = _era_drum_evidence_check(_saved_report_tidy_then_fill(
                _report_fill_from_evidence(t, structure_given=bool(structure_sections)), structure_sections))
            return analysis if t2 == t else lead + t2
        first = _MOSS_FIRST_PASS_BY_TRACK.get(str(track_key), "") if track_key is not None else ""
        out = _moss_canonical_report(t, first)
        if structure_sections:
            cut = _moss_report_head_end(out)
            head, tail = out[:cut], out[cut:]
            head = re.sub(r"(?ms)^STRUCTURE=.*?(?=^[A-Z][A-Z0-9_]{2,}=)",
                          lambda m_: _structure_field_text(structure_sections) + "\n", head, count=1)
            out = head + tail
        out = _report_fill_from_evidence(out, structure_given=bool(structure_sections))
        out = _saved_report_tidy_then_fill(out, structure_sections)    # dev73
        out = _era_drum_evidence_check(out)
        return lead + out
    except Exception:
        return analysis


_ERA_DRUM_NOTE_HEAD = "ERA NOTE (drums):"


def _era_drum_evidence_check(text):
    """With a DRUM STEM NOTE (no kit on the recording), flag the era pass's
    drum observations as contradicted, right after its EVIDENCE line. The era
    pass hears the mix only and described "vintage drum machines" and "analog
    drum recording" on acoustic recordings with no drums. Idempotent; text
    without a DRUM STEM NOTE is returned unchanged."""
    t = str(text or "")
    if "DRUM STEM NOTE:" not in t or _ERA_DRUM_NOTE_HEAD in t:
        return t
    i = t.find("ERA / RELEASE PERIOD (isolated dedicated pass")
    if i < 0:
        return t
    m = re.compile(r"(?m)^EVIDENCE=([^\n]*)$").search(t, i)
    if not m or not _DRUM_CLAIM_RE.search(m.group(1)) and not re.search(r"(?i)drum machine", m.group(1)):
        return t
    note = ("\n" + _ERA_DRUM_NOTE_HEAD + " the era pass's drum observations above are contradicted -- "
            "there is no drum kit on this recording (see DRUM STEM NOTE). Leave them out of any era "
            "reasoning; date it from the other evidence.")
    return t[:m.end()] + note + t[m.end():]


def _saved_analysis_with_checks_block(analysis):
    return _normalize_unresolved_vocal_report(_saved_analysis_with_checks_block_impl(analysis))


def _saved_analysis_with_checks_block_impl(analysis):
    """dev63: with MOSS_CONSISTENT_REPORT, every saved analysis opens the same
    way: a CHECKS block holding the GENRE / INSTRUMENT CHECK lines written
    above the report (or "none"), then the report. Unchanged otherwise."""
    if not (MOSS_CONSISTENT_REPORT or REPORT_FIXED_LAYOUT):
        return analysis
    t = str(analysis or "")
    if not t or t.startswith(_CHECKS_BLOCK_HEAD):
        return analysis
    paras = []
    while _CHECK_PARA_RE.match(t):
        k = t.find("\n\n")
        if k < 0:
            break
        paras.append(t[:k].strip())
        t = t[k + 2:]
    body = "\n".join("- " + p for p in paras) if paras else "none"
    return _CHECKS_BLOCK_HEAD + "\n" + body + "\n\n" + t


def _saved_analysis_with_genre_check(analysis):
    """dev56: see GENRE_CHECK_IN_SAVED_ANALYSIS. The analysis with its GENRE
    CHECK line (and the matching reasoning wording) at the top, exactly as the
    writer is shown it, or unchanged when there is none."""
    t = str(analysis or "")
    if not (GENRE_CHECK_IN_SAVED_ANALYSIS and GENRE_SUPERSEDED_NOTE) or not t or _GENRE_CHECK_HEAD in t:
        return analysis
    try:
        note = _genre_supersession_note(t)
        if note:
            if GENRE_CHECK_FIRM and _GENRE_MINOR_FLAVOUR_OLD in t and not _guitar_stem_reading(t)[0]:
                t = t.replace(_GENRE_MINOR_FLAVOUR_OLD, _GENRE_MINOR_FLAVOUR_NEW)
            return note + "\n\n" + t
        note = _genre_rockflip_note(t)
        if note:
            return note + "\n\n" + t
    except Exception:
        pass
    return analysis


def _seconds_to_mmss(seconds):
    """Format seconds as M:SS, matching the STRUCTURE=[...] timestamp style
    used elsewhere in this file.

    Truncates like a media player's elapsed-time counter instead of rounding:
    a section that starts at 24.6 s is already playing when the player shows
    0:24, and rounding it to 0:25 made every reported start look late. A
    0.2 s allowance absorbs beat-grid jitter (24.85 s still reads 0:25).
    """
    seconds = max(0.0, float(seconds))
    total = int(math.floor(seconds + 0.2))
    m, s = divmod(total, 60)
    return f"{m}:{s:02d}"


def _estimate_meter_from_beats(beat_times, accents):
    """Estimate common meter from an already-detected beat sequence.

    The beat detector supplies the pulse; this helper only chooses the recurring
    accent cycle, so callers do not have to run beat tracking a second time.
    Returns (downbeat_times, beats_per_bar) or (beat_times, 1) when inconclusive.
    """
    try:
        beat_times = np.asarray(beat_times, dtype=float)
        accents = np.asarray(accents, dtype=float)
        if beat_times.size < 4 or accents.size != beat_times.size:
            return beat_times.tolist(), 1
        # Score each (meter, phase) with a two-sample t statistic rather than a
        # raw mean difference. The old score ignored how many beats fell in the
        # "downbeat" set, so long cycles (8, 9, 12) -- which have few downbeats
        # and many phases to choose from -- won on noise alone: on synthetic
        # 4/4 accents it picked 12 or 8 about 75% of the time. The t statistic
        # accounts for sample size, and a mild prior toward common meters stops
        # a longer cycle from winning on a marginal difference.
        n_total = int(beat_times.size)
        all_idx = np.arange(n_total)
        best_by_bpb = {}
        for bpb in (4, 3, 6, 2, 8, 5, 7, 9, 12):
            if n_total < bpb * 3:
                continue
            for phase in range(bpb):
                in_mask = (all_idx % bpb) == phase
                n_in = int(np.count_nonzero(in_mask))
                n_out = n_total - n_in
                if n_in < 2 or n_out < 2:
                    continue
                a_in = accents[in_mask]
                a_out = accents[~in_mask]
                pooled = np.sqrt(
                    ((n_in - 1) * float(np.var(a_in, ddof=1))
                     + (n_out - 1) * float(np.var(a_out, ddof=1)))
                    / float(max(1, n_in + n_out - 2))
                ) + 1e-6
                se = pooled * np.sqrt(1.0 / n_in + 1.0 / n_out)
                t = (float(np.mean(a_in)) - float(np.mean(a_out))) / se
                prev = best_by_bpb.get(bpb)
                if prev is None or t > prev[0]:
                    best_by_bpb[bpb] = (t, phase)
        if not best_by_bpb:
            return beat_times.tolist(), 1

        # Prior toward the meters popular music actually uses at the tracked
        # pulse. A less common cycle must beat 4/4 or 3/4 by a clear margin.
        prior = {4: 1.0, 3: 1.0, 2: 0.8, 6: 0.8, 5: 0.7, 7: 0.7, 8: 0.7, 9: 0.65, 12: 0.65}
        scored = []
        for bpb, (t, phase) in best_by_bpb.items():
            w = prior.get(bpb, 0.6)
            eff = t * w if t > 0 else t / max(w, 1e-6)
            scored.append((eff, 1 if bpb == 4 else 0, bpb, phase, t))
        scored.sort(reverse=True)
        _eff, _pref4, bpb, phase, t_best = scored[0]

        # A 2-beat cycle and a 4-beat cycle are hard to tell apart when beat 3
        # carries a secondary accent. Keep 4 when the would-be downbeat is
        # itself clearly stronger than the beat half a bar later.
        if bpb == 2 and 4 in best_by_bpb and n_total >= 16:
            best4 = None
            for p4 in (phase, phase + 2):
                a_down = accents[(all_idx % 4) == p4]
                a_mid = accents[(all_idx % 4) == ((p4 + 2) % 4)]
                if a_down.size >= 3 and a_mid.size >= 3:
                    sd = np.sqrt((float(np.var(a_down, ddof=1)) + float(np.var(a_mid, ddof=1))) / 2.0) + 1e-6
                    t4 = (float(np.mean(a_down)) - float(np.mean(a_mid))) / (
                        sd * np.sqrt(1.0 / a_down.size + 1.0 / a_mid.size))
                    if best4 is None or t4 > best4[0]:
                        best4 = (t4, p4)
            if best4 is not None and best4[0] >= 2.5:
                bpb, phase = 4, best4[1]

        # No meaningful accent cycle at all: fall back to the common 4-beat bar
        # (already the downstream default) instead of asserting an odd meter.
        # The threshold allows for having searched many (meter, phase) pairs.
        if t_best < 3.0 and 4 in best_by_bpb:
            bpb, phase = 4, best_by_bpb[4][1]
        return beat_times[phase::bpb].tolist(), int(bpb)
    except Exception:
        return beat_times.tolist(), 1


def _downbeat_accent_curve(y, sr, beat_times, onset_env=None, hop_length=512):
    """Per-beat evidence that a beat is the FIRST beat of a bar.

    Plain broadband onset strength was used before, and it favours the snare:
    a backbeat on 2 and 4 has more high-frequency flux than the kick on 1 and
    3, so the bar phase routinely locked onto the backbeat (and often reported
    a 2-beat meter). Every section boundary is then snapped onto the wrong
    beat of the bar. Downbeats are better marked by low-frequency onsets (kick,
    bass entries) and by harmonic change (chords usually change on beat 1), so
    those lead here, with broadband onsets kept as a minor term.

    Returns an array aligned with beat_times. Falls back to the plain onset
    envelope if any of the extra features cannot be computed.
    """
    beat_times = np.asarray(beat_times, dtype=float)
    if onset_env is None:
        onset_env = librosa.onset.onset_strength(y=y, sr=sr, hop_length=hop_length)
    frame_times = librosa.frames_to_time(np.arange(len(onset_env)), sr=sr, hop_length=hop_length)
    full = np.interp(beat_times, frame_times, onset_env)

    def _z(a):
        a = np.asarray(a, dtype=float)
        sd = float(np.std(a))
        return (a - float(np.mean(a))) / sd if sd > 1e-9 else np.zeros_like(a)

    parts = [(0.15, _z(full))]
    try:
        low_env = librosa.onset.onset_strength(
            y=y, sr=sr, hop_length=hop_length, fmax=200.0, n_mels=24
        )
        low_t = librosa.frames_to_time(np.arange(len(low_env)), sr=sr, hop_length=hop_length)
        # Peak in a short window around each beat: a kick's low-band flux can
        # trail the broadband onset the beat tracker locked to.
        win = 0.05
        low = np.array([
            float(np.max(low_env[(low_t >= t - win) & (low_t <= t + win)]))
            if np.any((low_t >= t - win) & (low_t <= t + win)) else 0.0
            for t in beat_times
        ])
        parts.append((0.5, _z(low)))
    except Exception:
        pass
    try:
        chroma = librosa.feature.chroma_stft(y=y, sr=sr, hop_length=hop_length)
        bf = librosa.time_to_frames(beat_times, sr=sr, hop_length=hop_length)
        bf = np.clip(bf, 0, chroma.shape[1] - 1)
        # Mean chroma of the interval AFTER each beat vs the interval BEFORE it,
        # built explicitly per beat. This used to go through librosa.util.sync
        # and assume column k+1 starts at beat k -- but beat_track(trim=False)
        # routinely places the first beat at frame 0, sync then emits one column
        # fewer, the length check failed, and the harmonic-change term was
        # silently dropped on most tracks. Without it the accent curve cannot
        # tell beat 1 from beat 3 (kicks land on both), which is what kept
        # ordinary 4/4 songs being reported as 2/4 with half-bar "downbeats".
        n_frames = chroma.shape[1]
        n_beats = int(beat_times.size)
        typical = int(np.median(np.diff(bf))) if n_beats > 1 else 8
        typical = max(1, typical)

        def _seg_mean(a, b):
            a = int(max(0, min(a, n_frames - 1)))
            b = int(max(a + 1, min(b, n_frames)))
            v = np.mean(chroma[:, a:b], axis=1)
            nv = float(np.linalg.norm(v))
            return v / nv if nv > 1e-9 else None

        change = np.zeros(n_beats)
        valid = np.zeros(n_beats, dtype=bool)
        for k in range(n_beats):
            nxt = int(bf[k + 1]) if k + 1 < n_beats else int(bf[k]) + typical
            prv = int(bf[k - 1]) if k > 0 else int(bf[k]) - typical
            if prv < 0 or int(bf[k]) <= prv:
                continue
            after = _seg_mean(int(bf[k]), nxt)
            before = _seg_mean(prv, int(bf[k]))
            if after is None or before is None:
                continue
            change[k] = 1.0 - float(np.dot(after, before))
            valid[k] = True
        if np.count_nonzero(valid) >= max(4, n_beats // 2):
            if not np.all(valid):
                change[~valid] = float(np.median(change[valid]))
            parts.append((0.35, _z(change)))
    except Exception:
        pass
    if len(parts) == 1:
        return full
    total_w = sum(w for w, _ in parts)
    return sum(w * a for w, a in parts) / total_w


def _legacy_beat_and_downbeat_grid(y, sr, bpm_hint=None):
    """Previous grid estimator (512-sample hop, frame-quantised tempo). Kept as
    the fallback for _beat_and_downbeat_grid.

    Estimate the metrical grid: beat times, bar (downbeat) times, beat length.

    Section boundaries in almost all popular music land on a BAR LINE, not at an
    arbitrary frame index. Everything downstream in this pipeline used to report
    boundaries straight off a 0.25 s novelty frame grid, which is why timestamps
    were consistently a fraction of a bar out even when the change point itself
    was detected correctly. Snapping to this grid is what turns a roughly-right
    detection into an accurate timestamp.

    Downbeats are estimated without a dedicated downbeat tracker (which we don't
    have here) by testing every possible bar phase against a spectral-flux
    accent curve and keeping the phase whose beats carry the most accent. That
    is a well-behaved proxy: bar-initial beats are, on average, the most
    strongly accented ones.

    Returns (beat_times, downbeat_times, beat_len_s, beats_per_bar) or
    (None, None, None, None) when the track is too short / too weak to grid.
    """
    try:
        if y is None or len(y) < sr * 4:
            return (None, None, None, None)

        onset_env = librosa.onset.onset_strength(y=y, sr=sr, hop_length=512)

        kwargs = {"onset_envelope": onset_env, "sr": sr, "hop_length": 512,
                  "trim": False, "units": "time"}
        if bpm_hint:
            try:
                bh = float(bpm_hint)
                # A hint is useful only as a weak lock. The beat tracker itself
                # must remain free to discover a different pulse; a reconciled
                # BPM is not allowed to become a structural prior.
                if 40.0 <= bh <= 220.0:
                    kwargs["start_bpm"] = bh
            except Exception:
                pass

        tempo, beat_times = librosa.beat.beat_track(y=y, **kwargs)
        beat_times = np.asarray(beat_times, dtype=float)
        if beat_times.size < 8:
            return (None, None, None, None)

        # Median inter-beat interval is far more robust than the reported tempo.
        beat_len = float(np.median(np.diff(beat_times)))
        if not (0.2 <= beat_len <= 2.0):
            return (None, None, None, None)

        accents = _downbeat_accent_curve(y, sr, beat_times, onset_env=onset_env, hop_length=512)

        downbeats, bpb = _estimate_meter_from_beats(beat_times, accents)
        return (beat_times.tolist(), downbeats, beat_len, bpb)
    except Exception:
        return (None, None, None, None)


def _beat_and_downbeat_grid(y, sr, bpm_hint=None):
    """Estimate the metrical grid: beat times, bar (downbeat) times, beat
    length and beats per bar.

    Uses _sx_beat_grid: a sub-frame tempo estimate and a kick-anchored onset
    envelope, so the grid does not drift (the previous estimator snapped the
    tempo to whole onset frames -- 120 BPM read as 117.45 BPM -- and every
    bar line after the first few drifted with it). Downbeats are then chosen
    from the accent curve exactly as before. Falls back to the previous
    estimator if anything fails.

    Returns (beat_times, downbeat_times, beat_len_s, beats_per_bar) or
    (None, None, None, None) when the track is too short / too weak to grid.
    """
    if not STRUCTURE_V2_ENABLED:
        return _legacy_beat_and_downbeat_grid(y, sr, bpm_hint=bpm_hint)
    try:
        if y is None or len(y) < sr * 4:
            return (None, None, None, None)
        beats, _bpm = _sx_beat_grid(y, sr, bpm_hint=bpm_hint)
        if not beats or len(beats) < 8:
            return _legacy_beat_and_downbeat_grid(y, sr, bpm_hint=bpm_hint)
        beat_times = np.asarray(beats, dtype=float)
        beat_len = float(np.median(np.diff(beat_times)))
        if not (0.2 <= beat_len <= 2.0):
            return _legacy_beat_and_downbeat_grid(y, sr, bpm_hint=bpm_hint)
        accents = _downbeat_accent_curve(y, sr, beat_times)
        downbeats, bpb = _estimate_meter_from_beats(beat_times, accents)
        return (beat_times.tolist(), downbeats, beat_len, bpb)
    except Exception:
        return _legacy_beat_and_downbeat_grid(y, sr, bpm_hint=bpm_hint)


def _snap_time_to_grid(t, grid, max_shift_s):
    """Move a time to the nearest grid point if one is within max_shift_s."""
    if not grid:
        return float(t)
    arr = np.asarray(grid, dtype=float)
    i = int(np.argmin(np.abs(arr - float(t))))
    if abs(arr[i] - float(t)) <= float(max_shift_s):
        return float(arr[i])
    return float(t)


def _snap_boundaries_to_metre(times, downbeats, beats, beat_len):
    """Snap detected change points onto the metrical grid.

    Preference order: bar line first (a section change is a bar change), then
    beat, then leave alone. The tolerance is expressed in beats so it scales
    with tempo instead of being a fixed number of seconds that is far too loose
    at 160 BPM and far too tight at 70 BPM.
    """
    if not times:
        return []
    if not beat_len or beat_len <= 0:
        return [round(float(t), 2) for t in times]

    bar_tol = beat_len * 2.0     # within half a 4/4 bar -> pull to the bar line
    beat_tol = beat_len * 0.6    # otherwise pull to the nearest beat

    out = []
    for t in times:
        snapped = _snap_time_to_grid(t, downbeats, bar_tol)
        if snapped == float(t):
            snapped = _snap_time_to_grid(t, beats, beat_tol)
        out.append(round(float(snapped), 2))

    # De-duplicate after snapping (two nearby peaks can land on one bar line).
    deduped = []
    for t in sorted(out):
        if not deduped or t - deduped[-1] > 0.05:
            deduped.append(t)
    return deduped


def _structural_novelty_boundaries(y, sr, max_boundaries=16, min_spacing_s=5.0,
                                   bpm_hint=None, return_details=False):
    """Objective, signal-only estimate of song-section change points.

    Rewritten to be BEAT-SYNCHRONOUS and BAR-ALIGNED, which is where the
    accuracy of the reported timestamps actually comes from:

      1. Track beats and estimate the bar grid (_beat_and_downbeat_grid).
      2. Aggregate features per BEAT rather than per fixed 0.25 s frame. A
         fixed frame grid smears the self-similarity matrix differently at
         every tempo; beat-synchronous features make one kernel width mean the
         same musical span (bars) on every track, which is the whole reason a
         single hard-coded kernel used to work on some songs and not others.
      3. Build the self-similarity matrix on stacked-memory features so the
         matrix reflects local *context* rather than instantaneous timbre,
         which sharpens the corners at real section changes.
      4. Correlate a checkerboard kernel along the diagonal (Foote 2000) to get
         a novelty curve, then pick peaks by PROMINENCE, not by raw height --
         raw height plus a fixed floor was letting broad humps through and
         dropping genuine but locally-modest transitions.
      5. Snap surviving peaks onto the bar grid.

    Step 5 is the fix for the specific complaint that section timestamps are
    wrong: the change point was often found within a beat or two, but was then
    reported at whatever arbitrary frame the peak sat on. Section changes land
    on bar lines, so a bar-aligned answer is both more accurate and more
    musically usable.

    Returns a list of seconds. With return_details=True, returns
    (times, info_dict) where info carries the beat grid for reuse.
    """
    empty = ([], {}) if return_details else []
    try:
        duration = len(y) / float(sr)
        if duration < 20.0:
            return empty

        beats, downbeats, beat_len, beats_per_bar = _beat_and_downbeat_grid(
            y, sr, bpm_hint=bpm_hint
        )

        hop_length = 512
        mfcc = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20, hop_length=hop_length)
        # Coefficient 0 is overall log-energy and is ~an order of magnitude
        # larger than the rest; kept out of the timbre block so it cannot
        # dominate, and folded back in separately (below) at a controlled weight.
        mfcc_timbre = mfcc[1:, :]
        chroma = librosa.feature.chroma_cqt(y=y, sr=sr, hop_length=hop_length)
        rms = librosa.feature.rms(y=y, hop_length=hop_length)

        n_frames = min(mfcc_timbre.shape[1], chroma.shape[1], rms.shape[1])
        if n_frames < 16:
            return empty
        mfcc_timbre = mfcc_timbre[:, :n_frames]
        chroma = chroma[:, :n_frames]
        rms = rms[:, :n_frames]

        # --- Beat-synchronous aggregation -------------------------------
        used_beats = False
        if beats and len(beats) >= 12:
            beat_frames = librosa.time_to_frames(
                np.asarray(beats, dtype=float), sr=sr, hop_length=hop_length
            )
            beat_frames = np.clip(beat_frames, 0, n_frames - 1)
            beat_frames = np.unique(beat_frames)
            if beat_frames.size >= 12:
                mfcc_s = librosa.util.sync(mfcc_timbre, beat_frames, aggregate=np.median)
                chroma_s = librosa.util.sync(chroma, beat_frames, aggregate=np.median)
                rms_s = librosa.util.sync(rms, beat_frames, aggregate=np.mean)
                # librosa.util.sync emits len(idx)+1 columns: a leading column
                # for [0:idx[0]], then one per [idx[k-1]:idx[k]]. Mapping column
                # k to idx[k] therefore labels every column with the time of the
                # beat AFTER the audio it summarises, putting every reported
                # boundary a full beat late. seg_times must be the START time of
                # each column instead.
                seg_times = librosa.frames_to_time(
                    np.unique(np.concatenate([[0], beat_frames])),
                    sr=sr, hop_length=hop_length,
                )
                used_beats = True

        if not used_beats:
            # Fall back to a fixed ~0.25 s grid when beat tracking failed.
            step = max(1, int(round(0.25 * sr / hop_length)))
            idx = np.arange(0, n_frames, step)
            mfcc_s = librosa.util.sync(mfcc_timbre, idx, aggregate=np.median)
            chroma_s = librosa.util.sync(chroma, idx, aggregate=np.median)
            rms_s = librosa.util.sync(rms, idx, aggregate=np.mean)
            # Same +1 column / start-time alignment as the beat-synchronous path.
            seg_times = librosa.frames_to_time(
                np.unique(np.concatenate([[0], idx])),
                sr=sr, hop_length=hop_length,
            )

        n = min(mfcc_s.shape[1], chroma_s.shape[1], rms_s.shape[1], len(seg_times))
        if n < 16:
            return empty
        mfcc_s = mfcc_s[:, :n]
        chroma_s = chroma_s[:, :n]
        rms_s = rms_s[:, :n]
        seg_times = np.asarray(seg_times[:n], dtype=float)

        def _znorm(x):
            mu = x.mean(axis=1, keepdims=True)
            sd = x.std(axis=1, keepdims=True)
            # A feature that barely varies carries no structural information,
            # so it is zeroed rather than divided through by a near-zero std.
            # Clamping the divisor instead (sd[sd < 1e-8] = 1e-8) rescales
            # floating-point dither up to full amplitude, which manufactures a
            # convincing novelty curve out of a completely static signal --
            # that is how a held tone or an ambient bed ends up carved into
            # half a dozen "sections".
            scale = np.maximum(np.abs(mu), 1.0)
            dead = sd < (1e-4 * scale)
            safe = np.where(dead, 1.0, sd)
            out = (x - mu) / safe
            out[dead[:, 0], :] = 0.0
            return out

        def _l2(x, weight):
            nrm = np.linalg.norm(x, axis=0, keepdims=True)
            nrm[nrm < 1e-8] = 1e-8
            return weight * (x / nrm)

        # Each feature family is L2-normalised on its own BEFORE being stacked,
        # so the relative weights below are the actual weights. Previously the
        # families were merely z-scored and stacked, which meant a 13-row MFCC
        # block silently outweighed a 12-row chroma block by whatever their
        # variances happened to be on that track.
        loud = np.log1p(np.maximum(rms_s, 0.0) * 1000.0)
        feats = np.vstack([
            _l2(_znorm(mfcc_s), 1.00),                            # timbre
            _l2(_znorm(chroma_s), 0.90),                          # harmony
            _l2(_znorm(loud), 0.45),                              # energy
        ])

        # Stacked memory: each column carries a short window of recent history,
        # so the SSM compares musical *context*, sharpening section corners.
        delay = 4 if used_beats else 8
        memory_steps = 3
        memory_lag = 0
        if n > delay * 3:
            feats = librosa.feature.stack_memory(
                feats, n_steps=memory_steps, delay=delay, mode="edge"
            )
            # stack_memory stacks PAST frames, so the centre of mass of each
            # column's context sits delay*(n_steps-1)/2 frames BEHIND its index.
            # Left uncompensated this pushes every reported change point late by
            # that many frames -- a constant, systematic timestamp error of
            # roughly two bars at 120 BPM, which is precisely the kind of
            # "boundary is in the right place but the time is wrong" failure
            # this rewrite exists to remove. Compensated below when the peak
            # indices are converted back to seconds.
            memory_lag = int(round(delay * (memory_steps - 1) / 2.0))

        nrm = np.linalg.norm(feats, axis=0, keepdims=True)
        nrm[nrm < 1e-8] = 1e-8
        feats = feats / nrm
        sim = feats.T @ feats

        # --- Checkerboard novelty ---------------------------------------
        # Kernel spans ~4 bars of context on each side when beat-synchronous.
        if used_beats:
            bar = int(beats_per_bar or 4)
            kernel_size = max(9, min(int(bar * 8) | 1, n - 1))
        else:
            kernel_size = min(33, n - 1)
        if kernel_size % 2 == 0:
            kernel_size -= 1
        if kernel_size < 5:
            return empty
        half = kernel_size // 2

        gauss = np.exp(-0.5 * (np.linspace(-2, 2, kernel_size) ** 2))
        checker = np.outer(gauss, gauss)
        ar = np.arange(kernel_size)
        sign = np.where((ar[:, None] < half) == (ar[None, :] < half), 1.0, -1.0)
        kernel = checker * sign

        # Vectorised diagonal correlation: extract every kernel-sized window
        # along the main diagonal at once instead of looping in Python.
        centres = np.arange(half, n - half)
        if centres.size < 3:
            return empty
        windows = np.lib.stride_tricks.sliding_window_view(
            sim, (kernel_size, kernel_size)
        )
        diag_windows = windows[centres - half, centres - half]
        novelty_core = np.tensordot(diag_windows, kernel, axes=([1, 2], [0, 1]))

        novelty = np.zeros(n, dtype=float)
        novelty[centres] = novelty_core
        if memory_lag:
            # Shift the curve earlier by the stacked-memory lag so peaks line up
            # with the frame where the music actually changed.
            novelty = np.roll(novelty, -memory_lag)
            novelty[-memory_lag:] = 0.0

        span = float(novelty.max() - novelty.min())
        if span <= 1e-9:
            return empty

        # Guard against normalising nothing into structure. On material that
        # genuinely does not change -- a held tone, a static drone, an ambient
        # bed -- the raw novelty values are all tiny and nearly equal, but
        # rescaling them to 0..1 turns that flat nothing into a curve with
        # convincing-looking peaks, and the track gets carved into sections no
        # listener would hear.
        #
        # The test is MEAN self-similarity between distant frames, not its
        # spread. Spread does not separate the two cases at all: a constant
        # 440 Hz tone and a real verse/chorus song both measure a similarity
        # standard deviation of about 0.57, because frame-level CQT/MFCC jitter
        # on a static signal is as varied as real musical contrast. What
        # actually distinguishes them is the mean -- static material is
        # uniformly self-similar everywhere (mean ~0.42), whereas real music
        # contains genuinely dissimilar regions and averages near zero
        # (mean ~-0.02). A track whose every distant pair still looks alike has
        # no sections to find.
        iu = np.triu_indices(n, k=max(1, kernel_size // 2))
        if iu[0].size >= 16:
            distant = sim[iu]
            sim_mean = float(np.mean(distant))
            # Fraction of distant frame pairs that are genuinely unalike. Real
            # arrangements always have some; static material has essentially none.
            contrast = float(np.mean(distant < 0.0))
            # Measured separation is wide and unambiguous, so the thresholds sit
            # in the middle of the gap rather than near either side:
            #   real arrangements  mean ~-0.04, contrast ~0.59
            #   held tone          mean ~ 0.57, contrast ~0.07
            #   static drone       mean ~ 0.58, contrast ~0.06
            if sim_mean > 0.30 and contrast < 0.20:
                return empty

        novelty = (novelty - novelty.min()) / span

        # Light smoothing kills single-frame spikes without moving true peaks.
        if novelty.size >= 5:
            kern = np.array([0.15, 0.7, 0.15])
            novelty = np.convolve(novelty, kern / kern.sum(), mode="same")

        # --- Prominence-based peak picking ------------------------------
        # Height alone (the old approach) rewards broad humps and misses real
        # but locally-modest transitions. Prominence measures how far a peak
        # stands above the higher of its two flanking valleys, which is what
        # "this is a distinct change point" actually means.
        interior = novelty[half:n - half]
        if interior.size < 3:
            return empty

        peaks = []
        for i in range(half + 1, n - half - 1):
            if novelty[i] >= novelty[i - 1] and novelty[i] > novelty[i + 1]:
                lo = max(half, i - kernel_size)
                hi = min(n - half, i + kernel_size + 1)
                left_min = float(np.min(novelty[lo:i + 1]))
                right_min = float(np.min(novelty[i:hi]))
                prominence = float(novelty[i]) - max(left_min, right_min)
                peaks.append((prominence, float(novelty[i]), i))

        if not peaks:
            return empty

        prom_values = np.array([p[0] for p in peaks], dtype=float)
        med = float(np.median(prom_values))
        mad = float(np.median(np.abs(prom_values - med)))
        prom_floor = max(0.02, med + 0.5 * (mad if mad > 1e-6 else 0.02))

        # How many sections can a track of this length plausibly have? Roughly
        # one change every 15-25 s; this keeps a 2-minute track from being cut
        # into 16 pieces while still allowing a long track enough detail.
        cap = int(max(3, min(max_boundaries, round(duration / 18.0))))

        if used_beats and beat_len:
            # At least two bars between section boundaries.
            bar_len = beat_len * float(beats_per_bar or 4)
            effective_min_spacing = max(float(min_spacing_s), bar_len * 2.0, 8.0)
        else:
            effective_min_spacing = max(float(min_spacing_s), 8.0)

        peaks.sort(key=lambda p: (-p[0], -p[1]))
        chosen_idx = []
        for prominence, _height, i in peaks:
            if prominence < prom_floor:
                continue
            t = float(seg_times[i])
            if t < 4.0 or t > duration - 4.0:
                continue
            if all(abs(t - float(seg_times[j])) >= effective_min_spacing
                   for j in chosen_idx):
                chosen_idx.append(i)
            if len(chosen_idx) >= cap:
                break

        chosen_idx.sort()
        times = [float(seg_times[i]) for i in chosen_idx]

        # --- Bar alignment ----------------------------------------------
        times = _snap_boundaries_to_metre(times, downbeats, beats, beat_len)
        times = [t for t in times if 3.0 <= t <= duration - 3.0]

        # Re-enforce spacing after snapping (two peaks can share a bar line).
        final = []
        for t in times:
            if not final or t - final[-1] >= effective_min_spacing * 0.75:
                final.append(round(t, 2))

        if return_details:
            return final, {
                "beats": beats,
                "downbeats": downbeats,
                "beat_len": beat_len,
                "beats_per_bar": beats_per_bar,
                "beat_synchronous": used_beats,
                "duration": duration,
            }
        return final
    except Exception:
        return empty


# ==============================================================================
# SONG STRUCTURE v2 -- bar-level, multi-cue segmentation and naming
# ==============================================================================
# Everything in this block is signal-only: it measures THIS recording (mix
# features, separated-stem note events, lyric timestamps) and never consults
# genre assumptions, file tags or general knowledge about the song.
#
# Pipeline (see build_structure_map):
#   1. Beat grid with a sub-frame tempo estimate (tracked on a kick-anchored
#      onset envelope), then bar lines from a small Viterbi over bar
#      positions, so a beat the tracker inserts or drops mid-song does not
#      shift every later bar line.
#   2. Beat-synchronous mix features (timbre / harmony / loudness), pooled to
#      bars, plus per-bar stem descriptors when note events are available
#      (vocal coverage and register, kick/snare/hi-hat counts, bass and
#      harmonic-instrument activity).
#   3. A per-bar boundary-evidence curve combining checkerboard novelty on
#      the mix, repetition onsets (where repeated chord sequences start or
#      stop), and discrete arrangement events (drum fills, drum entries and
#      exits, vocal entries after a real gap, a change of vocal register,
#      lyric-block starts). A boundary found at the start of a short break
#      is moved to where the band comes back in.
#   4. A dynamic programme that picks the boundary set with the most evidence
#      under a section-length prior (no sub-4-bar fragments, mild preference
#      for 4-bar multiples, long sections discouraged but allowed).
#   5. Segments are clustered by aligned chord-sequence similarity (plus
#      timbre and repeated lyrics), so repeated sections are recognised even
#      when their arrangement differs a little.
#   6. Names come from what was measured: unsung bookends are Intro/Outro, the
#      repeated sung material with the strongest hook evidence (repeated words,
#      higher vocal register, more energy) is the Chorus -- whether it comes
#      first or second -- other repeated sung material is the Verse, one-off
#      sung material between choruses is the Bridge, unsung mid-song material
#      is Instrumental, digital silence is Silence.
# ==============================================================================

def _sx_refine_tempo(onset_env, frame_rate, bpm0, span=0.06):
    """Sub-frame tempo estimate around a coarse beat-tracker tempo.

    librosa's beat tracker works in whole onset frames, so its tempo snaps to
    60 * frame_rate / k. At the default 512-sample hop and 22.05 kHz that is
    a coarse ladder: a 120 BPM song reads as 117.45 BPM (22 frames) and a
    158 BPM one as 161.5 BPM (16 frames). A 2 % tempo error makes the beat
    grid drift a whole beat every ~50 beats, and every section boundary that
    is snapped to that grid inherits the drift.

    The fix measures the periodicity of the onset envelope directly: the
    magnitude of its Fourier component at each candidate tempo, evaluated on
    a fine grid around the coarse value. Only octave-preserving refinement is
    done (+/- span), so the metrical level the tracker chose is kept.
    """
    try:
        env = np.asarray(onset_env, dtype=float)
        bpm0 = float(bpm0)
        if env.size < 64 or not (30.0 <= bpm0 <= 300.0):
            return bpm0
        t = np.arange(env.size, dtype=float) / float(frame_rate)
        e = env - float(np.mean(env))

        # Candidates are evaluated in blocks small enough that the
        # (candidates x frames) complex matrix stays around 30 MB even on a
        # long file.
        per_block = max(1, int(2_000_000 // max(1, env.size)))

        def _best(cands):
            best_b, best_r = None, -1.0
            for chunk in np.array_split(cands, max(1, int(np.ceil(len(cands) / float(per_block))))):
                if chunk.size == 0:
                    continue
                ph = np.exp(-2j * np.pi * np.outer(chunk / 60.0, t))
                r = np.abs(ph @ e)
                k = int(np.argmax(r))
                if r[k] > best_r:
                    best_b, best_r = float(chunk[k]), float(r[k])
            return best_b

        coarse = _best(np.arange(bpm0 * (1.0 - span), bpm0 * (1.0 + span), 0.05))
        if coarse is None:
            return bpm0
        fine = _best(np.arange(coarse - 0.1, coarse + 0.1, 0.005))
        return float(fine if fine is not None else coarse)
    except Exception:
        return float(bpm0)


def _sx_onset_strength_chunked(y, sr, hop_length, chunk_s=45.0, **kwargs):
    """librosa.onset.onset_strength computed in overlapping blocks.

    A fine-hop STFT of a whole track is large (a 256-sample hop over 16
    minutes is ~1 GB transient), and this runs while the listening model may
    still be resident. Spectral flux is local, so blocks with a few frames of
    overlap stitch back together exactly apart from per-block dB clipping in
    near-silent passages."""
    n = len(y)
    block = int(chunk_s * sr) // hop_length * hop_length
    if n <= block * 2:
        return librosa.onset.onset_strength(y=y, sr=sr, hop_length=hop_length, **kwargs)
    pad = 16 * hop_length
    total_frames = 1 + n // hop_length
    out = np.zeros(total_frames, dtype=float)
    start = 0
    while start < n:
        a = max(0, start - pad)
        b = min(n, start + block + pad)
        env = librosa.onset.onset_strength(y=y[a:b], sr=sr, hop_length=hop_length, **kwargs)
        f0 = (start - a) // hop_length
        f_first = start // hop_length
        count = min(block // hop_length, total_frames - f_first, len(env) - f0)
        if count > 0:
            out[f_first:f_first + count] = env[f0:f0 + count]
        start += block
    return out


def _sx_onset_envelope(y, sr, hop_length=256):
    """Broadband onsets plus a low-frequency (kick/bass) onset envelope, each
    scaled to unit spread. Broadband flux alone lets off-beat hats, claps and
    synth stabs pull a beat tracker half a beat out for whole passages of
    dance and pop material; the low band anchors it to the kick."""
    env_full = _sx_onset_strength_chunked(y, sr, hop_length)
    env = env_full / (float(np.std(env_full)) + 1e-9)
    try:
        env_low = _sx_onset_strength_chunked(
            y, sr, hop_length, fmax=250.0, n_mels=32
        )
        if float(np.std(env_low)) > 1e-9:
            env = env + env_low / float(np.std(env_low))
    except Exception:
        pass
    return env


def _sx_track_beats_at(y, sr, bpm, env_cache=None):
    """Run librosa's tracker at a known tempo on a hop fine enough that its
    whole-frame beat period is within ~1 % of that tempo (the tracker rounds
    the period to whole frames: at a 256-sample hop a 240 BPM pulse is 21.5
    frames and is tracked as 234.9 BPM). Returns beat times or None."""
    try:
        bpm = float(bpm)
        if not (30.0 <= bpm <= 320.0):
            return None
        hop = 512
        for cand in (512, 256, 128, 64):
            hop = cand
            if 60.0 * sr / cand / bpm >= 40.0:
                break
        env = None
        if env_cache is not None:
            env = env_cache.get(hop)
        if env is None:
            if hop >= 256:
                env = _sx_onset_envelope(y, sr, hop)
            else:
                # Finer hops are made by interpolating the 256-sample
                # envelope rather than computing a new STFT: the tracker only
                # needs a finer period grid, and a 64/128-sample STFT of a
                # long track costs several hundred MB.
                base = env_cache.get(256) if env_cache is not None else None
                if base is None:
                    base = _sx_onset_envelope(y, sr, 256)
                    if env_cache is not None:
                        env_cache[256] = base
                factor = int(256 // hop)
                xs = np.arange(len(base) * factor, dtype=float) / factor
                env = np.interp(xs, np.arange(len(base), dtype=float), base)
            if env_cache is not None:
                env_cache[hop] = env
        _t, b = librosa.beat.beat_track(
            onset_envelope=env, sr=sr, hop_length=hop,
            trim=False, units="time", bpm=bpm,
        )
        b = np.asarray(b, dtype=float)
        return b if b.size >= 8 else None
    except Exception:
        return None


def _sx_beat_grid(y, sr, bpm_hint=None, hop_length=256):
    """Beat times with a refined tempo. Returns (beats, bpm) or ([], None).

    The metrical level comes from librosa's tempo estimator on a 512-sample
    envelope (cheap; estimating on the finer envelope costs ~600 MB for a
    four-minute track). The tempo is then refined to sub-frame precision on
    the finer envelope (_sx_refine_tempo) and the beats are tracked at that
    tempo on a hop fine enough for the tracker's whole-frame period to match
    it (_sx_track_beats_at), so the grid does not drift against the music.
    """
    try:
        if y is None or len(y) < sr * 4:
            return [], None
        envs = {}
        env512 = _sx_onset_envelope(y, sr, 512)
        envs[512] = env512
        start_bpm = 120.0
        if bpm_hint:
            try:
                bh = float(bpm_hint)
                if 40.0 <= bh <= 220.0:
                    start_bpm = bh
            except Exception:
                pass
        bpm0 = 0.0
        try:
            _tempo_fn = getattr(librosa.feature, "tempo", None) or librosa.beat.tempo
            t0 = _tempo_fn(onset_envelope=env512, sr=sr, hop_length=512, start_bpm=start_bpm)
            t0 = np.atleast_1d(t0)
            bpm0 = float(t0[0]) if t0.size else 0.0
        except Exception:
            bpm0 = 0.0
        if not (bpm0 > 0):
            _t, b0 = librosa.beat.beat_track(
                onset_envelope=env512, sr=sr, hop_length=512, trim=False,
                units="time", start_bpm=start_bpm,
            )
            b0 = np.asarray(b0, dtype=float)
            if b0.size > 4:
                bpm0 = 60.0 / float(np.median(np.diff(b0)))
        if not (bpm0 > 0):
            return [], None
        env = _sx_onset_envelope(y, sr, hop_length)
        envs[hop_length] = env
        bpm = _sx_refine_tempo(env, float(sr) / hop_length, bpm0)
        beats = _sx_track_beats_at(y, sr, bpm, envs)
        if beats is None or len(beats) < 8:
            return [], None
        return np.asarray(beats, dtype=float).tolist(), float(bpm)
    except Exception:
        return [], None


def _sx_drum_hits(stem_notes, kind):
    out = []
    for n in ((stem_notes or {}).get("drums") or []):
        try:
            k = n.get("drum_type") if "drum_type" in n else n.get("k")
            if k == kind:
                out.append(float(n.get("onset", n.get("t", 0.0))))
        except Exception:
            continue
    return out


def _sx_downbeat_flags(beats, bpb, accents, stem_notes=None, event_times=None):
    """Which beats start a bar -- decided along the whole song, not by one
    global phase.

    A beat tracker following a drifting live (or AI-generated) performance
    occasionally inserts or drops a beat. A single global "every 4th beat
    from beat k" grid is then right before the slip and a beat out after it,
    for the rest of the track -- observed: section starts landing one beat
    late after the first minute of a rock take. This runs a small Viterbi
    over bar positions instead: advancing one position per beat is free,
    stalling or skipping a position costs a lot, so the bar phase only moves
    where the evidence keeps saying it has moved. Evidence for "this beat is
    a downbeat": the accent curve (low-frequency onsets + harmonic change),
    section events (a fill resolving, a drum or vocal re-entry), a kick on
    the beat, and -- against it -- a snare/clap on the beat (backbeats sit on
    2 and 4). Returns a boolean array parallel to `beats`.
    """
    beats = np.asarray(beats, dtype=float)
    n = beats.size
    bpb = int(bpb or 4)
    flags = np.zeros(n, dtype=bool)
    if n == 0:
        return flags
    if n < bpb * 3 or bpb < 2:
        flags[0::max(bpb, 1)] = True
        return flags
    med_beat = float(np.median(np.diff(beats))) if n > 1 else 0.5
    tol = 0.25 * med_beat

    def _nearest(t):
        i = int(np.searchsorted(beats, t))
        if i <= 0:
            return 0
        if i >= n:
            return n - 1
        return i if abs(beats[i] - t) < abs(beats[i - 1] - t) else i - 1

    down = np.zeros(n)
    if accents is not None and len(accents) == n:
        a = np.asarray(accents, dtype=float)
        sd = float(np.std(a))
        if sd > 1e-9:
            down += 0.8 * (a - float(np.mean(a))) / sd
    for item in event_times or []:
        if isinstance(item, (tuple, list)):
            t, wv = float(item[0]), float(item[1])
        else:
            t, wv = float(item), 1.0
        k = _nearest(t)
        if abs(beats[k] - t) <= tol:
            down[k] += 2.5 * wv
    for kind, wv in (("snare", -0.6), ("kick", 0.3)):
        hits = _sx_drum_hits(stem_notes, kind)
        if len(hits) >= 16:
            on = np.zeros(n, dtype=bool)
            for t in hits:
                k = _nearest(t)
                if abs(beats[k] - t) <= 0.07:
                    on[k] = True
            down += wv * on

    # Viterbi over positions 0..bpb-1 (0 = downbeat).
    stall = skip = -7.0
    score = np.where(np.arange(bpb) == 0, down[0], 0.0)
    back = np.zeros((n, bpb), dtype=int)
    for k in range(1, n):
        new = np.full(bpb, -1e18)
        for st in range(bpb):
            emit = down[k] if st == 0 else 0.0
            for prev, cost in (((st - 1) % bpb, 0.0), (st, stall), ((st - 2) % bpb, skip)):
                v = score[prev] + cost + emit
                if v > new[st]:
                    new[st] = v
                    back[k, st] = prev
        score = new
    st = int(np.argmax(score))
    states = np.zeros(n, dtype=int)
    for k in range(n - 1, -1, -1):
        states[k] = st
        st = back[k, st]
    flags = states == 0
    return flags


def _sx_beat_features(y, sr, beats, hop_length=512):
    """Mix features pooled per beat interval (cached and re-pooled to bars).

    Returns dict(edges, mfcc, chroma, energy) where edges has n+1 entries and
    the first interval starts at 0.0. MFCC[0] (overall level) is excluded
    from timbre; level is carried separately as mean energy so it can be
    weighted on its own.
    """
    duration = len(y) / float(sr)
    mf = librosa.feature.mfcc(y=y, sr=sr, n_mfcc=20, hop_length=hop_length)[1:]
    ch = librosa.feature.chroma_cqt(y=y, sr=sr, hop_length=hop_length)
    rms = librosa.feature.rms(y=y, hop_length=hop_length)[0]
    nf = int(min(mf.shape[1], ch.shape[1], rms.shape[0]))
    bt = np.asarray([b for b in beats if 0.0 < b < duration], dtype=float)
    edges = np.concatenate([[0.0], bt, [duration]])
    fe = np.clip(librosa.time_to_frames(edges, sr=sr, hop_length=hop_length), 0, nf)
    fe[-1] = nf
    cols_m, cols_c, cols_e = [], [], []
    for a, b in zip(fe[:-1], fe[1:]):
        a = int(a)
        b = int(max(b, a + 1))
        a = min(a, nf - 1)
        b = min(b, nf)
        cols_m.append(np.mean(mf[:, a:b], axis=1))
        cols_c.append(np.mean(ch[:, a:b], axis=1))
        cols_e.append(float(np.mean(np.square(rms[a:b]))))
    return {
        "edges": edges,
        "mfcc": np.stack(cols_m, axis=1),
        "chroma": np.stack(cols_c, axis=1),
        "energy": np.asarray(cols_e, dtype=float),
        "duration": duration,
    }


def _sx_note_span(n):
    try:
        if "onset" in n:
            s = float(n.get("onset", 0.0))
            e = float(n.get("offset", s))
        else:
            s = float(n.get("t", 0.0))
            e = s + float(n.get("d", 0.0))
        return s, max(e, s)
    except Exception:
        return None


def _sx_note_midi(n):
    try:
        if n.get("m") is not None:
            return float(n["m"])
        f = float(n.get("frequency") or n.get("hz") or 0.0)
        if f > 0:
            return 69.0 + 12.0 * np.log2(f / 440.0)
    except Exception:
        pass
    return None


def _sx_bar_features(beatfeat, bars, end_time=None, stem_notes=None, instrumental=False):
    """Pool cached beat features into bars and add per-bar stem descriptors.
    Beats after `end_time` (a silent tail) are ignored."""
    edges_b = np.asarray(beatfeat["edges"], dtype=float)
    duration = float(end_time if end_time is not None else beatfeat["duration"])
    bar_edges = np.concatenate([np.asarray(bars, dtype=float), [duration]])
    nb = len(bars)
    centers = 0.5 * (edges_b[:-1] + edges_b[1:])
    idx = np.searchsorted(bar_edges, centers, side="right") - 1
    idx = np.where((centers >= bar_edges[0]) & (centers < duration), np.clip(idx, 0, nb - 1), -1)

    def _pool(X):
        out = np.zeros((X.shape[0], nb))
        for k in range(nb):
            m = idx == k
            if np.any(m):
                out[:, k] = X[:, m].mean(axis=1)
            elif k > 0:
                out[:, k] = out[:, k - 1]
        return out

    mf = _pool(beatfeat["mfcc"])
    ch = _pool(beatfeat["chroma"])
    en = _pool(beatfeat["energy"][None, :])[0]
    F = {
        "mfcc": mf,
        "chroma": ch,
        "loud": 10.0 * np.log10(np.maximum(en, 1e-12)),
        "has_stems": False,
        "has_vocal": False,
    }
    if not stem_notes:
        return F
    widths = np.maximum(1e-6, np.diff(bar_edges))

    def _coverage(notes):
        cov = np.zeros(nb)
        spans = sorted(sp for sp in (_sx_note_span(x) for x in (notes or []) if isinstance(x, dict)) if sp)
        merged = []
        for s, e in spans:
            if merged and s <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])
        for s, e in merged:
            k0 = max(0, int(np.searchsorted(bar_edges, s, side="right") - 1))
            k1 = min(nb, int(np.searchsorted(bar_edges, e, side="left")))
            for k in range(k0, k1):
                cov[k] += max(0.0, min(e, bar_edges[k + 1]) - max(s, bar_edges[k]))
        return np.minimum(1.0, cov / widths)

    def _counts(notes, kind=None):
        c = np.zeros(nb)
        for x in notes or []:
            if not isinstance(x, dict):
                continue
            if kind is not None:
                k = x.get("drum_type") if "drum_type" in x else x.get("k")
                if k != kind:
                    continue
            sp = _sx_note_span(x)
            if not sp:
                continue
            # A hit a few ms ahead of the bar line belongs to the new bar
            # (transcription and beat-tracking jitter are both ~20-40 ms).
            k = int(np.searchsorted(bar_edges, sp[0] + 0.06, side="right") - 1)
            if 0 <= k < nb:
                c[k] += 1
        return c

    def _pitch(notes):
        num = np.zeros(nb)
        den = np.zeros(nb)
        for x in notes or []:
            if not isinstance(x, dict):
                continue
            mid = _sx_note_midi(x)
            sp = _sx_note_span(x)
            if mid is None or not sp:
                continue
            s, e = sp
            k0 = max(0, int(np.searchsorted(bar_edges, s, side="right") - 1))
            k1 = min(nb, int(np.searchsorted(bar_edges, e, side="left")))
            for k in range(k0, max(k1, k0 + 1)):
                if k >= nb:
                    break
                w = max(0.0, min(e, bar_edges[k + 1]) - max(s, bar_edges[k])) or 1e-3
                num[k] += mid * w
                den[k] += w
        p = np.full(nb, np.nan)
        ok = den > 0
        p[ok] = num[ok] / den[ok]
        return p

    vocals = None
    for key in ("vocals", "vocal", "voice"):
        if stem_notes.get(key):
            vocals = stem_notes[key]
            break
    drums = stem_notes.get("drums") or []
    harm = []
    for key in ("other", "guitar", "piano"):
        harm.extend(stem_notes.get(key) or [])
    F.update({
        "has_stems": bool(drums or harm or stem_notes.get("bass")),
        "kick": _counts(drums, "kick"),
        "snare": _counts(drums, "snare"),
        "hat": _counts(drums, "hihat"),
        "drums": _counts(drums),
        "bass": _counts(stem_notes.get("bass")),
        "harm": _counts(harm),
    })
    if vocals and not instrumental:
        F["vocal"] = _coverage(vocals)
        F["vpitch"] = _pitch(vocals)
        F["has_vocal"] = bool(np.max(F["vocal"]) >= 0.3) if nb else False
        F["vocal_notes"] = vocals
    else:
        F["vocal"] = np.zeros(nb)
        F["vpitch"] = np.full(nb, np.nan)
    return F


def _sx_unit_cols(X):
    X = np.asarray(X, dtype=float)
    if X.ndim == 1:
        X = X[None, :]
    mu = X.mean(axis=1, keepdims=True)
    sd = X.std(axis=1, keepdims=True)
    scale = np.maximum(np.abs(mu), 1.0)
    dead = sd < (1e-4 * scale)
    Z = (X - mu) / np.where(dead, 1.0, sd)
    Z[dead[:, 0], :] = 0.0
    nrm = np.linalg.norm(Z, axis=0, keepdims=True)
    nrm[nrm < 1e-9] = 1.0
    return Z / nrm


def _sx_foote(S, half):
    """Checkerboard novelty on a bar-level SSM with a kernel `half` bars wide
    on each side. Truncated at the track edges (no padding), so the first and
    last bars are not flagged as changes just because the matrix ends."""
    n = S.shape[0]
    out = np.zeros(n)
    half = int(max(1, half))
    for i in range(1, n):
        a0 = max(0, i - half)
        b1 = min(n, i + half)
        if i - a0 < 1 or b1 - i < 1:
            continue
        A = S[a0:i, a0:i]
        B = S[i:b1, i:b1]
        X = S[a0:i, i:b1]
        val = 0.5 * (float(A.mean()) + float(B.mean())) - float(X.mean())
        # With fewer than two bars on one side the kernel compares a sliver
        # (a fade-in, a pickup) against a section and over-reports change.
        side = min(i - a0, b1 - i)
        if side < 2:
            val *= 0.5
        out[i] = val
    return np.maximum(out, 0.0)


def _sx_rnorm(x, q=90):
    """Scale a non-negative curve so its typical high values sit near 1.
    The divisor is never below a quarter of the curve's own maximum, so on
    material with one real change and otherwise tiny ripples the ripples
    stay tiny instead of being blown up to the size of a section change."""
    x = np.maximum(np.asarray(x, dtype=float), 0.0)
    pos = x[x > 0]
    if pos.size == 0:
        return x
    s = max(float(np.percentile(pos, q)), 0.25 * float(np.max(pos)))
    return np.minimum(x / (s + 1e-9), 1.5)


def _sx_chroma_unit(F):
    C = np.asarray(F["chroma"], dtype=float)
    Cz = C - C.mean(axis=1, keepdims=True)
    nrm = np.linalg.norm(Cz, axis=0, keepdims=True)
    nrm[nrm < 1e-9] = 1.0
    return Cz / nrm


def _sx_repetition_curve(F, w=4, thr=0.5, min_lag=4, bar_len=None):
    """Where repeated chord sequences begin or end, per bar.

    For every pair of bars far apart, compare the next `w` bars along the
    diagonal (does a repeat start here?) with the previous `w` bars (was it
    already repeating?). A section that comes back produces a diagonal stripe
    in the chord self-similarity matrix; its first and last bars are where
    this curve peaks -- even when the arrangement is unchanged, which is the
    case timbre novelty cannot see.
    """
    if bar_len:
        # ~10 s of context either side, whatever the tracked bar length.
        w = int(min(8, max(4, round(10.0 / float(bar_len)))))
        min_lag = w
    Cz = _sx_chroma_unit(F)
    n = Cz.shape[1]
    if n < 2 * w + min_lag or n > 1200:
        # Too short to hold a repeat, or so long (a DJ mix, a live set) that
        # the bar-by-bar matrices below would cost hundreds of MB.
        return np.zeros(n)
    S = Cz.T @ Cz
    Sp = np.full((n + 2 * w, n + 2 * w), np.nan)
    Sp[w:w + n, w:w + n] = S
    Rf = np.zeros((n, n))
    Rb = np.zeros((n, n))
    cf = np.zeros((n, n))
    cb = np.zeros((n, n))
    for k in range(w):
        f = Sp[w + k:w + k + n, w + k:w + k + n]
        b = Sp[w - 1 - k:w - 1 - k + n, w - 1 - k:w - 1 - k + n]
        Rf += np.nan_to_num(f)
        cf += ~np.isnan(f)
        Rb += np.nan_to_num(b)
        cb += ~np.isnan(b)
    Rf = np.where(cf > 0, Rf / np.maximum(cf, 1), 0.0)
    Rb = np.where(cb > 0, Rb / np.maximum(cb, 1), 0.0)
    I, J = np.indices((n, n))
    far = np.abs(I - J) >= min_lag
    start = np.where(far, np.maximum(0, Rf - thr) * np.maximum(0, thr - Rb), 0.0).sum(axis=1)
    end = np.where(far, np.maximum(0, Rb - thr) * np.maximum(0, thr - Rf), 0.0).sum(axis=1)
    return start + end


def _sx_vocal_phrases(vocal_notes, join_gap):
    spans = sorted(sp for sp in (_sx_note_span(x) for x in (vocal_notes or []) if isinstance(x, dict)) if sp)
    phrases = []
    for s, e in spans:
        if phrases and s - phrases[-1][1] <= join_gap:
            phrases[-1][1] = max(phrases[-1][1], e)
        else:
            phrases.append([s, e])
    return [p for p in phrases if p[1] - p[0] >= 0.4]


def _sx_event_evidence(F, bars, duration, stem_notes=None, lyric_blocks=None):
    """Discrete arrangement events, each scored 0..1 at the bar line where
    the new section would start. Returns (dict of arrays, list of event
    times usable as downbeat votes).

    Windows are measured in SECONDS, not tracked bars: at fast tempos the
    beat tracker often counts eighth notes, so a "bar" can be half a real bar
    and a bar-count window would halve with it.
    """
    nb = len(bars)
    bars = np.asarray(bars, dtype=float)
    bar_edges = np.concatenate([bars, [duration]])
    barlen = float(np.median(np.diff(bar_edges))) if nb > 1 else 2.0
    ev = {k: np.zeros(nb) for k in ("fill", "drum_in", "drum_out", "kick_in", "vocal_in",
                                    "vocal_out", "register", "lyric")}
    votes = []

    def _bar_at_or_before(t, pickup=0.3):
        k = int(np.searchsorted(bar_edges, t + pickup * barlen, side="right") - 1)
        return min(max(k, 0), nb - 1)

    if F.get("has_stems"):
        snares = np.asarray(sorted(_sx_drum_hits(stem_notes, "snare")), dtype=float)
        all_hits = []
        for n in ((stem_notes or {}).get("drums") or []):
            sp = _sx_note_span(n) if isinstance(n, dict) else None
            if sp:
                all_hits.append(sp[0])
        all_hits = np.asarray(sorted(all_hits), dtype=float)
        # Fill: the snare (toms and claps transcribe as snare) is far busier
        # in the stretch just before a bar line than anywhere typical in the
        # song. Judged against the song's own distribution of the same
        # window, so a busy groove does not read as a constant fill.
        win = max(barlen, 1.8)
        if snares.size >= 8:
            counts = np.array([
                np.count_nonzero((snares >= t - win) & (snares < t - 0.03)) for t in bars
            ], dtype=float)
            active = counts[counts > 0]
            if active.size >= 6:
                med = float(np.median(active))
                thr = max(4.0, 2.2 * med, float(np.percentile(active, 92)))
                for i in range(1, nb):
                    if counts[i] >= thr:
                        ev["fill"][i] = min(1.0, 0.6 + 0.4 * (counts[i] - thr) / max(thr, 1.0))
                    elif counts[i] >= 0.8 * thr:
                        # Ramp up to the threshold instead of a hard cut-off:
                        # Omnizart's snare count varies by a hit or two between
                        # runs, and with an all-or-nothing score one hit fewer
                        # erased an AI-generated test track's Chorus 2 boundary (6 snares scored
                        # 0.65, 5 scored 0). Starts at 80% of the threshold: a
                        # wider ramp (70%) gave ordinary busy bars inside a
                        # bridge enough "fill" to pull its boundary off.
                        ev["fill"][i] = 0.6 * (counts[i] - 0.8 * thr) / (0.2 * thr)
                # One fill is one event. When the window is longer than a bar
                # (fast tempos), the same fill also lands in the NEXT bar
                # line's window, and the two scores came out nearly equal
                # (rock test track: 2.12 vs 2.14), so one extra transcribed
                # snare moved Chorus 2 a bar late, from 2:04 to 2:06. Keep the
                # bar line whose window is busiest just before it -- a fill
                # peaks right before the new section's downbeat.
                late_w = min(win, 0.6 * win + 0.2)
                late = np.array([
                    np.count_nonzero((snares >= t - late_w) & (snares < t - 0.03)) for t in bars
                ], dtype=float)
                i = 1
                while i < nb:
                    if ev["fill"][i] <= 0:
                        i += 1
                        continue
                    j = i
                    while j + 1 < nb and ev["fill"][j + 1] > 0:
                        j += 1
                    if j > i:
                        run = list(range(i, j + 1))
                        top = max(float(ev["fill"][k]) for k in run)
                        # Busiest just before the bar line wins; on a tie the
                        # later line, where a long fill actually ends.
                        keep = max(run, key=lambda k: (late[k], k))
                        for k in run:
                            ev["fill"][k] = top if k == keep else 0.0
                    i = j + 1

        # Whole-kit entry / exit: at least ~2 s of (near) silence on the kit.
        if all_hits.size >= 16:
            gap_min = max(2.0, barlen)
            for i in range(1, nb):
                t = bars[i]
                before = np.count_nonzero((all_hits >= t - gap_min) & (all_hits < t - 0.15))
                after = np.count_nonzero((all_hits >= t - 0.15) & (all_hits < t + gap_min))
                if before == 0 and after >= 4:
                    ev["drum_in"][i] = 1.0
                    kicks_ = np.asarray(sorted(_sx_drum_hits(stem_notes, "kick")), dtype=float)
                    first = kicks_[(kicks_ >= t - 0.15) & (kicks_ <= t + max(1.0, 0.5 * barlen))]
                    if first.size:
                        votes.append(float(first[0]))
                elif after == 0 and before >= 4:
                    ev["drum_out"][i] = 1.0

        # Kick re-entry: the kick has been absent for at least two bars while
        # the rest of the kit (or the band) kept going, and comes back on this
        # bar line -- the classic breakdown-to-chorus return in pop and dance
        # music. The whole-kit test above misses it because hats or snare
        # carry on through the break; an AI-generated test track's last chorus (2:15) is exactly
        # this, and was found before only thanks to a borderline fill score.
        kicks_all = np.asarray(sorted(_sx_drum_hits(stem_notes, "kick")), dtype=float)
        if kicks_all.size >= 16:
            k_gap = max(2.0 * barlen, 3.0)
            # A pickup kick or two just before the downbeat belongs to the
            # return, not to the break.
            pickup = max(0.15, 0.25 * barlen)
            beat_w = max(0.3, 0.25 * barlen)
            for i in range(1, nb):
                if ev["drum_in"][i] > 0:
                    continue
                t = bars[i]
                k_before = np.count_nonzero((kicks_all >= t - k_gap) & (kicks_all < t - pickup))
                k_after = np.count_nonzero((kicks_all >= t - 0.15) & (kicks_all < t + barlen))
                on_line = np.count_nonzero((kicks_all >= t - pickup) & (kicks_all <= t + beat_w))
                if (k_before == 0 and k_after >= 2 and on_line >= 1
                        and np.any(kicks_all < t - k_gap)):
                    ev["kick_in"][i] = 1.0

    if F.get("has_vocal"):
        phrases = _sx_vocal_phrases(F.get("vocal_notes"), 0.5 * barlen)
        spans = [(s_, e_) for s_, e_ in phrases]
        notes = []
        for x in F.get("vocal_notes") or []:
            if not isinstance(x, dict):
                continue
            sp = _sx_note_span(x)
            mid = _sx_note_midi(x)
            if sp and mid is not None:
                notes.append((sp[0], sp[1], mid))
        notes.sort()
        n_on = np.asarray([a for a, _b, _m in notes], dtype=float)
        n_mid = np.asarray([mm for _a, _b, mm in notes], dtype=float)

        def _median_pitch(a, b):
            if n_on.size == 0:
                return None
            sel = (n_on >= a) & (n_on < b)
            if np.count_nonzero(sel) < 4:
                return None
            return float(np.median(n_mid[sel]))

        prev_end = None
        for pi, (s_, e_) in enumerate(spans):
            gap = (s_ - prev_end) if prev_end is not None else s_
            k = _bar_at_or_before(s_)
            need = 3.0 if prev_end is None else max(4.0, min(2.5 * barlen, 6.0))
            if gap >= need:
                # Singing resumes after a real break -- the classic section
                # start. Breaths between lines inside a verse do not qualify.
                ev["vocal_in"][k] = max(ev["vocal_in"][k], min(1.0, 0.45 + gap / 20.0))
                votes.append((s_, 0.3))
                if prev_end is not None:
                    j = int(np.searchsorted(bar_edges, prev_end - 0.1 * barlen, side="left"))
                    if 0 < j < nb:
                        ev["vocal_out"][j] = max(ev["vocal_out"][j], min(0.8, 0.3 + gap / 24.0))
            # A sustained change of vocal register at a phrase start: the
            # median pitch of the ~8 s after differs from the ~8 s before.
            if pi > 0 and gap >= 0.25 * barlen:
                before = _median_pitch(s_ - 8.0, s_ - 0.05)
                after = _median_pitch(s_ - 0.05, s_ + 8.0)
                if before is not None and after is not None:
                    d = abs(after - before)
                    if d >= 3.0:
                        ev["register"][k] = max(ev["register"][k], min(1.0, (d - 2.0) / 4.0))
            prev_end = e_ if prev_end is None else max(prev_end, e_)
        if prev_end is not None and duration - prev_end >= max(2.0 * barlen, 4.0):
            j = int(np.searchsorted(bar_edges, prev_end - 0.1 * barlen, side="left"))
            if 0 < j < nb:
                ev["vocal_out"][j] = max(ev["vocal_out"][j], 0.8)

    for blk in lyric_blocks or []:
        try:
            s_ = float(blk["start"])
        except Exception:
            continue
        # Nearest bar line: Whisper line timing is only good to ~0.5 s and
        # sung pickups start a little before the bar, so "at or before"
        # regularly put this a bar early.
        k = int(np.argmin(np.abs(bar_edges[:-1] - s_)))
        if 0 < k < nb:
            # The start of words that recur elsewhere (a chorus or refrain
            # coming in) is moderate evidence; any other block start is weak.
            # Lyrics mainly decide NAMES; the arrangement decides boundaries.
            ev["lyric"][k] = max(ev["lyric"][k], 0.5 if blk.get("signature") else 0.25)
    return ev, votes


def _sx_peaks(x, base_radius=6):
    """Novelty above its local baseline (running median over +/- base_radius
    bars). A broad hump keeps its shape but no longer lifts the whole
    neighbourhood, so the dynamic programme sees where the curve stands out
    rather than where it is merely high."""
    x = np.maximum(np.asarray(x, dtype=float), 0.0)
    n = x.size
    out = np.zeros(n)
    for i in range(n):
        a2 = max(0, i - base_radius)
        b2 = min(n, i + base_radius + 1)
        out[i] = max(0.0, x[i] - float(np.median(x[a2:b2])))
    return _sx_rnorm(out)


def _sx_evidence_curve(F, bars, duration, stem_notes=None, lyric_blocks=None):
    """Per-bar boundary evidence (higher = more likely a section starts here)."""
    nb = len(bars)
    Zt = _sx_unit_cols(F["mfcc"])
    St = Zt.T @ Zt
    L = np.asarray(F["loud"], dtype=float)
    Sl = -np.abs(L[:, None] - L[None, :]) / 3.0
    ev = 0.5 * _sx_peaks(_sx_foote(St, 4)) + 0.5 * _sx_peaks(_sx_foote(St, 8))
    ev = ev + 0.5 * _sx_peaks(_sx_foote(Sl, 4))
    bar_len = float(np.median(np.diff(np.concatenate([np.asarray(bars, dtype=float), [duration]])))) if nb > 1 else None
    ev = ev + 0.6 * _sx_peaks(_sx_repetition_curve(F, bar_len=bar_len))
    if F.get("has_stems"):
        rows = [F["kick"], F["snare"], F["hat"], F["bass"], F["harm"] / 3.0]
        if F.get("has_vocal"):
            vp = np.asarray(F["vpitch"], dtype=float)
            ok = np.where(~np.isnan(vp))[0]
            vpf = np.interp(np.arange(nb), ok, vp[ok]) if ok.size else np.zeros(nb)
            rows = [F["vocal"], (vpf / 6.0) * np.minimum(1.0, F["vocal"] * 3.0)] + rows
        Zs = _sx_unit_cols(np.vstack(rows))
        Ss = Zs.T @ Zs
        ev = ev + STRUCTURE_W_STEM_NOVELTY * (0.5 * _sx_peaks(_sx_foote(Ss, 4)) + 0.5 * _sx_peaks(_sx_foote(Ss, 8)))
    events, votes = _sx_event_evidence(F, bars, duration, stem_notes, lyric_blocks)
    ev = (ev + 1.0 * events["fill"] + 1.0 * events["vocal_in"] + 0.4 * events["vocal_out"]
          + 0.8 * events["drum_in"] + 0.5 * events["drum_out"] + 0.7 * events["kick_in"]
          + 0.6 * events["register"]
          + 0.6 * events["lyric"])
    if nb:
        ev[0] = 0.0
    return ev, events, votes


def _sx_boundary_dp(bars, duration, ev, lam=None, min_bars=None, min_s=None, soft_max_s=None):
    """Choose section starts (bar indices) maximising evidence under a
    section-length prior. Exact dynamic programme over bar lines."""
    lam = STRUCTURE_SECTION_COST if lam is None else lam
    min_bars = STRUCTURE_MIN_SECTION_BARS if min_bars is None else min_bars
    min_s = STRUCTURE_MIN_SECTION_S if min_s is None else min_s
    soft_max_s = STRUCTURE_SOFT_MAX_SECTION_S if soft_max_s is None else soft_max_s
    pos = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    N = len(pos)
    Ex = np.concatenate([np.asarray(ev, dtype=float), [0.0]])
    # At fast tempos the tracker often counts eighth notes, so a tracked
    # "bar" is half a real bar; count phrase lengths in pairs then.
    bar_len = float(np.median(np.diff(pos))) if N > 2 else 2.0
    group = 2 if bar_len < 1.6 else 1
    min_bars = int(min_bars * group)
    phrase = 4 * group
    best = np.full(N, -1e18)
    back = np.full(N, -1, dtype=int)
    best[0] = 0.0
    for j in range(1, N):
        i = np.arange(j)
        nbars = j - i
        L = pos[j] - pos[i]
        pen = np.zeros(j)
        # Too short to be a section. The final partial bar and the very first
        # (pickup) bar are exempt from the bar count, not from the seconds.
        # An intro or outro may be as short as two bars (pickup intros, a
        # final hit); everything else needs the full minimum.
        edge = (i == 0) | (j == N - 1)
        pen += np.where((nbars < min_bars) & ~edge, 3.0, 0.0)
        pen += np.where(edge & (nbars < max(2, min_bars // 2)), 3.0, 0.0)
        pen += np.where(L < np.where(edge, 4.0, min_s), 3.0, 0.0)
        pen += np.where(L > soft_max_s, ((L - soft_max_s) / 15.0) ** 2, 0.0)
        # Sections are usually 4, 8 or 16 bars long; a mild preference only,
        # so a strong cue still wins on an irregular phrase.
        pen += np.where((nbars % phrase == 0) | (j == N - 1) | (i == 0), 0.0, float(STRUCTURE_PHRASE_PENALTY))
        # Most pop/rock sections run 12 s or more; shorter ones need clearly
        # stronger evidence (a 2-bar break still gets through on its events).
        pen += np.where((L < 12.0) & (j < N - 1) & (i > 0), 0.35 * (12.0 - L) / 6.0, 0.0)
        cand = best[:j] + Ex[j] - lam - pen
        k = int(np.argmax(cand))
        best[j] = cand[k]
        back[j] = k
    path = []
    j = N - 1
    while j > 0:
        path.append(j)
        j = back[j]
    return sorted(k for k in path if k < N - 1)


def _sx_shift_off_fill_bar(starts, events, nb, bars=None, duration=None):
    """Move a boundary from the start of a fill bar to the bar line the fill
    leads into.

    A drum fill closes a section; the new one starts on the downbeat after
    it. The fill bar itself is often a timbre/register change too, so the
    dynamic programme could pick its START -- an AI-generated test track's Chorus 2 came out
    at 1:34 (the fill bar) instead of 1:37 when that fill scored a little
    weaker in one transcription. A boundary that is itself anchored by a
    vocal entry or a drum/kick entry is left alone.
    """
    if not events:
        return list(starts)
    fill = events.get("fill")
    if fill is None:
        return list(starts)
    chosen = sorted(set(starts))
    edges = None
    if bars is not None and duration is not None:
        edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
        bar_len = float(np.median(np.diff(edges))) if edges.size > 2 else 2.0
        group = 2 if bar_len < 1.6 else 1
        min_bars = int(STRUCTURE_MIN_SECTION_BARS * group)

    def _fits(j, nxt):
        # The shortened section (j .. next start) must still satisfy the
        # length limits the dynamic programme enforced.
        if edges is None:
            return True
        last = nxt >= nb
        nbars = nxt - j
        length = float(edges[min(nxt, nb)] - edges[j])
        if last:
            return nbars >= max(2, min_bars // 2) and length >= 4.0
        return nbars >= min_bars and length >= float(STRUCTURE_MIN_SECTION_S)

    out = []
    for idx, i in enumerate(chosen):
        j = i + 1
        nxt = chosen[idx + 1] if idx + 1 < len(chosen) else nb
        anchored = any(
            (events.get(k) is not None and i < len(events[k]) and events[k][i] >= 0.5)
            for k in ("vocal_in", "drum_in", "kick_in")
        )
        if (not anchored and j < nb and j not in chosen and j < len(fill) and fill[j] >= 0.3
                and fill[i] < 0.3 and _fits(j, nxt)):
            out.append(j)
        else:
            out.append(i)
    return sorted(set(out))


def _sx_shift_to_reentry(starts, bars, F, duration, events=None):
    """Move a boundary from the start of a short break to where the groove
    comes back.

    A "stop" -- the drums and most of the band dropping out for a bar or
    two -- is heard as the END of the section it closes; the next section
    starts when the band re-enters. Timbre novelty peaks at the drop, so the
    boundary would otherwise land a couple of bars early. A break must be
    quieter (or kick-less) than the music on BOTH sides of it, so a section
    that is simply softer than the one before is not mistaken for one.
    """
    nb = len(bars)
    if nb < 6:
        return list(starts)
    edges = np.concatenate([np.asarray(bars, dtype=float), [duration]])
    loud = np.asarray(F["loud"], dtype=float)
    kick = np.asarray(F["kick"], dtype=float) if F.get("has_stems") else None
    chosen = set(starts)
    out = []
    for i in starts:
        new_i = i
        anchored = False
        if events:
            for key in ("fill", "vocal_in"):
                arr = events.get(key)
                if arr is not None and i < len(arr) and arr[i] >= 0.5:
                    anchored = True
        before = loud[max(0, i - 4):i]
        if before.size >= 2 and not anchored:
            ref_b = float(np.median(before))
            kb = kick[max(0, i - 4):i] if kick is not None else None
            for k in (1, 2, 3):
                j = i + k                      # candidate re-entry bar
                if j >= nb or (edges[j] - edges[i]) > 7.0:
                    break
                after = loud[j:min(nb, j + 3)]
                if after.size < 2:
                    break
                ref = min(ref_b, float(np.median(after)))
                dip = loud[i:j]
                quiet = bool(np.all(dip <= ref - 2.5))
                kickless = False
                if kick is not None and kb is not None and kb.size:
                    ka = kick[j:min(nb, j + 3)]
                    kref = min(float(np.median(kb)), float(np.median(ka)) if ka.size else 0.0)
                    kickless = (kref >= 1.0 and bool(np.all(kick[i:j] <= 0.25 * kref))
                                and bool(np.all(dip <= ref - 1.0)))
                if (quiet or kickless) and j not in chosen:
                    new_i = j
                    break
        out.append(new_i)
    return sorted(set(out))


def _sx_silence_bounds(y, sr):
    """(music_start, music_end) in seconds, excluding digital silence of at
    least STRUCTURE_SILENCE_MIN_S at either end. Fades are kept as music."""
    try:
        hop = 512
        rms = librosa.feature.rms(y=y, hop_length=hop)[0]
        db = 20.0 * np.log10(np.maximum(rms, 1e-10))
        loud = float(np.percentile(db, 95))
        thr = max(STRUCTURE_SILENCE_ABS_DB, loud - STRUCTURE_SILENCE_REL_DB)
        audible = np.where(db > thr)[0]
        dur = len(y) / float(sr)
        if audible.size == 0:
            return 0.0, dur
        t0 = float(librosa.frames_to_time(audible[0], sr=sr, hop_length=hop))
        t1 = float(librosa.frames_to_time(audible[-1] + 1, sr=sr, hop_length=hop))
        start = t0 if t0 >= STRUCTURE_SILENCE_MIN_S else 0.0
        end = t1 if (dur - t1) >= STRUCTURE_SILENCE_MIN_S else dur
        return start, min(end, dur)
    except Exception:
        return 0.0, len(y) / float(sr) if y is not None else 0.0


def _sx_diag_smooth(S, half=4):
    """Average a bar-level SSM along its diagonals over +/-half bars, so each
    entry compares a whole passage around the two bars rather than the two
    bars alone. Short segments then match only where their surroundings
    match too, instead of matching every bar that happens to share a chord."""
    n = S.shape[0]
    acc = np.zeros_like(S)
    cnt = np.zeros_like(S)
    for k in range(-half, half):
        if k >= 0:
            acc[:n - k, :n - k] += S[k:, k:]
            cnt[:n - k, :n - k] += 1
        else:
            acc[-k:, -k:] += S[:n + k, :n + k]
            cnt[-k:, -k:] += 1
    return acc / np.maximum(cnt, 1)


def _sx_chroma_seq_sim(Cz, sa, sb, min_frac=0.6, R=None):
    """Best aligned chord-sequence similarity of two bar ranges: the shorter
    one is slid along the longer and the mean bar-to-bar similarity of the
    best alignment is returned. Alignment matters -- a chorus that comes back
    with a two-bar pickup still matches itself, while a verse and a chorus
    over the same key do not."""
    (a0, a1), (b0, b1) = sa, sb
    la, lb = a1 - a0, b1 - b0
    if la <= 0 or lb <= 0:
        return 0.0
    if la < lb:
        (a0, a1), (b0, b1), la, lb = (b0, b1), (a0, a1), lb, la
    need = max(2, int(np.ceil(min_frac * lb)))
    best = -1.0
    jj = np.arange(lb) + b0
    for off in range(-(lb - need), la - need + 1):
        ii = np.arange(lb) + a0 + off
        ok = (ii >= a0) & (ii < a1)
        if int(ok.sum()) < need:
            continue
        if R is not None:
            v = float(np.mean(R[ii[ok], jj[ok]]))
        else:
            v = float(np.mean(np.sum(Cz[:, ii[ok]] * Cz[:, jj[ok]], axis=0)))
        if v > best:
            best = v
    return best


def _sx_segment_similarity(F, segs, lyric_sig=None, lyric_rep=None, lyric_ng=None):
    """Pairwise 0..1 "same material" score for segments (bar ranges).

    Four independent views of a section, combined so that no single one can
    make two different sections look identical:
      * harmony  -- best-aligned chord-sequence similarity;
      * timbre   -- similarity of the mean (track-normalised) MFCC profile,
                    i.e. the arrangement / instrumentation;
      * register -- how close the sung melody sits (median vocal pitch), when
                    a vocal stem was transcribed. Verse and chorus very often
                    share chords and differ by where the voice sits;
      * level    -- loudness difference.
    Shared repeated lyrics (when available) can only raise the score.
    """
    n = len(segs)
    Cz = _sx_chroma_unit(F)
    Zt = _sx_unit_cols(F["mfcc"])
    loud = np.asarray(F["loud"], dtype=float)
    vpb = np.asarray(F.get("vpitch"), dtype=float) if F.get("has_vocal") else None
    means, lev, reg = [], [], []
    for a, b in segs:
        b = max(b, a + 1)
        v = Zt[:, a:b].mean(axis=1)
        means.append(v / (np.linalg.norm(v) + 1e-9))
        lev.append(float(np.mean(loud[a:b])))
        if vpb is not None:
            vv = vpb[a:b]
            vv = vv[~np.isnan(vv)]
            reg.append(float(np.median(vv)) if vv.size >= 2 else None)
        else:
            reg.append(None)
    W = np.eye(n)
    for i in range(n):
        for j in range(i + 1, n):
            cs = max(0.0, _sx_chroma_seq_sim(Cz, segs[i], segs[j]))
            ts = (float(means[i] @ means[j]) + 1.0) / 2.0
            ls = float(np.exp(-max(0.0, abs(lev[i] - lev[j]) - 1.0) / 2.0))
            # Weighted GEOMETRIC mean: every view must agree. With an
            # arithmetic mean, two sections over the same chord loop scored
            # as "the same" even when arrangement, level and vocal register
            # all said otherwise.
            if reg[i] is not None and reg[j] is not None:
                vs = float(np.exp(-max(0.0, abs(reg[i] - reg[j]) - 1.5) / 2.0))
                parts = ((cs, 0.42), (ts, 0.28), (vs, 0.20), (ls, 0.10))
            else:
                parts = ((cs, 0.50), (ts, 0.35), (ls, 0.15))
            w = float(np.exp(sum(wt * np.log(max(v, 0.02)) for v, wt in parts)))
            if lyric_sig and lyric_sig[i] and lyric_sig[j]:
                inter = len(lyric_sig[i] & lyric_sig[j])
                union = len(lyric_sig[i] | lyric_sig[j])
                # Only when repeated words make up most of BOTH parts: one
                # chorus line spilling into the next verse (timing jitter,
                # a pickup) must not make that verse "the same as" the chorus.
                both_mostly = (lyric_rep is not None
                               and lyric_rep[i] is not None and lyric_rep[j] is not None
                               and lyric_rep[i] >= 0.5 and lyric_rep[j] >= 0.5)
                if union and inter / union >= 0.5 and both_mostly:
                    w = max(w, 0.85)
            if lyric_ng and len(lyric_ng[i]) >= STRUCTURE_LYRIC_MIN_NGRAMS \
                    and len(lyric_ng[j]) >= STRUCTURE_LYRIC_MIN_NGRAMS:
                # Most of the sung phrases are shared both ways: the same
                # lyric section (every chorus), even when the arrangement
                # differs -- a stripped-down opening chorus, a quiet last one.
                o_min, o_max = _sx_lyric_overlap(lyric_ng[i], lyric_ng[j])
                if o_min >= 0.6 and o_max >= 0.4:
                    w = max(w, 0.85)
            # (Lyrics only ever RAISE the score. Lowering it when one part's
            # words repeat and the other's do not was tried and dropped:
            # Whisper often merges lines, which hides real repeats, so the
            # absence of repeated words is not reliable evidence.)
            W[i, j] = W[j, i] = w
    return W


def _sx_cluster(W, idxs, thr=None):
    """Average-linkage clustering of the segments listed in idxs; merging
    stops when the best remaining pair of groups is less alike than thr."""
    thr = STRUCTURE_SAME_MATERIAL_SIM if thr is None else thr
    groups = [[i] for i in idxs]

    def _link(g1, g2):
        return float(np.mean([W[a, b] for a in g1 for b in g2]))

    while len(groups) > 1:
        best = None
        for x in range(len(groups)):
            for y_ in range(x + 1, len(groups)):
                l = _link(groups[x], groups[y_])
                if best is None or l > best[0]:
                    best = (l, x, y_)
        if best is None or best[0] < thr:
            break
        _l, x, y_ = best
        groups[x] = groups[x] + groups[y_]
        del groups[y_]
    labels = {}
    for gi, g in enumerate(sorted(groups, key=min)):
        for i in g:
            labels[i] = gi
    return labels


def _sx_lyric_signatures(segs, bar_edges, lyric_chunks, lyric_groups):
    """Per segment: set of repeated-lyric group ids sung inside it, and the
    fraction of its sung lines whose words come back somewhere else."""
    sigs = [set() for _ in segs]
    rep_frac = [None for _ in segs]
    if not lyric_chunks:
        return sigs, rep_frac
    occ = {}
    for gid, g in enumerate(lyric_groups or []):
        for st, _en in g.get("occurrences") or []:
            occ[round(float(st), 2)] = gid
    tot = [0 for _ in segs]
    rep = [0 for _ in segs]
    for c in lyric_chunks:
        try:
            s = float(c.get("start", -1))
        except Exception:
            continue
        if s < 0:
            continue
        if len(_normalize_lyric_line(c.get("text", "")).split()) < 2:
            continue
        if STRUCTURE_LYRIC_REP_SKIP_VOCABLES:
            # dev26: a line of only "oh"/"yeah"/"na" says nothing about which
            # part it belongs to, however often it comes back.
            _w = [w.strip("'-") for w in re.sub(r"[^\w'\- ]+", " ", str(c.get("text") or "").lower()).split()]
            _w = [w for w in _w if w]
            if _w and all(w in _SX_VOCABLES for w in _w):
                continue
        for k, (a, b) in enumerate(segs):
            if bar_edges[a] - 0.5 <= s < bar_edges[b] - 0.5:
                tot[k] += 1
                g = occ.get(round(s, 2))
                if g is not None:
                    rep[k] += 1
                    sigs[k].add(g)
                break
    for k in range(len(segs)):
        if tot[k] >= 2:
            rep_frac[k] = rep[k] / float(tot[k])
    return sigs, rep_frac


# Three-word phrases made only of these say nothing about which section a
# line belongs to ("and i was", "all of the" are everywhere).
_SX_LYRIC_STOPWORDS = frozenset(
    "a an and are as at be but by for from have he her his i i'm in is it it's its me "
    "my no not of oh on or our she so that the their them they this to up was we were "
    "what when with yeah you your".split()
)


def _sx_sung_time_mapper(vocal_notes, t0, t1):
    """f(frac) -> time inside [t0, t1], spreading a chunk's words over the
    stretches where the vocal stem is actually sounding rather than evenly
    across the chunk (a merged chunk can span an instrumental gap). None when
    there is too little transcribed voice inside the chunk to go by."""
    if not vocal_notes or t1 - t0 <= 0.5:
        return None
    iv = []
    for x in vocal_notes:
        sp = _sx_note_span(x) if isinstance(x, dict) else None
        if sp is None:
            continue
        a, b = max(t0, sp[0]), min(t1, sp[1])
        if b > a:
            iv.append((a, b))
    if not iv:
        return None
    iv.sort()
    merged = [list(iv[0])]
    for a, b in iv[1:]:
        if a <= merged[-1][1] + 0.35:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    total = sum(b - a for a, b in merged)
    if total < 0.2 * (t1 - t0):
        return None

    def f(frac):
        target = frac * total
        acc = 0.0
        for a, b in merged:
            if acc + (b - a) >= target:
                return a + (target - acc)
            acc += b - a
        return merged[-1][1]
    return f


def _sx_split_tag_lines(lyric_chunks, vocal_notes=None):
    """Split chunks that were timed against the file's lyrics (they carry
    "lines": word indices where each tag line starts) into one chunk per
    line, each placed where the vocal stem is singing within the chunk (or
    spread evenly when there is too little transcribed voice), and give each
    line its stanza. A line whose words occur in more than one stanza (a
    hook that ends the bridge and also closes the chorus) takes the stanza
    of the line before it when it can. Unmatched chunks are kept whole,
    without a stanza."""
    out = []
    for c in lyric_chunks or []:
        if not isinstance(c, dict):
            continue
        cuts = c.get("lines")
        stz = c.get("line_stanzas")
        words = str(c.get("text") or "").split()
        try:
            t0 = float(c.get("start"))
            t1 = max(float(c.get("end", t0)), t0)
        except Exception:
            continue
        if not cuts or not stz or len(cuts) != len(stz) + 1 or len(words) < 2:
            d = {k: v for k, v in c.items() if k not in ("lines", "line_stanzas")}
            out.append(d)
            continue
        place = _sx_sung_time_mapper(vocal_notes, t0, t1)
        n = float(len(words))

        def _at(frac):
            return place(frac) if place is not None else t0 + (t1 - t0) * frac

        first = True
        for (a, b), cands in zip(zip(cuts[:-1], cuts[1:]), stz):
            if b <= a:
                continue
            # Only the chunk's first line is timed by Whisper itself; the
            # others are placed by interpolation and can be seconds off.
            out.append({"start": float(_at(a / n)), "end": float(_at(b / n)),
                        "text": " ".join(words[a:b]), "_stanzas": list(cands),
                        "chunk_first": first})
            first = False
    out.sort(key=lambda x: x["start"])
    prev = prev_idx = None
    for ln in out:
        cands = [tuple(x) for x in (ln.pop("_stanzas", None) or [])]
        if not cands:
            prev = prev_idx = None
            continue
        pick = cands[0]
        nxt_line = [x for x in cands if len(x) > 2 and prev_idx is not None and x[2] == prev_idx + 1]
        if nxt_line:
            # The line that follows the previous one in the lyrics: a line
            # repeated inside its stanza is not that stanza starting again.
            pick = nxt_line[0]
        elif prev is not None:
            same = [x for x in cands if x[0] == prev]
            if same:
                # Same stanza again from its top (a double chorus) when the
                # line is the stanza's first; otherwise where it sits in it.
                pick = ([x for x in same if x[1]] or same)[0]
        ln["stanza"], ln["stanza_first"] = int(pick[0]), bool(pick[1])
        prev = ln["stanza"]
        prev_idx = pick[2] if len(pick) > 2 else None
    return out


def _lyric_blocks_from_tag_lines(lines_in, gap_s=6.0):
    """Lyric blocks for lines timed against the file's lyrics, from the
    lyrics' own stanzas: a block starts where the sung stanza changes, where
    a stanza's first line comes round again (a double chorus), or after a gap
    of more than gap_s seconds. So a chorus's second line can never start a
    block (Whisper dropping the first line made the second look like an
    opener), and a hook ending the bridge belongs to the bridge. A stanza
    sung more than once is "repeated" (stronger evidence). Lines without a
    stanza join the block they fall in. Returns None when the lyrics have
    fewer than three stanzas, so the caller keeps the line-repetition
    blocks. Same output format as _lyric_block_segmentation."""
    lines = []
    for c in lines_in or []:
        try:
            st_ = float(c.get("start", -1))
            en_ = float(c.get("end", st_))
        except Exception:
            continue
        if st_ < 0:
            continue
        lines.append((st_, en_, c.get("stanza"), bool(c.get("stanza_first"))))
    lines.sort(key=lambda x: x[0])
    if len({ln[2] for ln in lines if ln[2] is not None}) < 3:
        return None
    blocks, cur, cur_st = [], [lines[0]], lines[0][2]
    for prev, ln in zip(lines, lines[1:]):
        st_, _en, stz, first = ln
        new = (st_ - prev[1]) > gap_s
        if stz is not None:
            if cur_st is not None and stz != cur_st:
                new = True
            elif first and stz == cur_st and not (prev[2] == stz and prev[3]):
                new = new or any(x[2] == stz and x[3] for x in cur)
        if new:
            blocks.append((cur, cur_st))
            cur, cur_st = [ln], stz
        else:
            cur.append(ln)
            if cur_st is None and stz is not None:
                cur_st = stz
    blocks.append((cur, cur_st))
    sung_count = {}
    for _b, stz in blocks:
        if stz is not None:
            sung_count[stz] = sung_count.get(stz, 0) + 1
    out = []
    for b, stz in blocks:
        rep_ = stz is not None and sung_count.get(stz, 0) >= 2
        # Only a block that opens on the stanza's first line marks where the
        # stanza starts; when Whisper missed that line the block starts a line
        # late, so it is weak evidence.
        opens = bool(b[0][3]) and b[0][2] == stz
        out.append({"start": float(b[0][0]), "end": float(b[-1][1]),
                    "signature": frozenset([("stanza", stz)]) if (rep_ and opens) else None,
                    "sung": True, "stanza": stz, "opens": opens})
    return out


def _sx_refine_starts_to_stanzas(starts, bars, duration, lyric_blocks, lines, max_shift_s=9.0):
    """Move a section start forward onto the start of a stanza when the
    arrangement changed a little before the words did.

    A build or fill at the end of a bridge is a strong acoustic change, so
    the boundary search put the chorus there -- but while the singer is still
    on the bridge (its closing hook line), the chorus has not started. When a
    stanza that opens on its first line starts within max_shift_s after a
    boundary, and the voice in between is singing a DIFFERENT stanza, the
    boundary moves to the bar nearest the stanza's start. That singing must
    begin a Whisper chunk after the boundary (its time is then Whisper's own,
    not interpolated across a long chunk, which put a chorus's last line into
    the following bridge often enough to move correct boundaries). A stretch
    with no singing (an instrumental build) is left alone, a boundary never
    passes the next one, and the section it shortens keeps the boundary
    search's minimum length (bars and seconds)."""
    if not starts or not lyric_blocks:
        return starts
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    bar_len = float(np.median(np.diff(edges))) if len(edges) > 2 else 2.0
    min_b = int(STRUCTURE_MIN_SECTION_BARS) * (2 if bar_len < 1.6 else 1)
    out = list(starts)
    for n, k in enumerate(out):
        t = float(edges[k])
        nxt = out[n + 1] if n + 1 < len(out) else len(bars)
        prv = out[n - 1] if n > 0 else 0
        for blk in lyric_blocks:
            if not blk.get("opens") or blk.get("stanza") is None:
                continue
            b0 = float(blk["start"])
            if not (t + 1.0 < b0 <= t + max_shift_s):
                continue
            between = [ln for ln in lines if t - 0.25 <= float(ln.get("start", -1)) < b0 - 0.25
                       and ln.get("stanza") is not None]
            if any(ln.get("stanza") == blk.get("stanza") for ln in between):
                continue
            # The other stanza's singing after the boundary must be timed by
            # Whisper itself (a line that starts its chunk), not placed by
            # interpolating across a long chunk.
            if not any(ln.get("chunk_first") and float(ln["start"]) >= t + 0.25 for ln in between):
                continue
            k2 = int(np.argmin(np.abs(edges[:-1] - b0)))
            if (k < k2 and nxt - k2 >= min_b and k2 - prv >= 2
                    and float(edges[nxt] - edges[k2]) >= STRUCTURE_MIN_SECTION_S):
                out[n] = k2
            break
    return sorted(set(out))


def _sx_backshift_starts_to_stanzas(starts, bars, duration, lyric_blocks, lines, max_back_s=None):
    """dev56: see STRUCTURE_STANZA_BACKSHIFT. A section start moves back to
    the bar nearest a stanza's first line sung more than a bar (at least
    2.5 s) and at most max_back_s before it,
    when that line was timed by Whisper itself (it starts its chunk), no line
    of another stanza starts between the two, and the last stanza sung before
    the line is a different one. Boundaries never cross, and the section it
    shortens keeps the minimum length."""
    max_back_s = float(STRUCTURE_STANZA_BACKSHIFT_S if max_back_s is None else max_back_s)
    if not starts or not lyric_blocks:
        return starts
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    bar_len = float(np.median(np.diff(edges))) if len(edges) > 2 else 2.0
    min_b = int(STRUCTURE_MIN_SECTION_BARS) * (2 if bar_len < 1.6 else 1)
    stz_lines = sorted([ln for ln in lines or [] if ln.get("stanza") is not None],
                       key=lambda x: float(x.get("start", -1)))
    out = list(starts)
    for n, k in enumerate(out):
        t = float(edges[k])
        prv = out[n - 1] if n > 0 else 0
        for blk in lyric_blocks:
            if not blk.get("opens") or blk.get("stanza") is None:
                continue
            b0 = float(blk["start"])
            if not (t - max_back_s <= b0 <= t - max(2.5, 1.25 * bar_len)):
                continue
            first = [ln for ln in stz_lines if abs(float(ln["start"]) - b0) < 0.05]
            if not first or not first[0].get("chunk_first") or not first[0].get("stanza_first"):
                continue
            between = [ln for ln in stz_lines if b0 + 0.05 <= float(ln["start"]) < t]
            if any(ln.get("stanza") != blk.get("stanza") for ln in between):
                continue
            before = [ln for ln in stz_lines if float(ln["start"]) < b0 - 0.05]
            if before and before[-1].get("stanza") == blk.get("stanza") and not before[-1].get("stanza_first"):
                # still inside the same stanza sung just before (a repeat
                # inside one section), not a new one starting
                if b0 - float(before[-1].get("end", before[-1]["start"])) < 6.0:
                    continue
            k2 = int(np.argmin(np.abs(edges[:-1] - b0)))
            if (k2 < k and k2 - prv >= min_b
                    and float(edges[k2] - edges[prv]) >= STRUCTURE_MIN_SECTION_S):
                out[n] = k2
            break
    return sorted(set(out))


def _sx_voiced_seconds(vocal_notes, t0, t1):
    """dev55: seconds inside [t0, t1] where the vocal stem has notes (gaps
    under 0.35 s bridged), or the whole span when there are no vocal notes."""
    if not vocal_notes:
        return float(t1 - t0)
    iv = []
    for x in vocal_notes:
        sp = _sx_note_span(x) if isinstance(x, dict) else None
        if sp is None:
            continue
        a, b = max(t0, sp[0]), min(t1, sp[1])
        if b > a:
            iv.append((a, b))
    if not iv:
        return 0.0
    iv.sort()
    tot, ca, cb = 0.0, iv[0][0], iv[0][1]
    for a, b in iv[1:]:
        if a <= cb + 0.35:
            cb = max(cb, b)
        else:
            tot += cb - ca
            ca, cb = a, b
    return tot + (cb - ca)


def _sx_lyric_ngrams(segs, bar_edges, lyric_chunks, vocal_notes=None):
    """Per segment: the set of short word patterns sung inside it -- each pair
    of neighbouring words, and each pair with one word between them.

    Whisper returns long chunks -- several lines merged, split differently
    each time a chorus comes round, often running across a section boundary
    -- so matching whole chunks (the line groups above) misses most repeats:
    on the rock test track it found the chorus in only one of its three
    occurrences. Word patterns survive that. Each word is placed in time by
    interpolating across its chunk; patterns are taken within one chunk and
    one segment. Using pairs and skip-pairs means one misheard word only
    removes a few patterns. Patterns made only of very common words are
    dropped.
    """
    sets = [set() for _ in segs]
    if not lyric_chunks or not segs:
        return sets
    starts = [float(bar_edges[a]) - 0.5 for a, _b in segs]
    ends = [float(bar_edges[b]) - 0.5 for _a, b in segs]
    for c in lyric_chunks:
        try:
            t0 = float(c.get("start"))
            t1 = float(c.get("end", t0))
        except Exception:
            continue
        if t0 < 0:
            continue
        if (STRUCTURE_NGRAM_MAX_CHUNK_S and (t1 - t0) > float(STRUCTURE_NGRAM_MAX_CHUNK_S)
                and _sx_voiced_seconds(vocal_notes, t0, t1) > float(STRUCTURE_NGRAM_MAX_CHUNK_S)):
            continue    # dev55: words smeared over more singing than one section
        txt = re.sub(r"[^\w' ]+", " ", str(c.get("text") or "").lower())
        words = [w for w in txt.split() if w.strip("'")]
        if len(words) < 2:
            continue
        t1 = max(t1, t0)
        span = t1 - t0
        place = _sx_sung_time_mapper(vocal_notes, t0, t1)
        seg_of = []
        for k in range(len(words)):
            frac = (k + 0.5) / len(words)
            t = place(frac) if place is not None else t0 + span * frac
            j = None
            for q in range(len(segs)):
                if starts[q] <= t < ends[q]:
                    j = q
                    break
            seg_of.append(j)
        for k in range(len(words) - 1):
            for gap in (1, 2):
                if k + gap >= len(words):
                    continue
                j = seg_of[k]
                if j is None or seg_of[k + gap] != j:
                    continue
                w1, w2 = words[k], words[k + gap]
                if w1 in _SX_LYRIC_STOPWORDS and w2 in _SX_LYRIC_STOPWORDS:
                    continue
                sets[j].add((w1, w2) if gap == 1 else (w1, "_", w2))
    return sets


def _sx_lyric_overlap(a, b):
    """(shared / smaller set, shared / larger set) for two phrase sets."""
    if not a or not b:
        return 0.0, 0.0
    inter = len(a & b)
    return inter / float(min(len(a), len(b))), inter / float(max(len(a), len(b)))


def _sx_word_recurrence(lyric_ng, i):
    """Share of segment i's word patterns sung elsewhere in the song (not in
    its neighbours, which share smeared lines), or None with too few words."""
    ng = lyric_ng[i]
    if len(ng) < STRUCTURE_LYRIC_MIN_NGRAMS:
        return None
    others = set()
    for j in range(len(lyric_ng)):
        if abs(j - i) > 1:
            others |= lyric_ng[j]
    return len(ng & others) / float(len(ng))


def _sx_chorus_over_tags(chorus, verse, units, repeated, sung_rep, lyric_ng, late, by_hook=False):
    """(chorus, verse, tags): if the chosen chorus is a short tag and another
    word-repeating part is clearly longer and comes round at least as often,
    that part is the chorus. Tags are the other word-repeating parts whose
    shortest occurrence is short and whose total length is well below the
    chorus's. by_hook: the chorus was chosen by level/register alone (no
    part's words stood out pair by pair); if its words mostly do not come
    back and another part's mostly do, that part is the chorus."""
    def _rec(c):
        vals = [_sx_word_recurrence(lyric_ng, i) for k in repeated[c] for i in units[k]["segs"]]
        vals = [v for v in vals if v is not None]
        return float(np.mean(vals)) if vals else None

    def _total(c):
        return sum(units[k]["len"] for k in repeated[c])

    def _shortest(c):
        return min(units[k]["len"] for k in repeated[c])

    wordy = [c for c in sung_rep if c not in late and (_rec(c) or 0.0) >= STRUCTURE_TAG_WORDS_MIN]
    if by_hook and STRUCTURE_CHORUS_WORDS_FALLBACK and chorus not in wordy:
        r0 = _rec(chorus)
        alt = [c for c in wordy if c != chorus]
        if r0 is not None and r0 <= STRUCTURE_HOOK_CHORUS_WORDS_MAX and alt:
            new_chorus = max(alt, key=_total)
            if verse == new_chorus or verse is None:
                verse = chorus
            chorus = new_chorus
    if not STRUCTURE_CHORUS_PREFERS_LONGER:
        return chorus, verse, set()
    if chorus in wordy and _shortest(chorus) <= STRUCTURE_TAG_MAX_S:
        longer = [c for c in wordy if c != chorus
                  and _total(c) >= STRUCTURE_TAG_LENGTH_RATIO * _total(chorus)
                  and len(repeated[c]) >= len(repeated[chorus])
                  and _shortest(c) > _shortest(chorus)]
        if longer:
            new_chorus = max(longer, key=_total)
            if verse == new_chorus:
                rest = [c for c in sung_rep if c not in (new_chorus, chorus) and c not in wordy]
                verse = max(rest, key=_total) if rest else None
            chorus = new_chorus
    tags = set(c for c in wordy if c != chorus and c != verse
               and _shortest(c) <= STRUCTURE_TAG_MAX_S
               and _total(c) * STRUCTURE_TAG_LENGTH_RATIO <= _total(chorus))
    return chorus, verse, tags


# dev51: see STRUCTURE_SPLIT_BY_COHESION.
def _sx_cluster_last_merges(W, idxs, thr=None):
    """For each group _sx_cluster(W, idxs, thr) produces, the merge that
    formed it last: {frozenset(group): (link, part_a, part_b)}. Same
    average-linkage steps as _sx_cluster."""
    thr = STRUCTURE_SAME_MATERIAL_SIM if thr is None else thr
    groups = [[i] for i in idxs]
    last = {}

    def _link(g1, g2):
        return float(np.mean([W[a, b] for a in g1 for b in g2]))

    while len(groups) > 1:
        best = None
        for x in range(len(groups)):
            for y_ in range(x + 1, len(groups)):
                l = _link(groups[x], groups[y_])
                if best is None or l > best[0]:
                    best = (l, x, y_)
        if best is None or best[0] < thr:
            break
        l, x, y_ = best
        a, b = list(groups[x]), list(groups[y_])
        groups[x] = a + b
        del groups[y_]
        last[frozenset(groups[x])] = (l, a, b)
    return {frozenset(g): last.get(frozenset(g)) for g in groups}


def _sx_regroup_lone_sung(W, labels, cov, lyric_ng=None):
    """dev51: see STRUCTURE_LONE_SUNG_REGROUP. Returns new labels. With
    lyrics, a segment whose words mostly come back is not moved into a group
    whose words mostly do not, nor the reverse."""
    def _rec(i):
        return _sx_word_recurrence(lyric_ng, i) if lyric_ng else None

    def _words_clash(i, g2):
        ri = _rec(i)
        rg = [v for v in (_rec(j) for j in g2) if v is not None]
        if ri is None or not rg:
            return False
        rm = float(np.mean(rg))
        lo, hi = min(ri, rm), max(ri, rm)
        return (lo <= STRUCTURE_WORDS_NEW_MAX and hi >= STRUCTURE_WORDS_SAME_MIN
                and hi - lo >= STRUCTURE_WORDS_GAP)

    groups = {}
    for i, l in labels.items():
        groups.setdefault(l, []).append(i)

    def _sung(i):
        return cov[i] >= STRUCTURE_SUNG_MIN_COVERAGE

    new = dict(labels)
    for l, g in sorted(groups.items()):
        s_ = [i for i in g if _sung(i)]
        if len(s_) != 1 or len(g) < 2:
            continue
        best = None
        for l2, g2 in groups.items():
            if l2 == l or len(g2) < 2 or not all(_sung(j) for j in g2):
                continue
            if _words_clash(s_[0], g2):
                continue
            link = float(np.mean([W[s_[0], j] for j in g2]))
            if best is None or link > best[0]:
                best = (link, l2)
        if best is not None and best[0] >= STRUCTURE_SAME_MATERIAL_SIM:
            new[s_[0]] = best[1]
    return new


def _sx_split_by_cohesion(W, body, labels, lyric_ng, cov):
    """Returns (labels, new_words_labels)."""
    n = len(lyric_ng)

    def _recur(i):
        ng = lyric_ng[i]
        if len(ng) < STRUCTURE_LYRIC_MIN_NGRAMS:
            return None
        others = set()
        for j in range(n):
            if abs(j - i) > 1:      # neighbours share smeared lines
                others |= lyric_ng[j]
        return len(ng & others) / float(len(ng))

    def _coh(g):
        return float(np.mean([W[a, b] for a in g for b in g if a < b]))

    def _runs(g):
        g = sorted(g)
        return 1 + sum(1 for a, b in zip(g, g[1:]) if b != a + 1)

    def _sung_runs(g):
        sg = [i for i in g if cov[i] >= STRUCTURE_SUNG_MIN_COVERAGE]
        return len(sg), (_runs(sg) if sg else 0)

    groups = {}
    for i, l in labels.items():
        groups.setdefault(l, []).append(i)
    new = dict(labels)
    made = set()
    nxt = (max(labels.values()) + 1) if labels else 0
    for _l, members in sorted(groups.items()):
        if len(members) < 4:
            continue
        # The group's own top split: the same average-linkage steps run on its
        # members alone, merged all the way.
        lm = list(_sx_cluster_last_merges(W, sorted(members), thr=-1.0).values())[0]
        if lm is None:
            continue
        link, ga, gb = lm
        if len(ga) < 2 or len(gb) < 2 or _runs(ga) < 2 or _runs(gb) < 2:
            continue
        if min(_coh(ga), _coh(gb)) - link < STRUCTURE_COHESION_MARGIN:
            continue
        # Each side must be recurring SUNG material on its own: two or more
        # sung segments at separate points in the song.
        if min(_sung_runs(ga)[1], _sung_runs(gb)[1]) < 2:
            continue
        ra = [v for v in (_recur(i) for i in ga) if v is not None]
        rb = [v for v in (_recur(i) for i in gb) if v is not None]
        if not ra or not rb:
            continue
        ma, mb = float(np.mean(ra)), float(np.mean(rb))
        lo, hi = (ga, gb) if ma < mb else (gb, ga)
        mlo, mhi = min(ma, mb), max(ma, mb)
        if mlo > STRUCTURE_WORDS_NEW_MAX or mhi < STRUCTURE_WORDS_SAME_MIN or mhi - mlo < STRUCTURE_WORDS_GAP:
            continue
        for i in lo:
            new[i] = nxt
        made.add(nxt)
        nxt += 1
    return new, made


def _sx_split_shared_music_by_words(labels, body, lyric_ng, sung):
    """Returns (labels, new_labels): the labels with any new-words segments
    moved to labels of their own, and the set of those new labels (parts the
    namer should treat as verse-like by their words)."""
    n = len(lyric_ng)

    def _recur(i):
        ng = lyric_ng[i]
        if len(ng) < STRUCTURE_LYRIC_MIN_NGRAMS:
            return None
        others = set()
        for j in range(n):
            if abs(j - i) > 1:      # neighbours share smeared lines
                others |= lyric_ng[j]
        return len(ng & others) / float(len(ng))

    rec = {i: _recur(i) for i in body}
    runs = []
    for i in body:
        if runs and runs[-1][-1] == i - 1 and labels[runs[-1][-1]] == labels[i]:
            runs[-1].append(i)
        else:
            runs.append([i])
    by_cl = {}
    for ru in runs:
        by_cl.setdefault(labels[ru[0]], []).append(ru)

    def _sung(c):
        return float(np.mean([bool(sung[i]) for ru in by_cl[c] for i in ru])) >= 0.5

    for c, rus in by_cl.items():
        if len(rus) >= 2 and _sung(c):
            vals = [rec[i] for ru in rus for i in ru if rec[i] is not None]
            if len(vals) >= 2 and max(vals) <= STRUCTURE_WORDS_NEW_MAX:
                return labels, set()    # a verse of its own already exists
    new = dict(labels)
    made = set()
    nxt = (max(labels.values()) + 1) if labels else 0
    for c, rus in sorted(by_cl.items()):
        if len(rus) < 2 or not _sung(c):
            continue
        members = sorted((i for ru in rus for i in ru if rec[i] is not None), key=lambda i: rec[i])
        if len(members) < 4:
            continue
        # The widest gap in the word-recurrence values splits new-words from
        # same-words segments.
        gap, cut = max((rec[members[k + 1]] - rec[members[k]], k + 1) for k in range(len(members) - 1))
        lo, hi = members[:cut], members[cut:]
        if (gap < STRUCTURE_WORDS_GAP or len(lo) < 2 or len(hi) < 2
                or rec[lo[-1]] > STRUCTURE_WORDS_NEW_MAX or rec[hi[0]] < STRUCTURE_WORDS_SAME_MIN):
            continue
        if not any((a in lo and b in hi) or (a in hi and b in lo)
                   for ru in rus for a, b in zip(ru, ru[1:])):
            continue
        for i in lo:
            new[i] = nxt
        made.add(nxt)
        nxt += 1
    return new, made


# dev48: two parts that both come back with the same words -- a chorus and its
# pre-chorus. On one arena-rock test scan the pre-chorus (0:59 and
# 1:45, words 85% the same) and the chorus (1:14, 2:02 and 3:19, 75%) tied on words, and the level/register score
# picked the pre-chorus, so the choruses were named Verse and the first one
# merged into the verse after it. A part that every time leads straight into
# another word-repeating part, which comes round more often (here also after
# the solo, with no lead-in) and runs at least as long, is that part's
# pre-chorus, not the chorus. Only between a verse and that part, so an
# opening chorus is never taken for a pre-chorus.
def _sx_drop_lead_ins(top, repeated, units):
    """The chorus candidates without any that are lead-ins to another
    candidate; never empty."""
    def _mean_len(c):
        return float(np.mean([units[k]["len"] for k in repeated[c]]))

    def _leads_into(a, b):
        # Every occurrence of a sits between other sung material (a verse)
        # and a sung occurrence of b -- the pre-chorus position.
        return (len(repeated[b]) > len(repeated[a])
                and _mean_len(b) >= _mean_len(a)
                and all(k + 1 < len(units) and units[k + 1]["cl"] == b and units[k + 1]["sung"]
                        and k >= 1 and units[k - 1]["sung"] and units[k - 1]["cl"] not in (a, b)
                        for k in repeated[a]))

    kept = [a for a in top if not any(b != a and _leads_into(a, b) for b in top)]
    return kept or list(top)


# dev50: lyric timing that has collapsed into a few huge chunks. Whisper
# sometimes returns one "line" covering a minute or two ("one clean-replay test scan": 0:00-1:09
# and 2:06-3:45; "one verse-first pop test scan": 0:00-2:05 and 2:27-3:35), and the line
# matching inside the hook score then compares meaningless blocks.
def _sx_lyric_timing_smeared(segs, bar_edges, F, lyric_chunks):
    """True when at least STRUCTURE_SMEARED_SHARE of the sung time (segments
    with vocal coverage) lies inside lyric chunks STRUCTURE_SMEARED_CHUNK_S
    long or longer."""
    long_spans = []
    for c in lyric_chunks or []:
        if not isinstance(c, dict):
            continue
        try:
            a, b = float(c.get("start")), float(c.get("end"))
        except (TypeError, ValueError):
            continue
        if b - a >= STRUCTURE_SMEARED_CHUNK_S:
            long_spans.append((a, b))
    if not long_spans:
        return False
    voc = F.get("vocal")
    if voc is None or not F.get("has_vocal"):
        return False
    voc = np.asarray(voc, dtype=float)
    sung = smeared = 0.0
    for a_i, b_i in segs:
        if b_i <= a_i or float(np.mean(voc[a_i:b_i])) < STRUCTURE_SUNG_MIN_COVERAGE:
            continue
        t0, t1 = float(bar_edges[a_i]), float(bar_edges[b_i])
        sung += t1 - t0
        ov = sum(max(0.0, min(t1, b) - max(t0, a)) for a, b in long_spans)
        smeared += min(ov, t1 - t0)
    return sung > 0 and smeared / sung >= STRUCTURE_SMEARED_SHARE


_SX_VOCABLES = frozenset(
    "oh ooh oooh ah ahh aah whoa woah wo wooh yeah yeh ya yah la na da doo dum hey ho mm mmm "
    "hmm uh huh ay ayy eh hoo uh-huh ooh-ooh oh-oh na-na la-la".split()
)


def _sx_vocable_only_segments(segs, bar_edges, lyric_chunks):
    """dev56: per segment, True when Whisper heard words in it and every one
    is a vocable ("oh", "na", "yeah"), else False. Each word is placed by
    interpolating across its chunk (as _sx_lyric_ngrams does)."""
    n = len(segs)
    heard = [0] * n
    lexical = [0] * n
    starts = [float(bar_edges[a]) for a, _b in segs]
    ends = [float(bar_edges[b]) for _a, b in segs]
    for c in lyric_chunks or []:
        try:
            t0 = float(c.get("start"))
            t1 = max(float(c.get("end", t0)), t0)
        except Exception:
            continue
        if t0 < 0:
            continue
        words = [w.strip("'-") for w in re.sub(r"[^\w'\- ]+", " ", str(c.get("text") or "").lower()).split()]
        words = [w for w in words if w]
        for k, w in enumerate(words):
            t = t0 + (t1 - t0) * (k + 0.5) / len(words)
            for q in range(n):
                if starts[q] <= t < ends[q]:
                    heard[q] += 1
                    if w not in _SX_VOCABLES:
                        lexical[q] += 1
                    break
    return [heard[q] > 0 and lexical[q] == 0 for q in range(n)], lexical, heard


def _sx_fading_last_chorus(u, prev, units, unit_names, repeated, chorus, lyric_ng, W, loud):
    """dev57: see STRUCTURE_FADING_LAST_CHORUS."""
    _cw = set()
    for k in repeated.get(chorus, []):
        if unit_names[k] == "Chorus":
            for i in units[k]["segs"]:
                _cw |= lyric_ng[i]
    mine = set()
    for i in u["segs"]:
        mine |= lyric_ng[i]
    if not _cw or len(mine) < STRUCTURE_LYRIC_MIN_NGRAMS or len(mine & _cw) < 0.5 * len(mine):
        return False
    # a whole chorus's length, not the last seconds of a fade
    _cl = [units[k]["len"] for k in repeated.get(chorus, []) if unit_names[k] == "Chorus"]
    if not _cl or u["len"] < 0.75 * float(np.median(_cl)):
        return False
    if max(W[i, j] for i in u["segs"] for j in prev["segs"]) < 0.6:
        return False
    l_u = float(np.mean([loud[i] for i in u["segs"]]))
    l_p = float(np.mean([loud[j] for j in prev["segs"]]))
    return l_u <= l_p - float(STRUCTURE_FADING_CHORUS_DB)


def _sx_timed_lyric_patterns(lyric_chunks, vocal_notes=None):
    """dev27: [(time, pattern)] -- the word patterns of _sx_lyric_ngrams
    (neighbouring pairs and skip-pairs, patterns of only common words dropped,
    chunks smeared over more than STRUCTURE_NGRAM_MAX_CHUNK_S of singing
    left out), each with the time it is sung, placed the same way. Pairs of
    vocables ("oh oh") are left out too."""
    out = []
    for c in lyric_chunks or []:
        try:
            t0 = float(c.get("start"))
            t1 = float(c.get("end", t0))
        except Exception:
            continue
        if t0 < 0:
            continue
        if (STRUCTURE_NGRAM_MAX_CHUNK_S and (t1 - t0) > float(STRUCTURE_NGRAM_MAX_CHUNK_S)
                and _sx_voiced_seconds(vocal_notes, t0, t1) > float(STRUCTURE_NGRAM_MAX_CHUNK_S)):
            continue
        txt = re.sub(r"[^\w' ]+", " ", str(c.get("text") or "").lower())
        words = [w for w in txt.split() if w.strip("'")]
        if len(words) < 2:
            continue
        t1 = max(t1, t0)
        place = _sx_sung_time_mapper(vocal_notes, t0, t1)
        ts = [(place((k + 0.5) / len(words)) if place is not None else t0 + (t1 - t0) * (k + 0.5) / len(words))
              for k in range(len(words))]
        for k in range(len(words) - 1):
            for gap in (1, 2):
                if k + gap >= len(words):
                    continue
                w1, w2 = words[k], words[k + gap]
                if w1 in _SX_LYRIC_STOPWORDS and w2 in _SX_LYRIC_STOPWORDS:
                    continue
                if w1 in _SX_VOCABLES and w2 in _SX_VOCABLES:
                    continue
                out.append((0.5 * (ts[k] + ts[k + gap]), (w1, w2) if gap == 1 else (w1, "_", w2)))
    return out


def _sx_prechorus_cuts(segs, names, bars, duration, ev, lyric_chunks, vocal_notes=None):
    """dev27 STRUCTURE_PRECHORUS_BY_WORDS: bar indices where a pre-chorus
    begins inside the verses, found by its words; [] when there is none.

    A pre-chorus is the part at the END of a verse, leading into the chorus,
    that sings the same words each time while the verse before it sings new
    ones. For every part named Verse that runs straight into a part named
    Chorus (two or more such verses), the word patterns it shares with the
    other such verses -- leaving out the chorus's own words -- are found;
    when they are packed at the verse's end (from some point on at least
    STRUCTURE_PRECHORUS_TAIL_SHARE of its patterns are shared, at least
    STRUCTURE_LYRIC_MIN_NGRAMS of them, and before it at most
    STRUCTURE_PRECHORUS_HEAD_SHARE), that point is where the pre-chorus starts,
    on the nearest bar line (an existing section line within a bar wins; else
    the best-evidenced bar). The pre-chorus lasts 8 to
    STRUCTURE_PRECHORUS_MAX_S seconds, the verse keeps at least the minimum
    section length, and at least two verses must show it with words they share
    with each other's pre-chorus. A verse whose words all come back (a repeated
    verse), or none of them, shows no such pattern, so nothing changes."""
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    nb = len(bars)
    bar_len = float(np.median(np.diff(edges))) if len(edges) > 2 else 2.0
    minb = int(STRUCTURE_MIN_SECTION_BARS) * (2 if bar_len < 1.6 else 1)
    units = []
    for i, nm in enumerate(names):
        if units and units[-1][0] == nm:
            units[-1][1].append(i)
        else:
            units.append([nm, [i]])
    vb = []
    for k, (nm, ix) in enumerate(units):
        if nm == "Verse" and k + 1 < len(units) and units[k + 1][0] == "Chorus":
            vb.append((segs[ix[0]][0], segs[ix[-1]][1]))
    if len(vb) < 2:
        return []
    tp = _sx_timed_lyric_patterns(lyric_chunks, vocal_notes)
    if not tp:
        return []
    ch_sp = [(float(edges[segs[ix[0]][0]]), float(edges[segs[ix[-1]][1]])) for nm, ix in units if nm == "Chorus"]
    ch_words = set(p for t, p in tp if any(a <= t < b for a, b in ch_sp))
    span = [(float(edges[a]), float(edges[b])) for a, b in vb]
    pats = [[(t, p) for t, p in tp if a <= t < b and p not in ch_words] for a, b in span]
    seg_starts = set(int(a) for a, _b in segs)

    def _cut_at(i, t):
        # the bar the line starts on: an existing section line within a
        # bar of it, else the best-evidenced bar within a bar; None when the
        # pre-chorus or the verse left before it would be too short or long
        a_b, b_b = vb[i]
        near = [k for k in range(a_b + 1, b_b) if abs(edges[k] - t) <= 1.25 * bar_len]
        old = [k for k in range(a_b + 1, b_b) if k in seg_starts and abs(edges[k] - t) <= 1.5 * bar_len]
        if not near and not old:
            return None
        k = (min(old, key=lambda q: abs(edges[q] - t)) if old
             else max(near, key=lambda q: (float(ev[q]) if ev is not None and q < len(ev) else 0.0,
                                           -abs(edges[q] - t))))
        # never leave a sliver of under two bars beside a section line
        _nbr = [q for q in seg_starts if a_b < q < b_b and q != k and abs(q - k) < 2]
        if _nbr:
            k = min(_nbr, key=lambda q: abs(q - k))
        tail_s, head_s = float(edges[b_b] - edges[k]), float(edges[k] - edges[a_b])
        if (8.0 <= tail_s <= float(STRUCTURE_PRECHORUS_MAX_S) and b_b - k >= minb // 2
                and k - a_b >= minb and head_s >= float(STRUCTURE_MIN_SECTION_S)):
            return k
        return None

    found = {}
    for i, (a_t, b_t) in enumerate(span):
        oth = set(p for j in range(len(span)) if j != i for _t, p in pats[j])
        pts = sorted((t, p in oth, p) for t, p in pats[i])
        for t, sh, _p in pts:
            if not sh:
                continue
            after = [x for x in pts if x[0] >= t]
            before = [x for x in pts if x[0] < t]
            n_sh = sum(1 for x in after if x[1])
            if n_sh < int(STRUCTURE_LYRIC_MIN_NGRAMS):
                break
            fa = n_sh / float(len(after))
            fb = (sum(1 for x in before if x[1]) / float(len(before))) if before else 0.0
            if fa >= float(STRUCTURE_PRECHORUS_TAIL_SHARE) and fb <= float(STRUCTURE_PRECHORUS_HEAD_SHARE):
                k = _cut_at(i, t)
                if k is not None:
                    found[i] = (k, set(x[2] for x in after if x[1]))
                break
    if STRUCTURE_PRECHORUS_PROPAGATE and found and len(found) < len(span):
        # dev37: see STRUCTURE_PRECHORUS_PROPAGATE -- the other verses, by the
        # words of the pre-chorus already found
        pw = set()
        for _k, shp in found.values():
            pw |= shp
        for i in range(len(span)):
            if i in found:
                continue
            pts = sorted((t, p in pw, p) for t, p in pats[i])
            for t, sh, _p in pts:
                if not sh:
                    continue
                after = [x for x in pts if x[0] >= t]
                before = [x for x in pts if x[0] < t]
                n_sh = sum(1 for x in after if x[1])
                if n_sh < int(STRUCTURE_LYRIC_MIN_NGRAMS):
                    break
                fa = n_sh / float(len(after))
                fb = (sum(1 for x in before if x[1]) / float(len(before))) if before else 0.0
                if fa >= float(STRUCTURE_PRECHORUS_TAIL_SHARE) and fb <= float(STRUCTURE_PRECHORUS_HEAD_SHARE):
                    k = _cut_at(i, t)
                    if k is not None:
                        found[i] = (k, set(x[2] for x in after if x[1]))
                    break
    if len(found) < 2:
        return []
    # each pre-chorus shares its words with another one's, not just with a verse
    keep = []
    for i, (k, shp) in found.items():
        others = set()
        for j, (k2, _s2) in found.items():
            if j != i:
                others |= set(p for t, p in pats[j] if t >= float(edges[k2]) - 0.5 * bar_len)
        if len(shp & others) >= 0.6 * len(shp):
            keep.append(k)
    return sorted(keep) if len(keep) >= 2 else []


def _sx_chorus_half(chorus, other, units, repeated, same_words, wmean=None, lyric_ng=None):
    """dev30 STRUCTURE_CHORUS_HALVES: True when `other` and the chorus are the
    two halves of one chorus -- both bring their words back
    (STRUCTURE_CHORUS_HALF_SAME_WORDS), every occurrence of one sits straight
    before (or straight after) an occurrence of the other, every occurrence of
    that other one without its partner next to it is long enough to hold both
    halves (0.8x the shortest pair), and the two halves of a pair are equally
    loud (within a dB) in two thirds of the pairs or more (one stripped-down
    pass, or the song's fading last unit, does not decide). A pre-chorus
    builds up to its chorus: it is quieter, or sung well below it
    (STRUCTURE_CHORUS_HALF_PRECHORUS_ST semitones or more lower, by the
    median vocal pitch), and is not a half. Returns the half sung first
    (a cluster id), or False. With `lyric_ng`, every worded
    occurrence of each half must sing words another occurrence of it sings
    (half of its word patterns or more): a verse that only picks up its
    pre-chorus lines in some passes is not a chorus half. `wmean` is unused."""
    if other is None or chorus is None or other not in repeated or chorus not in repeated:
        return False
    mn = float(STRUCTURE_CHORUS_HALF_SAME_WORDS)
    if same_words.get(other, 0.0) < mn or same_words.get(chorus, 0.0) < mn:
        return False
    if lyric_ng is not None:
        # every worded occurrence of each half sings words another occurrence
        # of it sings (half of its patterns or more) -- not only most of them
        for c in (chorus, other):
            occ_sets = []
            for k in repeated[c]:
                ss = set()
                for i in units[k]["segs"]:
                    if i < len(lyric_ng):
                        ss |= lyric_ng[i]
                if len(ss) >= STRUCTURE_LYRIC_MIN_NGRAMS:
                    occ_sets.append(ss)
            if len(occ_sets) < 2:
                return False
            for q, a_ in enumerate(occ_sets):
                if max(_sx_lyric_overlap(a_, b_)[0] for r_, b_ in enumerate(occ_sets) if r_ != q) < 0.5:
                    return False
    for x, y in ((other, chorus), (chorus, other)):
        occ, ch = repeated[x], set(repeated[y])
        if len(occ) < 2:
            continue
        for step in (1, -1):
            if not all(k + step in ch for k in occ):
                continue
            pair = [units[k]["len"] + units[k + step]["len"] for k in occ]
            partner = set(k + step for k in occ)
            if any(k not in partner and units[k]["len"] < 0.8 * min(pair) for k in ch):
                continue
            last = len(units) - 1
            judged = [k for k in occ if k != last and k + step != last]
            if not judged:
                continue
            level = sum(1 for k in judged
                        if not (np.isnan(units[k]["loud"]) or np.isnan(units[k + step]["loud"]))
                        and abs(units[k]["loud"] - units[k + step]["loud"]) <= 1.0)
            if level < (2.0 / 3.0) * len(judged):
                continue
            first, second = (x, y) if step == 1 else (y, x)
            vf = [units[k]["vp"] for k in repeated[first] if not np.isnan(units[k]["vp"])]
            vs = [units[k]["vp"] for k in repeated[second] if not np.isnan(units[k]["vp"])]
            if (vf and vs and float(np.median(vf))
                    <= float(np.median(vs)) - float(STRUCTURE_CHORUS_HALF_PRECHORUS_ST)):
                return False     # sung well below the part it leads into: a pre-chorus
            return first         # the half sung first
    return False


def _sx_vocal_notes_of(stem_notes):
    """The vocal stem's note events from `stem_notes`, or None."""
    for _key in ("vocals", "vocal", "voice"):
        if stem_notes and stem_notes.get(_key):
            return stem_notes[_key]
    return None


def _sx_names_kept(segs, names, segs2, names2):
    """dev30 STRUCTURE_PRECHORUS_KEEPS_NAMES: True when every segment of the
    re-cut map (segs2 / names2) other than a Pre-Chorus carries the name the
    first map gave the bars it covers (by the segment's middle bar)."""
    for (a, b), nm in zip(segs2, names2):
        if nm == "Pre-Chorus":
            continue
        mid = (a + b) // 2 if b - a > 1 else a
        old = None
        for (a0, b0), nm0 in zip(segs, names):
            if a0 <= mid < b0:
                old = nm0
                break
        if old is not None and old != nm:
            return False
    return True


def _sx_inherit_names(segs, names, labels, info, segs2, cut_bars):
    """dev30 STRUCTURE_PRECHORUS_KEEPS_NAMES: the re-cut segments (segs2)
    named and grouped as the first map named the bars they start in, with the
    pre-chorus stretches marked (_sx_mark_prechorus); (names, labels, info),
    or (None, None, None) when no pre-chorus is marked that way."""
    n2, l2 = [], {}
    for j, (a, _b) in enumerate(segs2):
        i = next((q for q, (a0, b0) in enumerate(segs) if a0 <= a < b0), None)
        if i is None:
            return None, None, None
        n2.append(names[i])
        if i in labels:
            l2[j] = labels[i]
    n3, l3 = _sx_mark_prechorus(segs2, n2, l2, cut_bars)
    if "Pre-Chorus" not in [x for x, y in zip(n3, n2) if x != y]:
        return None, None, None
    info2 = dict(info or {})
    if info2.get("keep_split"):
        st = {int(a): j for j, (a, _b) in enumerate(segs2)}
        info2["keep_split"] = set(st[int(segs[i][0])] for i in info2["keep_split"]
                                  if 0 <= i < len(segs) and int(segs[i][0]) in st)
    return n3, l3, info2


def _sx_prechorus_cuts_buildup(segs, names, bars, duration, F, ev=None):
    """dev35 STRUCTURE_PRECHORUS_BUILDUP_CUTS: bar indices where a pre-chorus
    begins inside the verses, found by the music building up to the chorus:
    for each part named Verse that runs straight into a part named Chorus,
    the bar from which the voice sings STRUCTURE_PRECHORUS_BUILDUP_ST
    semitones or more higher (median pitch) than before it and the drums play
    more, leaving 8 s to STRUCTURE_PRECHORUS_MAX_S for the pre-chorus and the
    minimum section length for the verse. The cut must show in two or more
    such verses, with pre-chorus lengths within a third of each other (a
    pre-chorus comes back the same length); [] otherwise."""
    if not F or F.get("vpitch") is None or not F.get("has_stems"):
        return []
    vp = np.asarray(F["vpitch"], dtype=float)
    dr = np.asarray(F["drums"], dtype=float)
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    bar_len = float(np.median(np.diff(edges))) if len(edges) > 2 else 2.0
    minb = int(STRUCTURE_MIN_SECTION_BARS) * (2 if bar_len < 1.6 else 1)
    seg_starts = set(int(a) for a, _b in segs)
    units = []
    for i, nm in enumerate(names):
        if units and units[-1][0] == nm:
            units[-1][1].append(i)
        else:
            units.append([nm, [i]])
    found = []
    for k, (nm, ix) in enumerate(units):
        if nm != "Verse" or k + 1 >= len(units) or units[k + 1][0] != "Chorus":
            continue
        a_b, b_b = segs[ix[0]][0], segs[ix[-1]][1]
        best = None
        for q in range(a_b + minb, b_b - max(1, minb // 2) + 1):
            tail_s, head_s = float(edges[b_b] - edges[q]), float(edges[q] - edges[a_b])
            if not (8.0 <= tail_s <= float(STRUCTURE_PRECHORUS_MAX_S)) or head_s < float(STRUCTURE_MIN_SECTION_S):
                continue
            h, t = vp[a_b:q], vp[q:b_b]
            h, t = h[~np.isnan(h)], t[~np.isnan(t)]
            if h.size < 2 or t.size < 2:
                continue
            rise = float(np.median(t) - np.median(h))
            if rise < float(STRUCTURE_PRECHORUS_BUILDUP_ST):
                continue
            if not (float(np.nanmean(dr[q:b_b])) > float(np.nanmean(dr[a_b:q]))):
                continue
            score = rise + (0.5 if q in seg_starts else 0.0)
            if best is None or score > best[0]:
                best = (score, q, tail_s)
        if best is not None:
            found.append((best[1], best[2]))
    if len(found) < 2:
        return []
    ls = [t for _q, t in found]
    if max(ls) > (4.0 / 3.0) * min(ls):
        return []
    return sorted(q for q, _t in found)


def _sx_mark_prechorus(segs, names, labels, cut_bars):
    """dev27: name the segments from each pre-chorus line up to the chorus
    Pre-Chorus, as one material of their own; (names, labels). A line whose
    stretch no longer leads straight into a Chorus is left as named."""
    names, labels = list(names), dict(labels)
    nxt = (max(labels.values()) + 1) if labels else 0
    cuts = set(int(k) for k in cut_bars)
    marked = False
    for i, (a, _b) in enumerate(segs):
        if a not in cuts or names[i] != "Verse":
            continue
        j = i
        while j + 1 < len(segs) and names[j + 1] == "Verse":
            j += 1
        if j + 1 < len(segs) and names[j + 1] == "Chorus":
            for q in range(i, j + 1):
                names[q] = "Pre-Chorus"
                labels[q] = nxt
            marked = True
    return names, labels


def _sx_eject_unshared_words(body, labels, lyric_ng, sung):
    """dev28 STRUCTURE_EJECT_UNSHARED_WORDS: in a group whose occurrences sing
    each other's words (two or more of them sharing half their word patterns
    or more -- a chorus), a sung occurrence between the first and the last
    that sings two lines or so of words (2 x STRUCTURE_LYRIC_MIN_NGRAMS
    patterns) of which almost none (STRUCTURE_UNSHARED_WORDS_MAX) come back
    from the group's other occurrences is not another chorus but a part of
    its own (a bridge over the chorus's chords); its neighbours' words, which
    Whisper can smear across the line between them, are not counted."""
    mn = int(STRUCTURE_LYRIC_MIN_NGRAMS)
    groups = {}
    for i in body:
        groups.setdefault(labels[i], []).append(i)
    new = dict(labels)
    nxt = (max(labels.values()) + 1) if labels else 0
    for _l, mem in sorted(groups.items()):
        mem = sorted(mem)
        worded = [j for j in mem if j < len(lyric_ng) and len(lyric_ng[j]) >= mn]
        if len(worded) < 3:
            continue
        for i in mem[1:-1]:
            if not sung[i] or i >= len(lyric_ng) or len(lyric_ng[i]) < 2 * mn:
                continue
            rest = [j for j in worded if j != i]
            # the rest must repeat their own words (a chorus)
            rep = [(a, b) for k, a in enumerate(rest) for b in rest[k + 1:]
                   if _sx_lyric_overlap(lyric_ng[a], lyric_ng[b])[0] >= 0.5]
            if not rep:
                continue
            far = [j for j in rest if abs(j - i) > 1]
            if not far:
                continue
            gw = set()
            for j in far:
                gw |= lyric_ng[j]
            if len(lyric_ng[i] & gw) <= float(STRUCTURE_UNSHARED_WORDS_MAX) * len(lyric_ng[i]):
                new[i] = nxt
                nxt += 1
    return new


def _sx_key_change(F, bars, duration):
    """dev28 STRUCTURE_KEY_CHANGE_ALIGN: (bar index, semitones) of a key
    change -- the song moving up or down a semitone or more for its last part
    (a final chorus "up a key") -- or None. Found from the bar chroma: the
    average chroma after some bar line in the song's second half is the
    average before it shifted by k semitones (correlation
    STRUCTURE_KEY_CHANGE_MIN_CORR or more, unshifted at most
    STRUCTURE_KEY_CHANGE_MAX_UNSHIFTED, the shift gaining
    STRUCTURE_KEY_CHANGE_MIN_GAIN), with at least STRUCTURE_KEY_CHANGE_MIN_TAIL_S
    of music after it."""
    C = np.asarray(F.get("chroma"), dtype=float)
    if C.ndim != 2 or C.shape[0] != 12:
        return None
    nb = C.shape[1]
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    if nb < 24:
        return None

    def _c(a, b):
        if np.std(a) < 1e-9 or np.std(b) < 1e-9:
            return 0.0
        return float(np.corrcoef(a, b)[0, 1])
    best = None
    for c in range(int(0.4 * nb), nb - 8):
        if float(edges[-1] - edges[c]) < float(STRUCTURE_KEY_CHANGE_MIN_TAIL_S):
            break
        pre, post = C[:, :c].mean(axis=1), C[:, c:].mean(axis=1)
        c0 = _c(pre, post)
        for k in (1, 2, 3, 4, -1, -2):
            ck = _c(np.roll(pre, k), post)
            if best is None or ck - c0 > best[0]:
                best = (ck - c0, c, k, c0, ck)
    if best is None:
        return None
    gain, c, k, c0, ck = best
    if (gain >= float(STRUCTURE_KEY_CHANGE_MIN_GAIN) and ck >= float(STRUCTURE_KEY_CHANGE_MIN_CORR)
            and c0 <= float(STRUCTURE_KEY_CHANGE_MAX_UNSHIFTED)):
        return int(c), int(k)
    return None


def _sx_reassign_by_words(W, body, labels, lyric_ng, sung):
    """dev26 STRUCTURE_REASSIGN_BY_WORDS: a sung segment clustered with one
    material, that SOUNDS like another recurring material just as well
    (median similarity STRUCTURE_REASSIGN_SIM or more to its occurrences) and
    SINGS that material's words (at least STRUCTURE_LYRIC_CHORUS_SHARE of its
    word patterns, median over that material's worded occurrences, two or
    more of them), while sharing few words with its own cluster, is moved to
    that material. Over a one-loop backing a chorus can measure as close to
    the verses as to the other choruses; its words tell which it is. One
    pass over the clustering as it stands, so moves cannot cascade."""
    mn = int(STRUCTURE_LYRIC_MIN_NGRAMS)
    new = dict(labels)
    by_c = {}
    for j in body:
        by_c.setdefault(labels[j], []).append(j)
    for i in body:
        if not sung[i] or i >= len(lyric_ng) or len(lyric_ng[i]) < mn:
            continue
        mine = lyric_ng[i]
        own = [j for j in by_c.get(labels[i], []) if j != i and len(lyric_ng[j]) >= mn]
        own_w = max([len(mine & lyric_ng[j]) / float(len(mine)) for j in own], default=0.0)
        if own_w >= STRUCTURE_REASSIGN_OWN_MAX:
            continue
        best = None
        for c, mem in by_c.items():
            if c == labels[i]:
                continue
            worded = [j for j in mem if j != i and len(lyric_ng[j]) >= mn]
            if len(worded) < 2:
                continue
            ww = float(np.median([len(mine & lyric_ng[j]) / float(len(mine)) for j in worded]))
            sd = float(np.median([W[i, j] for j in mem if j != i]))
            if ww >= STRUCTURE_LYRIC_CHORUS_SHARE and sd >= STRUCTURE_REASSIGN_SIM:
                if best is None or (ww, sd) > best[0]:
                    best = ((ww, sd), c)
        if best is not None:
            new[i] = best[1]
    return new


def _sx_split_by_known_parts(F, bars, duration, starts, lyric_chunks=None, vocal_notes=None):
    """dev26 STRUCTURE_SPLIT_BY_KNOWN_PARTS: section lines the boundary
    search missed because nothing changed in the sound at that point, found
    by repetition instead. A long segment is cut at the bar where
      (A) one side is a near-repeat (STRUCTURE_KNOWN_PART_SIM or more) of
          another segment of about the same length (0.7x to
          STRUCTURE_KNOWN_PART_MAX_RATIO, and no more than 40 s), and the other
          side does not sound like that segment at all
          (STRUCTURE_KNOWN_PART_OTHER_MAX or less) -- a chorus running
          straight into the bridge or outro over the same beat; or
      (B) the two sides are each a near-repeat of two DIFFERENT segments
          (each side clearly closer to its own match than to the other's) --
          a verse and pre-chorus heard separately elsewhere, joined here.
    Each segment is cut at most once, both pieces keep the minimum section
    length, and the measured boundaries are never moved or removed."""
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    nbars = len(bars)
    cuts = [0] + sorted(int(k) for k in starts) + [nbars]
    segs = [(cuts[k], cuts[k + 1]) for k in range(len(cuts) - 1) if cuts[k + 1] > cuts[k]]
    if len(segs) < 4:
        return starts
    bar_len = float(np.median(np.diff(edges))) if len(edges) > 2 else 2.0
    minb = int(STRUCTURE_MIN_SECTION_BARS) * (2 if bar_len < 1.6 else 1)
    min_s = max(float(STRUCTURE_MIN_SECTION_S), 8.0)
    hi, lo = float(STRUCTURE_KNOWN_PART_SIM), float(STRUCTURE_KNOWN_PART_OTHER_MAX)
    new_cuts = []
    for si, (a, b) in enumerate(segs):
        if b - a < 2 * minb or edges[b] - edges[a] < 2 * min_s:
            continue
        others = [x for k, x in enumerate(segs) if k != si]
        best = None
        for c in range(a + minb, b - minb + 1):
            if edges[c] - edges[a] < min_s or edges[b] - edges[c] < min_s:
                continue
            if STRUCTURE_KNOWN_PART_NOT_HALVES and 2 * c == a + b:
                continue          # dev37: two equal halves -- one part repeating its phrase
            P = [(a, c), (c, b)] + others
            Wm = _sx_segment_similarity(F, P)
            pl = [c - a, b - c]
            # (A) one side repeats a segment the other side does not resemble
            for pi, qi in ((0, 1), (1, 0)):
                for xi in range(2, len(P)):
                    xl = P[xi][1] - P[xi][0]
                    if not (0.7 <= xl / float(pl[pi]) <= float(STRUCTURE_KNOWN_PART_MAX_RATIO)):
                        continue
                    if edges[P[xi][1]] - edges[P[xi][0]] > 40.0:
                        continue          # a 40 s+ match is likely two parts itself
                    m, o = float(Wm[pi, xi]), float(Wm[qi, xi])
                    if m >= hi and o <= lo:
                        sc = m - o
                        if best is None or sc > best[0]:
                            best = (sc, c, P[qi], P[xi], qi)
            # (B) each side repeats its own, different segment
            xl_ = [xi for xi in range(2, len(P)) if 0.7 <= (P[xi][1] - P[xi][0]) / float(pl[0]) <= 1.45]
            xr_ = [xi for xi in range(2, len(P)) if 0.7 <= (P[xi][1] - P[xi][0]) / float(pl[1]) <= 1.45]
            if xl_ and xr_:
                xl = max(xl_, key=lambda x: Wm[0, x])
                xr = max(xr_, key=lambda x: Wm[1, x])
                if (xl != xr and Wm[0, xl] >= hi and Wm[1, xr] >= hi
                        and Wm[0, xl] - Wm[0, xr] >= 0.15 and Wm[1, xr] - Wm[1, xl] >= 0.15):
                    sc = float(min(Wm[0, xl] - Wm[0, xr], Wm[1, xr] - Wm[1, xl]))
                    if best is None or sc > best[0]:
                        best = (sc, c, None, None, None)
        if best is not None and best[2] is not None and STRUCTURE_KNOWN_PART_WORDS_VETO and lyric_chunks:
            # dev30: see STRUCTURE_KNOWN_PART_WORDS_VETO.
            try:
                _left, _x, _qi = best[2], best[3], best[4]
                _xi = segs.index(_x)
                _ni = _xi - 1 if _qi == 0 else _xi + 1
                if 0 <= _ni < len(segs):
                    _ng = _sx_lyric_ngrams([_left, segs[_ni]], edges, lyric_chunks, vocal_notes)
                    _sh = len(_ng[0] & _ng[1])
                    _dl = float(edges[_left[1]] - edges[_left[0]])
                    _dn = float(edges[segs[_ni][1]] - edges[segs[_ni][0]])
                    if (len(_ng[0]) >= 2 and _sh >= 0.5 * len(_ng[0]) and _sh < 0.3 * len(_ng[1])
                            and _dn >= 2.0 * _dl):
                        best = None
            except Exception:
                pass
        if best is not None:
            new_cuts.append(best[1])
    if not new_cuts:
        return starts
    return sorted(set(int(k) for k in starts) | set(new_cuts))


def _sx_eject_outliers(W, body, labels, lyric_ng, sung):
    """dev26 STRUCTURE_EJECT_OUTLIER: one sung segment grouped with a part
    of four or more segments, heard between that part's other occurrences,
    that is clearly less alike than they are with each other (its best match
    in the group STRUCTURE_OUTLIER_MARGIN or more below their median, and
    under STRUCTURE_OUTLIER_MAX_SIM) and repeats few of their words, becomes
    material of its own -- a bridge or breakdown over the chorus's chords
    (average linkage had pulled it in). The first and last occurrence are
    left alone (a stripped-down first or last chorus), as is anything whose
    words come back from the group."""
    mn = int(STRUCTURE_LYRIC_MIN_NGRAMS)
    groups = {}
    for i in body:
        groups.setdefault(labels[i], []).append(i)
    new = dict(labels)
    nxt = (max(labels.values()) + 1) if labels else 0
    for _l, mem in sorted(groups.items()):
        mem = sorted(mem)
        if len(mem) < 4:
            continue
        for i in mem[1:-1]:
            if not sung[i]:
                continue
            rest = [j for j in mem if j != i]
            inner = [W[a, b] for a in rest for b in rest if a < b]
            if not inner:
                continue
            med = float(np.median(inner))
            best = max(float(W[i, j]) for j in rest)
            if best >= STRUCTURE_OUTLIER_MAX_SIM or best > med - STRUCTURE_OUTLIER_MARGIN:
                continue
            if lyric_ng and i < len(lyric_ng) and len(lyric_ng[i]) >= mn:
                gw = set()
                for j in rest:
                    if abs(j - i) > 1:
                        gw |= lyric_ng[j]
                if len(lyric_ng[i] & gw) >= 0.5 * len(lyric_ng[i]):
                    continue
            new[i] = nxt
            nxt += 1
    return new


def _sx_matches_chorus_occurrence(words, occurrences, distinct_verse=False):
    """Prefer a single chorus match; reject pooled-only matches only when
    independent acoustic evidence supports a distinct verse. Missing or
    inconsistent lyrics alone must not demote a genuine chorus.
    """
    if len(words) < STRUCTURE_LYRIC_MIN_NGRAMS:
        return False
    if any(len(words & other) >= STRUCTURE_LYRIC_CHORUS_SHARE * len(words)
           for other in occurrences if len(other) >= STRUCTURE_LYRIC_MIN_NGRAMS):
        return True
    # Inconsistent Whisper renditions are not negative evidence by themselves.
    # Retain the pre-v6 pooled fallback unless the audio independently supports verse.
    pooled = set().union(*occurrences) if occurrences else set()
    return not distinct_verse and len(words & pooled) >= STRUCTURE_LYRIC_CHORUS_SHARE * len(words)


def _sx_name_sections(F, bars, duration, segs, W, lyric_sig=None, lyric_rep=None,
                      vocal_known=True, instrumental=False, lyric_ng=None, lyric_smeared=False,
                      info_out=None, vocable_only=None, sheet_intro=False, lone_sung_verse=True,
                      title_hits=None):
    """Assign musical-function names to segments.

    Returns (names, labels, coverage): a base name per segment, the cluster
    label per body segment, and per-segment vocal coverage (or None).

    Repetition is counted in RUNS: consecutive segments of the same material
    are one occurrence (a section the boundary search happened to split), so
    only material that comes back after something else counts as recurring.
    Nothing here assumes verse-before-chorus: the chorus is the recurring
    sung material with the strongest hook evidence, wherever it first occurs.
    """
    n = len(segs)
    bar_edges = np.concatenate([np.asarray(bars, dtype=float), [duration]])
    lens = [float(bar_edges[b] - bar_edges[a]) for a, b in segs]
    loud = np.array([float(np.mean(F["loud"][a:b])) for a, b in segs])
    has_v = bool(F.get("has_vocal")) and vocal_known and not instrumental
    if has_v:
        cov = np.array([float(np.mean(F["vocal"][a:b])) for a, b in segs])
        sung = cov >= STRUCTURE_SUNG_MIN_COVERAGE
        vp_bars = np.asarray(F["vpitch"], dtype=float)
    else:
        cov = None
        sung = np.zeros(n, dtype=bool) if instrumental else np.ones(n, dtype=bool)
        vp_bars = None
    names = [None] * n

    # ---- Bookends ------------------------------------------------------
    if has_v:
        sung_idx = [i for i in range(n) if sung[i]]
        if sung_idx and STRUCTURE_SUNG_INTRO and len(sung_idx) >= 4:
            # dev55: see STRUCTURE_SUNG_INTRO.
            _sl = [loud[i] for i in sung_idx]
            _ref_loud = float(np.median(_sl))
            _dr = None
            if F.get("has_stems"):
                _dv = [float(np.mean(F["drums"][segs[i][0]:segs[i][1]])) for i in sung_idx]
                _dr = float(np.median(_dv))
            k = 0
            while k < n - 3:
                if not sung[k]:
                    k += 1
                    continue
                short_stub = (lens[k] < STRUCTURE_SHORT_LEAD_S and k + 1 < n and not sung[k + 1])
                quiet_open = (lens[k] <= STRUCTURE_SUNG_INTRO_MAX_S
                              and loud[k] <= _ref_loud - STRUCTURE_SUNG_INTRO_QUIETER_DB
                              and (_dr is None or float(np.mean(F["drums"][segs[k][0]:segs[k][1]]))
                                   <= 0.5 * _dr))
                if (quiet_open and STRUCTURE_SUNG_INTRO_NEEDS_NO_WORDS and lyric_ng
                        and k < len(lyric_ng) and len(lyric_ng[k]) >= STRUCTURE_LYRIC_MIN_NGRAMS):
                    # dev26: it sings real lines -- a soft first verse (or a
                    # chorus sung softly first), not an intro.
                    quiet_open = False
                    if STRUCTURE_SUNG_INTRO_TAG_OR_SPEECH:
                        # dev30: see the setting -- still the intro when it
                        # repeats one short line, is a quiet spoken prelude
                        # before the band, or the lyric sheet opens with Intro
                        _wd = set(w_ for p_ in lyric_ng[k] for w_ in p_ if w_ != "_")
                        if (len(_wd) < int(STRUCTURE_SUNG_INTRO_MIN_WORDS)
                                or (loud[k] <= _ref_loud - float(STRUCTURE_SPOKEN_PRELUDE_DB)
                                    and k + 1 < n and not sung[k + 1])
                                or (sheet_intro and k == sung_idx[0])):
                            quiet_open = True
                # dev56: see STRUCTURE_VOCABLE_INTRO.
                vocable_open = bool(STRUCTURE_VOCABLE_INTRO and vocable_only is not None
                                    and k < len(vocable_only) and vocable_only[k]
                                    and lens[k] <= STRUCTURE_SUNG_INTRO_MAX_S
                                    and loud[k] <= _ref_loud - STRUCTURE_VOCABLE_INTRO_QUIETER_DB)
                if not (short_stub or quiet_open or vocable_open):
                    break
                sung[k] = False
                k += 1
            sung_idx = [i for i in range(n) if sung[i]]
        if sung_idx:
            for i in range(0, sung_idx[0]):
                names[i] = "Intro"
            for i in range(sung_idx[-1] + 1, n):
                names[i] = "Outro"
    else:
        med_loud = float(np.median(loud)) if n else 0.0
        if n >= 3 and lens[0] <= STRUCTURE_INTRO_MAX_S and loud[0] <= med_loud - 1.5:
            names[0] = "Intro"
        if n >= 3 and lens[-1] <= STRUCTURE_OUTRO_MAX_S and loud[-1] <= med_loud - 1.5:
            names[-1] = "Outro"

    body = [i for i in range(n) if names[i] is None]
    labels = _sx_cluster(W, body) if body else {}
    _new_words_labels = set()
    if (STRUCTURE_SPLIT_BY_COHESION and lyric_ng and has_v and not instrumental and labels
            and cov is not None):
        labels, _new_words_labels = _sx_split_by_cohesion(W, body, labels, lyric_ng, cov)
    if STRUCTURE_LONE_SUNG_REGROUP and has_v and not instrumental and labels and cov is not None:
        labels = _sx_regroup_lone_sung(W, labels, cov, lyric_ng)
    if STRUCTURE_SPLIT_SHARED_MUSIC and lyric_ng and has_v and not instrumental and labels:
        labels, _nw45 = _sx_split_shared_music_by_words(labels, body, lyric_ng, sung)
        _new_words_labels = set(_new_words_labels) | set(_nw45)

    if STRUCTURE_EJECT_OUTLIER and has_v and not instrumental and labels:
        try:
            labels = _sx_eject_outliers(W, body, labels, lyric_ng, sung)
        except Exception:
            pass
    if STRUCTURE_EJECT_UNSHARED_WORDS and lyric_ng and has_v and not instrumental and labels:
        try:
            labels = _sx_eject_unshared_words(body, labels, lyric_ng, sung)
        except Exception:
            pass
    if STRUCTURE_REASSIGN_BY_WORDS and lyric_ng and has_v and not instrumental and labels:
        try:
            labels = _sx_reassign_by_words(W, body, labels, lyric_ng, sung)
        except Exception:
            pass

    # ---- Runs of identical material --------------------------------------
    units = []   # each: dict(segs=[...], cl=label)
    for i in body:
        if (units and units[-1]["segs"][-1] == i - 1 and units[-1]["cl"] == labels[i]
                and not (STRUCTURE_RUNS_SPLIT_BY_VOICE and has_v
                         and bool(sung[i]) != bool(sung[i - 1]))):
            units[-1]["segs"].append(i)
        else:
            units.append({"segs": [i], "cl": labels[i]})
    for u in units:
        idx = u["segs"]
        a0, b1 = segs[idx[0]][0], segs[idx[-1]][1]
        u["len"] = sum(lens[i] for i in idx)
        u["loud"] = float(np.mean(F["loud"][a0:b1]))
        if vp_bars is not None:
            v = vp_bars[a0:b1]
            v = v[~np.isnan(v)]
            u["vp"] = float(np.median(v)) if v.size else np.nan
        else:
            u["vp"] = np.nan
        u["sung"] = float(np.mean([sung[i] for i in idx])) >= 0.5
        if F.get("has_stems"):
            u["dens"] = float(np.mean(F["drums"][a0:b1]))
        else:
            u["dens"] = np.nan
        reps = [lyric_rep[i] for i in idx if lyric_rep and lyric_rep[i] is not None]
        u["lyr"] = float(np.mean(reps)) if reps else None
    by_cl = {}
    for ui, u in enumerate(units):
        by_cl.setdefault(u["cl"], []).append(ui)
    repeated = {c: us for c, us in by_cl.items() if len(us) >= 2}

    def _z(v, arr):
        arr = np.asarray([a for a in arr if a is not None and not np.isnan(a)], dtype=float)
        if arr.size < 2 or v is None or np.isnan(v):
            return 0.0
        return float((v - arr.mean()) / (arr.std() + 1e-6))

    def _wmean(c, key):
        us = repeated[c]
        vals = [(units[k][key], units[k]["len"]) for k in us
                if units[k][key] is not None and not np.isnan(units[k][key])]
        if not vals:
            return np.nan
        return float(sum(v * w for v, w in vals) / sum(w for _v, w in vals))

    all_loud = [u["loud"] for u in units]
    all_vp = [u["vp"] for u in units]
    all_dens = [u["dens"] for u in units]

    def _hook_score(c, detail=None):
        parts = {
            "loud": STRUCTURE_HOOK_W_LOUD * _z(_wmean(c, "loud"), all_loud),
            "register": STRUCTURE_HOOK_W_REGISTER * _z(_wmean(c, "vp"), all_vp),
            "drums": STRUCTURE_HOOK_W_DRUMS * _z(_wmean(c, "dens"), all_dens),
            "repeats": STRUCTURE_HOOK_W_REPEATS * (len(repeated[c]) - 2),
        }
        lyr = [units[k]["lyr"] for k in repeated[c] if units[k]["lyr"] is not None]
        if lyr and not _hook_ctx["drop_lyrics"]:
            # Repeated words are the defining property of a chorus; when the
            # lyrics were transcribed they outweigh level and register.
            parts["lyrics"] = STRUCTURE_HOOK_W_LYRICS * (float(np.mean(lyr)) - 0.4)
        if detail is not None:
            detail[c] = parts
        return float(sum(parts.values()))

    # dev50: set below when the words decided nothing and their timing is
    # smeared across whole sections (see STRUCTURE_SMEARED_LYRICS_HOOK).
    _hook_ctx = {"drop_lyrics": False}

    sung_rep = [] if instrumental else [
        c for c, us in repeated.items() if np.mean([units[k]["sung"] for k in us]) >= 0.5
    ]

    # How much each recurring part keeps its WORDS from one occurrence to the
    # next (each occurrence against its best-matching other occurrence). A chorus comes back with the
    # same words; a verse comes back with the same music and new words. That
    # is the defining difference between them, so when the lyrics show it
    # clearly it decides -- loudness, register and drums are only clues, and
    # on a song whose chorus is quieter, lower or sparser than its verses
    # (or that opens with a stripped-down chorus) they point the wrong way.
    same_words = {}
    same_words_n = {}   # dev26: fewest word patterns of the occurrences compared
    if lyric_ng and not instrumental:
        for c in sung_rep:
            occ_sets = []
            for k in repeated[c]:
                ss = set()
                for i in units[k]["segs"]:
                    ss |= lyric_ng[i]
                if len(ss) >= STRUCTURE_LYRIC_MIN_NGRAMS:
                    occ_sets.append(ss)
            # Each occurrence's best match with any other occurrence, then
            # the median: one badly transcribed occurrence (misheard, or its
            # words smeared into a neighbour) cannot hide a real chorus.
            best = []
            for x in range(len(occ_sets)):
                others = [_sx_lyric_overlap(occ_sets[x], occ_sets[y_])[0]
                          for y_ in range(len(occ_sets)) if y_ != x]
                if others:
                    best.append(max(others))
            if best:
                same_words[c] = float(np.median(best))
                same_words_n[c] = min(len(x) for x in occ_sets)

    chorus = verse = None
    _wordless_demoted = None  # dev74: see STRUCTURE_WORDS_BEAT_UNWORDED
    _verse_only_last = None   # dev70: last verse unit when the verse is the only recurring sung part
    _tags = set()        # dev46: short word-repeating tags (post-chorus hook lines)
    lyric_hi = []
    lo_vals = [v for c, v in same_words.items()
               if v <= STRUCTURE_LYRIC_SAME_LO or c in _new_words_labels]
    if lo_vals:
        hi_thr = max(STRUCTURE_LYRIC_SAME_HI_MIN, max(lo_vals) + STRUCTURE_LYRIC_SAME_GAP)
        lyric_hi = sorted((c for c in sung_rep if same_words.get(c, -1.0) >= hi_thr),
                          key=lambda c: same_words[c], reverse=True)
    if lyric_hi:
        # The part whose words come back most is the chorus; only when two
        # parts repeat their words about equally (a chorus and a pre-chorus)
        # does the level / register / drums hook score choose between them.
        # A chorus comes round more often than a bridge that repeats its own
        # words: a part heard only in the second half of the song, two or
        # more times fewer than another such part, is not the chorus. (A
        # twice-sung bridge whose two passes were transcribed word-perfect
        # otherwise beat a five-times chorus whose lines Whisper merged and
        # dropped differently each time.) A part that is also heard early --
        # a chorus in a short song next to a hook heard more often -- stays.
        most = max(len(repeated[c]) for c in lyric_hi)

        def _late_and_rarer(c):
            if len(repeated[c]) > most - 2:
                return False
            first = min(float(bar_edges[segs[units[k]["segs"][0]][0]]) for k in repeated[c])
            return first >= STRUCTURE_BRIDGE_MIN_POS * float(duration)

        cands = [c for c in lyric_hi if not (STRUCTURE_LYRIC_CHORUS_CHECKS and _late_and_rarer(c))] or lyric_hi
        if STRUCTURE_PRECHORUS_LEADS_IN and len(cands) >= 2:
            cands = _sx_drop_lead_ins(cands, repeated, units)
        top = [c for c in cands if same_words[c] >= max(same_words[x] for x in cands) - 0.15]
        chorus = max(top, key=_hook_score)
        _tpool = cands if STRUCTURE_TITLE_PICKS_ANY_WORDED else top
        if STRUCTURE_TITLE_PICKS_CHORUS and title_hits and len(_tpool) >= 2:
            # dev32: see STRUCTURE_TITLE_PICKS_CHORUS.
            try:
                def _t_occ(c):
                    return [sum(title_hits[i] for i in units[k]["segs"]) for k in repeated[c]]
                _wt = [c for c in _tpool if all(x > 0 for x in _t_occ(c))]
                _nt = [c for c in _tpool if not any(x > 0 for x in _t_occ(c))]
                def _beside(c, t):
                    return all((k > 0 and units[k - 1]["cl"] == t)
                               or (k + 1 < len(units) and units[k + 1]["cl"] == t)
                               for k in repeated[c])
                # Not when the other part sits next to the title part every
                # time: two halves of one chorus, or a lead-in (left to the
                # checks above and below).
                if (len(_wt) == 1 and len(_nt) == len(_tpool) - 1
                        and not any(_beside(c, _wt[0]) for c in _nt)):
                    chorus = _wt[0]
            except Exception:
                pass
        if STRUCTURE_LEADIN_UNWORDED and STRUCTURE_PRECHORUS_LEADS_IN:
            # dev51: the part it leads into had no measurable words.
            _unworded = [c for c in sung_rep if c != chorus and c not in lyric_hi
                         and c not in same_words and c not in _new_words_labels]
            _led = _sx_drop_lead_ins([chorus] + _unworded, repeated, units)
            if chorus not in _led:
                chorus = max(_led, key=lambda c: (len(repeated[c]), sum(units[k]["len"] for k in repeated[c])))
        rest = [c for c in sung_rep if c != chorus and c not in lyric_hi]
        verse = max(rest, key=lambda c: sum(units[k]["len"] for k in repeated[c])) if rest else None
        if STRUCTURE_CHORUS_HALVES and STRUCTURE_CHORUS_HALVES_WORDED and lyric_ng:
            # dev30: the same for a song whose verses were compared by words.
            for _c2 in [c for c in sung_rep if c not in (chorus, verse) and c in repeated]:
                try:
                    _half = _sx_chorus_half(chorus, _c2, units, repeated, same_words, _wmean, lyric_ng)
                except Exception:
                    _half = False
                if _half is not False:
                    for k in repeated[_c2]:
                        units[k]["cl"] = chorus
                        for i in units[k]["segs"]:
                            labels[i] = chorus
                    repeated[chorus] = sorted(repeated[chorus] + repeated[_c2])
                    del repeated[_c2]
                    sung_rep = [c for c in sung_rep if c != _c2]
                    lyric_hi = [c for c in lyric_hi if c != _c2]
    elif len(sung_rep) >= 2:
        if STRUCTURE_SMEARED_LYRICS_HOOK and lyric_smeared:
            _hook_ctx["drop_lyrics"] = True
        ranked = sorted(sung_rep, key=_hook_score, reverse=True)
        if STRUCTURE_VERSE_BY_WORDS:
            # dev55: a recurring part measured to sing new words every time
            # is a verse, so it cannot be the chorus while another recurring
            # sung part is available (a jangle-pop test track: 6% of the 0:17 / 1:41
            # part's word patterns come back, yet it was louder-sounding by
            # register and was named Chorus).
            _vl = [c for c in ranked if c in same_words and same_words[c] <= STRUCTURE_LYRIC_SAME_LO
                   and not (STRUCTURE_VERSE_BY_WORDS_MIN_NGRAMS
                            and same_words_n.get(c, 0) < STRUCTURE_VERSE_BY_WORDS_MIN_NGRAMS)]
            _ok = [c for c in ranked if c not in _vl]
            if _vl and _ok:
                ranked = _ok + [c for c in ranked if c in _vl]
        if STRUCTURE_WORDS_BEAT_UNWORDED and same_words and ranked[0] not in same_words \
                and all(units[k]["lyr"] is None for k in repeated[ranked[0]]):
            # dev74: the hook score's front-runner has no measurable words, while
            # another recurring sung part brings its words back almost whole
            # (a dance-rock test track: the chorus at 0:00 and 2:25 repeats 92%
            # of its words, yet a 9-second title-line tail with no transcribed
            # words won on register and was named Chorus, the real chorus
            # Verse 1).
            _wc = [c for c in ranked if same_words.get(c, -1.0) >= float(STRUCTURE_WORDS_BEAT_UNWORDED_MIN)]
            if _wc:
                _wordless_demoted = ranked[0]
                ranked = [_wc[0]] + [c for c in ranked if c != _wc[0]]
        chorus = ranked[0]
        verse = max(ranked[1:], key=lambda c: sum(units[k]["len"] for k in repeated[c]))
        if STRUCTURE_CHORUS_HALVES and lyric_ng:
            # dev30: see STRUCTURE_CHORUS_HALVES.
            try:
                _half = _sx_chorus_half(chorus, verse, units, repeated, same_words, _wmean, lyric_ng)
            except Exception:
                _half = False
            if _half is not False:
                for k in repeated[verse]:
                    units[k]["cl"] = chorus
                    for i in units[k]["segs"]:
                        labels[i] = chorus
                repeated[chorus] = sorted(repeated[chorus] + repeated[verse])
                del repeated[verse]
                sung_rep = [c for c in sung_rep if c != verse]
                _rest = [c for c in ranked[1:] if c in repeated and c != chorus]
                verse = (max(_rest, key=lambda c: sum(units[k]["len"] for k in repeated[c]))
                         if _rest else None)
    elif len(sung_rep) == 1:
        c = sung_rep[0]
        if STRUCTURE_ONLY_RECURRING_IS_CHORUS and STRUCTURE_SMEARED_LYRICS_HOOK and lyric_smeared:
            _hook_ctx["drop_lyrics"] = True     # dev55: as for two or more parts
        lyr = [units[k]["lyr"] for k in repeated[c] if units[k]["lyr"] is not None]
        others_sung = [u for u in units if u["cl"] != c and u["sung"]]
        if (STRUCTURE_ONLY_RECURRING_NEW_WORDS_IS_VERSE and c in same_words
                and same_words[c] < float(STRUCTURE_ONLY_RECURRING_VERSE_MAX_SAME)):
            # dev70: the only recurring sung part sings mostly NEW words each
            # time it comes round, so it is the verse, even if some of its
            # lines (a refrain) repeat. ("a rock test track": 30-38% of the words
            # come back, the rest are new; a chorus comes back with most of
            # its words.)
            verse = c
            _verse_only_last = max(repeated[c])
        elif lyr and float(np.mean(lyr)) >= 0.5:
            chorus = c
        elif others_sung and _hook_score(c) > 0.6:
            # Recurring, louder/higher than the one-off sung parts around it.
            chorus = c
        elif (STRUCTURE_ONLY_RECURRING_IS_CHORUS and others_sung and len(repeated[c]) >= 3
              and _hook_score(c) > 0.0):
            # dev55: the only sung material that comes back, three or more
            # times and at least as loud/high as the rest, is the chorus (the
            # verses were each measured as their own material).
            chorus = c
        else:
            verse = c

    if ((STRUCTURE_CHORUS_PREFERS_LONGER or STRUCTURE_CHORUS_WORDS_FALLBACK)
            and lyric_ng and chorus is not None
            and not instrumental and repeated):
        chorus, verse, _tags = _sx_chorus_over_tags(
            chorus, verse, units, repeated, sung_rep, lyric_ng,
            [c for c in sung_rep if STRUCTURE_LYRIC_CHORUS_CHECKS and lyric_hi
             and c in lyric_hi and _late_and_rarer(c)],
            by_hook=not lyric_hi)
    def _distinct_verse_audio(ui):
        if verse is None or chorus is None:
            return False
        vs = [k for k in repeated.get(verse, []) if k != ui]
        cs = list(repeated.get(chorus, []))
        if len(vs) < 2 or len(cs) < 2:
            return False
        def similarity(k):
            return float(np.mean([W[i, j] for i in units[ui]["segs"] for j in units[k]["segs"]]))
        v = [similarity(k) for k in vs]
        c = [similarity(k) for k in cs]
        return (all(np.isfinite(x) for x in v + c)
                and min(v) >= STRUCTURE_SAME_MATERIAL_SIM
                and min(v) >= max(c) + 0.1)

    unit_names = [None] * len(units)
    if not repeated and not instrumental:
        # Nothing recurs: there is no measured basis for verse/chorus names.
        # Through-composed songs, ambient pieces and single-texture tracks
        # get neutral names rather than a guessed song form.
        for ui, u in enumerate(units):
            unit_names[ui] = "Instrumental" if (has_v and not u["sung"]) else "Section"
        for ui, u in enumerate(units):
            for i in u["segs"]:
                names[i] = unit_names[ui]
        if STRUCTURE_LONE_SUNG_IS_VERSE and lone_sung_verse and has_v and lyric_ng:
            # dev30: see STRUCTURE_LONE_SUNG_IS_VERSE.
            def _worded(i):
                return i < len(lyric_ng) and len(lyric_ng[i]) >= STRUCTURE_LYRIC_MIN_NGRAMS
            _su = [ui for ui, u in enumerate(units) if u["sung"] and any(_worded(i) for i in u["segs"])]
            if 1 <= len(_su) <= int(STRUCTURE_LONE_SUNG_MAX_PARTS):
                for ui in _su:
                    for i in units[ui]["segs"]:
                        # a stretch of it with no words and little voice (stem
                        # bleed after the singing ends) is instrumental
                        names[i] = ("Verse" if (_worded(i) or cov[i] >= 2 * STRUCTURE_SUNG_MIN_COVERAGE + 0.1)
                                    else "Instrumental")
        return names, labels, cov
    # A part with the verse's or chorus's music but (almost) no voice -- an
    # instrumental pass over the chorus chords, a solo over the verse -- is
    # Instrumental, not another verse or chorus. Only when it has well under
    # the sung level AND a small fraction of what its sung siblings carry, so
    # a quiet or thinly transcribed vocal occurrence keeps its name.
    u_cov = []
    for u in units:
        u_cov.append(float(np.mean([cov[i] for i in u["segs"]])) if cov is not None else None)

    def _voiceless(ui):
        if not STRUCTURE_SPLIT_INSTRUMENTAL:
            return False
        if u_cov[ui] is None or u_cov[ui] >= STRUCTURE_SUNG_MIN_COVERAGE:
            return False
        sib = [u_cov[k] for k in range(len(units)) if k != ui and units[k]["cl"] == units[ui]["cl"]
               and u_cov[k] is not None]
        return bool(sib) and u_cov[ui] < 0.25 * float(np.median(sib))

    for ui, u in enumerate(units):
        if u["cl"] in (chorus, verse) and u["cl"] is not None and _voiceless(ui):
            unit_names[ui] = "Instrumental"
        elif u["cl"] == chorus:
            unit_names[ui] = "Chorus"
        elif u["cl"] == verse:
            unit_names[ui] = "Verse"
    if (lyric_hi and chorus is not None and verse is not None and lyric_ng
            and STRUCTURE_LYRIC_PHRASES and STRUCTURE_LYRIC_CHORUS_CHECKS):
        # An occurrence that sounds like the verse but SINGS THE CHORUS'S WORDS
        # is a chorus: a stripped-down opening chorus (no drums, no bass) is
        # acoustically closer to the verses and was clustered with them, so a
        # chorus-first song came out "Verse 1 / Verse 2 / Chorus 1". Only when
        # the lyrics already decided which part is the chorus, and at least
        # half of its word patterns are the chorus's -- a verse that runs into
        # its chorus picks up a few of them through Whisper's merged lines
        # (under a quarter in every test), not half.
        def _unit_ng(k):
            ss = set()
            for i in units[k]["segs"]:
                ss |= lyric_ng[i]
            return ss
        ch_occurrences = [_unit_ng(k) for k in repeated.get(chorus, [])
                          if unit_names[k] == "Chorus"]
        if any(ch_occurrences):
            _ch0 = [k for k in range(len(units)) if unit_names[k] == "Chorus"]
            # (a short sung tail after it -- the last line, a fade -- does not count)
            _last_sung = max([k for k in range(len(units)) if units[k]["sung"]
                              and units[k]["len"] > 1.5 * STRUCTURE_SHORT_LEAD_S], default=-1)
            for ui, u in enumerate(units):
                if u["cl"] != verse or unit_names[ui] != "Verse":
                    continue
                mine = _unit_ng(ui)
                if _sx_matches_chorus_occurrence(mine, ch_occurrences, _distinct_verse_audio(ui)):
                    if (STRUCTURE_CHORUS_WORDS_TAIL_IS_OUTRO and _ch0 and ui > max(_ch0)
                            and ui == _last_sung):
                        # dev26: the verse's music under the chorus's hook,
                        # after the last chorus, ending the singing: the outro.
                        unit_names[ui] = "Outro"
                    else:
                        unit_names[ui] = "Chorus"
    ch_units = [ui for ui, u in enumerate(units)
                if u["cl"] == chorus and (unit_names[ui] == "Chorus" or not STRUCTURE_SPLIT_INSTRUMENTAL)
                ] if chorus is not None else []
    first_ch = ch_units[0] if ch_units else None
    last_ch = ch_units[-1] if ch_units else None
    theme_names = {}

    for ui, u in enumerate(units):
        if unit_names[ui] is not None:
            continue
        c = u["cl"]
        if instrumental:
            if c in repeated:
                if c not in theme_names:
                    theme_names[c] = "Theme %s" % chr(65 + len(theme_names))
                unit_names[ui] = theme_names[c]
            else:
                unit_names[ui] = "Section"
            continue
        if not u["sung"]:
            unit_names[ui] = "Instrumental"
            continue
        if c in _tags and chorus is not None:
            if ui > 0 and units[ui - 1]["cl"] == chorus:
                unit_names[ui] = "Post-Chorus"
                continue
            if last_ch is not None and ui > last_ch:
                unit_names[ui] = "Outro"
                continue
        if (c is not None and c == _wordless_demoted and chorus is not None and ui > 0
                and units[ui - 1]["cl"] == chorus and u["len"] <= 20.0):
            # dev74: the short tail that lost the chorus name to the words,
            # straight after a chorus, stays its own part (no boundary lost).
            unit_names[ui] = "Post-Chorus"
            continue
        _sung_twice = True
        if STRUCTURE_REPEAT_NEEDS_SUNG_TWICE and c in repeated and c not in (chorus, verse):
            # dev26: material that comes back only as an instrumental pass
            # is not a recurring SUNG part -- its one sung occurrence is named
            # like any other one-off sung part (see the setting).
            _sung_twice = (sum(1 for k in repeated[c] if units[k]["sung"]) >= 2
                           or not (first_ch is not None and first_ch < ui < last_ch))
        if c in repeated and chorus is not None and _sung_twice:
            occ = repeated[c]
            precedes = all(k + 1 < len(units) and units[k + 1]["cl"] == chorus for k in occ)
            follows = all(k - 1 >= 0 and units[k - 1]["cl"] == chorus for k in occ)
            short = all(units[k]["len"] <= STRUCTURE_PRECHORUS_UNIT_MAX_S for k in occ)
            after_sung = all(k - 1 >= 0 and units[k - 1]["sung"] and units[k - 1]["cl"] != chorus for k in occ)
            # A pre-chorus must be genuinely different material from the
            # verse it follows, not just the verse's second half.
            distinct = True
            if verse is not None:
                vs_ = [i for k in repeated.get(verse, []) for i in units[k]["segs"]]
                me_ = [i for k in occ for i in units[k]["segs"]]
                if vs_ and me_:
                    distinct = float(np.mean([W[a_, b_] for a_ in me_ for b_ in vs_])) <= STRUCTURE_PRECHORUS_DISTINCT_MAX
            _post_ok = short
            if (not short and follows and STRUCTURE_POSTCHORUS_CHORUS_LENGTH
                    and same_words.get(c, 0.0) >= STRUCTURE_LYRIC_SAME_HI_MIN):
                # dev26: a word-repeating part after every chorus may run a
                # little past 20 s when the choruses do too (see the setting).
                _chl = [units[k]["len"] for k in range(len(units)) if units[k]["cl"] == chorus]
                if _chl:
                    _lim = max(20.0, 1.1 * float(np.median(_chl)))
                    _post_ok = all(units[k]["len"] <= _lim and units[k]["len"] <= units[k - 1]["len"] + 1e-6
                                   for k in occ)
            if precedes and short and after_sung and distinct:
                unit_names[ui] = "Pre-Chorus"
            elif follows and _post_ok:
                unit_names[ui] = "Post-Chorus"
            elif (STRUCTURE_REPEATED_BRIDGE and follows and distinct and verse is not None
                  and same_words.get(c, 0.0) >= STRUCTURE_LYRIC_SAME_HI_MIN):
                # dev30: see STRUCTURE_REPEATED_BRIDGE.
                unit_names[ui] = "Bridge"
            elif (STRUCTURE_PRECHORUS_AFTER_VERSE and c in lyric_hi and verse is not None
                  and distinct and all(k - 1 >= 0 and units[k - 1]["cl"] == verse for k in occ)
                  and not any(k - 1 >= 0 and units[k - 1]["cl"] == chorus for k in occ)
                  and occ[0] + 1 < len(units) and units[occ[0] + 1]["cl"] == chorus
                  and all(units[k]["len"] <= STRUCTURE_PRECHORUS_AFTER_VERSE_MAX_S for k in occ)):
                # dev32: see STRUCTURE_PRECHORUS_AFTER_VERSE.
                unit_names[ui] = "Pre-Chorus"
            else:
                unit_names[ui] = "Verse"
            continue
        if c in repeated and _sung_twice:
            unit_names[ui] = "Verse"
            continue
        # dev50: a one-off part before the last chorus that sings mostly the
        # chorus's words is a chorus (see STRUCTURE_ONEOFF_CHORUS_WORDS).
        if (STRUCTURE_ONEOFF_CHORUS_WORDS and lyric_hi and chorus is not None and lyric_ng
                and STRUCTURE_LYRIC_PHRASES and STRUCTURE_LYRIC_CHORUS_CHECKS
                and last_ch is not None and ui < last_ch):
            _chorus_occurrences = []
            for k in repeated.get(chorus, []):
                if unit_names[k] == "Chorus":
                    _occurrence = set()
                    for i in units[k]["segs"]:
                        _occurrence |= lyric_ng[i]
                    _chorus_occurrences.append(_occurrence)
            _mine = set()
            for i in u["segs"]:
                _mine |= lyric_ng[i]
            _nb = sum(segs[i][1] - segs[i][0] for i in u["segs"])
            # A pickup of a bar or two is left to the short-lead join below,
            # which hands it to the section it leads into.
            if (_nb >= STRUCTURE_MIN_SECTION_BARS
                    and _sx_matches_chorus_occurrence(_mine, _chorus_occurrences, _distinct_verse_audio(ui))):
                unit_names[ui] = "Chorus"
                continue
        # One-off sung material.
        if first_ch is not None and first_ch < ui < last_ch:
            sim_verse = 0.0
            if verse is not None:
                vs = [i for k in repeated.get(verse, []) for i in units[k]["segs"]]
                sim_verse = max([W[i, j] for i in u["segs"] for j in vs], default=0.0)
                if STRUCTURE_ONEOFF_VERSE_TYPICAL and len(repeated.get(verse, [])) >= 3:
                    # dev26: like the verse as it usually sounds, not just
                    # like its one closest occurrence (see the setting).
                    _per = sorted(max([W[i, j] for i in u["segs"] for j in units[k]["segs"]], default=0.0)
                                  for k in repeated.get(verse, []))
                    sim_verse = min(sim_verse, float(np.median(_per)))
            unit_names[ui] = "Verse" if sim_verse >= STRUCTURE_SAME_MATERIAL_SIM + 0.05 else "Bridge"
        elif (STRUCTURE_FADING_LAST_CHORUS and first_ch is not None and ui > last_ch
              and ui - 1 >= 0 and units[ui - 1]["cl"] == chorus and lyric_ng
              and _sx_fading_last_chorus(u, units[ui - 1], units, unit_names, repeated, chorus,
                                         lyric_ng, W, loud)):
            unit_names[ui] = "Chorus"
            if info_out is not None:
                # its own section, not merged into the chorus before it
                info_out.setdefault("keep_split", set()).add(u["segs"][0])
                info_out["fading_last_chorus"] = True
        elif first_ch is not None and ui > last_ch:
            _rv = ([v for v in (_sx_word_recurrence(lyric_ng, i) for i in u["segs"]) if v is not None]
                   if (STRUCTURE_LATE_POSTCHORUS and lyric_ng) else [])
            _last_ui = len(units) - 1
            if STRUCTURE_FADE_TAIL_IS_NOT_NEXT:
                # dev56: trailing fade-out stubs do not count as a part after it.
                _sung_l = [float(loud[i]) for uu in units if uu["sung"] for i in uu["segs"]]
                _ref_l = float(np.median(_sung_l)) if _sung_l else None
                while (_ref_l is not None and _last_ui > ui and units[_last_ui]["len"] <= STRUCTURE_SHORT_LEAD_S
                       and max(float(loud[i]) for i in units[_last_ui]["segs"]) <= _ref_l - float(STRUCTURE_FADE_TAIL_DB)):
                    _last_ui -= 1
            if (_rv and ui - 1 >= 0 and units[ui - 1]["cl"] == chorus and ui < _last_ui
                    and float(np.mean(_rv)) >= STRUCTURE_TAG_WORDS_MIN):
                unit_names[ui] = "Post-Chorus"
            else:
                unit_names[ui] = ("Outro" if (ui == len(units) - 1 or STRUCTURE_NO_BRIDGE_AFTER_LAST_CHORUS)
                                  else "Bridge")
        elif _verse_only_last is not None and chorus is None and ui > _verse_only_last:
            # dev70: one-off sung material after the last verse of a song with
            # no chorus. When a substantial instrumental ending still follows
            # it (STRUCTURE_VERSE_ONLY_BRIDGE_TAIL_S), it is a bridge and the
            # outro starts after it (a rock test track: a one-off sung part at
            # 1:51-2:07, then the solo and ending); otherwise it is the outro,
            # as after a last chorus.
            _u_end = float(bar_edges[segs[u["segs"][-1]][1]])
            if (ui == len(units) - 1
                    and float(duration) - _u_end >= float(STRUCTURE_VERSE_ONLY_BRIDGE_TAIL_S)):
                unit_names[ui] = "Bridge"
            else:
                unit_names[ui] = ("Outro" if (ui == len(units) - 1 or STRUCTURE_NO_BRIDGE_AFTER_LAST_CHORUS)
                                  else "Bridge")
        else:
            unit_names[ui] = "Verse"

    if STRUCTURE_VERSE_BEFORE_CHORUS and chorus is not None and not instrumental and ch_units:
        # dev55: one-off sung parts in the verse's place -- each straight
        # before a chorus that is not the last one -- that sound alike are
        # the verses, even when they were not alike enough to be grouped as
        # one material (one child-lead test artist "one multi-chorus test scan": 0:16 and 1:14, 0.54).
        _cand = [ui for ui, u in enumerate(units)
                 if unit_names[ui] in ("Verse", "Bridge") and u["cl"] not in repeated and u["sung"]
                 and ui + 1 < len(units) and ui + 1 in ch_units and ui + 1 != last_ch]
        if len(_cand) >= 2:
            _segs_of = {ui: units[ui]["segs"] for ui in _cand}
            _first = _cand[0]
            for ui in _cand[1:]:
                _sim = float(np.mean([W[a_, b_] for a_ in _segs_of[_first] for b_ in _segs_of[ui]]))
                if _sim >= STRUCTURE_VERSE_BEFORE_CHORUS_SIM:
                    unit_names[ui] = "Verse"
                    unit_names[_first] = "Verse"

    if (STRUCTURE_ONEOFF_VERSE_SLOT and chorus is not None and not instrumental
            and (verse is None or STRUCTURE_ONEOFF_VERSE_SLOT_ANY)):
        # dev30: see STRUCTURE_ONEOFF_VERSE_SLOT.
        _runs = []
        for k in range(len(units)):
            if unit_names[k] == "Chorus":
                if _runs and k == _runs[-1][-1] + 1:
                    _runs[-1].append(k)
                else:
                    _runs.append([k])
        if len(_runs) >= 3:
            _mid = list(range(_runs[0][-1] + 1, _runs[1][0]))
            _v1 = [k for k in range(_runs[0][0]) if unit_names[k] == "Verse" and units[k]["sung"]]
            if len(_mid) == 1 and _v1:
                k = _mid[0]
                _w = set()
                for i in units[k]["segs"]:
                    if lyric_ng and i < len(lyric_ng):
                        _w |= lyric_ng[i]
                if (unit_names[k] == "Bridge" and units[k]["sung"]
                        and len(_w) >= STRUCTURE_LYRIC_MIN_NGRAMS):
                    unit_names[k] = "Verse"

    if (STRUCTURE_LATE_BRIDGE and verse is not None and chorus is not None and not instrumental
            and info_out is not None):
        _vocc = [k for k in range(len(units)) if units[k]["cl"] == verse and unit_names[k] == "Verse"]
        _chu = [k for k in range(len(units)) if unit_names[k] == "Chorus"]
        if len(_vocc) >= 3 and _chu:
            k = _vocc[-1]
            others = _vocc[:-1]
            _dens = [units[j]["dens"] for j in others if not np.isnan(units[j]["dens"])]
            _vps = [units[j]["vp"] for j in others if not np.isnan(units[j]["vp"])]
            if (sum(1 for c_ in _chu if c_ < k) >= 2 and max(_chu) > k and _dens and _vps
                    and not np.isnan(units[k]["dens"]) and not np.isnan(units[k]["vp"])
                    and units[k]["dens"] <= STRUCTURE_LATE_BRIDGE_DRUMS * float(np.mean(_dens))
                    and units[k]["vp"] >= float(np.median(_vps)) + STRUCTURE_LATE_BRIDGE_SEMITONES):
                unit_names[k] = "Bridge"
                if k + 1 < len(units) and unit_names[k + 1] == "Bridge":
                    info_out.setdefault("keep_split", set()).add(units[k + 1]["segs"][0])

    if (STRUCTURE_VOCABLE_BRIDGE and chorus is not None and not instrumental and info_out is not None
            and info_out.get("vocable_counts")):
        # dev74: a verse-named part sung (almost) only on vocables, after at
        # least two choruses and before the last, is the middle eight. One
        # boy-band test track runs on one chord loop, so its "na na na"
        # bridge (2:06) was grouped with verse 1 and named Verse 2, while the
        # real second verse (1:05, cut together with its pre-chorus) was a
        # one-off and named Bridge. When such a bridge is found, a one-off
        # part named Bridge that comes before the second chorus and sings
        # words is a verse.
        _heard, _lex = info_out["vocable_counts"]
        _chu = [k for k in range(len(units)) if unit_names[k] == "Chorus"]
        _found = False
        for k in range(len(units)):
            if unit_names[k] != "Verse" or len(_chu) < 3:
                continue
            h = sum(_heard[i] for i in units[k]["segs"] if i < len(_heard))
            lx = sum(_lex[i] for i in units[k]["segs"] if i < len(_lex))
            if (h >= int(STRUCTURE_VOCABLE_BRIDGE_MIN_WORDS)
                    and (h - lx) >= float(STRUCTURE_VOCABLE_BRIDGE_SHARE) * h
                    and sum(1 for c_ in _chu if c_ < k) >= 2 and max(_chu) > k):
                unit_names[k] = "Bridge"
                _found = True
        if _found:
            _second = _chu[1]
            for k in range(len(units)):
                if (unit_names[k] == "Bridge" and k < _second and units[k]["cl"] not in repeated
                        and units[k]["sung"]):
                    h = sum(_heard[i] for i in units[k]["segs"] if i < len(_heard))
                    lx = sum(_lex[i] for i in units[k]["segs"] if i < len(_lex))
                    if lx >= int(STRUCTURE_VOCABLE_BRIDGE_MIN_WORDS) and lx >= 0.5 * h:
                        unit_names[k] = "Verse"

    if (STRUCTURE_WORDLESS_CODA and chorus is not None and not instrumental and info_out is not None
            and info_out.get("vocable_counts")):
        # dev33: see STRUCTURE_WORDLESS_CODA.
        try:
            _heard, _lex = info_out["vocable_counts"]
            _chu = [k for k in range(len(units)) if unit_names[k] == "Chorus"]
            _ulex = [sum(_lex[i] for i in units[k]["segs"] if i < len(_lex)) for k in range(len(units))]
            if _chu and sum(_lex) >= int(STRUCTURE_WORDLESS_CODA_SONG_WORDS):
                _lc = max(_chu)
                for k in range(_lc + 1, len(units)):
                    if unit_names[k] != "Verse" or _ulex[k] > int(STRUCTURE_WORDLESS_CODA_MAX_WORDS):
                        continue
                    _c = units[k]["cl"]
                    if any(j <= _lc for j in range(len(units)) if units[j]["cl"] == _c):
                        continue    # music also heard before the coda (a verse Whisper missed, an intro's reprise)
                    unit_names[k] = "Instrumental"
        except Exception:
            pass
    for ui, u in enumerate(units):
        for i in u["segs"]:
            names[i] = unit_names[ui]
    if STRUCTURE_PRECHORUS_BUILDUP and chorus is not None and not instrumental:
        # dev35: see STRUCTURE_PRECHORUS_BUILDUP.
        try:
            def _segm(arr, i):
                if arr is None:
                    return np.nan
                a_, b_ = segs[i]
                x_ = np.asarray(arr[a_:b_], dtype=float)
                x_ = x_[~np.isnan(x_)]
                return float(np.mean(x_)) if x_.size else np.nan
            _hits = []
            for k in range(len(units) - 1):
                sg = units[k]["segs"]
                if unit_names[k] != "Verse" or unit_names[k + 1] != "Chorus" or len(sg) < 2:
                    continue
                j, head = sg[-1], sg[:-1]
                tl = float(lens[j])
                hl = float(sum(lens[i] for i in head))
                if not (8.0 <= tl <= float(STRUCTURE_PRECHORUS_MAX_S)) or hl < float(STRUCTURE_MIN_SECTION_S):
                    continue
                dvp = _segm(vp_bars, j) - float(np.nanmean([_segm(vp_bars, i) for i in head]))
                if not (dvp >= float(STRUCTURE_PRECHORUS_BUILDUP_ST)):
                    continue
                if F.get("has_stems"):
                    ddr = _segm(F["drums"], j) - float(np.nanmean([_segm(F["drums"], i) for i in head]))
                    if not (ddr > 0.0):
                        continue
                _hits.append(j)
            if len(_hits) >= int(STRUCTURE_PRECHORUS_BUILDUP_MIN_UNITS):
                for j in _hits:
                    names[j] = "Pre-Chorus"
        except Exception:
            pass
    if (STRUCTURE_TITLE_SEGMENTS and title_hits and not instrumental and not lyric_hi
            and len(title_hits) == len(names)
            and not (STRUCTURE_TITLE_SEGMENTS_NEEDS_NEW_WORDS and same_words
                     and max(same_words.values()) >= float(STRUCTURE_LYRIC_SAME_HI_MIN))):
        # dev32: see STRUCTURE_TITLE_SEGMENTS.
        try:
            _seg_u = {i: ui for ui, u in enumerate(units) for i in u["segs"]}
            _dense = [i for i in range(len(names)) if title_hits[i] >= 2 and i in _seg_u]
            if (len(_dense) >= 2 and len({units[_seg_u[i]]["cl"] for i in _dense}) >= 2
                    and all(names[i] in ("Chorus", "Verse") for i in _dense)
                    and any(names[i] == "Verse" for i in _dense)):
                for i in range(len(names)):
                    if i in _dense:
                        names[i] = "Chorus"
                    elif (names[i] == "Chorus" and title_hits[i] == 0 and i in _seg_u
                          and units[_seg_u[i]]["sung"]
                          and (not lyric_ng or (i < len(lyric_ng) and lyric_ng[i]))):
                        names[i] = "Verse"
        except Exception:
            pass
    return names, labels, cov


_SX_RECURRING_NAMES = ("Chorus", "Verse", "Pre-Chorus", "Post-Chorus")
_SX_SUNG_NAMES = ("Chorus", "Verse", "Pre-Chorus", "Post-Chorus", "Bridge")


def _sx_split_instrumental_edges(sections, F, bars, duration):
    """Separate a multi-bar instrumental stretch at the start or end of a sung
    section (a riff between chorus and verse, a solo after a chorus) from it.

    The boundary search can leave such a stretch inside the verse or chorus
    next to it -- most often when it runs over the same chords -- and the
    section was then described as a chorus that "goes instrumental" part way.
    Only runs of at least STRUCTURE_MIN_SECTION_BARS bars (and
    STRUCTURE_MIN_SECTION_S seconds) with essentially no voice are split, and
    only when the sung part left behind is at least as long, so the pauses
    between sung lines and a short lead-in or tail are never touched. A
    stretch next to the Intro / Outro / an Instrumental joins it; otherwise it
    becomes its own Instrumental section. With
    STRUCTURE_SHORT_INSTRUMENTAL_PARTS, a verse/chorus-named section with no
    voice anywhere in it (from 2 bars long) is renamed Instrumental.
    """
    if not sections or not F.get("has_vocal"):
        return sections
    sections = [dict(x) for x in sections]      # never edit the caller's sections
    vocal = np.asarray(F.get("vocal"), dtype=float)
    edges = np.concatenate([np.asarray(bars, dtype=float), [duration]])
    minb = int(STRUCTURE_MIN_SECTION_BARS)

    def _secs(a, b):
        return float(edges[b] - edges[a])

    out = []
    for s in sections:
        a, b = s.get("_a"), s.get("_b")
        short_ok = 2 if STRUCTURE_SHORT_INSTRUMENTAL_PARTS else 2 * minb
        if (s.get("name") not in _SX_SUNG_NAMES or a is None or b is None
                or b - a < short_ok or b > len(vocal)):
            out.append(s)
            continue
        v = vocal[a:b]
        if b - a < 2 * minb and not (float(np.max(v)) < STRUCTURE_SUNG_MIN_COVERAGE
                                     and float(np.mean(v)) < STRUCTURE_UNSUNG_RUN_MEAN):
            out.append(s)
            continue

        def _run(seq):
            # Longest run from the edge with no sung bar and a low average.
            k, best = 0, 0
            while k < len(seq) and seq[k] < STRUCTURE_SUNG_MIN_COVERAGE:
                k += 1
                if float(np.mean(seq[:k])) < STRUCTURE_UNSUNG_RUN_MEAN:
                    best = k
            return best

        lead = _run(v)
        tail = _run(v[::-1][:len(v) - lead])
        use_lead = lead >= minb and _secs(a, a + lead) >= STRUCTURE_MIN_SECTION_S
        use_tail = tail >= minb and _secs(b - tail, b) >= STRUCTURE_MIN_SECTION_S
        if (STRUCTURE_SHORT_INSTRUMENTAL_PARTS and lead == len(v) and len(v) >= 2
                and float(np.mean(v)) < STRUCTURE_UNSUNG_RUN_MEAN):
            # No voice anywhere in it: a pass over the chorus or verse music
            # without the singer (kept apart from the sung chorus before it by
            # a drum entry or fill) is an Instrumental, not "Chorus 2".
            s = dict(s)
            s["name"] = "Instrumental"
            out.append(s)
            continue
        core = (b - a) - (lead if use_lead else 0) - (tail if use_tail else 0)
        if core < minb or core < max(lead if use_lead else 0, tail if use_tail else 0):
            out.append(s)
            continue
        if use_lead:
            prev = out[-1] if out else None
            if prev is not None and prev.get("name") in ("Intro", "Instrumental") and prev.get("_b") == a:
                prev["end"] = float(edges[a + lead])
                prev["_b"] = a + lead
            else:
                out.append({"name": "Instrumental", "start": float(edges[a]),
                            "end": float(edges[a + lead]), "_a": a, "_b": a + lead,
                            "_parts": [], "cluster": "Unique"})
            s = dict(s)
            s["start"] = float(edges[a + lead])
            s["_a"] = a + lead
        if use_tail:
            s = dict(s)
            s["end"] = float(edges[b - tail])
            s["_b"] = b - tail
            out.append(s)
            out.append({"name": "Instrumental", "start": float(edges[b - tail]),
                        "end": float(edges[b]), "_a": b - tail, "_b": b,
                        "_parts": [], "cluster": "Unique", "_tail_of": True})
        else:
            out.append(s)
    # A split-off tail followed by the Outro or another Instrumental joins it.
    merged = []
    for s in out:
        if (merged and merged[-1].get("_tail_of") and s.get("name") in ("Outro", "Instrumental")
                and merged[-1].get("_b") == s.get("_a")):
            s = dict(s)
            s["start"] = merged[-1]["start"]
            s["_a"] = merged[-1]["_a"]
            merged[-1] = s
            continue
        merged.append(s)
    for s in merged:
        s.pop("_tail_of", None)
    try:
        return _sx_cluster_split_pieces([dict(x) for x in merged], F, bars, duration)
    except Exception:
        return merged


def _sx_cluster_split_pieces(sections, F, bars, duration):
    """Cluster letters for the Instrumental pieces split off above, measured
    like every other section: a piece that matches an existing Instrumental
    takes its letter, pieces that match each other share a new one, and the
    rest get letters of their own -- so a riff that recurs reads as the same
    material and different breaks as different."""
    new = [k for k, s in enumerate(sections) if s.get("name") == "Instrumental"
           and not s.get("_parts") and s.get("_a") is not None]
    if not new:
        return sections
    old = [k for k, s in enumerate(sections) if s.get("name") == "Instrumental"
           and s.get("_parts") and s.get("_a") is not None and s.get("cluster") not in (None, "Unique")]
    idx = new + old
    segs = [(int(sections[k]["_a"]), int(sections[k]["_b"])) for k in idx]
    W = _sx_segment_similarity(F, segs)
    used = {str(s.get("cluster")) for s in sections}
    assigned = {}
    for j, k in enumerate(new):
        best = None
        for jj in range(len(new), len(idx)):
            if W[j, jj] >= STRUCTURE_SAME_MATERIAL_SIM and (best is None or W[j, jj] > W[j, best]):
                best = jj
        if best is not None:
            assigned[k] = sections[idx[best]]["cluster"]
    rest = [j for j, k in enumerate(new) if k not in assigned]
    if rest:
        groups = _sx_cluster(W, rest)
        letter_for = {}
        nxt = 0
        for j in rest:
            g = groups[j]
            if g not in letter_for:
                while nxt < 26 and chr(65 + nxt) in used:
                    nxt += 1
                letter_for[g] = chr(65 + nxt) if nxt < 26 else "Z"
                used.add(letter_for[g])
            assigned[new[j]] = letter_for[g]
    for k, cl in assigned.items():
        sections[k]["cluster"] = cl
    return sections


def _sx_split_double_choruses(sections, segs, bars, duration, ev=None, F=None):
    """List a chorus sung twice back to back as two choruses.

    Neighbouring parts that are both the chorus are merged into one section
    (above), which is right when the boundary search cut one chorus into its
    halves and wrong for a double chorus: a chorus-first song's "1:40 Chorus,
    1:58 Chorus" came out as one 35-second "Chorus 3". The two are told apart
    by length. The song's ordinary chorus length is the median of its other
    choruses (at least two of them of four bars or more, leaving out any
    that are themselves half as long again as their median). A merged
    chorus is cut at its inner part boundaries only where every piece is
    close to that length (0.75-1.35x); halves of a chorus are about half of
    it and stay merged. When the boundary search left no cut inside a chorus
    1.75-2.3x the ordinary length, it is cut one ordinary length in (at the
    best-evidenced bar within a bar of that). Either way every piece must
    sound like the same material as the others (a chorus sung again, not a
    chorus plus a tag), so nothing is split without the bar features. Every
    piece keeps the chorus's name and cluster letter. Runs after the
    voiceless parts have been renamed Instrumental, so those never count as
    choruses here."""
    if not sections:
        return sections
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    ch = [k for k, s in enumerate(sections)
          if s.get("name") == "Chorus" and s.get("_a") is not None and s.get("_b") is not None]
    if len(ch) < 3:
        return sections
    lens = {k: int(sections[k]["_b"]) - int(sections[k]["_a"]) for k in ch}
    minb = int(STRUCTURE_MIN_SECTION_BARS)
    out = []
    for k, s in enumerate(sections):
        if k not in lens:
            out.append(s)
            continue
        others = sorted(lens[j] for j in ch if j != k and lens[j] >= minb)
        if len(others) < 2:
            out.append(s)
            continue
        base = [x for x in others if x <= 1.5 * float(np.median(others))]
        a, b = int(s["_a"]), int(s["_b"])
        L = b - a
        if STRUCTURE_DOUBLE_CHORUS_SHORTEST and others:
            # dev55: the ordinary chorus is the shortest full one when the
            # others are themselves doubles (8, 15 and 16 bars: 8 is the
            # chorus, not the 11.5-bar median of 8 and 15).
            _short = min(others)
            _dbl_ok = True
            if STRUCTURE_DOUBLE_CHORUS_SHORTEST_NEEDS_DOUBLES:
                # dev26: the shortest chorus sets the length only when the
                # other choruses are doubles of it (dev55's 8, 15 and 16 bars),
                # not when it is merely a shorter one (5, 8 and 10 bars).
                _rest = [x for x in others if x != _short]
                _dbl_ok = (not _rest) or all(x >= 1.75 * _short for x in _rest)
            if _dbl_ok and (len(base) < 2 or 1.75 * _short <= L <= 2.3 * _short) and \
                    float(edges[min(a + _short, len(edges) - 1)] - edges[a]) >= 10.0:
                if 1.75 * _short <= L <= 2.3 * _short:
                    base = [_short, _short]
        if len(base) < 2:
            out.append(s)
            continue
        Lc = float(np.median(base))
        if L < 1.6 * Lc:
            out.append(s)
            continue
        lo, hi = max(float(minb), 0.75 * Lc), 1.35 * Lc
        # dev55: the song's last chorus may run longer at its end (a vamp or
        # fade-out on the hook).
        _hi_last = (1.75 * Lc if (STRUCTURE_DOUBLE_CHORUS_SHORTEST and k == ch[-1]) else hi)
        parts = list(s.get("_parts") or [])
        inner = [int(segs[p][0]) for p in parts[1:] if segs is not None and a < int(segs[p][0]) < b]
        pos = [a] + sorted(set(inner)) + [b]
        # Best way to group the parts into chorus-length pieces.
        best = {0: (0.0, [0])}
        for j in range(1, len(pos)):
            cand = None
            for i in range(j):
                if i not in best:
                    continue
                g = pos[j] - pos[i]
                if lo <= g <= (_hi_last if j == len(pos) - 1 else hi):
                    c = best[i][0] + abs(g - Lc)
                    if cand is None or c < cand[0]:
                        cand = (c, best[i][1] + [j])
            if cand is not None:
                best[j] = cand
        cut_bars = None
        last = len(pos) - 1
        if last in best and len(best[last][1]) >= 3:
            cut_bars = [pos[i] for i in best[last][1][1:-1]]
        elif len(pos) == 2 and 1.75 * Lc <= L <= 2.3 * Lc and ev is not None and F is not None:
            target = a + int(round(Lc))
            cands = [q for q in (target - 1, target, target + 1)
                     if lo <= q - a <= hi and lo <= b - q <= hi and 0 < q < len(ev)]
            if cands:
                q = max(cands, key=lambda x: float(ev[x]))
                try:
                    Wq = _sx_segment_similarity(F, [(a, q), (q, b)])
                    if float(Wq[0, 1]) >= STRUCTURE_SAME_MATERIAL_SIM:
                        cut_bars = [q]
                except Exception:
                    cut_bars = None
        if cut_bars and F is not None:
            # Every piece must be the same material as every other (a chorus
            # sung again), not a chorus plus a tag or an extension.
            try:
                pcs = list(zip([a] + cut_bars, cut_bars + [b]))
                Wp = _sx_segment_similarity(F, pcs)
                if min(float(Wp[i, j]) for i in range(len(pcs)) for j in range(len(pcs)) if i != j) \
                        < STRUCTURE_SAME_MATERIAL_SIM:
                    cut_bars = None
            except Exception:
                cut_bars = None
        else:
            cut_bars = None
        if not cut_bars:
            out.append(s)
            continue
        bounds_ = [a] + cut_bars + [b]
        for x, y in zip(bounds_[:-1], bounds_[1:]):
            piece = dict(s)
            piece["start"] = float(edges[x])
            piece["end"] = float(edges[y])
            piece["_a"], piece["_b"] = x, y
            mine = [p for p in parts if segs is not None and x <= int(segs[p][0]) < y]
            if not mine:
                mine = [p for p in parts if segs is not None and int(segs[p][0]) < y <= int(segs[p][1])] or parts[:1]
            piece["_parts"] = mine
            out.append(piece)
    return out


def _sx_join_short_sung_edges(sections, F, bars, duration):
    """Join a sung first or last section that is only a couple of bars long
    to its sung neighbour.

    The boundary search lets the first and last sections be as short as two
    bars (pickup intros, a final hit). When such a stub is SUNG and next to a
    sung section it is not a section of its own: on a chorus-first track the
    singer's pickup came out as "Verse 1 0:00-0:04, Chorus 1 0:04-0:22", and
    the last line ringing out as "Outro 3:36-3:42". A stub joins only when it
    is shorter than STRUCTURE_SHORT_LEAD_S seconds AND than the boundary
    search's minimum bar count (so a real four-bar section at a fast tempo is
    never absorbed), carries voice (average coverage at the sung level), and
    both it and its neighbour are sung parts (an Intro / Outro made of
    instrumental bars, an Instrumental and Silence never join). Needs the
    vocal stem; without it nothing changes. Cluster letters are re-lettered
    in order of appearance afterwards when anything was joined."""
    if not sections or len(sections) < 2 or not isinstance(F, dict) or not F.get("has_vocal"):
        return sections
    vocal = np.asarray(F.get("vocal"), dtype=float)
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    bar_len = float(np.median(np.diff(edges))) if len(edges) > 2 else 2.0
    min_b = int(STRUCTURE_MIN_SECTION_BARS) * (2 if bar_len < 1.6 else 1)

    def _stub(s):
        a, b = s.get("_a"), s.get("_b")
        if a is None or b is None or not (0 <= int(a) < int(b) <= vocal.size):
            return False
        return (int(b) - int(a) < min_b
                and float(s["end"]) - float(s["start"]) < STRUCTURE_SHORT_LEAD_S
                and float(np.mean(vocal[int(a):int(b)])) >= STRUCTURE_SUNG_MIN_COVERAGE)

    sections = list(sections)
    joined = False
    s0, s1 = sections[0], sections[1]
    if (s0.get("name") in _SX_SUNG_NAMES and s1.get("name") in _SX_SUNG_NAMES
            and abs(float(s1["start"]) - float(s0["end"])) < 0.05 and _stub(s0)):
        s1 = dict(s1)
        s1["start"] = s0["start"]
        s1["_a"] = s0["_a"]
        s1["_parts"] = list(s0.get("_parts") or []) + list(s1.get("_parts") or [])
        sections = [s1] + sections[2:]
        joined = True
    if len(sections) >= 2:
        sp, sl = sections[-2], sections[-1]
        if (sl.get("name") in ("Outro",) + _SX_SUNG_NAMES and sp.get("name") in _SX_SUNG_NAMES
                and abs(float(sl["start"]) - float(sp["end"])) < 0.05 and _stub(sl)):
            sp = dict(sp)
            sp["end"] = sl["end"]
            sp["_b"] = sl["_b"]
            sp["_parts"] = list(sp.get("_parts") or []) + list(sl.get("_parts") or [])
            sections = sections[:-2] + [sp]
            joined = True
    if joined:
        letters = {}
        for s in sections:
            c = s.get("cluster")
            if isinstance(c, str) and len(c) == 1 and c.isalpha() and c not in letters:
                letters[c] = chr(65 + len(letters)) if len(letters) < 26 else "Z"
        sections = [dict(s, cluster=letters.get(s.get("cluster"), s.get("cluster"))) for s in sections]
    return sections


def _sx_merge_named(segs, names, labels, bars, duration, ev=None, events=None, keep_split=None):
    """Merge neighbours that ended up with the same base name.

    Exception: two occurrences of RECURRING material separated by a strong,
    arrangement-marked boundary (a fill or a drum/vocal re-entry plus high
    overall evidence) stay separate -- that is a section repeated back to
    back (a double chorus), not one long section.
    """
    bar_edges = np.concatenate([np.asarray(bars, dtype=float), [duration]])
    keep_split_at = set(keep_split or ())
    out = []
    for i, (a, b) in enumerate(segs):
        nm = names[i]
        keep_split = False
        if out and out[-1]["name"] == nm and ev is not None and a < len(ev):
            recurring = nm in _SX_RECURRING_NAMES or nm.startswith("Theme ")
            marked = False
            if events:
                for key in ("fill", "drum_in", "kick_in", "vocal_in"):
                    arr = events.get(key)
                    if arr is not None and a < len(arr) and arr[a] >= 0.5:
                        marked = True
            keep_split = recurring and marked and float(ev[a]) >= 2.0
        if keep_split_at and i in keep_split_at:
            keep_split = True
        if out and out[-1]["name"] == nm and nm not in ("Section",) and not keep_split:
            out[-1]["end"] = float(bar_edges[b])
            out[-1]["_b"] = b
            out[-1]["_parts"].append(i)
        else:
            out.append({
                "name": nm,
                "start": float(bar_edges[a]),
                "end": float(bar_edges[b]),
                "_a": a, "_b": b, "_parts": [i],
            })
    return out


# dev52: see STRUCTURE_FINAL_CODA.
def _sx_split_final_coda(sections, segs, F, W, bars, duration):
    ch = [k for k, s in enumerate(sections) if s.get("name") == "Chorus"]
    if not ch:
        return sections
    k = ch[-1]
    s = sections[k]
    parts = list(s.get("_parts") or [])
    if len(parts) < 2:
        return sections
    # Nothing sung may follow except an outro or silence.
    for t in sections[k + 1:]:
        if t.get("name") not in ("Outro", "Silence", "Instrumental"):
            return sections
    p = parts[-1]
    voc = F.get("vocal")
    if voc is None:
        return sections
    voc = np.asarray(voc, dtype=float)
    a_p, b_p = int(segs[p][0]), int(segs[p][1])
    if b_p <= a_p or float(np.mean(voc[a_p:b_p])) < STRUCTURE_SUNG_MIN_COVERAGE:
        return sections
    if max(float(W[p, q]) for q in parts[:-1]) >= STRUCTURE_SAME_MATERIAL_SIM:
        return sections
    edges = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    cut = float(edges[a_p])
    head = dict(s)
    head["_parts"] = parts[:-1]
    head["_b"] = a_p
    head["end"] = cut
    tail = dict(s)
    tail["name"] = "Outro"
    tail["_parts"] = [p]
    tail["_a"] = a_p
    tail["start"] = cut
    rest = sections[k + 1:]
    if rest and rest[0].get("name") == "Outro":
        tail["end"] = rest[0]["end"]
        tail["_b"] = rest[0].get("_b", tail.get("_b"))
        tail["_parts"] = tail["_parts"] + list(rest[0].get("_parts") or [])
        rest = rest[1:]
    return sections[:k] + [head, tail] + rest


def _sx_cluster_letters(sections, labels, segs=None):
    """Readable cluster letters (A, B, ...) in order of first appearance.
    A merged section takes the cluster of its longest part."""
    seen = {}
    for s in sections:
        if s["name"] in ("Silence",):
            s["cluster"] = "Unique"
            continue
        parts = [p for p in (s.get("_parts") or []) if p in labels]
        if not parts:
            s["cluster"] = "Unique"
            continue
        if segs is not None:
            cl = labels[max(parts, key=lambda p: segs[p][1] - segs[p][0])]
        else:
            cl = labels[parts[0]]
        if cl not in seen:
            seen[cl] = chr(65 + len(seen)) if len(seen) < 26 else "Z"
        s["cluster"] = seen[cl]
    return sections


def _sx_number(sections):
    totals = {}
    for s in sections:
        totals[s["name"]] = totals.get(s["name"], 0) + 1
    seen = {}
    for s in sections:
        base = s["name"]
        if totals[base] > 1 and base not in ("Silence",):
            seen[base] = seen.get(base, 0) + 1
            s["name"] = "%s %d" % (base, seen[base])
    return sections


_SX_GRID_MEMO = {}


def _sx_audio_memo_key(y, sr, bpm_hint):
    import hashlib
    a = np.ascontiguousarray(np.asarray(y)[::97])
    return (int(len(y)), int(sr), None if bpm_hint is None else float(bpm_hint),
            hashlib.md5(a.tobytes()).hexdigest())


def _sx_grid_and_features(y, sr, bpm_hint=None):
    """Beat grid and per-beat mix features for build_structure_map:
    (beats, bpm, beatfeat) or None when no beats were found. dev55: memoised
    per audio + tempo hint, so the background pass (PARALLEL_ANALYSIS) and
    the in-order call share one computation -- same code, same result."""
    try:
        key = _sx_audio_memo_key(y, sr, bpm_hint)
    except Exception:
        key = None
    if key is not None and key in _SX_GRID_MEMO:
        beats, bpm, beatfeat = _SX_GRID_MEMO.pop(key)
        return list(beats), bpm, dict(beatfeat)
    beats, bpm = _sx_beat_grid(y, sr, bpm_hint=bpm_hint)
    if not beats:
        return None
    beatfeat = _sx_beat_features(y, sr, beats)
    lead, tail = _sx_silence_bounds(y, sr)
    beatfeat["music_start"] = lead
    beatfeat["music_end"] = tail
    try:
        accents = _downbeat_accent_curve(y, sr, np.asarray(beats, dtype=float))
    except Exception:
        accents = None
    beatfeat["accents"] = None if accents is None else np.asarray(accents, dtype=float)
    return beats, bpm, beatfeat


def _sx_precompute_grid(audio_path, bpm_hint=None):
    """dev55: compute and memoise the grid for audio_path (loaded exactly as
    the structure step loads it). Background use only; never raises."""
    try:
        y, sr = librosa.load(audio_path, sr=None, mono=True)
        if len(y) / float(sr) < 20.0:
            return
        key = _sx_audio_memo_key(y, sr, bpm_hint)
        g = _sx_grid_and_features(y, sr, bpm_hint)
        if g is not None:
            _SX_GRID_MEMO.clear()
            _SX_GRID_MEMO[key] = g
    except Exception:
        pass


_SX_NAMER_CATS = ("intro", "verse", "prechorus", "chorus", "postchorus", "bridge",
                  "instrumental", "outro", "other")
_SX_NAMER_NAMES = {"intro": "Intro", "verse": "Verse", "prechorus": "Pre-Chorus",
                   "chorus": "Chorus", "postchorus": "Post-Chorus", "bridge": "Bridge",
                   "instrumental": "Instrumental", "outro": "Outro"}
_SX_NAMER_NUMERIC = 17       # the first columns of a row are numbers; the rest are 0/1 types
_SX_NAMER_MODEL = None       # the loaded model (dict), False when none is found
_SX_NAMER_CAPTURE = None     # a list to collect feature rows (the training tool sets it)


def _sx_namer_cat(name):
    """The section type of a name ("Pre-Chorus 2" -> "prechorus")."""
    l = re.sub(r"[\s\-]+", "", _sx_base_name(name).lower())
    for k in ("prechorus", "postchorus", "chorus", "verse", "bridge", "intro", "outro", "instrumental"):
        if l.startswith(k):
            return k
    return "other"


def _sx_namer_features(segs, names, labels, F, bars, duration, W, cov, lyric_ng, lyric_rep):
    """dev31: one row of numbers per segment for the learned namer -- where
    it sits in the song, how loud / sung / high / drum-heavy it is against the
    song's sung parts, how its words and music come back, and the type the
    rules gave it and its neighbours. Nothing that names the song."""
    n = len(segs)
    be = np.concatenate([np.asarray(bars, dtype=float), [float(duration)]])
    dur = max(1.0, float(duration))
    st = np.array([be[a] for a, _b in segs]); en = np.array([be[b] for _a, b in segs])
    ln = np.maximum(0.5, en - st)
    loud = np.array([float(np.mean(F["loud"][a:b])) for a, b in segs])
    cv = (np.array([float(cov[i]) for i in range(n)]) if cov is not None
          else np.array([float(np.mean(F["vocal"][a:b])) if "vocal" in F else 0.0 for a, b in segs]))
    sung = cv >= STRUCTURE_SUNG_MIN_COVERAGE
    vp = []
    for a, b in segs:
        v = np.asarray(F.get("vpitch", np.full(len(bars), np.nan))[a:b], dtype=float)
        v = v[~np.isnan(v)]
        vp.append(float(np.median(v)) if v.size else np.nan)
    vp = np.array(vp)
    dr = (np.array([float(np.mean(F["drums"][a:b])) for a, b in segs]) if F.get("has_stems")
          else np.zeros(n))
    ref_l = float(np.median(loud[sung])) if sung.any() else float(np.median(loud))
    ref_v = float(np.nanmedian(vp[sung])) if sung.any() and np.any(~np.isnan(vp[sung])) else np.nan
    ref_d = float(np.median(dr[sung])) if sung.any() else float(np.median(dr))
    sung_s = float(np.sum(ln[sung])) or 1.0
    before = np.cumsum(np.concatenate([[0.0], (ln * sung)[:-1]])) / sung_s
    first_s = int(np.argmax(sung)) if sung.any() else -1
    last_s = (n - 1 - int(np.argmax(sung[::-1]))) if sung.any() else -1
    runs = {}
    prev_l = None
    for i in range(n):
        l = labels.get(i) if isinstance(labels, dict) else None
        if l is not None and (i == 0 or labels.get(i - 1) != l):
            runs.setdefault(l, []).append(i)
    cats = [_sx_namer_cat(x) for x in names]
    rows = []
    for i in range(n):
        ng = lyric_ng[i] if (lyric_ng and i < len(lyric_ng)) else set()
        oth = set()
        if lyric_ng:
            for j in range(len(lyric_ng)):
                if abs(j - i) > 1:
                    oth |= lyric_ng[j]
        rec = (len(ng & oth) / float(len(ng))) if len(ng) >= STRUCTURE_LYRIC_MIN_NGRAMS else -0.5
        rep = (lyric_rep[i] if (lyric_rep and i < len(lyric_rep) and lyric_rep[i] is not None) else -0.5)
        l = labels.get(i) if isinstance(labels, dict) else None
        occ = runs.get(l, []) if l is not None else []
        k_occ = sum(1 for r in occ if r <= i) - 1 if occ else 0
        wmax = max([float(W[i, j]) for j in range(n) if abs(j - i) > 1], default=0.0)
        row = [st[i] / dur, en[i] / dur, float(np.log(ln[i])), loud[i] - ref_l, cv[i],
               (vp[i] - ref_v) if not (np.isnan(vp[i]) or np.isnan(ref_v)) else 0.0,
               0.0 if np.isnan(vp[i]) else 1.0,
               float(np.clip(dr[i] / (ref_d + 1e-6), 0.0, 3.0)) if F.get("has_stems") else 1.0,
               float(rep), float(np.log1p(len(ng))), float(rec),
               min(len(occ), 6) / 6.0, (k_occ / max(1, len(occ) - 1)) if len(occ) > 1 else 0.0,
               wmax, 1.0 if i == first_s else 0.0, 1.0 if i == last_s else 0.0, float(before[i])]
        for c in (cats[i], cats[i - 1] if i > 0 else "other", cats[i + 1] if i + 1 < n else "other"):
            row += [1.0 if c == k else 0.0 for k in _SX_NAMER_CATS]
        rows.append(row)
    return np.asarray(rows, dtype=float), cats, sung


def _sx_namer_load():
    """The learned namer's table from STRUCTURE_LEARNED_NAMER_FILE (next to
    this script, or a full path), or None when there is none."""
    global _SX_NAMER_MODEL
    if _SX_NAMER_MODEL is None:
        _SX_NAMER_MODEL = False
        try:
            path = str(STRUCTURE_LEARNED_NAMER_FILE or "")
            if path and not os.path.isabs(path):
                path = os.path.join(os.path.dirname(os.path.abspath(__file__)), path)
            if path and os.path.exists(path):
                with open(path, "r", encoding="utf-8") as fh:
                    m = json.load(fh)
                m["X"] = np.asarray(m["rows"], dtype=float)
                m["y"] = list(m["labels"])
                m["g"] = np.asarray(m["groups"], dtype=int)
                m["mu"] = np.asarray(m["mean"], dtype=float)
                m["sd"] = np.asarray(m["std"], dtype=float)
                m["wt"] = np.asarray(m.get("weights") or [1.0] * len(m["mu"]), dtype=float)
                if m["X"].ndim == 2 and m["X"].shape[1] == len(m["mu"]) and len(m["y"]) == len(m["X"]):
                    _SX_NAMER_MODEL = m
        except Exception:
            _SX_NAMER_MODEL = False
    return _SX_NAMER_MODEL or None


def _sx_learned_namer(segs, names, labels, F, bars, duration, W, cov, lyric_ng, lyric_rep):
    """dev31 STRUCTURE_LEARNED_NAMER: names checked against sections from
    reference songs that look alike (the K nearest by the rows above). A
    segment is renamed only when STRUCTURE_LEARNED_NAMER_AGREE of the vote
    names one other type and the neighbours come from at least
    STRUCTURE_LEARNED_NAMER_MIN_SONGS different songs; a sung segment only
    gets a sung name, an unsung one only Intro / Outro / Instrumental, and
    Intro / Outro only at the song's start / end. Segments are decided a
    section at a time (each run of one name, votes added up), and never so
    that a section would join its neighbour: the namer changes names only,
    never a section line. With no model file, or the training tool collecting
    rows, the names are returned unchanged."""
    if not STRUCTURE_LEARNED_NAMER:
        return names
    X, cats, sung = _sx_namer_features(segs, names, labels, F, bars, duration, W, cov, lyric_ng, lyric_rep)
    if _SX_NAMER_CAPTURE is not None:
        _SX_NAMER_CAPTURE.append({"segs": [(int(a), int(b)) for a, b in segs],
                                  "times": [(float(np.concatenate([np.asarray(bars, float), [duration]])[a]),
                                             float(np.concatenate([np.asarray(bars, float), [duration]])[b]))
                                            for a, b in segs],
                                  "X": X.tolist(), "cats": cats})
        return names
    m = _sx_namer_load()
    if not m or len(names) < 3:
        return names
    Z = (X - m["mu"]) / m["sd"] * m["wt"]
    k = int(STRUCTURE_LEARNED_NAMER_K)
    out = list(names)
    n = len(names)
    seg_votes, seg_songs = [], []
    for i in range(n):
        d = np.sqrt(np.sum((m["X"] - Z[i]) ** 2, axis=1))
        nn = np.argsort(d)[:k]
        votes, songs = {}, {}
        for j in nn:
            votes[m["y"][j]] = votes.get(m["y"][j], 0.0) + 1.0 / (0.25 + float(d[j]))
            songs.setdefault(m["y"][j], set()).add(int(m["g"][j]))
        seg_votes.append(votes)
        seg_songs.append(songs)
    # segments decided together: each run of segments carrying one name (the
    # section they will make), so a new name never moves a section line
    groups = {}
    run = 0
    for i in range(n):
        if i > 0 and names[i] != names[i - 1]:
            run += 1
        groups.setdefault(run, []).append(i)
    first_of = {i: mem[0] for mem in groups.values() for i in mem}
    last_of = {i: mem[-1] for mem in groups.values() for i in mem}
    decide = {}
    for key, mem in groups.items():
        votes, songs = {}, {}
        for i in mem:
            for c_, w_ in seg_votes[i].items():
                votes[c_] = votes.get(c_, 0.0) + w_
            for c_, g_ in seg_songs[i].items():
                songs.setdefault(c_, set()).update(g_)
        tot = sum(votes.values())
        best, bw = max(votes.items(), key=lambda kv: kv[1]) if votes else (None, 0.0)
        for i in mem:
            decide[i] = (best, bw, tot, len(songs.get(best, ())))
    for i in range(n):
        if cats[i] == "other" or _sx_base_name(names[i]) == "Silence":
            continue
        best, bw, tot, n_songs = decide[i]
        if best == cats[i] or best not in _SX_NAMER_NAMES or bw < float(STRUCTURE_LEARNED_NAMER_AGREE) * tot:
            continue
        if n_songs < int(STRUCTURE_LEARNED_NAMER_MIN_SONGS):
            continue
        g_sung = sum(1 for q in range(first_of[i], last_of[i] + 1) if sung[q]) * 2 > (last_of[i] - first_of[i] + 1)
        if g_sung and best == "instrumental":
            continue
        if not g_sung and best not in ("intro", "outro", "instrumental"):
            continue
        a_, b_ = first_of[i], last_of[i]
        if best == "intro" and any(_sx_namer_cat(names[q]) not in ("intro", "other") for q in range(a_)):
            continue
        if best == "outro" and any(_sx_namer_cat(names[q]) not in ("outro", "other") for q in range(b_ + 1, n)):
            continue
        if (a_ > 0 and _sx_namer_cat(out[a_ - 1]) == best) or (b_ + 1 < n and cats[b_ + 1] == best):
            continue        # the new name would join it to its neighbour and lose a section line
        out[i] = _SX_NAMER_NAMES[best]
    return out


def build_structure_map(
    y=None, sr=None, total_duration=None, *,
    beatfeat=None, beats=None, bpm_hint=None,
    stem_notes=None, lyric_chunks=None, lyric_groups=None,
    instrumental=False, details_out=None, prechorus_by_words=False, sheet_intro=False,
    lone_sung_verse=True, learned_namer=False, title=None,
):
    """Signal-only section map: [{"name","start","end","cluster", ...}].

    Either `y`/`sr` (mono audio) or a cached `beatfeat` + `beats` from an
    earlier call (details_out) must be supplied. Stem note events and lyric
    timestamps are optional extra evidence; without them the map is built
    from the mix alone.
    """
    if details_out is None:
        details_out = {}
    # ---- Grid and mix features (cached between calls) -------------------
    if beatfeat is None or beats is None:
        if y is None or sr is None:
            return []
        duration = len(y) / float(sr)
        if duration < 20.0:
            return []
        _g = _sx_grid_and_features(y, sr, bpm_hint)
        if _g is None:
            return []
        beats, bpm, beatfeat = _g
        details_out["bpm"] = bpm
    duration = float(total_duration or beatfeat["duration"])
    details_out["beatfeat"] = beatfeat
    details_out["beats"] = list(beats)
    music_start = float(beatfeat.get("music_start", 0.0) or 0.0)
    music_end = float(beatfeat.get("music_end", duration) or duration)
    music_end = min(music_end, duration)

    # ---- Lyric blocks (optional) ---------------------------------------
    lyric_blocks = []
    if lyric_chunks:
        try:
            if lyric_groups is None:
                lyric_groups = _detect_lyric_repetitions(lyric_chunks)
            lyric_blocks = _lyric_block_segmentation(lyric_chunks, lyric_groups)
        except Exception:
            lyric_blocks = []
    # Chunks timed against the file's own lyrics: split them back into the
    # lyric lines, each placed where the voice sings it, and find where each
    # of the lyrics' own stanzas is sung. That is used only to correct section
    # starts that the arrangement put a little early (below); the evidence and
    # the naming use the chunks exactly as before.
    stanza_blocks = None
    tag_line_list = None
    if lyric_chunks and STRUCTURE_LYRIC_PHRASES and STRUCTURE_TAG_STANZAS and any(
            isinstance(c, dict) and c.get("lines") for c in lyric_chunks):
        try:
            _vn = None
            for _key in ("vocals", "vocal", "voice"):
                if stem_notes and stem_notes.get(_key):
                    _vn = stem_notes[_key]
                    break
            _split = _sx_split_tag_lines(lyric_chunks, None if instrumental else _vn)
            stanza_blocks = _lyric_blocks_from_tag_lines(_split)
            if stanza_blocks is not None:
                tag_line_list = _split
        except Exception:
            stanza_blocks = None
            tag_line_list = None

    # ---- Bars ------------------------------------------------------------
    beats_arr = np.asarray(beats, dtype=float)
    beats_in = beats_arr[(beats_arr >= music_start - 0.05) & (beats_arr <= music_end + 0.05)]
    if beats_in.size < 16:
        beats_in = beats_arr
    accents = beatfeat.get("accents")
    if accents is not None and len(accents) == len(beats_arr):
        acc_in = np.asarray(accents)[(beats_arr >= music_start - 0.05) & (beats_arr <= music_end + 0.05)]
        if acc_in.size != beats_in.size:
            acc_in = None
    else:
        acc_in = None

    # Beats per bar from the accent cycle (3 or 4; 6/8 and 12/8 count in 3s).
    bpb = int(details_out.get("beats_per_bar") or 0) or None
    if bpb is None:
        bpb = 4
        try:
            if acc_in is not None:
                _db, est = _estimate_meter_from_beats(beats_in, acc_in)
                if int(est or 0) in (3, 4):
                    bpb = int(est)
                elif int(est or 0) in (6, 12):
                    bpb = 3
        except Exception:
            bpb = 4
    # Downbeats: a first pass without section events, then -- once the
    # events (fills, drum/vocal entries) are known -- a second pass that
    # lets them pin the bar lines.
    flags0 = _sx_downbeat_flags(beats_in, bpb, acc_in, stem_notes, None)
    bars0 = np.asarray([music_start] + [float(b) for b, f in zip(beats_in, flags0)
                                         if f and music_start + 0.25 < b < music_end - 0.25])
    flags = flags0
    if stem_notes and bars0.size >= 4:
        F0 = _sx_bar_features(beatfeat, bars0, music_end, stem_notes, instrumental)
        _e0, votes = _sx_event_evidence(F0, bars0, music_end, stem_notes, lyric_blocks)
        if votes:
            flags = _sx_downbeat_flags(beats_in, bpb, acc_in, stem_notes, votes)
    bar_list = [float(b) for b, f in zip(beats_in, flags) if f and music_start + 0.25 < b < music_end - 0.25]
    bars = np.asarray([music_start] + bar_list, dtype=float)
    if len(bars) < 2 * STRUCTURE_MIN_SECTION_BARS:
        return []
    details_out["downbeats"] = [float(b) for b, f in zip(beats_in, flags) if f]
    details_out["beats_per_bar"] = bpb
    details_out["beat_len"] = float(np.median(np.diff(beats_arr))) if beats_arr.size > 1 else None

    # Bar features are pooled over the music span only.
    F = _sx_bar_features(beatfeat, bars, music_end, stem_notes, instrumental)

    # Static material (a held tone, a drone, steady noise, a click track):
    # every feature is z-scored per track below, which would blow up tiny
    # fluctuations into convincing-looking section changes. Measured on the
    # RAW features instead, such material barely moves at all.
    try:
        Mraw = np.asarray(F["mfcc"], dtype=float)
        nbr = Mraw.shape[1]
        iu = np.triu_indices(nbr, k=min(4, max(1, nbr - 1)))
        sq = np.sum(Mraw * Mraw, axis=0)
        d2 = np.maximum(sq[:, None] + sq[None, :] - 2.0 * (Mraw.T @ Mraw), 0.0)
        dists = np.sqrt(d2[iu])
        static = (dists.size > 0 and float(np.percentile(dists, 90)) < 12.0
                  and float(np.std(F["loud"])) < 1.5)
    except Exception:
        static = False
    if static:
        out = []
        if music_start > 0.0:
            out.append({"name": "Silence", "start": 0.0, "end": round(music_start, 2), "cluster": "Unique"})
        out.append({"name": "Section", "start": round(music_start, 2), "end": round(music_end, 2), "cluster": "A"})
        if music_end < float(beatfeat.get("duration", duration) or duration) - 0.05 and (duration - music_end) >= STRUCTURE_SILENCE_MIN_S:
            out.append({"name": "Silence", "start": round(music_end, 2), "end": round(float(duration), 2), "cluster": "Unique"})
        out[0]["start"] = 0.0
        out[-1]["end"] = round(float(duration), 2)
        details_out["static"] = True
        details_out["bars"] = bars
        return out

    ev, events, _votes = _sx_evidence_curve(F, bars, music_end, stem_notes, lyric_blocks)
    starts = _sx_boundary_dp(bars, music_end, ev)
    try:
        starts = _sx_shift_off_fill_bar(starts, events, len(bars), bars, music_end)
    except Exception:
        pass
    try:
        starts = _sx_shift_to_reentry(starts, bars, F, music_end, events)
    except Exception:
        pass
    if stanza_blocks and tag_line_list:
        try:
            starts = _sx_refine_starts_to_stanzas(starts, bars, music_end, stanza_blocks, tag_line_list)
        except Exception:
            pass
        if STRUCTURE_STANZA_BACKSHIFT:
            try:
                starts = _sx_backshift_starts_to_stanzas(starts, bars, music_end, stanza_blocks, tag_line_list)
            except Exception:
                pass
    if STRUCTURE_SPLIT_BY_KNOWN_PARTS:
        try:
            starts = _sx_split_by_known_parts(
                F, bars, music_end, starts, lyric_chunks=None if instrumental else lyric_chunks,
                vocal_notes=None if instrumental else _sx_vocal_notes_of(stem_notes))
        except Exception:
            pass
    details_out["dp_starts"] = [float(bars[k]) for k in starts]
    cuts = [0] + list(starts) + [len(bars)]
    segs = [(cuts[k], cuts[k + 1]) for k in range(len(cuts) - 1) if cuts[k + 1] > cuts[k]]
    if not segs:
        return []

    bar_edges = np.concatenate([bars, [music_end]])
    _vn = None
    for _key in ("vocals", "vocal", "voice"):
        if stem_notes and stem_notes.get(_key):
            _vn = stem_notes[_key]
            break

    # dev28: a song that changes key for its last part -- the sections after
    # the change are compared with the rest in their own key (see
    # STRUCTURE_KEY_CHANGE_ALIGN); boundaries are not affected.
    F_same = F
    if STRUCTURE_KEY_CHANGE_ALIGN and not instrumental:
        try:
            _kc = _sx_key_change(F, bars, music_end)
        except Exception:
            _kc = None
        if _kc:
            _cb, _k = _kc
            _ch = np.array(F["chroma"], dtype=float, copy=True)
            _ch[:, _cb:] = np.roll(_ch[:, _cb:], -_k, axis=0)
            F_same = dict(F, chroma=_ch)
            details_out["key_change"] = (float(bars[_cb]), int(_k))

    def _measure_and_name(segs):
        lyric_sig, lyric_rep = (None, None)
        if lyric_chunks:
            try:
                lyric_sig, lyric_rep = _sx_lyric_signatures(segs, bar_edges, lyric_chunks, lyric_groups)
            except Exception:
                lyric_sig, lyric_rep = (None, None)
        lyric_ng = None
        if lyric_chunks and STRUCTURE_LYRIC_PHRASES:
            try:
                lyric_ng = _sx_lyric_ngrams(segs, bar_edges, lyric_chunks,
                                            vocal_notes=None if instrumental else _vn)
            except Exception:
                lyric_ng = None
        W = _sx_segment_similarity(F_same, segs, lyric_sig, lyric_rep, lyric_ng=lyric_ng)
        _name_info = {}
        _smeared = False
        if STRUCTURE_SMEARED_LYRICS_HOOK and lyric_chunks and not instrumental:
            try:
                _smeared = _sx_lyric_timing_smeared(segs, bar_edges, F, lyric_chunks)
            except Exception:
                _smeared = False
        _vocable_only = None
        if STRUCTURE_VOCABLE_INTRO and lyric_chunks and not instrumental:
            try:
                _vo, _lex, _heard = _sx_vocable_only_segments(segs, bar_edges, lyric_chunks)
                # Only when later sections have real words to compare with.
                if sum(1 for x in _lex if x >= 4) >= 2:
                    _vocable_only = _vo
                    _name_info["vocable_counts"] = (list(_heard), list(_lex))
            except Exception:
                _vocable_only = None
        _th = None
        if STRUCTURE_TITLE_PICKS_CHORUS and title and lyric_chunks and not instrumental:
            try:
                _th = _sx_title_hits(segs, bar_edges, lyric_chunks, title)    # dev32
            except Exception:
                _th = None
        names, labels, _cov = _sx_name_sections(
            F, bars, music_end, segs, W, lyric_sig=lyric_sig, lyric_rep=lyric_rep,
            vocal_known=bool(stem_notes), instrumental=instrumental, lyric_ng=lyric_ng,
            lyric_smeared=_smeared, info_out=_name_info, vocable_only=_vocable_only,
            sheet_intro=sheet_intro, lone_sung_verse=lone_sung_verse, title_hits=_th,
        )
        _name_info["_ng"], _name_info["_rep"] = lyric_ng, lyric_rep    # dev31: for the learned namer
        return names, labels, _cov, W, _name_info

    names, labels, _cov, W, _name_info = _measure_and_name(segs)
    if (prechorus_by_words and STRUCTURE_PRECHORUS_BY_WORDS and lyric_chunks and not instrumental
            and stem_notes):
        # dev27: see STRUCTURE_PRECHORUS_BY_WORDS.
        try:
            _pc = _sx_prechorus_cuts(segs, names, bars, music_end, ev, lyric_chunks,
                                     None if instrumental else _vn)
        except Exception:
            _pc = None
        if STRUCTURE_PRECHORUS_BUILDUP_CUTS and not _pc:
            try:
                _pc = _sx_prechorus_cuts_buildup(segs, names, bars, music_end, F, ev)   # dev35
            except Exception:
                _pc = None
        if _pc:
            _st2 = sorted(set(int(k) for k in starts) | set(_pc))
            _cuts2 = [0] + _st2 + [len(bars)]
            _segs2 = [(_cuts2[k], _cuts2[k + 1]) for k in range(len(_cuts2) - 1) if _cuts2[k + 1] > _cuts2[k]]
            try:
                _n2, _l2, _c2, _W2, _ni2 = _measure_and_name(_segs2)
                _n2, _l2 = _sx_mark_prechorus(_segs2, _n2, _l2, _pc)
                if STRUCTURE_PRECHORUS_KEEPS_NAMES and not _sx_names_kept(segs, names, _segs2, _n2):
                    # dev30: see STRUCTURE_PRECHORUS_KEEPS_NAMES -- the first
                    # map's names, on the new lines, with the pre-chorus marked
                    _n2, _l2, _ni2 = _sx_inherit_names(segs, names, labels, _name_info, _segs2, _pc)
            except Exception:
                _n2 = None
            if _n2 is not None:
                starts, segs = _st2, _segs2
                names, labels, _cov, W, _name_info = _n2, _l2, _c2, _W2, _ni2
                details_out["dp_starts"] = [float(bars[k]) for k in starts]
    if learned_namer and not instrumental:
        # dev31: see STRUCTURE_LEARNED_NAMER.
        try:
            names = _sx_learned_namer(segs, names, labels, F, bars, music_end, W, _cov,
                                      _name_info.get("_ng"), _name_info.get("_rep"))
        except Exception:
            pass
    sections = _sx_merge_named(segs, names, labels, bars, music_end, ev, events,
                               keep_split=_name_info.get("keep_split"))
    if STRUCTURE_FINAL_CODA and not instrumental and stem_notes and not _name_info.get("fading_last_chorus"):
        # (dev57: a last chorus that fades out keeps its fade -- no coda split)
        try:
            sections = _sx_split_final_coda(sections, segs, F, W, bars, music_end)
        except Exception:
            pass
    sections = _sx_cluster_letters(sections, labels, segs)
    if STRUCTURE_SPLIT_INSTRUMENTAL and not instrumental and stem_notes:
        try:
            sections = _sx_split_instrumental_edges(sections, F, bars, music_end)
        except Exception:
            pass
    if STRUCTURE_SPLIT_DOUBLE_CHORUS:
        try:
            sections = _sx_split_double_choruses(sections, segs, bars, music_end, ev, F)
        except Exception:
            pass
    if STRUCTURE_SHORT_LEAD_S > 0 and len(sections) >= 2 and not instrumental:
        try:
            sections = _sx_join_short_sung_edges(sections, F, bars, music_end)
        except Exception:
            pass
    if _name_info.get("fading_last_chorus") and len(sections) >= 2:
        # dev57: the near-silent last seconds after a fading last chorus are
        # the end of that fade, not an Outro / Instrumental of their own.
        try:
            last, prev = sections[-1], sections[-2]
            _sl = [float(np.mean(F["loud"][a_:b_])) for (a_, b_) in segs
                   if float(np.mean(F["vocal"][a_:b_])) >= STRUCTURE_SUNG_MIN_COVERAGE]
            _ref = float(np.median(_sl)) if _sl else None
            ka = int(np.searchsorted(bar_edges, float(last["start"]) - 1e-6))
            kb = int(np.searchsorted(bar_edges, float(last["end"]) - 1e-6))
            if (prev.get("name") == "Chorus" and last.get("name") in ("Outro", "Instrumental")
                    and _ref is not None and kb > ka
                    and float(last["end"]) - float(last["start"]) <= 1.5 * STRUCTURE_SHORT_LEAD_S
                    and float(np.mean(F["vocal"][ka:kb])) < STRUCTURE_SUNG_MIN_COVERAGE
                    and float(np.max(F["loud"][ka:kb])) <= _ref - float(STRUCTURE_FADE_TAIL_DB)):
                prev["end"] = last["end"]
                if "_b" in last:
                    prev["_b"] = last["_b"]
                sections = sections[:-1]
        except Exception:
            pass

    audio_dur = float(beatfeat.get("duration", duration) or duration)
    if music_start > 0.0:
        sections.insert(0, {"name": "Silence", "start": 0.0, "end": music_start, "cluster": "Unique"})
    if music_end < audio_dur - 0.05 and (duration - music_end) >= STRUCTURE_SILENCE_MIN_S:
        # Only silence actually measured in the decoded audio becomes a
        # section; a container that reports a slightly longer duration than
        # it decodes to just stretches the last section.
        sections.append({"name": "Silence", "start": music_end, "end": duration, "cluster": "Unique"})
    if STRUCTURE_VERSE_PARTS:
        # dev28: see STRUCTURE_VERSE_PARTS.
        for s in sections:
            try:
                parts = list(s.get("_parts") or [])
                if s.get("name") != "Verse" or len(parts) < 3:
                    continue
                cl = [labels.get(i) for i in parts]
                back = any(cl[x] is not None and cl[x] == cl[z] and cl[y] != cl[x]
                           for x in range(len(cl)) for y in range(x + 1, len(cl)) for z in range(y + 1, len(cl)))
                if back:
                    s["subparts"] = [round(float(bar_edges[segs[i][0]]), 2) for i in parts[1:]]
            except Exception:
                continue
    sections = _sx_number(sections)
    out = []
    for s in sections:
        d = {"name": s["name"], "start": round(float(s["start"]), 2),
             "end": round(float(s["end"]), 2), "cluster": s.get("cluster", "Unique")}
        if s.get("subparts"):
            d["subparts"] = list(s["subparts"])
        out.append(d)
    if out:
        out[0]["start"] = 0.0
        out[-1]["end"] = round(float(duration), 2)
    details_out["evidence"] = ev
    details_out["bars"] = bars
    return out


# Names the audio model may contribute for parts the measurements can only
# call "Instrumental"/"Section". Sung sections are never renamed by it: their
# names come from measured repetition, vocal register and lyrics.
_SX_MOSS_INSTRUMENTAL_ROLES = {
    "solo": "Solo", "guitar solo": "Guitar Solo", "piano solo": "Piano Solo",
    "sax solo": "Sax Solo", "synth solo": "Synth Solo", "keyboard solo": "Keyboard Solo",
    "instrumental solo": "Solo", "breakdown": "Breakdown", "interlude": "Interlude",
    "instrumental break": "Instrumental Break", "break": "Break", "drop": "Drop",
    "build": "Build", "build-up": "Build-Up", "buildup": "Build-Up", "riff": "Riff",
    "instrumental": "Instrumental", "vamp": "Vamp",
}


def _sx_moss_name_hints(sections, audio_path, moss_model, moss_processor):
    """Ask the audio model to name the measured parts. Returns a list of
    (start, end, label) hints; never changes boundaries."""
    if moss_model is None or moss_processor is None or len(sections) < 2:
        return []
    try:
        seg_list = []
        for i, s in enumerate(sections):
            seg_list.append(
                "Part %d (%s - %s, %.0fs): Acoustic Cluster '%s'"
                % (i + 1, _seconds_to_mmss(s["start"]), _seconds_to_mmss(s["end"]),
                   float(s["end"]) - float(s["start"]), s.get("cluster", "Unique"))
            )
        prompt = STRUCTURE_LABELING_PROMPT.format(segment_list="\n".join(seg_list))
        conversation = [{
            "role": "user",
            "content": [
                {"type": "text", "text": prompt},
                {"type": "audio", "path": audio_path},
            ],
        }]
        status("Naming measured structure segments with the audio model...")
        reply = moss_generate(moss_model, moss_processor, conversation, max_new_tokens=384)
        labels = _parse_structure_labels(reply, len(sections))
    except Exception as e:
        print("  (structure naming pass skipped: %s)" % e)
        return []
    hints = []
    for idx, label in labels.items():
        s = sections[idx - 1]
        hints.append((float(s["start"]), float(s["end"]), str(label)))
    return hints


def _sx_apply_moss_hints(sections, hints):
    """Adopt the audio model's name only for unsung parts the measurements
    could name just generically, and only where its part overlaps ours."""
    if not sections or not hints:
        return sections
    out = [dict(s) for s in sections]
    for s in out:
        base = re.sub(r"\s*\d+\s*$", "", str(s.get("name") or "")).strip()
        if base not in ("Instrumental", "Section"):
            continue
        a, b = float(s["start"]), float(s["end"])
        best, best_ov = None, 0.0
        for ha, hb, lab in hints:
            ov = min(b, hb) - max(a, ha)
            if ov > best_ov:
                best_ov, best = ov, lab
        if best is None or best_ov < 0.6 * max(1e-6, b - a):
            continue
        key = re.sub(r"\s*\d+\s*$", "", best).strip().lower()
        if key in _SX_MOSS_INSTRUMENTAL_ROLES:
            s["name"] = _SX_MOSS_INSTRUMENTAL_ROLES[key]
    # Re-number after renaming.
    for s in out:
        s["name"] = re.sub(r"\s*\d+\s*$", "", str(s["name"])).strip()
    return _sx_number(out)


# ==============================================================================
# PRODUCTION / MIX MEASUREMENTS
# ==============================================================================
# TIMBRE asks the writer for "stereo image, ambience, reverb, saturation/
# distortion, transient character", the genre prompt asks it to weigh
# "sidechain pump" and "club loudness vs garage band dynamics", and the era
# prompt asks about "stereo image and panning conventions" and "room/plate/
# digital reverb characteristics" -- but nothing in the pipeline measured any
# of that. Everything upstream loads the file with mono=True, so stereo was
# structurally invisible, and the only production numbers available were
# loudness/crest plus first-60s spectral stats. That left those fields to be
# filled from the writer's impression, or from genre expectation.
#
# These measurements are deliberately conservative: each is reported as a
# number with a plain-language reading, and each runs in its own try/except so
# a failure degrades that one line rather than the report.

# (PRODUCTION_ANALYSIS_ENABLED moved to the USER CONFIGURATION section near the top of this file.)
# Excerpts are spread evenly across the whole file rather than analysing one
# contiguous chunk, so an atypical intro cannot define the track's profile.
# (PRODUCTION_EXCERPT_COUNT moved to the USER CONFIGURATION section near the top of this file.)
# (PRODUCTION_EXCERPT_SECONDS moved to the USER CONFIGURATION section near the top of this file.)
# Sample rate for the continuous envelope analyses (pumping, ambience decay).
# The features live well below 5 kHz, so decoding at full rate would cost
# memory for no accuracy.
# (PRODUCTION_ENVELOPE_SR moved to the USER CONFIGURATION section near the top of this file.)


def _prod_excerpt_offsets(duration, count=None, seconds_each=None):
    """Evenly spaced excerpt start times covering the whole track, skipping
    the very start and very end (fades and silence would skew every
    measurement that follows)."""
    count = int(count or PRODUCTION_EXCERPT_COUNT)
    seconds_each = float(seconds_each or PRODUCTION_EXCERPT_SECONDS)
    if not duration or duration <= 0:
        return []
    if duration <= seconds_each * 1.5:
        return [0.0]
    edge = min(2.0, duration * 0.02)
    first = edge
    last = max(first, duration - seconds_each - edge)
    if last <= first:
        return [first]
    count = max(1, min(count, int((last - first) / max(1.0, seconds_each * 0.5)) + 1))
    if count == 1:
        return [(first + last) / 2.0]
    return [first + (last - first) * i / float(count - 1) for i in range(count)]


def _prod_load_excerpts(local_path, duration, mono=False):
    """Load evenly spaced excerpts at NATIVE sample rate (needed for the
    high-frequency cutoff measurement) preserving channels (needed for the
    stereo field measurement). Returns (list_of_arrays, sr) where each array
    is (channels, n) for stereo or (n,) for mono."""
    offsets = _prod_excerpt_offsets(duration)
    chunks = []
    sr = None
    for off in offsets:
        try:
            y, this_sr = librosa.load(
                local_path, sr=None, mono=mono,
                offset=float(off), duration=float(PRODUCTION_EXCERPT_SECONDS),
            )
        except Exception:
            continue
        if y is None or np.size(y) == 0:
            continue
        sr = this_sr
        chunks.append(np.asarray(y, dtype=np.float32))
    return chunks, sr


def _prod_split_lr(chunk):
    """Return (left, right) or (mono, None) from a librosa-shaped array."""
    arr = np.asarray(chunk)
    if arr.ndim == 1:
        return arr, None
    if arr.shape[0] == 1:
        return arr[0], None
    if arr.shape[0] >= 2:
        return arr[0], arr[1]
    return arr.reshape(-1), None


def _prod_stereo_field(chunks, sr):
    """Stereo image measurements: correlation, mid/side balance overall and by
    band, and mono-fold-down loss.

    Nothing else in the pipeline sees stereo at all, so width, panning
    convention and mono compatibility previously had no evidence behind them.
    Per-band width matters especially at the low end: a centred bass is a
    near-universal modern mastering convention, so an uncorrelated low end is
    a genuine signal about era or how finished the master is.
    """
    lines = []
    lefts, rights = [], []
    for c in chunks:
        L, R = _prod_split_lr(c)
        if R is None:
            continue
        n = min(len(L), len(R))
        if n > 0:
            lefts.append(L[:n])
            rights.append(R[:n])

    if not lefts:
        lines.append("channel format: mono (single channel) — no stereo image to assess")
        return lines

    L = np.concatenate(lefts).astype(np.float64)
    R = np.concatenate(rights).astype(np.float64)
    if len(L) < 1000:
        return lines

    mid = (L + R) * 0.5
    side = (L - R) * 0.5
    mid_e = float(np.mean(mid ** 2))
    side_e = float(np.mean(side ** 2))

    if mid_e <= 1e-12 and side_e <= 1e-12:
        lines.append("stereo field: unavailable (silent excerpts)")
        return lines

    # A file can be stereo-format but dual-mono in content.
    if side_e <= mid_e * 1e-7:
        lines.append(
            "channel format: stereo file carrying identical channels (dual mono) "
            "— no true stereo image"
        )
        return lines

    denom = float(np.sqrt(np.mean(L ** 2) * np.mean(R ** 2)))
    corr = float(np.mean(L * R) / denom) if denom > 1e-12 else 0.0
    corr = max(-1.0, min(1.0, corr))
    width_db = 10.0 * np.log10(max(side_e, 1e-20) / max(mid_e, 1e-20))

    lines.append(f"stereo correlation (L/R): {round(corr, 3)} (1.0=mono, 0=uncorrelated, <0=out of phase)")
    lines.append(f"side/mid energy ratio: {round(float(width_db), 1)} dB")

    if corr >= 0.95:
        desc = "very narrow / essentially centred"
    elif corr >= 0.75:
        desc = "narrow-to-moderate width"
    elif corr >= 0.4:
        desc = "conventional stereo width"
    elif corr >= 0.05:
        desc = "wide stereo image"
    else:
        desc = "very wide / heavily decorrelated"
    lines.append(f"stereo width reading: {desc}")

    if corr < 0.0:
        lines.append(
            "phase note: net negative L/R correlation — significant out-of-phase content "
            "(wide stereo processing, or a phase problem); would partially cancel in mono."
        )

    # Mono fold-down loss: how much energy disappears when summed to mono.
    stereo_e = float(np.mean((L ** 2 + R ** 2) * 0.5))
    mono_e = float(np.mean(mid ** 2))
    if stereo_e > 1e-12:
        fold = 10.0 * np.log10(max(mono_e, 1e-20) / stereo_e)
        lines.append(f"mono fold-down level change: {round(float(fold), 1)} dB")
        if fold < -3.0:
            lines.append(
                "mono compatibility: substantial cancellation when summed to mono "
                "(heavy widening or phase issues)."
            )

    # Per-band width. Bass centring is the informative one.
    try:
        n_fft = 2048
        Sm = np.abs(librosa.stft(mid.astype(np.float32), n_fft=n_fft, hop_length=1024))
        Ss = np.abs(librosa.stft(side.astype(np.float32), n_fft=n_fft, hop_length=1024))
        freqs = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
        bands = [("low (20-120 Hz)", 20, 120), ("low-mid (120-800 Hz)", 120, 800),
                 ("mid (800-4k Hz)", 800, 4000), ("high (4k-16k Hz)", 4000, 16000)]
        parts = []
        low_ratio = None
        for name, lo, hi in bands:
            mask = (freqs >= lo) & (freqs < hi)
            if not np.any(mask):
                continue
            m_e = float(np.sum(Sm[mask] ** 2))
            s_e = float(np.sum(Ss[mask] ** 2))
            if m_e <= 1e-12:
                continue
            ratio_db = 10.0 * np.log10(max(s_e, 1e-20) / m_e)
            parts.append(f"{name}: {round(float(ratio_db), 1)} dB")
            if lo == 20:
                low_ratio = ratio_db
        if parts:
            lines.append("stereo width by band (side/mid, higher = wider): " + "; ".join(parts))
        if low_ratio is not None:
            if low_ratio < -18.0:
                lines.append(
                    "low-end imaging: bass is strongly centred — the standard modern "
                    "mastering convention (elliptical/mono-below filtering)."
                )
            elif low_ratio > -8.0:
                lines.append(
                    "low-end imaging: unusually wide/uncorrelated low end — more typical of "
                    "older, unmastered, or deliberately unconventional productions."
                )
    except Exception:
        pass

    return lines


def _full_file_clip_runs(path, threshold=0.9995, min_run=4, block_frames=262144):
    """Count flat-topped clipping over the WHOLE file, streaming the decode.

    Returns (clipped_runs, clipped_samples, total_samples) or None when the file
    cannot be decoded this way. Runs are counted per channel and may span the
    decoder's block boundaries. Uses ffmpeg so every container the rest of the
    pipeline accepts works, without holding the whole file in memory.
    """
    if not path or str(path).startswith(("http://", "https://")) or not os.path.exists(str(path)):
        return None
    try:
        pr = subprocess.run(
            ["ffprobe", "-v", "error", "-select_streams", "a:0",
             "-show_entries", "stream=channels", "-of", "default=nw=1:nk=1", str(path)],
            capture_output=True, text=True, timeout=60,
        )
        ch = int((pr.stdout or "").strip().splitlines()[0])
        if ch < 1:
            return None
    except Exception:
        return None
    try:
        proc = subprocess.Popen(
            ["ffmpeg", "-v", "error", "-nostdin", "-i", str(path), "-map", "0:a:0",
             "-f", "f32le", "-acodec", "pcm_f32le", "-"],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
        )
    except Exception:
        return None
    runs = 0
    clipped = 0
    total = 0
    carry = [0] * ch            # length of a hot run still open at the block edge
    leftover = b""
    frame_bytes = 4 * ch
    try:
        while True:
            data = proc.stdout.read(block_frames * frame_bytes)
            if not data:
                break
            data = leftover + data
            usable = (len(data) // frame_bytes) * frame_bytes
            leftover = data[usable:]
            if usable == 0:
                continue
            arr = np.frombuffer(data[:usable], dtype=np.float32).reshape(-1, ch)
            total += arr.size
            hot_all = np.abs(arr) >= float(threshold)
            for c in range(ch):
                hot = hot_all[:, c]
                if not np.any(hot):
                    if carry[c] >= min_run:
                        runs += 1
                        clipped += carry[c]
                    carry[c] = 0
                    continue
                edges = np.diff(np.concatenate(([0], hot.view(np.int8), [0])))
                starts = np.flatnonzero(edges == 1)
                ends = np.flatnonzero(edges == -1)
                lengths = (ends - starts).tolist()
                if starts[0] == 0:
                    lengths[0] += carry[c]          # continues a run from the last block
                elif carry[c] >= min_run:
                    runs += 1
                    clipped += carry[c]
                carry[c] = 0
                if ends[-1] == hot.size:            # still open at this block's end
                    carry[c] = lengths.pop()
                for L in lengths:
                    if L >= min_run:
                        runs += 1
                        clipped += L
        for c in range(ch):
            if carry[c] >= min_run:
                runs += 1
                clipped += carry[c]
        proc.wait(timeout=60)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
        return None
    if total == 0:
        return None
    return runs, clipped, total


def _prod_peaks_and_clipping(local_path, chunks):
    """True peak, peak-to-loudness ratio, and digital clipping estimate.

    ffmpeg already computes a true-peak figure during the loudness pass but it
    was parsed and then discarded; it is the single most direct indicator of
    how hard a master was pushed. Clipped-sample runs are counted separately,
    since intersample overs and actual flat-topped clipping are different
    production facts.
    """
    lines = []
    lufs = tp = None
    try:
        lufs, _lra, tp, _src = _ffmpeg_ebur128_loudness(local_path)
    except Exception:
        pass

    if tp is not None:
        lines.append(f"true peak: {round(float(tp), 1)} dBTP")
        if tp > 0.0:
            lines.append(
                "true-peak note: exceeds 0 dBTP — intersample overs, typical of a loud "
                "master pushed to (or past) the ceiling; can distort on lossy playback."
            )
        elif tp > -0.3:
            lines.append("true-peak note: mastered right up against the ceiling.")

    if tp is not None and lufs is not None:
        plr = float(tp) - float(lufs)
        lines.append(f"peak-to-loudness ratio (PLR): {round(plr, 1)} dB")
        if plr < 8.0:
            lines.append(
                "PLR reading: very low — heavily limited/compressed master "
                "(loudness-maximised)."
            )
        elif plr < 12.0:
            lines.append("PLR reading: moderate — conventional contemporary master.")
        else:
            lines.append("PLR reading: high — dynamic, lightly limited master.")

    # Flat-topped clipping: consecutive samples pinned near full scale. Scanned
    # over the whole file -- the excerpts below cover only about a third of a
    # typical track, so "none" from them meant little (on one test master the
    # excerpts found 2 of 5 clipped runs).
    full = None
    try:
        full = _full_file_clip_runs(local_path)
    except Exception:
        full = None
    if full is not None:
        clipped_runs, clipped_samples, total = full
        if clipped_runs > 0:
            rate = clipped_samples / float(total) * 1e6
            lines.append(
                f"clipped-sample runs detected (whole file): {clipped_runs} "
                f"({round(rate, 1)} clipped samples per million)"
            )
            lines.append(
                "clipping note: flat-topped samples at full scale — the master is "
                "clipped, either deliberately for loudness or from a gain-staging error."
            )
        else:
            lines.append("clipped-sample runs detected (whole file): none")
        return lines

    try:
        total = 0
        clipped_runs = 0
        clipped_samples = 0
        for c in chunks:
            L, R = _prod_split_lr(c)
            for ch in (L, R):
                if ch is None or len(ch) == 0:
                    continue
                a = np.abs(np.asarray(ch, dtype=np.float32))
                total += a.size
                hot = a >= 0.9995
                if not np.any(hot):
                    continue
                # Count runs of >= 4 consecutive at-ceiling samples.
                idx = np.flatnonzero(
                    np.diff(np.concatenate(([0], hot.view(np.int8), [0]))) != 0
                )
                for s, e in zip(idx[0::2], idx[1::2]):
                    if e - s >= 4:
                        clipped_runs += 1
                        clipped_samples += int(e - s)
        if total > 0 and clipped_runs > 0:
            rate = clipped_samples / float(total) * 1e6
            lines.append(
                f"clipped-sample runs detected (sampled excerpts only): {clipped_runs} "
                f"({round(rate, 1)} clipped samples per million)"
            )
            lines.append(
                "clipping note: flat-topped samples at full scale — the master is "
                "clipped, either deliberately for loudness or from a gain-staging error."
            )
        elif total > 0:
            lines.append(
                "clipped-sample runs detected: none in the sampled excerpts (the whole "
                "file could not be scanned, so clipping elsewhere is not ruled out)"
            )
    except Exception:
        pass

    return lines


_LOSSY_AUDIO_EXTS = {".mp3", ".aac", ".ogg", ".oga", ".opus", ".wma", ".mp2", ".mpc", ".webm"}
_LOSSLESS_AUDIO_EXTS = {".wav", ".wave", ".flac", ".aif", ".aiff", ".aifc", ".w64", ".ape", ".wv"}


def _prod_hf_cutoff(chunks, sr, source_path=None):
    """Highest frequency carrying real energy, plus whether it ends in a sharp
    shelf. A brickwall well below Nyquist is the fingerprint of lossy encoding
    (or an old/band-limited source), which is real provenance information: it
    tells the writer this file may not be the full-quality master, and it is a
    genuine era/format clue that nothing else in the pipeline provides.

    Detection scans for the steepest sustained drop rather than thresholding
    against a fixed level, because a fixed threshold is defeated by spectral
    tilt: a bass-heavy mix has so little midrange reference energy that a
    dither/noise floor at 20 kHz can sit within any reasonable margin of it.
    A brickwall is a *shape* — a cliff — so the cliff is what is measured.
    """
    lines = []
    if not chunks or not sr:
        return lines
    nyq = sr / 2.0
    try:
        n_fft = 4096
        spec_sum = None
        frames = 0
        for c in chunks:
            L, R = _prod_split_lr(c)
            mono = L if R is None else (L[: min(len(L), len(R))] + R[: min(len(L), len(R))]) * 0.5
            if len(mono) < n_fft:
                continue
            S = np.abs(librosa.stft(np.asarray(mono, dtype=np.float32),
                                    n_fft=n_fft, hop_length=n_fft // 2))
            if S.size == 0:
                continue
            spec_sum = np.sum(S ** 2, axis=1) if spec_sum is None else spec_sum + np.sum(S ** 2, axis=1)
            frames += S.shape[1]
        if spec_sum is None or frames == 0:
            return lines

        freqs = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
        db = 10.0 * np.log10(np.maximum(spec_sum / float(frames), 1e-20))

        # Smooth over ~250 Hz so individual partials don't read as cliffs.
        bin_hz = float(freqs[1] - freqs[0]) if len(freqs) > 1 else 1.0
        w = max(1, int(250.0 / max(bin_hz, 1e-6)))
        if w % 2 == 0:
            w += 1
        pad = w // 2
        sm = np.convolve(np.pad(db, (pad, pad), mode="edge"),
                         np.ones(w) / w, mode="valid")[: len(db)]

        peak_db = float(np.max(sm))

        # Scan for the steepest 1.2 kHz-either-side drop above 5 kHz.
        best_f, best_drop = None, 0.0
        lo_i = int(np.searchsorted(freqs, 5000.0))
        hi_i = int(np.searchsorted(freqs, nyq * 0.985))
        step = max(1, (hi_i - lo_i) // 240)
        for i in range(lo_i, hi_i, step):
            f = float(freqs[i])
            below = (freqs >= f - 1200) & (freqs < f)
            above = (freqs > f) & (freqs <= f + 1200)
            if not np.any(below) or not np.any(above):
                continue
            drop = float(np.median(sm[below]) - np.median(sm[above]))
            if drop > best_drop:
                best_drop, best_f = drop, f

        sharp = best_f is not None and best_drop >= 18.0

        if sharp:
            # Corner frequency: last point still within 10 dB of the shelf's
            # pre-drop level, which lands on the knee rather than mid-slope.
            pre = (freqs >= best_f - 1200) & (freqs < best_f)
            pre_level = float(np.median(sm[pre])) if np.any(pre) else peak_db
            within = np.flatnonzero((sm >= pre_level - 10.0) & (freqs <= best_f + 1200))
            cutoff = float(freqs[within[-1]]) if len(within) else best_f
        else:
            floor = peak_db - 65.0
            above_floor = np.flatnonzero(sm >= floor)
            cutoff = float(freqs[above_floor[-1]]) if len(above_floor) else nyq

        lines.append(
            f"upper frequency limit: ~{int(round(cutoff / 100.0) * 100)} Hz "
            f"(file Nyquist {int(nyq)} Hz)"
        )
        if sharp:
            lines.append(
                f"cutoff character: sharp shelf (~{int(round(best_drop))} dB drop) — a "
                "brickwall lowpass rather than a natural rolloff"
            )

        # The container tells whether the file ITSELF is a lossy encode. A
        # lossless file (WAV/FLAC/AIFF) with a sharp shelf got its band limit
        # upstream -- an earlier lossy encode, a band-limited generator or
        # synth (AI music generators commonly produce exactly this), or
        # resampling -- and an AI-generated test track, a WAV straight from its generator, was
        # told it had "very probably been through lossy compression". m4a is
        # left as unknown: it can hold AAC or lossless ALAC.
        _ext = os.path.splitext(str(source_path or ""))[1].lower()
        _container = ("lossy" if _ext in _LOSSY_AUDIO_EXTS
                      else "lossless" if _ext in _LOSSLESS_AUDIO_EXTS else "")
        _fmt = _ext[1:].upper() if _ext else ""

        # Only interpret as a codec fingerprint when the ceiling is genuinely
        # below what the container could have carried.
        if cutoff < nyq * 0.93:
            if cutoff >= 19000:
                # A sharp shelf at 19-20 kHz is just as typical of a resampler's
                # anti-alias filter, a DAW/mastering low-pass or a soft-synth's
                # band limit as of a 256-320 kbps encode, so it proves nothing.
                note = ("high-bitrate lossy encoding (~256 kbps+) OR a sample-rate-conversion / "
                        "mastering / instrument low-pass -- a ceiling this high is NOT proof of "
                        "lossy compression")
                if _container == "lossy" and sharp:
                    # ...unless the file IS a lossy encode, when its own
                    # encoder's low-pass is the obvious explanation.
                    note = (f"high-bitrate lossy encoding (~256 kbps+) -- this file is itself a "
                            f"lossy {_fmt}, so the shelf is most likely its own encoder's low-pass")
                source_like = ""
            elif cutoff >= 16500:
                note = "consistent with mid-bitrate lossy encoding (roughly 160-192 kbps)"
                source_like = "a mid-bitrate (roughly 160-192 kbps) lossy encode"
            elif cutoff >= 14500:
                note = "consistent with ~128 kbps lossy encoding"
                source_like = "a ~128 kbps lossy encode"
            elif cutoff >= 10000:
                note = ("strongly band-limited — low-bitrate encoding, an analogue/broadcast "
                        "source, or deliberate lo-fi")
                source_like = ("low-bitrate encoding, an analogue/broadcast source or "
                               "deliberate lo-fi")
            else:
                note = ("very band-limited — a low-quality, very old, or deliberately "
                        "degraded source")
                source_like = "a low-quality, very old or deliberately degraded source"
            if _container == "lossless" and sharp and cutoff < 19000:
                note = (f"band-limited source -- the shelf sits where {source_like} "
                        f"would leave it, but this file is lossless ({_fmt}), so the limit was "
                        "introduced before the file was written")
            lines.append(f"bandwidth reading: {note}")
            if sharp and _container == "lossy":
                lines.append(
                    f"provenance caution: this file is itself a lossy {_fmt} encode, so the shelf is "
                    + ("most likely its encoder's low-pass at a low bitrate (or the source was "
                       "already band-limited)" if cutoff < 14500 else "its encoder's low-pass")
                    + " and the very top end is not the original master. Do not "
                    "read the missing top octave as a mixing or era choice."
                )
            elif sharp and _container == "lossless" and cutoff < 19000:
                lines.append(
                    f"provenance caution: the file itself is lossless ({_fmt}) but its spectrum "
                    "stops sharply, so the band limit came from upstream -- an earlier lossy "
                    "encode, a band-limited synthesis or source, or resampling from a lower "
                    "rate. Do not read the missing top "
                    "octave as a mixing or era choice, and do not call the file itself lossy or "
                    "transcoded."
                )
            elif sharp and cutoff < 19000:
                lines.append(
                    "provenance caution: this file has very probably been through lossy "
                    "compression at some point, so the very top end is not the original master. "
                    "Do not read the missing top octave as a mixing or era choice by itself."
                )
            elif sharp:
                lines.append(
                    "provenance note: the top end above the shelf is inaudible to most listeners; "
                    "do not describe the recording as lossy, degraded or transcoded on this "
                    "evidence alone."
                )
        else:
            lines.append(
                "bandwidth reading: full-band up to the file's own limit — no evidence of "
                "aggressive lossy band-limiting"
            )
    except Exception:
        pass
    return lines


def _beat_phase_shape(y, sr, beat_times, bins=24):
    """Fold the HARMONIC midrange (300 Hz-5 kHz) level onto the beat and read
    the shape of the average beat.

    Returns (shape, folded_range_db) where shape is
      "duck"   -- sharp drop, slow recovery: what a sidechain compressor does;
      "attack" -- sharp rise, slow decay: parts played ON the beat (strums,
                  stabs, picked figures);
      "weak"   -- the per-beat swings do not add up to a consistent shape
                  (folded range below BEAT_FOLD_MIN_CONSISTENT_DB), so they
                  are playing dynamics, not a compressor;
      None     -- not measurable, or neither shape is clear.

    The shape test uses only the ratio of the steepest rise to the steepest
    drop of the folded profile, so it does not depend on where the beat tracker
    put the beat (checked at +/-40 ms offsets). Percussive hits are removed
    first (soft HPSS at 11.025 kHz) so a snare cannot pose as an attack.
    """
    bt = np.asarray(beat_times if beat_times is not None else [], dtype=float)
    if bt.size < 8:
        return None, None
    # A beat grid found at half speed folds two real beats into one, which
    # blurs the shape. Subdivide until the fold period is a plausible beat.
    for _ in range(3):
        if float(np.median(np.diff(bt))) <= 0.75:
            break
        bt = np.sort(np.concatenate([bt, (bt[:-1] + bt[1:]) / 2.0]))
    sr_p = 11025 if sr > 11025 else sr
    yp = np.asarray(y, dtype=np.float32)
    if sr_p != sr:
        yp = librosa.resample(yp, orig_sr=sr, target_sr=sr_p)
    hop = 256   # ~23 ms
    f = librosa.fft_frequencies(sr=sr_p, n_fft=1024)
    m = (f >= 300.0) & (f < min(5000.0, sr_p / 2.0 - 1.0))
    # HPSS in 60 s blocks (+2 s context each side, far wider than the median
    # kernel) so peak memory stays ~100 MB whatever the track length.
    blk, ctx = 60 * sr_p, 2 * sr_p
    parts = []
    for a in range(0, len(yp), blk):
        lo, hi = max(0, a - ctx), min(len(yp), a + blk + ctx)
        Sm = np.abs(librosa.stft(yp[lo:hi], n_fft=1024, hop_length=hop, center=True))
        H = librosa.decompose.hpss(Sm, margin=1.0)[0]
        e = np.sqrt(np.mean(H[m] ** 2, axis=0))
        f0 = (a - lo) // hop
        n_keep = int(np.ceil(min(blk, len(yp) - a) / float(hop)))
        parts.append(e[f0:f0 + n_keep])
        del Sm, H
    band = np.concatenate(parts) if parts else np.zeros(0)
    if band.size < 32:
        return None, None
    db = 20.0 * np.log10(np.maximum(band, float(np.median(band)) * 1e-3 + 1e-12))
    fr = sr_p / float(hop)
    win = max(3, int(fr * 4.0)) | 1
    trend = np.convolve(np.pad(db, (win // 2, win // 2), mode="edge"), np.ones(win) / win, mode="valid")[: len(db)]
    detr = db - trend
    t = np.arange(len(detr)) / fr
    # Sample each beat at fixed phase points (interpolated), so the phase bins
    # never go empty when a bin is shorter than a frame.
    frac = (np.arange(bins) + 0.5) / float(bins)
    rows = []
    for a, b in zip(bt[:-1], bt[1:]):
        if b - a <= 0.1 or b > t[-1]:
            continue
        rows.append(np.interp(a + frac * (b - a), t, detr))
    if len(rows) < 8:
        return None, None
    prof = np.mean(rows, axis=0)
    rng = float(prof.max() - prof.min())
    if rng < BEAT_FOLD_MIN_CONSISTENT_DB:
        return "weak", rng
    q = np.convolve(np.concatenate([prof[-1:], prof, prof[:1]]), np.ones(3) / 3.0, mode="valid")
    d = np.diff(np.concatenate([q, q[:1]]))
    rise, drop = float(d.max()), float(-d.min())
    if drop <= 1e-9:
        return "attack", rng
    ratio = rise / drop
    if ratio <= 0.75:
        return "duck", rng
    if ratio >= 1.3:
        return "attack", rng
    return None, rng


def _prod_pumping(y, sr, beat_times=None):
    """Beat-synchronous amplitude modulation: objective evidence for
    sidechain-style pumping.

    The genre prompt explicitly asks the writer to weigh "sidechain pump" when
    choosing between electronic/dance and band-based genres, but nothing
    measured it, so that call rested on impression alone.

    Crucially this is measured in a MID BAND (roughly 300 Hz - 5 kHz), not on
    the full-mix envelope. A loud kick raises full-mix level at every beat, so
    full-mix ducking depth is nearly identical for a sidechained track and for
    one with a merely hard-hitting backbeat (measured: 11.6 dB vs 11.8 dB —
    indistinguishable). A kick contributes little above 300 Hz, so it cannot
    make a pad's midrange duck; only a compressor can. In the mid band the same
    two cases separate cleanly (11.1 dB vs 0.7 dB).

    The reliable, high-value output is the NEGATIVE: when the sustained bed
    plainly does not duck, the writer can say so with confidence. A positive
    reading is reported as consistent-with rather than proof, because a long
    reverb tail re-excited every beat produces a similar mid-band envelope.
    """
    lines = []
    try:
        hop = 512
        frame_rate = sr / float(hop)

        # Beat period, preferring measured beats over a raw tempo estimate.
        beat_period = None
        if beat_times is not None and len(beat_times) > 2:
            d = np.diff(np.asarray(beat_times, dtype=float))
            d = d[(d > 0.15) & (d < 2.5)]
            if len(d):
                beat_period = float(np.median(d))
        if not beat_period:
            return lines

        S = np.abs(librosa.stft(np.asarray(y, dtype=np.float32), n_fft=2048, hop_length=hop))
        if S.size == 0 or S.shape[1] < 32:
            return lines
        freqs = librosa.fft_frequencies(sr=sr, n_fft=2048)
        mask = (freqs >= 300.0) & (freqs < min(5000.0, sr / 2.0 - 1.0))
        if not np.any(mask):
            return lines
        band = np.sqrt(np.mean(S[mask] ** 2, axis=0))
        if band.size < 32:
            return lines

        # Floor relative to the band's own level, so near-silent passages
        # cannot produce absurd dB swings.
        med = float(np.median(band))
        floor = max(med * 1e-3, 1e-10)
        band_db = 20.0 * np.log10(np.maximum(band, floor))
        times = librosa.frames_to_time(np.arange(len(band_db)), sr=sr, hop_length=hop)

        # Guard: is there a sustained bed to duck at all? On a percussion-only
        # track the mid band is pure transients, so "ducking" between hits is
        # just silence and means nothing about compression.
        spread = float(np.percentile(band_db, 90) - np.percentile(band_db, 50))
        if spread > 20.0:
            lines.append(
                "sidechain assessment: not assessable — the 300 Hz-5 kHz range is almost "
                "entirely transient, with no sustained bed that could be ducked."
            )
            return lines

        # Detrend so slow arrangement dynamics don't read as beat-rate pumping.
        win = max(3, int(frame_rate * 4.0))
        if win % 2 == 0:
            win += 1
        pad = win // 2
        trend = np.convolve(np.pad(band_db, (pad, pad), mode="edge"),
                            np.ones(win) / win, mode="valid")[: len(band_db)]
        detr = band_db - trend
        detr = detr - float(np.mean(detr))
        if float(np.std(detr)) < 1e-6:
            return lines

        ac_full = np.correlate(detr, detr, mode="full")[len(detr) - 1:]
        if ac_full[0] <= 0:
            return lines
        ac = ac_full / ac_full[0]
        lag = int(round(beat_period * frame_rate))
        if lag < 2 or lag >= len(ac):
            return lines
        span = max(1, int(lag * 0.12))
        beat_ac = float(np.max(ac[max(1, lag - span):min(len(ac), lag + span + 1)]))

        depths = []
        bt = np.asarray(beat_times, dtype=float)
        for i in range(len(bt) - 1):
            s, e = bt[i], bt[i + 1]
            if e - s <= 0.05:
                continue
            seg = band_db[(times >= s) & (times < e)]
            if seg.size >= 4:
                depths.append(float(np.max(seg) - np.min(seg)))
        if not depths:
            return lines
        med_depth = float(np.median(depths))

        lines.append(
            f"beat-locked modulation of the sustained bed (300 Hz-5 kHz): "
            f"{round(beat_ac, 3)} (0=none, 1=perfectly periodic)"
        )
        lines.append(f"median per-beat ducking depth in that band: {round(med_depth, 1)} dB")

        if med_depth < 3.0 or beat_ac < 0.15:
            lines.append(
                "sidechain reading: the sustained bed does NOT duck with the beat — this track "
                "is not sidechained/pumping. Do not describe it as pumping, and do not use "
                "pumping as an argument for an electronic/dance genre label."
            )
        elif med_depth >= 6.0 and beat_ac >= 0.30:
            # Beat-locked level movement has two opposite causes. Sidechain
            # ducking pulls the bed DOWN just after each beat and lets it swell
            # back; parts that play ON the beat (strummed or stabbed chords,
            # picked riffs) push the level UP at each beat and let it decay.
            # The depth/periodicity numbers above cannot tell them apart -- a
            # strummed-guitar rock track read as "sidechain, a dance/electronic
            # signature". Where in the beat the harmonic level peaks can.
            shape, fold_db = None, None
            try:
                shape, fold_db = _beat_phase_shape(y, sr, beat_times)
            except Exception:
                shape, fold_db = None, None
            if shape == "weak":
                lines.append(
                    f"sidechain reading: the per-beat swings average out to only {fold_db:.1f} dB "
                    "when folded onto the beat -- they are not a consistent duck-and-recover, so "
                    "this is NOT sidechain pumping (playing dynamics / on-beat parts). Do not use it "
                    "as an argument for a dance/electronic label."
                )
            elif shape == "attack":
                lines.append(
                    "sidechain reading: the beat-locked movement comes from parts that play ON "
                    "the beat (strummed or stabbed chords, picked figures) -- the level jumps at "
                    "each beat and decays, rather than ducking and recovering. This is NOT "
                    "sidechain pumping; do not use it as an argument for a dance/electronic label."
                )
            elif shape == "duck":
                lines.append(
                    "sidechain reading: the sustained bed ducks strongly in lockstep with the beat "
                    "and recovers between beats — consistent with sidechain compression, a "
                    "dance/electronic production signature. Caveat: a long reverb tail "
                    "re-triggered each beat can produce a similar envelope, so check this against "
                    "the ambience measurement below."
                )
            else:
                lines.append(
                    "sidechain reading: strong beat-locked level movement, but its shape is "
                    "ambiguous (neither a clear duck-and-recover nor an on-beat attack) -- could "
                    "be sidechain, rhythmic gating or simply the arrangement. Do not assert pumping."
                )
        else:
            lines.append(
                "sidechain reading: mild beat-locked movement in the sustained bed — could be "
                "light sidechain, rhythmic gating, or simply arrangement. Not strong enough to "
                "assert pumping."
            )
    except Exception:
        pass
    return lines


def _prod_ambience(y, sr):
    """Reverb/ambience proxy from post-transient energy decay.

    TIMBRE and the era prompt both ask about reverb and room character with no
    measurement behind them. Decay rate after transients is a legitimate proxy:
    a dry, close-miked or heavily gated production decays fast, a plate/hall or
    washy production decays slowly. Reported as a proxy, not an RT60 claim.

    Two readings are made. On the full mix, anything that keeps sounding after
    a hit -- held chords, pads, strings -- reads as "decay", so a dense or
    sustained arrangement came out "very washy/reverb-heavy" whatever its
    reverb (and often pinned at the 6 s ceiling). The same measurement on the
    percussive component (harmonic/percussive separation) follows the tails of
    the hits themselves, which is much closer to the room/reverb on them; the
    ambience reading now comes from that one, and the full-mix figure is
    reported as sustain.
    """
    lines = []
    ceiling = 6.0

    def _decay(sig, s_r):
        hop = 256
        rms = librosa.feature.rms(y=sig, frame_length=1024, hop_length=hop)[0]
        if rms.size < 64:
            return None, None, 0
        db = 20.0 * np.log10(np.maximum(rms, 1e-8))
        frame_rate = s_r / float(hop)
        onset_frames = librosa.onset.onset_detect(y=sig, sr=s_r, hop_length=hop, backtrack=False)
        if len(onset_frames) < 4:
            return None, None, 0
        slopes, late_ratios = [], []
        min_gap = int(frame_rate * 0.28)
        skip = int(frame_rate * 0.04)
        for i, f in enumerate(onset_frames):
            nxt = onset_frames[i + 1] if i + 1 < len(onset_frames) else len(db)
            if nxt - f < min_gap:
                continue  # next hit masks the tail
            a = int(f + skip)
            b = int(min(f + frame_rate * 0.30, nxt - 1, len(db) - 1))
            if b - a < 6:
                continue
            seg = db[a:b]
            t = np.arange(len(seg)) / frame_rate
            slope = float(np.polyfit(t, seg, 1)[0])  # dB per second
            if slope < -1.0:
                slopes.append(slope)
            peak = float(np.max(db[int(f):int(f + max(2, skip)) + 1]))
            late_i = int(f + frame_rate * 0.18)
            if late_i < len(db):
                late_ratios.append(float(db[late_i] - peak))
        if not slopes:
            return None, None, 0
        med_slope = float(np.median(slopes))
        late = float(np.median(late_ratios)) if late_ratios else None
        return med_slope, late, len(slopes)

    def _fmt_decay(med_slope):
        d = 60.0 / abs(med_slope) if med_slope < -1e-6 else None
        if d is None:
            return None, "n/a"
        if d >= ceiling:
            return ceiling, f">= {ceiling:.0f} s (at the measurement ceiling)"
        d = max(0.05, d)
        return d, f"{round(d, 2)} s"

    def _reading(d):
        if d < 0.35:
            return "dry/tight — close, damped, or gated production"
        if d < 0.8:
            return "moderate room/plate ambience"
        if d < 1.6:
            return "noticeably reverberant — large room/hall/plate feel"
        return "very washy/reverb-heavy, long tails"

    try:
        mix_slope, mix_late, mix_n = _decay(y, sr)
        if mix_slope is None:
            return lines
        mix_d, mix_txt = _fmt_decay(mix_slope)

        perc_slope = perc_late = None
        perc_n = 0
        try:
            # Separation at 11.025 kHz: tails of hits are broadband, so this
            # loses nothing the decay estimate uses and halves the cost.
            sr_p = 11025 if sr > 11025 else sr
            y_p = np.asarray(y, dtype=np.float32)
            if sr_p != sr:
                y_p = librosa.resample(y_p, orig_sr=sr, target_sr=sr_p)
            S = librosa.stft(y_p, n_fft=1024, hop_length=256)
            _H, P = librosa.decompose.hpss(S, margin=2.0)
            y_perc = librosa.istft(P, hop_length=256, length=len(y_p))
            perc_slope, perc_late, perc_n = _decay(y_perc, sr_p)
        except Exception:
            perc_slope = None

        lines.append(f"post-transient decay rate, full mix: {round(mix_slope, 1)} dB/s "
                     f"(median over {mix_n} isolated hits)")
        lines.append(f"full-mix sustain after hits (extrapolated to -60 dB): {mix_txt}")
        if mix_late is not None:
            lines.append(
                f"energy remaining 180 ms after a hit: {round(mix_late, 1)} dB relative to the hit"
            )
        if perc_slope is not None:
            perc_d, perc_txt = _fmt_decay(perc_slope)
            lines.append(
                f"decay of the hits themselves (percussive component, extrapolated to -60 dB): "
                f"{perc_txt} (median over {perc_n} isolated hits)"
            )
            if perc_d is not None:
                lines.append(f"ambience reading: {_reading(perc_d)}")
                if mix_d is not None and mix_d >= 1.6 and perc_d < 0.8:
                    lines.append(
                        "sustain note: the long full-mix sustain comes from instruments that keep "
                        "sounding (held chords, pads, strings), not from reverb on the hits — do "
                        "not describe the production as reverb-heavy on the strength of it."
                    )
        elif mix_d is not None:
            lines.append(
                f"ambience reading (full mix only, so sustained instruments count as decay): "
                f"{_reading(mix_d)}"
            )
        lines.append(
            "NOTE: these are proxies, not an RT60 — dense arrangements mask true tails, and the "
            "full-mix figure includes anything that sustains."
        )
    except Exception:
        pass
    return lines


def _prod_fullband_balance(chunks, sr):
    """Band energy share averaged over excerpts spanning the WHOLE track.

    The existing TIMBRE block measures only the first 60 seconds. Intros are
    routinely unrepresentative — no drums, no bass, filtered pads, a solo
    voice — so first-60s band shares can describe a section that never
    returns. This does not replace that block; it sits alongside it so the
    two can be compared, and reports how much the balance actually moves
    across the track.
    """
    lines = []
    if not chunks or not sr:
        return lines
    try:
        n_fft = 2048
        bands = [("sub-bass", 20, 60), ("bass", 60, 250), ("low-mid", 250, 800),
                 ("mid", 800, 4000), ("high", 4000, 16000)]
        per_excerpt = []
        centroids = []
        for c in chunks:
            L, R = _prod_split_lr(c)
            mono = L if R is None else (L[: min(len(L), len(R))] + R[: min(len(L), len(R))]) * 0.5
            mono = np.asarray(mono, dtype=np.float32)
            if len(mono) < n_fft:
                continue
            S = np.abs(librosa.stft(mono, n_fft=n_fft, hop_length=n_fft // 2))
            freqs = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
            tot = float(np.sum(S ** 2))
            if tot <= 0:
                continue
            shares = []
            for _name, lo, hi in bands:
                mask = (freqs >= lo) & (freqs < hi)
                shares.append(float(np.sum(S[mask] ** 2)) / tot * 100.0 if np.any(mask) else 0.0)
            per_excerpt.append(shares)
            try:
                centroids.append(float(np.mean(librosa.feature.spectral_centroid(S=S, sr=sr))))
            except Exception:
                pass

        if not per_excerpt:
            return lines
        arr = np.asarray(per_excerpt, dtype=float)
        means = arr.mean(axis=0)
        lines.append(
            f"band energy share, whole-track average over {len(per_excerpt)} excerpts "
            "(compare with the first-60s figures above):"
        )
        for (name, lo, hi), m in zip(bands, means):
            # Label the band by what this sample rate can actually hold: on the
            # 22.05 kHz working copy "high (4000-16000 Hz)" really ends at ~11 kHz.
            lines.append(f"  {name} ({lo}-{min(int(hi), int(sr // 2))} Hz): {round(float(m), 1)}%")
        if centroids:
            lines.append(
                f"whole-track brightness (mean spectral centroid): "
                f"{round(float(np.mean(centroids)), 1)} Hz"
            )
        if arr.shape[0] >= 3:
            spread = float(np.mean(arr.std(axis=0)))
            lines.append(f"section-to-section spectral variation: {round(spread, 1)} percentage points")
            if spread < 1.5:
                lines.append(
                    "arrangement reading: spectral balance barely changes across the track — "
                    "a consistent, static arrangement/mix."
                )
            elif spread > 5.0:
                lines.append(
                    "arrangement reading: spectral balance shifts a lot across the track — "
                    "sections differ substantially in instrumentation or density."
                )
    except Exception:
        pass
    return lines


def _prod_effect_tags(mix_audio_path):
    """Production-character tags (audible distortion, reverb, echo, noise
    floor) from the same already-cached PANNs windows the instrument tagger
    uses, so this costs no extra inference."""
    lines = []
    if not ENABLE_INSTRUMENT_TAGGING:
        return lines
    if not mix_audio_path or str(mix_audio_path).startswith(("http://", "https://")):
        return lines
    try:
        tags = _panns_tag_windowed(mix_audio_path, _PRODUCTION_LABEL_MAP, 5, 0.15)
        if not tags:
            return lines
        parts = []
        for label, prob, t in tags:
            part = f"{label} ({prob * 100:.0f}%"
            cov = _tag_coverage_note(_panns_tag_stats(mix_audio_path, label))
            if cov:
                part += f", {cov}"
            parts.append(part + ")")
        lines.append(
            "production-character tags (audio classifier, supporting evidence only): "
            + ", ".join(parts)
        )
    except Exception:
        pass
    return lines


def build_production_analysis_report(local_path, y=None, sr=None, duration=None,
                                     beat_times=None, original_path=None):
    """Objective mix/production measurements: stereo image, true peak and
    clipping, bandwidth/provenance, sidechain-style pumping, ambience decay,
    and whole-track spectral balance.

    `y`/`sr` are the mono waveform the caller has already decoded (reused for
    the envelope analyses so the file is not decoded twice); stereo excerpts
    are loaded separately because every existing load path is mono-only.
    Returns "" when nothing could be measured. Each measurement is independent
    and failure-isolated.
    """
    if not PRODUCTION_ANALYSIS_ENABLED:
        return ""
    if not local_path or str(local_path).startswith(("http://", "https://")):
        return ""

    if duration is None and y is not None and sr:
        try:
            duration = len(y) / float(sr)
        except Exception:
            duration = None
    if not duration or duration < 3.0:
        return ""

    chunks, ex_sr = [], None
    try:
        chunks, ex_sr = _prod_load_excerpts(local_path, duration, mono=False)
    except Exception:
        chunks, ex_sr = [], None

    # `local_path` is the pipeline's 22.05 kHz working WAV, and convert_to_wav()
    # builds that with ffmpeg "-ac 1" — so it is ALWAYS single-channel and the
    # excerpts above can never carry a second channel. _prod_stereo_field() then
    # saw R is None for every chunk and reported "mono (single channel)" for
    # every track, regardless of the real source. Load a separate set of
    # excerpts from the untouched original file for that one measurement.
    #
    # Deliberately scoped to the stereo lines only: every other measurement
    # below still reads `chunks`/`ex_sr` exactly as before, so their numbers do
    # not move. Falls back to the original chunks whenever the source file is
    # missing, remote, or unreadable, which reproduces the previous behaviour.
    stereo_chunks, stereo_sr = [], None
    _stereo_src_path = None   # the file the stereo excerpts came from, if it is the original
    try:
        if (
            original_path
            and isinstance(original_path, str)
            and not str(original_path).startswith(("http://", "https://"))
            and os.path.exists(original_path)
        ):
            stereo_chunks, stereo_sr = _prod_load_excerpts(
                original_path, duration, mono=False
            )
            if stereo_chunks and stereo_sr:
                _stereo_src_path = original_path
    except Exception:
        stereo_chunks, stereo_sr = [], None
    if not stereo_chunks or not stereo_sr:
        # The pipeline's own working WAV: its container says nothing about the
        # source, so the bandwidth reading must not treat it as "lossless".
        stereo_chunks, stereo_sr = chunks, ex_sr
        _stereo_src_path = None

    sections = []

    stereo_lines = []
    try:
        if stereo_chunks and stereo_sr:
            stereo_lines = _prod_stereo_field(stereo_chunks, stereo_sr)
    except Exception:
        pass
    if stereo_lines:
        sections.append(("STEREO IMAGE / MIX WIDTH (objective)", stereo_lines))

    peak_lines = []
    try:
        # True peak / PLR / clipping describe the MASTER, so they are read from
        # the untouched source (stereo, native rate) when available. On the
        # resampled mono working copy, resampling moves peaks and softens the
        # flat tops that clipping detection looks for.
        _peak_src = local_path
        if (
            original_path
            and isinstance(original_path, str)
            and not str(original_path).startswith(("http://", "https://"))
            and os.path.exists(original_path)
            and stereo_chunks
        ):
            _peak_src = original_path
        peak_lines = _prod_peaks_and_clipping(
            _peak_src, stereo_chunks if _peak_src != local_path else chunks
        )
    except Exception:
        pass
    if peak_lines:
        sections.append(("MASTERING: TRUE PEAK / CLIPPING (objective)", peak_lines))

    bw_lines = []
    try:
        # Must use the NATIVE-rate excerpts. `chunks` comes from the pipeline's
        # 22.05 kHz working WAV, so its Nyquist is ~11 kHz — this measurement
        # could never observe a cutoff above that, and reported "full-band up to
        # the file's own limit" for everything, including 128 kbps MP3s with a
        # 16 kHz brickwall. stereo_chunks is loaded from the untouched source at
        # its own sample rate, which is exactly what this needs. _prod_hf_cutoff
        # folds L/R to mono itself, so stereo input is fine.
        #
        # Scoped to this measurement and the stereo one. _prod_peaks_and_clipping
        # and _prod_fullband_balance still read `chunks`/`ex_sr` unchanged, so
        # their numbers do not move.
        if stereo_chunks and stereo_sr:
            bw_lines = _prod_hf_cutoff(stereo_chunks, stereo_sr, source_path=_stereo_src_path)
    except Exception:
        pass
    if bw_lines:
        sections.append(("BANDWIDTH / SOURCE PROVENANCE (objective)", bw_lines))

    env_y, env_sr = None, None
    try:
        if y is not None and sr:
            env_sr = int(sr)
            env_y = np.asarray(y, dtype=np.float32)
            # Envelope features live below ~5 kHz; downsample to keep this cheap.
            if env_sr > PRODUCTION_ENVELOPE_SR * 1.5:
                env_y = librosa.resample(env_y, orig_sr=env_sr, target_sr=PRODUCTION_ENVELOPE_SR)
                env_sr = PRODUCTION_ENVELOPE_SR
    except Exception:
        env_y, env_sr = None, None

    if env_y is not None and env_sr:
        pump_lines = []
        try:
            pump_lines = _prod_pumping(env_y, env_sr, beat_times=beat_times)
        except Exception:
            pass
        if pump_lines:
            sections.append(("BEAT-SYNCHRONOUS DYNAMICS / PUMPING (objective)", pump_lines))

        amb_lines = []
        try:
            amb_lines = _prod_ambience(env_y, env_sr)
        except Exception:
            pass
        if amb_lines:
            sections.append(("AMBIENCE / REVERB CHARACTER (objective proxy)", amb_lines))

    bal_lines = []
    try:
        if chunks and ex_sr:
            bal_lines = _prod_fullband_balance(chunks, ex_sr)
    except Exception:
        pass
    if bal_lines:
        sections.append(("WHOLE-TRACK SPECTRAL BALANCE (objective)", bal_lines))

    fx_lines = []
    try:
        fx_lines = _prod_effect_tags(local_path)
    except Exception:
        pass
    if fx_lines:
        sections.append(("PRODUCTION-CHARACTER TAGS", fx_lines))

    # Free the excerpt buffers promptly; the batch path is RSS-sensitive.
    # stereo_chunks is native-rate/stereo and so can be several times larger
    # than chunks — it must be released here too. (In the fallback case both
    # names point at the same list, which del handles fine.)
    try:
        del chunks
        del stereo_chunks
        del env_y
    except Exception:
        pass

    if not sections:
        return ""

    out = [
        "PRODUCTION / MIX MEASUREMENTS (objective, measured from THIS file)",
        "These are measurements, not impressions. When describing stereo width, reverb, "
        "loudness/limiting, sidechain pumping or bandwidth, use these figures rather than "
        "inferring from genre or era. They describe the mix and master only — they say "
        "nothing about which instruments are playing.",
    ]
    for title, body in sections:
        out.append("")
        out.append(title)
        out.extend(body)
    return "\n".join(out)


def build_objective_audio_report(local_path, original_path=None):
    """`local_path` is the mono 22.05 kHz working WAV used for every
    measurement. `original_path`, when given, is the untouched source file and
    is used ONLY for the stereo-image measurement, which cannot work on a
    single-channel downmix. Optional and defaulting to None so any existing
    caller behaves exactly as before."""
    try:
        y, sr = librosa.load(local_path, sr=None, mono=True)
        duration = len(y) / float(sr)
        if duration < 1.0:
            return ""

        lines = []
        lines.append("OBJECTIVE AUDIO MEASUREMENTS")
        lines.append(f"duration: {round(duration, 2)} s")

        # Structural boundary detection is moved up here, right after duration,
        # and computed before any of the riskier downstream measurements
        # (LUFS, beat tracking, spectral peaks, band onset density). Those
        # later blocks can throw on unusual audio; computing/recording the
        # boundary candidates first means they're already captured into
        # `lines` and won't be lost even if something later fails (see the
        # partial-report fallback at the bottom of this function).
        try:
            _boundary_times = _structural_novelty_boundaries(y, sr)
        except Exception:
            _boundary_times = []
        if _boundary_times:
            lines.append("")
            lines.append(
                "STRUCTURAL BOUNDARY CANDIDATES (objective, timbre+harmony+energy self-similarity "
                "novelty -- a raw first-pass cross-check, NOT the section map and NOT section names/labels)"
            )
            lines.append(
                "candidate change points: "
                + ", ".join(_seconds_to_mmss(t) for t in _boundary_times)
            )
            lines.append(
                "WARNING: The raw list on the line above is unmerged DSP peaks. Do not read that "
                "raw list out as the song's structure, and do not quote it as section boundaries. "
                "ALWAYS use the RECOMMENDED STRUCTURE FOR DISCUSSION block for section names and "
                "timestamps. NOTE: if that block appears with the heading '(from objective change "
                "points)', it was built by merging and validating these very peaks against the "
                "track duration — it is a finished section map and IS authoritative. Otherwise the "
                "section map is built separately, bar by bar, from drum fills, vocal entries, "
                "repetition and lyric timing, so some peaks here fall inside sections and some real "
                "section changes are missing; where the two disagree, the RECOMMENDED STRUCTURE is "
                "right. This warning applies only to the raw list here, never to the RECOMMENDED "
                "STRUCTURE block."
            )

        peak = float(np.max(np.abs(y))) if len(y) else 0.0
        rms = float(np.sqrt(np.mean(np.square(y.astype(np.float64))))) if len(y) else 0.0
        lines.append("")
        lines.append("DYNAMIC RANGE / LOUDNESS (numeric)")
        try:
            # Measure loudness on the untouched source when it is available.
            # local_path is the mono 22.05 kHz working copy, and a mono downmix
            # reads roughly 3 LU quieter than the stereo master under EBU R128
            # -- which made this block disagree with RECOMMENDED DYNAMICS (which
            # already uses the original) and skewed the loud-master era caveat
            # that is parsed back out of this text.
            _loud_path = local_path
            if (
                original_path
                and isinstance(original_path, str)
                and not original_path.startswith(("http://", "https://"))
                and os.path.exists(original_path)
            ):
                _loud_path = original_path
            _lufs, _lra, _lsrc = measure_ebur128_loudness(_loud_path)
            if _lufs is None and _loud_path != local_path:
                _lufs, _lra, _lsrc = measure_ebur128_loudness(local_path)
            if _lufs is not None:
                lines.append(f"EBU R128 integrated loudness: {_lufs} LUFS ({_lsrc})")
                if _lra is not None:
                    lines.append(f"EBU R128 loudness range (LRA): {_lra} LU")
        except Exception:
            pass
        if peak > 1e-12 and rms > 1e-12:
            crest_db = round(float(20 * np.log10(peak / rms)), 1)
            label, plain = _dynamics_label_from_crest(crest_db)
            lines.append(f"crest factor / dynamic-range proxy: {crest_db} dB")
            lines.append(f"peak amplitude (normalized): {peak:.4f}")
            lines.append(f"RMS level (normalized): {rms:.6f}")
            if label:
                lines.append(f"crest band (peak-to-average / peak limiting, not loudness range): {label}")
            if plain:
                lines.append(f"dynamic-range note: {plain}")
            if crest_db < 10.0:
                lines.append(
                    "compression character: low crest factor is consistent with heavy "
                    "limiting/compression; do not infer release era from crest factor alone."
                )
            elif crest_db >= 14.0:
                # Same boundary as the crest band above (_dynamics_label_from_crest
                # calls 14.0 dB "high"); with "> 14.0" a 14.0 dB track was "high
                # crest" on one line and "moderate crest factor" on the next.
                lines.append(
                    "compression character: high crest factor is consistent with a more dynamic, "
                    "less-limited master; do not infer release era from crest factor alone."
                )
            else:
                lines.append(
                    "compression character: moderate crest factor — do not infer release era from this alone."
                )
        else:
            lines.append("")
            lines.append("DYNAMIC RANGE / LOUDNESS (numeric)")
            lines.append("crest factor / dynamic-range proxy: unavailable (silent or near-silent audio)")

        # start_bpm is a *prior*, not just an initial guess: librosa weights
        # tempo candidates by closeness to it (controlled by std_bpm, which
        # defaults to a tight ~1-octave spread). With the old defaults this
        # pulled real readings toward 120 BPM even when the track wasn't
        # actually near 120 (observed: a 125-126 BPM track reported as
        # ~123 BPM). Widening std_bpm keeps the prior's intended job --
        # nudging genuinely ambiguous half/double-time picks toward a
        # plausible song tempo -- without dragging correct readings toward
        # the prior's center.
        try:
            # Old librosa: beat_track() accepted std_bpm directly.
            tempo_raw, beats = librosa.beat.beat_track(y=y, sr=sr, start_bpm=120.0, std_bpm=30.0)
        except TypeError:
            # Newer librosa removed std_bpm from beat_track() (it now wants
            # a scipy.stats `prior` distribution instead). librosa.feature.tempo()
            # still exposes std_bpm and uses the exact same log-normal prior
            # math beat_track() used to apply internally, so compute the
            # tempo there first (preserving the widened-prior tuning) and
            # feed the fixed tempo into beat_track() for beat positions.
            tempo_raw = librosa.feature.tempo(y=y, sr=sr, start_bpm=120.0, std_bpm=30.0)
            _tempo_val = float(np.atleast_1d(tempo_raw)[0]) if np.size(tempo_raw) else 120.0
            _, beats = librosa.beat.beat_track(y=y, sr=sr, bpm=_tempo_val)
            tempo_raw = np.array([_tempo_val])
        tempo_arr = np.atleast_1d(tempo_raw)
        tempo = float(tempo_arr[0]) if len(tempo_arr) else None
        # librosa reports tempo in whole onset frames (60 * sr/512 / k), a
        # coarse ladder: 120 BPM reads as 117.5, ~158 as 161.5. Refine within
        # +/-6 % (same metrical level) from the onset envelope's periodicity.
        beat_times = librosa.frames_to_time(beats, sr=sr)
        if tempo:
            try:
                _env_ref = librosa.onset.onset_strength(y=y, sr=sr, hop_length=512)
                _tempo_ref = _sx_refine_tempo(_env_ref, sr / 512.0, tempo)
                if _tempo_ref and abs(_tempo_ref - tempo) / tempo <= 0.06:
                    tempo = float(_tempo_ref)
                    # Re-track at the refined tempo (same metrical level) on a
                    # finer hop and a kick-anchored envelope, so beat spacing,
                    # meter and the production measurements below use beats
                    # that do not drift against the music.
                    _b2 = _sx_track_beats_at(y, sr, float(tempo))
                    if _b2 is not None and _b2.size >= 8:
                        _med = 60.0 / float(np.median(np.diff(_b2)))
                        if abs(_med - tempo) / tempo <= 0.03:
                            beat_times = _b2
            except Exception:
                pass

        onset_env = librosa.onset.onset_strength(y=y, sr=sr)
        onsets = librosa.onset.onset_detect(onset_envelope=onset_env, sr=sr)
        frame_times = librosa.frames_to_time(np.arange(len(onset_env)), sr=sr)
        if len(beat_times):
            try:
                beat_accents = _downbeat_accent_curve(y, sr, beat_times, onset_env=onset_env, hop_length=512)
            except Exception:
                beat_accents = np.interp(beat_times, frame_times, onset_env)
        else:
            beat_accents = np.array([])
        downbeat_times, beats_per_bar = _estimate_meter_from_beats(beat_times, beat_accents)

        # Compute the median inter-beat-interval BPM BEFORE calling
        # _preferred_tempo, so it can be used as an independent corroborating
        # measurement (a different calculation -- from actual detected beat
        # timestamps -- rather than the raw autocorrelation/tempogram value)
        # instead of letting the half-time heuristic override a genuinely
        # fast, well-supported tempo.
        median_ibi_bpm = None
        if len(beat_times) > 1:
            ibis_for_corroboration = np.diff(beat_times)
            if len(ibis_for_corroboration):
                med = float(np.median(ibis_for_corroboration))
                if med > 0:
                    median_ibi_bpm = round(60.0 / med, 1)

        lines.append("")
        lines.append("BEAT / TEMPO MEASUREMENTS")
        if tempo is not None:
            preferred, cands, note = _preferred_tempo(tempo, corroborating_bpm=median_ibi_bpm)
            lines.append(f"estimated tempo (raw detector): {round(tempo, 1)} BPM")
            if preferred is not None and abs(preferred - round(tempo, 1)) > 0.5:
                lines.append(f"preferred musical tempo for discussion: {preferred} BPM")
            if len(cands) > 1:
                lines.append("tempo candidates (half/double interpretations): " + ", ".join(f"{c} BPM" for c in cands))
            if note:
                lines.append(note)
        else:
            lines.append("estimated tempo: unavailable")

        if len(beat_times):
            ibis = np.diff(beat_times)
            median_ibis = float(np.median(ibis)) if len(ibis) else None
            mean_ibis = float(np.mean(ibis)) if len(ibis) else None
            std_ibis = float(np.std(ibis)) if len(ibis) > 1 else None

            lines.append(f"detected beats: {len(beat_times)}")
            lines.append(f"first beat at {round(float(beat_times[0]), 2)} s, last beat at {round(float(beat_times[-1]), 2)} s")

            if median_ibis is not None and median_ibis > 0:
                lines.append(f"median inter-beat interval: {round(median_ibis, 3)} s ({round(60.0 / median_ibis, 1)} BPM)")

            if mean_ibis is not None and std_ibis is not None and mean_ibis > 0:
                lines.append(f"beat regularity (std/mean IBI): {round(std_ibis / mean_ibis, 3)}")

            if len(beat_times) >= 4:
                meter = int(beats_per_bar or 1)
                bar_times = np.asarray(downbeat_times, dtype=float)
                if len(bar_times) > 1:
                    bar_durs = np.diff(bar_times)
                    meter_label = {2: "2/4", 3: "3/4", 4: "4/4", 5: "5/4", 6: "6/8", 7: "7/4", 8: "8-beat cycle (usually 4/4 with a two-bar accent pattern, not literally 8/8)", 9: "9/8", 12: "12/8"}.get(meter, f"{meter}-beat meter")
                    bar_note = ""
                    # The bars are counted in the tracker's own beats. When that
                    # pulse is very fast it is usually double the felt tempo (the
                    # dance-pop test track: 240 tracker BPM, 120 felt), and "4/4,
                    # 1.0 s bars" then describes half-bars. Say so, so the bar
                    # length is not read against the RECOMMENDED TEMPO.
                    try:
                        _pulse = 60.0 / float(median_ibis) if median_ibis else None
                    except (TypeError, ValueError, ZeroDivisionError):
                        _pulse = None
                    if _pulse and _pulse >= 175.0 and meter in (2, 4):
                        bar_note = (
                            f"; counted in the detector's own ~{_pulse:.0f}-BPM beats — if the felt "
                            f"tempo is half that (~{_pulse / 2.0:.0f} BPM), a 4/4 bar lasts "
                            f"~{480.0 / _pulse:.1f} s"
                        )
                    lines.append(f"meter estimate: {meter_label} ({len(bar_times)} bars, median bar length {round(float(np.median(bar_durs)), 3)} s{bar_note})")

                if not COMPACT_OBJECTIVE_REPORT and len(downbeat_times):
                    shown = ", ".join(f"{round(float(t), 2)}" for t in downbeat_times[:16])
                    suffix = "..." if len(downbeat_times) > 16 else ""
                    lines.append(
                        f"candidate downbeats (accent-cycle meter estimate): {shown}{suffix}"
                    )

        if duration > 0:
            lines.append(f"onset density: {round(len(onsets) / duration * 60.0, 1)} onsets/min")

        seg_seconds = min(duration, 60.0)
        y_seg = y[: int(seg_seconds * sr)]

        if len(y_seg) >= sr * 0.5:
            try:
                n_fft = 2048
                hop_length = 512
                S = np.abs(librosa.stft(y_seg, n_fft=n_fft, hop_length=hop_length))
                freqs = librosa.fft_frequencies(sr=sr, n_fft=n_fft)
                total_power = float(np.sum(S ** 2))

                lines.append("")
                lines.append(f"TIMBRE / ELEMENT MEASUREMENTS (first {round(seg_seconds, 1)} s)")

                if total_power > 0:
                    centroid = float(np.mean(librosa.feature.spectral_centroid(S=S, sr=sr)))
                    rolloff75 = float(np.mean(librosa.feature.spectral_rolloff(S=S, sr=sr, roll_percent=0.75)))
                    rolloff85 = float(np.mean(librosa.feature.spectral_rolloff(S=S, sr=sr, roll_percent=0.85)))
                    rolloff95 = float(np.mean(librosa.feature.spectral_rolloff(S=S, sr=sr, roll_percent=0.95)))
                    flatness = float(np.mean(librosa.feature.spectral_flatness(S=S)))
                    zcr = float(np.mean(librosa.feature.zero_crossing_rate(y=y_seg)))

                    lines.append(f"brightness (spectral centroid): {round(centroid, 1)} Hz")
                    if COMPACT_OBJECTIVE_REPORT:
                        lines.append(f"spectral rolloff 85: {round(rolloff85, 1)} Hz")
                    else:
                        lines.append(
                            f"spectral rolloff 75/85/95: {round(rolloff75, 1)}, "
                            f"{round(rolloff85, 1)}, {round(rolloff95, 1)} Hz"
                        )
                    lines.append(f"noise-likeness (spectral flatness): {round(flatness, 4)} (0=tonal, 1=noisy)")
                    if not COMPACT_OBJECTIVE_REPORT:
                        lines.append(f"zero-crossing rate: {round(zcr, 4)}")

                    D, H = librosa.decompose.hpss(S)
                    hp_total = float(np.sum((H + D) ** 2))
                    if hp_total > 0:
                        perc_ratio = float(np.sum(D ** 2) / hp_total)
                        lines.append(f"percussive vs harmonic power share: {round(perc_ratio * 100.0, 1)}% percussive")

                        if not COMPACT_OBJECTIVE_REPORT:
                            def component_centroid(Sx):
                                p = float(np.sum(Sx ** 2))
                                if p <= 0:
                                    return None
                                c = librosa.feature.spectral_centroid(S=Sx, sr=sr)
                                return float(np.mean(c))

                            h_c = component_centroid(H)
                            d_c = component_centroid(D)
                            if h_c is not None and d_c is not None:
                                lines.append(
                                    f"harmonic component brightness: {round(h_c, 1)} Hz; "
                                    f"percussive component brightness: {round(d_c, 1)} Hz"
                                )

                    bands = [
                        ("sub-bass", 20, 60),
                        ("bass", 60, 250),
                        ("low-mid", 250, 800),
                        ("mid", 800, 4000),
                        ("high", 4000, 16000),
                    ]

                    lines.append("band energy share:")
                    for name, lo, hi in bands:
                        mask = (freqs >= lo) & (freqs < hi)
                        if np.any(mask):
                            band_power = float(np.sum(S[mask] ** 2)) / total_power
                            lines.append(f"  {name} ({lo}-{min(int(hi), int(sr // 2))} Hz): {round(band_power * 100.0, 1)}%")

                    if not COMPACT_OBJECTIVE_REPORT:
                        mean_spec = np.mean(S, axis=1)
                        valid = freqs >= 20
                        valid_mean = np.where(valid, mean_spec, 0.0)
                        peak_ref = float(np.max(valid_mean))
                        if peak_ref > 0:
                            top_idx = [
                                int(i) for i in np.argsort(valid_mean)[::-1][:5]
                                if valid[int(i)] and valid_mean[int(i)] > 0
                            ]
                            if top_idx:
                                peak_desc = ", ".join(
                                    f"{int(freqs[i])} Hz ({round(float(20 * np.log10(mean_spec[i] / peak_ref)), 1)} dB)"
                                    for i in sorted(top_idx, key=lambda x: int(freqs[x]))
                                )
                                lines.append(f"dominant mean-spectrum peaks: {peak_desc}")

                        lines.append("band onset density (transient activity):")
                        for name, lo, hi in bands:
                            mask = (freqs >= lo) & (freqs < hi)
                            if not np.any(mask):
                                continue
                            S_band = np.zeros_like(S)
                            S_band[mask] = S[mask]
                            try:
                                env = librosa.onset.onset_strength(S=S_band, sr=sr, hop_length=hop_length)
                                band_onsets = librosa.onset.onset_detect(onset_envelope=env, sr=sr)
                                density = len(band_onsets) / seg_seconds * 60.0 if seg_seconds > 0 else 0.0
                                lines.append(f"  {name}: {round(float(density), 1)} onsets/min")
                            except Exception:
                                lines.append(f"  {name}: unavailable")
            except Exception:
                pass

        # Production/mix measurements (stereo image, true peak/clipping,
        # bandwidth, pumping, ambience, whole-track balance). Appended last and
        # fully failure-isolated so it can never cost the report anything that
        # was already computed above. `y`/`beat_times` are handed over so the
        # file is not decoded and beat-tracked a second time.
        try:
            _prod_block = build_production_analysis_report(
                local_path,
                y=y,
                sr=sr,
                duration=duration,
                beat_times=(beat_times if len(beat_times) else None),
                original_path=original_path,
            )
        except Exception as _pe:
            _prod_block = ""
            try:
                print(f"  (production analysis skipped -- {type(_pe).__name__}: {_pe})")
            except Exception:
                pass
        if _prod_block:
            lines.append("")
            lines.append(_prod_block)

        return "\n".join(lines)
    except Exception as _e:
        # Previously this silently returned "" on ANY exception anywhere in
        # this ~270-line function, discarding even successfully-computed
        # data (duration, structural boundary candidates, etc.) with zero
        # visibility into why. Now: report the failure so it's actually
        # diagnosable, and salvage whatever was already computed rather than
        # throwing away a partial report because one unrelated measurement
        # (e.g. spectral peaks, band onset density) failed.
        try:
            print(f"  (objective audio report: partial/failed -- {type(_e).__name__}: {_e})")
        except Exception:
            pass
        try:
            return "\n".join(lines) if lines else ""
        except Exception:
            return ""


def _clean_f0_series(f0_values):
    """Drop sparse outliers and octave jumps that inflate vocal range."""
    if not f0_values:
        return np.array([], dtype=float)
    arr = np.array(f0_values, dtype=float)
    arr = arr[np.isfinite(arr)]
    if arr.size < 8:
        return arr
    # IQR fence on log-Hz (octave-stable). Wide multiplier (3x, not the
    # textbook 1.5x): pitch-tracking frames are heavily weighted toward
    # sustained/held notes, so a tight fence would treat genuine melodic
    # excursions (brief high notes in a chorus, etc.) as statistical
    # outliers and crop them out, artificially narrowing the reported
    # range down to just the most common tessitura. The looser fence still
    # removes genuine octave-jump/tracking errors, which sit much further
    # out than any real single-voice excursion.
    logf = np.log2(np.clip(arr, 40.0, 2000.0))
    q1, q3 = np.percentile(logf, [25, 75])
    iqr = max(q3 - q1, 1e-6)
    keep = (logf >= q1 - 3.0 * iqr) & (logf <= q3 + 3.0 * iqr)
    cleaned = arr[keep]
    if cleaned.size < 5:
        cleaned = arr
    # Second pass: drop points more than an octave from the median, but only
    # when that's clearly a small minority of stray frames (isolated
    # octave-tracking/harmonic errors). A genuinely wide-ranged performance --
    # a chest-voice verse against a falsetto/whistle chorus, for example --
    # can legitimately put a large share of frames beyond one octave from the
    # median; that's real singing, not tracking noise, and this pass used to
    # discard it unconditionally, directly undercutting the wider IQR fence
    # above (whose whole point was to preserve genuine excursions). Requiring
    # the within-octave frames to be a clear majority keeps the original
    # behavior for the common single-register case (where few or no frames
    # sit outside one octave, so nothing changes) while no longer amputating
    # the top/bottom of a real multi-register range.
    med = float(np.median(cleaned))
    if med > 0:
        ratio = cleaned / med
        within_octave = (ratio >= 0.5) & (ratio <= 2.0)
        if within_octave.sum() >= 0.85 * cleaned.size:
            cleaned = cleaned[within_octave]
    return cleaned if cleaned.size else arr


def _f0_multi_peak_note(f0_arr):
    """Return a short note if voiced f0 looks multi-modal (possible multi-singer
    or wide dual-register singing). Supporting evidence only — octave doubles
    and wide single-voice ranges can also look multi-modal."""
    try:
        arr = np.asarray(f0_arr, dtype=float)
        arr = arr[np.isfinite(arr) & (arr > 50) & (arr < 1200)]
        if arr.size < 40:
            return ""
        # Work in semitone space relative to median for stable binning.
        med = float(np.median(arr))
        if med <= 0:
            return ""
        semis = 12.0 * np.log2(arr / med)
        # Histogram over ~±18 semitones
        bins = np.linspace(-18, 18, 37)
        hist, edges = np.histogram(semis, bins=bins)
        if hist.sum() < 40:
            return ""
        # Smooth slightly
        kernel = np.array([1, 2, 3, 2, 1], dtype=float)
        kernel /= kernel.sum()
        smooth = np.convolve(hist.astype(float), kernel, mode="same")
        # Peak detection: local maxima above a floor
        peaks = []
        for i in range(1, len(smooth) - 1):
            if smooth[i] >= smooth[i - 1] and smooth[i] >= smooth[i + 1] and smooth[i] > 0:
                peaks.append((smooth[i], 0.5 * (edges[i] + edges[i + 1]), i))
        if len(peaks) < 2:
            return ""
        peaks.sort(reverse=True)
        # Keep strongest peaks that are well separated
        chosen = [peaks[0]]
        for p in peaks[1:]:
            if all(abs(p[1] - c[1]) >= 3.0 for c in chosen):
                chosen.append(p)
            if len(chosen) >= 3:
                break
        if len(chosen) < 2:
            return ""
        # Convert peak offsets back to approx Hz
        peak_hz = sorted(med * (2 ** (c[1] / 12.0)) for c in chosen[:3])
        peak_str = ", ".join(f"{hz:.0f} Hz" for hz in peak_hz)
        sep = abs(chosen[0][1] - chosen[1][1])
        strength = chosen[1][0] / max(chosen[0][0], 1e-9)
        if strength < 0.25:
            return ""
        return (
            f"voiced-f0 multi-peak hint: ~{len(chosen)} pitch centres near {peak_str} "
            f"(~{sep:.1f} semitones between top two; secondary/primary mass ratio {strength:.2f}). "
            "Possible multi-singer, call-and-response, or wide dual-register single singer / "
            "octave stacking — not proof of multiple people by itself."
        )
    except Exception:
        return ""


def build_vocal_objective_report(local_path):
    try:
        y, sr = librosa.load(local_path, sr=None, mono=True)
        duration = len(y) / float(sr)
        if duration < 2.0:
            return ""

        max_scan_seconds = min(duration, 120.0)
        chunk_seconds = 30.0
        f0_values = []
        frames_scanned = 0

        # Sample windows SPREAD ACROSS the track rather than scanning
        # contiguously from t=0. A single 30s chunk alone typically yields
        # well over 1000 voiced pyin frames, so a "stop once we have enough
        # frames" exit (the old approach) almost always triggered after just
        # the first chunk — i.e. intro/verse 1 only — and never reached the
        # chorus or bridge, where the real vocal range usually opens up. That
        # produced artificially narrow reported ranges (e.g. a semitone or
        # two) even for tracks with normal melodic range. Spreading a fixed
        # number of chunks evenly across the full duration keeps the same
        # total-audio budget (~max_scan_seconds) but gives verse+chorus (and
        # bridge, for longer tracks) a real chance to be represented.
        n_chunks = max(1, int(round(max_scan_seconds / chunk_seconds)))
        if duration <= max_scan_seconds or n_chunks <= 1:
            chunk_starts = [i * chunk_seconds for i in range(n_chunks)]
        else:
            usable_span = max(0.0, duration - chunk_seconds)
            chunk_starts = [usable_span * i / (n_chunks - 1) for i in range(n_chunks)]

        for start_sec in chunk_starts:
            start = int(max(0.0, start_sec) * sr)
            end = min(start + int(chunk_seconds * sr), len(y))
            y_chunk = y[start:end]
            if len(y_chunk) < sr:
                continue

            # Slightly narrower band + higher voicing threshold reduces
            # harmonic/bleed spikes that inflate the top of the range.
            f0, _, voiced_prob = librosa.pyin(
                y_chunk,
                fmin=librosa.note_to_hz("C2"),
                fmax=librosa.note_to_hz("C6"),
                sr=sr,
                frame_length=2048,
            )

            valid = ~np.isnan(f0) & (voiced_prob > 0.65)
            frames_scanned += int(len(f0))
            if np.any(valid):
                f0_values.extend(f0[valid].tolist())

        lines = []

        if f0_values:
            f0_arr = _clean_f0_series(f0_values)
            if f0_arr.size == 0:
                f0_arr = np.array(f0_values, dtype=float)
            median_f0 = float(np.median(f0_arr))
            p5 = float(np.percentile(f0_arr, 5))
            p10 = float(np.percentile(f0_arr, 10))
            p90 = float(np.percentile(f0_arr, 90))
            p95 = float(np.percentile(f0_arr, 95))

            lines.append("VOCAL OBJECTIVE MEASUREMENTS (pitch/formant proxies)")
            lines.append(f"voiced pitch median: {round(median_f0, 1)} Hz")
            if frames_scanned > 0:
                # How much of the scanned audio was confidently pitched at all.
                # A real vocal part is voiced for a large share of the time;
                # separation residue on an instrumental is not.
                lines.append(
                    f"voiced frames: {round(100.0 * len(f0_values) / frames_scanned, 1)}% "
                    "of scanned audio"
                )
            lines.append(
                f"voiced pitch 5-95 percentile range: {round(p5, 1)}-{round(p95, 1)} Hz"
            )
            lines.append(
                f"practical sung range (10-90%): {round(p10, 1)}-{round(p90, 1)} Hz "
                f"(~{_hz_to_note_name(p10)} to {_hz_to_note_name(p90)}) — prefer this over absolute extremes"
            )

            try:
                lines.append(f"approx median note: {librosa.hz_to_note(median_f0)}")
            except Exception:
                pass

            # Weak multi-voice proxy: multiple well-separated pitch centres in
            # voiced f0 (can also be wide single-singer range or octave doubles —
            # never proof of two people by itself).
            multi_note = _f0_multi_peak_note(f0_arr)
            if multi_note:
                lines.append(multi_note)

        scan_y = y[: int(max_scan_seconds * sr)]
        if len(scan_y) >= sr:
            S = np.abs(librosa.stft(scan_y, n_fft=2048, hop_length=512))
            D, H = librosa.decompose.hpss(S)
            freqs = librosa.fft_frequencies(sr=sr, n_fft=2048)

            total_h_power = float(np.sum(H ** 2))
            if total_h_power > 0:
                vocal_mask = (freqs >= 250) & (freqs <= 4000)
                if np.any(vocal_mask):
                    vocal_share = float(np.sum(H[vocal_mask] ** 2) / total_h_power)
                    lines.append(f"harmonic energy in 250-4000 Hz vocal band: {round(vocal_share * 100.0, 1)}%")

                mean_h = np.mean(H, axis=1)
                valid_formant_band = (freqs >= 300) & (freqs <= 5000)
                valid_mean = np.where(valid_formant_band, mean_h, 0.0)
                peak_ref = float(np.max(valid_mean))

                # Formant-like peaks are only meaningful when a voice was found.
                if peak_ref > 0 and f0_values:
                    # Distinct spectral PEAKS at least ~250 Hz apart. Taking the
                    # four largest bins reported neighbouring FFT bins of one
                    # peak (e.g. 322 Hz and 333 Hz) as separate "formants".
                    try:
                        from scipy.signal import find_peaks as _find_peaks
                        bin_hz = float(freqs[1] - freqs[0]) if len(freqs) > 1 else 1.0
                        pk, _ = _find_peaks(valid_mean, distance=max(1, int(250.0 / max(bin_hz, 1e-6))))
                        pk = [int(i) for i in pk if valid_formant_band[int(i)] and valid_mean[int(i)] > 0]
                        top_idx = sorted(pk, key=lambda i: valid_mean[i], reverse=True)[:4]
                    except Exception:
                        top_idx = []
                    if top_idx:
                        peak_desc = ", ".join(
                            f"{int(freqs[i])} Hz ({round(float(20 * np.log10(mean_h[i] / peak_ref)), 1)} dB)"
                            for i in sorted(top_idx, key=lambda x: int(freqs[x]))
                        )
                        lines.append(f"formant-like harmonic peaks: {peak_desc}")

        if not lines:
            return ""

        lines.append("Note: pitch and formant proxies overlap heavily between young male, young female, and some adult singers; use them as evidence, not proof.")
        return "\n".join(lines)
    except Exception:
        return ""


# --- Essentia integration helpers ------------------------------------------
def _essentia_first_float(value):
    try:
        if isinstance(value, (tuple, list)):
            value = value[0]
        if hasattr(value, "item"):
            val = float(value.item())
        else:
            arr = np.asarray(value, dtype=float).ravel()
            if arr.size == 0:
                return None
            val = float(arr[0])
        return val if np.isfinite(val) else None
    except Exception:
        return None


def _essentia_to_float_array(value):
    try:
        if value is None:
            return np.array([], dtype=float)

        if isinstance(value, (tuple, list)):
            # If the whole tuple/list is numeric, treat it as a sequence of values.
            try:
                arr = np.asarray(value, dtype=float).ravel()
                if arr.size:
                    return arr[np.isfinite(arr)]
            except Exception:
                pass

            for item in value:
                try:
                    arr = np.asarray(item, dtype=float).ravel()
                except Exception:
                    continue
                if arr.size > 1 or not np.isscalar(item):
                    return arr[np.isfinite(arr)]

            try:
                return np.array([float(value[0])], dtype=float)
            except Exception:
                return np.array([], dtype=float)

        arr = np.asarray(value, dtype=float).ravel()
        return arr[np.isfinite(arr)]
    except Exception:
        return np.array([], dtype=float)


def _essentia_set_sample_rate(kernel, sample_rate):
    for attr in ("sampleRate", "sr"):
        try:
            setattr(kernel, attr, int(sample_rate))
            return True
        except Exception:
            pass
    return False


def _essentia_load_audio(local_path, max_seconds=None):
    if not ESSENTIA_AVAILABLE or essentia is None:
        return None, None

    try:
        samples = None
        sample_rate = 44100

        # Prefer MonoLoader (returns a mono float vector).
        try:
            from essentia.standard import MonoLoader
            samples = np.asarray(
                MonoLoader(filename=local_path, sampleRate=44100)(),
                dtype=np.float32,
            )
            sample_rate = 44100
        except Exception:
            loader = None
            try:
                from essentia.standard import AudioLoader as _AudioLoader
                loader = _AudioLoader(filename=local_path)
            except Exception:
                try:
                    loader = essentia.standard.AudioLoader(filename=local_path)
                except Exception:
                    loader = None

            if loader is not None:
                loaded = loader()
                # AudioLoader returns (audio, sampleRate, channels, md5, bit_rate, codec)
                if isinstance(loaded, tuple) and len(loaded) >= 2:
                    samples = loaded[0]
                    sample_rate = loaded[1]
                else:
                    samples = loaded
                    sample_rate = 44100

        if samples is None:
            return None, None

        samples = np.asarray(samples, dtype=np.float32)

        if samples.ndim == 0:
            return None, None

        if samples.ndim == 2:
            # Usual layout is (samples, channels).
            if samples.shape[1] <= 8 and samples.shape[0] > samples.shape[1]:
                samples = samples.mean(axis=1).astype(np.float32)
            else:
                samples = samples.mean(axis=0).astype(np.float32)
        elif samples.ndim > 2:
            samples = samples.reshape(samples.shape[0], -1).mean(axis=1).astype(np.float32)

        if samples.size:
            peak_check = float(np.max(np.abs(samples)))
            if peak_check > 1.5:
                samples = (samples / peak_check).astype(np.float32)

        sample_rate = int(_essentia_first_float(sample_rate) or 44100)
        if sample_rate <= 0:
            return None, None

        if max_seconds is not None and len(samples) > int(max_seconds * sample_rate):
            samples = samples[: int(max_seconds * sample_rate)]

        if len(samples) < max(1, sample_rate // 2):
            return None, None

        return samples, sample_rate
    except Exception:
        return None, None


def _essentia_make_frame_kernel(kernel_class):
    if kernel_class is None or not callable(kernel_class):
        raise RuntimeError("Essentia kernel unavailable")

    try:
        return kernel_class(frameSize=ESSENTIA_FRAME_SIZE, hopSize=ESSENTIA_HOP_SIZE)
    except Exception:
        # Some kernels may not accept frame parameters in every Essentia build.
        return kernel_class()


def _essentia_mean_feature(kernel_factory, samples, sample_rate):
    try:
        kernel = kernel_factory()
        _essentia_set_sample_rate(kernel, sample_rate)
        out = kernel(samples)
        arr = _essentia_to_float_array(out)
        if arr.size == 0:
            return None
        val = float(np.mean(arr))
        return val if np.isfinite(val) else None
    except Exception:
        return None


def _essentia_as_vector(samples):
    """Ensure float32 mono vector; wrap as essentia.array when available
    (some algorithms reject plain numpy arrays)."""
    arr = np.asarray(samples, dtype=np.float32).reshape(-1)
    try:
        return essentia.array(arr)
    except Exception:
        return arr


def _essentia_resolve_kernel(name):
    """Resolve an essentia.standard algorithm by name, even if the module-level
    optional binding failed at import time (e.g. delayed import issues)."""
    existing = globals().get(name)
    if existing is not None and callable(existing):
        return existing
    if not ESSENTIA_AVAILABLE or essentia is None:
        return None
    try:
        return getattr(essentia.standard, name)
    except Exception:
        return None


def _essentia_tempo_and_beats(samples, sample_rate):
    """Try several Essentia rhythm/BPM algorithms. Builds differ in which
    constructors and return layouts they support; failures used to surface as
    a silent 'tempo: unavailable' even when librosa had a solid estimate."""
    vec = _essentia_as_vector(samples)
    duration = len(samples) / float(sample_rate) if sample_rate else 0.0
    last_err = None

    attempts = []

    Rhythm2013 = _essentia_resolve_kernel("RhythmExtractor2013")
    if Rhythm2013 is not None:
        for method in ("multifeature", "degara", None):
            attempts.append(("RhythmExtractor2013", Rhythm2013, method))

    Rhythm = _essentia_resolve_kernel("RhythmExtractor")
    if Rhythm is not None:
        attempts.append(("RhythmExtractor", Rhythm, None))

    Percival = _essentia_resolve_kernel("PercivalBpmEstimator")
    if Percival is not None:
        attempts.append(("PercivalBpmEstimator", Percival, None))

    for name, cls, method in attempts:
        try:
            if method is not None:
                try:
                    kernel = cls(method=method)
                except TypeError:
                    kernel = cls()
            else:
                kernel = cls()
            _essentia_set_sample_rate(kernel, sample_rate)
            out = kernel(vec)

            tempo = None
            beats = np.array([], dtype=float)

            if isinstance(out, (tuple, list)):
                tempo = _essentia_first_float(out[0]) if out else None
                # RhythmExtractor2013: bpm, beats, confidence, estimates, intervals
                if len(out) >= 2:
                    beats = _essentia_to_float_array(out[1])
                    # If out[1] is a scalar confidence, beats may be empty —
                    # try later slots that look like a beat array.
                    if beats.size <= 1 and len(out) >= 2:
                        for slot in out[1:]:
                            cand = _essentia_to_float_array(slot)
                            if cand.size > 4:
                                beats = cand
                                break
            else:
                tempo = _essentia_first_float(out)

            if tempo is None or not np.isfinite(tempo) or tempo <= 0:
                continue

            if beats.size and duration > 0 and np.max(beats) > max(duration * 2.0, 10.0):
                # Frame indices rather than seconds
                beats = beats / float(sample_rate)

            beats = beats[np.isfinite(beats)] if beats.size else np.array([], dtype=float)
            return float(tempo), beats
        except Exception as e:
            last_err = e
            continue

    return None, np.array([], dtype=float)


def _key_profile_kwargs_for_genre(genre_hint=None):
    """Ordered KeyExtractor profileType kwargs lists by coarse genre family.

    Electronic/dance → prefer edma (and related) first.
    Rock/folk/classical/ballad → prefer temperley / krumhansl-style first.
    Always fall back through the full set so a weak preferred profile cannot
    silence a much stronger alternate reading.
    """
    fam = "other"
    try:
        fam = _bpm_genre_family_from_hint(genre_hint) if genre_hint else "other"
        # Map hiphop/dnb toward electronic-ish profile preference
        if fam in ("dnb", "hiphop"):
            fam = "electronicish"
        if fam == "ballad":
            fam = "rockish"
    except Exception:
        fam = "other"

    electronic_first = [
        {"profileType": "edma"},
        {"profileType": "bgate"},
        {"profileType": "temperley"},
        {"profileType": "krumhansl"},
        {},
    ]
    tonal_first = [
        {"profileType": "temperley"},
        {"profileType": "krumhansl"},
        {"profileType": "bgate"},
        {"profileType": "edma"},
        {},
    ]
    balanced = [
        {"profileType": "bgate"},
        {"profileType": "temperley"},
        {"profileType": "edma"},
        {"profileType": "krumhansl"},
        {},
    ]
    if fam == "electronicish":
        return electronic_first, "electronic/dance (edma-first)"
    if fam in ("rockish", "popish"):
        return tonal_first, f"{fam} (temperley/krumhansl-first)"
    return balanced, "balanced"


def _parse_key_extractor_output(out):
    """Normalize KeyExtractor / Key output to (key_name_with_mode, strength_or_None)."""
    key_name = None
    scale = None
    strength = None

    if isinstance(out, (tuple, list)):
        if len(out) >= 3:
            key_name, scale, strength = out[0], out[1], out[2]
        elif len(out) == 2:
            key_name, second = out[0], out[1]
            if isinstance(second, (str, bytes)) or (
                second is not None and not isinstance(second, (int, float, np.floating))
                and _essentia_first_float(second) is None
            ):
                scale = second
            else:
                strength = second
        elif len(out) == 1:
            key_name = out[0]
    else:
        key_name = out

    if isinstance(key_name, bytes):
        key_name = key_name.decode("utf-8", "ignore")
    if isinstance(scale, bytes):
        scale = scale.decode("utf-8", "ignore")

    key_name = str(key_name).strip() if key_name is not None else ""
    scale = str(scale).strip().lower() if scale is not None else ""

    if not key_name or key_name.lower() in ("", "none", "unknown", "nan"):
        return None, None

    if scale in ("major", "minor", "maj", "min"):
        scale_norm = "major" if scale.startswith("maj") else "minor"
        key_name = f"{key_name} {scale_norm}"

    return key_name, _essentia_first_float(strength)


def _energy_key_windows(samples, sample_rate, window_sec=25.0, max_windows=4):
    """Pick up to max_windows high-energy segments for key voting.

    Avoids estimating key only on a quiet intro / fade. Falls back to a single
    full-clip window when the file is short or energy is flat.
    """
    try:
        n = len(samples)
        sr = float(sample_rate)
        if n < int(sr * 3):
            return [(0, n)]
        win = int(window_sec * sr)
        if win <= 0 or n <= win:
            return [(0, n)]
        # Hop so we scan the file; score by mean square energy
        hop = max(win // 2, int(5.0 * sr))
        scored = []
        start = 0
        while start + win <= n:
            seg = samples[start:start + win]
            eng = float(np.mean(np.square(seg.astype(np.float64))))
            scored.append((eng, start, start + win))
            start += hop
        if not scored:
            return [(0, n)]
        scored.sort(key=lambda t: t[0], reverse=True)
        # Keep top windows, in time order, de-duplicating heavy overlap
        picked = []
        for eng, a, b in scored:
            if any(abs(a - pa) < win * 0.4 for pa, pb in picked):
                continue
            picked.append((a, b))
            if len(picked) >= max_windows:
                break
        picked.sort(key=lambda ab: ab[0])
        return picked or [(0, n)]
    except Exception:
        return [(0, len(samples))]


def _essentia_key_on_vector(vec, sample_rate, ctor_kwargs_list):
    """Run KeyExtractor over ctor_kwargs_list; return (key, strength, profile_note)."""
    KeyCls = _essentia_resolve_kernel("KeyExtractor")
    if KeyCls is None:
        return None, None, ""

    best_key, best_strength, best_prof = None, None, ""
    for kwargs in ctor_kwargs_list:
        try:
            try:
                key_kernel = KeyCls(**kwargs) if kwargs else KeyCls()
            except TypeError:
                key_kernel = KeyCls()
            _essentia_set_sample_rate(key_kernel, sample_rate)
            out = key_kernel(vec)
            key_name, strength_val = _parse_key_extractor_output(out)
            if key_name is None:
                continue
            prof = kwargs.get("profileType", "default") if kwargs else "default"
            if strength_val is None:
                if best_key is None:
                    best_key, best_strength, best_prof = key_name, None, prof
                continue
            # Small bonus for preferred (earlier) profiles when strengths are close
            # is applied by caller via vote aggregation; here pure strength wins.
            if best_strength is None or strength_val > best_strength:
                best_key, best_strength, best_prof = key_name, strength_val, prof
        except Exception:
            continue
    return best_key, best_strength, best_prof


def _essentia_key_hpcp_fallback(samples, sample_rate):
    """Lower-level HPCP → Key path with higher resolution and harmonic weighting.

    Mirrors the Deep Cuts-style idea: denser chroma (pcpSize=36), harmonic
    contribution, non-linear HPCP weighting, then key profile matching.
    Used only when KeyExtractor is missing or returns nothing useful.
    """
    try:
        FrameCutter = _essentia_resolve_kernel("FrameCutter")
        Windowing = _essentia_resolve_kernel("Windowing")
        Spectrum = _essentia_resolve_kernel("Spectrum")
        SpectralPeaks = _essentia_resolve_kernel("SpectralPeaks")
        HPCP = _essentia_resolve_kernel("HPCP")
        Key = _essentia_resolve_kernel("Key")
        if not all([FrameCutter, Windowing, Spectrum, SpectralPeaks, HPCP, Key]):
            return None, None

        # Limit runtime on long files
        max_sec = min(len(samples) / float(sample_rate), 120.0)
        seg = samples[: int(max_sec * sample_rate)]
        frame_size = 4096
        hop = 2048

        try:
            fc = FrameCutter(frameSize=frame_size, hopSize=hop)
        except TypeError:
            fc = FrameCutter()
        try:
            win = Windowing(type="blackmanharris62")
        except TypeError:
            try:
                win = Windowing(type="hann")
            except TypeError:
                win = Windowing()
        spec = Spectrum()
        try:
            peaks = SpectralPeaks(
                sampleRate=float(sample_rate),
                maxPeaks=60,
                magnitudeThreshold=0.00001,
                orderBy="magnitude",
            )
        except TypeError:
            peaks = SpectralPeaks()
        try:
            hpcp = HPCP(
                sampleRate=float(sample_rate),
                size=36,           # higher-resolution pitch class profile
                referenceFrequency=440.0,
                harmonics=4,       # harmonic contribution
                nonLinear=True,    # non-linear weighting
                bandPreset=True,
            )
        except TypeError:
            try:
                hpcp = HPCP(size=36, nonLinear=True, harmonics=4)
            except TypeError:
                try:
                    hpcp = HPCP(size=36)
                except TypeError:
                    hpcp = HPCP()

        # Average HPCP over frames
        hpcp_sum = None
        n_frames = 0
        # Feed samples as essentia vector; FrameCutter may need sequential calls
        try:
            from essentia import array as esarr
            buf = esarr(seg.astype(np.float32))
        except Exception:
            buf = _essentia_as_vector(seg)

        # Some builds: FrameCutter(audio) returns frames iteratively
        try:
            fc.reset()
        except Exception:
            pass
        pos = 0
        while pos + frame_size <= len(seg) and n_frames < 400:
            frame = seg[pos:pos + frame_size]
            pos += hop
            try:
                try:
                    fr = win(_essentia_as_vector(frame))
                except Exception:
                    fr = frame
                sp = spec(fr) if not isinstance(fr, tuple) else spec(fr[0] if fr else frame)
                pk = peaks(sp)
                # SpectralPeaks often returns (frequencies, magnitudes)
                if isinstance(pk, (tuple, list)) and len(pk) >= 2:
                    freqs, mags = pk[0], pk[1]
                else:
                    continue
                hp = hpcp(freqs, mags)
                hp = np.asarray(hp, dtype=np.float64).reshape(-1)
                if hpcp_sum is None:
                    hpcp_sum = np.zeros_like(hp)
                if hpcp_sum.shape != hp.shape:
                    continue
                hpcp_sum += hp
                n_frames += 1
            except Exception:
                continue

        if hpcp_sum is None or n_frames < 4:
            return None, None
        hpcp_mean = hpcp_sum / float(n_frames)

        # Key profile match — try a few profile names
        best_key, best_strength = None, None
        for prof in ("temperley", "krumhansl", "edma", "bgate", None):
            try:
                if prof:
                    key_algo = Key(profileType=prof)
                else:
                    key_algo = Key()
            except TypeError:
                try:
                    key_algo = Key()
                except Exception:
                    continue
            except Exception:
                continue
            try:
                out = key_algo(hpcp_mean)
            except Exception:
                try:
                    out = key_algo(_essentia_as_vector(hpcp_mean))
                except Exception:
                    continue
            key_name, strength_val = _parse_key_extractor_output(out)
            if key_name is None:
                continue
            if strength_val is None:
                if best_key is None:
                    best_key, best_strength = key_name, None
                continue
            if best_strength is None or strength_val > best_strength:
                best_key, best_strength = key_name, strength_val
        return best_key, best_strength
    except Exception:
        return None, None


def _essentia_key(samples, sample_rate, genre_hint=None):
    """Estimate musical key via Essentia.

    Pipeline (Deep-Cuts-inspired, still pure Essentia):
      1. Genre-ordered KeyExtractor profiles (edma-first for electronic, etc.)
      2. Vote across a few high-energy windows rather than one global pass
      3. Fall back to higher-resolution HPCP (pcpSize=36, harmonics, nonLinear)
         → Key if KeyExtractor yields nothing useful

    Returns (key_name, strength) as before so callers stay compatible.
    """
    if samples is None or len(samples) == 0:
        return None, None

    ctor_kwargs_list, prof_note = _key_profile_kwargs_for_genre(genre_hint)
    windows = _energy_key_windows(samples, sample_rate)

    # Aggregate votes: key_norm -> (total_strength, count, display_name)
    votes = {}
    any_result = False
    for a, b in windows:
        seg = samples[a:b]
        if len(seg) < int(float(sample_rate) * 2):
            continue
        vec = _essentia_as_vector(seg)
        key_name, strength_val, _prof = _essentia_key_on_vector(
            vec, sample_rate, ctor_kwargs_list
        )
        if key_name is None:
            continue
        any_result = True
        norm = _normalize_key_for_compare(key_name) or key_name.lower()
        # Prefer profiles: slight weight already via strength; count ties
        w = float(strength_val) if strength_val is not None else 0.15
        prev = votes.get(norm)
        if prev is None:
            votes[norm] = [w, 1, key_name]
        else:
            prev[0] += w
            prev[1] += 1

    best_key, best_strength = None, None
    if votes:
        # Rank by (vote count, total strength)
        ranked = sorted(votes.items(), key=lambda kv: (kv[1][1], kv[1][0]), reverse=True)
        _norm, (tot_w, cnt, display) = ranked[0]
        best_key = display
        # Report mean strength when available
        best_strength = round(tot_w / max(cnt, 1), 3) if tot_w > 0 else None

    if best_key is None:
        # Single full-clip KeyExtractor pass as last KeyExtractor try
        vec = _essentia_as_vector(samples)
        best_key, best_strength, _ = _essentia_key_on_vector(
            vec, sample_rate, ctor_kwargs_list
        )

    if best_key is None:
        best_key, best_strength = _essentia_key_hpcp_fallback(samples, sample_rate)

    return best_key, best_strength


def refine_essentia_key_with_genre(local_path, genre_hint, previous_key=None, previous_strength=None):
    """Optional *corroboration* pass for key estimation.

    Genre is never allowed to rewrite the primary key by itself. The returned
    candidate is informational so callers can expose disagreement without
    introducing circular genre -> key -> genre reasoning.
    """
    if not genre_hint or not local_path or str(local_path).startswith(("http://", "https://")):
        return previous_key, previous_strength, ""
    if not ENABLE_ESSENTIA_REPORT:
        return previous_key, previous_strength, ""
    try:
        samples, sample_rate = _essentia_load_audio(local_path, ESSENTIA_MAX_SECONDS)
        if samples is None or len(samples) == 0:
            return previous_key, previous_strength, ""
        key2, str2 = _essentia_key(samples, sample_rate, genre_hint=genre_hint)
        if not key2:
            return previous_key, previous_strength, ""
        if previous_key and _normalize_key_for_compare(previous_key) and _normalize_key_for_compare(key2) == _normalize_key_for_compare(previous_key):
            return previous_key, previous_strength, (
                f"genre-conditioned Essentia reaffirmed {key2} (prior={genre_hint}, strength={str2})."
            )
        return previous_key, previous_strength, (
            f"genre-conditioned Essentia independently suggested {key2} "
            f"(prior={genre_hint}, strength={str2}); primary key was not changed by genre."
        )
    except Exception:
        return previous_key, previous_strength, ""

def build_essentia_report(local_path, genre_hint=None):
    """
    Optional independent Essentia report.

    This is intentionally limited to objective audio measurements such as tempo/beat,
    key, spectral/timbre proxies, and dynamics. It should not be used by the writer
    to infer genre or vocal identity.

    genre_hint (optional): free-form genre label used to order KeyExtractor
    profiles (edma-first for electronic/dance, temperley/krumhansl for rock/folk).
    """
    if not ENABLE_ESSENTIA_REPORT:
        return ""

    if local_path.startswith(("http://", "https://")):
        # Essentia is being used here on local files only, matching the existing DSP path.
        return ""

    samples, sample_rate = _essentia_load_audio(local_path, ESSENTIA_MAX_SECONDS)
    if samples is None or len(samples) == 0:
        return (
            "ESSENTIA OBJECTIVE MEASUREMENTS unavailable "
            "(could not load audio via MonoLoader/AudioLoader — "
            "check that Essentia can read this WAV path)."
        )

    lines = []
    duration = len(samples) / float(sample_rate)
    lines.append(f"ESSENTIA OBJECTIVE MEASUREMENTS (first {round(duration, 2)} s)")

    # Tempo and beat timing.
    tempo, beats = _essentia_tempo_and_beats(samples, sample_rate)

    # Compute median-IBI BPM first so it can corroborate the raw reading
    # before the half-time heuristic runs (see _preferred_tempo docstring --
    # this is the exact case that previously forced a genuine ~156 BPM
    # reading down to ~78 BPM despite both figures agreeing).
    essentia_median_ibi_bpm = None
    if beats.size > 1:
        ibis_for_corroboration = np.diff(beats)
        if ibis_for_corroboration.size:
            med = float(np.median(ibis_for_corroboration))
            if med > 0:
                essentia_median_ibi_bpm = round(60.0 / med, 1)

    if tempo is not None:
        preferred, cands, note = _preferred_tempo(tempo, corroborating_bpm=essentia_median_ibi_bpm)
        lines.append(f"Essentia estimated tempo (raw detector): {round(tempo, 1)} BPM")
        if preferred is not None and abs(preferred - round(tempo, 1)) > 0.5:
            lines.append(f"Essentia preferred musical tempo for discussion: {preferred} BPM")
        if len(cands) > 1:
            lines.append("Essentia tempo candidates (half/double interpretations): " + ", ".join(f"{c} BPM" for c in cands))
        if note:
            lines.append(note)
    else:
        lines.append("Essentia estimated tempo: unavailable")

    if beats.size:
        ibis = np.diff(beats)
        median_ibis = float(np.median(ibis)) if len(ibis) else None
        mean_ibis = float(np.mean(ibis)) if len(ibis) else None
        std_ibis = float(np.std(ibis)) if len(ibis) > 1 else None

        lines.append(f"Essentia detected beats: {len(beats)}")
        lines.append(
            f"first beat at {round(float(beats[0]), 2)} s, last beat at {round(float(beats[-1]), 2)} s"
        )

        if median_ibis is not None and median_ibis > 0:
            lines.append(
                f"Essentia median inter-beat interval: "
                f"{round(median_ibis, 3)} s ({round(60.0 / median_ibis, 1)} BPM)"
            )

        if mean_ibis is not None and std_ibis is not None and mean_ibis > 0:
            lines.append(f"Essentia beat regularity (std/mean IBI): {round(std_ibis / mean_ibis, 3)}")

    # Key estimation (genre-ordered profiles + energy-window vote + HPCP fallback).
    key_name, key_strength = _essentia_key(samples, sample_rate, genre_hint=genre_hint)
    if key_name:
        strength_text = f", strength={round(key_strength, 3)}" if key_strength is not None else ""
        hint_txt = f", profile prior={genre_hint}" if genre_hint else ""
        lines.append(f"Essentia estimated key: {key_name}{strength_text}{hint_txt}")
    else:
        lines.append("Essentia estimated key: unavailable")

    # Spectral/timbre proxies on a shorter segment to keep runtime reasonable.
    lowlevel_seconds = min(duration, ESSENTIA_LOWLEVEL_MAX_SECONDS)
    seg = samples[: int(lowlevel_seconds * sample_rate)]

    if len(seg) >= ESSENTIA_FRAME_SIZE * 2:
        spectral_lines = []
        seg_vec = _essentia_as_vector(seg)

        def _frame_factory(kernel_name):
            cls = _essentia_resolve_kernel(kernel_name)
            if cls is None:
                raise RuntimeError(f"{kernel_name} unavailable")
            return _essentia_make_frame_kernel(cls)

        centroid = _essentia_mean_feature(
            lambda: _frame_factory("SpectralCentroidTime"),
            seg_vec,
            sample_rate,
        )
        if centroid is not None:
            spectral_lines.append(f"Essentia brightness (spectral centroid): {round(centroid, 1)} Hz")

        flatness = _essentia_mean_feature(
            lambda: _frame_factory("SpectralFlatness"),
            seg_vec,
            sample_rate,
        )
        if flatness is not None:
            spectral_lines.append(f"Essentia noise-likeness (spectral flatness): {round(flatness, 4)}")

        zcr = _essentia_mean_feature(
            lambda: _frame_factory("ZeroCrossingRate"),
            seg_vec,
            sample_rate,
        )
        if zcr is not None:
            spectral_lines.append(f"Essentia zero-crossing rate: {round(zcr, 4)}")

        rms = _essentia_mean_feature(
            lambda: _frame_factory("RMS"),
            seg_vec,
            sample_rate,
        )
        if rms is not None and rms > 0:
            peak = float(np.max(np.abs(seg)))
            spectral_lines.append(f"Essentia RMS level: {round(rms, 5)}")

            if peak > 0:
                crest_db = 20 * np.log10(peak / rms)
                if np.isfinite(crest_db):
                    spectral_lines.append(
                        f"Essentia RMS-based crest factor proxy: {round(float(crest_db), 1)} dB"
                    )

        if spectral_lines:
            lines.append("")
            lines.extend(spectral_lines)

    lines.append(
        "Note: Essentia values are objective measurements, not genre labels. "
        "Use them as cross-checks for tempo/beat/key/timbre/dynamics only."
    )

    return "\n".join(lines)
# ---------------------------------------------------------------------------


def _normalize_vocal_tag(value):
    value = (value or "").lower().strip()
    value = re.sub(r"[^a-z0-9]+", "_", value)
    return value.strip("_")


def _resolve_lead_tag_variant(tag):
    """Map near-miss lead-tag spellings onto the canonical taxonomy.

    Explicit aliases cover the common cases; this strips hedge affixes
    ("_likely", "likely_", "_probable", "possible_") so a spelling nobody
    anticipated still lands on a real category instead of "unknown".

    Returning "unknown" is not a safe default here: both age guards ignore it,
    so an unparsed tag silently switches off the entire acoustic age-correction
    layer and lets the identity pass decide alone.
    """
    tag = _normalize_vocal_tag(tag)
    if not tag:
        return ""
    if tag in VOCAL_LEAD_TAGS:
        return tag
    if tag in VOCAL_LEAD_ALIASES:
        return VOCAL_LEAD_ALIASES[tag]

    # Trailing words on the same line ("post_puberty_male (medium confidence)",
    # "female_teen_adult likely") used to collapse the whole capture into an
    # unknown tag, which silently disabled both age guards. Accept the
    # longest canonical tag/alias the capture starts with.
    _both = "female" in tag and re.search(r"(?<!fe)male", tag)
    for known in ([] if _both else sorted(set(VOCAL_LEAD_TAGS) | set(VOCAL_LEAD_ALIASES), key=len, reverse=True)):
        if tag.startswith(known + "_") and known not in ("unknown",):
            return VOCAL_LEAD_ALIASES.get(known, known) if known not in VOCAL_LEAD_TAGS else known

    stripped = re.sub(r"^(?:likely|probably|probable|possible|possibly|sounds_like)_", "", tag)
    stripped = re.sub(r"_(?:likely|probable|probably|possible|possibly)$", "", stripped)
    if stripped != tag:
        if stripped in VOCAL_LEAD_TAGS:
            return stripped
        if stripped in VOCAL_LEAD_ALIASES:
            return VOCAL_LEAD_ALIASES[stripped]
    return ""


def _lead_from_category_modifier(category, modifier):
    category = _normalize_vocal_tag(category)
    modifier = _normalize_vocal_tag(modifier)

    if "child" in category:
        if "male" in modifier and "female" not in modifier:
            return "child_male_likely"
        if "female" in modifier and "male" not in modifier:
            return "child_female_likely"
        return "child_gender_uncertain"

    if category in ("post_puberty_male", "adult_male", "post_pubertal_male") or (
        "post" in category and "pubert" in category and "male" in category and "female" not in category
    ):
        return "post_puberty_male"

    if any(token in category for token in ("adolescent", "transitional", "changing_voice", "voice_change")):
        return "adolescent_male_likely"

    if category in ("female_teen_adult", "adult_female", "young_female") or (
        "female" in category and "child" not in category
    ):
        return "female_teen_adult"

    if category in ("uncertain", "transitional"):
        if "adolescent" in modifier or "transitional" in modifier:
            return "adolescent_male_likely"
        if any(token in modifier for token in ("child", "young")):
            return "child_gender_uncertain"
        return "uncertain"

    return ""


def _parse_vocals_present_flag(text):
    """Parse VOCALS_PRESENT from listening-model output. Accepts underscore or space forms
    and common synonyms. Returns 'yes'|'no'|'uncertain'|'' (unparsed)."""
    if not text:
        return ""
    text = _strip_md_emphasis(text)
    m = re.search(
        # Also accepts the "VOCAL PRESENCE: yes" spelling the listening model often
        # uses, which this regex used to miss entirely (flag left unparsed).
        r"\bVOCALS?[_\s]?PRESEN(?:T|CE)\s*[=:\-–—]?\s*(yes|no|uncertain|instrumental|true|false)",
        text,
        re.IGNORECASE,
    )
    if not m:
        # Free-text fallbacks common in failed short-clip passes
        low = text.lower()
        # "instrumental" only counts when it describes the whole track: "an
        # instrumental intro / break / solo / backing" says nothing about
        # whether there is a singer (the rock test track's description pass
        # opens "an instrumental intro establishes the guitar motif").
        if re.search(
            r"\b(?:no clear(?:ly)? (?:singable )?lead|no (?:clear )?vocals?(?: detected)?|"
            r"instrumental(?![\s\-]+(?:only[\s\-]+)?(?:intro|introduction|opening|break|breakdown|"
            r"bridge|section|passage|solo|outro|coda|interlude|hook|riff|motif|part|backing|"
            r"backdrop|bed|arrangement|accompaniment|layer|element|line|tag|fill|build|"
            r"lead-in|verse|chorus|stretch|texture|groove|figure|theme|melod(?:y|ies)|"
            r"segment|moment|space|gap|pause|swell|lick)(?:e?s)?\b)(?:\s+only)?|"
            r"no human voice)\b",
            low,
        ):
            if not re.search(r"\bVOCALS[_\s]?PRESENT\s*[=:\-–—]?\s*yes", text, re.I):
                return "no"
        return ""
    val = m.group(1).strip().lower()
    if val in ("yes", "true"):
        return "yes"
    if val in ("no", "instrumental", "false"):
        return "no"
    return "uncertain"


def _vocal_report_pitch_is_voice_evidence(vocal_objective_report):
    """Can this report's pitch reading stand as evidence of a human voice?

    No when it was measured on the full mix (pyin there tracks whatever is
    loudest and pitched -- a pad, a bass, a guitar), or when only a sliver of
    the scanned audio was voiced. Reports without either line (older saved
    analyses) keep the previous behaviour.
    """
    rep = str(vocal_objective_report or "").lower()
    if "measurement source: full mix" in rep:
        return False
    m = re.search(r"voiced frames:\s*([0-9]+(?:\.[0-9]+)?)\s*%", rep)
    if m:
        try:
            if float(m.group(1)) / 100.0 < float(VOCAL_PITCH_EVIDENCE_MIN_VOICED_FRACTION):
                return False
        except ValueError:
            pass
    return True


def _objective_evidence_of_vocals(median_f0=None, vocal_objective_report="", stem_midi_report=""):
    """True when DSP/stems independently suggest a human voice even if the listening
    model's vocal pass said no vocals / instrumental.

    A pitch reading only counts when it came from the isolated vocal stem and
    enough of the audio was voiced (see _vocal_report_pitch_is_voice_evidence).
    Previously ANY median f0 between 70 and 1100 Hz -- i.e. any pitched sound,
    including a synth pad measured on the full mix -- counted as a voice, and so
    did any line mentioning notes in the vocals stem, which on an instrumental
    is just whatever the separator routed there. Neither is evidence of a singer.
    """
    pitch_ok = _vocal_report_pitch_is_voice_evidence(vocal_objective_report)
    if pitch_ok:
        try:
            if median_f0 is not None:
                f0 = float(median_f0)
                # Human sung range (rough); exclude obvious noise floors
                if 70.0 <= f0 <= 1100.0:
                    return True
        except (TypeError, ValueError):
            pass
        rep = (vocal_objective_report or "").lower()
        if re.search(r"voiced pitch median:\s*[1-9]", rep):
            return True
    return False


# A sentence in the main listening pass that states the track has no vocal.
# Deliberately narrow: "an instrumental intro/break/solo" must NOT match.
_INSTRUMENTAL_PROSE_RE = re.compile(
    r"(?i)\b(?:"
    r"(?:this|the)\s+(?:piece|track|song|recording|composition|tune|cut)\s+is\s+"
    r"(?:an?\s+|entirely\s+|purely\s+|fully\s+|wholly\s+)*instrumental\b"
    r"|(?:an?|purely|entirely|fully)\s+instrumental\s+(?:[a-z\-]+\s+){0,2}"
    r"(?:piece|track|song|recording|composition|number|work)\b"
    r"|there\s+(?:are|is)\s+no\s+(?:lead\s+)?vocals?\b"
    r"|no\s+(?:lead\s+)?vocals?\s+(?:are\s+|is\s+)?(?:present|audible|detected)"
    r"|(?:has|contains|features)\s+no\s+(?:lead\s+)?vocals?\b"
    r"|without\s+(?:any\s+)?(?:lead\s+)?vocals?\b"
    r"|absence\s+of\s+(?:vocals?|lyrics|a\s+vocal|singing)"
    r")"
)

VOCAL_ARBITRATION_MARKER = "VOCALS_PRESENT=no  # from vocal-presence arbitration"


def _main_pass_says_instrumental(text):
    """True when the main listening pass states the recording has no vocal --
    an explicit VOCALS_PRESENT=no field, or a clear prose statement."""
    t = _strip_md_emphasis(str(text or ""))
    # A field the model pasted into a run of fields is not an answer (see
    # _moss_copied_fields): on the post-punk test track and another test track "none (...)" had been
    # copied into VOCALS_PRESENT and every field around it.
    t = _moss_drop_copied_field_lines(t)
    m = re.search(
        r"\bVOCALS?[_\s]?PRESEN(?:T|CE)\s*[=:\-–—]?\s*(yes|no|uncertain|instrumental|true|false)",
        t, re.IGNORECASE,
    )
    if m:
        # An answer limited to a stretch of time ("none (0.00s-13.92s)": no
        # voice in the intro) is not a claim about the whole recording.
        rest = t[m.end():].split("\n", 1)[0]
        if _VOCAL_ANSWER_TIME_SPAN_RE.search(rest):
            return False
        return m.group(1).lower() in ("no", "instrumental", "false")
    return bool(_INSTRUMENTAL_PROSE_RE.search(t))


_VOCAL_ANSWER_TIME_SPAN_RE = re.compile(
    r"\d+(?:\.\d+)?\s*s\s*[-–—]\s*\d+(?:\.\d+)?\s*s\b|\b\d{1,2}:\d{2}\b")


def _voiced_fraction_from_report(vocal_objective_report):
    m = re.search(r"voiced frames:\s*([0-9]+(?:\.[0-9]+)?)\s*%", str(vocal_objective_report or ""), re.I)
    try:
        return float(m.group(1)) / 100.0 if m else None
    except ValueError:
        return None


def _stem_level_vs_mix_db(stem_path, mix_path):
    """RMS of a stem relative to the mix, in dB (negative = below). None on
    any failure. Streams both files so memory stays flat."""
    def _rms(path):
        tot, n = 0.0, 0
        try:
            import soundfile as _sf
            for block in _sf.blocks(str(path), blocksize=262144, always_2d=True):
                b = np.asarray(block, dtype=np.float64).mean(axis=1)
                tot += float(np.dot(b, b)); n += b.size
        except Exception:
            try:
                y, _sr = librosa.load(str(path), sr=None, mono=True)
                tot, n = float(np.dot(y.astype(np.float64), y.astype(np.float64))), int(y.size)
            except Exception:
                return None
        return (tot / n) ** 0.5 if n else None
    if not stem_path or not mix_path:
        return None
    a, b = _rms(stem_path), _rms(mix_path)
    if not a or not b:
        return None
    return float(20.0 * np.log10(a / b))


# A person, not an instrument that "sings": "the trumpet sings" never counts.
_HEARD_VOICE_RE = re.compile(
    r"(?i)\b(?:vocals?|vocalist|singer|rapper|crooner|"
    r"baritone|tenor|soprano|mezzo(?:-soprano)?|contralto)\b")
# The words, not "lyrical phrasing" on a saxophone.
_HEARD_LYRICS_RE = re.compile(
    r"(?i)\blyrics?\b|\blyrical\s+(?:content|themes?|subject|focus|narrative|imagery)\b")
_HEARD_NEGATION_RE = re.compile(
    r"(?i)\b(?:no|not|without|absence|absent|lacks?|lacking|instrumental|wordless|devoid)\b|n't\b")
_HEARD_QUOTE_RE = re.compile(r"[“\"]([^”\"\n]{6,160})[”\"]")


def _other_pass_heard_singing(other_text, vocal_result):
    """dev73: True when a SEPARATE listening pass (the era pass's free
    description) plainly heard a singer: the dedicated vocal pass answered
    that a voice is present, and the other pass has a sentence naming a
    singer and a sentence about the lyrics (neither negated) and quotes at
    least two sung lines of three or more words.

    One half-spoken big-band test scan is sung, half-spoken, over a
    big band. The main pass called it instrumental and the vocal stem was
    confidently pitched in only 1.5% of the audio (a near-spoken delivery
    under horns), so the arbitration declared it instrumental -- while the
    era pass described "a male baritone" and quoted four lines it had heard
    (misheard, so not copied from the file's lyric tag, which no listening
    pass is given). Audio only: tags, lyrics files and identity play no part."""
    t = _strip_md_emphasis(str(other_text or ""))
    if not t or _parse_vocals_present_flag(vocal_result or "") != "yes":
        return False
    if _INSTRUMENTAL_PROSE_RE.search(t):     # it also calls the track instrumental
        return False
    sents = re.split(r"(?<=[.!?])\s+", t)
    voice = any(_HEARD_VOICE_RE.search(s) and not _HEARD_NEGATION_RE.search(s) for s in sents)
    lyrics = any(_HEARD_LYRICS_RE.search(s) and not _HEARD_NEGATION_RE.search(s) for s in sents)
    quotes = [q for q in _HEARD_QUOTE_RE.findall(t) if len(q.split()) >= 3]
    return bool(voice and lyrics and len(quotes) >= 2)


def _arbitrate_vocal_presence(main_text, vocal_result, vocal_objective_report,
                              vocal_stem_path=None, mix_path=None, other_text=""):
    """Decide whether the recording has a voice at all, before anything builds
    a singer profile on top of the answer.

    The main listening pass and the dedicated vocal pass were never reconciled:
    on an instrumental the main pass said "the piece is instrumental" while the
    vocal pass -- asked only about voices -- answered "VOCAL PRESENCE: yes,
    child, high", and that answer then fed the f0 duet upgrade and singer
    identity ("mixed_leads"). This arbitration only ever turns a vocal claim
    OFF, and only with an isolated vocal stem to measure:

      - the main pass says instrumental AND the vocal stem is weak (voiced in
        under VOCAL_PITCH_EVIDENCE_MIN_VOICED_FRACTION of the audio, no usable
        pitch reading, or >= VOCAL_ARBITRATION_STEM_BELOW_MIX_DB below the mix); or
      - the vocal stem is >= VOCAL_ARBITRATION_STRONG_BELOW_MIX_DB below the mix
        and almost never voiced, whatever the listening passes said.

    Returns a dict: instrumental (bool), reasons (list), level_db, voiced.
    """
    out = {"instrumental": False, "reasons": [], "level_db": None, "voiced": None,
           "main_says_instrumental": False}
    if not vocal_stem_path or not os.path.exists(str(vocal_stem_path)):
        return out          # nothing measured: leave the listening passes alone
    main_instr = _main_pass_says_instrumental(main_text)
    voiced = _voiced_fraction_from_report(vocal_objective_report)
    pitch_ok = (
        _vocal_report_pitch_is_voice_evidence(vocal_objective_report)
        and bool(re.search(r"voiced pitch median:\s*[1-9]", str(vocal_objective_report or ""), re.I))
    )
    level_db = _stem_level_vs_mix_db(vocal_stem_path, mix_path) if mix_path else None
    out.update(level_db=level_db, voiced=voiced, main_says_instrumental=main_instr)

    weak = []
    if voiced is not None and voiced < float(VOCAL_PITCH_EVIDENCE_MIN_VOICED_FRACTION):
        weak.append(f"the vocal stem is confidently pitched in only {voiced * 100:.1f}% of the scanned audio")
    elif not pitch_ok:
        weak.append("no usable voiced pitch in the vocal stem")
    _below = float(VOCAL_ARBITRATION_STEM_BELOW_MIX_DB)
    if FAINT_VOCAL_TEXTURE_CHECK:
        _below = min(_below, float(VOCAL_ARBITRATION_FAINT_BELOW_MIX_DB))
    if level_db is not None and level_db <= -_below:
        weak.append(f"the vocal stem sits {abs(level_db):.0f} dB below the mix")
    strong = (
        level_db is not None and level_db <= -float(VOCAL_ARBITRATION_STRONG_BELOW_MIX_DB)
        and (voiced is None or voiced < float(VOCAL_ARBITRATION_STRONG_MAX_VOICED))
    )
    # dev73: another listening pass heard a singer and quoted the lyrics, so
    # the main pass's "instrumental" is contradicted and cannot decide on its
    # own; only the measured "strong" case below still can.
    if main_instr and VOCAL_ARBITRATION_HEARD_LYRICS_GUARD and other_text:
        try:
            if _other_pass_heard_singing(other_text, vocal_result):
                out["other_pass_heard_singing"] = True
                main_instr = False
        except Exception:
            pass
    # The main pass's "instrumental" against the dedicated vocal pass's "yes"
    # cannot be settled by a low pitched-frame share alone when the vocal stem
    # is loud: real voices in these scans sit 2-9 dB below the mix and are
    # confidently pitched in as little as 0.2-6% of frames (rough or
    # consonant-heavy singing under a band), while separation residue on an
    # instrumental sits far lower. MOSS-Music's main pass has called sung
    # tracks instrumental ("Despite the absence of vocals" on a duo test track,
    # while its own melody notes described "vocal lines ... catchy and
    # singable"). Only the measured "strong" case can still decide then.
    if (main_instr and VOCAL_ARBITRATION_LOUD_STEM_GUARD and level_db is not None
            and level_db > -float(VOCAL_ARBITRATION_LOUD_STEM_DB)
            and _parse_vocals_present_flag(vocal_result or "") == "yes"):
        out["loud_stem_guard"] = True
        main_instr = False
    if (main_instr and weak) or strong:
        out["instrumental"] = True
        if main_instr:
            out["reasons"].append("the main listening pass describes the track as instrumental")
        out["reasons"].extend(weak)
    return out


def _faint_vocal_texture_reasons(arb, lyrics_text):
    """Reasons to rule a track instrumental after the lyrics pass: the vocal
    stem sits VOCAL_ARBITRATION_FAINT_BELOW_MIX_DB+ below the mix and Whisper
    transcribed fewer than FAINT_VOCAL_MAX_WHISPER_WORDS words. Else None.
    Only called when Whisper ran and there are no tagged lyrics."""
    if not FAINT_VOCAL_TEXTURE_CHECK or not isinstance(arb, dict):
        return None
    level = arb.get("level_db")
    if level is None or level > -float(VOCAL_ARBITRATION_FAINT_BELOW_MIX_DB):
        return None
    words = len(re.findall(r"[A-Za-z\u00C0-\u024F']+", str(lyrics_text or "")))
    if words >= int(FAINT_VOCAL_MAX_WHISPER_WORDS):
        return None
    return [f"the vocal stem sits {abs(level):.0f} dB below the mix -- far quieter than a sung lead",
            f"the lyrics pass could transcribe almost nothing from the track ({words} word{'s' if words != 1 else ''})"]


def _vocal_arbitration_block(arb, vocal_result=""):
    """Evidence text for an instrumental verdict. When the vocal pass claimed a
    voice, its output is kept only as a marked false positive; when it agreed
    (VOCALS_PRESENT=no) it is shown as agreeing."""
    reasons = "; ".join(arb.get("reasons") or []) or "the measurements show no voice"
    vr = _collapse_repeated_line_blocks(vocal_result or "").strip()
    agreed = bool(vr) and _parse_vocals_present_flag(vr) == "no"
    if agreed:
        tail = ("The dedicated vocal pass agrees. Treat this recording as instrumental: do not "
                "describe a singer, a vocal range, lyrics or a duet.")
    else:
        tail = ("The dedicated vocal pass's 'vocal present' answer, any singer profile, age/gender, "
                "pitch or range figures, multi-singer reading and audio-transcribed lyrics are a "
                "false positive and are SUPERSEDED. Treat this recording as instrumental: do not "
                "describe a singer, a vocal range, lyrics or a duet.")
    residue = ("Whatever the vocals stem holds is separation residue (instrument bleed). " if not arb.get("texture")
               else "Faint vocal-like sounds (a sample, or a chopped or processed voice used as texture) may "
                    "be audible in the background, but there is no sung lead: mention them, if at all, only "
                    "as a background texture. ")
    txt = (
        "\n\nVOCAL PRESENCE ARBITRATION: INSTRUMENTAL. " + reasons[:1].upper() + reasons[1:] + ". "
        + residue + tail
        + "\n" + VOCAL_ARBITRATION_MARKER
    )
    if vr:
        label = ("[agrees: no voice]" if agreed else
                 "[SUPERSEDED — listening-model false positive; see VOCAL PRESENCE ARBITRATION]")
        txt += "\n\nVOCAL / SINGER PROFILE (isolated dedicated pass) " + label + ":\n" + vr
    return txt


def _collapse_repeated_line_blocks(text):
    """Remove back-to-back repeats of the same block of lines. A generation
    that loops (the vocal pass was observed writing its whole answer four
    times) otherwise reaches the notes verbatim, repeated."""
    prev = str(text or "")
    # Largest blocks are tried first, so four copies can first collapse to two;
    # repeat until nothing changes.
    for _ in range(6):
        cur = _collapse_repeated_line_blocks_once(prev)
        if cur == prev:
            break
        prev = cur
    return prev


def _collapse_repeated_line_blocks_once(text):
    lines = str(text or "").split("\n")
    if len(lines) < 4:
        return str(text or "")

    # Compared loosely: a looping generation rarely repeats itself byte for
    # byte (an AI-generated test track's vocal pass wrote "LEAD_CATEGORY" in one copy and
    # "LEAD CATEGORY" in the next, three times over), so exact matching let
    # every copy through.
    def _k(line):
        return re.sub(r"[\s_]+", " ", str(line).strip().lower()).strip(" .:")

    keys = [_k(l) for l in lines]

    import difflib

    _num_re = re.compile(r"\d+(?:\.\d+)?")
    _tag_re = re.compile(r"^([^=:]{1,60})[=:]\s*(.*)$")

    def _eq(x, y):
        # Long lines may differ by a reworded word between copies ("pitch/
        # formant proxies" vs "... prefixes" in the rock track's looping vocal
        # pass). Never treated as the same: short lines that differ at all,
        # lines whose numbers differ (timestamps, Hz, counts), and "TAG=value"
        # / "Label: value" lines whose short value differs (male vs female,
        # 1 vs 2 voices) -- those are different content, not a loop.
        if x == y:
            return True
        if len(x) < 20 or len(y) < 20:
            return False
        if _num_re.findall(x) != _num_re.findall(y):
            return False
        mx, my = _tag_re.match(x), _tag_re.match(y)
        if mx and my:
            vx, vy = mx.group(2).strip(), my.group(2).strip()
            if (vx or vy) and (len(vx) <= 40 or len(vy) <= 40) and vx != vy:
                return False
        sm = difflib.SequenceMatcher(None, x, y, autojunk=False)
        if sm.real_quick_ratio() < 0.9 or sm.quick_ratio() < 0.9:
            return False
        return sm.ratio() >= 0.9

    def _same_block(j0, bk):
        if j0 + len(bk) > n:
            return False
        return all(_eq(keys[j0 + q], bk[q]) for q in range(len(bk)))

    out = []
    i = 0
    n = len(lines)
    while i < n:
        collapsed = False
        for size in range(min(40, (n - i) // 2), 1, -1):
            bkey = keys[i:i + size]
            if not any(bkey):
                continue
            j = i + size
            reps = 0
            while _same_block(j, bkey):
                j += size
                reps += 1
            if reps:
                # Keep the copy whose lines are written as the canonical
                # underscore tags (LEAD_CATEGORY, not "LEAD CATEGORY"): the
                # tag parser only reads those, so dropping that copy in
                # favour of a looser one would lose the tags.
                def _tag_lines(k0):
                    return sum(
                        1 for ln in lines[k0:k0 + size]
                        if re.match(r"\s*\**[A-Z]+_[A-Z_]+\**\s*[=:]", ln)
                    )
                best_k = max(range(reps + 1), key=lambda c: (_tag_lines(i + c * size), -c))
                keep_from = i + best_k * size
                # A final copy cut off part-way (the generation hit its
                # length limit) is dropped too: whole lines that match the
                # block's start, ending in one that is a prefix of the next.
                t = 0
                while t < size and j + t < n and keys[j + t] and _eq(keys[j + t], bkey[t]):
                    t += 1
                if t < size and j + t < n and keys[j + t] and bkey[t].startswith(keys[j + t]) \
                        and j + t + 1 >= n:
                    t += 1
                    j += t
                elif t and j + t >= n:
                    j += t
                out.extend(lines[keep_from:keep_from + size])
                i = j
                collapsed = True
                break
        if not collapsed:
            out.append(lines[i])
            i += 1
    return "\n".join(out)


def _stem_onset_vocal_salvage(vocal_result, revised, stem_midi_report):
    """Stem notes cannot establish human vocal presence: instruments leak in.
    Kept as a no-op for existing callers; actual voices use listening evidence.
    """
    return ""


def _salvage_false_no_vocals(
    vocal_result,
    no_clear_vocals,
    median_f0=None,
    vocal_objective_report="",
    stem_midi_report="",
    initial_lead="",
):
    """If the listening model claimed no vocals but objective pitch/stem evidence says otherwise,
    clear the no_clear_vocals flag and return a salvage note + adjusted flags.

    Returns (no_clear_vocals, salvage_note, forced_present_yes).
    """
    present = _parse_vocals_present_flag(vocal_result or "")
    if present == "yes":
        return False, "", True
    objective = _objective_evidence_of_vocals(
        median_f0=median_f0,
        vocal_objective_report=vocal_objective_report,
        stem_midi_report=stem_midi_report,
    )
    # Also salvage when a structured LEAD_PROFILE was parsed despite a free-text "no"
    lead_ok = initial_lead in VOCAL_LEAD_TAGS and initial_lead not in ("", "unknown")
    if no_clear_vocals or present == "no":
        if objective or lead_ok:
            note = (
                "VOCAL PRESENCE SALVAGE: MOSS-Music's vocal pass reported no/unclear vocals, "
                "but independent evidence indicates a human voice is present"
            )
            if median_f0 is not None:
                note += f" (objective voiced pitch median ~{median_f0} Hz)"
            if lead_ok:
                note += f" (structured LEAD_PROFILE={initial_lead})"
            note += (
                ". Treat VOCALS_PRESENT=yes. Demographic age/gender may still be uncertain. "
                "Do NOT tell the user there is no singable lead or that the track is instrumental "
                "solely because lyric transcription failed or the clip is short."
            )
            return False, note, True
    return bool(no_clear_vocals), "", present == "yes"


def _discard_vocal_choice_lists(text):
    text = _strip_md_emphasis(text)
    return "\n".join(line for line in text.splitlines()
                     if not (re.match(r"\s*(?:LEAD_PROFILE|LEAD_CATEGORY|GENDER_MODIFIER)\s*[=:]", line, re.I)
                             and "|" in line.split("=", 1)[-1].split(":", 1)[-1]))


def parse_vocal_tags(text):
    text = _discard_vocal_choice_lists(text)
    lead = ""
    backing = ""
    # Accept "=" or ":" — the listening model often emits "LEAD_PROFILE: ..." instead of "=".
    m = re.search(r'LEAD_PROFILE\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
    if m:
        lead = _resolve_lead_tag_variant(m.group(1))

    if lead not in VOCAL_LEAD_TAGS:
        cat_m = re.search(r'LEAD_CATEGORY\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
        mod_m = re.search(r'GENDER_MODIFIER\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
        if cat_m and mod_m:
            lead = _lead_from_category_modifier(cat_m.group(1), mod_m.group(1))
        elif cat_m:
            lead = _lead_from_category_modifier(cat_m.group(1), "")
        if lead not in VOCAL_LEAD_TAGS and cat_m:
            # The same hedge-spelling problem appears on LEAD_CATEGORY.
            lead = _resolve_lead_tag_variant(cat_m.group(1)) or lead

    lead = VOCAL_LEAD_ALIASES.get(lead, lead)
    if lead not in VOCAL_LEAD_TAGS:
        lead = "unknown"

    m = re.search(r'BACKING_PROFILES\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
    if m:
        backing = _normalize_vocal_tag(m.group(1))
    if backing not in VOCAL_BACKING_TAGS:
        backing = "uncertain"

    return lead, backing


def parse_multi_voice_fields(text):
    """Extract structured multi-singer fields from a vocal analysis pass.
    Returns a dict with keys that may be empty strings when unparsed.
    """
    text = _strip_md_emphasis(text or "")
    out = {
        "num_distinct_voices": "",
        "voice_arrangement": "",
        "co_lead_detail": "",
        "multi_voice_evidence": "",
    }

    m = re.search(
        r'NUM_DISTINCT_VOICES\s*[=:]\s*["\'<\[]?\s*([0-9]+\+?|uncertain|one|two|three[+]?|1|2|3)',
        text,
        re.IGNORECASE,
    )
    if m:
        raw = m.group(1).strip().lower()
        alias = {"one": "1", "two": "2", "three": "3", "three+": "3+"}
        out["num_distinct_voices"] = alias.get(raw, raw)

    m = re.search(
        r'VOICE_ARRANGEMENT\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\-]+)',
        text,
        re.IGNORECASE,
    )
    if m:
        arr = m.group(1).strip().lower().replace("-", "_")
        allowed = {
            "solo_lead", "lead_plus_backing", "duet_co_leads",
            "call_response", "group_unison", "uncertain",
        }
        if arr in allowed:
            out["voice_arrangement"] = arr

    m = re.search(
        r'CO_LEAD_DETAIL\s*[=:]\s*\[?([^\n\]]+)',
        text,
        re.IGNORECASE,
    )
    if m:
        detail = m.group(1).strip().strip("[]")
        if detail and detail.lower() not in ("none", "n/a", "na"):
            out["co_lead_detail"] = detail[:400]

    m = re.search(
        r'MULTI_VOICE_EVIDENCE\s*[=:]\s*\[?([^\n\]]+)',
        text,
        re.IGNORECASE,
    )
    if m:
        ev = m.group(1).strip().strip("[]")
        if ev:
            out["multi_voice_evidence"] = ev[:500]

    # Consistency: if arrangement is clearly multi-lead, nudge num voices.
    if out["voice_arrangement"] in ("duet_co_leads", "call_response") and not out["num_distinct_voices"]:
        out["num_distinct_voices"] = "2"
    if out["voice_arrangement"] == "solo_lead" and not out["num_distinct_voices"]:
        out["num_distinct_voices"] = "1"

    return out


def format_multi_voice_audit(fields, lead_profile, backing_profiles):
    """Compact multi-singer block for the private track notes."""
    if not fields:
        return ""
    num = fields.get("num_distinct_voices") or "unparsed"
    arr = fields.get("voice_arrangement") or "unparsed"
    detail = fields.get("co_lead_detail") or "none"
    evid = fields.get("multi_voice_evidence") or "not stated"
    lines = [
        "MULTI-SINGER / VOICE ARRANGEMENT AUDIT:",
        f"- NUM_DISTINCT_VOICES: {num}",
        f"- VOICE_ARRANGEMENT: {arr}",
        f"- CO_LEAD_DETAIL: {detail}",
        f"- MULTI_VOICE_EVIDENCE: {evid}",
        f"- LEAD_PROFILE tag: {lead_profile or 'unknown'}; BACKING: {backing_profiles or 'uncertain'}",
        "Guidance: doubles/octave stacks/reverb ≠ separate people. "
        "Only treat as multiple lead singers when arrangement is duet_co_leads or "
        "call_response (or NUM_DISTINCT_VOICES≥2 with clear CO_LEAD_DETAIL). "
        "lead_plus_backing means one lead plus supporting voices, not mixed leads.",
    ]
    # Soft consistency fix hint for the writer
    if lead_profile == "mixed_leads" and arr in ("solo_lead", "lead_plus_backing"):
        lines.append(
            "- Note: LEAD_PROFILE=mixed_leads conflicts with a solo/lead+backing arrangement; "
            "prefer the arrangement fields and describe one primary lead unless CO_LEAD_DETAIL "
            "clearly names two people."
        )
    if lead_profile != "mixed_leads" and arr in ("duet_co_leads", "call_response"):
        lines.append(
            "- Note: arrangement suggests distinct co-leads even though LEAD_PROFILE is not "
            "mixed_leads — mention both voices when discussing who is singing."
        )
    return "\n".join(lines)


def parse_vocal_confirmation(text):
    text = _discard_vocal_choice_lists(text)
    lead = ""
    confidence = ""

    m = re.search(r'LEAD_PROFILE\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
    if m:
        lead = _resolve_lead_tag_variant(m.group(1))

    if lead not in VOCAL_LEAD_TAGS:
        cat_m = re.search(r'LEAD_CATEGORY\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
        mod_m = re.search(r'GENDER_MODIFIER\s*[=:]\s*["\'<\[]?\s*([A-Za-z0-9_\- ]+)', text or "", re.IGNORECASE)
        if cat_m and mod_m:
            lead = _lead_from_category_modifier(cat_m.group(1), mod_m.group(1))
        elif cat_m:
            lead = _lead_from_category_modifier(cat_m.group(1), "")
        if lead not in VOCAL_LEAD_TAGS and cat_m:
            # The same hedge-spelling problem appears on LEAD_CATEGORY.
            lead = _resolve_lead_tag_variant(cat_m.group(1)) or lead

    lead = VOCAL_LEAD_ALIASES.get(lead, lead)
    if lead not in VOCAL_LEAD_TAGS:
        lead = ""

    m = re.search(r"CONFIDENCE\s*[=:]\s*(low|medium|high)", text or "", re.IGNORECASE)
    if m:
        confidence = m.group(1).lower()

    return lead, confidence


def extract_vocal_median_f0(text):
    m = re.search(r"voiced pitch median:\s*([0-9]+(?:\.[0-9]+)?)\s*Hz", text or "")
    if not m:
        return None
    try:
        return float(m.group(1))
    except Exception:
        return None


def extract_vocal_pitch_summary(text):
    median = extract_vocal_median_f0(text)
    low = None
    high = None
    note = None
    band = None

    # Prefer the "practical sung range (10-90%)" line -- build_vocal_objective_report
    # computes this specifically because it's less skewed by stray high/low
    # frames than the wider 5-95 band, and its own text says to prefer it over
    # extremes. Previously this function only ever looked for the 5-95 line,
    # so that preferred, tighter statistic never actually reached the final
    # VOCAL PITCH REPORT even though it was already being computed. Fall back
    # to the 5-95 line for robustness (e.g. older/cached report text) if the
    # practical line isn't found.
    m = re.search(
        r"practical sung range \(10-90%\):\s*([0-9]+(?:\.[0-9]+)?)-([0-9]+(?:\.[0-9]+)?)\s*Hz",
        text or "",
    )
    if m:
        band = "10-90"
    else:
        m = re.search(
            r"voiced pitch 5-95 percentile range:\s*([0-9]+(?:\.[0-9]+)?)-([0-9]+(?:\.[0-9]+)?)\s*Hz",
            text or "",
        )
        if m:
            band = "5-95"
    if m:
        try:
            low = float(m.group(1))
            high = float(m.group(2))
        except Exception:
            low = None
            high = None
            band = None

    m = re.search(r"approx median note:\s*(\S+)", text or "")
    if m:
        note = m.group(1).strip()

    return {"median": median, "low": low, "high": high, "note": note, "band": band}


def _any_marker_present(text, markers):
    """Return True if any marker phrase appears in text as a real word/phrase
    start, not merely as a run of letters buried inside an unrelated word.

    Plain substring checks (`marker in text`) let short markers false-positive
    on unrelated words that merely contain the same letters -- e.g. "thin"
    inside "within", "teen" inside "eighteen"/"sixteen"/"nineteen", or "light"
    inside "highlight"/"delight"/"flight". Anchoring on a leading word
    boundary (`\\bmarker`) fixes that while still deliberately allowing a
    marker to match as the START of a longer word (e.g. "teen" still matches
    "teenager", "bright" still matches "brighter") since several markers here
    are intentional prefixes (e.g. "post-pubert" matching "post-pubertal").
    Assumes `text` is already lowercased, matching how markers are written.
    """
    if not text:
        return False
    for marker in markers:
        if re.search(r"\b" + re.escape(marker), text):
            return True
    return False


def _marker_present_unnegated(text, markers):
    """Like _any_marker_present, but ignores markers that are negated or belong
    to an explicitly rejected alternative.

    Deliberately a SEPARATE function rather than a change to
    _any_marker_present: that helper is also used by the genre/style detection
    path, which wants plain substring/word matching and must not start skipping
    negated mentions.

    The vocal passes routinely write things like "an adult male voice, not a
    teen voice" or "the voice is not still changing". Plain keyword scanning
    reads those as adolescent evidence and inverts the conclusion.
    """
    if not text:
        return False

    negators = (
        "not", "no", "never", "nothing", "isn't", "isnt", "aren't", "arent",
        "doesn't", "doesnt", "don't", "dont", "wasn't", "wasnt", "hardly",
        "rather than", "instead of", "far from", "without", "no longer",
        "rejected", "ruled out", "unlike", "n't",
    )

    for marker in markers:
        for m in re.finditer(r"\b" + re.escape(marker), text):
            # Look back a short window for a negation cue. Stop at sentence
            # boundaries so a negation in a previous sentence doesn't leak.
            window = text[max(0, m.start() - 45):m.start()]
            window = re.split(r"[.;!?]", window)[-1]
            if any(re.search(r"\b" + re.escape(n), window) for n in negators):
                continue
            # Rejection cues can also FOLLOW the marker ("a young male reading
            # was ruled out"), so check a short forward window in the same
            # clause too.
            ahead = text[m.end():m.end() + 45]
            ahead = re.split(r"[.;!?]", ahead)[0]
            if re.search(r"\b(?:was |were |is |are )?(?:ruled out|rejected|discounted|dismissed)", ahead):
                continue
            return True
    return False


_FORMANT_NOTE_TEMPLATE_OPTIONS = "prepubertal-like/adolescent-transitional/adult-sized/ambiguous/not assessable"
_ADULT_SIZED_MARKERS = ("adult-sized", "adult sized")


def _vocal_text_without_template_labels(text):
    """A vocal pass's reply without the wording it copies from its own output
    template, for the keyword scan in _apply_vocal_age_guard.

    The PROBABILITY_ESTIMATE line repeats the template's category names
    ("adolescent male (voice changing/recently changed) Y%; female teen/adult
    A%") whatever the numbers are, and a FORMANT_NOTE copied whole lists
    "adolescent-transitional" among the options. Read as prose, those labels
    are "explicit voice-change evidence" in every reply that fills the line
    in, which demoted adult male voices to adolescent_male_likely. The
    previous listening model wrote "PROBABILITY ESTIMATE: not available", so
    this never came up; MOSS-Music always fills the line. Everything else in
    the reply is scanned as before."""
    t = str(text or "")
    t = re.sub(r"(?im)^[ \t*_-]*PROBABILITY[ _]ESTIMATE[ \t]*[:=][^\n]*$", "", t)
    return t.replace(_FORMANT_NOTE_TEMPLATE_OPTIONS, "")


def _apply_vocal_age_guard(lead_profile, analysis_text=""):
    """
    Nudge a post_puberty_male classification to adolescent_male_likely ONLY when
    the analysis text contains explicit adolescent / voice-change evidence, and
    never when there is settled adult-male evidence.

    CRITICAL: this must NOT fire on generic timbre or pitch adjectives
    ('bright', 'light', 'thin', 'high register', 'falsetto', etc.). The vocal
    prompts are explicit that pitch, brightness, thinness, and register are NOT
    age evidence. Using those words here was systematically demoting correctly
    identified adult male voices to adolescent on the strength of ordinary
    timbre description — the exact error the prompts warn against.

    'youthful' is deliberately back in the marker list below despite that
    history. It was dropped in the same pass as the pure-timbre words, but it
    isn't one: "bright"/"thin"/"light" describe acoustic PROPERTIES a mature
    voice can have too, while "youthful" is already an AGE JUDGEMENT the
    analysis chose to make (the same category as "boyish", which was kept) —
    removing it was collateral damage from fixing the timbre-word bug, not a
    deliberate tightening, and it left the gate narrow enough that the listening model's more
    natural age-descriptive language (which reads as "youthful-sounding"
    rather than the clinical "voice still changing") stopped being caught at
    all, under-firing on genuinely adolescent voices instead of over-firing on
    adult ones.
    """
    text = _vocal_text_without_template_labels(analysis_text).lower()

    # Explicit adolescent / voice-change evidence ONLY. No pure-timbre words —
    # but "youthful" and "boyish" are age judgements, not timbre properties,
    # so they stay.
    adolescent_markers = (
        "still changing", "voice changing", "voice change", "mid-change",
        "in transition", "transitional voice", "changing voice",
        "adolescent", "teen", "young male", "boyish",
        "youthful voice", "youthful-sounding voice", "youthful timbre",
        "youthful tone", "youthful male", "youthful-sounding male",
        "not yet settled", "not fully settled", "recently changed",
        "recently broken", "voice recently",
    )
    # Explicit statements that the voice has not finished changing. These are
    # direct age evidence -- the strongest this analysis can produce -- so they
    # override the settled-adult veto below rather than being cancelled by it.
    # Without this, a single incidental register word ("light tenor") was enough
    # to discard an explicit "the voice is still changing" reading.
    decisive_adolescent_markers = (
        "still changing", "voice changing", "changing voice", "voice change",
        "mid-change", "in transition", "transitional voice",
        "not yet settled", "not fully settled", "recently changed",
        "recently broken", "unbroken",
    )
    # Any settled adult-male evidence blocks a demotion.
    #
    # NOTE: this list must contain only MATURITY evidence. "tenor" and "chest
    # voice" were removed because they are tessitura/register labels, not age
    # markers -- adolescent male leads are routinely described as light tenors
    # singing in chest voice, and including them here vetoed almost every
    # correct demotion (the same pure-register error the docstring above warns
    # against, applied to the blocking side instead of the firing side).
    # "baritone" is kept: a settled baritone tessitura does imply a changed voice.
    adult_male_markers = (
        "post-pubert", "post puberty", "adult male", "male resonance",
        "male vocal weight", "baritone",
        "deepened voice", "mature male", "adult-sounding male",
        "settled adult", "full adult", "full chest", "deep chest",
        "heavy vocal weight", "settled chest", "grown", "man's voice",
        "man voice", "adult chest",
    )

    # Settled adult FEMALE evidence, so the child_female / child_gender_uncertain
    # branches below have a destination too. Previously only child_male_likely
    # was ever revisited, so an erroneous child-female read survived evidence
    # that would have overturned the male equivalent.
    adult_female_markers = (
        "adult female", "mature female", "adult woman", "grown woman",
        "woman's voice", "woman voice", "settled female", "female resonance",
        "adult-sounding female", "full female",
    )

    # Child labels: only move off 'child' when there is explicit adult
    # (or adolescent) evidence. Handled symmetrically across all three
    # child categories.
    if lead_profile in ("child_male_likely", "child_female_likely", "child_gender_uncertain"):
        has_adult_male = _marker_present_unnegated(text, adult_male_markers)
        has_adult_female = _marker_present_unnegated(text, adult_female_markers)
        has_adolescent = _marker_present_unnegated(text, adolescent_markers)

        if lead_profile == "child_male_likely" and has_adult_male:
            if has_adolescent:
                return "adolescent_male_likely"
            return "post_puberty_male"

        if lead_profile == "child_female_likely" and has_adult_female:
            return "female_teen_adult"

        if lead_profile == "child_gender_uncertain":
            # Only act when the evidence points one way; conflicting adult
            # male+female cues keep the conservative child tag.
            if has_adult_male and not has_adult_female:
                return "adolescent_male_likely" if has_adolescent else "post_puberty_male"
            if has_adult_female and not has_adult_male:
                return "female_teen_adult"

        return lead_profile

    # Adult male -> adolescent ONLY on explicit adolescent/changing evidence
    # with no settled-adult evidence present -- unless the analysis explicitly
    # states the voice is still changing, which outranks the veto.
    if lead_profile in ("post_puberty_male", "adult_male", "young_male"):
        has_adolescent = _marker_present_unnegated(text, adolescent_markers)
        # "adult-sized" is the vocal template's own FORMANT_NOTE answer for a
        # grown vocal tract, the counterpart of "adolescent-transitional"
        # (which already counts through "adolescent"), so it vetoes a
        # demotion here. Not used in the child branch above: it says nothing
        # about gender, so it cannot turn child_gender_uncertain male.
        has_settled = _marker_present_unnegated(text, adult_male_markers + _ADULT_SIZED_MARKERS)
        has_decisive = _marker_present_unnegated(text, decisive_adolescent_markers)
        if has_decisive or (has_adolescent and not has_settled):
            return "adolescent_male_likely"
    return lead_profile


def _mark_superseded_vocal_tags(raw_text, final_lead):
    """Annotate stale lead-profile tags inside a raw vocal pass before it is
    embedded verbatim in the analysis.

    The raw VOCAL / SINGER PROFILE and VOCAL CONFIRMATION PASS text is stored
    unmodified so its reasoning stays auditable, but it carries the pass's own
    structured guess (e.g. "LEAD_PROFILE=post_puberty_male"). When the guards or
    the confirmation merge later settle on a different category, that literal
    token is still sitting in the notes contradicting the settled answer, and
    the writer reads it as current -- which is how a reply hedges correctly
    ("youthful") early and then reverts to the stale tag further down.

    Values that already agree with the final decision are left untouched.
    """
    if not raw_text or not final_lead:
        return raw_text or ""

    final_norm = _normalize_vocal_tag(final_lead)
    final_norm = VOCAL_LEAD_ALIASES.get(final_norm, final_norm)
    if not final_norm or final_norm in ("", "unknown"):
        return raw_text

    def _annotate(m):
        label, value = m.group(1), m.group(2).rstrip()
        if not value:
            return m.group(0)
        if raw_text[m.end():m.end() + 16].lstrip().startswith("[SUPERSEDED"):
            return m.group(0)
        norm = _resolve_lead_tag_variant(value)
        if not norm or norm == final_norm:
            return m.group(0)
        return (
            f"{label}={value}  [SUPERSEDED — this was this pass's own provisional "
            f"guess and was overruled by later evidence. The settled category for "
            f"this track is {final_norm}. Do not use this line, and do not describe "
            f"the singer using this superseded category.]"
        )

    try:
        return re.sub(
            r"\b(LEAD_PROFILE|LEAD_CATEGORY)\s*[=:]\s*([A-Za-z0-9_\- ]+)",
            _annotate,
            raw_text,
        )
    except Exception:
        return raw_text


def _voice_type_map_lines(median_f0, low_f0=None, high_f0=None):
    """Where the measured vocal line sits, expressed as voice-type words for
    BOTH a male and a female singer, computed from pitch alone.

    Kept gender-neutral on purpose so the pitch report is identical with or
    without tags; the writer picks the column that matches the settled
    gender. Boundaries are approximate tessitura centres for a sung lead
    (median of the voiced line), not strict classical ranges.
    """
    try:
        med = float(median_f0)
    except (TypeError, ValueError):
        return []
    if med <= 0:
        return []

    # Bands are for the MEDIAN of a sung popular-music lead, which sits well
    # above classical tessitura centres. They used to put anything from 250 Hz
    # (B3) up in "high tenor / countertenor (head voice or falsetto)" and from
    # 330 Hz (E4) up in "treble / boy soprano", and to flag "unusually high for
    # an adult man" from 250 Hz -- so an ordinary male pop lead centred on C4
    # and a belting rock tenor centred on E4 were both described as falsetto.
    # Chest/mixed-voice male leads routinely centre anywhere up to ~F4.
    if med < 130:
        male = "bass range"
    elif med < 175:
        male = "baritone range"
    elif med < 280:
        male = "tenor range (the usual home of male pop/rock leads)"
    elif med < 350:
        male = "high tenor range (typical of belted rock/pop leads in chest or mixed voice)"
    elif med < 440:
        male = "very high for a man (upper-tenor belting, head voice or falsetto)"
    else:
        male = "falsetto / countertenor territory for an adult man (treble range for a boy)"

    if med < 185:
        female = "below contralto — unusually deep for a woman, tenor-like"
    elif med < 250:
        female = "contralto range (low for a woman)"
    elif med < 330:
        female = "alto / low mezzo range (typical of female pop leads in chest voice)"
    elif med < 440:
        female = "mezzo-soprano range"
    else:
        female = "soprano range"

    lines = [
        "VOICE-TYPE MAP (from measured pitch only; approximate tessitura of the sung line):",
        f"- if the singer is male (any age): {male}",
        f"- if the singer is female: {female}",
    ]
    notes = []
    if med >= 440:
        notes.append("remarkably high for an adult man (falsetto-led)")
    elif med >= 350:
        notes.append("unusually high for an adult man")
    if med < 185:
        notes.append("unusually deep for a woman")
    if med < 200:
        notes.append("deep for a boy whose voice hasn't fully broken")
    if notes:
        lines.append("- worth remarking on if it matches the settled gender/age: " + "; ".join(notes))
    try:
        if low_f0 and high_f0:
            lines.append(
                f"- practical range in notes: {_hz_to_note_name(float(low_f0))} to "
                f"{_hz_to_note_name(float(high_f0))}"
            )
    except Exception:
        pass
    return lines


_SETTLED_ADULT_MALE_CUES = (
    "adult male", "male resonance", "male vocal weight", "mature male",
    "settled adult", "full adult", "full chest", "deep chest", "man's voice",
    "adult chest", "adult-sounding male", "grown man",
)
_HIGH_ADULT_MALE_REGISTER_CUES = (
    "falsetto", "head voice", "countertenor", "high tenor", "tenore contraltino",
)


def _apply_f0_pitch_guard(lead_profile, median_f0, low_f0=None, high_f0=None,
                          analysis_text="", confirmed_adult_male=False):
    """Use objective voiced-pitch statistics as a *soft* constraint on lead tags.

    Rules of engagement:
      - Never invent child/prepubertal from high pitch alone.
      - Never force female from high pitch alone here (countertenor / falsetto-heavy
        male leads exist). Gender recovery from high f0 + cover/metadata is handled
        in singer-identity resolution when the acoustic tag is uncertain.
      - Veto confident male tags when the track-wide *median* is so high that a
        male modal centre (settled adult or adolescent) is acoustically implausible.
        Important: age-guard often demotes post_puberty_male → adolescent_male_likely
        on "high/light" prose; this guard must also demote adolescent_male_likely at
        extreme medians, otherwise female leads mislabeled male stay "adolescent male".

    median_f0 / low_f0 / high_f0 are Hz (or None if unavailable).
    """
    if lead_profile is None or lead_profile in ("", "unknown"):
        return lead_profile
    if median_f0 is None:
        return lead_profile

    try:
        med = float(median_f0)
    except (TypeError, ValueError):
        return lead_profile

    soft_cap = globals().get("F0_POST_PUBERTY_SOFT_CAP_HZ")
    hard_cap = globals().get("F0_POST_PUBERTY_HARD_CAP_HZ")
    male_any_cap = globals().get("F0_MALE_ANY_HARD_CAP_HZ")
    child_floor = globals().get("F0_CHILD_SOFT_FLOOR_HZ")

    male_like = lead_profile in (
        "post_puberty_male",
        "adult_male",
        "young_male",
        "adolescent_male_likely",
        "child_male_likely",
    )

    _txt = (analysis_text or "").lower()
    adult_high_male = (
        confirmed_adult_male
        and lead_profile in ("post_puberty_male", "adult_male", "young_male")
        and _marker_present_unnegated(_txt, _SETTLED_ADULT_MALE_CUES)
        and _marker_present_unnegated(_txt, _HIGH_ADULT_MALE_REGISTER_CUES)
    )
    if adult_high_male:
        return lead_profile

    # Extreme track-wide median: no male-tagged lead (adult or adolescent) is safe.
    if male_like and male_any_cap is not None and med >= float(male_any_cap):
        return "uncertain"

    # Settled adult male with a high median (not just top notes) is rare.
    if lead_profile in ("post_puberty_male", "adult_male", "young_male"):
        if hard_cap is not None and med >= float(hard_cap):
            return "uncertain"
        if soft_cap is not None and med >= float(soft_cap):
            return "adolescent_male_likely"

    # Child labels need more than pitch; a low-to-mid median argues against
    # keeping a child tag that was probably pitch-driven.
    if lead_profile in (
        "child_male_likely",
        "child_female_likely",
        "child_gender_uncertain",
    ):
        if child_floor is not None and med < float(child_floor):
            return "uncertain"

    return lead_profile

def _refine_multi_singer_from_f0(vocal_objective_report, min_sep=3.0, min_ratio=0.2):
    """
    Parse the vocal objective report for the 'voiced-f0 multi-peak hint' line.
    If present, return a dict with suggestions for multi-voice fields.

    `min_sep`/`min_ratio` are now parameters, not fixed constants, because this
    function is used two ways with two very different risk profiles:

    1. REFINEMENT of a classification the listening model (or the confirmation pass) has already
       called mixed_leads -- adding detail to something already established.
       Called with the original, looser defaults (3 semitones, 0.2 ratio),
       exactly as before, so nothing about that path changes.

    2. INDEPENDENT TRIGGER, upgrading a SINGLE-voice classification to
       mixed_leads on this evidence alone, when the listening model's own pass reported only
       one voice — the case a male-verse/female-chorus track hits when the listening model's
       one holistic listen just doesn't notice or report the second voice
       (a small audio-language model missing a secondary register across
       sections is a common failure, not a corner case). Overriding the listening model's own
       classification is a bigger claim than adding detail to one it has already
       made, so the caller uses a stricter bar for this case -- see
       INDEPENDENT_MULTI_SINGER_MIN_SEP_SEMITONES /
       _MIN_RATIO below, tuned toward a real male/female split (typically
       7-12+ semitones apart) rather than the vibrato or dual-register
       artefacts a single voice can produce.
    """
    # A pitch histogram is only evidence about SINGERS when it was measured on
    # a real voice: from the isolated stem, and voiced for a meaningful share
    # of the audio. Two pitch centres in vocal-stem residue (instrument bleed)
    # turned an instrumental into "mixed_leads / duet_co_leads".
    if not _vocal_report_pitch_is_voice_evidence(vocal_objective_report):
        return {}
    if not vocal_objective_report:
        return {}
    lines = vocal_objective_report.splitlines()
    multi_hint = None
    for line in lines:
        if "voiced-f0 multi-peak hint" in line:
            multi_hint = line.strip()
            break
    if not multi_hint:
        return {}
    import re
    peaks_match = re.search(r'~(\d+)\s+pitch centres?', multi_hint)
    num_peaks = int(peaks_match.group(1)) if peaks_match else 0
    if num_peaks < 2:
        return {}
    sep_match = re.search(r'~(\d+(?:\.\d+)?)\s+semitones between top two', multi_hint)
    sep = float(sep_match.group(1)) if sep_match else 0.0
    ratio_match = re.search(r'secondary/primary mass ratio ([\d.]+)', multi_hint)
    ratio = float(ratio_match.group(1)) if ratio_match else 0.0
    if sep < float(min_sep) or ratio < float(min_ratio):
        return {}
    return {
        "num_distinct_voices": "2",
        "voice_arrangement": "duet_co_leads",
        "co_lead_detail": f"two distinct pitch centres (~{sep:.1f} semitones apart) from objective f0 analysis; likely two singers or a wide dual-register single voice",
        "multi_voice_evidence": multi_hint
    }

def _confirm_child_flip_has_evidence(confirm_text):
    """
    Gate for flipping a MALE_LEAD_CATEGORIES / ADOLESCENT_MALE_CATEGORIES
    classification to a child_* category based on the confirmation pass.

    A bare CONFIDENCE=high tag from one isolated audio pass is not enough —
    that pass can hallucinate confidence just as easily as a category, and
    doing so previously let a single mistaken confirmation pass override a
    correctly-identified adult male voice with no corroborating evidence at
    all. Require the confirmation pass's own analysis text to actually state
    a prepubertal-type acoustic marker before the flip is accepted.
    """
    text = (confirm_text or "").lower()
    child_evidence_markers = (
        "prepubert",
        "pre-pubert",
        "child-like vocal tract",
        "childlike vocal tract",
        "child vocal tract",
        "child-like resonance",
        "childlike resonance",
        "child vocal weight",
        "small vocal tract",
        "unbroken voice",
        "boy soprano",
        "boy treble",
        "child resonance",
    )
    return any(marker in text for marker in child_evidence_markers)


# dev43: single singers called "two co-leads ... about an octave apart". The
# pitch histogram upgrade (below) is meant to run only when neither listening
# pass said how many singers there are, but the vocal pass writes that in
# forms the field parser does not read ("NUM_DISTINCT VOICES: 1", "VOICE
# ARRANGEMENT: solo lead", "single lead voice with occasional backing
# harmonies"), so the upgrade ran on single-singer tracks; and two centres an
# octave apart are what octave doubling, or the pitch tracker jumping an
# octave on one voice, produce.
_SINGLE_VOICE_RES = (
    r"NUM[_ ]DISTINCT[_ ]VOICES\s*[=:]\s*[\"'<\[]?\s*(?:1|one)\b",
    r"VOICE[_ ]ARRANGEMENT\s*[=:]\s*[\"'<\[]?\s*(?:solo[_ ]lead|lead[_ ]plus[_ ]backing|single[_ ]lead)\b",
    r"MULTI[_ \-]VOICE[_ ]EVIDENCE\s*[=:]\s*[\"'<\[]?\s*single lead",
    r"\bsingle lead (?:voice|vocal|vocalist|singer)\b",
    r"\bsingle (?:vocalist|singer)\b",
    r"\bone lead (?:vocalist|singer)\b",
)
F0_OCTAVE_BAND_SEMITONES = (11.0, 13.0)


def _vocal_pass_says_single(text):
    """True when a listening pass's own text reports one singer, in any of the
    spellings it uses."""
    t = _strip_md_emphasis(str(text or ""))
    return any(re.search(p, t, re.IGNORECASE) for p in _SINGLE_VOICE_RES)


def _f0_hint_separation(report):
    m = re.search(r"voiced-f0 multi-peak hint:[^\n]*?~(\d+(?:\.\d+)?)\s+semitones between top two",
                  str(report or ""))
    return float(m.group(1)) if m else None


def _f0_sep_is_octave(sep):
    lo, hi = F0_OCTAVE_BAND_SEMITONES
    return sep is not None and lo <= sep <= hi


def _apply_independent_f0_multi_singer(final_lead, initial_lead, vocal_objective_report,
                                       multi_voice_fields, vocal_text=None):
    """Consult the objective f0 histogram when the listening model reported a single voice.

    The two analysis paths used to disagree: the batch path upgraded to
    mixed_leads on the histogram alone, while the interactive path kept it as
    evidence but still wrote "[Upgraded from a single-voice listening-model
    classification...]" into the notes -- telling the writer a duet had been
    confirmed when it had not.

    Rule now used by both: upgrade only when neither vocal pass explicitly
    reported a single singer. When a pass did say one voice, the histogram is
    recorded honestly as supporting evidence (one singer's chest/head
    registers, octave doubling and harmonies all produce two pitch centres).
    """
    if not (ENABLE_INDEPENDENT_F0_MULTI_SINGER_TRIGGER and vocal_objective_report):
        return final_lead
    if (final_lead or initial_lead) in ("mixed_leads", ""):
        return final_lead
    try:
        f0_independent = _refine_multi_singer_from_f0(
            vocal_objective_report,
            min_sep=INDEPENDENT_MULTI_SINGER_MIN_SEP_SEMITONES,
            min_ratio=INDEPENDENT_MULTI_SINGER_MIN_RATIO,
        )
    except Exception:
        f0_independent = {}
    if f0_independent.get("num_distinct_voices") not in ("2", "3+"):
        return final_lead

    if VOCAL_F0_UPGRADE_GUARDS and _f0_sep_is_octave(_f0_hint_separation(vocal_objective_report)):
        multi_voice_fields["multi_voice_evidence"] = (
            (multi_voice_fields.get("multi_voice_evidence") or "")
            + " [Objective f0 histogram shows two centres about an octave apart. NOT upgraded: "
            "that is the signature of octave doubling or of the pitch tracker jumping an octave "
            "on one voice, not of two singers.]"
        ).strip()
        return final_lead
    said_single = (
        multi_voice_fields.get("num_distinct_voices") == "1"
        or multi_voice_fields.get("voice_arrangement") in ("solo_lead", "lead_plus_backing")
        or (VOCAL_F0_UPGRADE_GUARDS and _vocal_pass_says_single(vocal_text))
    )
    prior_evidence = multi_voice_fields.get("multi_voice_evidence") or ""
    if said_single:
        multi_voice_fields["multi_voice_evidence"] = (
            prior_evidence
            + " [Objective f0 histogram shows two well-separated pitch centres, but the "
            "listening passes reported a single lead. NOT upgraded: this pattern is also "
            "produced by one singer moving between registers, octave doubling or "
            "harmonies. Mention a second voice only if other evidence supports it.]"
        ).strip()
        return final_lead

    for k, v in f0_independent.items():
        if v:
            multi_voice_fields[k] = v
    multi_voice_fields["multi_voice_evidence"] = (
        prior_evidence
        + " [Upgraded to mixed leads on independent objective f0 evidence: the listening "
        "passes did not specify the number of voices, and the measured pitch histogram "
        "shows two well-separated, substantial centres consistent with two singers.]"
    ).strip()
    return "mixed_leads"


_SECTION_VOICE_HEAD = "SECTION VOICE CHECK"


def _adult_lead_gender(tag):
    t = str(tag or "")
    if t == "female_teen_adult":
        return "female"
    if t in ("post_puberty_male", "adult_male"):
        return "male"
    return None


def _section_voice_gate(final_lead, initial_lead, confirm_lead, vocal_objective_report):
    """The lead's gender when the section voice check should look further,
    else None: a settled adult lead both vocal passes agree on, and two
    pitch centres 4+ semitones apart that are not an octave."""
    if not SECTION_VOICE_CHECK:
        return None
    g = _adult_lead_gender(final_lead)
    if not g:
        return None
    for other in (initial_lead, confirm_lead):
        if other and other not in ("unknown", "unparsed") and _adult_lead_gender(other) != g:
            return None
    sep = _f0_hint_separation(vocal_objective_report)
    if sep is None or sep < SECTION_VOICE_MIN_SHIFT_ST or _f0_sep_is_octave(sep):
        return None
    return g


def _register_regions(times, midi, duration, gender, win=8.0, hop=4.0):
    """(lead median, [(start, end, median)], control (start, end) or None)
    from voiced pitch frames: stretches of SECTION_VOICE_MIN_REGION_S+ whose
    8-second windows sit SECTION_VOICE_MIN_SHIFT_ST+ below a female lead (at
    or below E4) or above a male lead (at or above C4)."""
    t = np.asarray(times, dtype=float)
    m = np.asarray(midi, dtype=float)
    if m.size < 200 or not duration:
        return None
    lead = float(np.median(m))
    fps = m.size / max(1e-9, float(duration))
    rows = []
    s0 = 0.0
    while s0 + win <= duration + 0.01:
        sel = (t >= s0) & (t < s0 + win)
        if int(sel.sum()) >= 0.15 * win * max(fps, 1.0):
            rows.append((s0, float(np.median(m[sel])), int(sel.sum())))
        s0 += hop

    def odd(med):
        if gender == "female":
            return med <= lead - SECTION_VOICE_MIN_SHIFT_ST and med <= 64.0     # E4
        return med >= lead + SECTION_VOICE_MIN_SHIFT_ST and med >= 60.0         # C4
    regs, cur = [], None
    for s_, med, _n in rows:
        if odd(med):
            if cur and s_ <= cur[1]:
                cur[1] = s_ + win
                cur[2].append(med)
            else:
                if cur:
                    regs.append(cur)
                cur = [s_, s_ + win, [med]]
        elif cur:
            regs.append(cur)
            cur = None
    if cur:
        regs.append(cur)
    regs = [(a, b, float(np.median(ms))) for a, b, ms in regs if b - a >= SECTION_VOICE_MIN_REGION_S]
    typical = [(n, s_) for s_, med, n in rows if abs(med - lead) <= 2.0
               and not any(a - win < s_ < b for a, b, _m in regs)]
    control = None
    if typical:
        _n, cs = max(typical)
        control = (cs, cs + win)
    return lead, regs, control


def _section_voice_clip_answer(reply):
    """{"lead", "conf", "g"} from the standard singer-confirmation answer for
    one clip; g is the voice's gender (boys and children count as male), or
    None for an uncertain, mixed or unparsed answer."""
    lead, conf = parse_vocal_confirmation(reply or "")
    g = _lead_gender(lead) if lead and lead not in ("mixed_leads", "uncertain", "unknown") else None
    return {"lead": lead or "", "conf": (conf or "").lower(), "g": g}


def _section_voice_decide(gender, regions, answers, control=None):
    """True when the clip answers show a second lead of the other gender:
    the main-lead clip heard as the lead's gender (medium or high
    confidence), and 2+ stretches heard as the other gender (and at least
    half of those asked), or a single stretch of
    SECTION_VOICE_SINGLE_REGION_MIN_S+ heard so with high confidence."""
    other = "male" if gender == "female" else "female"
    if not control or control.get("g") != gender or control.get("conf") not in ("medium", "high"):
        return False
    # A high male voice (falsetto, a boy-band tenor) is the likelier thing to
    # be heard as a woman, so a female stretch in a male-led track needs high
    # confidence; a male stretch in a female-led one needs medium or high.
    confs = ("medium", "high") if gender == "female" else ("high",)
    ok = [a.get("g") == other and a.get("conf") in confs for a in answers]
    n_ok = sum(ok)
    if n_ok >= 2 and n_ok * 2 >= len(answers):
        return True
    if (len(answers) == 1 and n_ok == 1 and answers[0].get("conf") == "high" and regions
            and regions[0][1] - regions[0][0] >= SECTION_VOICE_SINGLE_REGION_MIN_S):
        return True
    return False


def _mmss(x):
    return f"{int(x // 60)}:{int(x % 60):02d}"


def _section_voice_check_legacy(moss_model, moss_processor, vocal_stem_path, final_lead, initial_lead,
                         confirm_lead, vocal_objective_report, mix_path=None):
    """See SECTION_VOICE_CHECK. Returns None when it did not run, else a dict
    with "mixed" (bool) and, when mixed, "detail", "evidence" and "block".
    Never raises."""
    try:
        gender = _section_voice_gate(final_lead, initial_lead, confirm_lead, vocal_objective_report)
        if not gender or moss_model is None or not vocal_stem_path or not os.path.exists(str(vocal_stem_path)):
            return None
        status("Section voice check: looking for a second lead voice of the other gender...")
        sr = 8000
        y, _ = librosa.load(str(vocal_stem_path), sr=sr, mono=True)
        duration = len(y) / float(sr)
        f0, _vflag, vprob = librosa.pyin(y, fmin=65.0, fmax=1000.0, sr=sr, frame_length=1024, hop_length=256)
        times = librosa.times_like(f0, sr=sr, hop_length=256)
        ok = np.isfinite(f0) & (np.nan_to_num(vprob) > 0.65)
        if int(ok.sum()) < 200:
            status_done("Section voice check: not enough voiced audio")
            return {"mixed": False, "summary": "inconclusive -- not enough voiced audio to check for another lead"}
        midi = 69.0 + 12.0 * np.log2(f0[ok] / 440.0)
        rr = _register_regions(times[ok], midi, duration, gender)
        if not rr:
            status_done("Section voice check: not enough voiced audio")
            return {"mixed": False, "summary": "inconclusive -- not enough voiced audio to check for another lead"}
        lead_m, regions, control = rr
        enough = len(regions) >= 2 or (regions and regions[0][1] - regions[0][0] >= SECTION_VOICE_SINGLE_REGION_MIN_S)
        if not enough or not control:
            status_done("Section voice check: no qualifying separate-register stretch; another lead not confirmed")
            return {"mixed": False, "summary": "inconclusive -- no qualifying separate-register stretch; another lead not confirmed"}
        asked = sorted(regions, key=lambda r: (-(r[1] - r[0]), r[0]))[:SECTION_VOICE_MAX_REGIONS]
        asked.sort(key=lambda r: r[0])
        # Clips of the full mix (what the listening model is used to hearing;
        # on an isolated vocal stem it answered "unclear" to everything), each
        # asked the scan's own singer-confirmation question on its own.
        src = mix_path if (mix_path and os.path.exists(str(mix_path))) else vocal_stem_path
        y16, sr16 = librosa.load(str(src), sr=16000, mono=True)

        def ask(a, b):
            mid = 0.5 * (a + b)
            half = min(SECTION_VOICE_CLIP_S, b - a) / 2.0
            st_ = max(0, int((mid - half) * sr16))
            audio = y16[st_:int((mid + half) * sr16)]
            tmp = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
            tmp.close()
            try:
                import soundfile as _sf
                _sf.write(tmp.name, audio, sr16)
                reply = moss_generate(moss_model, moss_processor, [{
                    "role": "user",
                    "content": [{"type": "text", "text": VOCAL_CONFIRMATION_PROMPT},
                                {"type": "audio", "path": tmp.name}],
                }], max_new_tokens=256) or ""
            finally:
                try:
                    os.remove(tmp.name)
                except OSError:
                    pass
            return _section_voice_clip_answer(reply)
        c0, c1 = control
        ctrl_ans = ask(max(0.0, c0 - 2.0), min(duration, c1 + 2.0))
        answers = [ask(a, b) for a, b, _m in asked]
        mixed = _section_voice_decide(gender, asked, answers, ctrl_ans)
        if not mixed:
            _ans_s = ("main " + f"{_mmss(c0)}-{_mmss(c1)}: {ctrl_ans.get('lead') or '?'} "
                      f"({ctrl_ans.get('conf') or '?'}); " + "; ".join(
                          f"{_mmss(a)}-{_mmss(b)}: {x.get('lead') or '?'} ({x.get('conf') or '?'})"
                          for (a, b, _m), x in zip(asked, answers)))
            status_done("Section voice check: another lead not confirmed (" + _ans_s + ")")
            return {"mixed": False, "summary": "inconclusive -- another lead not confirmed (" + _ans_s + ")"}
        other = "male" if gender == "female" else "female"
        conf_spans = [(a, b) for (a, b, _m), x in zip(asked, answers) if x.get("g") == other]
        all_spans = [(a, b) for a, b, _m in regions]
        spans_s = ", ".join(f"{_mmss(a)}-{_mmss(b)}" for a, b in conf_spans)
        more = [f"{_mmss(a)}-{_mmss(b)}" for a, b in all_spans if (a, b) not in conf_spans]
        detail = (f"a {other} lead in {spans_s}" + (f" (and likely {', '.join(more)})" if more else "")
                  + f"; a {gender} lead elsewhere")
        evidence = (f"Section voice check: asked about each stretch on its own, the listening model heard a "
                    f"{other} singer in {spans_s} and a {gender} one in the main lead at "
                    f"{_mmss(control[0])}-{_mmss(control[1])}.")
        block = (
            f"\n\n{_SECTION_VOICE_HEAD} (measured on the separated vocal track, then heard by the listening "
            "model; read with the vocal blocks above):\n"
            f"- The lead is {gender} for most of the track, but the voice sits "
            f"{SECTION_VOICE_MIN_SHIFT_ST:g}+ semitones {'lower' if gender == 'female' else 'higher'} in "
            + ", ".join(f"{_mmss(a)}-{_mmss(b)}" for a, b in all_spans) + ".\n"
            f"- Asked about each stretch on its own, the listening model heard a {other} singer in "
            f"{spans_s}, and a {gender} singer in the main lead ({_mmss(control[0])}-{_mmss(control[1])}).\n"
            f"- FINAL LEAD PROFILE is therefore mixed_leads: a {gender} lead and a {other} lead who takes "
            "those stretches. When asked who sings, describe both voices and where each one leads; the "
            "whole-track vocal passes above heard only the main voice. Pitch alone did not decide this."
        )
        status_done(f"Section voice check: a {other} lead in {spans_s} -> mixed leads")
        return {"mixed": True, "detail": detail, "evidence": evidence, "block": block,
                "summary": f"checked -- a {other} lead in {spans_s} (see SECTION VOICE CHECK)"}
    except Exception as e:
        print(f"  (section voice check skipped: {e})")
        return None


def _section_voice_conflict(final_lead, initial_lead, confirm_lead):
    """Only opposing recognised voice genders trigger recovery, never age alone.
    A contradiction is a reason to listen again, not proof of two people.
    """
    if not SECTION_VOICE_CHECK or not SECTION_VOICE_CONFLICT_RECOVERY:
        return False
    if final_lead == "mixed_leads":
        return False
    genders = {_lead_gender(t) for t in (initial_lead, confirm_lead)
               if t and t not in ("unknown", "unparsed", "uncertain", "mixed_leads")}
    return "male" in genders and "female" in genders


def _section_voice_coverage_windows(duration, section_hints=None):
    """Bounded disjoint listening windows, with no pitch/voicing prerequisite.
    Start inside measured sections where possible; fill gaps across the timeline.
    Section labels are never used, and each clip must independently prove a lead.
    """
    import math
    limit = max(0, int(SECTION_VOICE_RECOVERY_MAX_CLIPS))
    width = float(SECTION_VOICE_RECOVERY_CLIP_S)
    if not math.isfinite(duration) or not math.isfinite(width) or duration < 6 or width < 6 or not limit:
        return []
    candidates = []
    for section in section_hints or []:
        try:
            a, b = float(section["start"]), float(section["end"])
        except (KeyError, TypeError, ValueError):
            continue
        if not math.isfinite(a) or not math.isfinite(b):
            continue
        a, b = max(0.0, a), min(duration, b)
        if b - a >= 6:
            span = min(width, b - a)
            mid = (a + b) / 2
            candidates.append((mid - span / 2, mid + span / 2, 0.0))
    candidates.sort()
    # Spread a capped selection over the whole song, rather than keeping only
    # the first sections. Tiny/invalid/overlapping sections cannot add votes.
    if len(candidates) > limit:
        indices = ([len(candidates) // 2] if limit == 1 else
                   [round(i * (len(candidates) - 1) / (limit - 1)) for i in range(limit)])
        candidates = [candidates[i] for i in indices]
    chosen = []
    def add(a, b):
        if len(chosen) < limit and b - a >= 6 and not any(a < z and b > x for x, z, _ in chosen):
            chosen.append((a, b, 0.0))
    for a, b, _ in candidates:
        add(a, b)
    # No section map is required. Grid centres also cover unrepresented parts
    # of long sections; failed pitch tracking can never suppress this fallback.
    for i in range(limit):
        span = min(width, duration)
        mid = (i + .5) * duration / limit
        a = max(0.0, min(duration - span, mid - span / 2))
        add(a, a + span)
    return sorted(chosen)


def _section_voice_gap_windows(duration, regions, answers):
    """Sample unused audio, prioritising neighbours of a rare confident lead.
    Never overlap an existing vote or use section names, artist or pitch as evidence.
    """
    import math
    limit = max(0, int(SECTION_VOICE_RECOVERY_GAP_CLIPS))
    if not limit or not math.isfinite(duration) or duration < 6:
        return []
    counts = {"male": 0, "female": 0}
    anchors = []
    for (a, b, _), x in zip(regions, answers):
        g = x.get("g")
        if (g in counts and x.get("present") and x.get("conf") == "high"
                and not x.get("conflict")
                and x.get("arrangement") in ("solo_lead", "lead_plus_backing")):
            counts[g] += 1
            anchors.append((a, b, g))
    # This is not a search for a second singer on otherwise consistent tracks.
    if not all(counts.values()) or min(counts.values()) >= 2:
        return []
    rare = [(a, b) for a, b, g in anchors if counts[g] < 2]
    occupied = sorted((max(0., a), min(duration, b)) for a, b, _ in regions)
    gaps, end = [], 0.
    for a, b in occupied:
        if a - end >= 6:
            gaps.append((end, a))
        end = max(end, b)
    if duration - end >= 6:
        gaps.append((end, duration))
    candidates = []
    for a, b in gaps:
        # Tile a gap with nonoverlapping clips, including its far end.
        count = int((b - a) // 6)
        for i in range(count):
            start = a if count == 1 else a + i * (b - a - 6) / (count - 1)
            candidates.append((start, start + 6, 0.))
    def distance(window):
        a, b, _ = window
        return min(max(x - b, a - z, 0.) for x, z in rare), a
    return sorted(sorted(candidates, key=distance)[:limit])


def _section_voice_recovery_answer(reply):
    text = _strip_md_emphasis(reply)
    fields = {}
    allowed = {"VOCALS_PRESENT": {"yes", "no", "uncertain"},
               "LEAD_GENDER": {"male", "female", "mixed", "uncertain"},
               "VOICE_ARRANGEMENT": {"solo_lead", "lead_plus_backing", "duet_co_leads", "group_unison", "uncertain"},
               "CONFIDENCE": {"high", "medium", "low"}}
    for key, values in allowed.items():
        found = re.findall(r"(?mi)^\s*" + key + r"\s*[=:]\s*([^\n]*)", text)
        value = found[0].strip().lower() if len(found) == 1 else ""
        fields[key] = value if value in values else "uncertain"
    g = fields["LEAD_GENDER"]
    present = fields["VOCALS_PRESENT"] == "yes"
    return {"g": g if present and g in ("male", "female") else None,
            "lead": g if present else "no clear foreground lead",
            "conf": fields["CONFIDENCE"], "present": present,
            "conflict": g == "mixed", "arrangement": fields["VOICE_ARRANGEMENT"]}


def _section_voice_recovery_groups(regions, answers):
    """Repeated high-confidence opposite classifications, in disjoint clips.
    Empty/low-confidence, contradictory, mixed and backing-only answers do not vote.
    """
    groups = {"male": [], "female": []}
    if len(regions) != len(answers):
        return {}
    used = []
    for (a, b, _m), answer in zip(regions, answers):
        g = answer.get("g")
        if (g not in groups or not answer.get("present") or answer.get("conf") != "high" or answer.get("conflict")
                or answer.get("arrangement") not in ("solo_lead", "lead_plus_backing")
                or b - a < 6 or any(a < z and b > x for x, z in used)):
            continue
        groups[g].append((float(a), float(b)))
        used.append((a, b))
    return groups if all(len(groups[g]) >= 2 for g in groups) else {}


def _section_voice_pair_confirmed(reply):
    # Require an exact field, a stated lead change (not backing/harmony), and
    # high confidence. Never accept a phrase merely containing "different".
    fields = {}
    for key in ("LEAD_CHANGE", "CONFIDENCE"):
        values = re.findall(r"(?mi)^\s*" + key + r"\s*[=:]\s*([a-z_]+)\s*$", _strip_md_emphasis(reply))
        if len(values) != 1:
            return False
        fields[key] = values[0].lower()
    return fields == {"LEAD_CHANGE": "different_lead", "CONFIDENCE": "high"}


def _instrumental_presence_answer(reply):
    """Only exact, unique, confident absence is an instrumental vote."""
    text = _strip_md_emphasis(str(reply or ""))
    fields = {}
    for key in ("HUMAN_VOICE", "CONFIDENCE"):
        values = re.findall(r"(?mi)^\s*" + key + r"\s*[=:]\s*([^\n]*)", text)
        if len(values) != 1:
            return False
        fields[key] = values[0].strip().lower()
    return fields == {"HUMAN_VOICE": "no", "CONFIDENCE": "high"}


def _instrumental_full_coverage(mix, rate, ask, diagnostic=None):
    """Full coverage, with one shorter-window retry for ambiguous answers.
    A positive voice answer vetoes absence. All negative votes remain high-confidence.
    """
    import math
    log = diagnostic if diagnostic is not None else {}
    log.update(outcome="unresolved", detail="verification unavailable")
    if not INSTRUMENTAL_FULL_COVERAGE_CHECK or rate <= 0 or len(mix) < rate * 6:
        return None
    duration = len(mix) / float(rate)
    count = max(1, int(math.ceil(max(0., duration - 20.) / 19.)) + 1)
    limit = max(0, int(INSTRUMENTAL_PRESENCE_MAX_CLIPS))
    if count > limit:
        log["detail"] = "full coverage exceeds configured call limit"
        return None
    calls = 0
    def check(a, b):
        nonlocal calls
        audio = mix[int(a * rate):min(len(mix), int(b * rate))]
        if not len(audio) or not np.isfinite(audio).all():
            return "uncertain"
        if float(np.max(np.abs(audio))) < 1e-5:
            return "no"  # Only digital/near silence; not low vocal-stem energy.
        if calls >= limit:
            log["detail"] = "verification call limit reached"
            return "uncertain"
        calls += 1
        reply = ask(audio, VOCAL_PRESENCE_VERIFY_PROMPT)
        log.update(detail=f"{_mmss(a)}-{_mmss(b)}: " + " ".join(str(reply).split())[:240],
                   calls=calls)
        if _instrumental_presence_answer(reply):
            return "no"
        values = re.findall(r"(?mi)^\s*HUMAN_VOICE\s*[=:]\s*([^\n]*)",
                            _strip_md_emphasis(str(reply or "")))
        # Even a low-confidence explicit yes blocks an absence verdict.
        if len(values) == 1 and values[0].strip().lower() == "yes":
            confidence = re.findall(r"(?mi)^\s*CONFIDENCE\s*[=:]\s*([^\n]*)",
                                    _strip_md_emphasis(str(reply or "")))
            log["positive_confidence"] = confidence[0].strip().lower() if len(confidence) == 1 else ""
            return "yes"
        return "uncertain"
    def covered(a, b, depth=0):
        verdict = check(a, b)
        if verdict == "yes":
            log["outcome"] = "voice_detected"
            # A positive vote still vetoes absence. Require a second, explicit
            # human-articulation check before it can unlock singer identification.
            if calls < limit and log.get("positive_confidence") == "high":
                corroboration = ask(mix[int(a * rate):min(len(mix), int(b * rate))],
                    "Listen only to this audio clip. Distinguish a real human voice from guitar, synth, "
                    "feedback, percussion and separation artefacts. Speaking, chanting, rapping and "
                    "wordless singing count; pitch or a voice-like tone alone does not. Do not infer "
                    "a singer from the song or artist. Return exactly three fields on separate lines: "
                    "HUMAN_VOICE=yes|no|uncertain; CONFIDENCE=high|medium|low; "
                    "HUMAN_CUES=speech|singing|chanting|rapping|wordless_singing|none|uncertain. "
                    "Choose one value per field; use uncertain if human articulation is not clear.")
                log["calls"] = calls + 1
                fields = {}
                for key in ("HUMAN_VOICE", "CONFIDENCE", "HUMAN_CUES"):
                    vals = re.findall(r"(?mi)^\s*" + key + r"\s*[=:]\s*([^\n]*)",
                                      _strip_md_emphasis(str(corroboration or "")))
                    fields[key] = vals[0].strip().lower() if len(vals) == 1 else ""
                if (fields["HUMAN_VOICE"] == "yes" and fields["CONFIDENCE"] == "high"
                        and fields["HUMAN_CUES"] in ("speech", "singing", "chanting", "rapping", "wordless_singing")):
                    log["outcome"] = "voice_confirmed"
                log["detail"] += "; corroboration: " + " ".join(str(corroboration or "").split())[:240]
            return False
        if verdict == "no":
            return True
        # A second subdivision covers ambiguous half-windows without lowering
        # confidence or interpreting explanatory prose as a negative vote.
        if (depth >= (2 if INSTRUMENTAL_EXTRA_PRESENCE_RETRY else 1)
                or b - a < (8 if INSTRUMENTAL_EXTRA_PRESENCE_RETRY else 12)
                or calls + 2 > limit):
            return False
        mid = (a + b) / 2.
        return covered(a, mid + .5, depth + 1) and covered(mid - .5, b, depth + 1)
    for index in range(count):
        a, b = index * 19., min(duration, index * 19. + 20.)
        if not covered(a, b):
            return None
    log.update(outcome="instrumental", calls=calls)
    return {"instrumental": True, "reasons": [
        f"a dedicated human-voice presence check found no human voice with high confidence "
        f"throughout the full {duration:.1f}-second mix (silent windows excluded directly)"],
        "presence_coverage_seconds": duration, "presence_windows": count}


def _identity_pitch_median(median, report, initial, confirmed, confidence):
    """A rejected tracker reading cannot veto two agreeing adult-male passes.
    Keep the raw measurement for reporting and all section-voice checks.
    """
    if (initial == confirmed == "post_puberty_male" and confidence == "high"
            and _pyin_reading_confidence_note(report)):
        return None
    return median


def _audio_only_singer_identity(audit):
    """Record the accepted acoustic category without inventing a named person."""
    t = str(audit or "")
    if ("VOCAL PRESENCE VERIFICATION: UNRESOLVED" in t
            or "No clear vocals detected." in t):
        return ""
    m = re.search(r"(?mi)^-?\s*FINAL LEAD PROFILE:\s*([a-z_]+)\s*$", t)
    if not m or m.group(1) not in ("post_puberty_male", "female_teen_adult", "mixed_leads",
                                  "adolescent_male_likely", "child_male_likely", "child_female_likely"):
        return ""
    tag = m.group(1)
    count = "several" if tag == "mixed_leads" else "uncertain"
    return (f"SINGER_IDENTITY={tag}\n"
            "REASONING=Accepted audio vocal profile; no artist metadata or cover evidence is available. "
            "This describes the audible voice category, not a named performer or documented singer count.\n"
            "CONFIDENCE=medium\n"
            f"LEAD_SINGERS={count}\nIDENTITY_SOURCE=audio_only")


def _uncorroborated_presence_report(text):
    """Reject a lone presence vote contradicted by its targeted corroboration."""
    t = str(text or "")
    check = re.search(r"Section voice check[^\n]*inconclusive -- no reliable sampled lead voices[^\n]*", t)
    if not check or "presence verification voice_detected:" not in check.group(0):
        return False
    line = check.group(0)
    # v13 recorded the corroboration reply. An uncertain/negative reply does
    # not become positive evidence just because the whole-track pass said yes.
    failed = re.search(r"corroboration:\s*HUMAN_VOICE=(?:uncertain|no)\b", line)
    old_uncertain = (re.search(r"(?mi)^- FINAL LEAD PROFILE:\s*(?:unknown|unparsed|uncertain)\s*$", t)
        and re.search(r"VOCAL / SINGER PROFILE[^\n]*\nVOCALS_PRESENT=uncertain\b", t))
    return bool(failed or old_uncertain)


def _repair_confirmed_vocal_description(text):
    t = str(text or "")
    if ("VOCAL PRESENCE VERIFICATION: UNRESOLVED" in t
            or "VOCALS_PRESENT=no  # from vocal-presence arbitration" in t):
        return text
    settled = re.search(r"(?mi)^- FINAL LEAD PROFILE:\s*(post_puberty_male|female_teen_adult|adolescent_male|child_male|child_female|mixed_leads)\b", t)
    if not settled:
        return text
    profile = re.search(r"VOCAL / SINGER PROFILE[^\n]*\n([\s\S]*?)(?:\n\nVOCAL DECISION AUDIT|\Z)", t)
    if not profile or not re.search(r"(?mi)^VOCALS_PRESENT\s*[=:]\s*yes\s*$", profile.group(1)):
        return text
    denial = (r"(?i)\bno\s+(?:(?:discernible|clear|audible|human|identifiable|obvious)\s+){0,3}"
              r"(?:vocals?|voices?|singing|speech)\b|\bwithout\s+(?:any\s+)?(?:vocals?|voices?|singing)\b"
              r"|\b(?:purely|entirely|wholly)\s+instrumental\b")
    def clean(m):
        kept = [x for x in re.split(r"(?<=[.!?])\s+", m.group(1)) if not re.search(denial, x)]
        return "DESCRIPTION=" + (" ".join(kept).strip() or "Human vocals are present; see the dedicated vocal profile.")
    return re.sub(r"(?m)^DESCRIPTION=([^\n]*)", clean, t)


def _normalize_unresolved_vocal_report(text):
    """Do not publish positive vocal fields when verification remains open."""
    t = str(_repair_confirmed_vocal_description(text) or "")
    if _uncorroborated_presence_report(t) and "VOCAL PRESENCE VERIFICATION: UNRESOLVED" not in t:
        t += "\n\nVOCAL PRESENCE VERIFICATION: UNRESOLVED. An isolated positive presence vote was not corroborated; artist membership is not evidence of a singer on this recording."
    # Repair older saved reports whose sole positive override was stem notes.
    if ("VOCAL PRESENCE SALVAGE (from vocal-stem transcription)" in t
            and re.search(r"(?mi)^- FINAL LEAD PROFILE:\s*(?:unknown|unparsed|uncertain)\s*$", t)):
        t = re.sub(r"(?m)^VOCAL PRESENCE SALVAGE \(from vocal-stem transcription\)[^\n]*(?:\nVOCALS_PRESENT=[^\n]*)?", "", t)
        if "VOCAL PRESENCE VERIFICATION: UNRESOLVED" not in t:
            t += "\n\nVOCAL PRESENCE VERIFICATION: UNRESOLVED. Stem-note onset alone did not establish a human voice; earlier singer claims are unverified."
    if "VOCAL PRESENCE VERIFICATION: UNRESOLVED" not in t:
        return t
    # Previously generated lyrics or identity assertions cannot survive a
    # failed presence decision when an older report is loaded or exported.
    t = re.sub(r"(?ms)^LYRICS HEARD IN AUDIO[^\n]*\n.*?\[END OF TRANSCRIPTION\]\s*", "", t)
    t = re.sub(r"(?ms)^SINGER IDENTITY RESOLUTION[^\n]*\n.*?(?=\n\n[A-Z][A-Z /()_-]{5,}|\Z)", "", t)
    t = re.sub(r"(?mi)^(VOCALS_PRESENT\s*[=:]\s*)yes\b", r"\1uncertain", t)
    t = re.sub(r"(?mi)^LEAD_VOCAL_CHARACTERISTICS=.*$",
               "LEAD_VOCAL_CHARACTERISTICS=unverified; human vocal presence is unresolved", t)
    t = re.sub(r"(?mi)^MELODIC_RANGE=.*$",
               "MELODIC_RANGE=not established as a vocal range; vocal presence is unresolved", t)
    t = re.sub(r"(?mi)^EARLIEST VOCAL ONSET:.*$",
               "UNVERIFIED STEM ONSET: notes in a separated stem do not establish a human voice or vocal entrance.", t)
    # Remove unsupported vocal claims only from the user-facing description;
    # retain the listening pass and verification diagnostics elsewhere.
    def description(m):
        sentences = re.split(r"(?<=[.!?])\s+", m.group(1))
        kept = [x for x in sentences if not re.search(r"(?i)\b(?:vocal(?:s|ist|ists)?|sing(?:er|ers|ing)?|lyrics?|voice|voices)\b", x)]
        return "DESCRIPTION=" + (" ".join(kept).strip() or "Vocal presence is unresolved.")
    t = re.sub(r"(?m)^DESCRIPTION=([^\n]*)", description, t)
    # Keep the precedence notice independent of DESCRIPTION, whose text is
    # rearranged by the report formatter.
    notice = ("VOCAL PRESENCE VERIFICATION: UNRESOLVED. Human vocal presence was not established; "
              "do not assert a singer, vocal range, vocal onset or reliable audio-transcribed lyrics. "
              "Earlier listening impressions and stem notes are unverified. This is not an instrumental verdict.")
    if notice not in t:
        t += "\n\n" + notice
    return t


def _section_voice_subdivide_minority(regions, answers, clip, ask):
    """Recheck one rare lead as two disjoint clips; never count its parent too.
    This validates a brief appearance without demanding two separate verses.
    """
    eligible = {"male": [], "female": []}
    for i, ((a, b, _), x) in enumerate(zip(regions, answers)):
        if (x.get("g") in eligible and x.get("present") and x.get("conf") == "high"
                and not x.get("conflict")
                and x.get("arrangement") in ("solo_lead", "lead_plus_backing")):
            eligible[x["g"]].append(i)
    rare = [g for g in eligible if len(eligible[g]) == 1
            and len(eligible["female" if g == "male" else "male"]) >= 2]
    if len(rare) != 1:
        return regions, answers, ""
    g = rare[0]
    index = eligible[g][0]
    a, b, m = regions[index]
    if b - a < 12:
        return regions, answers, "minority sample too short for two disjoint checks"
    mid = (a + b) / 2.
    halves = [(a, mid, m), (mid, b, m)]
    checked = []
    for x, z, _ in halves:
        answer = _section_voice_recovery_answer(ask(clip(x, z), SECTION_VOICE_CLIP_PROMPT))
        checked.append(answer)
    if not all(x.get("g") == g and x.get("present") and x.get("conf") == "high"
               and not x.get("conflict") and x.get("arrangement") in ("solo_lead", "lead_plus_backing")
               for x in checked):
        return regions, answers, "minority subdivision did not corroborate both halves"
    return (regions[:index] + halves + regions[index + 1:],
            answers[:index] + checked + answers[index + 1:],
            "minority lead corroborated in two disjoint halves; parent sample replaced")


def _section_voice_context_recheck(regions, answers, clip, stem_clip, ask, duration, section_hints=None):
    """Corroborate a rare voice with longer context, without weakening votes."""
    def eligible(x):
        return (x.get("present") and x.get("conf") == "high" and not x.get("conflict")
                and x.get("arrangement") in ("solo_lead", "lead_plus_backing"))
    counts = {g: sum(eligible(x) and x.get("g") == g for x in answers) for g in ("male", "female")}
    if min(counts.values()) != 1 or max(counts.values()) < 2:
        return regions, answers, ""
    minority = min(counts, key=counts.get)
    i = next(i for i, x in enumerate(answers) if eligible(x) and x.get("g") == minority)
    a, b, m = regions[i]
    # Two disjoint eight-to-twelve-second checks retain phrase context.
    # Each must independently agree in both the mix and vocal stem.
    lo, hi = a, min(duration, a + 24.)
    for sec in section_hints or []:
        start, end = float(sec["start"]), float(sec["end"])
        overlap = max(0., min(b, end) - max(a, start))
        if start <= (a + b) / 2. < end and overlap >= .75 * (b - a):
            length = min(24., end - start)
            lo = min(max(start, a), end - length)
            hi = lo + length
            break
    if hi - lo < 16.:
        return regions, answers, "minority context too short for two eight-second checks"
    mid = (lo + hi) / 2.
    halves = [(lo, mid, m), (mid, hi, m)]
    checked = []
    for x, z, _ in halves:
        pair = [_section_voice_recovery_answer(ask(audio, SECTION_VOICE_CLIP_PROMPT))
                for audio in (clip(x, z), stem_clip(x, z))]
        if not all(eligible(v) and v.get("g") == minority for v in pair):
            return regions, answers, "longer-context mix/stem checks did not corroborate the minority lead"
        checked.append(pair[0])
    # Replace every overlapping old sample: no parent or contrary overlapping
    # observation is counted alongside the new evidence.
    kept = [(r, v) for r, v in zip(regions, answers) if r[1] <= lo or r[0] >= hi]
    result = sorted(kept + list(zip(halves, checked)), key=lambda item: item[0])
    rr, aa = [r for r, v in result], [v for r, v in result]
    if not _section_voice_recovery_groups(rr, aa):
        return regions, answers, "longer context lacked disjoint majority control samples"
    return rr, aa, "minority lead corroborated in mix and stem on two disjoint longer-context clips"


def _section_voice_short_recheck(regions, answers, clip, stem_clip, ask):
    eligible = lambda x: (x.get("present") and x.get("conf") == "high" and not x.get("conflict")
                          and x.get("arrangement") in ("solo_lead", "lead_plus_backing"))
    counts = {g: sum(eligible(x) and x.get("g") == g for x in answers) for g in ("male", "female")}
    if max(counts.values()) < 2:
        return regions, answers, ""
    majority = max(counts, key=counts.get)
    minority = "female" if majority == "male" else "male"
    # Examine short or uncertain passages first; no successful mixed result reaches here.
    candidates = [i for i, ((a,b,_), x) in enumerate(zip(regions, answers))
                  if b-a >= 12 and x.get("present") and (x.get("g") == minority or not eligible(x))]
    candidates.sort(key=lambda i: (not (eligible(answers[i]) and answers[i].get("g") == minority), i))
    for i in candidates[:3]:
        a,b,m = regions[i]; mid=(a+b)/2
        halves=[(a,mid,m),(mid,b,m)]; checked=[]
        for lo,hi,_ in halves:
            pair = [_section_voice_recovery_answer(ask(audio, SECTION_VOICE_CLIP_PROMPT))
                    for audio in (clip(lo,hi), stem_clip(lo,hi))]
            if not all(eligible(x) and x.get("g") == minority for x in pair):
                break
            checked.append(pair[0])
        if len(checked) == 2:
            return (regions[:i]+halves+regions[i+1:], answers[:i]+checked+answers[i+1:],
                    "short minority passage corroborated in mix and vocal stem on two disjoint halves")
    return regions, answers, "short passage mix/stem recheck did not confirm another lead"


VOCAL_PRESENCE_UNRESOLVED_MARKER = "VOCAL PRESENCE VERIFICATION: UNRESOLVED"
VOCAL_PRESENCE_UNRESOLVED_NOTE = (
    "\n\n" + VOCAL_PRESENCE_UNRESOLVED_MARKER + ". No sampled foreground lead was confirmed, "
    "and the dedicated check could not settle whether any human voice is audible. "
    "Do not assert a singer, singer identity, vocal range or reliable audio-transcribed lyrics. "
    "Earlier positive vocal descriptions are unverified. Do not call the track instrumental "
    "unless a separate VOCAL PRESENCE ARBITRATION verdict establishes it. Artist or group "
    "membership cannot establish vocal presence on this recording. This warning takes precedence "
    "over generic singer claims elsewhere in these notes.")


def _harmony_clips_one_lead(answers, pair_reply, had_conflict, whole_track_lead):
    """0.7-pre5 SECTION_VOICE_HARMONY_CLIPS: a short reason when sampled clips
    that disagree on the singer's sex still show ONE lead, or "". All of:
    the whole-track passes agree (no conflict) on a sex that matches the
    majority of the confident clip readings; a direct comparison heard the
    same singer with high confidence; the other-sex readings are a small
    minority (at most a quarter, at most three) and every one of them had
    backing harmonies; and no more than one clip heard co-leads."""
    if not SECTION_VOICE_HARMONY_CLIPS or had_conflict:
        return ""
    wt = str(whole_track_lead or "").lower()
    whole = "male" if wt in ("post_puberty_male", "adult_male", "young_male") else (
        "female" if wt in ("female_teen_adult", "adult_female", "young_female") else "")
    if not whole:
        return ""
    fields = {}
    for key in ("LEAD_CHANGE", "CONFIDENCE"):
        values = re.findall(r"(?mi)^\s*" + key + r"\s*[=:]\s*([a-z_]+)", _strip_md_emphasis(str(pair_reply or "")))
        if len(values) != 1:
            return ""
        fields[key] = values[0].lower()
    if fields != {"LEAD_CHANGE": "same_lead", "CONFIDENCE": "high"}:
        return ""
    votes = [x for x in answers if x.get("present") and x.get("conf") == "high" and not x.get("conflict")
             and x.get("arrangement") in ("solo_lead", "lead_plus_backing") and x.get("g") in ("male", "female")]
    if sum(1 for x in answers if x.get("arrangement") == "duet_co_leads" and x.get("conf") == "high") > 1:
        return ""
    major = [x for x in votes if x["g"] == whole]
    minor = [x for x in votes if x["g"] != whole]
    if not minor or len(major) < 3 or len(minor) > 3 or len(minor) * 4 > len(votes):
        return ""
    if any(x.get("arrangement") != "lead_plus_backing" for x in minor):
        return ""
    if HARMONY_CLIPS_SCATTERED_ONLY:
        # 0.7-pre8: two other-sex readings back to back are a passage sung by
        # someone else (a second singer's verse), not harmonies heard in passing.
        _other = [x["g"] != whole for x in votes]
        if any(a and b for a, b in zip(_other, _other[1:])):
            return ""
    return (f"{len(minor)} of {len(votes)} confident clips heard a {'female' if whole == 'male' else 'male'} "
            "voice, all with backing harmonies, and a direct comparison heard the same singer")


def _section_voice_recovery_check(moss_model, moss_processor, vocal_stem_path, mix_path,
                                  section_hints=None, had_conflict=False, whole_track_lead=None):
    """Listen across the full mix; pitch and vocal-stem availability are optional.
    Clear foreground singing, repeated clip readings and pair checks are required.
    """
    prefix = ("inconclusive -- conflicting whole-track voices" if had_conflict else
              "inconclusive -- no reliable sampled lead voices")
    failure = {"mixed": False, "summary": prefix + "; another lead not confirmed"}
    if moss_model is None or not mix_path or not os.path.exists(str(mix_path)):
        failure["summary"] += " (listening model or full-mix audio unavailable)"
        return failure
    status("Section voice check: listening across the track...")
    mix, rate = librosa.load(str(mix_path), sr=16000, mono=True)
    regions = _section_voice_coverage_windows(len(mix) / float(rate), section_hints)
    if not regions:
        failure["summary"] += " (no usable listening windows)"
        return failure

    def clip(a, b):
        return mix[max(0, int(a * rate)):min(len(mix), int(b * rate))]

    def ask(audio, prompt, budget=256):
        import soundfile as sf
        tmp = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
        tmp.close()
        try:
            sf.write(tmp.name, audio, rate)
            return moss_generate(moss_model, moss_processor, [{"role": "user", "content": [
                {"type": "text", "text": prompt}, {"type": "audio", "path": tmp.name}]}],
                max_new_tokens=budget) or ""
        finally:
            try:
                os.remove(tmp.name)
            except OSError:
                pass

    answers = []
    for a, b, _m in regions:
        audio = clip(a, b)
        # Digital/near silence needs no model call. Music without voice is
        # handled by the prompt's explicit foreground-vocal presence field.
        if not len(audio) or float(np.max(np.abs(audio))) < 1e-5:
            answer = _section_voice_recovery_answer("VOCALS_PRESENT=no")
        else:
            answer = _section_voice_recovery_answer(ask(audio, SECTION_VOICE_CLIP_PROMPT))
        answers.append(answer)
    presence_diagnostic = {}
    # Lead absence is only a trigger, never evidence that all vocals are absent.
    # Any sampled vocal presence (including uncertain-gender/group voices) vetoes it.
    if (INSTRUMENTAL_FULL_COVERAGE_CHECK and len(answers) >= 4
            and all(not x.get("present") for x in answers)):
        try:
            presence = _instrumental_full_coverage(mix, rate, ask, presence_diagnostic)
        except Exception as exc:
            presence = None
            presence_diagnostic.update(outcome="unresolved", detail="verification failed: " + type(exc).__name__)
        if presence:
            return {"mixed": False, "summary": "checked -- full-mix presence verification: instrumental",
                    "presence_arbitration": presence}
    # Preserve every already-successful v2/v3 decision and all original votes.
    # Only a shortage of repeated, contradictory readings enables extra sampling.
    if not _section_voice_recovery_groups(regions, answers):
        extra = _section_voice_gap_windows(len(mix) / float(rate), regions, answers)
        for a, b, m in extra:
            audio = clip(a, b)
            if not len(audio) or float(np.max(np.abs(audio))) < 1e-5:
                answer = _section_voice_recovery_answer("VOCALS_PRESENT=no")
            else:
                answer = _section_voice_recovery_answer(ask(audio, SECTION_VOICE_CLIP_PROMPT))
            regions.append((a, b, m))
            answers.append(answer)
        ordered = sorted(zip(regions, answers), key=lambda item: item[0])
        regions = [item[0] for item in ordered]
        answers = [item[1] for item in ordered]
    subdivision_log = ""
    if not _section_voice_recovery_groups(regions, answers):
        regions, answers, subdivision_log = _section_voice_subdivide_minority(regions, answers, clip, ask)
    if (not _section_voice_recovery_groups(regions, answers)
            and (had_conflict or "minority subdivision did not corroborate" in subdivision_log)
            and vocal_stem_path and os.path.exists(str(vocal_stem_path))):
        try:
            stem, stem_rate = librosa.load(str(vocal_stem_path), sr=rate, mono=True)
            if abs(len(stem) / float(stem_rate) - len(mix) / float(rate)) <= 0.25:
                def stem_clip(a, b):
                    return stem[max(0, int(a * rate)):min(len(stem), int(b * rate))]
                regions, answers, short_log = _section_voice_short_recheck(regions, answers, clip, stem_clip, ask)
                subdivision_log = (subdivision_log + "; " + short_log).strip("; ")
                if not _section_voice_recovery_groups(regions, answers):
                    regions, answers, context_log = _section_voice_context_recheck(
                        regions, answers, clip, stem_clip, ask, len(mix) / float(rate), section_hints)
                    subdivision_log = (subdivision_log + "; " + context_log).strip("; ")
        except Exception:
            pass  # Optional recovery cannot erase existing evidence.
    heard = {x.get("g") for x in answers if x.get("present") and x.get("conf") == "high"
             and x.get("arrangement") in ("solo_lead", "lead_plus_backing") and x.get("g")}
    if len(heard) > 1:
        prefix = "inconclusive -- sampled lead voices disagree"
    elif heard and not had_conflict:
        prefix = "sampled -- no different lead confirmed"
    sample_log = "; samples: " + "; ".join(
        f"{_mmss(a)}-{_mmss(b)} {x.get('lead') or 'uncertain'} ({x.get('conf') or 'unknown confidence'}; {x.get('arrangement') or 'unknown arrangement'})"
        for (a, b, _), x in zip(regions, answers))
    failure["summary"] = prefix + sample_log
    if subdivision_log:
        failure["summary"] += "; " + subdivision_log
    if presence_diagnostic:
        failure["summary"] += "; presence verification " + presence_diagnostic.get("outcome", "unresolved") + ": " + presence_diagnostic.get("detail", "")
        failure["presence_diagnostic"] = presence_diagnostic
        failure["presence_unresolved"] = presence_diagnostic.get("outcome") == "unresolved"
    groups = _section_voice_recovery_groups(regions, answers)
    if not groups:
        return failure
    # Two comparisons must corroborate the clip readings. Opposite apparent
    # genders/pitches alone never establish different people.
    prompt = SECTION_VOICE_PAIR_PROMPT
    for index in range(2):
        a, b = groups["female"][index]
        c, d = groups["male"][index]
        pair = np.concatenate((clip(a, b), np.zeros(rate, dtype=mix.dtype), clip(c, d)))
        pair_reply = ask(pair, prompt)
        if not _section_voice_pair_confirmed(pair_reply):
            diagnostic = " ".join(str(pair_reply).split())[:300] or "empty answer"
            failure["summary"] += f"; direct comparison {index + 1} did not confirm a different lead: {diagnostic}"
            _one = _harmony_clips_one_lead(answers, pair_reply, had_conflict, whole_track_lead)
            if _one and failure["summary"].startswith("inconclusive -- sampled lead voices disagree"):
                failure["summary"] = ("sampled -- no different lead confirmed (" + _one + ")"
                                      + failure["summary"][len("inconclusive -- sampled lead voices disagree"):])
            return failure
    female, male = groups["female"], groups["male"]
    def spans(items):
        return ", ".join(f"{_mmss(a)}-{_mmss(b)}" for a, b in items)
    detail = f"female lead heard in sampled clips {spans(female)}; male lead heard in sampled clips {spans(male)}"
    evidence = "Repeated voiced clips and two direct comparisons confirmed different foreground lead voices. " + detail
    # Keep the legacy sentence readable by existing Musiclyse/load/export code;
    # explicitly restrict its interpretation to the sampled intervals.
    block = ("\n\nSECTION VOICE CHECK (measured clip times, then heard by the listening model):\n"
             "- SAMPLED_LEADS_ONLY=yes\n"
             f"- FEMALE_LEAD_SAMPLES={spans(female)}\n"
             f"- MALE_LEAD_SAMPLES={spans(male)}\n"
             f"- Asked about each stretch on its own, the listening model heard a male singer in {spans(male)}, "
             f"and a female singer in the main lead ({_mmss(female[0][0])}-{_mmss(female[0][1])}).\n"
             "- Two direct clip comparisons confirmed different foreground leads, rather than a register "
             "change, doubling or backing harmonies. FINAL LEAD PROFILE=mixed_leads.\n"
             "- These times are sampled listening windows, NOT singer-change or section boundaries. "
             "Neither singer is established as the majority lead. Do not assign untested passages to either "
             "voice or describe the whole-track pitch range as one person's range. Earlier whole-track "
             "single-lead claims are superseded. The singers' ages are not established by these clips.")
    return {"mixed": True, "detail": detail, "evidence": evidence, "block": block,
            "summary": "confirmed -- different leads in sampled clips (see SECTION VOICE CHECK)"}


def _section_voice_check(moss_model, moss_processor, vocal_stem_path, final_lead, initial_lead,
                         confirm_lead, vocal_objective_report, mix_path=None, section_hints=None,
                         vocals_present=""):
    conflict = _section_voice_conflict(final_lead, initial_lead, confirm_lead)
    coverage = (SECTION_VOICE_CHECK and SECTION_VOICE_COVERAGE_CHECK
                and (vocals_present in ("yes", "uncertain")
                     or (not vocals_present and final_lead in (None, "", "unknown", "unparsed", "uncertain")))
                and final_lead != "mixed_leads")
    # An explicit no-vocals decision must never trigger recovery.
    if vocals_present == "no":
        return None
    legacy = None
    if not conflict:
        legacy = _section_voice_check_legacy(moss_model, moss_processor, vocal_stem_path, final_lead,
                                             initial_lead, confirm_lead, vocal_objective_report, mix_path)
        if not coverage or (legacy and legacy.get("mixed")):
            return legacy
    try:
        result = _section_voice_recovery_check(moss_model, moss_processor, vocal_stem_path, mix_path,
                                               section_hints, conflict, whole_track_lead=final_lead)
        status_done("Section voice check: " + result["summary"].split("; samples:")[0])
        return result
    except Exception as exc:
        status_done("Section voice check: coverage check unavailable")
        reason = "conflicting whole-track voices" if conflict else "no reliable sampled lead voices"
        return {"mixed": False, "summary": "inconclusive -- " + reason
                + "; recovery failed (" + type(exc).__name__ + ")"}


_SV_BLOCK_RE = re.compile(r"SECTION VOICE CHECK \(measured[^\n]*\n[\s\S]*?heard a (male|female) singer in ([^\n]*?), and a "
                          r"(male|female) singer in the main lead")
_SV_NOT_UPGRADED_RE = re.compile(r"\s*\[Objective f0 histogram shows two well-separated pitch centres, but the listening "
                                 r"passes reported a single lead\. NOT upgraded:[^\]]*\]")


def _unbroken_colead_prompt_note(vocal_text, background):
    """Target identity resolution only; leave adult co-lead acoustic checks alone."""
    if not PRESERVE_UNBROKEN_COLEAD_IDENTITY:
        return ""
    young = re.search(r"(?mi)(?:Initial isolated lead profile:|FINAL LEAD PROFILE:|SINGER_IDENTITY=)\s*"
                      r"(?:child_male_likely|adolescent_male_likely)\b", str(vocal_text or ""))
    unbroken = re.search(r"(?i)\bunbroken\b|\bboy[- ]soprano\b|\bvoice (?:had|has) not (?:yet )?broken\b",
                         str(background or ""))
    acoustic_mark = "VOICE MATURITY: the voice sounds UNBROKEN" in str(vocal_text or "")
    if not (young or unbroken or acoustic_mark):
        return ""
    return (
        "\n\nUNBROKEN VOICE WITH CO-LEADS (identity, not a new acoustic decision):\n"
        "Resolve each credited singer separately. An unbroken male voice can be heard as female "
        "in the same track as a real female co-lead. Similar pitch, female-sounding clips or the "
        "presence of a female guest do not change a documented male singer into a woman. Conversely, "
        "a male artist credit does not make a documented female co-lead male. Preserve both supported "
        "identities and any supported unbroken-voice evidence; do not assign identities to sampled "
        "windows merely from their perceived gender. A youthful age alone does not prove an unbroken voice. "
        "Group membership, a feature credit or hypothetical wording alone does not prove either lead.\n"
        "ONLY when THIS recording has both a documented unbroken male lead and a documented female "
        "co-lead, use SINGER_IDENTITY=mixed_leads and LEAD_SINGERS=several. In addition to the normal "
        "fields, append all six fields below, with concrete track/recording-era evidence for each basis. "
        "Omit these fields if either performer, role or voice maturity is uncertain. Never copy the "
        "placeholders or infer a fact just to fill them:\n"
        "UNBROKEN_MALE_LEAD_CONFIRMED=yes\nUNBROKEN_MALE_LEAD_NAME=<verified performer name>\n"
        "UNBROKEN_MALE_LEAD_BASIS=<supported male lead identity and unbroken voice at this recording>\n"
        "FEMALE_COLEAD_CONFIRMED=yes\nFEMALE_COLEAD_NAME=<verified different performer name>\n"
        "FEMALE_COLEAD_BASIS=<supported female co-lead identity for this recording>\n"
        "These are reference-based identity findings, not audio-only evidence or inferred changeover times."
    )


def _unbroken_colead_identity(identity_text):
    """Retain explicitly grounded per-performer findings, never infer from a pitch tag.
    No fields -> exact no-op. Keep the acoustic pipeline and its sample map unchanged.
    """
    if not PRESERVE_UNBROKEN_COLEAD_IDENTITY:
        return identity_text
    text = str(identity_text or "")
    def field(key):
        hits = re.findall(r"(?mi)^" + key + r"\s*[=:]\s*([^\n]*)", text)
        return hits[0].strip() if len(hits) == 1 else ""
    if any(field(k).lower() != "yes" for k in ("UNBROKEN_MALE_LEAD_CONFIRMED", "FEMALE_COLEAD_CONFIRMED")):
        return identity_text
    keys = ("UNBROKEN_MALE_LEAD_NAME", "FEMALE_COLEAD_NAME", "UNBROKEN_MALE_LEAD_BASIS", "FEMALE_COLEAD_BASIS")
    values = [field(k) for k in keys]
    if any(not v or re.search(r"[<>|]|\b(?:unknown|uncertain|unverified|placeholder)\b", v, re.I) for v in values):
        return identity_text
    if values[0].casefold() == values[1].casefold():
        return identity_text
    if any(name.casefold() not in basis.casefold() for name, basis in zip(values[:2], values[2:])):
        return identity_text
    if not re.search(r"(?i)\bunbroken\b|\bvoice (?:had|has) not (?:yet )?broken\b", values[2]):
        return identity_text
    if any(re.search(r"(?i)\b(?:no evidence|not confirmed|not established|hypothetical|possibly)\b", v) for v in values[2:]):
        return identity_text
    if re.search(r"(?i)\b(?:not|never|without)\b.{0,30}\bunbroken\b", values[2]):
        return identity_text
    # Do not manufacture a valid identity result from an otherwise malformed reply.
    if not re.search(r"(?m)^SINGER_IDENTITY\s*[=:]\s*\S+", text):
        return identity_text
    out = re.sub(r"(?m)^(SINGER_IDENTITY\s*[=:]\s*)\S+", r"\g<1>mixed_leads", text, count=1)
    if re.search(r"(?m)^LEAD_SINGERS\s*[=:]", out):
        out = re.sub(r"(?m)^(LEAD_SINGERS\s*[=:]\s*)\S+", r"\g<1>several", out, count=1)
    else:
        out += "\nLEAD_SINGERS=several"
    if "UNBROKEN_MALE_IDENTITY_PRESERVED=yes" not in out:
        out = out.rstrip() + "\nUNBROKEN_MALE_IDENTITY_PRESERVED=yes\n"
    if "COLEAD_IDENTITY_SCOPE=" not in out:
        out += ("COLEAD_IDENTITY_SCOPE=The identity findings retain an unbroken male lead AND a female "
                "co-lead. Female-sounding samples do not establish which person sang them; do not "
                "relabel both people female or assign unverified passage identities.\n")
    return out


def _identity_colead_recheck_needed(identity_text, background):
    if not PRESERVE_UNBROKEN_COLEAD_IDENTITY:
        return False
    text = str(identity_text or "")
    # A complete supported mixed result requires no extra call.
    if re.search(r"(?m)^SINGER_IDENTITY=mixed_leads\b", text):
        return False
    young = re.search(r"(?m)^SINGER_IDENTITY=(?:child_male_likely|adolescent_male_likely)\b", text)
    young = young or re.search(r"(?i)\bunbroken\b|before his voice broke", text)
    return bool(young and re.search(r"(?i)\b(?:co[- ]lead|duet|shared lead vocals)\b", str(background or "")))


def _identity_colead_source_checked(candidate, background, metadata):
    """Accept a repair only with explicit per-performer fields and source excerpts.
    Never promote a group member, backing singer or pitch impression to co-lead.
    """
    fixed = _unbroken_colead_identity(candidate)
    if "UNBROKEN_MALE_IDENTITY_PRESERVED=yes" not in str(fixed):
        return None
    def field(key):
        hits = re.findall(r"(?mi)^" + key + r"\s*=\s*([^\n]+)", str(candidate or ""))
        return hits[0].strip() if len(hits) == 1 else ""
    norm = lambda x: re.sub(r"\s+", " ", str(x)).strip().casefold()
    bg = norm(background)
    title = norm((metadata or {}).get("title", ""))
    for prefix, role in (("MALE", "UNBROKEN_MALE_LEAD_NAME"), ("FEMALE", "FEMALE_COLEAD_NAME")):
        quote, name = field(prefix + "_IDENTITY_SOURCE"), field(role)
        if not quote or not name or len(quote) > 800 or norm(quote) not in bg or norm(name) not in norm(quote):
            return None
        if prefix == "MALE" and not re.search(r"(?i)\bunbroken\b|voice (?:had|has) not (?:yet )?broken|before his voice broke", quote):
            return None
        if prefix == "FEMALE":
            if (not title or title not in norm(quote)
                    or not re.search(r"(?i)\b(?:co[- ]lead|duet|shared lead vocals)\b", quote)
                    or re.search(r"(?i)\b(?:not|no|rumou?r|unconfirmed|possibly|backing only)\b", norm(quote).replace(title, "[title]").replace(norm(name), "[name]"))):
                return None
    return fixed


def _reference_single_credit_roster(background, metadata, name, credit):
    """Positive, complete track personnel list; never infer exclusivity from silence."""
    norm = lambda x: re.sub(r"\s+", " ", str(x)).strip().casefold()
    title = norm((metadata or {}).get("title", ""))
    artist = norm((metadata or {}).get("artist", ""))
    if not title or not artist or not name or not credit:
        return False
    articles = re.split(r'(?m)^--- "([^"\n]+)" ---\s*\n', str(background or ""))
    for i in range(1, len(articles), 2):
        article_title, body = articles[i], articles[i+1]
        # Require the actual track article, rather than band/album credits.
        if norm(article_title) not in (title, title + " (song)") or artist not in norm(body):
            continue
        if re.search(r"(?i)\b(?:co[- ]lead|duet|guest vocal(?:ist|s)?|additional vocal(?:ist|s)?)\b", body):
            continue
        headings = list(re.finditer(r"(?mi)^(?:={2,6}\s*)?(Personnel|Credits)(?:\s*={2,6})?\s*$", body))
        for h in headings:
            tail = body[h.end():]
            # A following non-personnel heading establishes that the list was
            # not cut off by a reference snippet's length cap.
            end = re.search(r"(?mi)^(?:={2,6}\s*)?(Charts|Chart performance|Certifications|References|External links|Notes|Release history|Reception)(?:\s*={2,6})?\s*$", tail)
            if not end:
                continue
            block = tail[:end.start()].strip()
            if not block or re.search(r"\.\.\.|…|(?i:additional personnel|guest|co[- ]lead)", block):
                continue
            vocal_names = []; valid = True
            for line in block.splitlines():
                if not line.strip():
                    continue
                row = re.match(r"^\s*[*#•-]?\s*([^–—\n]+?)\s+[–—-]\s+(.+?)\s*$", line)
                if not row:
                    valid = False
                    break
                performer, roles = row.groups()
                if re.search(r"(?i)\b(?:vocals?|singer|singing)\b", roles):
                    # Even another backing singer vetoes this conservative path.
                    vocal_names.append(norm(performer))
                    if re.search(r"(?i)\bbacking\b|\bbackground\b", roles):
                        valid = False
                if re.search(r"(?i)\b(?:not|uncertain|possibly|uncredited)\b", roles):
                    valid = False
            if (valid and vocal_names == [norm(name)] and norm(credit) in norm(block)
                    and norm(name) in norm(credit) and re.search(r"(?i)\bvocals?\b", credit)):
                return True
    return False


def _reference_vocal_correction(candidate, background, metadata):
    """Require verbatim, positive credits; silence about guests is insufficient."""
    def field(key):
        hits = re.findall(r"(?mi)^" + key + r"\s*=\s*([^\n]+)", str(candidate or ""))
        return hits[0].strip() if len(hits) == 1 else ""
    norm = lambda x: re.sub(r"\s+", " ", str(x)).strip().casefold()
    title = norm((metadata or {}).get("title", ""))
    scope, name = field("REFERENCE_SCOPE"), field("REFERENCE_SINGER")
    credit, identity = field("REFERENCE_TRACK_SOURCE"), field("REFERENCE_IDENTITY_SOURCE")
    bg = norm(background)
    if scope not in ("single_male", "all_male_group") or not title or not name:
        return None
    if any(not q or len(q) > 1800 or norm(q) not in bg for q in (credit, identity)):
        return None
    roster = (scope == "single_male" and _reference_single_credit_roster(background, metadata, name, credit))
    if (not roster and title not in norm(credit)) or norm(name) not in norm(credit) or norm(name) not in norm(identity):
        return None
    if not roster and not re.search(r"(?i)\b(?:lead vocals?|lead singer|sole vocalist|only vocalist)\b", credit):
        return None
    evidence = norm(credit + " " + identity).replace(title, "[title]").replace(norm(name), "[name]")
    if re.search(r"\b(?:not|no|possibly|unconfirmed|rumou?r|female|duet|co[- ]lead|guest vocalist)\b", evidence):
        return None
    if scope == "single_male":
        if not roster and not re.search(r"\b(?:sole|only|single) (?:lead )?(?:singer|vocalist)\b", evidence):
            return None
        if not re.search(r"\b(?:male|man|his|he)\b", norm(identity)):
            return None
        count = "one"
    else:
        if not re.search(r"\b(?:all[- ]male|boy ?band|male vocal group)\b", evidence):
            return None
        count = "several"
    tag = field("SINGER_IDENTITY")
    if tag not in ("post_puberty_male", "adolescent_male_likely", "child_male_likely"):
        return None
    return ("SINGER_IDENTITY=" + tag + "\nCONFIDENCE=medium\nLEAD_SINGERS=" + count
            + "\nREFERENCE_VOCAL_CORRECTION=yes\nREASONING=Positive reference credits constrain singer identity and count; "
            "the contradictory sampled gender impressions do not establish a female co-lead. "
            "Acoustic measurements remain unchanged.\nREFERENCE_TRACK_SOURCE=" + credit
            + "\nREFERENCE_IDENTITY_SOURCE=" + identity)


def _vocal_presence_still_unresolved(vocal_result, svc, final_lead=None):
    svc = svc or {}
    # A whole-track yes cannot overrule failed targeted corroboration when
    # the section checks found no reliable lead anywhere. Accepted mixed
    # leads and successful presence arbitration retain their existing path.
    if (not svc.get("mixed") and not svc.get("presence_arbitration")
            and (svc.get("presence_diagnostic") or {}).get("outcome") == "voice_detected"
            and "no reliable sampled lead voices" in str(svc.get("summary") or "")):
        return True
    flag = _parse_vocals_present_flag(vocal_result or "")
    if flag in ("yes", "no"):
        return False
    if not flag and final_lead in ("post_puberty_male", "female_teen_adult", "mixed_leads"):
        return False  # Preserve an accepted legacy lead when only the flag is missing.
    svc = svc or {}
    if svc.get("mixed") or svc.get("presence_arbitration"):
        return False
    if (svc.get("presence_diagnostic") or {}).get("outcome") == "voice_confirmed":
        return False
    # Accepted lead samples are positive human-vocal evidence too.
    if re.search(r"; samples:[^\n]*\b(?:male|female) \(high; (?:solo_lead|lead_plus_backing)\)", str(svc.get("summary") or "")):
        return False
    return True


def _section_voice_identity_line(svc):
    """The line the singer-identity step is shown when the section voice
    check confirmed a second lead of the other gender, else ""."""
    if not svc or not svc.get("mixed"):
        return ""
    if "SAMPLED_LEADS_ONLY=yes" in svc.get("block", ""):
        return (svc.get("evidence", "") + " These acoustic impressions suggest mixed leads but can confuse register changes with another person. "
                "Check positive reference credits before settling singer identity. Neither voice is established as the majority lead. "
                "Only the sampled intervals were checked; do not infer ages from these clips.")
    return ("SECTION VOICE CHECK (measured, then heard by the listening model): " + (svc.get("evidence") or "")
            + " These acoustic impressions suggest mixed leads; reference credits may identify a register-change false positive. "
            "Preserve genuine documented co-leads and do not infer exclusive credits from missing information.")


def _qualify_unconfirmed_leads(identity_text, analysis_text):
    """Do not publish a single-lead identity when sampled genders disagree."""
    t = str(identity_text or "")
    if (not t or "REFERENCE_VOCAL_CORRECTION=yes" in t
            or "UNBROKEN_MALE_IDENTITY_PRESERVED=yes" in t
            or re.search(r"(?mi)^SINGER_IDENTITY=mixed_leads\s*$", t)):
        return identity_text
    line = re.search(r"Section voice check[^\n]*inconclusive -- sampled lead voices disagree[^\n]*", str(analysis_text or ""))
    if not line:
        return identity_text
    evidence = line.group(0)
    if not all(re.search(r"\b" + g + r" \(high; (?:solo_lead|lead_plus_backing)\)", evidence) for g in ("male", "female")):
        return identity_text
    if not re.search(r"(?mi)^SINGER_IDENTITY=(?:female_teen_adult|post_puberty_male|uncertain)\s*$", t):
        return identity_text
    return ("SINGER_IDENTITY=uncertain\n"
            "REASONING=High-confidence sampled clips suggest both male and female foreground leads, "
            "but corroboration did not establish distinct singers. The whole-track lead profile is provisional; "
            "neither a single lead nor mixed leads is established.\nCONFIDENCE=low\nLEAD_SINGERS=uncertain")


def _reconcile_identity_with_section_voice(identity_text, analysis_text):
    """When the notes carry a SECTION VOICE CHECK block (a second lead of the
    other gender, confirmed) but the singer-identity answer names one
    voice, set it to mixed_leads / LEAD_SINGERS=several and say why. Any
    other identity text is returned unchanged."""
    t = str(identity_text or "")
    try:
        if not SECTION_VOICE_CHECK or not t or "REFERENCE_VOCAL_CORRECTION=yes" in t:
            return identity_text
        m = _SV_BLOCK_RE.search(str(analysis_text or ""))
        if not m:
            return _qualify_unconfirmed_leads(identity_text, analysis_text)
        tag = _parse_singer_identity(t)
        if not tag or tag == "mixed_leads":
            return identity_text
        other, spans, main = m.group(1), m.group(2).strip(), m.group(3)
        preserved_young = (PRESERVE_UNBROKEN_COLEAD_IDENTITY
                           and tag in ("child_male_likely", "adolescent_male_likely")
                           and _identity_reason_says_unbroken(t))
        out = re.sub(r"(?m)^(SINGER_IDENTITY\s*[=:]\s*)\S+", lambda _m: _m.group(1) + "mixed_leads", t, count=1)
        if re.search(r"(?m)^LEAD_SINGERS\s*[=:]", out):
            out = re.sub(r"(?m)^(LEAD_SINGERS\s*[=:]\s*)\S+", lambda _m: _m.group(1) + "several", out, count=1)
        else:
            out = out.rstrip() + "\nLEAD_SINGERS=several"
        note = (f" [Set to mixed_leads by the section voice check: the listening model heard a {other} lead in "
                f"{spans} and a {main} lead elsewhere; '{tag}' above describes the main lead only.]")
        if "SAMPLED_LEADS_ONLY=yes" in str(analysis_text or ""):
            note = " [Set to mixed_leads by confirmed sampled lead voices; no majority lead or untested section assignments are established.]"
        if re.search(r"(?m)^REASONING\s*[=:]", out):
            out = re.sub(r"(?m)^(REASONING\s*[=:][^\n]*)", lambda _m: _m.group(1) + note, out, count=1)
        else:
            out = out.rstrip() + "\nREASONING=" + note.strip()
        if preserved_young and "UNBROKEN_MALE_IDENTITY_PRESERVED=yes" not in out:
            out = out.rstrip() + "\nUNBROKEN_MALE_IDENTITY_PRESERVED=yes\n"
            out += ("COLEAD_IDENTITY_SCOPE=A supported unbroken male identity was retained before the "
                    "track-wide tag became mixed_leads. Female-sounding samples are impressions, not "
                    "proof of female identity. Preserve any separately documented female co-lead; "
                    "do not assign the male identity to every sample or invent passage identities.\n")
        return out
    except Exception:
        return identity_text


def _section_voice_audit_line(svc, final_lead, initial_lead, confirm_lead, vocal_objective_report):
    """One line for the VOCAL DECISION AUDIT, on every track that has one:
    what the section voice check did, or why it did not run."""
    try:
        if svc and svc.get("summary"):
            why = svc["summary"]
        elif not SECTION_VOICE_CHECK:
            why = "not run -- switched off"
        else:
            g = _adult_lead_gender(final_lead)
            sep = _f0_hint_separation(vocal_objective_report)
            if not g:
                why = "not run -- the lead is not a settled adult voice (young, child, uncertain or mixed)"
            elif any(o and o not in ("unknown", "unparsed") and _adult_lead_gender(o) != g
                     for o in (initial_lead, confirm_lead)):
                why = "not run -- the vocal passes disagree on the lead's gender or age"
            elif sep is None:
                why = "not run -- no second vocal pitch centre"
            elif _f0_sep_is_octave(sep):
                why = "not run -- the two vocal pitch centres are an octave apart"
            elif sep < SECTION_VOICE_MIN_SHIFT_ST:
                why = f"not run -- the vocal pitch centres are under {SECTION_VOICE_MIN_SHIFT_ST:g} semitones apart"
            else:
                why = "not run -- no separated vocal track to measure"
        return f"- Section voice check (a second lead of the other gender): {why}\n"
    except Exception:
        return ""


def _apply_section_voice_check(final_lead, multi_voice_fields, svc):
    """mixed_leads and the co-lead fields when the section voice check found
    a second lead of the other gender; else final_lead unchanged."""
    if not svc or not svc.get("mixed") or multi_voice_fields is None:
        return final_lead
    multi_voice_fields["num_distinct_voices"] = "2"
    multi_voice_fields["voice_arrangement"] = "duet_co_leads"
    multi_voice_fields["co_lead_detail"] = svc.get("detail") or ""
    _prev = _SV_NOT_UPGRADED_RE.sub("", multi_voice_fields.get("multi_voice_evidence") or "")
    if _prev.strip().lower() == "none":
        _prev = ""
    multi_voice_fields["multi_voice_evidence"] = ((_prev + " [" + (svc.get("evidence") or "") + "]").strip())
    return "mixed_leads"


def choose_final_vocal_lead(initial_lead, confirm_lead, confirm_confidence, confirm_text="", median_f0=None, multi_voice_fields=None):
    initial = initial_lead if initial_lead in VOCAL_LEAD_TAGS else "unknown"
    confirm = confirm_lead if confirm_lead in VOCAL_LEAD_TAGS else ""

    if not confirm:
        return initial
        
    # If multi-voice fields clearly indicate multiple distinct leads, override to mixed_leads
    if multi_voice_fields:
        _arr = multi_voice_fields.get("voice_arrangement")
        if _arr in ("duet_co_leads", "call_response") or (
            multi_voice_fields.get("num_distinct_voices") in ("2", "3", "3+")
            and _arr not in ("solo_lead", "lead_plus_backing", "group_unison")
        ):
            return "mixed_leads"

    strong_confirm = confirm_confidence in ("medium", "high")
    high_confirm = confirm_confidence == "high"

    # If the isolated pass already says mixed leads, do not silently collapse that
    # into a single-gender lead from the confirmation pass alone.
    if initial == "mixed_leads":
        return initial

    # Confirmation may discover distinct co-leads the first pass missed.
    if confirm == "mixed_leads" and strong_confirm:
        return "mixed_leads"

    if initial == "unknown":
        return confirm if strong_confirm else "uncertain"

    # If the initial result is already young/gender-uncertain:
    # - accept a clear teenage/adult female result at medium/high confidence
    # - require high confidence before overriding with other child/young categories
    if initial in UNCERTAIN_YOUNG_CATEGORIES:
        if confirm == "female_teen_adult" and strong_confirm:
            return confirm

        if high_confirm and confirm not in ("unknown",):
            return confirm

        return initial

    # Move away from female only when the confirmation pass is confident enough.
    # This still targets the common failure mode where a young male voice gets labelled
    # female because of pitch/youth, but it avoids demoting a teenage/adult female to
    # "uncertain" on medium-confidence evidence alone.
    if initial in FEMALE_LEAD_CATEGORIES:
        if strong_confirm and confirm in MALE_LEAD_CATEGORIES:
            return confirm

        if high_confirm and confirm in UNCERTAIN_YOUNG_CATEGORIES:
            return confirm

        if confirm == initial:
            return confirm

        return initial

    # Male → female from confirmation alone is normally blocked (young male leads are often
    # mislabeled female on pitch). Exception: when objective median f0 is extreme (≥ hard
    # male cap), a strong female confirmation is allowed — this is the female→male mislabel
    # recovery path for high-median leads.
    if initial in MALE_LEAD_CATEGORIES or initial in ADOLESCENT_MALE_CATEGORIES:
        try:
            _med = float(median_f0) if median_f0 is not None else None
        except (TypeError, ValueError):
            _med = None
        # Its own threshold (the value the male caps used to have), so raising
        # those caps for adult rock/pop tenors does not also narrow this
        # female-mislabel recovery path, which needs a strong female
        # confirmation as well.
        _male_cap = globals().get("F0_FEMALE_RECOVERY_MIN_HZ") or globals().get("F0_MALE_ANY_HARD_CAP_HZ")
        _extreme_f0 = (
            _med is not None
            and _male_cap is not None
            and _med >= float(_male_cap)
        )
        if confirm == "female_teen_adult" and _extreme_f0 and strong_confirm:
            return confirm
        if confirm in ("child_male_likely", "child_female_likely", "child_gender_uncertain"):
            # Flipping a male/adolescent classification to a child category
            # requires BOTH high confidence AND actual corroborating evidence
            # in the confirmation pass's own text — a self-reported
            # confidence tag alone is not sufficient. This is the fix for
            # clearly adult/male voices being flipped to "child" on a single
            # isolated pass's say-so.
            if high_confirm and _confirm_child_flip_has_evidence(confirm_text):
                return confirm
            return initial

        # Prefer adolescent over post_puberty when either pass supports adolescent
        # at medium/high confidence — early teen-pop male leads are often still
        # high/light and should not be rounded up to settled post-puberty male.
        if confirm == "adolescent_male_likely" and strong_confirm:
            return confirm
        if initial == "adolescent_male_likely" and confirm == "post_puberty_male":
            # Only allow upgrade to post_puberty on high confidence; medium keeps adolescent.
            if high_confirm:
                return confirm
            return initial
        if initial in ("post_puberty_male", "adult_male", "young_male") and confirm == "adolescent_male_likely":
            if strong_confirm:
                return confirm

        if high_confirm and confirm == "post_puberty_male":
            return confirm

        if confirm == initial:
            return confirm

        return initial

    if confirm == initial:
        return confirm

    return initial


def _reconcile_identity_with_acoustic_age(resolved_tag, final_lead):
    """Decide the user-facing lead category from the identity pass + acoustics.

    The identity pass is the right authority for WHO is singing (and therefore
    gender, which artist identity genuinely settles). It is NOT an authority on
    vocal maturity: it is allowed to map "a named, documented solo male artist"
    straight to post_puberty_male, which silently overwrites a correct
    adolescent acoustic read whenever the artist is an adult today. That is the
    early-teen-recording failure -- the artist is a grown man now, so the
    identity pass upgrades a voice that had not finished changing when the
    record was made.

    So: identity wins on gender and on everything else, but it may not push a
    male acoustic read UP the maturity scale. Demotions and gender corrections
    are unaffected.
    """
    if resolved_tag not in VOCAL_LEAD_TAGS:
        return final_lead
    if resolved_tag == final_lead:
        return resolved_tag

    acoustic_young_male = final_lead in ("adolescent_male_likely",)
    identity_adult_male = resolved_tag in ("post_puberty_male", "adult_male", "young_male")
    if acoustic_young_male and identity_adult_male:
        # Same gender, higher maturity, sourced from identity rather than audio.
        return final_lead

    return resolved_tag


_VFT_NOUN = r"(?:vocal(?:s|ist|ly)?|singer|singing|sings|sung|voice|lead|led|crooner|frontman|frontwoman|rapper)"
_VFT_FEMALE = r"(?:female|woman|women|girl|girls|soprano|mezzo(?:[- ]soprano)?|contralto|alto)"


def _free_form_vocal_lean(texts):
    """dev55: what the listening model's free descriptions say about the lead
    voice's gender. Returns dict(lean=None|'male'|'female'|'both',
    male=n, female=n, teen=bool, quotes=[...]). Only sentences that are about
    a voice (vocal/singer/lead...) count; hedged sentences ("uncertain",
    "unclear"), negations ("no female vocals"), structured tag lines and
    saxophone ranges are ignored."""
    male = female = 0
    teen = False
    quotes = []
    for txt in texts or []:
        if not txt:
            continue
        for sent in re.split(r"(?<=[.!?\n])\s+", str(txt)):
            s_ = sent.strip()
            if not s_ or len(s_) > 400:
                continue
            low = s_.lower()
            if not re.search(r"\b" + _VFT_NOUN + r"\b", low):
                continue
            if re.search(r"\b(?:uncertain|unclear|cannot|can't|unsure|ambiguous|androgynous|not (?:clear|possible|determinable))\b", low):
                continue
            if re.search(r"\b(?:no|not|without|absence of|lacks?)\s+(?:a\s+|any\s+)?(?:male|female|man|woman|boy|girl)\b", low):
                continue
            if re.match(r"^\W*(?:lead_category|gender_modifier|lead_profile|backing_profiles?|backing_note|"
                        r"vocal[ _]demographics|probability_estimate|co_lead_detail|backing)\b", low):
                continue
            if re.search(r"\b(?:alto|tenor|baritone|soprano)\s+sax", low):
                continue
            f_ = bool(re.search(r"\b" + _VFT_FEMALE + r"\b", low))
            m_ = bool(re.search(r"\b(?:male|man|men|boy|baritone|tenor)\b", low)) and not re.search(
                r"\b(?:female|woman|women|girl)\b", low)
            if m_ and not f_:
                male += 1
            elif f_ and not m_:
                female += 1
            if m_ or f_:
                quotes.append(s_)
                if re.search(r"\b(?:teen|teens|teenage|teenager|adolescent)\b", low):
                    teen = True
    lean = None
    if male and not female:
        lean = "male"
    elif female and not male:
        lean = "female"
    elif male and female:
        lean = "both"
    return {"lean": lean, "male": male, "female": female, "teen": teen, "quotes": quotes}


def _vocal_probability_masses(vocal_text):
    """dev57: (male, female) probability mass from the vocal pass's
    "PROBABILITY ESTIMATE:" line (adolescent + post-puberty male; female), or
    None when there is no such line."""
    t = re.sub(r"[\u2010-\u2015]", "-", _strip_md_emphasis(str(vocal_text or "")))
    m = re.search(r"(?im)^[ \t*_-]*PROBABILITY[ _]ESTIMATE[ \t]*[:=][ \t]*(.+)$", t)
    if not m:
        return None
    male = female = 0.0
    seen = False
    for part in re.split(r"[;,]\s*", m.group(1)):
        mm = re.match(r"\s*(.+?)[\s:=]+([01](?:\.\d+)?)\s*$", part)
        if not mm:
            continue
        lab, val = mm.group(1).lower(), float(mm.group(2))
        if "female" in lab:
            female += val
            seen = True
        elif "male" in lab and "child" not in lab:
            male += val
            seen = True
    return (male, female) if seen else None


def _vocal_probability_young_mass(vocal_text):
    """dev59: (young, adult_male, female) from the vocal pass's PROBABILITY
    ESTIMATE line: child-like + adolescent male; post-puberty / adult male;
    female. None when there is no such line."""
    t = re.sub(r"[\u2010-\u2015]", "-", _strip_md_emphasis(str(vocal_text or "")))
    m = re.search(r"(?im)^[ \t*_-]*PROBABILITY[ _]ESTIMATE[ \t]*[:=][ \t]*(.+)$", t)
    if not m:
        return None
    young = adult = female = 0.0
    seen = False
    for part in re.split(r"[;,]\s*", m.group(1)):
        mm = re.match(r"\s*(.+?)[\s:=]+([01](?:\.\d+)?)\s*$", part)
        if not mm:
            continue
        lab, val = mm.group(1).lower(), float(mm.group(2))
        if "female" in lab:
            female += val
        elif "child" in lab or "prepubert" in lab or "adolescent" in lab or "changing" in lab:
            young += val
        elif "male" in lab:
            adult += val
        else:
            continue
        seen = True
    return (young, adult, female) if seen else None


_VOICE_UNBROKEN_MARK = "VOICE MATURITY: the voice sounds UNBROKEN"


def _vocal_probability_veto(lean, vocal_text):
    """dev57: see VOCAL_PROBABILITY_VETO. A short reason when the vocal pass's
    probability line clearly favours the other gender, else ""."""
    if not VOCAL_PROBABILITY_VETO or lean not in ("male", "female"):
        return ""
    pm = _vocal_probability_masses(vocal_text)
    if not pm:
        return ""
    male, female = pm
    mine, other = (female, male) if lean == "female" else (male, female)
    if other >= 0.4 and mine <= 0.15 and other >= 3.0 * max(mine, 1e-9):
        other_name = "male" if lean == "female" else "female"
        return (f"the dedicated vocal pass's probability estimate favours a {other_name} voice "
                f"({other:.2f} against {mine:.2f})")
    return ""


def _apply_free_form_vocal_lean(final_lead, info, median_f0=None):
    """dev55: lead profile from the free descriptions, only when the
    structured passes settled nothing (unknown / uncertain / empty)."""
    if not VOCAL_FREE_TEXT_GENDER or not info or final_lead not in ("", "unknown", "uncertain", None):
        return final_lead
    lean = info.get("lean")
    if info.get("vetoed"):
        return final_lead
    if lean == "female":
        return "female_teen_adult"
    if lean == "male":
        cap = float(F0_MALE_ANY_HARD_CAP_HZ) if F0_MALE_ANY_HARD_CAP_HZ is not None else None
        if info.get("teen"):
            return "adolescent_male_likely"
        if median_f0 is None or cap is None or float(median_f0) < cap:
            return "post_puberty_male"
    return final_lead


def _free_form_vocal_lean_line(info):
    if not info or not info.get("quotes"):
        return ""
    qs = "; ".join('"%s"' % q.replace("\n", " ")[:160] for q in info["quotes"][:3])
    lean = {"male": "a male lead", "female": "a female lead", "both": "both male and female voices"}.get(
        info.get("lean"), "no consistent gender")
    return (f"LISTENING-MODEL VOICE DESCRIPTIONS (free text, audio-based): {info.get('male', 0)} describe a male "
            f"voice, {info.get('female', 0)} a female voice -> {lean}"
            + (" (described as teenage)" if info.get("teen") else "") + f". Quotes: {qs}"
            + (f" -- NOT used for FINAL LEAD PROFILE: {info['vetoed']}; the two disagree, so the "
               "audio-only gender is left open" if info.get("vetoed") else "")
            + (f". {_VOICE_UNBROKEN_MARK}: heard as a woman's voice in those descriptions, while "
               f"the dedicated vocal pass rated it child-like or a teenage boy's at "
               f"{info['unbroken'][0]:.2f} together (adult man {info['unbroken'][1]:.2f}, woman "
               f"{info['unbroken'][2]:.2f}) -- the usual signature of a boy whose voice has not "
               "dropped yet" if info.get("unbroken") else ""))


def _free_text_vocal_step(moss_model, moss_processor, audio_path, first_pass, era_result,
                          vocal_result, final_lead, median_f0, no_clear_vocals):
    """dev55: run the short voice question and collect the free descriptions;
    returns (final_lead, info). Never raises."""
    if not (VOCAL_FREE_TEXT_GENDER and vocal_result and not no_clear_vocals):
        return final_lead, None
    _vq = ""
    if VOCAL_QUICK_PASS and moss_model is not None and moss_processor is not None:
        try:
            status("Listening — describing the lead voice in plain words...")
            _vq = moss_generate(moss_model, moss_processor, [{
                "role": "user",
                "content": [
                    {"type": "text", "text": VOCAL_QUICK_PROMPT},
                    {"type": "audio", "path": audio_path},
                ],
            }], max_new_tokens=96) or ""
        except Exception:
            _vq = ""
    try:
        _fp_desc = re.split(r"\n\s*(?:LYRICS|13\.\s*LYRICS)", first_pass or "")[0]
        info = _free_form_vocal_lean([_fp_desc, era_result or "", _vq])
        info["quick"] = (_vq or "").strip()
        _veto = _vocal_probability_veto(info.get("lean"), vocal_result)
        if _veto:
            info["vetoed"] = _veto
            if VOCAL_UNBROKEN_SIGNATURE and info.get("lean") == "female":
                _ym = _vocal_probability_young_mass(vocal_result)
                if _ym and _ym[0] >= 0.5:
                    info["unbroken"] = _ym
        before = final_lead
        final_lead = _apply_free_form_vocal_lean(final_lead, info, median_f0)
        if final_lead != before:
            info["applied"] = final_lead
        return final_lead, info
    except Exception:
        return final_lead, None


def _vocal_note_pitch_line(stem_notes):
    """dev55: duration-weighted pitch summary of the vocal stem's transcribed
    notes, or "" when there are too few (fewer than 40 notes / 15 s sung)."""
    if not VOCAL_NOTE_PITCH_LINE or not isinstance(stem_notes, dict):
        return ""
    notes = None
    for key in ("vocals", "vocal", "voice"):
        if stem_notes.get(key):
            notes = stem_notes[key]
            break
    if not notes:
        return ""
    mids, durs = [], []
    for n in notes:
        if not isinstance(n, dict):
            continue
        m = _sx_note_midi(n)
        sp = _sx_note_span(n)
        if m is None or not sp:
            continue
        d = float(sp[1] - sp[0])
        if d <= 0 or not (36 <= m <= 96):
            continue
        mids.append(float(m))
        durs.append(d)
    if len(mids) < 40 or sum(durs) < 15.0:
        return ""
    m_ = np.asarray(mids)
    w_ = np.asarray(durs)
    o = np.argsort(m_)
    cw = np.cumsum(w_[o]) / float(w_.sum())

    def _q(p):
        return float(m_[o][min(len(o) - 1, int(np.searchsorted(cw, p)))])

    def _hz(mm):
        return 440.0 * 2.0 ** ((mm - 69.0) / 12.0)

    def _nm(mm):
        try:
            return librosa.midi_to_note(int(round(mm)))
        except Exception:
            return ""
    med, lo, hi = _q(0.5), _q(0.1), _q(0.9)
    return (f"VOCAL NOTE PITCH (second reading, from the vocal stem's {len(mids)} transcribed notes, "
            f"{sum(durs):.0f} s sung, duration-weighted): median {_hz(med):.0f} Hz ({_nm(med)}); "
            f"10-90%: {_hz(lo):.0f}-{_hz(hi):.0f} Hz ({_nm(lo)} to {_nm(hi)}). Pitch is not gender or age; "
            "use it, like the pyin reading, only as a range/register description and a soft constraint.")


def _pyin_reading_confidence_note(vocal_objective_report):
    """dev55: a low-confidence label for a pyin reading that rests on very few
    voiced frames or has collapsed to one pitch, else ""."""
    rep = str(vocal_objective_report or "")
    if not VOCAL_NOTE_PITCH_LINE or not rep:
        return ""
    reasons = []
    vf = _voiced_fraction_from_report(rep)
    if vf is not None and vf < 0.05:
        reasons.append(f"only {vf * 100:.1f}% of the scanned frames were confidently voiced")
    m = re.search(r"(?:practical sung range \(10-90%\)|voiced pitch 5-95 percentile range):\s*([0-9.]+)-([0-9.]+)\s*Hz", rep)
    if m:
        try:
            a, b = float(m.group(1)), float(m.group(2))
            if a > 0 and b / a < 2.0 ** (1.0 / 12.0):
                reasons.append(f"its range collapsed to {a:.0f}-{b:.0f} Hz (under a semitone)")
        except ValueError:
            pass
    if not reasons:
        return ""
    return ("pyin pitch reading confidence: LOW (" + "; ".join(reasons)
            + ") -- prefer VOCAL NOTE PITCH when present.")


def build_vocal_priority_note(lead_profile, backing_profiles):
    if lead_profile in ("child_male_likely", "young_male"):
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is a young/child male voice. "
            "For user-facing claims about the lead singer, say 'young male voice'. Say 'boy' only if the evidence is unambiguously child-like and confidence is high; otherwise do not overstate certainty."
        )

    elif lead_profile in ("child_female_likely", "young_female"):
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is a young/child female voice. "
            "For user-facing claims about the lead singer, say 'young female voice'. Say 'girl' only if the evidence is unambiguously child-like and confidence is high; otherwise do not overstate certainty."
        )

    elif lead_profile in ("child_gender_uncertain",):
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is a young/child voice with uncertain gender. "
            "For user-facing claims, say 'young/child voice; gender uncertain' or 'young voice; cannot confidently tell boy/girl'. Do not call it a girl/woman/boy/man unless the user explicitly corrects you."
        )

    elif lead_profile == "adolescent_male_likely":
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is an adolescent male voice — "
            "clearly male, not a small child's voice, but not yet a fully mature adult male voice either "
            "(a voice actively changing, or recently changed but still light/boyish). "
            "For user-facing claims, say 'young/adolescent male voice' or 'a voice that sounds like it's still "
            "changing'. Do NOT round this up to a full adult male description ('post-pubescent', 'mature male "
            "voice') and do NOT round it down to 'child' or 'boy' — this is its own category with its own evidence."
        )

    elif lead_profile in ("post_puberty_male", "adult_male"):
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is a post-puberty male voice. "
            "Say 'male voice' or 'male lead'; say 'teen/adult male' only if the analysis explicitly supports that age range."
        )


    elif lead_profile in ("female_teen_adult", "adult_female"):
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is a female teen/adult voice. "
            "Say 'female voice', 'female lead', or 'young adult female voice' as appropriate. "
            "Do not describe this as child-like, boy/girl uncertain, or a young male voice unless the user explicitly corrects it."
        )

    elif lead_profile == "mixed_leads":
        note = (
            "\n\nVOCAL CLASSIFICATION PRIORITY: The final lead vocal category is mixed leads / multiple lead voices. "
            "Describe the distinct co-leads (register, rough gender if supported, section roles) using CO_LEAD_DETAIL / "
            "MULTI-SINGER audit when present. Do not flatten this to a single singer. "
            "Do not invent a second gender if only one gender is evidenced among the co-leads."
        )

    else:
        note = (
            "\n\nVOCAL PROFILE PRIORITY: For final claims about lead vocal age/gender category, prefer the VOCAL DECISION AUDIT / FINAL LEAD PROFILE "
            "over generic wording elsewhere in this analysis. Distinguish lead from backing; do not claim mixed male/female vocals unless distinct voices are explicitly identified."
        )

    if backing_profiles == "female":
        note += (
            " If female backing/harmonies are mentioned, describe them as possible female backing only, "
            "not as an equal mixed-lead performance, unless distinct co-leads are established."
        )
    elif backing_profiles == "male":
        note += (
            " If male backing/harmonies are mentioned, describe them as possible male backing only, "
            "not as an equal mixed-lead performance, unless distinct co-leads are established."
        )
    elif backing_profiles == "mixed":
        note += (
            " Mixed backing is not the same as mixed lead vocals. Do not describe the track as having mixed lead vocals "
            "unless distinct male and female co-leads are explicitly established."
        )

    return note


def _backing_guidance(backing_profiles):
    full = build_vocal_priority_note("unknown", backing_profiles)
    for start in (" If female backing", " If male backing", " Mixed backing"):
        i = full.find(start)
        if i != -1:
            return full[i:]
    return ""


def _lead_gender(tag):
    if tag in ("child_male_likely", "adolescent_male_likely", "post_puberty_male",
               "adult_male", "young_male"):
        return "male"
    if tag in FEMALE_LEAD_CATEGORIES or tag == "child_female_likely":
        return "female"
    return None


def _identity_overrides_gender(identity_tag, acoustic_lead):
    gi, ga = _lead_gender(identity_tag), _lead_gender(acoustic_lead)
    return bool(gi and ga and gi != ga)


def _unbroken_voice_note(identity_tag, backing_profiles):
    """dev59: ACOUSTIC VOCAL READING for a voice recorded as sounding
    unbroken (see VOCAL_UNBROKEN_SIGNATURE)."""
    g = _lead_gender(identity_tag)
    if g == "male":
        who = (
            "With the SINGER IDENTITY below (male), this is a boy's voice that has not dropped yet "
            "-- describe it that way (light, high, boyish; it had not broken), never as a woman's. "
            "If he was already in his mid-teens on this recording, say so: most boys' voices have "
            "dropped by about 15 or 16, so a voice still unbroken at that age is notable, and "
            "worth remarking on when the voice comes up."
        )
    elif g == "female":
        who = "With the SINGER IDENTITY below (female), it is simply a woman's voice."
    else:
        who = ("Without an identity to settle it, say it sounds young and high -- it could be a boy "
               "whose voice has not dropped or a woman -- and do not assign a gender.")
    return (
        "\n\nACOUSTIC VOCAL READING (audio only): the lead voice sounds UNBROKEN -- the listening "
        "model heard it as a woman's voice, while its dedicated vocal pass rated it most likely a "
        "child's or a teenage boy's. " + who + " Everything measured still stands: use the VOCAL "
        "PITCH REPORT and VOCAL / SINGER PROFILE for pitch figures, range, register, timbre, "
        "brightness and weight, exactly as reported." + _backing_guidance(backing_profiles)
    )


def build_acoustic_vocal_note(acoustic_lead, backing_profiles, identity_tag=None, unbroken=False):
    """How the lead voice SOUNDS, from the audio passes only.

    Emitted for every track, with or without tags. Previously the only vocal
    wording directive was produced inside the identity-resolution branch, so
    a tagged file got a strong "say 'male voice'" instruction keyed to the
    identity result while an untagged copy of the same audio got none -- and
    the writer's description of pitch and register changed with the tags.
    This note is keyed to the acoustic FINAL LEAD PROFILE and is therefore
    identical for the same audio regardless of metadata.
    """
    if (unbroken and VOCAL_UNBROKEN_SIGNATURE and acoustic_lead in ("", "unknown", "uncertain", None)):
        return _unbroken_voice_note(identity_tag, backing_profiles)
    if _identity_overrides_gender(identity_tag, acoustic_lead):
        # The audio passes' gender label is known to be wrong for this track
        # (typically an unbroken boy's voice read as female). Don't hand the
        # writer a sentence telling it to say "female voice" at all.
        return (
            "\n\nACOUSTIC VOCAL READING (audio only): the audio passes' gender label for "
            f"this lead ({acoustic_lead}) is overridden by the SINGER IDENTITY note below — "
            "a high voice that has not fully deepened is routinely misread by those passes. "
            "Everything they MEASURED still stands: use the VOCAL PITCH REPORT and VOCAL / "
            "SINGER PROFILE for pitch figures, range, register, timbre, brightness and weight, "
            "exactly as reported. Only the gender and age words come from the identity."
            + _backing_guidance(backing_profiles)
        )
    note = build_vocal_priority_note(acoustic_lead, backing_profiles)
    note = note.replace(
        "VOCAL CLASSIFICATION PRIORITY:",
        "ACOUSTIC VOCAL READING (audio only; identical with or without file tags; its gender/age "
        "wording is only the default when no SINGER IDENTITY note follows):",
    ).replace(
        "VOCAL PROFILE PRIORITY:",
        "ACOUSTIC VOCAL READING (audio only; identical with or without file tags; its gender/age "
        "wording is only the default when no SINGER IDENTITY note follows):",
    )
    # The per-category wording directives inside build_vocal_priority_note
    # ("say 'female voice'", "do not call it a young male voice") must not
    # overrule an identity result that names a different gender.
    note = note.replace(
        " Do not describe this as child-like, boy/girl uncertain, or a young male voice unless the user explicitly corrects it.",
        "",
    )
    return note + (
        " Use this reading, the VOCAL PITCH REPORT and the VOCAL / SINGER PROFILE for the "
        "measured SOUND: pitch figures, range, register, timbre and weight. File tags, the "
        "artist's name, Wikipedia and the cover art must NOT change those. Gender and age "
        "words (she/he, woman/boy/man, young/adult) are different: if a SINGER IDENTITY note "
        "is present it decides them, because the audio alone cannot tell an unbroken boy's "
        "voice from a woman's. With no identity note, use this reading's category."
    )


# dev69: a young singer whose voice had already deepened (see VOCAL_DEEPENED_SIGNATURE).
_YOUNG_MALE_TAGS = ("child_male_likely", "adolescent_male_likely")
_ADULT_MALE_ACOUSTIC = ("post_puberty_male", "adult_male")


def _measured_lead_pitch(text):
    """{'median_hz', 'median_note', 'lo_hz', 'hi_hz', 'lo_note', 'hi_note',
    'notes_median_hz', 'notes_median_note', 'notes_lo_hz', 'notes_hi_hz'} from
    the VOCAL PITCH REPORT and the VOCAL NOTE PITCH line, whichever exist."""
    t = str(text or "")
    out = {}
    m = re.search(r"objective voiced pitch median:\s*([\d.]+)\s*Hz", t)
    if m:
        out["median_hz"] = float(m.group(1))
    m = re.search(r"approximate median note:\s*([A-G][#♯♭b]?\d)", t)
    if m:
        out["median_note"] = m.group(1)
    m = re.search(r"practical sung range \(10th-90th percentile\):\s*([\d.]+)-([\d.]+)\s*Hz", t)
    if m:
        out["lo_hz"], out["hi_hz"] = float(m.group(1)), float(m.group(2))
    m = re.search(r"practical range in notes:\s*([A-G][#♯♭b]?\d)\s+to\s+([A-G][#♯♭b]?\d)", t)
    if m:
        out["lo_note"], out["hi_note"] = m.group(1), m.group(2)
    m = re.search(r"VOCAL NOTE PITCH \(second reading[^)]*\):\s*median\s*([\d.]+)\s*Hz\s*\(([^)]+)\);\s*"
                  r"10-90%:\s*([\d.]+)-([\d.]+)\s*Hz", t)
    if m:
        out["notes_median_hz"], out["notes_median_note"] = float(m.group(1)), m.group(2)
        out["notes_lo_hz"], out["notes_hi_hz"] = float(m.group(3)), float(m.group(4))
    return out


_UV_SAYS_UNBROKEN_RE = re.compile(
    r"(?i)\bunbroken\b|\bfemale[- ]sounding\b|\b(?:read|reads|heard|sounds?)\s+(?:as\s+)?(?:an?\s+)?"
    r"(?:high\s*/\s*)?(?:female|woman)\b")
_UV_SAYS_DEEPENED_RE = re.compile(
    r"(?i)\b(?:not|no longer|never|isn't|wasn't)\b[^.\n]{0,25}\bunbroken\b|"
    r"\balready\s+(?:broken|deepened|dropped)\b|\bhad\s+(?:already\s+)?(?:broken|deepened|dropped)\b")


def _identity_reason_says_unbroken(reason):
    """True when an identity's REASONING records a female-sounding or
    unbroken voice and does not say the voice had already deepened."""
    r = str(reason or "")
    return bool(_UV_SAYS_UNBROKEN_RE.search(r)) and not _UV_SAYS_DEEPENED_RE.search(r)


def _identity_resolution_reason(text):
    """The REASONING line of the SINGER IDENTITY RESOLUTION block in an
    analysis, or ""."""
    t = str(text or "")
    i = t.rfind("SINGER IDENTITY RESOLUTION")
    if i < 0:
        return ""
    m = re.search(r"REASONING\s*[=:]\s*([^\n]+)", t[i:i + 3000])
    return m.group(1) if m else ""


def _young_male_unbroken_identity_text(acoustic_lead):
    """UNBROKEN_VOICE_IDENTITY_CHECK: the SINGER IDENTITY note's sentence for a
    boy or teenager whose identity reasoning records a female-sounding or
    unbroken voice although the audio passes' final profile is a man's."""
    return (
        f"The audio passes' final profile reads {acoustic_lead} (a man's voice), but the identity "
        "reasoning records that the voice was heard as female-sounding: this is his voice before it "
        "broke, or while it was still changing, sitting where women's and boys' voices usually do. "
        "Describe it as a boy's high, light voice -- not a woman's and not a grown man's deepened "
        "voice. Keep the measured pitch, range and timbre exactly as reported; this singer is male, "
        "never 'she' or a woman."
    )


def _young_male_adult_voice_text(acoustic_lead, vocal_text):
    """dev69: the SINGER IDENTITY note's sentence when the identity puts a
    boy or teenager on the recording but the audio heard a man's voice."""
    p = _measured_lead_pitch(vocal_text)
    meds = [v for v in (p.get("median_hz"), p.get("notes_median_hz")) if v]
    low = bool(meds) and min(meds) < float(VOCAL_DEEPENED_MAX_MEDIAN_HZ)
    if low:
        _r = []
        if p.get("median_hz"):
            _r.append(f"{p['median_hz']:.0f} Hz ({p.get('median_note', '?')})")
        if p.get("notes_median_hz"):
            _r.append(f"{p['notes_median_hz']:.0f} Hz ({p.get('notes_median_note', '?')}) note by note")
        mp = " and ".join(_r)
        return (
            f"The audio heard a man's voice here: the vocal passes read it as {acoustic_lead}, and "
            f"the measured median pitch is {mp}, within an adult male singer's range. So his "
            "voice had already deepened (broken, or largely so) by this recording, even though he "
            "was young. Describe it as his deepened voice -- lower and fuller than a boy's "
            "unbroken voice -- not as high, light or boyish. If his earlier recordings, where the "
            "voice had not dropped, come up, that change is the thing to point out. Keep the "
            "measured pitch, range and timbre exactly as reported; this singer is male, never "
            "'she' or a woman."
        )
    return (
        f"The audio passes read it as {acoustic_lead} -- a man's voice -- while the identity puts "
        "him younger, so his voice may already have been deepening on this recording. Use this "
        "identity for gender and age, keep the measured pitch, range and timbre from the audio, "
        "and do not describe the voice as unbroken, high or light unless the measured pitch says so."
    )


def _confirm_flip_reading(text):
    """dev18: (first reading, confirmation reading, median Hz, median note)
    when the VOCAL DECISION AUDIT shows the confirmation pass alone turning
    the first vocal pass's female reading into a man's voice, and the lead's
    measured median pitch (both readings, when both exist) is at or above
    VOCAL_DEEPENED_MAX_MEDIAN_HZ; else None."""
    t = str(text or "")
    mi = re.search(r"(?m)^- Initial isolated lead profile:\s*([a-z_]+)", t)
    mc = re.search(r"(?m)^- Confirmation pass:\s*([a-z_]+)\s*\(confidence=(\w+)\)", t)
    mf = re.search(r"(?m)^- FINAL LEAD PROFILE:\s*([a-z_]+)", t)
    if not (mi and mc and mf):
        return None
    ini, con, fin = mi.group(1), mc.group(1), mf.group(1)
    if ini not in FEMALE_LEAD_CATEGORIES:
        return None
    if con not in _ADULT_MALE_ACOUSTIC or fin != con:
        return None
    p = _measured_lead_pitch(t)
    meds = [(v, nt) for v, nt in ((p.get("median_hz"), p.get("median_note")),
                                  (p.get("notes_median_hz"), p.get("notes_median_note"))) if v]
    if not meds:
        return None
    med, note = min(meds)
    if med < float(VOCAL_DEEPENED_MAX_MEDIAN_HZ):
        return None
    return ini, con, med, note or "?"


def _young_male_confirm_flip_text(acoustic_lead, vocal_text):
    """dev18: the SINGER IDENTITY note's sentence for a boy or teenager whose
    voice the first vocal pass heard as a woman's and only the confirmation
    pass as a man's, at a pitch above where a deepened voice sits."""
    ini, con, med, note = _confirm_flip_reading(vocal_text)
    return (
        f"The first vocal pass heard a woman's voice ({ini}); only the confirmation pass heard a "
        f"man's ({con}), and the measured median pitch is {med:.0f} Hz ({note}), above where a "
        "deepened male voice usually sits. For a boy or teenager that is his voice before it "
        "dropped: the lead voice sounds unbroken here, high and young, sitting where women's and "
        "boys' voices usually do. Call it his voice, use the male column of the VOICE-TYPE MAP for "
        "how high or deep it sits, and keep the measured pitch, range and timbre exactly as "
        "reported. Do not call it a grown man's voice. Never call this singer 'she' or a woman."
    )


# dev71: a pitch tracker reading an octave above the sung line (see VOCAL_PITCH_OCTAVE_CHECK).
_OCTAVE_CHECK_TAG = "OCTAVE CHECK:"


def _pitch_octave_error(text):
    """dev71: (pyin_median, corrected_median, notes_lo, notes_hi) when the
    pitch tracker's median sits an octave above the vocal stem's
    note-by-note median and the tracker itself also saw the lower octave;
    else None."""
    t = str(text or "")
    if not VOCAL_PITCH_OCTAVE_CHECK:
        return None
    p = re.search(r"objective voiced pitch median:\s*([\d.]+)\s*Hz", t)
    nm = re.search(r"VOCAL NOTE PITCH \(second reading[^)]*\):\s*median\s*([\d.]+)\s*Hz\s*\([^)]*\);\s*"
                   r"10-90%:\s*([\d.]+)-([\d.]+)\s*Hz", t)
    if not (p and nm):
        return None
    pyin, nmed = float(p.group(1)), float(nm.group(1))
    if pyin <= 0 or nmed <= 0:
        return None
    d = 12.0 * math.log2(pyin / nmed)
    if not (12.0 - float(VOCAL_PITCH_OCTAVE_TOL_ST) <= d <= 12.0 + float(VOCAL_PITCH_OCTAVE_TOL_ST)):
        return None
    # The tracker must itself show the lower octave: two pitch centres an
    # octave apart, or its own 10th percentile down at the note reading.
    seen_low = False
    mp = re.search(r"multi-peak hint: ~\d+ pitch centres near ([^(]*)\(~([\d.]+) semitones between top two", t)
    if mp:
        try:
            if abs(float(mp.group(2)) - 12.0) <= 1.0:
                seen_low = True
        except Exception:
            pass
    lo = re.search(r"practical sung range \(10th-90th percentile\):\s*([\d.]+)-([\d.]+)\s*Hz", t)
    if lo and abs(12.0 * math.log2(float(lo.group(1)) / nmed)) <= 2.0:
        seen_low = True
    if not seen_low:
        return None
    return pyin, pyin / 2.0, float(nm.group(2)), float(nm.group(3))


def _pitch_octave_raw_figure(text):
    """dev72: the tracker's median exactly as written ("200.0", "659.3")."""
    p = re.search(r"objective voiced pitch median:\s*([\d.]+)\s*Hz", str(text or ""))
    return p.group(1) if p else None


def _pitch_octave_check(text):
    """dev71: rewrite the VOCAL PITCH REPORT (median, note, range, voice-type
    map) an octave down when _pitch_octave_error finds the tracker an octave
    high, and flag the raw figure in the vocal measurements. Idempotent."""
    t = str(text or "")
    if _OCTAVE_CHECK_TAG in t:
        return t
    oe = _pitch_octave_error(t)
    if not oe:
        return t
    pyin, med, lo, hi = oe
    _raw_fig = _pitch_octave_raw_figure(t) or ("%g" % pyin)
    try:
        i = t.find("VOCAL PITCH REPORT (independent")
        if i < 0:
            return t
        j = t.find("\n\n", i)
        j = len(t) if j < 0 else j
        block = t[i:j]
        lines = block.split("\n")
        out = [lines[0],
               f"- objective voiced pitch median: {med:.1f} Hz",
               f"- approximate median note: {_hz_to_note_name(med)}",
               f"- practical sung range (10th-90th percentile): {lo:.1f}-{hi:.1f} Hz",
               f"- {_OCTAVE_CHECK_TAG} the pitch tracker read a median of {pyin:.1f} Hz "
               f"({_hz_to_note_name(pyin)}), exactly an octave above the vocal stem's note-by-note "
               f"reading ({_hz_to_note_name(med)}), and it also found the lower octave -- it was "
               "following the voice's first overtone for much of the song. The figures in this "
               "block are the sung line's: the median an octave down, the range from the note "
               "reading. Do not describe the voice as a soprano, treble or falsetto from the "
               "tracker's figure."]
        out.extend(_voice_type_map_lines(med, lo, hi))
        keep = [ln for ln in lines[1:] if ln.startswith("- Prefer median")]
        out.extend(keep)
        t = t[:i] + "\n".join(out) + t[j:]
        # Every other place that quotes the tracker's median (the vocal
        # measurements, the decision audit) is flagged, not rewritten.
        _tag = (f" [{_OCTAVE_CHECK_TAG} an octave above the sung line, which centres near "
                f"{med:.0f} Hz ({_hz_to_note_name(med)}); see VOCAL PITCH REPORT]")
        _num = r"(?:" + re.escape(_raw_fig) + r"|" + re.escape("%g" % pyin) + r"(?:\.0+)?)"
        _pat = re.compile(r"(?im)^([^\n]*(?:median f0|voiced pitch median)[^\n]*?\b"
                          + _num + r"\s*Hz[^\n]*)$")
        _hi_note = _hz_to_note_name(pyin)
        _pat2 = re.compile(r"(?m)^(approx median note:\s*" + re.escape(_hi_note) + r")\s*$")
        k = t.find("VOCAL PITCH REPORT (independent")
        k_end = t.find("\n\n", k) if k >= 0 else -1
        head, mid, tail = (t[:k], t[k:k_end], t[k_end:]) if (k >= 0 and k_end >= 0) else (t, "", "")
        fix = lambda x: _pat2.sub(lambda m: m.group(1) + _tag, _pat.sub(lambda m: m.group(1) + _tag, x))
        t = fix(head) + mid + fix(tail)
        # the report field filled from the old figures (dev66)
        t = re.sub(r"(?m)^MELODIC_RANGE=lead vocal [^\n]*\(median " + re.escape(_hi_note) + r"\)$",
                   lambda m: (f"MELODIC_RANGE=lead vocal {_hz_to_note_name(lo)}-{_hz_to_note_name(hi)} "
                              f"(median {_hz_to_note_name(med)})"), t, count=1)
        return t
    except Exception:
        return text


def _pitch_octave_audit_line(oct_err):
    """dev71: one line for the identity step's vocal evidence when the
    objective median f0 there is an octave too high (oct_err from
    _pitch_octave_error)."""
    if not oct_err:
        return ""
    pyin, med, _lo, _hi = oct_err
    return (f"{_OCTAVE_CHECK_TAG} the objective median f0 above ({pyin:.1f} Hz) is an octave too high "
            f"(the pitch tracker followed an overtone); the sung line centres near {med:.0f} Hz "
            f"({_hz_to_note_name(med)}), as the note reading shows.")


_STUCK_CHECK_TAG = "PITCH CHECK:"
_SEMITONE = 2.0 ** (1.0 / 12.0)


def _pitch_stuck_error(text):
    """dev73: (pyin_median, pyin_lo, pyin_hi, note_median, note_lo, note_hi)
    when the pitch tracker's sung range has collapsed to under a semitone
    while the vocal stem's note-by-note reading spans three semitones or
    more; else None. One stuck-pitch test scan read "194.9-197.1 Hz (G3 to G3)"
    from 5.9% voiced frames -- the tracker held one sustained tone -- while
    524 transcribed vocal notes over 143 s gave E3 to E4 around B3."""
    t = str(text or "")
    if not VOCAL_PITCH_STUCK_CHECK or _OCTAVE_CHECK_TAG in t:
        return None
    p = re.search(r"objective voiced pitch median:\s*([\d.]+)\s*Hz", t)
    r = re.search(r"practical sung range \(10th-90th percentile\):\s*([\d.]+)-([\d.]+)\s*Hz", t)
    nm = re.search(r"VOCAL NOTE PITCH \(second reading[^)]*\):\s*median\s*([\d.]+)\s*Hz\s*\([^)]*\);\s*"
                   r"10-90%:\s*([\d.]+)-([\d.]+)\s*Hz", t)
    if not (p and r and nm):
        return None
    try:
        pyin, lo, hi = float(p.group(1)), float(r.group(1)), float(r.group(2))
        nmed, nlo, nhi = float(nm.group(1)), float(nm.group(2)), float(nm.group(3))
    except ValueError:
        return None
    if min(pyin, lo, hi, nmed, nlo, nhi) <= 0:
        return None
    if hi / lo >= _SEMITONE or nhi / nlo < _SEMITONE ** 3:
        return None
    return pyin, lo, hi, nmed, nlo, nhi


def _pitch_stuck_check(text):
    """dev73: rewrite the VOCAL PITCH REPORT from the note-by-note reading
    when _pitch_stuck_error finds the tracker's range collapsed, and flag the
    collapsed figures where the vocal measurements quote them. Idempotent."""
    t = str(text or "")
    if _STUCK_CHECK_TAG in t:
        return t
    se = _pitch_stuck_error(t)
    if not se:
        return t
    pyin, lo, hi, med, nlo, nhi = se
    try:
        i = t.find("VOCAL PITCH REPORT (independent")
        if i < 0:
            return t
        j = t.find("\n\n", i)
        j = len(t) if j < 0 else j
        lines = t[i:j].split("\n")
        raw_med = _pitch_octave_raw_figure(t) or ("%g" % pyin)
        out = [lines[0],
               f"- objective voiced pitch median: {med:.1f} Hz",
               f"- approximate median note: {_hz_to_note_name(med)}",
               f"- practical sung range (10th-90th percentile): {nlo:.1f}-{nhi:.1f} Hz",
               f"- {_STUCK_CHECK_TAG} the pitch tracker's own range collapsed to {lo:.1f}-{hi:.1f} Hz "
               f"(under a semitone, median {raw_med} Hz, {_hz_to_note_name(pyin)}): it held one "
               "sustained tone for the few frames it could follow, which no sung line does. The "
               "figures in this block are the vocal stem's note-by-note reading (see VOCAL NOTE "
               "PITCH). Do not describe the voice as staying on one note."]
        out.extend(_voice_type_map_lines(med, nlo, nhi))
        out.extend(ln for ln in lines[1:] if ln.startswith("- Prefer median"))
        t = t[:i] + "\n".join(out) + t[j:]
        # Elsewhere the collapsed figures are flagged, not rewritten.
        _tag = (f" [{_STUCK_CHECK_TAG} a collapsed reading; the sung line spans "
                f"{_hz_to_note_name(nlo)}-{_hz_to_note_name(nhi)} around {_hz_to_note_name(med)}; "
                "see VOCAL PITCH REPORT]")
        _rng = r"%s\s*-\s*%s\s*Hz" % (re.escape("%.1f" % lo), re.escape("%.1f" % hi))
        _num = r"(?:" + re.escape(raw_med) + r"|" + re.escape("%g" % pyin) + r"(?:\.0+)?)"
        _pat = re.compile(r"(?im)^([^\n]*(?:(?:median f0|voiced pitch median)[^\n]*?\b" + _num
                          + r"\s*Hz|" + _rng + r")[^\n]*)$")
        k = t.find("VOCAL PITCH REPORT (independent")
        k_end = t.find("\n\n", k) if k >= 0 else -1
        head, mid, tail = (t[:k], t[k:k_end], t[k_end:]) if (k >= 0 and k_end >= 0) else (t, "", "")
        fix = lambda x: _pat.sub(lambda m: m.group(1) + _tag, x)
        t = fix(head) + mid + fix(tail)
        # the report field filled from the collapsed figures (dev66)
        t = re.sub(r"(?m)^MELODIC_RANGE=lead vocal [^\n]*\(median " + re.escape(_hz_to_note_name(pyin))
                   + r"\)$",
                   lambda m: (f"MELODIC_RANGE=lead vocal {_hz_to_note_name(nlo)}-{_hz_to_note_name(nhi)} "
                              f"(median {_hz_to_note_name(med)})"), t, count=1)
        return t
    except Exception:
        return text


_LOWCONF_CHECK_TAG = "PITCH CHECK (few voiced frames):"


def _pitch_low_confidence_error(text):
    """(pyin_median, note_median, note_lo, note_hi) when the pitch tracker's
    reading is marked LOW confidence and its median sits at least
    VOCAL_PITCH_LOW_CONFIDENCE_MIN_ST semitones from the vocal stem's
    note-by-note reading; else None. The octave and collapsed-range cases
    have their own checks and are left to them. the post-punk test track's tracker read
    a median of 622 Hz (D#5) from 0.4% voiced frames, so the voice-type map
    called the post-punk singer's baritone "falsetto / countertenor territory", while
    271 transcribed vocal notes centred on A#3."""
    t = str(text or "")
    if (not VOCAL_PITCH_LOW_CONFIDENCE_CHECK or _OCTAVE_CHECK_TAG in t or _STUCK_CHECK_TAG in t
            or "pyin pitch reading confidence: LOW" not in t):
        return None
    p = re.search(r"objective voiced pitch median:\s*([\d.]+)\s*Hz", t)
    nm = re.search(r"VOCAL NOTE PITCH \(second reading[^)]*\):\s*median\s*([\d.]+)\s*Hz\s*\([^)]*\);\s*"
                   r"10-90%:\s*([\d.]+)-([\d.]+)\s*Hz", t)
    if not (p and nm):
        return None
    try:
        pyin = float(p.group(1))
        nmed, nlo, nhi = float(nm.group(1)), float(nm.group(2)), float(nm.group(3))
    except ValueError:
        return None
    if min(pyin, nmed, nlo, nhi) <= 0:
        return None
    _tol = PITCH_CHECK_ROUNDING_TOL_ST if PITCH_CHECK_ROUNDED_FIGURES else 0.0
    if abs(12.0 * math.log2(pyin / nmed)) < float(VOCAL_PITCH_LOW_CONFIDENCE_MIN_ST) - _tol:
        return None
    return pyin, nmed, nlo, nhi


def _pitch_low_confidence_check(text):
    """Rewrite the VOCAL PITCH REPORT (median, note, range, voice-type map)
    from the note-by-note reading when _pitch_low_confidence_error applies,
    and flag the tracker's median where the vocal measurements quote it.
    Idempotent. The measured age/gender guards are not affected."""
    t = str(text or "")
    if _LOWCONF_CHECK_TAG in t:
        return t
    le = _pitch_low_confidence_error(t)
    if not le:
        return t
    pyin, med, nlo, nhi = le
    try:
        i = t.find("VOCAL PITCH REPORT (independent")
        if i < 0:
            return t
        j = t.find("\n\n", i)
        j = len(t) if j < 0 else j
        lines = t[i:j].split("\n")
        raw_med = _pitch_octave_raw_figure(t) or ("%g" % pyin)
        out = [lines[0],
               f"- objective voiced pitch median: {med:.1f} Hz",
               f"- approximate median note: {_hz_to_note_name(med)}",
               f"- practical sung range (10th-90th percentile): {nlo:.1f}-{nhi:.1f} Hz",
               f"- {_LOWCONF_CHECK_TAG} the pitch tracker read a median of {raw_med} Hz "
               f"({_hz_to_note_name(pyin)}) from too few confidently voiced frames to trust (its reading "
               "is marked LOW confidence), far from the vocal stem's note-by-note reading. The figures "
               "in this block are the note reading's (see VOCAL NOTE PITCH). Do not describe the voice's "
               "register from the tracker's figure."]
        out.extend(_voice_type_map_lines(med, nlo, nhi))
        out.extend(ln for ln in lines[1:] if ln.startswith("- Prefer median"))
        t = t[:i] + "\n".join(out) + t[j:]
        _tag = (f" [{_LOWCONF_CHECK_TAG} a low-confidence reading; the sung line centres near "
                f"{med:.0f} Hz ({_hz_to_note_name(med)}); see VOCAL PITCH REPORT]")
        _num = r"(?:" + re.escape(raw_med) + r"|" + re.escape("%g" % pyin) + r"(?:\.0+)?)"
        _pat = re.compile(r"(?im)^([^\n]*(?:median f0|voiced pitch median)[^\n]*?\b" + _num
                          + r"\s*Hz[^\n]*)$")
        k = t.find("VOCAL PITCH REPORT (independent")
        k_end = t.find("\n\n", k) if k >= 0 else -1
        head, mid, tail = (t[:k], t[k:k_end], t[k_end:]) if (k >= 0 and k_end >= 0) else (t, "", "")
        fix = lambda x: _pat.sub(lambda m: m.group(1) + _tag, x)
        t = fix(head) + mid + fix(tail)
        # the report field filled from the tracker's figures (dev66)
        t = re.sub(r"(?m)^MELODIC_RANGE=lead vocal [^\n]*\(median " + re.escape(_hz_to_note_name(pyin))
                   + r"\)$",
                   lambda m: (f"MELODIC_RANGE=lead vocal {_hz_to_note_name(nlo)}-{_hz_to_note_name(nhi)} "
                              f"(median {_hz_to_note_name(med)})"), t, count=1)
        return t
    except Exception:
        return text


def build_singer_identity_note(identity_tag, acoustic_lead, unbroken=False, vocal_text=""):
    """Who is singing (the person), which MAY use tags, cover art and
    background knowledge. Kept separate from the acoustic note so identity
    evidence can settle gender/age of the PERSON without rewriting the
    description of the SOUND."""
    if identity_tag not in VOCAL_LEAD_TAGS or identity_tag in ("unknown", ""):
        return ""
    if (SECTION_VOICE_CHECK and acoustic_lead == "mixed_leads" and identity_tag != "mixed_leads"
            and _SECTION_VOICE_HEAD + " (" in str(vocal_text or "")):
        # The section voice check heard a second lead of the other gender in
        # some stretches; a one-person identity names the main lead only.
        return (
            "\n\nSINGER IDENTITY (who is singing; combines audio, file tags, cover art and "
            f"background knowledge): {identity_tag}, for the main lead. The SECTION VOICE CHECK above "
            "heard a second lead singer of the other gender in the stretches it names, so this is a "
            "mixed-voice track: use this identity for the main lead only, and describe the second "
            "voice where it leads."
        )
    same = identity_tag == acoustic_lead
    txt = (
        "\n\nSINGER IDENTITY (who is singing; combines audio, file tags, cover art and "
        f"background knowledge): {identity_tag}. This decides the singer's gender and age "
        "and therefore the pronouns and the kind of voice you name (a boy's voice, a young "
        "man's, a woman's). "
    )
    if same:
        txt += "It agrees with the acoustic reading."
        return txt
    male_id = identity_tag in ("child_male_likely", "adolescent_male_likely",
                               "post_puberty_male", "adult_male", "young_male")
    female_ac = acoustic_lead in FEMALE_LEAD_CATEGORIES or acoustic_lead in (
        "child_female_likely",)
    if (male_id and unbroken and VOCAL_UNBROKEN_SIGNATURE
            and acoustic_lead in ("", "unknown", "uncertain", None)):
        txt += (
            "The audio says his voice sounds unbroken (see the ACOUSTIC VOCAL READING): it is his "
            "voice before it dropped, sitting where women's and boys' voices usually do. Call it "
            "his voice, use the male column of the VOICE-TYPE MAP for how high or deep it sits, "
            "and keep the measured pitch, range and timbre exactly as reported. Never call this "
            "singer 'she' or a woman."
        )
        return txt
    if male_id and female_ac:
        txt += (
            f"The audio passes read the voice as female ({acoustic_lead}), but the singer is "
            "male: treat that as his pitch sitting where female voices usually do, not as a "
            "woman singing. Call it his voice, use the male column of the VOICE-TYPE MAP for "
            "how high or deep it sits, and keep the measured pitch, range and timbre exactly "
            "as reported. Never call this singer 'she' or a woman."
        )
    elif (VOCAL_DEEPENED_SIGNATURE and identity_tag in _YOUNG_MALE_TAGS
          and acoustic_lead in _ADULT_MALE_ACOUSTIC):
        # dev69: the mirror of the unbroken voice -- a boy or teenager whose
        # voice the audio heard as a man's. The general sentence below gave
        # "the voice still sits high and light" as its example, the opposite.
        # dev18: unless only the confirmation pass heard a man, at a high
        # measured pitch (YOUNG_VOICE_CONFIRM_FLIP).
        if (UNBROKEN_VOICE_IDENTITY_CHECK
                and _identity_reason_says_unbroken(_identity_resolution_reason(vocal_text))):
            txt += _young_male_unbroken_identity_text(acoustic_lead)
        elif YOUNG_VOICE_CONFIRM_FLIP and _confirm_flip_reading(vocal_text):
            txt += _young_male_confirm_flip_text(acoustic_lead, vocal_text)
        else:
            txt += _young_male_adult_voice_text(acoustic_lead, vocal_text)
    else:
        txt += (
            f"The audio passes read it as {acoustic_lead or 'unknown'}. Use this identity for "
            "gender and age; keep the measured pitch, range and timbre from the audio, and "
            "mention the difference only if it is interesting (e.g. 'he was an adult here, but "
            "the voice still sits high and light')."
        )
    return txt


# ---- starting Ollama (0.6.2-dev15) --------------------------------------------------

_OLLAMA_LAUNCH_MODES = ("off", "background", "background_log", "log_window", "window")
def _ollama_override_name():
    """This build's override file: this script's name with "-ollama-override.py"
    in place of ".py" (0.6.2-dev16)."""
    try:
        stem = os.path.splitext(os.path.basename(os.path.abspath(__file__)))[0]
    except Exception:
        stem = "Musiclyse"
    return f"{stem}-ollama-override.py"
_OLLAMA_OWNED = {"proc": None, "log_fh": None, "window_id": None}


def _ollama_override_values():
    """The plain values assigned in this build's override file next to this
    script ({} when it isn't there). Read as values, never run."""
    try:
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), _ollama_override_name())
    except Exception:
        return {}
    if not os.path.isfile(path):
        return {}
    import ast as _ast
    found = {}
    try:
        tree = _ast.parse(open(path, encoding="utf-8").read(), filename=path)
        for node in tree.body:
            if (isinstance(node, _ast.Assign) and len(node.targets) == 1
                    and isinstance(node.targets[0], _ast.Name)):
                try:
                    found[node.targets[0].id] = _ast.literal_eval(node.value)
                except Exception:
                    pass
    except Exception as e:
        print(f"  ({_ollama_override_name()} could not be read ({e}) -- using the main script's settings.)")
        return {}
    found["_present"] = True
    return found


def _ollama_log_window_placement():
    """OLLAMA_LOG_WINDOW, or the override file's value: "behind" or "minimized"."""
    value = _ollama_override_values().get("OLLAMA_LOG_WINDOW", OLLAMA_LOG_WINDOW)
    return value if value in ("behind", "minimized") else "behind"


def _ollama_launch_mode():
    """OLLAMA_LAUNCH_MODE, or the value in this build's override file next to
    this script when that file is present (read as a value, never run)."""
    mode = OLLAMA_LAUNCH_MODE
    over = _ollama_override_values()
    if over.get("_present"):
        found = over.get("OLLAMA_LAUNCH_MODE")
        if found in _OLLAMA_LAUNCH_MODES:
            mode = found
        else:
            print(f"  ({_ollama_override_name()}: no valid OLLAMA_LAUNCH_MODE in it -- using {mode!r}.)")
    if mode not in _OLLAMA_LAUNCH_MODES:
        mode = "off"
    if mode in ("log_window", "window") and sys.platform != "darwin":
        mode = "background_log"
    return mode


def _ollama_log_path():
    """OLLAMA_LAUNCH_LOG as a full path (a relative one is inside this script's folder)."""
    path = os.path.expanduser(str(OLLAMA_LAUNCH_LOG or "logs/ollama.log"))
    if not os.path.isabs(path):
        try:
            path = os.path.join(os.path.dirname(os.path.abspath(__file__)), path)
        except Exception:
            path = os.path.abspath(path)
    return path


def _ollama_reachable(timeout=2):
    try:
        requests.get(OLLAMA_BASE_URL, timeout=timeout)
        return True
    except Exception:
        return False


def _ollama_binary():
    found = shutil.which("ollama")
    if found:
        return found
    for cand in ("/Applications/Ollama.app/Contents/Resources/ollama", "/opt/homebrew/bin/ollama",
                 "/usr/local/bin/ollama", os.path.expanduser("~/Applications/Ollama.app/Contents/Resources/ollama")):
        if os.path.isfile(cand) and os.access(cand, os.X_OK):
            return cand
    return None


def _ollama_launch_env():
    """The environment Ollama is started with: OLLAMA_LAUNCH_ENV, listening where
    Musiclyse talks to it, and with request-content logging off."""
    env = dict(os.environ)
    env.update({str(k): str(v) for k, v in (OLLAMA_LAUNCH_ENV or {}).items()})
    try:
        import urllib.parse as _up
        netloc = _up.urlparse(OLLAMA_BASE_URL).netloc
        if netloc:
            env["OLLAMA_HOST"] = netloc
    except Exception:
        pass
    env.pop("OLLAMA_DEBUG", None)                 # default detail, as an Ollama window shows
    env["OLLAMA_DEBUG_LOG_REQUESTS"] = "false"    # never log what was sent
    return env


def _osascript(lines, *args):
    cmd = ["osascript"]
    for line in lines:
        cmd += ["-e", line]
    out = subprocess.run(cmd + list(args), capture_output=True, text=True, timeout=20)
    return out.stdout.strip()


_TERMINAL_OPEN_SCRIPT = [
    "on run argv",
    'tell application "Terminal"',
    "set orig to missing value",
    "if (count of windows) > 0 then set orig to id of front window",
    "set t to do script (item 1 of argv)",
    "set custom title of t to (item 2 of argv)",
    "delay 0.3",                                   # let Terminal finish opening it
    "set newId to id of front window",
    "try",
    "set newId to id of (first window whose selected tab is t)",
    "end try",
    'if (item 3 of argv) is "minimized" then',
    "try",
    "set miniaturized of window id newId to true",
    "end try",
    "end if",
    "if orig is not missing value and orig is not newId then",
    "repeat 3 times",
    "try",
    "set index of window id orig to 1",
    "set frontmost of window id orig to true",
    "end try",
    "delay 0.2",
    "if id of front window is orig then exit repeat",
    "end repeat",
    "end if",
    "return newId",
    "end tell",
    "end run",
]


def _ollama_open_terminal(command, title, placement="front"):
    """Run command in a new Terminal window, leaving Musiclyse's window in front
    (placement "behind" or "minimized"; "front" for the standalone server window
    still puts Musiclyse's window back in front). Returns the new window's id, or None."""
    try:
        got = _osascript(_TERMINAL_OPEN_SCRIPT, command, title, placement)
        return int(got) if got.strip().isdigit() else None
    except Exception:
        return None


def _ollama_stop_owned():
    """Stop the Ollama Musiclyse started (and close its log window). Safe to call twice."""
    proc = _OLLAMA_OWNED.get("proc")
    if proc is not None:
        _OLLAMA_OWNED["proc"] = None
        try:
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=10)
                except Exception:
                    proc.kill()
        except Exception:
            pass
    fh = _OLLAMA_OWNED.get("log_fh")
    if fh is not None:
        _OLLAMA_OWNED["log_fh"] = None
        try:
            fh.close()
        except Exception:
            pass
    wid = _OLLAMA_OWNED.get("window_id")
    if wid is not None:
        _OLLAMA_OWNED["window_id"] = None
        try:
            time.sleep(1.5)     # the log window's own loop ends once Ollama has stopped
            _osascript(['tell application "Terminal"',
                        f"if (exists window id {int(wid)}) then close window id {int(wid)}",
                        "end tell"])
        except Exception:
            pass


def _ollama_autostart():
    """Start Ollama per the launch mode when none is running. Never touches an
    Ollama that is already running."""
    mode = _ollama_launch_mode()
    if mode == "off" or _ollama_reachable():
        return
    binary = _ollama_binary()
    if not binary:
        print(f"  (OLLAMA_LAUNCH_MODE is {mode!r}, but the ollama command wasn't found -- "
              "start Ollama yourself.)")
        return
    env = _ollama_launch_env()
    if mode == "window":
        import shlex as _shlex
        exports = " ".join(f"{k}={_shlex.quote(v)}" for k, v in
                           {**{str(a): str(b) for a, b in (OLLAMA_LAUNCH_ENV or {}).items()},
                            "OLLAMA_HOST": env.get("OLLAMA_HOST", ""),
                            "OLLAMA_DEBUG_LOG_REQUESTS": "false"}.items() if v != "")
        command = f"unset OLLAMA_DEBUG; export {exports}; {_shlex.quote(binary)} serve"
        if _ollama_open_terminal(command, "Ollama (started by Musiclyse)") is None:
            print("  (Couldn't open a Terminal window for Ollama -- start it yourself.)")
            return
        started = "Opened Ollama in its own Terminal window (it keeps running after you leave Musiclyse)."
    else:
        log_path = _ollama_log_path() if mode in ("background_log", "log_window") else None
        out = subprocess.DEVNULL
        if log_path:
            try:
                os.makedirs(os.path.dirname(log_path), exist_ok=True)
                out = open(log_path, "w", encoding="utf-8", errors="replace")
                _OLLAMA_OWNED["log_fh"] = out
            except Exception as e:
                print(f"  (Couldn't open the Ollama log {log_path}: {e} -- starting it without a log.)")
                out, log_path = subprocess.DEVNULL, None
        try:
            proc = subprocess.Popen([binary, "serve"], env=env, stdin=subprocess.DEVNULL,
                                    stdout=out, stderr=subprocess.STDOUT, start_new_session=True)
        except Exception as e:
            print(f"  (Couldn't start Ollama: {e} -- start it yourself.)")
            _ollama_stop_owned()
            return
        _OLLAMA_OWNED["proc"] = proc
        import atexit as _atexit
        _atexit.register(_ollama_stop_owned)
        try:
            import signal as _signal

            def _leave(signum, frame):
                raise SystemExit(0)
            for _sig in (getattr(_signal, "SIGHUP", None), _signal.SIGTERM):
                if _sig is not None:
                    _signal.signal(_sig, _leave)
        except Exception:
            pass
        if mode == "log_window" and log_path:
            import shlex as _shlex
            viewer = (f"tail -n +1 -f {_shlex.quote(log_path)} & T=$!; "
                      f"while kill -0 {proc.pid} 2>/dev/null; do sleep 1; done; "
                      f"kill $T 2>/dev/null; exit")
            _OLLAMA_OWNED["window_id"] = _ollama_open_terminal(viewer, "Ollama log (Musiclyse)",
                                                               _ollama_log_window_placement())
        started = "Started Ollama in the background; it stops when you leave Musiclyse."
        if mode == "log_window" and _OLLAMA_OWNED.get("window_id") is not None:
            started += (" Its log is in a separate Terminal window"
                    + (" (minimised to the Dock)" if _ollama_log_window_placement() == "minimized" else "")
                    + ", which closes with it.")
        elif log_path:
            started += f" Log: {log_path} (watch it with: tail -f {log_path})"
    for _ in range(60):
        if _ollama_reachable(timeout=1):
            break
        if _OLLAMA_OWNED.get("proc") is not None and _OLLAMA_OWNED["proc"].poll() is not None:
            print("  (Ollama stopped straight after starting"
                  + (f" -- see {_ollama_log_path()}" if mode not in ("background", "window") else "") + ".)")
            _ollama_stop_owned()
            return
        time.sleep(0.5)
    else:
        print("  (Ollama was started but hasn't answered after 30 seconds.)")
        return
    print(_colorize(f"  {started}", Ansi.YELLOW))


def check_ollama_running():
    try:
        requests.get("http://localhost:11434", timeout=2)
    except requests.exceptions.ConnectionError:
        print(
            "\nCan't reach Ollama at localhost:11434.\n"
            "Start it with 'ollama serve' (or open the Ollama app), then re-run.\n"
        )
        sys.exit(1)

def _sample_list_evenly(items, max_items):
    if max_items is None or len(items) <= max_items:
        return list(items)

    if max_items <= 1:
        return items[:1]

    step = (len(items) - 1) / float(max_items - 1)
    idxs = sorted({int(round(i * step)) for i in range(max_items)})
    return [items[i] for i in idxs if 0 <= i < len(items)]


_MIDI_JSON_LOG_RE = re.compile(r"((?:note|hit) events \((?:MIDI|rhythm)-JSON\):\s*)(\[.*\])")
# The formats actually emitted today. STEM_MIDI_COMPACT_EVENT_FORMAT and
# FULL_MIDI_TRANSCRIPTION mean the JSON form above is never produced, so the
# original pattern matched nothing and this whole function was a no-op.
_MIDI_FULL_LIST_RE = re.compile(r"(full (note|hit) list \((\d+) (notes|hits)\):\s*)(.+)$")
_MIDI_COMPACT_LOG_RE = re.compile(r"((note|hit) events \(compact\):\s*)(.+)$")

# Substrings that indicate a line may carry an event log worth compressing.
# An already-sampled list, so a log can be compressed AGAIN when one pass was
# not enough. Without this the sampling rewrite was a one-shot: the new label
# ("note list sample (40 of 1893 notes...)") matches none of the patterns
# above, so a second pass returned the text untouched and anything still over
# budget fell through to blind head/tail truncation, which removes the MIDDLE
# of the analysis -- where the per-section evidence lives.
_MIDI_SAMPLE_LIST_RE = re.compile(
    r"((note|hit) list sample \((\d+) of (\d+) (notes|hits)[^)]*\):\s*)(.+)$"
)
_MIDI_LOG_MARKERS = ("events (", "full note list (", "full hit list (",
                     "note list sample (", "hit list sample (")


def _compress_stem_midi_event_logs(text, max_events_per_log=30):
    """Reduce huge stem/MIDI event logs before sending them to Ollama.

    Samples evenly rather than head-truncating, so coverage spans the whole
    track instead of stopping partway through.

    Handles three serialisations:
      * "note/hit events (MIDI-JSON|rhythm-JSON): [...]"  - JSON array
      * "note/hit events (compact): C4@1.2-1.5, ..."      - comma-separated
      * "full note/hit list (N notes|hits): C4@1.2-1.5 (amp=0.4), ..."

    Only the first was previously matched, and it is the one format the current
    config never emits — so oversized note lists reached _truncate_text_for_ollama
    intact and had their MIDDLE removed, losing an entire span of the track.
    Even sampling is strictly better: it keeps the track's shape end to end.

    When a full list is sampled its label is REWRITTEN to say so. That matters:
    WRITER_MUSIC_RULES tells the model a "full note list" covers every
    transcribed note and is not a sample, so leaving the original label on
    reduced data would make the model trust it as complete.
    """
    if not text:
        return text
    if not any(marker in text for marker in _MIDI_LOG_MARKERS):
        return text

    out_lines = []
    for line in str(text).splitlines():
        m = _MIDI_JSON_LOG_RE.search(line)
        if m:
            try:
                arr = json.loads(m.group(2))
                if isinstance(arr, list) and len(arr) > max_events_per_log:
                    arr = _sample_list_evenly(arr, max_events_per_log)
                line = line[:m.start()] + m.group(1) + json.dumps(arr) + line[m.end():]
            except Exception:
                pass
            out_lines.append(line)
            continue

        m = _MIDI_FULL_LIST_RE.search(line)
        if m:
            try:
                kind, total_str, unit, body = m.group(2), m.group(3), m.group(4), m.group(5)
                events = [e for e in (x.strip() for x in body.split(",")) if e]
                if len(events) > max_events_per_log:
                    kept = _sample_list_evenly(events, max_events_per_log)
                    label = (
                        f"{kind} list sample ({len(kept)} of {total_str} {unit}, "
                        "evenly spaced across the track — NOT a complete list): "
                    )
                    line = line[:m.start()] + label + ", ".join(kept)
            except Exception:
                pass
            out_lines.append(line)
            continue

        m = _MIDI_SAMPLE_LIST_RE.search(line)
        if m:
            try:
                kind, orig_total, unit, body = m.group(2), m.group(4), m.group(5), m.group(6)
                events = [e for e in (x.strip() for x in body.split(",")) if e]
                if len(events) > max_events_per_log:
                    kept = _sample_list_evenly(events, max_events_per_log)
                    # Keep the ORIGINAL total in the label, not the count of
                    # the previous sample, so the writer is never told a track
                    # has fewer notes than it does.
                    label = (
                        f"{kind} list sample ({len(kept)} of {orig_total} {unit}, "
                        "evenly spaced across the track — NOT a complete list): "
                    )
                    line = line[:m.start()] + label + ", ".join(kept)
            except Exception:
                pass
            out_lines.append(line)
            continue

        m = _MIDI_COMPACT_LOG_RE.search(line)
        if m:
            try:
                body = m.group(3)
                events = [e for e in (x.strip() for x in body.split(",")) if e]
                if len(events) > max_events_per_log:
                    kept = _sample_list_evenly(events, max_events_per_log)
                    line = line[:m.start()] + m.group(1) + ", ".join(kept)
            except Exception:
                pass
            out_lines.append(line)
            continue

        out_lines.append(line)

    return "\n".join(out_lines)


def _estimate_ollama_message_chars(msg):
    try:
        content = msg.get("content") or ""
        if isinstance(content, list):
            content = json.dumps(content)

        n = len(str(content))

        imgs = msg.get("images") or []
        for img in imgs:
            try:
                # Base64 image payloads are not 1:1 with tokens, but this gives a
                # conservative size estimate for trimming.
                n += max(1000, len(str(img)) // 3)
            except Exception:
                pass

        return n
    except Exception:
        return 0


def _truncate_text_for_ollama(text, limit):
    text = str(text or "")

    if limit <= 1000:
        return text[:max(0, int(limit))]

    if len(text) <= limit:
        return text

    marker = "\n\n[... truncated for Ollama context ...]\n\n"
    head = int(limit * 0.72)
    tail = limit - head - len(marker)

    # Never exceed limit, including the small-context fallback cases.
    if tail <= 0:
        return text[:max(0, int(limit))]
    return text[:head] + marker + text[-tail:]


def _ollama_output_budget(num_ctx, max_output_tokens):
    """num_predict for one request at this context size.

    Ollama needs prompt + num_predict <= num_ctx. The fallback ladder in
    ollama_chat() steps down to 16384 and 8192, and batch-mode cover-art /
    singer-identity calls use 8192 -- all with the full 16384-token reply
    budget, which left no room at all for the prompt. The reply budget is
    now at most half the window, so every attempt has room for a prompt.
    Unchanged at 32768 and above (the normal interactive attempts).
    """
    return max(256, min(int(max_output_tokens), int(num_ctx) // 2))


def _prepare_ollama_messages(messages, num_ctx, keep_images=True, max_output_tokens=16384):
    """Build a safer copy of the message list for Ollama.

    This does not mutate the original writer_history. It:
      - keeps the system prompt but truncates it if necessary;
      - keeps the newest user message even if it is large;
      - drops older messages that would exceed the context budget;
      - compresses stem/MIDI event logs;
      - limits images to a small number, preferring newest messages.
    """
    keep_images = bool(keep_images) and OLLAMA_SUPPORTS_IMAGES

    messages = list(messages or [])
    if not messages:
        return []

    # Ollama requires prompt_tokens + num_predict <= num_ctx server-side, but
    # this budget used to be computed off the full num_ctx with no headroom
    # reserved for the reply. That let the assembled prompt keep growing as
    # if the whole window were available for history, right up until a real
    # conversation's prompt got close enough to num_ctx that adding the
    # reserved max_output_tokens pushed the actual request over the model's
    # limit -- which Ollama rejects with a 400, triggering a fallback to a
    # SMALLER num_ctx. That fallback is a full model reload (num_ctx is set
    # at load time), discarding the entire cached conversation, and the
    # smaller window then requires dropping much more history too. Budgeting
    # off the space actually left for the prompt keeps requests inside the
    # window that's already loaded, so the first (preferred, cache-friendly)
    # attempt keeps succeeding as the conversation grows instead of only
    # failing once it's already large enough for the loss to be expensive.
    effective_ctx = max(1, int(num_ctx) - int(max_output_tokens))
    budget = max(1, int(effective_ctx * HISTORY_CHAR_BUDGET_FACTOR))
    # Reserve space for a truthful warning when evidence has to be omitted.
    omission_note = ("\n\nCONTEXT LIMIT: Some earlier evidence was omitted to fit this request. "
                     "Use only evidence actually present; do not infer missing track details "
                     "from earlier assistant answers. Say when a comparison lacks evidence.")
    notice_reserve = min(len(omission_note), budget // 10)
    budget -= notice_reserve
    prepared = []
    start = 0

    if messages[0].get("role") == "system":
        sys_msg = dict(messages[0])
        # The system prompt (persona + WRITER_MUSIC_RULES) is ~36.6k chars with the
        # default persona. A former fixed 30k ceiling here truncated it on EVERY
        # request, silently cutting the middle out of the music rules (the
        # timestamp-precision, drum-grid-quoting, MIDI-handling and melody-authority
        # sections). The proportional guard is what actually matters — it stops the
        # system prompt from crowding out history on small contexts — so keep that
        # and drop the fixed cap. At OLLAMA_NUM_CTX=131072 this allows ~146k chars,
        # so the prompt now goes out whole and costs ~8.7% of the char budget.
        sys_limit = max(0, int(budget * 0.35))
        sys_msg.pop("images", None)
        sys_msg["content"] = _truncate_text_for_ollama(sys_msg.get("content"), sys_limit)

        prepared.append(sys_msg)
        budget -= _estimate_ollama_message_chars(sys_msg)
        start = 1

    def _process_message(msg):
        m = dict(msg)

        content = m.get("content") or ""
        if isinstance(content, list):
            content = json.dumps(content)

        # STABLE per-message cap: derived from num_ctx alone, never from the
        # running budget.
        #
        # This used to be `budget // 3`, where `budget` decrements as the loop
        # walks the history newest-first. The big loaded-analysis message is
        # the OLDEST, so it was processed last, against whatever budget was
        # left -- and that remainder shrank on every turn as the conversation
        # grew. The same message therefore got a different truncation point
        # (and, with adaptive compression, a different sampling level) each
        # turn, so its text changed even though its content had not.
        #
        # For a server with a prefix cache that is the worst possible property:
        # a prompt prefix is only reusable if it is byte-identical, so one
        # shifting message near the START invalidates everything after it and
        # the whole tail is re-processed every turn. On a long /loadcompare
        # session that meant ~40k tokens of prompt re-processing per message,
        # about a minute of wall time before generation could even begin, with
        # the model and machine sitting well inside their limits.
        #
        # Keying the cap to num_ctx makes each message truncate identically on
        # every turn, so the prefix stays stable and the cache does its job.
        # The budget still governs which messages are KEPT (below); it just no
        # longer reaches inside a message and reshapes it.
        max_msg_chars = min(
            MAX_MESSAGE_CHARS_FOR_OLLAMA,
            max(4000, int(int(num_ctx * HISTORY_CHAR_BUDGET_FACTOR) // 3)),
        )

        content = _compress_stem_midi_event_logs(
            str(content),
            40 if num_ctx > 16384 else 25,
        )
        # If one pass was not enough, sample the note logs harder rather than
        # letting the blind truncator take the middle out. Note lists are ~64%
        # of a saved analysis and are already a sample; the per-section groove,
        # beat-grid, melody and intensity blocks are not reconstructible and
        # must survive. Losing note resolution costs detail, losing those
        # blocks makes the model report them as absent, which is worse: on a
        # two-track /loadcompare it answered "there is no BEAT GRID for the
        # chorus" and "no MELODY PER SECTION block" about files that contained
        # seven grids and five melody blocks.
        for _level in (20, 12, 8, 5, 3):
            if len(content) <= max_msg_chars:
                break
            content = _compress_stem_midi_event_logs(str(content), _level)
        content = _truncate_text_for_ollama(content, max_msg_chars)

        m["content"] = content

        imgs = m.get("images") or []
        if keep_images:
            m["images"] = [str(img) for img in list(imgs)[:MAX_WRITER_IMAGES_PER_TURN]]
        else:
            m.pop("images", None)

        return m

    rest = messages[start:]
    true_newest_idx = len(rest) - 1 if rest else None

    # Keep the question first, then prefer recent protected evidence. Protection
    # is a priority, never permission to exceed the request's budget.
    processed = {}
    protected_indices = [i for i, msg in enumerate(rest) if id(msg) in _PROTECTED_EVIDENCE_MESSAGE_IDS]
    if true_newest_idx is not None:
        m = _process_message(rest[true_newest_idx])
        if _estimate_ollama_message_chars(m) > budget:
            m.pop("images", None)
            m["content"] = _truncate_text_for_ollama(m["content"], budget)
        processed[true_newest_idx] = m
        budget -= _estimate_ollama_message_chars(m)
    priority = list(reversed(protected_indices)) + list(range(len(rest) - 1, -1, -1))
    omitted = False
    for i in dict.fromkeys(priority):
        if i in processed:
            continue
        m = _process_message(rest[i])
        cost = _estimate_ollama_message_chars(m)
        if cost > budget:
            omitted = True
            continue
        processed[i] = m
        budget -= cost
    if omitted and true_newest_idx is not None and notice_reserve:
        processed[true_newest_idx]["content"] += omission_note[:notice_reserve]
    kept_indices = list(processed)

    kept_indices.sort()
    prepared.extend(processed[i] for i in kept_indices)

    # Enforce a global image limit across the whole request, preferring newest messages.
    total_images = 0
    for m in reversed(prepared):
        imgs = m.get("images") or []
        if not imgs:
            continue

        room = MAX_WRITER_IMAGES_PER_TURN - total_images
        if room <= 0:
            m.pop("images", None)
        else:
            m["images"] = imgs[:room]
            total_images += len(m["images"])

    return prepared


def warn_if_system_prompt_truncated(system_text, num_ctx=None, max_output_tokens=16384):
    """Print a warning if the system prompt is large enough to be truncated.

    Purely diagnostic: computes the same `sys_limit` that
    _prepare_ollama_messages() uses and reports when the prompt would not
    survive intact. Mirrors that calculation rather than sharing it, so this
    check can never affect what is actually sent. Returns True if the prompt
    would be truncated.

    This exists because truncation here is otherwise silent — a fixed 30k cap
    used to cut ~6.6k chars out of the middle of WRITER_MUSIC_RULES on every
    request (losing the timestamp-precision, drum-grid, MIDI-handling and
    melody-authority sections) with no indication it was happening.
    """
    try:
        text = str(system_text or "")
        if not text:
            return False

        ctx = int(num_ctx or OLLAMA_NUM_CTX)
        effective_ctx = max(2048, ctx - _ollama_output_budget(ctx, max_output_tokens))
        budget = int(effective_ctx * HISTORY_CHAR_BUDGET_FACTOR)
        sys_limit = max(6000, int(budget * 0.35))

        if len(text) <= sys_limit:
            return False

        print(_colorize(
            f"\n  WARNING: the system prompt is {len(text):,} chars but the limit at "
            f"num_ctx={ctx:,} is {sys_limit:,}.\n"
            f"  About {len(text) - sys_limit:,} chars will be cut from the MIDDLE of the "
            f"music rules on every request.\n"
            f"  Raise OLLAMA_NUM_CTX, or shorten the persona / WRITER_MUSIC_RULES.\n",
            Ansi.YELLOW,
        ))
        return True
    except Exception:
        return False


# Identities (via id()) of writer_history messages currently registered in
# track_evidence_message -- the message each track's full evidence block
# most recently went out in. Kept in sync at every place track_evidence_message
# itself is set/cleared/popped.
#
# Protection prioritises stable evidence for prefix-cache reuse, but both
# history compaction and request preparation enforce their limits. A missing
# evidence message is re-sent on a later /listen turn; an omitted block is
# explicitly disclosed to the writer instead of silently exceeding context.
_PROTECTED_EVIDENCE_MESSAGE_IDS = set()


def _compact_writer_history_in_place(history, *, enforce_message_limit=True):
    """Reduce Python-side memory used by writer_history.

    This is called before Ollama requests and at the start of each main loop turn.
    It removes old base64 images, compresses large stem/MIDI logs, and caps the
    number of stored messages.
    """
    try:
        if not history:
            return

        if not OLLAMA_SUPPORTS_IMAGES:
            for m in history:
                m.pop("images", None)
        else:
            # Retention is a MESSAGE-DISTANCE window, not "the last N images".
            # An earlier version kept the last MAX_STORED_IMAGES_IN_HISTORY
            # image-bearing messages, but with a single image shared once in a
            # session, that one message is simultaneously the newest AND the
            # only image-bearing message on every future turn -- so it was
            # never pruned. Some inference backends cannot restore their
            # prefix cache across a prompt containing image data, so that one
            # unpruned image forced a full prompt reprocess on every
            # subsequent turn for the rest of the session, however many turns
            # followed with no image in them at all. Expiring by how many
            # MESSAGES have arrived since (not how many other images have)
            # is what actually bounds this: after IMAGE_RETAIN_LAST_N_MESSAGES
            # more messages, the bytes go, regardless of whether a second
            # image was ever shared.
            cutoff = len(history) - int(IMAGE_RETAIN_LAST_N_MESSAGES)
            for i, m in enumerate(history):
                if "images" not in m:
                    continue

                if i < cutoff:
                    m.pop("images", None)
                else:
                    m["images"] = [
                        str(img)
                        for img in list(m.get("images") or [])[:MAX_WRITER_IMAGES_PER_TURN]
                    ]

        for m in history:
            content = m.get("content")
            # Guard must match every label _compress_stem_midi_event_logs can
            # handle. It previously tested only "events (", which the current
            # full-list format does not contain, so stored note lists were never
            # compacted in history either.
            if (
                isinstance(content, str)
                and len(content) > 20000
                and any(marker in content for marker in _MIDI_LOG_MARKERS)
            ):
                m["content"] = _compress_stem_midi_event_logs(content, 30)

        if enforce_message_limit and len(history) > MAX_WRITER_HISTORY_MESSAGES:
            system = history[0] if history and history[0].get("role") == "system" else None
            rest = history[1:] if system is not None else history[:]

            keep_count = (
                MAX_WRITER_HISTORY_MESSAGES - 1
                if system is not None
                else MAX_WRITER_HISTORY_MESSAGES
            )

            # Evidence messages get priority after the newest message; all
            # retained messages count toward the history cap. Total kept is still
            # capped at keep_count, so this does not raise how much history
            # is retained overall -- it only changes which messages fill
            # those slots.
            newest = rest[-1:] if keep_count > 0 else []
            newest_ids = {id(m) for m in newest}
            protected_rest = [m for m in rest if id(m) in _PROTECTED_EVIDENCE_MESSAGE_IDS
                              and id(m) not in newest_ids]
            slots = max(0, keep_count - len(newest))
            protected_rest = protected_rest[-slots:] if slots else []
            keep_ids = newest_ids | {id(m) for m in protected_rest}
            recent_slots = max(0, keep_count - len(keep_ids))
            unprotected_rest = [m for m in rest if id(m) not in keep_ids]
            recent_kept = unprotected_rest[-recent_slots:] if recent_slots else []
            keep_ids.update(id(m) for m in recent_kept)
            kept_rest = [m for m in rest if id(m) in keep_ids]

            history.clear()
            if system is not None:
                history.append(system)
            history.extend(kept_rest)

    except Exception as e:
        print(f"  (writer-history compaction skipped: {e})")


class _OllamaReplyInterrupted(RuntimeError):
    """dev2: a streamed chat reply stopped partway (an Ollama error line or a
    dropped connection after text was printed). Not retried, not kept."""


def _ollama_response_error(resp):
    """Extract a human-readable error from an Ollama HTTP response."""
    if resp is None:
        return "no response"

    try:
        data = resp.json()
        if isinstance(data, dict) and data.get("error"):
            return str(data["error"])
    except Exception:
        pass

    try:
        text = (resp.text or "").strip()
        if text:
            return text[:1000]
    except Exception:
        pass

    try:
        return str(resp.reason)
    except Exception:
        return "unknown Ollama error"


def _print_token_usage(usage):
    """Show last-turn and session token use against the configured context window."""
    if not usage:
        return
    # Accept either a per-turn dict from ollama_chat or the session accumulator.
    if usage is SESSION_TOKEN_USAGE or (
        isinstance(usage, dict) and "last_prompt" in usage and "prompt" in usage
        and usage is not None and "completion" in usage and "ctx" not in usage
    ):
        last_p = int(SESSION_TOKEN_USAGE.get("last_prompt") or 0)
        last_c = int(SESSION_TOKEN_USAGE.get("last_completion") or 0)
        last_ctx = int(SESSION_TOKEN_USAGE.get("last_ctx") or OLLAMA_NUM_CTX or 0)
        total = int(SESSION_TOKEN_USAGE.get("total") or 0)
    else:
        last_p = int(usage.get("prompt") or 0)
        last_c = int(usage.get("completion") or 0)
        last_ctx = int(usage.get("ctx") or OLLAMA_NUM_CTX or 0)
        total = int(SESSION_TOKEN_USAGE.get("total") or (last_p + last_c))
    print(
        f"  (tokens: this turn ~{last_p + last_c} "
        f"[prompt {last_p} + reply {last_c}] · "
        f"session ~{total} · context window {last_ctx})"
    )


# dev58: see WRITER_CASUAL_VOICE. Sentence-opening clauses that cite where a
# fact came from. Only the opener is removed, and only when a full clause
# follows it ("According to the background, they formed in 1976." -> "They
# formed in 1976."); a bare "The notes show a tempo of 120" is left alone, as
# removing its opener would leave a fragment.
_NATURAL_ATTR_STATE = {"on": True}
_ATTR_SRC = (
    r"(?:(?:the|my|our|these|those|your|this)\s+(?:private\s+|track\s+|technical\s+|background\s+|saved\s+)?"
    r"(?:notes?|background(?:\s+(?:info(?:rmation)?|notes?|article|context))?|analysis|data|measurements?|"
    r"metadata|tags|scan|article|wiki(?:pedia)?(?:\s+(?:article|entry|page))?|sources?|readings?|"
    r"evidence|report|info(?:rmation)?(?:\s+I\s+have)?|(?:file|track)\s+info)"
    r"|wikipedia|what\s+I\s+have(?:\s+here)?|what\s+I\s+can\s+see|the\s+information\s+available)"
)
_ATTR_TAIL = r"(?:\s+(?:here|on\s+(?:this|the|that)\s+(?:track|song|record|band|artist|album)))?"
_SENT_START = r"(?:(?<=^)|(?<=\n)|(?<=[.!?]\s)|(?<=[.!?]\)\s)|(?<=[.!?][\"\u201d]\s))(?P<lead>[ \t]*(?:[-*\u2022]\s+)?)"
_ATTR_OPENER_RES = (
    re.compile(_SENT_START + r"(?:according\s+to|based\s+on|going\s+(?:by|off)|judging\s+by|per|from)\s+"
               + _ATTR_SRC + _ATTR_TAIL + r"\s*,\s+(?=[\w\"'\u2018\u201c(])", re.IGNORECASE),
    re.compile(_SENT_START + _ATTR_SRC + _ATTR_TAIL
               + r"\s+(?:say|says|said|show|shows|showed|indicate|indicates|suggest|suggests|mention|"
                 r"mentions|note|notes|state|states|confirm|confirms|tell\s+me|tells\s+me|has\s+it|"
                 r"have\s+it|put\s+it)\s+that\s+(?=[\w\"'\u2018\u201c(])", re.IGNORECASE),
)
_ATTR_INLINE_RES = (
    # ", according to the notes," / " (according to Wikipedia)" inside a sentence
    (re.compile(r",\s+according\s+to\s+" + _ATTR_SRC + _ATTR_TAIL + r"\s*(?=[,.;:!?])", re.IGNORECASE), ""),
    (re.compile(r"\s+\(\s*(?:according\s+to|per|via|from)\s+" + _ATTR_SRC + _ATTR_TAIL + r"\s*\)",
                re.IGNORECASE), ""),
)


def _natural_attribution(text):
    """dev58: drop source-citing sentence openers from a writer reply (see
    WRITER_CASUAL_VOICE). Returns the text unchanged when the setting is off,
    or when the person's question was about sources."""
    if (not text or not globals().get("WRITER_CASUAL_VOICE")
            or not _NATURAL_ATTR_STATE.get("on", True)):
        return text
    out = text

    def _drop(m):
        return m.group("lead")

    for rx in _ATTR_OPENER_RES:
        out = rx.sub(_drop, out)
    for rx, rep in _ATTR_INLINE_RES:
        out = rx.sub(rep, out)
    if out != text:
        # Capitalise the word that now starts each sentence.
        out = re.sub(r"(?:(?<=^)|(?<=\n)|(?<=[.!?]\s)|(?<=[.!?]\)\s)|(?<=[.!?][\"\u201d]\s))"
                     r"([ \t]*(?:[-*\u2022]\s+)?)([\"'\u2018\u201c(]?)([a-z])",
                     lambda m: m.group(1) + m.group(2) + m.group(3).upper(), out)
    return out


def _humanize_vocal_category_language(text):
    """Rewrite internal vocal-category vocabulary into ordinary music talk.

    The writer prompt forbids saying "post-puberty male", "adolescent_male_likely"
    and similar, but the tags sit in the private notes the writer is reading, so
    smaller models echo them anyway. This is the deterministic backstop.

    Applied ONLY to the writer's user-facing reply (see _safe_ollama_chat).
    Internal passes call ollama_chat() directly and keep their raw tags, so no
    parsing or classification logic is affected by this.
    """
    if not text:
        return text
    if not globals().get("SANITIZE_VOCAL_CATEGORY_LANGUAGE", True):
        return _natural_attribution(text)

    def _match_case(original, replacement):
        if original[:1].isupper():
            return replacement[:1].upper() + replacement[1:]
        return replacement

    # Longest / most specific patterns first.
    # The bare forms only get rewritten when they are actually describing a
    # voice (or end the clause). Otherwise legitimate terminology is mangled --
    # "a prepubescent choir" is the correct term for a boys' choir and must
    # survive, while "the lead reads as post-pubertal." should not.
    _voice_ctx = (
        r"(?=\s+(?:male|female|voice|vocal|vocals|lead|leads|singer|singers|"
        r"tone|timbre|delivery|register)\b|\s*[.,;:!?]|$)"
    )
    substitutions = (
        (r"\bpost[-\s]?pub(?:erty|ertal|escent)[-\s]+male\b", "adult male"),
        (r"\bpost[-\s]?pub(?:erty|ertal|escent)\b" + _voice_ctx, "adult"),
        (r"\bpre[-\s]?pub(?:erty|ertal|escent)\b" + _voice_ctx, "childlike"),
        (r"\badolescent_male_likely\b", "young, still-changing male"),
        (r"\bpost_puberty_male\b", "adult male"),
        (r"\bchild_male_likely\b", "young male"),
        (r"\bchild_female_likely\b", "young female"),
        (r"\bchild_gender_uncertain\b", "young"),
        (r"\bfemale_teen_adult\b", "female"),
        (r"\bmixed_leads\b", "two lead singers"),
        # The same tags written with hyphens or spaces ("a female-teen-adult
        # voice", "adolescent male likely"), and the vocal pass's
        # LEAD_PROFILE spelling; also the arbitration block's name.
        (r"\bgirl[-_\s]female[-_\s]teen[-_\s]adult\b", "female"),
        (r"\bfemale[-_\s]teen[-_\s]adult\b", "female"),
        (r"\badolescent[-_\s]male[-_\s]likely\b", "young, still-changing male"),
        (r"\bchild[-_\s]male[-_\s]likely\b", "young male"),
        (r"\bchild[-_\s]female[-_\s]likely\b", "young female"),
        (r"\bchild[-_\s]gender[-_\s]uncertain\b", "young"),
        (r"\bmixed-leads\b", "two lead singers"),
        (r"\bvocal[-\s]presence arbitration\b", "vocal check"),
        (r"\badult_male\b", "adult male"),
        (r"\badult_female\b", "adult female"),
    )

    out = text
    for pattern, replacement in substitutions:
        out = re.sub(
            pattern,
            lambda m, r=replacement: _match_case(m.group(0), r),
            out,
            flags=re.IGNORECASE,
        )

    # Substitution can leave the wrong indefinite article behind ("a
    # post-puberty male" -> "a adult male", "an adolescent_male_likely" ->
    # "an young ..."). Repair only in front of the words this function
    # actually introduces, so ordinary prose is never touched.
    def _fix_article(m, correct):
        article = m.group(1)
        article = correct[:1].upper() + correct[1:] if article[:1].isupper() else correct
        return f"{article} {m.group(2)}"

    out = re.sub(
        r"\b(a)\s+(adult)\b",
        lambda m: _fix_article(m, "an"),
        out,
        flags=re.IGNORECASE,
    )
    out = re.sub(
        r"\b(an)\s+(young|female|childlike|two)\b",
        lambda m: _fix_article(m, "a"),
        out,
        flags=re.IGNORECASE,
    )
    return _natural_attribution(out)


# File names and titles too generic to blank out wherever they appear.
_BLIND_GENERIC_NAMES = frozenset(
    "mix master mastered demo track song audio music recording take version edit live remix sample "
    "test final untitled new intro outro verse chorus bridge instrumental acapella bounce export "
    "output input file unknown vocal vocals drums drum bass guitar piano keys synth other beat beats "
    "groove rhythm melody harmony tempo stem stems loop".split()
    + ["a cappella", "rough mix", "final mix", "unknown artist", "unknown title", "untitled track"]
)


def _stream_safe_cut(raw, hold=None):
    """Index up to which streamed text can be printed without splitting a
    phrase the vocal-category sanitizer may rewrite ("a post-puberty male").
    Holds back the tail and cuts two words early so an article stays with the
    word it precedes. dev58: a longer hold-back with WRITER_CASUAL_VOICE, so a
    source-citing sentence opener is complete before any of it is shown."""
    if hold is None:
        hold = 72 if globals().get("WRITER_CASUAL_VOICE") else 48
    if len(raw) <= hold:
        return 0
    cut = len(raw) - hold
    for _ in range(2):
        sp = max(raw.rfind(" ", 0, cut), raw.rfind("\n", 0, cut))
        if sp <= 0:
            return 0
        cut = sp
    # Never end a printed chunk on an article: the sanitizer may need to
    # change "an" <-> "a" once it sees the following word.
    while True:
        sp = max(raw.rfind(" ", 0, cut), raw.rfind("\n", 0, cut))
        if sp <= 0:
            return 0
        if raw[sp + 1:cut].strip().lower() in ("a", "an"):
            cut = sp
            continue
        if globals().get("WRITER_CASUAL_VOICE"):
            # dev58: keep the first 64 characters of a sentence back until all
            # of them can be seen, so a source-citing opener is judged whole.
            s0 = 0
            for m in re.finditer(r"(?:[.!?][\)\"\u201d]?\s+|\n)", raw[:cut]):
                s0 = m.end()
            if 0 < cut - s0 < 64 or (s0 == 0 and cut < 64):
                cut = s0
            if cut <= 0:
                return 0
        return cut


def ollama_chat(messages: list, num_ctx=None, keep_alive=_KEEP_ALIVE_UNSET, max_output_tokens=16384,
                 stream_output=False, stream_prefix="", stream_color=None, require_images=False,
                 options=None, enforce_message_limit=True):
    """Chat with the Ollama writer model.

    stream_output: when True, requests the reply from Ollama as it's
    generated (rather than waiting for the complete response) and writes
    each piece to stdout as it arrives -- the status is cleared the moment
    the first piece is ready, so the "Writing..."/"Thinking..." status line
    turns into the live reply at exactly the right moment. stream_prefix and
    stream_color (e.g. "\\nMusiclyse: ", Ansi.MAGENTA) are written once,
    right before that first piece. The retry/fallback cascade below is
    unaffected either way: the status-code check that decides whether to
    retry happens before any response body is read, streamed or not, so a
    failing attempt is retried exactly as before and nothing is ever printed
    for an attempt that gets abandoned. The return value (full text + usage)
    is identical to the non-streaming case either way -- this only changes
    how the text reaches the screen, not what's returned to the caller.

    keep_alive:
      unset (default) — OLLAMA_INTERACTIVE_KEEP_ALIVE ("30m" by default). This
      used to mean "omit the field, let Ollama's own server default apply" --
      observed to be 5 minutes, shorter than a normal thinking gap between
      messages, which caused the whole model process (not just its cache) to
      be killed and fully reloaded on the very next turn. See
      OLLAMA_INTERACTIVE_KEEP_ALIVE for the full explanation.
      0 / "0" — unload the model immediately after this reply (used in batch
      so MOSS-Music/Demucs/Omnizart do not compete with a resident 30B writer). This
      is unaffected by the change above: batch calls pass this explicitly.
      None — send no keep_alive at all, restoring Ollama's own server default.
      Other values are passed through to Ollama (e.g. "5m", -1).

    Musiclyse session state (writer_history, analysis caches) lives in this
    Python process and is unaffected by Ollama unload.
    """
    if keep_alive is _KEEP_ALIVE_UNSET:
        keep_alive = OLLAMA_INTERACTIVE_KEEP_ALIVE
    if num_ctx is None:
        num_ctx = OLLAMA_NUM_CTX

    # Compact the stored history in place before building the request.
    if require_images:
        # Dedicated cover request: the JPEG bytes are transport data, not
        # prompt text. Do not let the text-history budget silently discard them.
        if (len(messages) != 1 or messages[0].get("role") != "user"
                or not messages[0].get("images")):
            raise ValueError("Image-required requests need one user message with artwork")
    else:
        _compact_writer_history_in_place(messages, enforce_message_limit=enforce_message_limit)

    attempts = [
        (int(num_ctx), True),
        (min(int(num_ctx), 32768), True),
        (16384, True),
        (8192, True),
        # No-images fallback cascade. If a model has no vision support, every
        # attempt above gets rejected (observed as repeated 400s) and the loop
        # used to exhaust all four WITHOUT ever trying a plain text request,
        # ending in an unhandled RuntimeError that crashed the whole process --
        # even though the model is perfectly capable of answering once images
        # are off the table. Repeats the SAME context cascade rather than just
        # one small-context attempt: dropping images also drops a large chunk
        # of payload size (base64 image data), so the full context size may
        # well fit again once they're gone, and there's no reason to force a
        # smaller context on a text-only retry just because that's where the
        # image attempts happened to end up. A vision-capable model succeeds
        # on the very first attempt above and never reaches these at all, so
        # this changes nothing for it.
        (int(num_ctx), False),
        (min(int(num_ctx), 32768), False),
        (16384, False),
        (8192, False),
    ]

    # De-duplicate while preserving order. Same context with different image policy is allowed.
    seen = set()
    unique_attempts = []
    for attempt in attempts:
        if attempt not in seen:
            seen.add(attempt)
            unique_attempts.append(attempt)
    attempts = [a for a in unique_attempts if a[1]] if require_images else unique_attempts

    last_error = ""

    for idx, (ctx, keep_images) in enumerate(attempts):
        # dev2: set once a streamed reply has printed text; a failure after
        # that is reported instead of retried (a retry printed a second answer).
        _stream_printed = False
        try:
            # Reply budget sized to THIS attempt's window (see
            # _ollama_output_budget): the 16384 / 8192 fallbacks used to ask
            # for a 16384-token reply, leaving no room for the prompt.
            out_tokens = _ollama_output_budget(ctx, max_output_tokens)
            if require_images:
                payload_messages = [dict(messages[0], images=list(messages[0]["images"]))]
            else:
                payload_messages = _prepare_ollama_messages(
                    messages, ctx, keep_images=keep_images, max_output_tokens=out_tokens)

            payload = {
                "model": OLLAMA_MODEL,
                "messages": payload_messages,
                "stream": stream_output,
                "options": {
                    "num_ctx": ctx,
                    "num_predict": out_tokens,
                },
            }
            if keep_alive is not None:
                payload["keep_alive"] = keep_alive
            if options:
                payload["options"].update(options)       # 0.7-pre5: scan steps only (_scan_llm_options)
            if _TEST_SEED is not None:
                payload["options"]["seed"] = _TEST_SEED   # dev54 test-only; off by default

            resp = requests.post(
                OLLAMA_URL,
                json=payload,
                timeout=900,
                stream=stream_output,
            )

            has_later_attempt = idx < len(attempts) - 1
            # A later attempt without images exists and this one still has
            # them -- worth trying regardless of the exact status code, since
            # different Ollama/backend versions have been observed to signal
            # "this model has no vision support" differently (a clean 400 is
            # the common case this was originally written for, but not
            # guaranteed).
            drop_images_might_help = keep_images and any(
                not a[1] for a in attempts[idx + 1:]
            )

            if resp.status_code >= 400 and has_later_attempt and (
                resp.status_code == 400 or drop_images_might_help
            ):
                last_error = _ollama_response_error(resp)
                print(
                    f"  (Ollama returned {resp.status_code}; retrying with "
                    f"smaller context/images. Error: {last_error[:300]})"
                )
                continue

            resp.raise_for_status()

            if not stream_output:
                data = resp.json()
                content = str(data.get("message", {}).get("content") or "").strip()
                # Ollama reports per-request token counts when stream=False.
                prompt_n = int(data.get("prompt_eval_count") or 0)
                comp_n = int(data.get("eval_count") or 0)
            else:
                # Live path: this attempt already passed the status-code check
                # above, so it's the one being used -- nothing printed here
                # was ever at risk of belonging to an abandoned/retried
                # attempt. Prints exactly the same characters Ollama sends,
                # unstripped; only the returned `content` is stripped, same
                # as the non-streaming branch.
                content_parts = []
                _emitted = ""
                _emitted_raw = 0
                prompt_n = 0
                comp_n = 0
                first_piece = True
                # dev2: Ollama reports a failure after the reply has started
                # (e.g. the model process stopping) as a {"error": ...} line;
                # it used to be skipped, leaving a cut-off or empty reply that
                # was kept as if complete.
                _stream_error = None
                _done_reason = ""
                try:
                    for line in resp.iter_lines():
                        if not line:
                            continue
                        try:
                            chunk = json.loads(line)
                        except (ValueError, TypeError):
                            continue
                        if isinstance(chunk, dict) and chunk.get("error"):
                            _stream_error = str(chunk.get("error"))
                            break
                        piece = str((chunk.get("message") or {}).get("content") or "")
                        if piece:
                            if first_piece:
                                status_done(clear=True)
                                if stream_color and USE_COLOR:
                                    sys.stdout.write(stream_color)
                                if stream_prefix:
                                    sys.stdout.write(stream_prefix)
                                first_piece = False
                                _stream_printed = True
                            content_parts.append(piece)
                            _raw = "".join(content_parts)
                            _cut = _stream_safe_cut(_raw)
                            if _cut > _emitted_raw:
                                _clean = _humanize_vocal_category_language(_raw[:_cut])
                                if _clean.startswith(_emitted):
                                    sys.stdout.write(_clean[len(_emitted):])
                                    _emitted = _clean
                                else:
                                    _seg = _humanize_vocal_category_language(_raw[_emitted_raw:_cut])
                                    sys.stdout.write(_seg)
                                    _emitted += _seg
                                _emitted_raw = _cut
                            sys.stdout.flush()
                        if chunk.get("done"):
                            prompt_n = int(chunk.get("prompt_eval_count") or 0)
                            comp_n = int(chunk.get("eval_count") or 0)
                            _done_reason = str(chunk.get("done_reason") or "")
                finally:
                    if not first_piece:
                        _raw_all = "".join(content_parts)
                        _clean = _humanize_vocal_category_language(_raw_all)
                        if _clean.startswith(_emitted):
                            sys.stdout.write(_clean[len(_emitted):])
                        else:
                            sys.stdout.write(_humanize_vocal_category_language(_raw_all[_emitted_raw:]))
                        if stream_color and USE_COLOR:
                            sys.stdout.write(Ansi.RESET)
                        sys.stdout.write("\n\n")
                        sys.stdout.flush()
                        if _CHAT_DISPLAY_ARCHIVE is not None:
                            display_reply = (stream_prefix or "") + _humanize_vocal_category_language(_raw_all)
                            if stream_color and USE_COLOR:
                                display_reply = stream_color + display_reply + Ansi.RESET
                            _CHAT_DISPLAY_ARCHIVE.append(display_reply + "\n\n")
                if _stream_error is not None:
                    last_error = _stream_error
                    if not _stream_printed and idx < len(attempts) - 1:
                        print(f"  (Ollama stopped before replying; retrying with smaller context/images. "
                              f"Error: {last_error[:300]})")
                        continue
                    raise _OllamaReplyInterrupted(
                        "Ollama stopped partway through the reply"
                        + (" (the text above is incomplete)" if _stream_printed else "")
                        + f": {last_error}")
                if _done_reason == "length" and _stream_printed:
                    print("  (the reply reached its length limit and was cut off)\n")
                content = "".join(content_parts).strip()

            usage = {
                "prompt": prompt_n,
                "completion": comp_n,
                "ctx": ctx,
            }
            SESSION_TOKEN_USAGE["prompt"] = int(SESSION_TOKEN_USAGE.get("prompt") or 0) + prompt_n
            SESSION_TOKEN_USAGE["completion"] = int(SESSION_TOKEN_USAGE.get("completion") or 0) + comp_n
            SESSION_TOKEN_USAGE["total"] = (
                int(SESSION_TOKEN_USAGE.get("prompt") or 0)
                + int(SESSION_TOKEN_USAGE.get("completion") or 0)
            )
            SESSION_TOKEN_USAGE["last_prompt"] = prompt_n
            SESSION_TOKEN_USAGE["last_completion"] = comp_n
            SESSION_TOKEN_USAGE["last_ctx"] = ctx
            return content, usage

        except requests.exceptions.HTTPError as e:
            last_error = (
                _ollama_response_error(e.response)
                if e.response is not None
                else str(e)
            )
            print(f"  (Ollama request failed: {last_error[:300]})")

            # Retry on 400s, missing responses, or (regardless of status code)
            # when this attempt still had images and a later no-images attempt
            # remains — covers backends that signal "no vision support" with
            # something other than a clean 400.
            drop_images_might_help = keep_images and any(
                not a[1] for a in attempts[idx + 1:]
            )
            if idx < len(attempts) - 1 and (
                e.response is None
                or e.response.status_code == 400
                or drop_images_might_help
            ):
                continue

            raise RuntimeError(f"Ollama request failed: {last_error}") from e

        except requests.exceptions.RequestException as e:
            last_error = str(e)
            print(f"  (Ollama network error: {last_error[:300]})")

            # dev2: the connection dropped after part of a streamed reply was
            # printed. Report it rather than retrying, which printed a second,
            # different answer under the first.
            if _stream_printed:
                raise _OllamaReplyInterrupted(
                    f"Ollama connection dropped partway through the reply "
                    f"(the text above is incomplete): {last_error}") from e

            # Retry transient connection/timeout errors if possible.
            if idx < len(attempts) - 1 and (
                "Connection" in str(e) or "Timeout" in str(e)
            ):
                continue

            raise RuntimeError(f"Ollama request failed: {last_error}") from e

    raise RuntimeError(f"Ollama request failed after retries: {last_error}")


def _ollama_split_name(name):
    """("repo", "tag") for an Ollama model name, lower-cased, with the default
    registry prefix dropped; a missing tag is "" (Ollama itself reads that as
    "latest")."""
    n = str(name or "").strip().lower()
    for pre in ("registry.ollama.ai/library/", "registry.ollama.ai/"):
        if n.startswith(pre):
            n = n[len(pre):]
            break
    head, _, last = n.rpartition("/")
    if ":" in last:
        repo_last, tag = last.rsplit(":", 1)
    else:
        repo_last, tag = last, ""
    return ((head + "/" if head else "") + repo_last, tag)


def _ollama_name_matches_configured(name, strict_latest=False):
    """Does an installed/loaded Ollama model name refer to OLLAMA_MODEL?

    A tagged OLLAMA_MODEL ("model:30b-mlx") must match exactly: any
    other variant of the same model used to count as "loaded", so the unload went
    to a model that was not resident (briefly loading it) while the variant
    actually holding the memory stayed put. An untagged OLLAMA_MODEL
    ("gemma4") keeps the old any-tag rule, because which tag it means is
    ambiguous. strict_latest=True reads an untagged name the way Ollama does
    when asked to run it -- as ":latest" -- which is what "is it installed?"
    needs.
    """
    cfg_repo, cfg_tag = _ollama_split_name(OLLAMA_MODEL)
    if not cfg_repo:
        return False
    repo, tag = _ollama_split_name(name)
    if repo != cfg_repo:
        return False
    if not cfg_tag and not strict_latest:
        return True
    return (tag or "latest") == (cfg_tag or "latest")


def _warn_if_ollama_model_missing():
    """At startup, say plainly when OLLAMA_MODEL is not installed in Ollama
    (with the exact `ollama pull` to run), instead of leaving it to the first
    chat reply to fail. Silent when Ollama cannot be reached or answers
    oddly -- the chat path already explains those."""
    try:
        resp = requests.get(OLLAMA_BASE_URL + "/api/tags", timeout=3)
        if resp.status_code != 200:
            return False
        models = (resp.json() or {}).get("models")
        if not isinstance(models, list):
            return False
        names = [str(m.get("name") or m.get("model") or "") for m in models if isinstance(m, dict)]
        names = [n for n in names if n]
        if any(_ollama_name_matches_configured(n, strict_latest=True) for n in names):
            return False
        shown = ", ".join(names[:8]) + (" ..." if len(names) > 8 else "") if names else "none"
        print(_colorize(
            f"\n  WARNING: OLLAMA_MODEL is {OLLAMA_MODEL!r}, but Ollama does not have that exact "
            f"model installed.\n"
            f"  Run:  ollama pull {OLLAMA_MODEL}\n"
            f"  (or set OLLAMA_MODEL near the top of this file to one you have; installed: {shown})\n",
            Ansi.YELLOW,
        ))
        return True
    except Exception:
        return False


def _ollama_model_is_loaded():
    """Return True/False if known. Return None if Ollama's /api/ps is unavailable."""
    try:
        resp = requests.get(OLLAMA_BASE_URL + "/api/ps", timeout=5)

        # Older Ollama builds may not have /api/ps.
        if resp.status_code == 404:
            return None

        if resp.status_code != 200:
            return False

        models = (resp.json() or {}).get("models") or []

        for m in models:
            name = str(m.get("name") or m.get("model") or "")
            if not name:
                continue
            if _ollama_name_matches_configured(name):
                return True

        return False

    except Exception:
        return None


def ollama_unload_model():
    """Best-effort unload of the writer model from Ollama.

    The old implementation sent an empty /api/chat request, which can be rejected
    with 400 and therefore silently failed to unload the output LLM. This version checks
    /api/ps first when possible and uses a valid one-token chat request with
    keep_alive=0.
    """
    try:
        loaded = _ollama_model_is_loaded()

        # If we know it is not loaded, do nothing.
        if loaded is False:
            return

        # If unknown (old Ollama or network issue), still attempt once because the
        # previous behavior was to always ask. This may briefly load then unload on
        # very old servers, but modern Ollama should report via /api/ps.
        payload = {
            "model": OLLAMA_MODEL,
            "messages": [{"role": "user", "content": "Unload."}],
            "stream": False,
            "keep_alive": 0,
            "options": {"num_ctx": 512, "num_predict": 1},
        }

        requests.post(OLLAMA_URL, json=payload, timeout=30)

    except Exception:
        # Unloading is best-effort; do not crash the analysis pipeline because of it.
        pass


def _cover_reply_missing_image(text):
    """Reject model attachment refusals, not legitimate covers with no people."""
    t = str(text or "")
    return bool(re.search(
        r"(?i)(?:no|not? an?y?)\s+(?:album[/ -]*)?(?:cover\s+)?(?:artwork|image|picture|photo)"
        r"[^.\n]{0,90}\b(?:attached|provided|uploaded|received)|"
        r"(?:artwork|image|picture|photo)[^.\n]{0,60}\b(?:not|wasn't|isn't)\s+(?:attached|provided|uploaded)|"
        r"(?:please|need (?:you )?to)\s+upload\s+(?:the|an?|your)\s+(?:cover\s+)?(?:image|artwork|picture)", t))


def _cover_observation_is_useful(obs):
    if not obs or _cover_reply_missing_image(str(obs.get("raw") or "") + " " + str(obs.get("style_vibe") or "")):
        return False
    keys = ("people", "person_cues", "text_logos", "era_cues", "style_vibe")
    return any(str(obs.get(k) or "").strip() for k in keys)


def _parse_cover_observation(text):
    obs = {"raw": (text or "").strip()}
    for field in ("PEOPLE", "PERSON_CUES", "TEXT_LOGOS", "ERA_CUES", "STYLE_VIBE", "CONFIDENCE"):
        m = re.search(rf"^{field}\s*[:=]\s*(.+)$", text or "", re.MULTILINE | re.IGNORECASE)
        obs[field.lower()] = m.group(1).strip() if m else ""
    return obs


def _format_cover_observation_block(obs):
    if not obs:
        return ""

    lines = [
        "COVER ART OBSERVATIONS (structured visual evidence from the attached artwork; not direct audio proof):"
    ]

    labels = [
        ("people", "People"),
        ("person_cues", "Person cues"),
        ("text_logos", "Text/logos"),
        ("era_cues", "Era cues"),
        ("style_vibe", "Style/vibe"),
        ("confidence", "Confidence"),
    ]

    for key, label in labels:
        val = str(obs.get(key) or "").strip()
        lines.append(f"{label}: {val if val else 'unavailable'}")

    return "\n".join(lines)


def _scan_llm_options():
    """0.7-pre5 SCAN_LLM_REPEATABLE: sampling for the scan's own chat-model
    steps (cover art, singer identity). None leaves the model's defaults."""
    if not SCAN_LLM_REPEATABLE:
        return None
    return {"temperature": 0, "seed": int(SCAN_LLM_SEED)}


def describe_cover_art(cover_b64):
    """
    Return a structured dict of visual observations from an attached image.
    Returns {} on failure or if nothing useful was extracted.
    """
    if not ENABLE_COVER_ART_DESCRIPTION or not OLLAMA_SUPPORTS_IMAGES:
        return {}

    if not cover_b64 or cover_b64 == NO_COVER_SENTINEL:
        return {}

    # In batch, unload the writer immediately after this short helper so it
    # does not sit in RAM while MOSS-Music / Demucs / Omnizart run.
    _ka = None
    if globals().get("BATCH_UNLOAD_OLLAMA", True) and _is_batch_context():
        _ka = globals().get("BATCH_OLLAMA_KEEP_ALIVE", 0)

    # Ollama allocates its context buffer at model-load time, so a request
    # with a different num_ctx than the currently-resident instance forces a
    # full reload -- discarding any cached conversation state. In batch,
    # there's no ongoing conversation to protect (the model is unloaded right
    # after this call anyway via keep_alive above), so the small dedicated
    # context is a genuine, harmless memory/time saving. In an interactive
    # session, though, this call runs mid-conversation whenever a track is
    # loaded (see resolve_singer_identity's call site too) -- forcing the
    # resident large-context writer instance to reload down to 8192 for this
    # one message, then reload again back up for the very next reply, losing
    # everything cached from the conversation so far. Passing None here lets
    # ollama_chat() fall back to its normal default (OLLAMA_NUM_CTX), which
    # is what the surrounding interactive conversation already requests as
    # its first, preferred attempt -- so this call reuses the resident
    # instance instead of evicting it.
    _cover_art_ctx = COVER_ART_DESCRIPTION_NUM_CTX if _is_batch_context() else None

    try:
        text, _usage = ollama_chat([
                {
                    "role": "user",
                    "content": COVER_ART_OBSERVATION_PROMPT,
                    "images": [cover_b64],
                }
            ],
            num_ctx=_cover_art_ctx,
            keep_alive=_ka,
            require_images=True,
            max_output_tokens=4096,   # dev2: was 1024; reasoning could use it all, leaving no description
            options=_scan_llm_options(),
        )
    except Exception as e:
        print(f"  (cover art description failed: {e})")
        return {}
    finally:
        if _ka is not None:
            try:
                ollama_unload_model()
            except Exception:
                pass

    if _cover_reply_missing_image(text):
        print("  (artwork is present, but the vision model did not inspect it; no description recorded)")
        return {}
    obs = _parse_cover_observation(text)

    if not _cover_observation_is_useful(obs):
        stripped = (text or "").strip()
        if len(stripped) > 20:
            # Fallback: keep the prose as a style/vibe note rather than discarding it entirely.
            obs["style_vibe"] = stripped[:500]
            return obs
        return {}

    return obs


def _parse_singer_identity(text):
    text = _strip_md_emphasis(text)
    m = re.search(r"SINGER_IDENTITY\s*[:=]\s*[\"'<\[]?\s*([A-Za-z0-9_\- ]+)", text or "")
    if not m:
        return ""

    tag = _resolve_lead_tag_variant(m.group(1)) or _normalize_vocal_tag(m.group(1))
    tag = VOCAL_LEAD_ALIASES.get(tag, tag)

    simple_aliases = {
        "young_male": "uncertain",
        "male_lead": "post_puberty_male",
        "adult_female": "female_teen_adult",
    }
    tag = simple_aliases.get(tag, tag)

    return tag if tag in VOCAL_LEAD_TAGS else ""


