def run_demucs_stems(stem_wav_path: str, out_dir: str, shifts: int = 0):
    """Run Demucs stem separation. shifts>0 enables test-time shift
    ensembling (`--shifts N`): Demucs is run N extra times on randomly
    time-shifted copies of the input and the results are averaged, which
    measurably improves separation quality -- particularly for the weaker
    htdemucs_6s guitar/piano stems -- at roughly (N+1)x runtime. See
    DEMUCS_SHIFTS_FAST / DEMUCS_SHIFTS_DEEP."""
    base_cmd = [sys.executable, "-m", "demucs", "-n", DEMUCS_MODEL, "-o", out_dir]
    if shifts and shifts > 0:
        base_cmd += ["--shifts", str(int(shifts))]
    base_cmd += [stem_wav_path]

    attempts = [
        base_cmd + ["-d", "mps"],
        base_cmd + ["--device", "mps"],
        base_cmd,
    ]

    last_err = ""
    result = None
    for cmd in attempts:
        result = subprocess.run(cmd, capture_output=True, text=True)
        if result.returncode == 0:
            break
        last_err = result.stderr or result.stdout

    if result is None or result.returncode != 0:
        raise RuntimeError(f"Demucs failed:\n{last_err[-2000:]}")

    found = {}
    for root, dirs, files in os.walk(out_dir):
        for f in files:
            if not f.lower().endswith(".wav"):
                continue
            name = os.path.splitext(f)[0].lower()
            if name in STEM_MIDI_STEMS and name not in found:
                found[name] = os.path.join(root, f)

    return found


def _prepare_demucs_stems_for_track(
    track_path,
    stem_temp_files,
    demucs_out_dirs,
    status_fn=None,
    deep_mode=False,
):
    """Run Demucs 6s stem separation for track_path up front (if enabled)
    and return (stems_dict, out_dir).

    Used to get a clean isolated 'vocals' stem for pitch tracking -- running
    pitch estimation on the raw mix instead can lock pyin onto a sustained
    bass/pad/guitar drone rather than the singer, which is what produced
    misleadingly narrow/flat "vocal pitch" reads. The stems computed here
    are reused later for the stem MIDI report so Demucs only runs once per
    track. Returns ({}, None) on any failure or if stem separation is
    disabled; callers must fall back to whole-mix analysis in that case.

    Gated on ENABLE_STEM_MIDI OR ENABLE_VOCAL_STEM_ISOLATION (not just the
    former) so that disabling instrument MIDI transcription doesn't also
    silently disable vocal isolation for pitch tracking -- the two are
    independent concerns that happened to share one Demucs call."""
    if not (ENABLE_STEM_MIDI or ENABLE_VOCAL_STEM_ISOLATION):
        return {}, None
    try:
        if track_path in stem_temp_files:
            stem_wav = stem_temp_files[track_path]
        else:
            if status_fn:
                status_fn("Preparing stereo WAV for Demucs/MIDI...")
            stem_wav = convert_to_wav_for_stems(
                track_path,
                sample_rate=44100,
                channels=2,
                max_seconds=STEM_MIDI_MAX_SECONDS,
            )
            stem_temp_files[track_path] = stem_wav

        if status_fn:
            status_fn("Running Demucs 6s stem separation (this can be slow)...")
        out_dir = tempfile.mkdtemp(prefix="demucs_")
        demucs_out_dirs.append(out_dir)
        stems = run_demucs_stems(
            stem_wav, out_dir,
            shifts=DEMUCS_SHIFTS_DEEP if deep_mode else DEMUCS_SHIFTS_FAST,
        )
        return (stems or {}), out_dir
    except Exception as e:
        print(f"  (early stem separation for vocal pitch skipped: {e})")
        return {}, None


# (DEBUG_STEM_MIDI moved to the USER CONFIGURATION section near the top of this file.)
# False (default): silence Omnizart/TensorFlow/Keras progress bars and
# per-stem console chatter during stem MIDI. Set True only when debugging
# transcription failures.
# (SHOW_OMNIZART_LOGS moved to the USER CONFIGURATION section near the top of this file.)


def _pretty_midi_to_note_dicts(midi):
    """Convert an Omnizart pretty_midi.PrettyMIDI result (pitched stems:
    vocals/bass/guitar/piano/other) into this file's internal note-dict
    format: onset/offset in seconds, frequency in Hz, amplitude 0..1."""
    if midi is None:
        return []

    out = []
    skipped_placeholders = 0
    for instrument in midi.instruments:
        # Omnizart's vocal model (vocal/inference.py, infer_midi) writes every
        # onset it could not assign a pitch to as a fixed MIDI 77 (F5) note on a
        # separate is_drum track named "Missing Notes". Those are placeholders,
        # not sung notes: read as pitch they produced a phantom F5 "highest
        # note", impossible 2-octave leaps, and runs of F5 in sections where the
        # singer had stopped (which also made the vocal stem look active).
        if getattr(instrument, "is_drum", False) or (
            str(getattr(instrument, "name", "") or "").strip().lower() == "missing notes"
        ):
            skipped_placeholders += len(instrument.notes)
            continue
        for note in instrument.notes:
            start = float(note.start)
            end = float(note.end)
            if end <= start:
                continue
            try:
                freq = float(librosa.midi_to_hz(int(note.pitch)))
            except Exception:
                continue
            if not np.isfinite(freq) or freq <= 0:
                continue
            # Omnizart's velocities are not measurements: the vocal model writes
            # a constant 80 and the music model squeezes its activation into
            # 110-127 (inverted). The model value is kept for reference only;
            # "amplitude" is replaced with a level measured from the stem audio
            # by _attach_measured_amplitudes() before any filtering/analysis.
            amp = max(0.0, min(1.0, float(note.velocity) / 127.0))
            out.append({
                "onset": start,
                "offset": end,
                "frequency": freq,
                "amplitude": amp,
                "model_velocity": int(note.velocity),
                "duration": end - start,
            })

    if DEBUG_STEM_MIDI:
        print(f"  (stem MIDI debug: Omnizart returned {len(out)} pitched note(s); "
              f"skipped {skipped_placeholders} unpitched placeholder note(s))")

    return sorted(out, key=lambda x: x["onset"])


# The only pitches Omnizart's three-class drum model ever writes.
_OMNIZART_DRUM_CLASS_PITCHES = frozenset({35, 38, 42})


def _drum_pretty_midi_to_note_dicts(midi):
    """Convert an Omnizart drum-model pretty_midi.PrettyMIDI result into
    note dicts, each carrying an explicit 'drum_type' (kick/snare/hihat/
    tom/cymbal) rather than a pitch. Omnizart's drum model only
    distinguishes 3 classes; different builds have been seen to encode
    that either via standard GM percussion note numbers on a single
    instrument track, or via separate named instrument tracks. We check
    both, and if neither is recognised, fall back to ranking the distinct
    pitches actually present in this file low-to-high as kick/snare/hihat
    so a hit is never silently mislabeled as a single generic bucket."""
    if midi is None:
        return []

    raw = []
    distinct_pitches = set()
    for instrument in midi.instruments:
        track_name = getattr(instrument, "name", "") or ""
        name_guess = _guess_drum_type_from_name(track_name)
        # Kept alongside the coarse guess so the finer subtype can be read off
        # the track name too, not only off GM pitch numbers.
        subtype_guess = _guess_drum_subtype_from_name(track_name)
        for note in instrument.notes:
            start = float(note.start)
            end = float(note.end)
            if end <= start:
                end = start + 0.05
            pitch = int(note.pitch)
            raw.append((start, end, pitch, int(note.velocity), name_guess, subtype_guess))
            distinct_pitches.add(pitch)

    if not raw:
        return []

    # Fallback only used when a hit's pitch isn't a recognised GM
    # percussion number AND its instrument track wasn't named.
    sorted_pitches = sorted(distinct_pitches)
    rank_labels = ["kick", "snare", "hihat"]
    pitch_rank_type = {}
    for i, p in enumerate(sorted_pitches):
        bucket = min(i * len(rank_labels) // max(len(sorted_pitches), 1), len(rank_labels) - 1)
        pitch_rank_type[p] = rank_labels[bucket]

    # Omnizart's drum model (drum/inference.py) has exactly three outputs and
    # writes them as fixed GM pitches: 35 (kick), 38 (snare), 42 (hi-hat, which
    # also absorbs every cymbal). Those pitches are class IDs, not instrument
    # identifications, so mapping them through GM_DRUM_PITCH_SUBTYPE reported
    # "acoustic bass drum / acoustic snare / closed hi-hat" and "hi-hat closed
    # throughout" for every track ever scanned. Only attach a finer subtype when
    # the transcription actually distinguishes more than those three classes.
    three_class_only = bool(distinct_pitches) and distinct_pitches <= _OMNIZART_DRUM_CLASS_PITCHES

    out = []
    for start, end, pitch, velocity, name_guess, subtype_guess in raw:
        drum_type = name_guess or GM_DRUM_PITCH_TYPE.get(pitch) or pitch_rank_type.get(pitch, "other")
        # Finer class, when the pitch or track name identifies one. Carried as
        # a separate field so every existing consumer that groups on
        # drum_type keeps seeing exactly the buckets it saw before.
        subtype = subtype_guess or (None if three_class_only else GM_DRUM_PITCH_SUBTYPE.get(pitch))
        # Model velocity is a constant (Omnizart writes 100 for every hit); it is
        # kept for reference and replaced by a level measured from the drums
        # stem in _attach_measured_amplitudes().
        amp = max(0.0, min(1.0, float(velocity) / 127.0))
        entry = {
            "onset": start,
            "offset": end,
            "duration": max(end - start, 0.01),
            "amplitude": amp,
            "model_velocity": int(velocity),
            "drum_type": drum_type,
        }
        if subtype:
            entry["drum_subtype"] = subtype
        out.append(entry)

    if DEBUG_STEM_MIDI:
        print(f"  (stem MIDI debug: Omnizart drum model returned {len(out)} hit(s); "
              f"distinct raw pitches={sorted_pitches})")

    return sorted(out, key=lambda x: x["onset"])

def _drum_band_label(freq_hz):
    """Very rough register guess from spectral centroid — not a real pitch."""
    if freq_hz < 150:
        return "low (kick-like)"
    if freq_hz < 800:
        return "mid (snare/tom-like)"
    return "high (hihat/cymbal-like)"


def transcribe_drums_with_onsets(stem_path: str, preset: dict):
    """
    Multi-band onset detection for drums.
    Separate low / mid / high bands so kicks, snares, and hats are not
    competing for one global peak list. 'frequency' is still a band centre
    proxy used only for register labelling — not a musical pitch.
    """
    y, sr = librosa.load(stem_path, sr=None, mono=True)
    if y.size == 0:
        return []

    hop_length = 256
    min_amplitude = float(preset.get("min_amplitude", 0.015))
    min_note_length = float(preset.get("min_note_length", 0.01))
    onset_threshold = float(preset.get("onset_threshold", 0.04))

    # Band-limited onset envelopes approximate kick / snare / hat registers.
    bands = [
        ("low",  30,   150,  80.0),    # kick-like
        ("mid",  150,  800,  300.0),   # snare/tom-like
        ("high", 5000, 12000, 8000.0), # hihat/cymbal-like
    ]

    all_notes = []
    for _name, fmin, fmax, proxy_hz in bands:
        try:
            env = librosa.onset.onset_strength(
                y=y, sr=sr, hop_length=hop_length,
                fmin=fmin, fmax=fmax, aggregate=np.mean,
            )
        except TypeError:
            # Preserve band separation on older APIs too; never assign the
            # same full-band envelope to kick, snare AND hat.
            band_y = _band_filter(y, sr, fmin, fmax)
            env = librosa.onset.onset_strength(
                y=band_y, sr=sr, hop_length=hop_length, aggregate=np.mean,
            )

        max_env = float(np.max(env)) if env.size else 0.0
        if max_env <= 0:
            continue

        env_norm = env / max_env
        frames = librosa.onset.onset_detect(
            onset_envelope=env_norm,
            sr=sr,
            hop_length=hop_length,
            backtrack=True,
            delta=onset_threshold,
            wait=1,
            pre_max=3,
            post_max=3,
            pre_avg=3,
            post_avg=3,
        )
        if len(frames) == 0:
            frames = librosa.onset.onset_detect(
                onset_envelope=env_norm,
                sr=sr,
                hop_length=hop_length,
                backtrack=True,
                delta=max(0.02, onset_threshold * 0.5),
                wait=1,
            )
        if len(frames) == 0:
            continue

        times = librosa.frames_to_time(frames, sr=sr, hop_length=hop_length)
        for idx, frame in enumerate(frames):
            frame_i = int(min(int(frame), len(env) - 1))
            amp = float(env[frame_i]) / max_env
            if amp < min_amplitude:
                continue
            onset_t = float(times[idx])
            next_t = float(times[idx + 1]) if idx + 1 < len(times) else onset_t + 0.10
            dur = max(min_note_length, min(next_t - onset_t, 0.20))
            all_notes.append({
                "onset": onset_t,
                "offset": onset_t + dur,
                "frequency": proxy_hz,
                "amplitude": amp,
                "duration": dur,
            })

    if not all_notes:
        return []

    # Retain the legacy selection as provenance ONLY, for stable structure
    # and tempo evidence. All simultaneous bands still reach the drum report.
    legacy = []
    ordered = sorted(all_notes, key=lambda n: n["onset"])
    for n in ordered:
        if legacy and n["onset"] - legacy[-1]["onset"] < 0.02:
            if n["amplitude"] > legacy[-1]["amplitude"]:
                legacy[-1] = n
        else:
            legacy.append(n)
    keep_ids = {id(n) for n in legacy}
    # Backtracking may return the exact same onset twice in one band.
    # Only deduplicate that event, never a simultaneous different band.
    distinct = {}
    for n in ordered:
        n["structure_legacy_keep"] = id(n) in keep_ids
        key = (n["frequency"], n["onset"])
        old = distinct.get(key)
        if old is None or n["amplitude"] > old["amplitude"]:
            distinct[key] = n
        elif n["structure_legacy_keep"]:
            old["structure_legacy_keep"] = True
    return sorted(distinct.values(), key=lambda n: n["onset"])


_OMNIZART_OUTPUT_DIRS = []  # temp dirs Omnizart writes its .mid side-output into; cleaned up in main()'s finally block
_OMNIZART_MODEL_USED = {}   # stem -> Omnizart model/mode that produced its notes (for the report)

_OMNIZART_PREFETCH = {"proc": None, "out": None, "results": None, "paths": {}, "t0": None}


def _start_omnizart_prefetch(stems):
    """dev55: transcribe the non-silent stems in a separate process (see
    PARALLEL_ANALYSIS / OMNIZART_PREFETCH_PROCESS). Returns True when started."""
    if not (PARALLEL_ANALYSIS and OMNIZART_PREFETCH_PROCESS and ENABLE_STEM_MIDI and stems):
        return False
    try:
        script = os.path.abspath(__file__)
    except Exception:
        return False
    if not os.path.exists(script):
        return False
    todo = []
    for stem in STEM_MIDI_STEMS:
        path = stems.get(stem)
        if not path or not os.path.exists(path):
            continue
        try:
            preset = STEM_MIDI_PRESETS[stem]
            empty_rms = float(preset.get("empty_rms_threshold", 0) or 0)
            if empty_rms > 0:
                rms, _ = _stem_rms_by_section(path, None)
                if rms < empty_rms:
                    continue        # summaries skip it too
        except Exception:
            pass
        todo.append({"stem": stem, "path": os.path.abspath(path)})
    if not todo:
        return False
    try:
        tmpd = tempfile.mkdtemp(prefix="omnizart_prefetch_")
        _OMNIZART_OUTPUT_DIRS.append(tmpd)
        jin = os.path.join(tmpd, "in.json")
        jout = os.path.join(tmpd, "out.json")
        with open(jin, "w", encoding="utf-8") as f:
            json.dump({"stems": todo}, f)
        env = dict(os.environ)
        env["MUSICLYSE_OMNIZART_CHILD"] = "1"
        proc = subprocess.Popen(
            [sys.executable, script, "--omnizart-prefetch", jin, jout],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, env=env,
            cwd=os.getcwd(),
        )
    except Exception:
        return False
    _OMNIZART_PREFETCH.update(proc=proc, out=jout, results=None, t0=time.perf_counter(),
                              paths={(d["path"], d["stem"]) for d in todo})
    return True


def _omnizart_prefetch_results():
    """Wait for the prefetch process (once) and return its results dict
    {(path, stem): (notes, model_used)} -- empty when it failed."""
    st = _OMNIZART_PREFETCH
    if st.get("results") is not None:
        return st["results"]
    proc = st.get("proc")
    res = {}
    if proc is not None:
        try:
            proc.wait(timeout=float(OMNIZART_PREFETCH_TIMEOUT_S))
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
        try:
            if st.get("t0") is not None:
                _STAGE_LOG.append(("[background, overlapped] Omnizart stem transcription (separate process)",
                                   time.perf_counter() - st["t0"]))
        except Exception:
            pass
        try:
            if proc.returncode == 0 and st.get("out") and os.path.exists(st["out"]):
                with open(st["out"], "r", encoding="utf-8") as f:
                    data = json.load(f)
                for item in data.get("results") or []:
                    res[(item["path"], item["stem"])] = (item.get("notes") or [], item.get("model_used"))
        except Exception:
            res = {}
    st["results"] = res
    st["proc"] = None
    try:
        if st.get("out"):
            shutil.rmtree(os.path.dirname(st["out"]), ignore_errors=True)
    except Exception:
        pass
    return res


def _clear_omnizart_prefetch():
    proc = _OMNIZART_PREFETCH.get("proc")
    if proc is not None:
        try:
            if proc.poll() is None:
                proc.kill()
        except Exception:
            pass
    _OMNIZART_PREFETCH.update(proc=None, out=None, results=None, paths={}, t0=None)


def _omnizart_prefetch_child(in_json, out_json):
    """Entry for `--omnizart-prefetch in.json out.json` (see
    _start_omnizart_prefetch): the same omnizart_transcribe() as the in-order
    run, one stem after another, results written as JSON."""
    with open(in_json, "r", encoding="utf-8") as f:
        todo = (json.load(f) or {}).get("stems") or []
    results = []
    for item in todo:
        stem, path = item["stem"], item["path"]
        try:
            notes = _omnizart_transcribe_impl(path, stem, STEM_MIDI_PRESETS.get(stem, {}))
        except Exception:
            notes = []
        results.append({"stem": stem, "path": path, "notes": notes or [],
                        "model_used": _OMNIZART_MODEL_USED.get(stem)})
    tmp = out_json + ".part"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"results": results}, f, default=float)
    os.replace(tmp, out_json)
    for d in list(_OMNIZART_OUTPUT_DIRS):      # this process's own scratch dirs
        try:
            shutil.rmtree(d, ignore_errors=True)
        except Exception:
            pass


def omnizart_transcribe(stem_path: str, stem: str, preset: dict):
    """Transcribe one separated stem with Omnizart (list of note dicts, or []
    on failure). dev55: uses the background process's result for this stem
    when it produced one; otherwise transcribes here, exactly as before."""
    key = (os.path.abspath(str(stem_path)), stem)
    if key in (_OMNIZART_PREFETCH.get("paths") or ()):
        got = _omnizart_prefetch_results().get(key)
        if got is not None and got[0]:
            if got[1] is not None:
                _OMNIZART_MODEL_USED[stem] = got[1]
            return [dict(n) for n in got[0]]
    return _omnizart_transcribe_impl(stem_path, stem, preset)


def _omnizart_transcribe_impl(stem_path: str, stem: str, preset: dict):
    """
    Transcribe one separated stem with Omnizart.
    Returns a list of note dicts (or empty list on any failure).
    """
    import pretty_midi
    import tempfile

    try:
        apps = _get_omnizart()
    except Exception:
        return []

    app_key = OMNIZART_STEM_APP.get(stem, "music")
    try:
        app = apps[app_key]
    except Exception:
        return []

    out_dir = tempfile.mkdtemp(prefix="omnizart_")
    _OMNIZART_OUTPUT_DIRS.append(out_dir)

    def _load_midi_candidate(candidate):
        if candidate is None:
            return None
        if isinstance(candidate, pretty_midi.PrettyMIDI):
            return candidate
        if isinstance(candidate, (str, os.PathLike)):
            candidate = os.fspath(candidate)
            if os.path.isfile(candidate):
                try:
                    return pretty_midi.PrettyMIDI(candidate)
                except Exception:
                    return None
        return None

    # Run Omnizart. The music app defaults to its PIANO checkpoint when no
    # model is named; OMNIZART_MUSIC_MODEL_BY_STEM can name another mode
    # (e.g. "Pop") per stem. A named mode that fails to load falls back to the
    # default call, so a missing checkpoint never costs the stem its notes.
    result = None
    model_mode = None
    if app_key == "music":
        model_mode = (globals().get("OMNIZART_MUSIC_MODEL_BY_STEM") or {}).get(stem)
    attempts = []
    if model_mode:
        attempts.append({"model_path": model_mode, "output": out_dir})
    attempts += [{"output": out_dir}, {}]
    used_mode = None
    with quiet_stdout():
        for kwargs in attempts:
            try:
                result = app.transcribe(stem_path, **kwargs)
                used_mode = kwargs.get("model_path")
                break
            except TypeError:
                continue
            except Exception:
                if kwargs.get("model_path"):
                    continue
                return []
    _OMNIZART_MODEL_USED[stem] = used_mode or ("default (Piano)" if app_key == "music" else app_key)

    # Try to get the MIDI object
    midi_obj = _load_midi_candidate(result)

    if midi_obj is None:
        # Search the output directory for the side-output Omnizart wrote.
        # Prefer the newest MIDI file: Omnizart may leave auxiliary files.
        candidates = []
        for root, _, files in os.walk(out_dir):
            for filename in files:
                if filename.lower().endswith((".mid", ".midi")):
                    candidates.append(os.path.join(root, filename))
        candidates.sort(key=lambda p: os.path.getmtime(p), reverse=True)
        for candidate in candidates:
            midi_obj = _load_midi_candidate(candidate)
            if midi_obj is not None:
                break

    if midi_obj is None:
        return []

    try:
        if stem == "drums":
            notes = _drum_pretty_midi_to_note_dicts(midi_obj)
        else:
            notes = _pretty_midi_to_note_dicts(midi_obj)
        return notes if notes is not None else []
    except Exception:
        return []

def _rms_envelope(x, frame=1024, hop=256):
    """Centred frame-RMS envelope, one value per `hop` samples, computed from
    per-hop block energies. Memory stays O(len(x)) -- unlike an STFT or
    librosa.feature.rms, which materialise frame x n_frames arrays (hundreds of
    MB for a six-minute stem at 44.1 kHz)."""
    x = np.asarray(x, dtype=np.float32)
    if x.size == 0:
        return np.zeros(0)
    n_blocks = int(np.ceil(x.size / float(hop)))
    xb = np.pad(x, (0, n_blocks * hop - x.size)).reshape(n_blocks, hop)
    e = np.einsum("ij,ij->i", xb, xb, dtype=np.float64)
    k = max(1, int(round(frame / float(hop))))
    c = np.concatenate([[0.0], np.cumsum(e)])
    idx = np.arange(n_blocks)
    a = np.clip(idx - k // 2, 0, n_blocks)
    b = np.clip(idx - k // 2 + k, 0, n_blocks)
    return np.sqrt((c[b] - c[a]) / (np.maximum(b - a, 1) * float(hop)))


def _band_filter(y, sr, lo, hi):
    """4th-order Butterworth band-pass (or low/high-pass at the edges), float32,
    streaming. Used for level/onset envelopes, where a few ms of filter delay is
    irrelevant."""
    from scipy.signal import butter, sosfilt
    nyq = sr / 2.0
    lo = float(lo or 0.0)
    hi = min(float(hi or nyq), nyq * 0.95)
    if lo <= 0 and hi >= nyq * 0.95:
        return np.asarray(y, dtype=np.float32)
    if lo <= 0:
        sos = butter(4, hi, btype="low", fs=sr, output="sos")
    elif hi >= nyq * 0.95:
        sos = butter(4, lo, btype="high", fs=sr, output="sos")
    else:
        sos = butter(4, [lo, hi], btype="band", fs=sr, output="sos")
    return sosfilt(sos, np.asarray(y, dtype=np.float32)).astype(np.float32)


def _attach_measured_amplitudes(notes, stem_path, stem):
    """Give every note/hit an amplitude MEASURED from the separated stem.

    Omnizart does not estimate loudness: drums are always velocity 100, vocals
    always 80, and the music model maps its activation into 110-127 (inverted).
    Everything that read "amplitude" -- the velocity-spread / programmed-vs-
    played line, the per-stem amplitude floor that is meant to drop low-level
    bleed, and the saved note data -- was therefore reading a constant.

    Level = peak band-limited RMS in a short window after the onset (50 ms for
    drum hits, the note itself up to 1 s for pitched notes), relative to the 99th-percentile
    frame level of the same band in the same stem, so 1.0 is "as loud as this
    part gets" and 0.06 is ~24 dB below that. Drum hits are measured inside
    their own drum's frequency band so a kick is not credited with the hat on
    top of it. The model value stays in "model_velocity". Notes are modified in
    place and also returned. On any failure the notes are returned untouched.
    """
    if not notes or not stem_path or not os.path.exists(str(stem_path)):
        return notes
    try:
        y, sr = librosa.load(str(stem_path), sr=None, mono=True)
    except Exception:
        return notes
    if y is None or y.size < 4096:
        return notes
    hop = 256
    is_drums = (stem == "drums")
    cache = {}
    # Absolute (time-domain) level as well: a stem that is separation residue
    # throughout is loud RELATIVE to itself, so only an absolute floor can tell
    # its "notes" from playing (see STEM_NOTE_MIN_ABS_RMS). Drums never go
    # through that filter, so only pitched stems need it.
    abs_env = _rms_envelope(y, frame=2048, hop=hop) if not is_drums else np.zeros(0)

    def _env(key):
        if key not in cache:
            if is_drums:
                lo, hi = _DRUM_ANALYSIS_BANDS.get(key, (30.0, 16000.0))
                env = _rms_envelope(_band_filter(y, sr, lo, hi), frame=1024, hop=hop)
            else:
                env = abs_env
            nz = env[env > 0]
            ref = float(np.percentile(nz, 99)) if nz.size else 0.0
            cache[key] = (env, ref)
        return cache[key]

    for n in notes:
        try:
            onset = float(n["onset"])
        except (KeyError, TypeError, ValueError):
            continue
        key = (n.get("drum_type") or "other") if is_drums else "_all"
        env, ref = _env(key)
        if ref <= 0 or env.size == 0:
            continue
        if is_drums:
            win = 0.05
        else:
            # Over the note itself (up to 1 s), not just its first instants:
            # a slow-attack note (string swell, pad) is still rising 150 ms in
            # and would read far quieter than it gets.
            win = min(max(float(n.get("duration") or 0.0), 0.03), 1.0)
        a = int(max(0.0, onset) * sr / hop)
        b = max(a + 1, int((onset + win) * sr / hop) + 1)
        if a >= env.size:
            continue
        lvl = float(np.max(env[a:min(b, env.size)]))
        n["amplitude"] = round(float(min(1.0, lvl / ref)), 4)
        n["amplitude_source"] = "stem audio"
        if a < abs_env.size:
            n["abs_rms"] = round(float(np.max(abs_env[a:min(b, abs_env.size)])), 6)
    return notes


def _refine_drum_onsets_from_audio(hits, stem_path, max_shift_s=0.045):
    """Move Omnizart drum hits from its own beat grid onto the real transients.

    Omnizart's drum model does not output onset times. It tracks beats with
    madmom, divides each beat into eight "mini-beats" (32nd notes), classifies
    each mini-beat, and writes every hit exactly ON a mini-beat
    (drum/inference.py, feature/beat_for_drum.py). Every hit time the groove
    code saw was therefore quantised to another beat tracker's grid, so
    grid-lock, swing and micro-timing were measuring madmom, not the drummer
    (a 2:1 swing cannot even be represented on a 32nd grid).

    For each hit, look within +/- max_shift_s for the strongest onset in that
    drum's own frequency band in the drums stem and move the hit there. A hit
    with no clear transient nearby keeps its grid time. The grid time is kept
    in "grid_onset". Returns (hits, n_moved). Never raises.
    """
    if not hits or not stem_path or not os.path.exists(str(stem_path)):
        return hits, 0
    try:
        y, sr = librosa.load(str(stem_path), sr=None, mono=True)
    except Exception:
        return hits, 0
    if y is None or y.size < 4096:
        return hits, 0
    hop = 64
    flux_cache = {}

    def _flux(dtype):
        """Onset function for one drum: rise of the band's log envelope."""
        if dtype not in flux_cache:
            lo, hi = _DRUM_ANALYSIS_BANDS.get(dtype, (30.0, 16000.0))
            env = _rms_envelope(_band_filter(y, sr, lo, hi), frame=256, hop=hop)
            loge = np.log1p(1000.0 * env / (float(np.max(env)) + 1e-12))
            fl = np.concatenate([[0.0], np.maximum(0.0, np.diff(loge))])
            base = float(np.median(fl)) + 1e-9
            flux_cache[dtype] = (fl, base)
        return flux_cache[dtype]

    try:
        from scipy.signal import hilbert as _hilbert
    except Exception:
        _hilbert = None

    def _attack_time(dtype, t_coarse):
        """Pin the attack in the time domain. Spectral flux finds the right
        transient but, being frame-based, leads the true onset by several ms
        (the analysis window starts filling before the frame centre). The
        band-limited envelope's 50%-of-peak crossing does not have that bias."""
        if _hilbert is None:
            return None
        lo, hi = _DRUM_ANALYSIS_BANDS.get(dtype, (30.0, 16000.0))
        a = int(max(0.0, t_coarse - 0.015) * sr)
        b = int((t_coarse + 0.040) * sr)
        if b - a < 64 or a >= y.size:
            return None
        xb = _drum_band_limit(y[a:min(b, y.size)], sr, lo, hi)
        env = np.abs(_hilbert(xb))
        w = max(1, int(sr * 0.0005))
        if w > 1:
            env = np.convolve(env, np.ones(w) / w, mode="same")
        m = int(np.argmax(env))
        if env[m] <= 0:
            return None
        below = np.flatnonzero(env[:m + 1] < 0.5 * env[m])
        i = int(below[-1]) + 1 if below.size else 0
        return (a + i) / float(sr)

    moved = 0
    for h in hits:
        dtype = h.get("drum_type")
        if dtype not in _DRUM_ANALYSIS_BANDS:
            continue
        try:
            t = float(h["onset"])
        except (KeyError, TypeError, ValueError):
            continue
        fl, base = _flux(dtype)
        a = int(max(0.0, t - max_shift_s) * sr / hop)
        b = int((t + max_shift_s) * sr / hop) + 1
        if a >= fl.size or b <= a:
            continue
        seg = fl[a:min(b, fl.size)]
        k = int(np.argmax(seg))
        if float(seg[k]) < 4.0 * base:
            continue                      # no clear transient: keep grid time
        coarse = (a + k) * hop / float(sr)
        fine = _attack_time(dtype, coarse)
        new_t = fine if (fine is not None and abs(fine - t) <= max_shift_s + 0.02) else coarse
        new_t = max(0.0, new_t)
        if abs(new_t - t) > 1e-4:
            h.setdefault("grid_onset", t)
            dur = float(h.get("offset", t) or t) - t
            h["onset"] = round(new_t, 4)
            h["offset"] = round(new_t + max(dur, 0.01), 4)
            moved += 1
        h["onset_source"] = "drum-stem transient"
    return hits, moved


def _stem_rms(path, max_seconds=None):
    """Root-mean-square energy of a stem.

    IMPORTANT: default is the WHOLE file, not a truncated read. This used to
    default to the first 60s only, which meant the "stem energy" figure (and
    everything derived from it -- the activity/prominence label, the
    cross-stem prominence ranking) was silently measuring only the intro of
    the track while the surrounding report text claimed it covered the
    whole song. Pass max_seconds explicitly only where a fast partial
    estimate is genuinely acceptable.
    """
    try:
        y, _sr = librosa.load(path, sr=None, mono=True, duration=max_seconds)
        if y.size == 0:
            return 0.0
        return float(np.sqrt(np.mean(y ** 2)))
    except Exception:
        return 0.0


def _stem_rms_by_section(path, sections=None):
    """Load a stem once and return (whole_track_rms, per_section_rms_list).

    per_section_rms_list is a list of {"name","start","end","rms"} dicts, one
    per structural section, computed from the SAME audio read used for the
    whole-track figure (so this costs nothing extra beyond one file load).
    Used so the writer can describe an instrument's intensity in different
    parts of the song ("the guitar barely registers in the verse but comes
    in hard for the chorus") instead of only a single track-wide number.
    """
    try:
        y, sr = librosa.load(path, sr=None, mono=True)
    except Exception:
        return 0.0, []
    if y.size == 0:
        return 0.0, []
    whole_rms = float(np.sqrt(np.mean(y ** 2)))
    section_rms = []
    if sections:
        for sec in sections:
            try:
                start = max(0.0, float(sec["start"]))
                end = float(sec["end"])
            except Exception:
                continue
            i0 = int(start * sr)
            i1 = max(i0 + 1, int(end * sr))
            seg = y[i0:i1]
            sec_rms = float(np.sqrt(np.mean(seg ** 2))) if seg.size else 0.0
            section_rms.append({
                "name": sec.get("name", "?"),
                "start": start,
                "end": end,
                "rms": sec_rms,
            })
    return whole_rms, section_rms


def _section_intensity_label(rms, ref_min, ref_max):
    """Map a section's RMS to a relative intensity band, scaled against THIS
    STEM's own quietest/loudest section (not an absolute loudness scale).
    That matters because an instrument that's naturally soft after stem
    separation (e.g. a clean rhythm guitar under a loud vocal) should still
    read as "prominent" in the section where it's most forward, rather than
    always reading "quiet" against some fixed threshold that only really
    suits drums or bass."""
    if ref_max <= 0 or (ref_max - ref_min) < 1e-6:
        return "steady"
    # Measured in dB below this stem's loudest section rather than as a linear
    # fraction of the min-max range. The linear version stretched ANY spread to
    # the full scale, so a part that varied by barely 1 dB was reported as
    # "quiet / mostly absent" in one section and "peak intensity" in another --
    # a dramatic arrangement change that was never played. A spread under
    # ~2 dB is now reported as steady, and every label corresponds to a real
    # level difference a listener would hear.
    floor = 1e-9
    spread_db = 20.0 * np.log10(max(ref_max, floor) / max(ref_min, floor))
    if spread_db < 2.0:
        return "steady"
    below_db = 20.0 * np.log10(max(ref_max, floor) / max(float(rms), floor))
    if below_db <= 1.5:
        return "peak intensity"
    elif below_db <= 3.5:
        return "prominent"
    elif below_db <= 7.0:
        return "moderate"
    elif below_db <= 14.0:
        return "present but restrained"
    else:
        return "quiet / mostly absent"


def _format_intensity_by_section(stem, section_rms_list, section_totals=None, whole_rel_db=None):
    """Render the per-section relative-intensity block for one stem.

    `section_totals` (optional): combined RMS of all stems per section (the mix
    level there); a section where this stem is SECTION_RESIDUE_BELOW_TOTAL_DB
    or more below it is "not playing". `whole_rel_db` (optional): the stem's
    whole-track level relative to all stems, used to say when the whole stem is
    only a minor or residual part.
    """
    if not section_rms_list:
        return ""
    floor = float(SECTION_AUDIBLE_MIN_RMS)
    loudest = max(float(s["rms"]) for s in section_rms_list)
    if loudest < floor:
        return (
            f"INTENSITY BY SECTION ({stem} stem): near-silent in every section (never above "
            f"about -54 dBFS) -- this stem carries only separation residue here, so treat the "
            f"instrument as not playing; do not describe it building, peaking or dropping out."
        )

    totals = list(section_totals or [])

    def _not_playing(r, i=None):
        if float(r) < floor and float(r) < loudest * 10.0 ** (-30.0 / 20.0):
            return True
        if i is not None and i < len(totals) and totals[i] > 0:
            return float(r) < totals[i] * 10.0 ** (-float(SECTION_RESIDUE_BELOW_TOTAL_DB) / 20.0)
        return False

    audible = [s["rms"] for i, s in enumerate(section_rms_list) if not _not_playing(s["rms"], i)]
    if not audible:
        return (
            f"INTENSITY BY SECTION ({stem} stem): at least {SECTION_RESIDUE_BELOW_TOTAL_DB:.0f} dB "
            f"below the rest of the mix in every section -- separation residue, so treat the "
            f"instrument as not playing; do not describe it building, peaking or dropping out."
        )
    ref_min, ref_max = min(audible), max(audible)
    lines = [
        f"INTENSITY BY SECTION ({stem} stem energy relative to its own "
        "loudest section in this track, in real level steps; 'steady' means it "
        "stays at about the same level throughout; 'not playing' means the stem is "
        "below an absolute audibility floor there -- use this for how the "
        "instrument's presence rises/falls across the song, not for "
        "absolute loudness or cross-instrument comparison):"
    ]
    if whole_rel_db is not None and whole_rel_db <= -20.0:
        lines[0] = lines[0][:-1] + (
            f" NOTE: overall this stem sits {abs(whole_rel_db):.0f} dB below the combined stems, "
            "so even its 'peak' sections are a minor part of the mix):"
        )
    for i, s in enumerate(section_rms_list):
        if _not_playing(s["rms"], i):
            label = "not playing (below audibility floor)"
        else:
            label = _section_intensity_label(s["rms"], ref_min, ref_max)
        lines.append(
            f"  {s['name']} ({_seconds_to_mmss(s['start'])}-{_seconds_to_mmss(s['end'])}): {label}"
        )
    return "\n".join(lines)


def _mmss_to_seconds(s):
    """Parse a 'M:SS', 'MM:SS', or 'H:MM:SS' timestamp into seconds. Returns
    None if it doesn't look like a timestamp."""
    if not s:
        return None
    parts = s.strip().split(":")
    if not (2 <= len(parts) <= 3):
        return None
    try:
        parts = [float(p) for p in parts]
    except ValueError:
        return None
    seconds = 0.0
    for p in parts:
        seconds = seconds * 60.0 + p
    return seconds


_STRUCTURE_FIELD_RE = re.compile(
    r"(?i:STRUCTURE)\s*[=:]\s*(.*?)(?=\n\s*[A-Z][A-Z0-9_]{2,}\s*[=:]|\n\n|\Z)",
    re.DOTALL,
)

# Dash-like characters between two timestamps.
_STRUCTURE_DASH = r"[-\u2010\u2011\u2012\u2013\u2014\u2015\u2212]"
_STRUCTURE_TIME = r"\d{1,2}:\d{2}(?::\d{2})?"

# FIXED: '*' quantifiers restored so single- and multi-word section names
# ("Intro", "Verse 1", "Post-Chorus") actually match. Regex backtracking
# keeps the name from swallowing the following timestamp.
_STRUCTURE_NAME = r"[A-Za-z][A-Za-z0-9'/!]*(?:[ \u00A0\u202F-][A-Za-z0-9'/!]+)*"

_STRUCTURE_ENTRY_RE = re.compile(
    rf"(?:"
    rf"(?P<name1>{_STRUCTURE_NAME})\s+(?P<start1>{_STRUCTURE_TIME})\s*{_STRUCTURE_DASH}+\s*(?P<end1>{_STRUCTURE_TIME})"
    rf"|"
    rf"(?P<start2>{_STRUCTURE_TIME})\s*{_STRUCTURE_DASH}+\s*(?P<end2>{_STRUCTURE_TIME})\s+(?P<name2>{_STRUCTURE_NAME})"
    rf")"
    rf"(?:\s*\((?P<approx>[^)]*)\))?"
)


def extract_structure_sections(text):
    """Parse STRUCTURE=[...] or STRUCTURE: ... into [{name,start,end}, ...]."""
    if not text:
        return []
    # A bolded label ("**STRUCTURE**=[...]") used to miss the field regex, and
    # the fallback then scanned the WHOLE analysis for "Name M:SS-M:SS" pairs.
    text = _strip_md_emphasis(text)
    m = _STRUCTURE_FIELD_RE.search(text)
    body = m.group(1) if m else text
    # The canonical field written back by _overwrite_structure_field uses
    # "Name | M:SS-M:SS" lines. Splitting on "|" below separated every name
    # from its times, so a map this script had itself written could never
    # be read back. Join name and time first.
    body = re.sub(r"\s*\|\s*(?=\d{1,2}:\d{2})", " ", body)
    sections = []
    for entry in re.split(r"[;\n|]+", body):
        entry = entry.strip(" \t-•*[]()")
        if not entry:
            continue
        em = _STRUCTURE_ENTRY_RE.search(entry)
        if not em:
            continue
        gd = em.groupdict()
        if gd.get("name1") is not None:
            name, start_raw, end_raw = gd["name1"], gd["start1"], gd["end1"]
        else:
            name, start_raw, end_raw = gd["name2"], gd["start2"], gd["end2"]
        name = name.strip(" \t-\u2010\u2011\u2012\u2013\u2014\u2015\u00A0\u202F")
        if name.upper() in {
            "STRUCTURE", "KEY", "TEMPO_BPM", "TEMPO", "CHORDS",
            "INSTRUMENTATION", "DRUMS", "VOCALS", "GENRE", "GENRE_RANKED",
        }:
            continue
        start = _mmss_to_seconds(start_raw)
        end = _mmss_to_seconds(end_raw)
        if name and start is not None and end is not None and end > start:
            sections.append({"name": name, "start": float(start), "end": float(end)})
    sections.sort(key=lambda s: (s["start"], s["end"]))
    return sections


_OBJECTIVE_BOUNDARY_RE = re.compile(
    r"candidate change points:\s*(.+)", re.IGNORECASE
)


def extract_objective_structure_boundaries(text):
    """Parse the 'STRUCTURAL BOUNDARY CANDIDATES' line written by
    build_objective_audio_report (via _structural_novelty_boundaries) back
    out of the OBJECTIVE AUDIO MEASUREMENTS report text, e.g.
    'candidate change points: 0:19, 0:47, 1:15' -> [19.0, 47.0, 75.0].
    Returns [] if the line isn't present or nothing parses."""
    if not text:
        return []
    m = _OBJECTIVE_BOUNDARY_RE.search(text)
    if not m:
        return []
    times = []
    for tok in m.group(1).split(","):
        secs = _mmss_to_seconds(tok.strip())
        if secs is not None:
            times.append(secs)
    return sorted(times)


def _normalize_structure_sections(sections, total_duration=None, min_section_s=3.0):
    """Monotonic, contiguous sections; drop/merge tiny scraps; clamp to duration."""
    if not sections:
        return []

    out = [dict(s) for s in sections]
    out.sort(key=lambda s: (float(s["start"]), float(s["end"])))

    for i in range(1, len(out)):
        prev_end = float(out[i - 1]["end"])
        cur_start = float(out[i]["start"])
        if abs(cur_start - prev_end) <= 2.0 or cur_start < prev_end:
            out[i]["start"] = prev_end

    if total_duration is not None and float(total_duration) > 0:
        dur = float(total_duration)
        out[0]["start"] = max(0.0, min(float(out[0]["start"]), dur))
        for s in out:
            s["start"] = max(0.0, min(float(s["start"]), dur))
            s["end"] = max(float(s["start"]), min(float(s["end"]), dur))
        out[-1]["end"] = dur

    cleaned = []
    for s in out:
        start, end = float(s["start"]), float(s["end"])
        if end - start < min_section_s:
            if cleaned:
                cleaned[-1]["end"] = max(float(cleaned[-1]["end"]), end)
            continue
        keep = dict(s)
        keep.update({"name": s["name"], "start": start, "end": end})
        cleaned.append(keep)

    for i in range(1, len(cleaned)):
        cleaned[i]["start"] = float(cleaned[i - 1]["end"])
        if cleaned[i]["end"] <= cleaned[i]["start"]:
            cleaned[i]["end"] = cleaned[i]["start"] + min_section_s

    if total_duration is not None and cleaned:
        cleaned[-1]["end"] = float(total_duration)
        # Final pass: drop any section that is still tiny after chaining
        cleaned = [s for s in cleaned if float(s["end"]) - float(s["start"]) >= min_section_s * 0.5]
        if cleaned:
            cleaned[-1]["end"] = float(total_duration)

    return cleaned


# Section names that describe a real, repeatable musical role. Only these are
# safe to pool across occurrences: "Verse 1" and "Verse 2" are two instances of
# one idea, so a single pooled groove read answers "what are the drums doing in
# the verse". A placeholder name like "Section 2" carries no such claim -- the
# number is the ONLY thing distinguishing it from "Section 3" -- so stripping
# the digit merged unrelated passages into one average. On a pop test track that
# collapsed 0:19-0:34 (kick and hats, no snare), 0:34-0:47 (snare enters) and
# 1:10-1:40 into a single "Section" groove, erasing exactly the build the
# listener hears.
_POOLABLE_SECTION_ROLES = (
    "verse", "chorus", "pre-chorus", "prechorus", "post-chorus", "postchorus",
    "bridge", "refrain", "hook", "intro", "outro", "interlude", "breakdown",
    "drop", "build", "instrumental", "solo", "coda", "vamp", "tag", "ending",
)


def _section_group_key(name):
    """Normalize 'Verse 1' / 'Verse 2' / 'Chorus 3' -> 'verse' / 'chorus' so
    repeated sections of the same kind can be pooled for a single groove read,
    which is almost always what's meant by "the groove in the verse".

    Generic placeholder names are deliberately NOT pooled: for those the
    trailing number is the only thing telling two passages apart, so merging
    them averages away real musical differences instead of summarising
    repetitions of one section.
    """
    raw = (name or "").strip()
    stripped = re.sub(r"\s*\d+\s*$", "", raw).strip().lower()
    if re.fullmatch(r"chorus [a-c]", stripped):
        stripped = "chorus"          # pre60 STRUCTURE_CHORUS_GROUPS: pooled as choruses, as before
    if stripped in _POOLABLE_SECTION_ROLES:
        return stripped
    return raw.lower()


def _snap_onsets_to_subdivision(times, beat_len, subdivision=0.25, max_snap_s=0.045):
    """Snap onset times to the nearest beat subdivision if within max_snap_s.

    Programmed pop drums often land a few ms early/late relative to a
    detector's onset frame; that jitter tanks circular concentration even
    when the musical grid is tight. Snapping within a small window recovers
    lock for quantized kits without inventing structure for free-time playing
    (hits farther than max_snap_s from any grid point are left alone).
    subdivision is in beats (0.25 = 16th notes at the track tempo).
    """
    if not times or beat_len <= 0:
        return list(times) if times else []
    cell = beat_len * float(subdivision)
    if cell <= 0:
        return list(times)
    out = []
    for t in times:
        t = float(t)
        nearest = round(t / cell) * cell
        if abs(t - nearest) <= max_snap_s:
            out.append(nearest)
        else:
            out.append(t)
    return out


def _circular_lock(times, beat_len, divisor):
    """Circular concentration (0-1) of onset phase within a grid cell of
    `divisor` beats. 1.0 = every hit at the same phase; ~0 = scattered."""
    cell = beat_len * divisor
    if cell <= 0 or not times:
        return 0.0
    phases = (np.array(times, dtype=float) % cell) / cell
    angles = phases * 2 * np.pi
    return float(np.abs(np.mean(np.exp(1j * angles))))


def _trim_phase_outliers(times, beat_len, divisor, keep_frac=0.85):
    """Drop the farthest-from-mean-phase hits before lock scoring.

    One fill or a few mis-labelled onsets should not force an entire
    programmed kick pattern into the 'irregular' bin.
    """
    if not times or len(times) < 8:
        return list(times)
    cell = beat_len * divisor
    if cell <= 0:
        return list(times)
    arr = np.array(times, dtype=float)
    phases = (arr % cell) / cell
    angles = phases * 2 * np.pi
    mean_angle = np.angle(np.mean(np.exp(1j * angles)))
    # Circular distance to mean phase
    dist = np.abs(((angles - mean_angle + np.pi) % (2 * np.pi)) - np.pi)
    n_keep = max(6, int(len(arr) * keep_frac))
    if n_keep >= len(arr):
        return list(times)
    idx = np.argsort(dist)[:n_keep]
    return sorted(float(arr[i]) for i in idx)


def _active_segments(times, beat_len, gap_beats=8.0):
    """Split sorted onset times into stretches where the part is actually
    playing, breaking wherever it stops for longer than `gap_beats`.

    Per-section groove reads pool every occurrence of a section (Verse 1 and
    Verse 2, which sit a minute apart), and a whole-track read spans drum
    breaks. Measuring hit RATE over first-to-last hit counted all of that
    silence as beats with no hits: a clean half-time kick pooled over two
    verses came out at ~0.33 kicks per beat and was reported as "rate does
    not match a simple pattern", and a four-on-the-floor kick lost its
    beat coverage the same way.
    """
    arr = np.asarray(sorted(float(t) for t in (times if times is not None else [])), dtype=float)
    if arr.size == 0 or not beat_len or beat_len <= 0:
        return []
    gap = float(gap_beats) * float(beat_len)
    segs = []
    start = prev = float(arr[0])
    for t in arr[1:]:
        t = float(t)
        if t - prev > gap:
            segs.append((start, prev))
            start = t
        prev = t
    segs.append((start, prev))
    return segs


def _active_rate_per_beat(times, beat_len, gap_beats=8.0):
    """(hits per beat, active span in beats) over the playing stretches only.

    For a single contiguous stretch this is exactly count / span, the value
    the classifiers always used; each extra stretch removes one count so a
    pooled read is not biased upward by its segment boundaries.
    """
    segs = _active_segments(times, beat_len, gap_beats=gap_beats)
    if not segs:
        return 0.0, 0.0
    span_beats = sum(e - s for s, e in segs) / float(beat_len)
    if span_beats <= 0:
        return 0.0, 0.0
    count = len(times) - (len(segs) - 1)
    return max(0.0, count / span_beats), span_beats


def _kick_beat_coverage(kicks, beat_len, tol_frac=0.10):
    """Fraction of beats in the span that actually carry a kick, plus the
    fraction of kicks that land on a beat.

    "Four on the floor" means a kick on EVERY beat. The grid-lock score alone
    cannot express that: it measures how tightly kick phases cluster, not how
    many beats get hit. A boom-bap or dembow pattern (kick on 1, the 'a' of 1,
    the '&' of 2, the '&' of 3) averages almost exactly one kick per beat and
    clusters into two phase groups, which scores as moderate lock at a
    four-on-the-floor hit rate -- so rate+lock alone labelled several of the
    most common non-four-on-the-floor grooves in popular music as
    four-on-the-floor. Coverage separates them cleanly: a real
    four-on-the-floor covers ~100% of beats, those grooves cover ~25-50%.

    The beat grid's absolute phase is unknown here (only bpm is passed in), so
    the offset that maximises coverage is searched for and used -- consistent
    with this module's existing assumption that we don't know where bar 1 is.
    A consequence worth knowing: a kick landing evenly on every off-beat scores
    as full coverage, because with only a tempo to go on there is no way to
    tell "kick on every beat" from "kick on every off-beat" -- and a listener
    would hear an evenly spaced kick as the pulse either way.

    The tolerance must stay below half a 16th-note (0.125 beat) or a single
    grid point can sit between two adjacent 16th positions and match both,
    which is exactly how a boom-bap pattern scored 0.76 coverage instead of
    its true 0.5.

    Returns (beat_coverage, on_beat_fraction, n_beats).
    """
    if not kicks or not beat_len or beat_len <= 0:
        return 0.0, 0.0, 0
    arr = np.asarray(sorted(float(k) for k in kicks), dtype=float)
    if arr.size < 2:
        return 0.0, 0.0, 0
    t0, t1 = arr[0], arr[-1]
    n_beats = int(round((t1 - t0) / beat_len)) + 1
    if n_beats < 4:
        return 0.0, 0.0, n_beats

    tol = beat_len * float(tol_frac)
    # Only beats inside stretches where the kick is actually playing count as
    # "should carry a kick" -- a drum break or the gap between two pooled
    # verses is not a run of missing four-on-the-floor kicks.
    segs = _active_segments(arr, beat_len)
    if len(segs) > 1:
        seg_lo = np.asarray([a for a, _b in segs], dtype=float) - tol
        seg_hi = np.asarray([b for _a, b in segs], dtype=float) + tol
    else:
        seg_lo = seg_hi = None
    best = (0.0, 0.0)
    # 24 candidate grid phases is finer than the tolerance window, so the true
    # alignment is always within reach of one of them.
    for step in range(24):
        offset = (step / 24.0) * beat_len
        grid = t0 + offset + np.arange(n_beats) * beat_len
        grid = grid[(grid >= t0 - tol) & (grid <= t1 + tol)]
        if seg_lo is not None and grid.size:
            k = np.searchsorted(seg_lo, grid, side="right") - 1
            inside = (k >= 0) & (grid <= seg_hi[np.clip(k, 0, len(seg_hi) - 1)])
            grid = grid[inside]
        if grid.size == 0:
            continue
        idx = np.searchsorted(arr, grid)
        left = np.clip(idx - 1, 0, arr.size - 1)
        right = np.clip(idx, 0, arr.size - 1)
        dist = np.minimum(np.abs(arr[left] - grid), np.abs(arr[right] - grid))
        covered = float(np.count_nonzero(dist <= tol)) / float(grid.size)

        gidx = np.searchsorted(grid, arr)
        gl = np.clip(gidx - 1, 0, grid.size - 1)
        gr = np.clip(gidx, 0, grid.size - 1)
        kdist = np.minimum(np.abs(grid[gl] - arr), np.abs(grid[gr] - arr))
        on_beat = float(np.count_nonzero(kdist <= tol)) / float(arr.size)

        if covered > best[0]:
            best = (covered, on_beat)
    return best[0], best[1], n_beats


def _local_grid_windows(times, beat_len, win_beats=16.0, gap_beats=8.0, min_seg_hits=3):
    """Split hits into local windows (inside the stretches where the part is
    actually playing) for the drift-tolerant grid measures below.

    Yields (window_start, window_end, hits_in_window). A short tail is merged
    into the window before it so no window is too short to judge. Stretches
    of fewer than `min_seg_hits` hits (an isolated accent between long gaps)
    are skipped: a lone hit trivially "covers" a one-point grid.
    """
    arr = np.asarray(sorted(float(t) for t in (times if times is not None else [])), dtype=float)
    if arr.size == 0 or not beat_len or beat_len <= 0:
        return []
    W = float(win_beats) * float(beat_len)
    out = []
    for s, e in _active_segments(arr, beat_len, gap_beats=gap_beats):
        seg_hits = arr[(arr >= s) & (arr <= e)]
        if seg_hits.size < int(min_seg_hits):
            continue
        edges = [s]
        while edges[-1] + W < e:
            edges.append(edges[-1] + W)
        if len(edges) > 1 and (e - edges[-1]) < 0.5 * W:
            edges.pop()
        edges.append(e + 1e-6)
        for a, b in zip(edges[:-1], edges[1:]):
            m = arr[(arr >= a) & (arr < b)]
            out.append((float(a), float(b), m))
    return out


def _fit_window_grid(m, a, b, period, tol, n_off):
    """Best-fitting grid (one point every `period` s) for the hits `m` inside
    the window [a, b).

    Grid points are counted across the WHOLE window, not just between its
    first and last hit, so a window cannot score well by trimming away the
    stretch it fails to cover. Among offsets that tie on coverage the centre
    of the tied run is used, and the grid is then shifted onto the mean
    position of the hits it caught -- otherwise the first tied offset (the
    early edge of the tolerance) was used and every phase measured from it
    came out ~0.1 beat late.

    Returns (grid, covered, on_grid_mask) or None.
    """
    if m.size == 0 or period <= 0 or b <= a:
        return None
    n_pts = int(np.ceil((b - a) / period)) + 1
    scores = []
    for i in range(n_off):
        off = (i / float(n_off)) * period
        grid = a + off + np.arange(n_pts) * period
        grid = grid[(grid >= a) & (grid < b)]
        if grid.size == 0:
            scores.append((-1, -1))
            continue
        idx = np.searchsorted(m, grid)
        lo = np.clip(idx - 1, 0, m.size - 1)
        hi = np.clip(idx, 0, m.size - 1)
        dist = np.minimum(np.abs(m[lo] - grid), np.abs(m[hi] - grid))
        gidx = np.searchsorted(grid, m)
        gl = np.clip(gidx - 1, 0, grid.size - 1)
        gr = np.clip(gidx, 0, grid.size - 1)
        hd = np.minimum(np.abs(grid[gl] - m), np.abs(grid[gr] - m))
        scores.append((int(np.count_nonzero(dist <= tol)), int(np.count_nonzero(hd <= tol))))
    best_key = max(scores)
    if best_key[0] <= 0:
        return None
    tied = np.asarray([i for i, k in enumerate(scores) if k == best_key], dtype=float)
    ang = 2.0 * np.pi * tied / float(n_off)
    centre = (float(np.angle(np.mean(np.exp(1j * ang)))) % (2.0 * np.pi)) / (2.0 * np.pi)

    def _evaluate(off):
        grid = a + off + np.arange(-1, n_pts + 1) * period
        # Shift onto the hits actually caught.
        gidx = np.searchsorted(grid, m)
        gl = np.clip(gidx - 1, 0, grid.size - 1)
        gr = np.clip(gidx, 0, grid.size - 1)
        near = np.where(np.abs(grid[gl] - m) <= np.abs(grid[gr] - m), grid[gl], grid[gr])
        resid = m - near
        on = np.abs(resid) <= tol
        if np.any(on):
            grid = grid + float(np.mean(resid[on]))
        grid_in = grid[(grid >= a - tol) & (grid < b)]
        if grid_in.size == 0:
            return None
        idx = np.searchsorted(m, grid_in)
        lo = np.clip(idx - 1, 0, m.size - 1)
        hi = np.clip(idx, 0, m.size - 1)
        dist = np.minimum(np.abs(m[lo] - grid_in), np.abs(m[hi] - grid_in))
        covered = int(np.count_nonzero(dist <= tol))
        gidx = np.searchsorted(grid_in, m)
        gl = np.clip(gidx - 1, 0, grid_in.size - 1)
        gr = np.clip(gidx, 0, grid_in.size - 1)
        hd = np.minimum(np.abs(grid_in[gl] - m), np.abs(grid_in[gr] - m))
        return grid_in, covered, hd <= tol

    res = _evaluate(centre * period)
    if res is None or res[1] < best_key[0]:
        # Tied offsets split into separate runs (their centre is not itself
        # a good fit): fall back to the first tied offset, still shifted
        # onto the caught hits.
        alt = _evaluate((float(tied[0]) / float(n_off)) * period)
        if alt is not None and (res is None or alt[1] > res[1]):
            res = alt
    return res


def _local_cell_coverage(times, beat_len, period_beats=1.0, win_beats=16.0,
                         tol_frac=0.12, steps_per_beat=24, collect_on_grid=None):
    """Coverage of a grid with one point every `period_beats` beats, with the
    grid's phase fitted separately in each local window.

    _kick_beat_coverage fits ONE phase to the whole stretch at a constant
    tempo. Real recordings -- an unclicked band, and in particular AI-generated
    audio, whose timing wanders by tens of milliseconds and can jump between
    generation chunks -- drift off any single grid within half a minute. A kick
    landing on every beat to within 10 ms (an AI-generated test track: kick spacing 0.500 s,
    spread 0.01) then scored ~0.69 coverage over the track and only ~0.53 over
    its pooled verses, and was reported as "syncopated, NOT four-on-the-floor".
    Fitting the phase per window of `win_beats` beats removes the drift while
    keeping the test itself: a syncopated one-kick-per-beat pattern (boom-bap,
    dembow) still covers at most ~half of the beats in every window.

    Returns (coverage, on_grid_fraction, n_grid_points). `coverage` is the
    share of grid points that carry a hit; `on_grid_fraction` the share of ALL
    the hits passed in that sit on the fitted grids. When `collect_on_grid` is
    a list, the on-grid hit times are appended to it.
    """
    try:
        beat_len = float(beat_len)
        period = float(period_beats) * beat_len
    except (TypeError, ValueError):
        return 0.0, 0.0, 0
    if not times or beat_len <= 0 or period <= 0:
        return 0.0, 0.0, 0
    tol = float(tol_frac) * beat_len
    gap_beats = max(8.0, 2.5 * float(period_beats))
    n_off = max(8, int(round(steps_per_beat * float(period_beats))))
    covered_tot = 0
    grid_tot = 0
    on_tot = 0
    for a, b, m in _local_grid_windows(times, beat_len, win_beats=max(win_beats, 4.0 * period_beats),
                                       gap_beats=gap_beats):
        fit = _fit_window_grid(m, a, b, period, tol, n_off)
        if fit is None:
            # Hits but no grid point caught anything: the grid is uncovered.
            grid_tot += max(1, int(np.floor((b - a) / period)))
            continue
        grid, cov, on_mask = fit
        covered_tot += cov
        grid_tot += int(grid.size)
        on_tot += int(np.count_nonzero(on_mask))
        if collect_on_grid is not None:
            collect_on_grid.extend(float(t) for t in m[on_mask])
    if grid_tot == 0:
        return 0.0, 0.0, 0
    return covered_tot / float(grid_tot), on_tot / float(max(1, len(times))), grid_tot


def _local_circular_lock(times, beat_len, divisor, win_beats=16.0, min_hits=4):
    """Grid-lock (circular phase concentration) measured window by window.

    The same drift that defeats a single whole-track phase also lowers the
    whole-track lock: phases that are tight locally smear into a broad
    distribution once the grid has wandered. Each window's resultant is
    debiased for its hit count (a handful of random hits always clusters a
    little), then the windows are pooled weighted by hits.
    """
    cell = float(beat_len) * float(divisor)
    if not times or cell <= 0:
        return 0.0
    num = 0.0
    den = 0.0
    for _a, _b, m in _local_grid_windows(times, beat_len, win_beats=win_beats):
        n = int(m.size)
        if n < int(min_hits):
            continue
        ang = 2.0 * np.pi * (m % cell) / cell
        r2 = float(np.abs(np.mean(np.exp(1j * ang)))) ** 2
        r2u = max(0.0, (n * r2 - 1.0) / (n - 1.0))
        num += n * r2u
        den += n
    if den <= 0:
        return 0.0
    return float(np.sqrt(num / den))


def _local_relative_phase(ref_times, other_times, beat_len, period_beats, win_beats=16.0, tol_frac=0.12):
    """Where `other_times` sit inside a `period_beats` cycle anchored on the
    locally fitted grid of `ref_times` (e.g. kicks relative to the snare).

    Returns (mean_position_in_beats, concentration) -- the circular mean of
    the other part's position within the cycle (0 = with the reference,
    period/2 = opposite it) and how tightly it clusters there (0-1), or
    (None, 0.0) when there is not enough to say.
    """
    period = float(period_beats) * float(beat_len)
    if not ref_times or not other_times or period <= 0:
        return None, 0.0
    oth = np.asarray(sorted(float(t) for t in other_times), dtype=float)
    tol = float(tol_frac) * float(beat_len)
    n_off = max(8, int(round(24 * float(period_beats))))
    zs = []
    for a, b, m in _local_grid_windows(ref_times, beat_len, win_beats=max(win_beats, 4.0 * period_beats),
                                       gap_beats=max(8.0, 2.5 * float(period_beats))):
        fit = _fit_window_grid(m, a, b, period, tol, n_off)
        if fit is None:
            continue
        grid = fit[0]
        o = oth[(oth >= a) & (oth < b)]
        if o.size == 0:
            continue
        anchor = float(grid[0])
        ang = 2.0 * np.pi * ((o - anchor) % period) / period
        zs.extend(np.exp(1j * ang).tolist())
    if len(zs) < 4:
        return None, 0.0
    z = np.mean(np.asarray(zs))
    pos = (float(np.angle(z)) % (2.0 * np.pi)) / (2.0 * np.pi) * float(period_beats)
    return pos, float(np.abs(z))


def _local_offset_hit_rate(ref_times, other_times, beat_len, period_beats, offset_beats,
                           win_beats=32.0, tol_frac=0.12):
    """Share of the reference part's locally fitted grid points (one every
    `period_beats`) that have an `other_times` hit `offset_beats` later (a
    negative offset looks earlier). E.g. with the snare as reference and a
    4-beat period: is there a kick two beats away from the snare, bar after
    bar? Returns (rate, n_points) or (0.0, 0).
    """
    period = float(period_beats) * float(beat_len)
    if not ref_times or not other_times or period <= 0:
        return 0.0, 0
    oth = np.asarray(sorted(float(t) for t in other_times), dtype=float)
    tol = float(tol_frac) * float(beat_len)
    n_off = max(8, int(round(24 * float(period_beats))))
    hit = 0
    tot = 0
    for a, b, m in _local_grid_windows(ref_times, beat_len, win_beats=max(win_beats, 4.0 * period_beats),
                                       gap_beats=max(8.0, 2.5 * float(period_beats))):
        fit = _fit_window_grid(m, a, b, period, tol, n_off)
        if fit is None:
            continue
        targets = fit[0] + float(offset_beats) * float(beat_len)
        idx = np.searchsorted(oth, targets)
        lo = np.clip(idx - 1, 0, oth.size - 1)
        hi = np.clip(idx, 0, oth.size - 1)
        dist = np.minimum(np.abs(oth[lo] - targets), np.abs(oth[hi] - targets))
        hit += int(np.count_nonzero(dist <= tol))
        tot += int(targets.size)
    if tot == 0:
        return 0.0, 0
    return hit / float(tot), tot


def _refine_bpm_from_onsets(onsets, bpm, max_dev=0.03, min_onsets=12):
    """Return the tempo that the drum onsets themselves sit on, near `bpm`.

    The reported BPM is a rounded integer (and the reconciliation that picks
    it can land a percent or so off), while grid-lock is measured as the
    circular spread of onset phases across the WHOLE track or section. A
    0.3% error drifts the phase by more than a beat over three minutes, so a
    perfectly quantised four-on-the-floor kick scored as "syncopated, NOT
    four-on-the-floor" and a clean backbeat as merely "moderate". Fitting the
    16th-note cell length to the onsets removes that drift before any grid
    judgement is made. The nominal tempo is kept unless the fit is clearly
    better, and the search never leaves +/- max_dev, so this can only correct
    a rounding/estimation error -- never change the pulse level.
    """
    try:
        bpm = float(bpm)
    except (TypeError, ValueError):
        return bpm
    if not bpm or bpm <= 0:
        return bpm
    arr = np.asarray(sorted(float(t) for t in (onsets if onsets is not None else [])), dtype=float)
    if arr.size < int(min_onsets):
        return bpm
    cell0 = 60.0 / bpm / 4.0
    rel = arr - float(np.median(arr))
    span = float(arr[-1] - arr[0])
    if span <= cell0 * 8:
        return bpm

    def _r(cells):
        cells = np.asarray(cells, dtype=float).reshape(-1, 1)
        ang = 2.0 * np.pi * (rel.reshape(1, -1) / cells)
        return np.hypot(np.mean(np.sin(ang), axis=1), np.mean(np.cos(ang), axis=1))

    n_cells = span / cell0
    # Step fine enough that the main lobe of the fit (width ~1/n_cells) is
    # always sampled, however long the stretch of music is.
    step = min(0.00025, 0.25 / max(1.0, n_cells))
    n_steps = int(min(6001, max(61, np.ceil(2 * max_dev / step) + 1)))
    scales = np.linspace(1.0 - max_dev, 1.0 + max_dev, n_steps)
    try:
        r = _r(cell0 * scales)
    except MemoryError:
        return bpm
    i = int(np.argmax(r))
    best_scale, best_r = float(scales[i]), float(r[i])
    fine = np.linspace(best_scale - step, best_scale + step, 41)
    rf = _r(cell0 * fine)
    j = int(np.argmax(rf))
    if float(rf[j]) > best_r:
        best_scale, best_r = float(fine[j]), float(rf[j])
    r0 = float(_r([cell0])[0])
    if best_r < 0.3 or best_r < r0 + 0.03:
        return bpm
    return bpm / best_scale


def _cell_resultant(times, cell):
    """Circular resultant length of onset phases on a grid of `cell` seconds."""
    arr = np.asarray(times, dtype=float)
    if arr.size == 0 or cell <= 0:
        return 0.0
    ang = 2.0 * np.pi * (arr - float(np.median(arr))) / float(cell)
    return float(np.hypot(np.mean(np.sin(ang)), np.mean(np.cos(ang))))


def _tempo_warp_onsets(onsets, bpm, win_beats=32.0, hop_beats=8.0, max_dev=0.025):
    """Map onset times onto a steady-tempo timeline when the drummer drifts.

    Returns a function t -> warped t, or None when no warp is warranted.

    An unclicked live take wanders a percent or two around its average tempo.
    Grid-lock is measured as phase against ONE tempo across the whole track,
    so that wander alone made a live four-on-the-floor read as "syncopated,
    NOT four-on-the-floor" and a live backbeat as "loosely on a grid". Here
    the local tempo is fitted in overlapping windows (tempo only -- no phase,
    so phase stays continuous) and integrated into a beat-position clock.

    Used only when it clearly tightens the whole-track fit, so clicked and
    programmed tracks, whose tempo is already constant, are left exactly as
    they were.
    """
    try:
        bpm = float(bpm)
    except (TypeError, ValueError):
        return None
    arr = np.asarray(sorted(float(t) for t in (onsets if onsets is not None else [])), dtype=float)
    if not bpm or bpm <= 0 or arr.size < 48:
        return None
    beat = 60.0 / bpm
    cell = beat / 4.0
    t0, t1 = float(arr[0]), float(arr[-1])
    if (t1 - t0) < beat * win_beats * 2.0:
        return None

    win = beat * win_beats
    centers, scales = [], []
    c = t0 + win / 2.0
    scale_grid = np.linspace(1.0 - max_dev, 1.0 + max_dev, 201)
    while c <= t1 - win / 2.0 + 1e-9:
        seg = arr[(arr >= c - win / 2.0) & (arr <= c + win / 2.0)]
        if seg.size >= 16:
            rel = (seg - c).reshape(1, -1)
            cells = (cell * scale_grid).reshape(-1, 1)
            ang = 2.0 * np.pi * rel / cells
            r = np.hypot(np.mean(np.sin(ang), axis=1), np.mean(np.cos(ang), axis=1))
            i = int(np.argmax(r))
            if float(r[i]) >= 0.35:
                centers.append(c)
                scales.append(float(scale_grid[i]))
        c += beat * hop_beats
    if len(scales) < 3:
        return None
    scales = np.asarray(scales, dtype=float)
    # Median-of-3 smoothing so one noisy window cannot kink the clock.
    sm = scales.copy()
    for i in range(1, len(scales) - 1):
        sm[i] = float(np.median(scales[i - 1:i + 2]))
    if float(np.max(np.abs(sm - 1.0))) < 0.002:
        return None  # already steady; nothing to correct
    centers = np.asarray(centers, dtype=float)

    grid_t = np.linspace(t0 - beat, t1 + beat, int(max(64, (t1 - t0) / cell)) + 1)
    local_beat = beat * np.interp(grid_t, centers, sm)
    rate = 1.0 / local_beat                     # beats per second
    dt = np.diff(grid_t)
    beats_pos = np.concatenate([[0.0], np.cumsum(0.5 * (rate[1:] + rate[:-1]) * dt)])

    def warp(t):
        return float(grid_t[0] + beat * np.interp(float(t), grid_t, beats_pos))

    warped = np.asarray([warp(t) for t in arr])
    r_raw = _cell_resultant(arr, cell)
    r_warp = _cell_resultant(warped, cell)
    if r_warp < r_raw + 0.05:
        return None
    return warp


def _classify_kick_grid(kicks, bpm):
    """Classify how the kick drum sits on the track's beat grid, using the
    reconciled tempo rather than a raw hits-per-minute threshold.

    A hit-rate-only heuristic can't tell a genuine one-kick-per-beat
    four-on-the-floor pattern apart from, say, a mid-tempo song with kicks
    only on beats 1 and 3 that happens to fall in the same rate band. This
    instead measures how tightly the kicks cluster around a candidate
    beat-grid (quarter/half/eighth note) using circular concentration,
    independent of where bar 1 actually falls (which we don't know).

    Lock thresholds are tiered so medium concentration on a rate-matching
    pattern (common with soft 808s / onset jitter on quantized pop) is
    reported as 'mostly on grid' rather than 'irregular' — the previous
    hard 0.75 cutoff was labelling tight programmed kits as wandering.

    Rate and lock are necessary but NOT sufficient for a four-on-the-floor
    claim: both are satisfied by common syncopated grooves that put roughly
    one kick per beat somewhere other than on the beats. Beat COVERAGE (are
    the beats themselves actually being hit?) is therefore required as well
    before the phrase is used — see _kick_beat_coverage.

    Returns (label, detail) or (None, None) if there isn't enough evidence
    (no bpm, or too few kicks) to say anything reliable.
    """
    if not bpm or bpm <= 0 or not kicks or len(kicks) < 6:
        return None, None

    kicks_raw = sorted(float(k) for k in kicks)
    beat_len = 60.0 / bpm
    kicks_per_beat, span_beats = _active_rate_per_beat(kicks_raw, beat_len)
    if span_beats < 3:
        return None, None

    # Snap then score — use the better of raw vs snapped lock so free-time
    # playing is not artificially tightened.
    kicks_snap = _snap_onsets_to_subdivision(kicks_raw, beat_len, subdivision=0.25, max_snap_s=0.045)

    def _best_lock(divisor):
        raw_t = _trim_phase_outliers(kicks_raw, beat_len, divisor)
        snap_t = _trim_phase_outliers(kicks_snap, beat_len, divisor)
        return max(
            _circular_lock(raw_t, beat_len, divisor),
            _circular_lock(snap_t, beat_len, divisor),
            # Window-by-window lock, so timing drift over the track (live
            # playing, AI-generated audio) is not mistaken for looseness.
            _local_circular_lock(kicks_raw, beat_len, divisor),
        )

    lock_quarter = _best_lock(1.0)   # every beat
    lock_half = _best_lock(2.0)      # every other beat
    lock_eighth = _best_lock(0.5)    # two per beat

    coverage, on_beat_frac, _n_beats = _kick_beat_coverage(kicks_raw, beat_len)
    # The same coverage test with its grid phase fitted locally (see
    # _local_cell_coverage): drift moved a perfectly regular kick off the
    # single whole-track grid and it was reported as NOT four-on-the-floor.
    _lcov, _lon, _ln = _local_cell_coverage(kicks_raw, beat_len, 1.0)
    if _ln and _lcov > coverage:
        coverage, on_beat_frac = _lcov, _lon

    # Tiered thresholds (was a single hard 0.75 → everything else 'irregular').
    STRONG = 0.68
    MODERATE = 0.52
    WEAK = 0.40
    # A kick on every beat is what the phrase means, so demand most beats be hit.
    FOTF_COVERAGE_STRONG = 0.85
    FOTF_COVERAGE_MODERATE = 0.70

    def _rate_label(strong_lab, moderate_lab, lock_val, kpb_note):
        if lock_val >= STRONG:
            return strong_lab, f"~{kicks_per_beat:.2f} kicks/beat, grid-lock {lock_val:.2f}"
        if lock_val >= MODERATE:
            return moderate_lab, f"~{kicks_per_beat:.2f} kicks/beat, grid-lock {lock_val:.2f} (moderate — quantized/programmed kits often land here)"
        return None, None

    if 0.8 <= kicks_per_beat <= 1.25:
        cov_note = f", beat coverage {coverage:.2f}"
        if lock_quarter >= STRONG and coverage >= FOTF_COVERAGE_STRONG:
            return (
                "four-on-the-floor (kick locked to every beat)",
                f"~{kicks_per_beat:.2f} kicks/beat, grid-lock {lock_quarter:.2f}{cov_note}",
            )
        if lock_quarter >= MODERATE and coverage >= FOTF_COVERAGE_MODERATE:
            return (
                "mostly four-on-the-floor / on-beat kick (moderate grid-lock; treat as a programmed on-beat pattern, not irregular)",
                f"~{kicks_per_beat:.2f} kicks/beat, grid-lock {lock_quarter:.2f}{cov_note} "
                "(moderate — quantized/programmed kits often land here)",
            )
        if coverage < FOTF_COVERAGE_MODERATE:
            # Roughly one kick per beat on average, but the beats themselves are
            # not being hit — a syncopated groove (boom-bap, dembow, funk,
            # shuffle) rather than four-on-the-floor. Say so explicitly, because
            # this is precisely the case that used to be mislabelled.
            return (
                "syncopated kick at roughly one hit per beat — NOT four-on-the-floor "
                "(the kicks fall between the beats as often as on them)",
                f"~{kicks_per_beat:.2f} kicks/beat, grid-lock {lock_quarter:.2f}{cov_note}, "
                f"only {on_beat_frac:.2f} of kicks land on a beat — do not call this "
                "four-on-the-floor",
            )
    if 0.35 <= kicks_per_beat <= 0.7:
        # Worded as what it is -- a kick on every other beat. Calling it a
        # "half-time kick" invited the writer to call an ordinary rock beat
        # (kick 1 & 3, snare 2 & 4) a half-time feel; half-time is a property
        # of the SNARE (on 3 only), which the snare analysis reports itself.
        lab, det = _rate_label(
            "kick on every other beat (e.g. 1 & 3)",
            "kick mostly on every other beat (moderate grid-lock; e.g. roughly 1 & 3 — not irregular)",
            lock_half,
            kicks_per_beat,
        )
        if lab:
            return lab, det
    if 1.6 <= kicks_per_beat <= 2.4:
        lab, det = _rate_label(
            "eighth-note / double-time kick (two hits per beat)",
            "mostly eighth-note / double-time kick (moderate grid-lock — not irregular)",
            lock_eighth,
            kicks_per_beat,
        )
        if lab:
            return lab, det

    best = max(lock_quarter, lock_half, lock_eighth)
    if best < WEAK:
        return (
            "syncopated / not locked to a simple beat grid",
            f"~{kicks_per_beat:.2f} kicks/beat, best grid-lock only {best:.2f}",
        )
    if best < MODERATE:
        return (
            "loosely on a beat grid (some timing scatter or syncopation; not a free-time irregular spray)",
            f"~{kicks_per_beat:.2f} kicks/beat, best grid-lock {best:.2f}",
        )
    # Rate did not match a simple pattern, but phase concentration is decent.
    return (
        "kick pattern with moderate grid-lock (rate does not match a simple on-beat / every-other-beat / eighth-note pattern; prefer texture over 'irregular')",
        f"~{kicks_per_beat:.2f} kicks/beat, best grid-lock {best:.2f}",
    )


def _classify_snare_grid(snares, bpm, kicks=None):
    """Classify how the snare sits on the beat grid, the same way
    _classify_kick_grid does for the kick — grid-lock tested against the
    track's actual tempo rather than inferred from raw rate.

    When kicks are also grid-locked, this additionally checks the phase
    offset between kick and snare on a 2-beat cell: a real backbeat sits
    opposite the kick (e.g. kick on 1 & 3, snare on 2 & 4); a snare that
    coincides with the kick's own phase is something else (doubling, not
    a backbeat), even though both can produce the same raw "every other
    beat" hit rate.

    Tiered lock thresholds (strong / moderate / weak) mirror the kick
    classifier so quantized pop snares with mild onset jitter are not
    reported as 'irregular' or 'wandering'.

    Returns (label, detail) or (None, None) if there isn't enough evidence.
    """
    if not bpm or bpm <= 0 or not snares or len(snares) < 6:
        return None, None

    snares_raw = sorted(float(s) for s in snares)
    beat_len = 60.0 / bpm
    snares_per_beat, span_beats = _active_rate_per_beat(snares_raw, beat_len)
    if span_beats < 3:
        return None, None

    snares_snap = _snap_onsets_to_subdivision(snares_raw, beat_len, subdivision=0.25, max_snap_s=0.045)

    def _lock_and_phase(divisor, times):
        cell = beat_len * divisor
        if cell <= 0 or not times:
            return 0.0, 0.0
        phases = (np.array(times, dtype=float) % cell) / cell
        angles = phases * 2 * np.pi
        z = np.mean(np.exp(1j * angles))
        return float(np.abs(z)), float(np.angle(z)) % (2 * np.pi)

    def _best_lock_phase(divisor):
        # Prefer snapped times when they improve lock; keep phase from the
        # version that wins so kick/snare offset stays consistent.
        raw_t = _trim_phase_outliers(snares_raw, beat_len, divisor)
        snap_t = _trim_phase_outliers(snares_snap, beat_len, divisor)
        lr, pr = _lock_and_phase(divisor, raw_t)
        ls, ps = _lock_and_phase(divisor, snap_t)
        if ls >= lr:
            return ls, ps, snap_t
        return lr, pr, raw_t

    lock_quarter, phase_quarter, _ = _best_lock_phase(1.0)
    lock_half, phase_half, snares_for_phase = _best_lock_phase(2.0)
    lock_eighth, phase_eighth, _ = _best_lock_phase(0.5)

    STRONG = 0.65
    MODERATE = 0.50
    WEAK = 0.40

    def _phase_vs_kick(kicks_list, snare_phase):
        if not kicks_list or len(kicks_list) < 6:
            return None, None
        kicks_s = _snap_onsets_to_subdivision(
            sorted(float(k) for k in kicks_list), beat_len, subdivision=0.25, max_snap_s=0.045
        )
        kicks_t = _trim_phase_outliers(kicks_s, beat_len, 2.0)
        klock_half, kphase_half = _lock_and_phase(2.0, kicks_t)
        if klock_half < MODERATE:
            return klock_half, None
        phase_diff = abs(((snare_phase - kphase_half + np.pi) % (2 * np.pi)) - np.pi) / np.pi
        return klock_half, phase_diff

    # ---- Coverage-led read -------------------------------------------------
    # Which grid does the snare actually fill -- every 8th, every beat, every
    # other beat, or once every four beats? Measured as the share of grid
    # positions that carry a snare, with the grid's phase fitted window by
    # window so tempo drift and small timing jumps cannot hide a steady
    # pattern (see _local_cell_coverage). This is checked before the raw
    # hit-rate tests below because the rate counts fills, flams and ghost
    # notes too: a half-time rock snare (once per bar, on 3) plus its fills
    # averages ~0.45 snares per beat -- right in the backbeat band -- and was
    # reported as "rate does not match simple backbeat" or "doubling the kick",
    # while no half-time class existed at all.
    COV = 0.65
    # Most of the snare hits must belong to the pattern being named, so a
    # one-bar roll or a handful of isolated accents cannot carry a label.
    ON_MIN = 0.40
    cov_e, on_e, n_e = _local_cell_coverage(snares_raw, beat_len, 0.5)
    cov_1, on_1, n_1 = _local_cell_coverage(snares_raw, beat_len, 1.0)
    main_2 = []
    cov_2, on_2, n_2 = _local_cell_coverage(snares_raw, beat_len, 2.0, collect_on_grid=main_2)
    cov_4, on_4, n_4 = _local_cell_coverage(snares_raw, beat_len, 4.0, win_beats=32.0)
    k_list = sorted(float(k) for k in kicks) if kicks else []
    kick_every_beat = False
    if len(k_list) >= 6:
        try:
            _k_rate, _k_span = _active_rate_per_beat(k_list, beat_len)
            _k_cov = max(
                _local_cell_coverage(k_list, beat_len, 1.0)[0],
                _kick_beat_coverage(k_list, beat_len)[0],
            )
            kick_every_beat = 0.8 <= _k_rate <= 1.25 and _k_cov >= 0.70
        except Exception:
            kick_every_beat = False

    if n_e >= 8 and cov_e >= COV and on_e >= ON_MIN and snares_per_beat >= 1.5:
        return (
            "snare on eighth-note subdivisions (busy/rolled feel)",
            f"~{snares_per_beat:.2f} snares/beat, snare on {cov_e:.0%} of eighth-note positions",
        )
    if n_1 >= 8 and cov_1 >= COV and on_1 >= ON_MIN and snares_per_beat >= 0.8:
        return (
            "snare on every beat (dense, not a classic backbeat)",
            f"~{snares_per_beat:.2f} snares/beat, snare on {cov_1:.0%} of beats",
        )
    if n_2 >= 6 and cov_2 >= COV and on_2 >= ON_MIN:
        detail = (
            f"~{snares_per_beat:.2f} snares/beat, snare on {cov_2:.0%} of every-other-beat "
            f"positions, grid-lock {max(lock_half, _local_circular_lock(snares_raw, beat_len, 2.0)):.2f}"
        )
        if kick_every_beat:
            # Every-other-beat periodicity alone is not a backbeat: a dembow
            # or breakbeat snare also repeats every two beats but lands
            # BETWEEN the kicks. Check where the main (on-grid) snares sit
            # against the kick's beats; rolls and fills are left out of that,
            # and only a clear off-beat placement gets the syncopated label.
            s_pos, s_conc = _local_relative_phase(k_list, main_2 or snares_raw, beat_len, 1.0)
            if s_pos is not None and s_conc >= 0.5 and min(s_pos, 1.0 - s_pos) >= 0.25:
                return (
                    "syncopated snare/clap repeating every two beats but landing between the "
                    "kicks, over a kick on every beat (e.g. a dembow-style pattern — not a 2-and-4 backbeat)",
                    detail + ", kick on every beat, snare off the beat",
                )
            return (
                "snare/clap on alternate beats over a kick on every beat "
                "(the usual four-on-the-floor backbeat pairing)",
                detail + ", kick on every beat",
            )
        pos, conc = _local_relative_phase(snares_raw, k_list, beat_len, 2.0)
        if pos is not None and conc >= 0.30:
            phase_diff = min(pos, 2.0 - pos)  # 0 = with the snare, 1 = opposite
            detail += f", kick/snare phase offset {phase_diff:.2f} (1.0 = opposite the kick)"
            if phase_diff >= 0.7:
                return (
                    "classic backbeat (snare falls opposite the kick, e.g. 2 & 4 against kick on 1 & 3)"
                    if cov_2 >= 0.80 else
                    "mostly classic backbeat (snare on most 2s and 4s, opposite the kick — not irregular)",
                    detail,
                )
            if phase_diff <= 0.3:
                return "snare doubling the kick's grid position (not a classic backbeat)", detail
            return (
                "snare on a backbeat-rate grid with imperfect opposite-phase lock (still a backbeat-family pattern, not wandering)",
                detail,
            )
        return (
            "backbeat-rate snare (on every other beat; the kick moves around too much to confirm it sits opposite)",
            detail,
        )
    if n_4 >= 4 and cov_4 >= COV and cov_2 < COV and on_4 >= ON_MIN:
        half_bpm = float(bpm) / 2.0
        detail = (
            f"~{snares_per_beat:.2f} snares/beat including fills, main snare on {cov_4:.0%} of "
            f"four-beat cycles but only {cov_2:.0%} of every-other-beat positions"
        )
        if len(k_list) >= 6:
            # Half-time puts the kick on 1, two beats from the snare on 3. A
            # 2-and-4 backbeat whose every other snare the transcription
            # missed also leaves one snare per bar, but its kicks sit one
            # beat either side of that snare (on 1 and 3) and the position
            # opposite it is an empty snare slot.
            opp, _n_opp = _local_offset_hit_rate(snares_raw, k_list, beat_len, 4.0, 2.0)
            before, _n_b = _local_offset_hit_rate(snares_raw, k_list, beat_len, 4.0, -1.0)
            after, _n_a = _local_offset_hit_rate(snares_raw, k_list, beat_len, 4.0, 1.0)
            if opp >= 0.45:
                detail += f", kick two beats from the snare (beat 1) in {opp:.0%} of bars"
            elif opp < 0.25 and before >= 0.5 and after >= 0.5:
                return (
                    "snare once every four beats (one main snare per bar; the kicks sit one beat "
                    "either side of it rather than opposite, so this may be a 2-and-4 backbeat with "
                    "missed snares — not confirmed as a half-time feel)",
                    detail + f", kick one beat before/after the snare in {before:.0%}/{after:.0%} of bars, "
                    f"opposite it in only {opp:.0%}",
                )
        return (
            "half-time backbeat (snare once per bar, on beat 3 — a half-time feel at this tempo; "
            f"counted at half speed, ~{half_bpm:.0f} BPM, it is an ordinary 2-and-4 backbeat)",
            detail,
        )

    if 0.35 <= snares_per_beat <= 0.7 and lock_half >= MODERATE:
        detail = f"~{snares_per_beat:.2f} snares/beat, grid-lock {lock_half:.2f}"
        klock, phase_diff = _phase_vs_kick(kicks, phase_half)
        if phase_diff is not None:
            detail += f", kick/snare phase offset {phase_diff:.2f} (1.0 = opposite the kick)"
            if phase_diff >= 0.7:
                lab = (
                    "classic backbeat (snare falls opposite the kick, e.g. 2 & 4 against kick on 1 & 3)"
                    if lock_half >= STRONG
                    else "mostly classic backbeat (moderate grid-lock; treat as a programmed backbeat, not irregular)"
                )
                return lab, detail
            if phase_diff <= 0.3:
                return "snare doubling the kick's grid position (not a classic backbeat)", detail
            return (
                "snare on a backbeat-rate grid with imperfect opposite-phase lock (still a backbeat-family pattern, not wandering)",
                detail,
            )
        # A kick on EVERY beat has no single phase on a 2-beat cell, so the
        # opposite-phase test above cannot run -- but that is the kick being
        # locked, not the kick being absent. Say so rather than claiming there
        # is no locked kick: snare/clap on alternate beats over an every-beat
        # kick is the standard four-on-the-floor backbeat.
        if kicks and len(kicks) >= 6:
            try:
                kicks_q = _snap_onsets_to_subdivision(
                    sorted(float(k) for k in kicks), beat_len, subdivision=0.25, max_snap_s=0.045
                )
                klock_q, _kp = _lock_and_phase(1.0, _trim_phase_outliers(kicks_q, beat_len, 1.0))
                k_per_beat, _k_span = _active_rate_per_beat(sorted(kicks_q), beat_len)
                # Same beat-coverage test the kick classifier uses before it
                # will say four-on-the-floor. Without it a syncopated kick at
                # about one hit per beat (boom-bap, dembow) was described here
                # as "a kick on every beat" while the kick analysis two lines
                # up said "NOT four-on-the-floor" for the same hits.
                k_cov, _k_on, _k_n = _kick_beat_coverage(sorted(kicks_q), beat_len)
                k_cov = max(k_cov, _local_cell_coverage(sorted(kicks_q), beat_len, 1.0)[0])
            except Exception:
                klock_q, k_per_beat, k_cov = 0.0, 0.0, 0.0
            if klock_q >= MODERATE and 0.8 <= k_per_beat <= 1.25 and k_cov >= 0.70:
                return (
                    "snare/clap on alternate beats over a kick on every beat "
                    "(the usual four-on-the-floor backbeat pairing)",
                    detail + f", kick locked to every beat (grid-lock {klock_q:.2f})",
                )
        lab = (
            "backbeat-rate snare (roughly every other beat; no locked kick to confirm the offset)"
            if lock_half >= STRONG
            else "mostly backbeat-rate snare (moderate grid-lock — not irregular)"
        )
        return lab, detail

    if 0.8 <= snares_per_beat <= 1.25 and lock_quarter >= MODERATE:
        lab = (
            "snare on every beat (dense, not a classic backbeat)"
            if lock_quarter >= STRONG
            else "mostly on-beat snare (moderate grid-lock; dense, not a classic backbeat)"
        )
        return lab, f"~{snares_per_beat:.2f} snares/beat, grid-lock {lock_quarter:.2f}"

    if 1.6 <= snares_per_beat <= 2.4 and lock_eighth >= MODERATE:
        lab = (
            "snare on eighth-note subdivisions (busy/rolled feel)"
            if lock_eighth >= STRONG
            else "mostly eighth-note snare subdivisions (moderate grid-lock — not irregular)"
        )
        return lab, f"~{snares_per_beat:.2f} snares/beat, grid-lock {lock_eighth:.2f}"

    best = max(lock_quarter, lock_half, lock_eighth)
    if best < WEAK:
        return (
            "syncopated / off-grid snare placement",
            f"~{snares_per_beat:.2f} snares/beat, best grid-lock only {best:.2f}",
        )
    if best < MODERATE:
        return (
            "loosely on a snare grid (some timing scatter; not a free-time irregular spray)",
            f"~{snares_per_beat:.2f} snares/beat, best grid-lock {best:.2f}",
        )
    return (
        "snare pattern with moderate grid-lock (rate does not match simple backbeat/on-beat/eighth; prefer texture over 'irregular')",
        f"~{snares_per_beat:.2f} snares/beat, best grid-lock {best:.2f}",
    )


def _detect_swing_feel(onsets, bpm=None, min_hits=10):
    """Detect a genuine swing/shuffle feel from a dense, regular subdivision
    stream (typically the hi-hat, or the snare/kick if the hat is too
    sparse).

    Swing shows up as a *repeating long-short alternation* in adjacent
    inter-onset intervals -- not just spacing variability in general, which
    the existing per-type "spacing-spread" figure already reports and which
    can come from many other things (transcription noise, fills, tempo
    drift) that have nothing to do with swing. This checks specifically for
    an alternating pattern before calling anything swung.

    If bpm is available, the median spacing is also sanity-checked against
    the expected eighth-note length at that tempo, so a stream that isn't
    actually running at roughly 8th-note density doesn't get misread as a
    swing/straight subdivision.

    Returns (label, ratio, detail) or (None, None, None) if there isn't
    enough clean evidence to say.
    """
    if not onsets or len(onsets) < min_hits:
        return None, None, None
    onsets = sorted(float(o) for o in onsets)
    iois = np.diff(onsets)
    if len(iois) < min_hits - 1:
        return None, None, None
    # Drop the gaps where the part stops (breakdowns, section changes) before
    # measuring the subdivision. A handful of multi-second gaps inflated the
    # mean enough to push a real 8th-note stream out of its tempo band, and
    # each gap also counted as a spurious "long" note in the alternation test.
    med_ioi = float(np.median(iois))
    if med_ioi > 0:
        core = iois[iois <= 4.0 * med_ioi]
        if core.size >= max(3, min_hits - 1):
            iois = core
    mean_ioi = float(np.mean(iois))
    if mean_ioi <= 1e-6:
        return None, None, None

    level = ""
    if bpm and bpm > 0:
        # Mean, not median: for a long/short subdivision the mean is exactly
        # the half-beat regardless of the swing ratio (long+short always
        # sums to one beat), whereas the median can skew toward whichever
        # value happens to be in the majority by one sample and drift away
        # from the true subdivision size. A tighter band than the raw
        # regularity check below, so this specifically catches streams that
        # aren't running at roughly 8th-note density (e.g. plain quarter
        # notes) rather than mislabeling them straight-8ths.
        expected_8th = 30.0 / bpm  # (60/bpm) / 2
        if 0.55 * expected_8th <= mean_ioi <= 1.8 * expected_8th:
            level = ""
        elif 0.55 * (expected_8th / 2.0) <= mean_ioi < 0.55 * expected_8th:
            # A 16th-note stream (busy hats in pop, hip-hop, funk). This used to
            # be rejected outright, so the most common modern hat pattern never
            # got a straight/swung read at all -- and swung 16ths, the defining
            # feel of a lot of hip-hop and neo-soul, could not be reported.
            level = "16th-note "
        else:
            return None, None, None

    # Only trust this on an already fairly regular subdivision stream (no
    # wild outliers like a dropped beat or a fill breaking the pattern).
    # Bounds are set relative to the mean rather than the median: a real
    # heavy shuffle (e.g. a 3:1 long/short ratio) skews the median toward
    # whichever of the two values happens to be in the majority by one
    # sample, which can push its own short notes just outside a
    # median-centred tolerance band and get an otherwise clean shuffle
    # rejected as "irregular".
    within_range = np.sum((iois > 0.25 * mean_ioi) & (iois < 4.0 * mean_ioi))
    if within_range / len(iois) < 0.6:
        return None, None, None

    # Split around the mean, not the median: for a genuine ~50/50 long/short
    # alternation, the median of the combined sequence often lands exactly
    # on one of the two discrete values (whichever is in the majority by a
    # single sample), which would misclassify that entire bucket as
    # "not different enough" from the threshold. The mean sits strictly
    # between two distinct values and doesn't have that failure mode.
    long_mask = iois > mean_ioi
    short_mask = ~long_mask

    if not long_mask.any() or not short_mask.any():
        return "straight", 1.0, "no clear long/short contrast; straight subdivision"

    labels = np.where(long_mask, 1, -1)
    alt_frac = float(np.sum(labels[1:] != labels[:-1]) / (len(labels) - 1))
    long_vals = iois[long_mask]
    short_vals = iois[short_mask]
    ratio = float(np.mean(long_vals) / np.mean(short_vals))

    sub_note = f" ({level.strip()} subdivision)" if level else ""
    if alt_frac < 0.55:
        return "straight", ratio, f"long/short IOIs don't alternate consistently ({alt_frac:.2f}); reads as straight, not swung{sub_note}"

    if ratio < 1.15:
        label = "straight"
    elif ratio < 1.5:
        label = f"light {level}swing/shuffle"
    elif ratio < 2.2:
        label = f"moderate-to-triplet {level}swing"
    else:
        label = f"heavy {level}shuffle / dotted-note feel"

    return label, ratio, f"long:short IOI ratio ~{ratio:.2f}, alternation consistency {alt_frac:.2f}{sub_note}"


def _drum_band_limit(seg, sr, lo, hi):
    """Zero-phase FFT band-limit. numpy-only, so this adds no dependency.

    Essential rather than cosmetic: a drums stem is a MIX of the whole kit, so
    the window around a kick also contains whatever snare, hat or cymbal
    happens to land nearby. Measured broadband, a kick's 'decay' is frequently
    just the snare on the next beat -- in testing, the loudest point inside the
    first kick's own window was the snare 502 ms later, so every kick decay and
    every consistency score was actually describing a different drum. Measuring
    each drum inside its own frequency band removes that.
    """
    seg = np.asarray(seg, dtype=np.float64)
    if seg.size < 32:
        return seg
    spec = np.fft.rfft(seg)
    freqs = np.fft.rfftfreq(seg.size, 1.0 / sr)
    mask = np.ones(spec.shape, dtype=bool)
    if lo is not None:
        mask &= (freqs >= lo)
    if hi is not None:
        mask &= (freqs <= hi)
    spec = spec * mask
    return np.fft.irfft(spec, n=seg.size)


# Frequency ranges each drum is measured in. Chosen to keep the neighbours out:
# the kick band stops below a typical snare fundamental (~180-200 Hz), and the
# hat band starts above where snare body lives.
_DRUM_ANALYSIS_BANDS = {
    "kick": (30.0, 150.0),
    "snare": (150.0, 6000.0),
    "hihat": (6000.0, 16000.0),
    "tom": (60.0, 1200.0),
    "cymbal": (3000.0, 16000.0),
}


# Which drums put energy into each drum's own analysis band (see
# _DRUM_ANALYSIS_BANDS). A tone/decay window only has to stop at these.
_DRUM_WINDOW_CONFLICTS = {
    "kick": ("kick", "snare", "tom"),
    "snare": ("snare", "kick", "tom", "cymbal"),
    "hihat": ("hihat", "cymbal", "snare"),
}


def _drum_hit_windows(y, sr, onsets, pre=0.005, post=0.25, all_onsets=None,
                      band=None, min_gap=0.03):
    """Slice the drums stem around each transcribed hit.

    `all_onsets`: every hit in the stem regardless of type. Each window is
    truncated before the next hit of ANY drum so a neighbouring hit cannot be
    mistaken for the tail of this one.
    `band`: (lo, hi) to band-limit the slice to this drum's own range.
    """
    out = []
    n = len(y)
    nxt = np.asarray(sorted(all_onsets), dtype=float) if all_onsets else None
    for t in onsets:
        t = float(t)
        a = int(max(0, (t - pre) * sr))
        limit = t + post
        if nxt is not None and nxt.size:
            i = int(np.searchsorted(nxt, t + min_gap))
            if i < nxt.size:
                limit = min(limit, float(nxt[i]))
        b = int(min(n, limit * sr))
        if b - a > int(sr * 0.02):
            seg = y[a:b]
            if band is not None:
                try:
                    seg = _drum_band_limit(seg, sr, band[0], band[1])
                except Exception:
                    pass
            out.append(seg)
    return out


def _drum_decay_ms(seg, sr, drop_db=20.0):
    """Time from a hit's peak until it falls drop_db below that peak.
    Separates a tight gated snare or short acoustic kick from a long 808 tail."""
    if seg is None or len(seg) < 16:
        return None
    seg = np.asarray(seg, dtype=np.float64)
    # Amplitude envelope. This used to be |x| smoothed over 2 ms, which on a
    # low-pitched hit is not an envelope at all: a 60-80 Hz kick has a zero
    # crossing every ~7 ms, the 2 ms average dips deep at each one, and the
    # "-20 dB point" was simply the first dip once the hit had decayed a few
    # dB -- a kick with a 276 ms decay measured ~90 ms. The analytic-signal
    # magnitude follows the true envelope regardless of pitch.
    try:
        from scipy.signal import hilbert as _hilbert
        env = np.abs(_hilbert(seg))
    except Exception:
        env = np.abs(seg)
    win = max(1, int(sr * 0.003))
    if win > 1:
        env = np.convolve(env, np.ones(win) / win, mode="same")
    pk = int(np.argmax(env))
    peak = float(env[pk])
    if peak <= 1e-8:
        return None
    thresh = peak * (10.0 ** (-drop_db / 20.0))
    tail = env[pk:]
    below = np.flatnonzero(tail <= thresh)
    if below.size:
        return float(below[0]) / sr * 1000.0
    # The window ended before the hit fell drop_db. Discarding those hits (the
    # old behaviour) kept only the fastest-decaying ones and biased the median
    # short. Extrapolate the log-linear decay instead, when there is enough
    # tail to fit and it is clearly falling.
    if tail.size < int(sr * 0.03):
        return None
    t = np.arange(tail.size) / float(sr)
    db = 20.0 * np.log10(np.maximum(tail, peak * 1e-6) / peak)
    try:
        slope = float(np.polyfit(t, db, 1)[0])          # dB per second
    except Exception:
        return None
    if slope >= -3.0 or float(db[-1]) > -3.0:
        return None
    return float(min(2000.0, (-drop_db / slope) * 1000.0))


def _drum_centroid_hz(seg, sr):
    """Spectral centroid of one hit. n_fft is sized to the slice: hit windows
    are routinely shorter than librosa's 2048 default, which otherwise emits a
    warning per hit and floods the console during a scan."""
    if seg is None or len(seg) < 64:
        return None
    try:
        seg = np.asarray(seg, dtype=np.float32)
        n_fft = int(min(2048, 2 ** int(np.floor(np.log2(max(64, len(seg)))))))
        return float(np.mean(librosa.feature.spectral_centroid(
            y=seg, sr=sr, n_fft=n_fft, hop_length=max(1, n_fft // 4))))
    except Exception:
        return None


def _drum_fundamental_hz(seg, sr, fmax=250.0):
    """Dominant low-frequency partial of a kick hit -- the difference between
    a sub-heavy 808 (~40-55 Hz) and a punchy acoustic kick (~60-100 Hz)."""
    if seg is None or len(seg) < 256:
        return None
    try:
        n_fft = 4096
        seg = np.asarray(seg, dtype=np.float32)
        if len(seg) < n_fft:
            seg = np.pad(seg, (0, n_fft - len(seg)))
        spec = np.abs(np.fft.rfft(seg[:n_fft] * np.hanning(n_fft)))
        freqs = np.fft.rfftfreq(n_fft, 1.0 / sr)
        mask = (freqs >= 25.0) & (freqs <= fmax)
        if not np.any(mask) or float(np.max(spec[mask])) <= 0:
            return None
        return float(freqs[mask][int(np.argmax(spec[mask]))])
    except Exception:
        return None


def _isolated_onsets(onsets, conflicting_onsets, guard=0.045):
    """Hits with no CONFLICTING drum landing within `guard` seconds either side.

    Consistency is only meaningful on hits that aren't overlapping something
    else in the same frequency range: a kick that always coincides with a
    snare carries that snare's variation into its own score.

    Only genuinely conflicting drums are passed in, not the whole kit.
    Requiring total isolation is useless in practice -- a hi-hat lands on
    almost every kick in most music, so a strict test finds zero usable hits
    and the measurement silently disappears. A hat sits far above the band the
    kick is measured in, so it does not conflict; a snare or tom does.
    """
    if not conflicting_onsets:
        return list(onsets)
    arr = np.asarray(sorted(conflicting_onsets), dtype=float)
    out = []
    for t in onsets:
        t = float(t)
        lo = np.searchsorted(arr, t - guard, side="left")
        hi = np.searchsorted(arr, t + guard, side="right")
        # No conflicting drum anywhere in the guard window.
        if hi - lo == 0:
            out.append(t)
    return out


def _drum_hit_consistency(segs, sr, max_hits=60):
    """How alike successive hits of the same drum are.

    Programmed/sampled drums retrigger the same waveform, so their spectra are
    near-identical hit to hit; a human hitting a real drum varies. Returns the
    mean pairwise cosine similarity of consecutive hits' log-magnitude spectra
    (1.0 = identical). This is the closest thing to an objective
    programmed-vs-played signal available from the audio, and nothing in the
    pipeline measured it -- 'programmed drums' was previously a genre-driven
    assumption.

    Feed this WIDE-band, isolated hits. Restricted to a kick's 30-150 Hz band
    the metric barely discriminates, because the low fundamental of a real
    played kick is nearly as repeatable as a sampled one -- what actually
    varies hit to hit is the attack/beater content higher up. Measured that
    way a live kit scored 0.98 and was reported as 'retriggered sample',
    which is exactly the wrong answer.
    """
    segs = [s for s in segs if s is not None and len(s) >= 512][:max_hits]
    if len(segs) < 4:
        return None
    n_fft = 1024
    specs = []
    for s in segs:
        s = np.asarray(s[:n_fft], dtype=np.float32)
        if len(s) < n_fft:
            s = np.pad(s, (0, n_fft - len(s)))
        mag = np.abs(np.fft.rfft(s * np.hanning(n_fft)))
        mag = np.log1p(mag)
        nrm = float(np.linalg.norm(mag))
        if nrm > 1e-9:
            specs.append(mag / nrm)
    if len(specs) < 4:
        return None
    sims = [float(np.dot(specs[i], specs[i + 1])) for i in range(len(specs) - 1)]
    return float(np.median(sims))


def _consistency_note(cons):
    """Wording for a hit-consistency score.

    Only the extremes are asserted. The middle of this range is deliberately
    left ambiguous: a tightly played, well-recorded kit and a sample-replaced
    one both sit around 0.98-0.99, and the absolute thresholds here have been
    validated on synthetic kits rather than on a corpus of real recordings.
    Claiming "programmed" from a mid-range score would turn a genuine
    measurement back into the guess it was meant to replace.
    """
    if cons is None:
        return ""
    if cons >= 0.995:
        return ("hits are essentially identical — a retriggered sample; "
                "safe to call this programmed/sequenced")
    if cons >= 0.97:
        return ("hits are very repeatable — consistent with programming or "
                "sample-replacement, but also with a tightly played, closely "
                "miked kit; do not assert programmed on this number alone")
    if cons >= 0.93:
        return "hits vary noticeably — played, or programmed with round-robin/humanisation"
    return "hits vary a lot — played, or heavily processed/varied per hit"


def build_drum_production_report(drums_stem_path, hits, bpm=None):
    """Sonic/production character of the kit, measured from the drums stem.

    The pipeline already described WHAT the drummer plays (rates, grid, swing)
    but nothing about how the kit SOUNDS -- whether the kick is a sub-heavy
    808 or a tight acoustic thud, whether the snare is gated or roomy, how
    hard the bus is compressed, whether the hits are retriggered samples or
    played. Those are exactly the production questions TIMBRE and the era/genre
    prompts ask about, and they were being answered from genre expectation.

    Returns "" when it cannot measure anything. Every measurement is
    independent and failure-isolated.
    """
    if not drums_stem_path or not hits:
        return ""
    if not os.path.exists(str(drums_stem_path)):
        return ""

    try:
        y, sr = librosa.load(drums_stem_path, sr=None, mono=True)
    except Exception:
        return ""
    if y is None or len(y) < 1000:
        return ""

    by_type = {}
    for h in hits:
        t = h.get("drum_type") or "other"
        by_type.setdefault(t, []).append(float(h["onset"]))

    # Every hit in the stem, used to stop each analysis window before the next
    # drum lands (see _drum_hit_windows).
    all_onsets = sorted(float(h["onset"]) for h in hits if h.get("onset") is not None)

    # Tone/decay windows are band-limited, so they only need to stop at hits
    # that put energy into the SAME band. Truncating a kick's 30-150 Hz window
    # at the next hi-hat (often 100-200 ms later) cut almost every kick off
    # before it could decay, which is half of why kick decays read so short.
    def _conflict_onsets(kind):
        kinds = _DRUM_WINDOW_CONFLICTS.get(kind)
        if not kinds:
            return all_onsets
        return sorted(t for k in kinds for t in (by_type.get(k) or []))

    lines = []

    # --- Kick character -----------------------------------------------------
    kicks = sorted(by_type.get("kick") or [])
    if len(kicks) >= 4:
        segs = _drum_hit_windows(
            y, sr, kicks[:80], post=0.6, all_onsets=_conflict_onsets("kick"),
            band=_DRUM_ANALYSIS_BANDS["kick"],
        )
        decays = [d for d in (_drum_decay_ms(s, sr) for s in segs) if d]
        fundamentals = [f for f in (_drum_fundamental_hz(s, sr) for s in segs) if f]
        parts = []
        if fundamentals:
            f0 = float(np.median(fundamentals))
            parts.append(f"fundamental ~{f0:.0f} Hz")
            if f0 < 50:
                parts.append("sub-heavy (808/synth-bass-drum territory)")
            elif f0 < 70:
                parts.append("deep, weighted low end")
            elif f0 < 110:
                parts.append("punchy, midweight kick")
            else:
                parts.append("light/high-tuned kick")
        if decays:
            d = float(np.median(decays))
            parts.append(f"-20 dB decay ~{d:.0f} ms")
            if d > 300:
                parts.append("long sustained tail (808-style)")
            elif d > 120:
                parts.append("moderate tail")
            else:
                parts.append("tight/damped")
        if parts:
            lines.append("kick sound: " + "; ".join(parts))
        # Consistency uses isolated hits over a wide band: the attack content is
        # where a played kit differs from a retriggered sample, and it lives
        # well above the 30-150 Hz band used for tone measurements above.
        kick_conflicts = sorted(
            (by_type.get("snare") or []) + (by_type.get("tom") or [])
            + (by_type.get("cymbal") or [])
        )
        iso = _isolated_onsets(kicks, kick_conflicts)
        if len(iso) >= 4:
            cons = _drum_hit_consistency(
                _drum_hit_windows(y, sr, iso[:80], post=0.25,
                                  all_onsets=all_onsets, band=(30.0, 2500.0)),
                sr,
            )
            if cons is not None:
                lines.append(
                    f"kick hit-to-hit consistency: {cons:.3f} "
                    f"({_consistency_note(cons)}; measured on {len(iso)} isolated hits)"
                )

    # --- Snare / backbeat character ----------------------------------------
    snares = sorted(by_type.get("snare") or [])
    if len(snares) >= 4:
        segs = _drum_hit_windows(
            y, sr, snares[:80], post=0.5, all_onsets=_conflict_onsets("snare"),
            band=_DRUM_ANALYSIS_BANDS["snare"],
        )
        decays = [d for d in (_drum_decay_ms(s, sr) for s in segs) if d]
        cents = [c for c in (_drum_centroid_hz(s, sr) for s in segs) if c]
        parts = []
        if cents:
            c = float(np.median(cents))
            parts.append(f"brightness ~{c:.0f} Hz centroid")
            parts.append("bright//crisp or clap-like" if c > 3500 else
                         "midrange-weighted, bodied" if c > 1800 else "dark/thick")
        if decays:
            d = float(np.median(decays))
            parts.append(f"-20 dB decay ~{d:.0f} ms")
            if d < 80:
                parts.append("very tight — gated or heavily damped")
            elif d < 200:
                parts.append("controlled, modern-dry")
            else:
                parts.append("open with audible tail/room")
        if parts:
            lines.append("snare/backbeat sound: " + "; ".join(parts))
        # The kick sits below this band, so it is not a conflict for the snare.
        snare_conflicts = sorted(
            (by_type.get("tom") or []) + (by_type.get("cymbal") or [])
        )
        iso_s = _isolated_onsets(snares, snare_conflicts)
        if len(iso_s) >= 4:
            cons = _drum_hit_consistency(
                _drum_hit_windows(y, sr, iso_s[:80], post=0.25,
                                  all_onsets=all_onsets, band=(150.0, 9000.0)),
                sr,
            )
            if cons is not None:
                lines.append(
                    f"snare hit-to-hit consistency: {cons:.3f} "
                    f"({_consistency_note(cons)}; measured on {len(iso_s)} isolated hits)"
                )

    # --- Hats ---------------------------------------------------------------
    hats = sorted(by_type.get("hihat") or [])
    if len(hats) >= 6:
        segs = _drum_hit_windows(
            y, sr, hats[:80], post=0.15, all_onsets=_conflict_onsets("hihat"),
            band=_DRUM_ANALYSIS_BANDS["hihat"],
        )
        cents = [c for c in (_drum_centroid_hz(s, sr) for s in segs) if c]
        decays = [d for d in (_drum_decay_ms(s, sr, drop_db=15.0) for s in segs) if d]
        parts = []
        if cents:
            c = float(np.median(cents))
            parts.append(f"brightness ~{c:.0f} Hz centroid")
            parts.append("very bright/thin" if c > 8000 else
                         "bright" if c > 5500 else "darker/filtered")
        if decays:
            parts.append(f"typical ring ~{float(np.median(decays)):.0f} ms")
        if parts:
            lines.append("hi-hat sound: " + "; ".join(parts))

    # --- Whole-kit dynamics -------------------------------------------------
    # Hit levels must be MEASURED from the audio (amplitude_source set by
    # _attach_measured_amplitudes, or the onset fallback's own envelope). The
    # drum transcriber writes velocity 100 for every hit, so the old line --
    # computed from that constant -- reported "0.00, machine-like/quantized
    # dynamics" for every track, played or programmed. Spread is taken per
    # drum and then combined, because pooling kicks with hi-hats measures the
    # level difference between drums, not how evenly each one is played.
    try:
        per_type = {}
        for h in hits:
            src = h.get("amplitude_source")
            if src != "stem audio" and h.get("detected_from") != "onset-band fallback":
                continue
            dt = h.get("drum_type")
            if dt in ("kick", "snare", "hihat") and h.get("amplitude") is not None:
                per_type.setdefault(dt, []).append(float(h["amplitude"]))
        spreads = {
            dt: float(np.percentile(v, 90) - np.percentile(v, 10))
            for dt, v in per_type.items() if len(v) >= 8
        }
        if spreads:
            spread = float(np.median(list(spreads.values())))
            detail = ", ".join(
                f"{ {'hihat': 'hi-hat'}.get(dt, dt)} {v:.2f}" for dt, v in sorted(spreads.items())
            )
            lines.append(
                f"hit-level spread measured from the drums audio (90th-10th pct, per drum): "
                f"{detail} "
                + ("— nearly uniform; machine-like/quantized dynamics"
                   if spread < 0.12 else
                   "— some accenting, but controlled" if spread < 0.30 else
                   "— wide dynamic accenting, human-feeling")
            )
    except Exception:
        pass

    # Drum-bus crest: how hard the kit itself is compressed, independent of the
    # whole-mix loudness figures (which the bass and synths dominate). RMS is
    # taken over the passages where the kit is actually playing: averaging in
    # drum-free intros and breakdowns lowered the RMS and inflated the crest,
    # pushing every arrangement with a drum-less section toward "open, lightly
    # compressed".
    try:
        peak = float(np.max(np.abs(y)))
        yy = y.astype(np.float64)
        fr = librosa.feature.rms(y=y, frame_length=2048, hop_length=512)[0].astype(np.float64)
        active = fr >= (float(np.max(fr)) * 10.0 ** (-35.0 / 20.0)) if fr.size else fr
        if fr.size and np.any(active):
            rms = float(np.sqrt(np.mean(np.square(fr[active]))))
        else:
            rms = float(np.sqrt(np.mean(np.square(yy))))
        if peak > 1e-6 and rms > 1e-9:
            crest = 20.0 * np.log10(peak / rms)
            lines.append(
                f"drum-bus peak-to-RMS (while the kit is playing): {crest:.1f} dB "
                + ("— very squashed; heavy bus compression/limiting on the kit"
                   if crest < 10 else
                   "— moderately compressed kit" if crest < 15 else
                   "— open, lightly compressed kit with intact transients")
            )
    except Exception:
        pass

    if not lines:
        return ""

    return (
        "DRUM SOUND / PRODUCTION (objective, measured from the separated drums stem):\n"
        "These describe how the kit SOUNDS, not what it plays. Use them for questions about "
        "drum tone, punch, room, and whether the kit is programmed or played. Note the stem "
        "comes from source separation, so faint bleed from other instruments is possible — "
        "treat these as strong indicators rather than absolute values.\n"
        + "\n".join(lines)
    )


def _summarize_drum_rhythm(filtered, max_pattern_hits=32, bpm=None):
    """Compact groove description from drum hits — no full event list needed.

    Returns lines covering:
      - per-type rates and typical spacing
      - a short pattern sample (types only) sampled across the track
      - kick/snare relationship (backbeat vs on-beat)
      - hat density / openness proxy
      - a kick-grid classification (four-on-the-floor / half-time / eighth-
        note / syncopated), grounded in the track's actual tempo rather than
        a raw hit-rate guess, when bpm is available
      - a snare-grid classification (classic backbeat / doubling the kick /
        every-beat / eighth-note / syncopated), also tempo-grounded, and
        phase-checked against the kick when both are grid-locked
      - a swing/shuffle read from the densest subdivision stream, based on
        long-short IOI alternation rather than raw spacing variability
      - a short GROOVE_HINT line the writer can paraphrase instead of
        collapsing to "driving drums" / "tight backbeat"
    """
    if not filtered:
        return []

    by_type = {}
    for n in filtered:
        t = n.get("drum_type") or "other"
        by_type.setdefault(t, []).append(float(n["onset"]))

    # Grid judgements below measure phase against the tempo; fit that tempo to
    # the kit itself first so rounding in the reported BPM cannot masquerade as
    # syncopation (see _refine_bpm_from_onsets). Only the transcribed kit
    # pieces are used -- audio-detected cymbals and percussion are sparser and
    # less precisely timed.
    if bpm:
        _fit_onsets = []
        for _k in ("kick", "snare", "hihat", "hi-hat"):
            _fit_onsets.extend(by_type.get(_k) or [])
        bpm = _refine_bpm_from_onsets(_fit_onsets, bpm)

    lines = []
    rate_parts = []
    type_rates = {}
    for drum_type, onsets in sorted(by_type.items(), key=lambda kv: -len(kv[1])):
        onsets = sorted(onsets)
        if len(onsets) < 2:
            rate_parts.append(f"{drum_type}: {len(onsets)} hit(s)")
            type_rates[drum_type] = 0.0
            continue
        intervals = np.diff(onsets)
        med_ibi = float(np.median(intervals))
        rate = 60.0 / med_ibi if med_ibi > 1e-6 else 0.0
        type_rates[drum_type] = rate
        # Spacing variability as a crude swing/looseness proxy.
        if len(intervals) >= 4:
            iqr = float(np.percentile(intervals, 75) - np.percentile(intervals, 25))
            cv = (iqr / med_ibi) if med_ibi > 1e-6 else 0.0
            rate_parts.append(
                f"{drum_type}: {len(onsets)} hits, ~{rate:.1f}/min, "
                f"median spacing {med_ibi:.3f}s, spacing-spread {cv:.2f}"
            )
        else:
            rate_parts.append(
                f"{drum_type}: {len(onsets)} hits, ~{rate:.1f}/min, median spacing {med_ibi:.3f}s"
            )
    if rate_parts:
        lines.append("per-type rhythm: " + "; ".join(rate_parts))

    # Pattern sample: evenly spaced hits across the track, types only.
    ordered = sorted(filtered, key=lambda n: float(n["onset"]))
    sample = _evenly_sample_notes(ordered, max_pattern_hits)
    pattern = " ".join(
        (n.get("drum_type") or _drum_band_label(float(n.get("frequency", 300.0))))
        for n in sample
    )
    if pattern:
        lines.append(
            f"hit pattern sample ({len(sample)} hits across track): {pattern}"
        )

    kicks = by_type.get("kick") or []
    snares = by_type.get("snare") or []
    hihats = by_type.get("hihat") or by_type.get("hi-hat") or []
    cymbals = by_type.get("cymbal") or []
    toms = by_type.get("tom") or []

    backbeat_frac = None
    kick_ibi = None
    # The kick pulse does not depend on the snare. It used to be measured only
    # when snares were present too, so a snare-less passage (kick + hats verse)
    # lost its hat-density figure and was told there was "no stable kick pulse".
    if len(kicks) >= 4:
        kick_ibi = float(np.median(np.diff(sorted(kicks))))
        if not (kick_ibi > 0):
            kick_ibi = None
    if len(kicks) >= 4 and len(snares) >= 2:
        # Rough backbeat check: snares often sit near midpoint between kicks.
        mid_hits = 0
        for s in snares:
            prev = [k for k in kicks if k <= s]
            nxt = [k for k in kicks if k > s]
            if not prev or not nxt:
                continue
            span = nxt[0] - prev[-1]
            if span <= 0:
                continue
            pos = (s - prev[-1]) / span
            if 0.35 <= pos <= 0.65:
                mid_hits += 1
        backbeat_frac = mid_hits / max(1, len(snares))
        if kick_ibi and kick_ibi > 0:
            lines.append(
                f"kick/snare relationship: kick median spacing {kick_ibi:.3f}s; "
                f"~{mid_hits}/{len(snares)} snares near mid-interval "
                f"({backbeat_frac * 100:.0f}% backbeat-like) between surrounding kicks"
            )

    # Hat density relative to kick pulse.
    hat_vs_kick = None
    # Hat subdivision measured against the BEAT when the tempo is known. The
    # kick-relative ratio alone mislabels the most common pattern in pop and
    # rock: 8th-note hats over a half-time kick (kicks on 1 and 3) come out as
    # "4x the kick pulse" and were reported as 16th-note hat work.
    hat_per_beat = None
    hat_med = None
    if len(hihats) >= 2:
        _hd = np.diff(sorted(hihats))
        _hd = _hd[_hd > 1e-6]
        if _hd.size:
            hat_med = float(np.median(_hd))
    if hat_med and bpm:
        try:
            hat_per_beat = (60.0 / float(bpm)) / hat_med
        except (TypeError, ValueError, ZeroDivisionError):
            hat_per_beat = None
    if hihats and kicks and kick_ibi and kick_ibi > 0:
        if hat_med and hat_med > 1e-6:
            hat_vs_kick = kick_ibi / hat_med
            if hat_per_beat is not None:
                density_word = (
                    "very dense (16th-note hats)" if hat_per_beat >= 3.2
                    else "busy (8th-note hats)" if hat_per_beat >= 1.6
                    else "quarter-note hats, one per beat" if hat_per_beat >= 0.8 and hat_per_beat < 1.2
                    else "sparse / on the beat" if hat_per_beat < 0.8
                    else "moderate"
                )
            else:
                density_word = (
                    "very dense (8th/16th-ish)" if hat_vs_kick >= 3.2
                    else "busy (around 8ths)" if hat_vs_kick >= 1.8
                    else "sparse / on the beat" if hat_vs_kick < 1.2
                    else "moderate"
                )
            per_beat_txt = (
                f", ~{hat_per_beat:.1f} per beat" if hat_per_beat is not None else ""
            )
            lines.append(
                f"hi-hat density vs kick pulse: ~{hat_vs_kick:.1f}x{per_beat_txt} "
                f"({density_word}; {len(hihats)} hat hits)"
            )
    elif hihats:
        if hat_per_beat is not None:
            lines.append(
                f"hi-hat activity: {len(hihats)} hits, ~{hat_per_beat:.1f} per beat "
                "(no stable kick pulse for a kick-relative ratio)"
            )
        else:
            lines.append(f"hi-hat activity: {len(hihats)} hits (no stable kick pulse for ratio)")

    # Fill / tom activity as a density proxy (not precise fill detection).
    if toms or cymbals:
        lines.append(
            f"tom/cymbal activity: toms={len(toms)}, cymbals={len(cymbals)} "
            f"(elevated counts often mean fills or open cymbal work)"
        )

    # Finer kit breakdown. The buckets above collapse a lot of detail that a
    # listener plainly hears -- open vs closed hats, ride vs crash, a clap
    # standing in for a snare, which tom -- so where the transcription
    # identified the specific instrument, report it. This is additive: the
    # groove statistics above still use the coarse buckets.
    subtype_counts = {}
    for n in filtered:
        st = n.get("drum_subtype")
        if st:
            subtype_counts[st] = subtype_counts.get(st, 0) + 1
    if subtype_counts:
        ranked_sub = sorted(subtype_counts.items(), key=lambda kv: -kv[1])
        lines.append(
            "kit detail (specific instruments identified in the transcription): "
            + ", ".join(f"{name} x{count}" for name, count in ranked_sub[:12])
        )
        open_hats = subtype_counts.get("open hi-hat", 0)
        closed_hats = subtype_counts.get("closed hi-hat", 0)
        if open_hats and closed_hats:
            lines.append(
                f"hi-hat articulation: {closed_hats} closed vs {open_hats} open "
                f"({open_hats / float(open_hats + closed_hats) * 100:.0f}% open) "
                "-- open hats on the off-beats are a house/dance signature; "
                "sparse opens usually mark section ends or accents"
            )
        elif closed_hats and not open_hats:
            lines.append("hi-hat articulation: closed throughout (no open hats transcribed)")
        claps = subtype_counts.get("hand clap", 0)
        real_snare = subtype_counts.get("acoustic snare", 0) + subtype_counts.get("electric snare", 0)
        if claps and claps >= real_snare:
            lines.append(
                f"backbeat voice: hand claps ({claps}) rather than (or layered over) a struck "
                f"snare ({real_snare}) -- describe the backbeat as claps, not as a snare"
            )
        rides = subtype_counts.get("ride cymbal", 0) + subtype_counts.get("ride cymbal 2", 0) \
            + subtype_counts.get("ride bell", 0)
        crashes = subtype_counts.get("crash cymbal", 0) + subtype_counts.get("crash cymbal 2", 0)
        if rides or crashes:
            lines.append(
                f"cymbal voices: ride/bell hits={rides}, crash hits={crashes} "
                "(a sustained ride pattern is a different groove from occasional crashes)"
            )
        aux = {k: v for k, v in subtype_counts.items() if k in (
            "tambourine", "cowbell", "shaker", "claves", "conga", "bongo",
            "high bongo", "low bongo", "muted high conga", "open high conga",
            "low conga", "high timbale", "low timbale", "cabasa", "maracas",
            "triangle", "open triangle", "muted triangle", "wood block",
            "high wood block", "low wood block", "guiro",
        )}
        if aux:
            lines.append(
                "auxiliary percussion present: "
                + ", ".join(f"{k} x{v}" for k, v in sorted(aux.items(), key=lambda kv: -kv[1]))
            )

    # Grid-sensitive judgements (swing, kick grid, snare grid) are made on a
    # tempo-steadied timeline when the playing drifts. The rate/spacing lines
    # above keep the real timestamps. See _tempo_warp_onsets.
    g_kicks, g_snares, g_hihats = kicks, snares, hihats
    if bpm:
        try:
            _warp = _tempo_warp_onsets(list(kicks) + list(snares) + list(hihats), bpm)
        except Exception:
            _warp = None
        if _warp is not None:
            g_kicks = sorted(_warp(t) for t in kicks)
            g_snares = sorted(_warp(t) for t in snares)
            g_hihats = sorted(_warp(t) for t in hihats)

    # Swing/shuffle: use the densest available subdivision stream (hi-hat
    # first, since it's normally the clearest subdivision voice; fall back
    # to snare or kick if the hat is too sparse to judge).
    swing_label, swing_ratio, swing_detail = None, None, None
    for _cand_onsets in (g_hihats, g_snares, g_kicks):
        if _cand_onsets and len(_cand_onsets) >= 10:
            swing_label, swing_ratio, swing_detail = _detect_swing_feel(_cand_onsets, bpm=bpm)
            if swing_label:
                break
    if swing_label:
        lines.append(f"swing/shuffle analysis: {swing_label} ({swing_detail})")

    # Human-readable groove hint the writer should paraphrase, not ignore.
    groove_bits = []
    kick_rate = type_rates.get("kick") or 0.0
    snare_rate = type_rates.get("snare") or 0.0
    hat_rate = type_rates.get("hihat") or type_rates.get("hi-hat") or 0.0

    kick_grid_label, kick_grid_detail = _classify_kick_grid(g_kicks, bpm)
    if kick_grid_label:
        lines.append(f"kick beat-grid analysis: {kick_grid_label} ({kick_grid_detail})")
        groove_bits.append(kick_grid_label)
    elif kick_rate >= 100:
        # No tempo available to test grid-lock — fall back to a hedged,
        # rate-only description rather than naming a specific pattern.
        groove_bits.append("fast kick activity (rate-only estimate; no tempo to confirm the grid)")
    elif kick_rate >= 25:
        groove_bits.append("moderate kick activity (rate-only estimate; no tempo to confirm the grid)")
    elif kick_rate > 0:
        groove_bits.append("sparse kick activity (rate-only estimate; no tempo to confirm the grid)")

    if backbeat_frac is not None:
        if backbeat_frac >= 0.55:
            groove_bits.append("clear backbeat snare")
        elif backbeat_frac <= 0.25:
            groove_bits.append("snare often off the classic backbeat / on-beat emphasis")
        else:
            groove_bits.append("mixed backbeat and off-backbeat snare placement")

    snare_grid_label, snare_grid_detail = _classify_snare_grid(g_snares, bpm, kicks=g_kicks)
    if snare_grid_label:
        lines.append(f"snare beat-grid analysis: {snare_grid_label} ({snare_grid_detail})")
        # This is the more rigorous, tempo-grounded read -- prefer it over
        # the plain midpoint-fraction groove bit above when both are present.
        if groove_bits and groove_bits[-1] in (
            "clear backbeat snare",
            "snare often off the classic backbeat / on-beat emphasis",
            "mixed backbeat and off-backbeat snare placement",
        ):
            groove_bits[-1] = snare_grid_label
        else:
            groove_bits.append(snare_grid_label)

    if hat_per_beat is not None and len(hihats) >= 8:
        if hat_per_beat >= 3.2:
            groove_bits.append("busy closed-hat or 16th-note hat work")
        elif hat_per_beat >= 1.6:
            groove_bits.append("regular 8th-note hat layer")
        elif 0.8 <= hat_per_beat < 1.2:
            groove_bits.append("quarter-note hat pulse (one hat per beat)")
        elif hat_per_beat < 0.8:
            groove_bits.append("open or sparse hat / little continuous hat bed")
    elif hat_vs_kick is not None:
        if hat_vs_kick >= 3.2:
            groove_bits.append("busy closed-hat or 16th-note hat work")
        elif hat_vs_kick >= 1.8:
            groove_bits.append("regular 8th-note hat layer")
        elif hat_vs_kick < 1.2:
            groove_bits.append("open or sparse hat / little continuous hat bed")
    elif hat_rate >= 120:
        groove_bits.append("high hat hit rate (busy top end)")
    elif hat_rate > 0 and hat_rate < 30:
        groove_bits.append("minimal hat activity")

    if len(toms) >= max(6, int(0.08 * len(filtered))):
        groove_bits.append("noticeable tom/fill activity")
    if len(cymbals) >= max(8, int(0.1 * len(filtered))):
        groove_bits.append("frequent cymbal crashes/rides")

    if swing_label:
        groove_bits.append(
            "straight (unswung) subdivision feel" if swing_label == "straight" else f"{swing_label} feel"
        )

    if groove_bits:
        lines.append(
            "GROOVE_HINT (paraphrase in ordinary language; do not say "
            "'driving drums' / 'tight backbeat' unless the pattern matches, "
            "do not say 'four-on-the-floor' unless the kick beat-grid analysis "
            "reports it, do not say 'backbeat' unless the snare beat-grid "
            "analysis reports a classic backbeat, and do not say 'swung' / "
            "'shuffled' unless the swing/shuffle analysis reports it — none "
            "of these are safe defaults for a merely fast or busy drum part): "
            + "; ".join(groove_bits)
        )

    return lines


def _fmt_mmss(t):
    t = max(0.0, float(t))
    return f"{int(t // 60)}:{int(t % 60):02d}"


def _drum_active_spans(onsets, max_gap):
    """Group one drum type's onsets into continuous playing spans.

    A span breaks when the instrument stops for longer than `max_gap`, which is
    set to a few bars so ordinary pattern spacing (a snare on 2 and 4) never
    splits a span, but a real drop-out does.
    """
    spans = []
    if not onsets:
        return spans
    ordered = sorted(float(o) for o in onsets)
    start = prev = ordered[0]
    for t in ordered[1:]:
        if t - prev > max_gap:
            spans.append((start, prev))
            start = t
        prev = t
    spans.append((start, prev))
    return spans


def _describe_kit_config(active):
    """Plain-language name for a set of simultaneously-playing drum types."""
    if not active:
        return "no drums"
    pretty = {"kick": "kick", "snare": "snare", "hihat": "hi-hat",
              "tom": "toms", "cymbal": "cymbals", "percussion": "percussion"}
    order = ["kick", "snare", "hihat", "tom", "cymbal", "percussion", "other"]
    names = [pretty.get(a, a) for a in order if a in active]
    names += [pretty.get(a, a) for a in sorted(active) if a not in order]
    label = " + ".join(names)
    core = {"kick", "snare", "hihat"}
    if core.issubset(active):
        label = "full kit (" + label + ")"
    elif active & core and "snare" not in active:
        label += " (no snare)"
    return label


def _summarize_drum_entry_timeline(filtered, bpm=None, total_duration=None,
                                   min_segment_s=2.0):
    """Say WHEN each part of the kit is playing, not just what the kit does on
    average across the track.

    Every other drum statistic in this report is a whole-track or whole-section
    aggregate, so a track that starts with no drums, brings in a kick, and only
    adds the snare later reads as one averaged pattern -- there was no evidence
    anywhere that the arrangement changed, and questions like "what are the
    drums doing in the first half of the verse" could only be answered from
    that average. This walks the actual onset times and reports the kit
    configuration over time, including silence before the drums enter.

    Returns a list of text lines, or [] when there is nothing useful to say.
    """
    if not filtered:
        return []
    by_type = {}
    for n in filtered:
        t = n.get("drum_type") or "other"
        try:
            by_type.setdefault(t, []).append(float(n["onset"]))
        except (TypeError, ValueError, KeyError):
            continue
    if not by_type:
        return []

    beat_len = (60.0 / float(bpm)) if bpm and float(bpm) > 0 else 0.5
    # A few bars of silence is a real drop-out; anything shorter is just the
    # instrument's own spacing (or a fill) and must not split a span.
    max_gap = max(3.0, 8.0 * beat_len)

    spans_by_type = {t: _drum_active_spans(o, max_gap) for t, o in by_type.items()}

    first_seen = {t: min(o) for t, o in by_type.items() if o}
    last_seen = {t: max(o) for t, o in by_type.items() if o}
    track_end = float(total_duration) if total_duration else max(last_seen.values())
    track_end = max(track_end, max(last_seen.values()))

    # Change points: every moment the set of playing instruments could differ.
    points = {0.0, track_end}
    for spans in spans_by_type.values():
        for a, b in spans:
            points.add(a)
            points.add(b)
    edges = sorted(p for p in points if 0.0 <= p <= track_end)

    segments = []
    for i in range(len(edges) - 1):
        a, b = edges[i], edges[i + 1]
        if b - a <= 0.01:
            continue
        mid = (a + b) / 2.0
        active = frozenset(
            t for t, spans in spans_by_type.items()
            if any(s <= mid <= e for s, e in spans)
        )
        if segments and segments[-1][2] == active:
            segments[-1] = (segments[-1][0], b, active)
        else:
            segments.append((a, b, active))

    # Drop segments too short to be a real arrangement change, folding them
    # into whichever neighbour they interrupt, then re-merge.
    if len(segments) > 1:
        kept = []
        for seg in segments:
            if seg[1] - seg[0] < float(min_segment_s) and kept:
                kept[-1] = (kept[-1][0], seg[1], kept[-1][2])
            else:
                kept.append(seg)
        # A short FIRST segment has no earlier neighbour to fold into, so it
        # used to survive as its own line ("0:00-0:00: kick + hi-hat (no
        # snare)") -- usually just the first hit of each drum landing a few
        # milliseconds apart. Fold it forward into the segment that follows.
        if len(kept) >= 2 and kept[0][1] - kept[0][0] < float(min_segment_s):
            kept[1] = (kept[0][0], kept[1][1], kept[1][2])
            kept = kept[1:]
        merged = []
        for seg in kept:
            if merged and merged[-1][2] == seg[2]:
                merged[-1] = (merged[-1][0], seg[1], merged[-1][2])
            else:
                merged.append(list(seg))
        segments = [tuple(x) for x in merged]

    if not segments:
        return []

    lines = ["DRUM ARRANGEMENT TIMELINE (kit configuration over time, computed from the "
             "actual hit timestamps — use this, not the whole-track pattern, when asked "
             "what the drums are doing at a particular moment, when they come in, or "
             "whether they drop out; a segment listed as 'no drums' means no drum hits "
             "were transcribed in that span at all):"]
    for a, b, active in segments:
        lines.append(
            f"  {_fmt_mmss(a)}-{_fmt_mmss(b)}: {_describe_kit_config(set(active))}"
        )

    # Plain type names here -- _describe_kit_config() appends "(no snare)" to a
    # partial kit, which is right for a segment but nonsense for a single type.
    _pretty = {"kick": "kick", "snare": "snare", "hihat": "hi-hat", "tom": "toms",
               "cymbal": "cymbals", "percussion": "percussion"}
    entries = []
    for t in sorted(first_seen, key=lambda k: first_seen[k]):
        entries.append(f"{_pretty.get(t, t)} from {_fmt_mmss(first_seen[t])}")
    if entries:
        lines.append("  first entry per drum type: " + "; ".join(entries))
    return lines


def detect_cymbal_onsets(drums_stem_path, hits, max_hits=600):
    """Recover cymbal hit TIMES from the drums stem audio.

    The note transcription cannot represent cymbals, and the percussion probe
    only says one exists somewhere in a 10-second window -- too coarse for a
    grid, which needs onsets.

    The discriminator is the high-band FLOOR BETWEEN hits, not the decay of any
    single hit. Measuring one hit's decay does not work here: a cymbal almost
    always rings underneath a busy hi-hat pattern, and any per-hit window has
    to stop at the next hit a few tens of milliseconds later, so the ring is
    never inside the window. But a crash or ride raises the high-frequency
    floor for hundreds of milliseconds, whereas closed hats are spikes with
    near-silence between them. So: after each hit, look at the QUIETEST moment
    in the following window. If the top end never falls back to the track's
    usual between-hits level, something up there is still ringing.

    This ADDS a row; it never edits the transcribed kick/snare/hat data, and a
    hit can be both (a crash landing with a kick is ordinary).

    Returns a sorted list of onset times, or [] when nothing is confident.
    """
    if not CYMBAL_ONSET_DETECT_ENABLED or not drums_stem_path or not hits:
        return []
    if not os.path.exists(str(drums_stem_path)):
        return []
    try:
        y, sr = librosa.load(str(drums_stem_path), sr=None, mono=True)
    except Exception:
        return []
    if y is None or not len(y):
        return []

    onsets = []
    for h in hits:
        try:
            v = h.get("onset", h.get("t"))
            if v is not None:
                onsets.append(round(float(v), 3))
        except (TypeError, ValueError):
            continue
    onsets = sorted(set(onsets))
    if not onsets:
        return []
    if len(onsets) > max_hits:
        step = len(onsets) / float(max_hits)
        onsets = [onsets[int(i * step)] for i in range(max_hits)]

    lo, hi = CYMBAL_BAND_HZ
    try:
        hf = _drum_band_limit(y, sr, lo, hi)
        if hf is None or not len(hf):
            return []
        env = np.abs(np.asarray(hf, dtype=np.float64))
        win = max(1, int(sr * 0.005))
        if win > 1:
            env = np.convolve(env, np.ones(win) / win, mode="same")
    except Exception:
        return []

    n = len(env)
    if n < sr // 2:
        return []

    def _floor_after(t):
        a = int((t + 0.15) * sr)
        b = int((t + 0.45) * sr)
        if a >= n:
            return None
        return float(np.min(env[a:min(b, n)])) if min(b, n) > a else None

    floors, peaks = [], []
    for t in onsets:
        f = _floor_after(t)
        a = int(max(0.0, t) * sr)
        b = int((t + 0.05) * sr)
        pk = float(np.max(env[a:min(b, n)])) if min(b, n) > a else 0.0
        floors.append(f)
        peaks.append(pk)

    valid = [f for f in floors if f is not None]
    if len(valid) < 8:
        return []
    # The track's own idea of "top end has decayed away", so this adapts to
    # both a dry programmed kit and a washy live one.
    baseline = float(np.median(valid))
    if baseline <= 0:
        baseline = float(np.mean(valid)) or 1e-9

    found = []
    for t, f, pk in zip(onsets, floors, peaks):
        if f is None or pk <= 0:
            continue
        # Still ringing well above the track's usual between-hits floor...
        if f < baseline * float(CYMBAL_FLOOR_RATIO):
            continue
        # ...and the sustained energy is a real fraction of the hit itself, so
        # a quiet hit sitting inside another cymbal's wash is not double-counted.
        if (f / pk) < float(CYMBAL_MIN_SUSTAIN_RATIO):
            continue
        # ...and there must be a fresh ATTACK here. A crash rings for over a
        # second, so the two or three hits that follow it all sit on a raised
        # high-frequency floor and pass the tests above on the strength of the
        # FIRST cymbal's tail -- one crash would be drawn as four. A struck
        # cymbal spikes above the level immediately preceding it; a decaying
        # tail does not. A time-based merge cannot separate these, because a
        # ride played on every beat has exactly the spacing of a crash tail.
        a0 = int(max(0.0, t - 0.06) * sr)
        a1 = int(max(0.0, t - 0.005) * sr)
        prev = float(np.max(env[a0:a1])) if a1 > a0 else 0.0
        if prev > 0 and (pk / prev) < float(CYMBAL_MIN_ATTACK_RATIO):
            continue
        # ...and this hit must actually RAISE the sustained top end. A hat or
        # snare landing on an earlier crash's tail passes the attack test (it
        # is a fresh transient) and the floor test (the tail is still ringing),
        # so each crash was also reported a beat or two later. Comparing the
        # floor after the hit with the floor just before it separates the two:
        # a new cymbal lifts it, a hit on a decaying tail does not.
        b0 = int(max(0.0, t - 0.35) * sr)
        b1 = int(max(0.0, t - 0.03) * sr)
        floor_before = float(np.min(env[b0:b1])) if b1 > b0 else 0.0
        if floor_before > 0 and f < floor_before * 1.5:
            continue
        found.append(float(t))

    if len(found) < int(CYMBAL_MIN_DETECTIONS):
        return []
    # Collapse a ring detected across several consecutive hits down to its
    # start: one crash, not one per hit it happens to cover.
    merged = [found[0]]
    for t in found[1:]:
        if t - merged[-1] >= float(CYMBAL_MERGE_GAP_S):
            merged.append(t)
    return merged


def _estimate_grid_phase(onsets, cell_len):
    """Where the grid actually sits, from the hits themselves.

    Circular mean of every onset's position within ONE CELL, not within one
    beat. Taking it modulo the beat is wrong whenever the kit plays more than
    one subdivision per beat: hits then spread across the whole beat, the
    circular mean of a near-uniform distribution is arbitrary, and the grid
    lands wherever that noise points -- rendering an ordinary pattern rotated
    by a subdivision, so a kick on the beat reads as a kick on the "e". Modulo
    the cell, every hit contributes the same sub-cell offset regardless of
    which subdivision it fell on, which is the quantity actually wanted.
    """
    if not onsets or cell_len <= 0:
        return 0.0
    ang = 2.0 * np.pi * (np.asarray(onsets, dtype=float) % cell_len) / cell_len
    mean = np.arctan2(np.mean(np.sin(ang)), np.mean(np.cos(ang)))
    return float((mean / (2.0 * np.pi)) * cell_len % cell_len)


def _refine_local_grid(onsets, cell_len, ref=0.0, max_dev=0.03, steps=241):
    """Fit the grid's cell length and phase to a local group of onsets.

    Returns (cell_len, phase) where grid points are phase + k * cell_len.

    The cell length is searched within +/- max_dev of the nominal value and
    scored by how tightly the onsets cluster at one sub-cell offset (circular
    resultant length). Offsets are measured relative to `ref`, a time near the
    onsets, so the fit is not dominated by how far the window sits from 0:00.
    The nominal cell is kept unless another length fits clearly better, so a
    well-tempo'd track gets exactly the grid it always did.
    """
    arr = np.asarray(onsets if onsets is not None else [], dtype=float)
    if arr.size == 0 or cell_len <= 0:
        return cell_len, 0.0
    rel = arr - float(ref)

    def _fit(c):
        ang = 2.0 * np.pi * np.mod(rel, c) / c
        s, co = float(np.mean(np.sin(ang))), float(np.mean(np.cos(ang)))
        return float(np.hypot(s, co)), float(np.arctan2(s, co))

    r0, a0 = _fit(cell_len)
    best_c, best_r, best_a = cell_len, r0, a0
    if arr.size >= 8:
        for scale in np.linspace(1.0 - max_dev, 1.0 + max_dev, int(steps)):
            c = cell_len * float(scale)
            r, a = _fit(c)
            if r > best_r:
                best_c, best_r, best_a = c, r, a
        # Require a real improvement before abandoning the nominal tempo.
        if best_r < r0 + 0.03:
            best_c, best_r, best_a = cell_len, r0, a0
    offset = (best_a / (2.0 * np.pi)) * best_c % best_c
    return float(best_c), float((float(ref) + offset) % best_c)


def _grid_alignment(by_type, cell_index, subdiv, anchor_cell=None):
    """Find which cells are beats, and which beat is beat 1.

    Both are decided from the hits themselves, in CELL INDEX space. Phase only
    fixes the sub-cell offset; it says nothing about which cells carry the
    pulse, so anchoring the bar to phase alone leaves the whole diagram free to
    sit a subdivision or a beat out -- rhythmically correct but starting in the
    wrong place, which for a reader is simply a wrong pattern.

    Returns (beat_residue, downbeat_offset):
      beat_residue    -- cell indices where c %% subdiv == this are on a beat
      downbeat_offset -- which of the four beats in the bar is beat 1
    """
    kicks = [cell_index(t) for t in (by_type.get("kick") or [])]
    snares = [cell_index(t) for t in (by_type.get("snare") or [])]
    cymbal_cells = [cell_index(t) for t in (by_type.get("cymbal") or [])]
    every = [cell_index(t) for ts in by_type.values() for t in ts]

    # Kicks define the pulse when present: they are the most reliably
    # on-the-beat part of a kit. Fall back to all hits for kick-less passages.
    # Backbeat snares are just as reliably on the beat, and settle the common
    # case where kicks alone tie between two residues (drum & bass kicks on 1
    # and the "and" of 3, boom-bap kicks pushed onto off-16ths). With kicks
    # only, that tie went to whichever residue was counted first, so the whole
    # diagram could be drawn an 8th or a 16th out. All other hits add a small
    # weight as a final tie-break.
    res_src = kicks if kicks else every
    res_counts = [0.0] * subdiv
    for c in res_src:
        res_counts[c % subdiv] += 1.0
    if kicks:
        for c in snares:
            res_counts[c % subdiv] += 1.0
        for c in every:
            res_counts[c % subdiv] += 0.01
    beat_residue = int(np.argmax(res_counts)) if any(res_counts) else 0

    def _beat_no(c):
        return ((c - beat_residue) // subdiv) % 4

    kh, sh = [0] * 4, [0] * 4
    for c in kicks:
        if c % subdiv == beat_residue:
            kh[_beat_no(c)] += 1
    for c in snares:
        if c % subdiv == beat_residue:
            sh[_beat_no(c)] += 1
    if not any(kh) and not any(sh):
        return beat_residue, 0

    # Accented cymbals (crashes) mark bar starts far more often than any other
    # beat. Only a light weight: they are audio detections, not transcribed hits.
    ch = [0] * 4
    for c in (cymbal_cells or []):
        if c % subdiv == beat_residue:
            ch[_beat_no(c)] += 1

    # Which beat the window's own start lands on. A section boundary is
    # normally a bar line, so when the kit alone is ambiguous -- kicks on 1 and
    # 3 score identically for offsets 0 and 2, which is the most common pattern
    # in popular music -- the window start decides. Previously the tie always
    # went to whichever offset happened to be tried first, so a grid could
    # quietly start on beat 3 and show the pattern half a bar rotated.
    anchor_beat = None
    if anchor_cell is not None:
        try:
            ac = int(anchor_cell)
            delta = (beat_residue - ac) % subdiv
            if delta > subdiv / 2.0:
                delta -= subdiv
            anchor_beat = _beat_no(ac + delta)
        except Exception:
            anchor_beat = None

    # A half-time snare lands once per bar, on beat 3. Scored as a 2-and-4
    # backbeat it fits beat 2 or beat 4 equally well and never beat 3, so the
    # diagram drew the snare on "2" while the snare analysis (correctly) said
    # "half-time, on 3". Recognise it: one beat position carries most of the
    # snares and the position two beats away carries almost none.
    s_tot = float(sum(sh))
    half_time = False
    if s_tot >= 3:
        s_top = int(np.argmax(sh))
        half_time = (sh[s_top] >= 0.6 * s_tot and sh[(s_top + 2) % 4] <= 0.25 * sh[s_top])

    raw = []
    for off in range(4):
        # Beat 1 usually carries a kick, and the backbeat snares sit opposite.
        kick_score = kh[off] + kh[(off + 2) % 4] * 0.5
        if half_time:
            snare_score = sh[(off + 2) % 4] * 2.0
        else:
            snare_score = sh[(off + 1) % 4] + sh[(off + 3) % 4]
        raw.append(kick_score * 2.0 + snare_score + ch[off] * 0.5)

    top = max(raw) if raw else 0.0
    bonus = 0.25 + 0.03 * max(0.0, top)
    best, best_score = 0, None
    for off in range(4):
        score = raw[off]
        if anchor_beat is not None and off == anchor_beat:
            # Tie-break only: large enough to settle an exact or near tie,
            # far too small to overturn a clear kick/snare pattern.
            score += bonus
        if best_score is None or score > best_score:
            best, best_score = off, score
    return beat_residue, best


_BEAT_GRID_ROW_ORDER = ("kick", "snare", "hihat", "tom", "cymbal", "percussion", "other")
_BEAT_GRID_ROW_NAMES = {
    "kick": "kick", "snare": "snare", "hihat": "hi-hat", "tom": "toms",
    "cymbal": "cymbals", "percussion": "perc", "other": "other",
}


def build_beat_grid_diagram(hits, bpm, start=None, end=None, bars=None,
                            subdiv=None, label=""):
    """Render the measured drum pattern as a fixed-width grid.

    Every column is exactly two characters wide and the count row uses the
    same spacing, so the beat markers line up with the cells beneath them in
    any monospace font. Alignment is the whole point of the diagram: a grid
    whose columns drift is worse than no grid, because it reads as a rhythm
    that was never played.

    Cells are filled from the real onsets, quantised to the nearest
    subdivision with a half-cell tolerance. An 'x' means at least one hit of
    that type landed in that cell.

    Returns "" when there is not enough to draw honestly.
    """
    if not BEAT_GRID_ENABLED or not hits or not bpm:
        return ""
    try:
        beat_len = 60.0 / float(bpm)
    except (TypeError, ValueError, ZeroDivisionError):
        return ""
    if beat_len <= 0:
        return ""
    bars = int(bars or BEAT_GRID_BARS)
    subdiv = int(subdiv or BEAT_GRID_SUBDIV)
    if bars < 1 or subdiv < 1:
        return ""

    window = [h for h in hits
              if (start is None or float(h.get("onset", -1)) >= float(start))
              and (end is None or float(h.get("onset", -1)) < float(end))]
    if len(window) < BEAT_GRID_MIN_HITS:
        return ""

    by_type = {}
    for h in window:
        try:
            by_type.setdefault(h.get("drum_type") or "other", []).append(float(h["onset"]))
        except (TypeError, ValueError, KeyError):
            continue
    if not by_type:
        return ""

    all_onsets = sorted(t for ts in by_type.values() for t in ts)
    cell_len = beat_len / float(subdiv)
    bar_len = beat_len * 4.0

    # Where the drawn bars will sit: one bar into the window when there is room,
    # so the diagram shows the settled pattern rather than a pickup or fill.
    first = all_onsets[0]
    span = (end if end is not None else all_onsets[-1]) - first
    lead_in = beat_len * 4.0 if span > beat_len * 4.0 * (bars + 1) else 0.0
    anchor_t = first + lead_in

    # LOCAL tempo and phase. The reported BPM is a rounded integer (and can be
    # a percent or so off the true tempo), and the phase used to be a circular
    # mean over EVERY hit in the window -- a whole section, or for the
    # representative grid the whole song. A 0.4 BPM rounding error drifts the
    # grid by a full 16th every ~15 s, so on anything longer than a short
    # section the averaged phase described no particular moment and the
    # rhythm came out shifted by one or two cells (kicks on the "e", snares on
    # the "&"). The grid is now fitted to the hits around the bars actually
    # drawn, with the cell length allowed to flex by up to 3%.
    loc_lo = anchor_t - bar_len
    loc_hi = anchor_t + (bars + 2) * bar_len
    local = [t for t in all_onsets if loc_lo <= t <= loc_hi]
    if len(local) < BEAT_GRID_MIN_HITS:
        local = all_onsets
    cell_len, phase = _refine_local_grid(local, cell_len, ref=anchor_t)

    def _cell_index(t):
        return int(round((float(t) - phase) / cell_len))

    # Beat/downbeat voting uses the same neighbourhood, so that tempo drift
    # far from the drawn bars cannot out-vote the hits actually shown.
    vote_lo = anchor_t - 2 * bar_len
    vote_hi = anchor_t + (bars + 4) * bar_len
    local_by_type = {}
    for dtype, ts in by_type.items():
        near = [t for t in ts if vote_lo <= t <= vote_hi]
        if near:
            local_by_type[dtype] = near
    if sum(len(v) for v in local_by_type.values()) < BEAT_GRID_MIN_HITS:
        local_by_type = by_type

    anchor_ref = float(start) if start is not None else first
    beat_res, down_off = _grid_alignment(
        local_by_type, _cell_index, subdiv, anchor_cell=_cell_index(anchor_ref)
    )

    # Walk forward in CELL space to the first cell that is both on a beat and
    # is beat 1 of a bar, so the grid can never start mid-beat or mid-bar.
    c0 = _cell_index(anchor_t)
    for _ in range(subdiv * 4 + 1):
        if c0 % subdiv == beat_res and ((c0 - beat_res) // subdiv) % 4 == down_off:
            break
        c0 += 1
    grid_start = phase + c0 * cell_len

    cells = bars * 4 * subdiv
    tol = cell_len / 2.0

    # Keep the drawn bars inside the material. Walking forward to a downbeat
    # (or the lead-in) could push the last bar past the end of a short section,
    # leaving trailing cells empty -- which reads as the kit stopping, a rhythm
    # that was never played. Step back a bar at a time while that happens and
    # there is earlier material to show instead.
    data_end = all_onsets[-1] + beat_len
    if end is not None:
        data_end = min(data_end, float(end))
    bar_cells = 4 * subdiv
    while (
        grid_start + cells * cell_len > data_end + tol
        and grid_start - bar_cells * cell_len >= first - tol
    ):
        grid_start -= bar_cells * cell_len

    grid_end = grid_start + cells * cell_len

    rows = {}
    for dtype, onsets in by_type.items():
        row = ["."] * cells
        used = False
        for t in onsets:
            if t < grid_start - tol or t >= grid_end + tol:
                continue
            idx = int(round((t - grid_start) / cell_len))
            if 0 <= idx < cells:
                row[idx] = "x"
                used = True
        if used:
            rows[dtype] = row
    if not rows:
        return ""

    ordered = [d for d in _BEAT_GRID_ROW_ORDER if d in rows]
    ordered += [d for d in sorted(rows) if d not in _BEAT_GRID_ROW_ORDER]

    # Includes len("count") so the header/count row's own label fits within
    # the same column width as every data row — see the header-row rename
    # below for why this label exists at all.
    name_w = max(
        [len(_BEAT_GRID_ROW_NAMES.get(d, d)) for d in ordered] + [len("count")]
    )

    # Count row. One token per cell, every token padded to the same 2 chars as
    # a grid cell, so column N of the count sits above column N of every row.
    marks_4 = ["1", "e", "&", "a"]
    counts = []
    for c in range(cells):
        beat = (c // subdiv) % 4 + 1
        sub = c % subdiv
        if sub == 0:
            counts.append(str(beat))
        elif subdiv == 4:
            counts.append(marks_4[sub])
        elif subdiv == 2:
            counts.append("&")
        elif subdiv == 3:
            counts.append("ea"[sub - 1] if sub <= 2 else ".")
        else:
            counts.append(".")

    def _render(tokens):
        out = []
        for c, tok in enumerate(tokens):
            out.append(tok)
            # Bar separator sits between bars, never inside one.
            if (c + 1) % (4 * subdiv) == 0 and (c + 1) < cells:
                out.append("|")
        return " ".join(out)

    res = {4: "16th", 2: "8th", 3: "triplet 8th", 1: "quarter"}.get(subdiv, f"1/{subdiv} beat")
    head = f"BEAT GRID{(' — ' + label) if label else ''}"
    meta = (
        f"{bars} bar{'s' if bars != 1 else ''} from {_fmt_mmss(grid_start)}, "
        f"{float(bpm):.0f} BPM, {res} resolution, 4-beat bar proxy"
    )
    out = [
        f"{head} ({meta}). Fixed-width: reproduce EXACTLY as-is inside a code block, "
        "never redraw or re-space it. The 'count' row is the beat position (1 e & a "
        "2 e & a...), not a drum -- do not read it as a percussion part. 'x' = a "
        "transcribed hit in that cell, '.' = no hit, "
        "'|' = bar line. Kick, snare and hi-hat come from the note transcription; "
        "a 'cymbals' row, when present, is detected from the stem audio instead "
        "and its timing is measured the same way. Toms, shakers and hand "
        "percussion still cannot be gridded — if the notes list them elsewhere, "
        "mention them separately rather than adding a row.",
        f"{'count':<{name_w}} : {_render(counts)}",
    ]
    for d in ordered:
        out.append(f"{_BEAT_GRID_ROW_NAMES.get(d, d):<{name_w}} : {_render(rows[d])}")
    return "\n".join(out)


def _summarize_drum_rhythm_by_section(filtered, sections, bpm, max_pattern_hits=16, min_hits_per_section=8):
    """Group drum hits by the STRUCTURE sections already reported for this
    track (e.g. all 'Verse' occurrences pooled, all 'Chorus' occurrences
    pooled) and run the same grounded groove analysis on each group.

    This is what answers "what's the groove like in the chorus vs the
    verse" — instead of the writer guessing from the whole-track pattern
    (or from genre expectations), it gets a real per-section read computed
    from the actual drum-hit timestamps.

    Returns a list of text blocks, one per section group, or [] if there
    aren't enough sections/hits to say anything reliable.
    """
    if not filtered or not sections:
        return []

    groups = {}
    order = []
    for sec in sections:
        key = _section_group_key(sec["name"])
        if key not in groups:
            groups[key] = {"label": sec["name"], "ranges": []}
            order.append(key)
        if key == "chorus" and re.fullmatch(r"Chorus [A-C]\d*", str(sec["name"])):
            groups[key]["label"] = "Chorus"      # pre60: the chorus groups pooled under one label
        groups[key]["ranges"].append((sec["start"], sec["end"]))
        # Prefer the shortest/plainest occurrence name as the group label
        # (e.g. "Verse" over "Verse 1") when both singular and numbered
        # forms show up.
        if len(sec["name"]) < len(groups[key]["label"]):
            groups[key]["label"] = sec["name"]

    blocks = []
    for key in order:
        ranges = groups[key]["ranges"]
        hits = [
            n for n in filtered
            if any(start <= float(n["onset"]) < end for start, end in ranges)
        ]
        if len(hits) < min_hits_per_section:
            continue

        range_str = ", ".join(
            f"{int(s // 60)}:{int(s % 60):02d}-{int(e // 60)}:{int(e % 60):02d}"
            for s, e in ranges
        )
        section_lines = _summarize_drum_rhythm(hits, max_pattern_hits=max_pattern_hits, bpm=bpm)
        if not section_lines:
            continue
        label = groups[key]["label"]
        block = (
            f"SECTION GROOVE — {label} ({range_str}):\n"
            + "\n".join(f"  {l}" for l in section_lines)
        )
        # A grid drawn from this section's own hits. Prose can say "syncopated
        # kick, busy hats"; only the grid says exactly where they land, and it
        # is drawn here rather than left to the writer because reproducing a
        # rhythm as aligned columns from a list of timestamps is not something
        # a language model does reliably.
        try:
            grid = ""
            # Try occurrences in chronological order (ranges[0] first, exactly
            # as before) and fall back to a later occurrence only if an
            # earlier one has nothing to draw from -- e.g. the first "Verse"
            # occurrence can be an intro stretch before the drums have
            # entered yet, which would otherwise silently drop the grid for
            # the whole section even though later occurrences are full of
            # hits.
            for range_start, range_end in ranges:
                grid = build_beat_grid_diagram(
                    filtered, bpm, start=range_start, end=range_end, label=label
                )
                if grid:
                    break
            if grid:
                block += "\n" + "\n".join(f"  {l}" for l in grid.split("\n"))
        except Exception:
            pass
        blocks.append(block)

    return blocks


def _stem_activity_label(rms, density, is_drums=False):
    """Rough human-readable activity band from energy + event density."""
    dens_name = "hit density" if is_drums else "note density"
    if rms < 0.01 and density < 5:
        band = "silent/negligible"
    elif rms < 0.03 or density < 15:
        band = "low / background"
    elif rms < 0.08 or density < 60:
        band = "moderate"
    elif rms < 0.15 or density < 150:
        band = "prominent"
    else:
        band = "dominant / very dense"
    return band, dens_name

def _filter_transcribed_notes(notes, preset):
    min_freq = float(preset.get("min_frequency", 0))
    max_freq = float(preset.get("max_frequency", 100000))

    # Per-stem duration/amplitude floors, scaled down from the raw preset
    # values (see STEM_NOTE_FILTER_PRESET_WEIGHT) so instruments keep some
    # differentiation -- e.g. bass still gets a longer floor than guitar/piano
    # to fight sustain bloat/rumble -- without reintroducing the over-filtering
    # that came from applying the full preset values. Never goes below the
    # global floors that were found to work well on their own.
    preset_min_duration_s = float(preset.get("minimum_note_length_ms", 0) or 0) / 1000.0
    preset_min_amplitude = float(preset.get("min_amplitude", 0) or 0)
    min_duration_s = max(
        STEM_NOTE_MIN_DURATION_SEC_FLOOR,
        preset_min_duration_s * STEM_NOTE_FILTER_PRESET_WEIGHT,
    )
    min_amplitude = max(
        STEM_NOTE_MIN_AMPLITUDE_FLOOR,
        preset_min_amplitude * STEM_NOTE_FILTER_PRESET_WEIGHT,
    )

    filtered = []
    removed = 0

    for n in notes:
        # 1. Frequency Range Check (Keep this to remove sub-bass noise/overtones)
        if not (min_freq <= n["frequency"] <= max_freq):
            removed += 1
            continue
        
        # 2. Duration Check: per-stem floor (scaled down from preset; see above),
        # still permissive enough to catch staccato/fast runs.
        if n["duration"] < min_duration_s:
            removed += 1
            continue
            
        # 3. Amplitude Check: per-stem floor (scaled down from preset; see above),
        # still permissive enough to keep quiet vocals and soft piano notes.
        # "amplitude" is measured from the stem audio (see
        # _attach_measured_amplitudes); the transcriber's own velocities were
        # constants, so before that this check could never remove anything.
        if n.get("amplitude", 1.0) < min_amplitude:       
            removed += 1
            continue

        # 4. Absolute level: drop "notes" in passages where the stem is
        # effectively silent (separation residue), however loud they are
        # relative to the rest of a residue-only stem.
        if n.get("abs_rms") is not None and float(n["abs_rms"]) < float(STEM_NOTE_MIN_ABS_RMS):
            removed += 1
            continue
            
        filtered.append(n)

    return sorted(filtered, key=lambda x: x["onset"]), removed


def _hz_to_note_name(freq):
    try:
        return librosa.hz_to_note(float(freq))
    except Exception:
        return f"{float(freq):.0f}Hz"


def _hz_to_pitch_class(freq):
    try:
        midi = float(librosa.hz_to_midi(float(freq)))
        return int(round(midi)) % 12
    except Exception:
        return None


def _chord_label_from_pcs(pcs):
    pcs = sorted(set(int(p) % 12 for p in pcs if p is not None))
    if not pcs:
        return ""

    if len(pcs) >= 3:
        best_score = 999.0
        best = None
        for root in range(12):
            for quality, intervals in (("major", (0, 4, 7)), ("minor", (0, 3, 7))):
                target = [(root + i) % 12 for i in intervals]
                score = 0.0
                for pc in pcs:
                    d = min(min(abs(pc - t), 12 - abs(pc - t)) for t in target)
                    score += d
                avg = score / len(pcs)
                if avg < best_score:
                    best_score = avg
                    best = (root, quality)

        if best is not None and best_score <= 0.75:
            return f"{NOTE_NAMES[best[0]]} {best[1]}"

    return "+".join(NOTE_NAMES[p] for p in pcs[:6])


def _detect_common_chords(notes, max_count=5):
    if len(notes) < 2:
        return []

    notes = sorted(notes, key=lambda x: x["onset"])[:1500]
    counts = {}
    i = 0

    while i < len(notes):
        cluster = [notes[i]]
        j = i + 1
        while j < len(notes) and notes[j]["onset"] - notes[i]["onset"] <= 0.18:
            cluster.append(notes[j])
            j += 1

        if len(cluster) >= 2:
            pcs = []
            for n in cluster:
                pc = _hz_to_pitch_class(n["frequency"])
                if pc is not None and pc not in pcs:
                    pcs.append(pc)
            if len(pcs) >= 2:
                label = _chord_label_from_pcs(pcs)
                counts[label] = counts.get(label, 0) + 1

        i = j

    top = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:max_count]
    return [(label, count) for label, count in top if count >= 2 or len(top) <= 3]


def _note_midi_number(freq):
    """Continuous-to-integer MIDI note number from a frequency in Hz."""
    try:
        f = float(freq)
        if f <= 0:
            return None
        return int(round(69 + 12 * math.log2(f / 440.0)))
    except Exception:
        return None


def _notes_sorted(notes):
    """Notes in time order, skipping any whose onset isn't a usable number.

    The onset is parsed once and carried through to the sort key. Previously it
    was parsed, discarded, and then parsed again inside the sort lambda -- which
    left the sort able to raise on input the filter above it had just approved,
    and made the filtering look accidental rather than deliberate.
    """
    out = []
    for n in (notes or []):
        if not isinstance(n, dict):
            continue
        try:
            onset = float(n.get("onset", 0.0))
        except (TypeError, ValueError):
            continue
        out.append((onset, n))
    out.sort(key=lambda pair: pair[0])
    return [n for _onset, n in out]


def _split_melodic_phrases(notes, bpm=None, max_phrases=8):
    """Split a line into phrases at rests, the way a singer actually breathes.

    A melody is not one undifferentiated stream of pitches; it is a sequence of
    phrases separated by rests. Splitting on rest length is what makes it
    possible to say "the verse phrase rises then falls back to the tonic"
    instead of only being able to report an average contour over the whole
    section. Gap threshold scales with tempo so it means the same musical
    amount of silence at any BPM.
    """
    seq = _notes_sorted(notes)
    if not seq:
        return []
    beat = (60.0 / float(bpm)) if bpm and float(bpm) > 0 else 0.5
    # A rest of about a beat is a phrase break to a listener. 1.5 beats was
    # wide enough that ordinary phrase gaps fell under it and every line came
    # back as a single undifferentiated phrase.
    gap_threshold = max(0.35, beat * 0.9)

    phrases = []
    current = [seq[0]]
    for prev, cur in zip(seq, seq[1:]):
        try:
            prev_end = float(prev.get("offset", prev.get("onset", 0.0)))
            cur_start = float(cur.get("onset", 0.0))
        except Exception:
            current.append(cur)
            continue
        if cur_start - prev_end >= gap_threshold:
            phrases.append(current)
            current = [cur]
        else:
            current.append(cur)
    phrases.append(current)

    phrases = [p for p in phrases if len(p) >= 2]
    return phrases[:max_phrases]


def _interval_sequence(notes):
    """Semitone intervals between consecutive notes -- the shape of the line,
    independent of what key it happens to be in."""
    seq = _notes_sorted(notes)
    pitches = []
    for n in seq:
        m = _note_midi_number(n.get("frequency"))
        if m is not None:
            pitches.append(m)
    return [b - a for a, b in zip(pitches, pitches[1:])], pitches


def _extract_motifs(notes, min_len=3, max_len=6, max_motifs=3):
    """Find the actual repeated melodic figures in a line.

    Motifs are matched on INTERVAL patterns rather than absolute pitches, so a
    figure still counts as the same figure when it is transposed -- which is
    how riffs and hooks normally recur. Returns a list of
    {"intervals", "count", "first_onset", "notes", "span"} ordered by how
    strongly each figure characterises the line.

    This exists because contour + range + step/leap ratio can all be reported
    correctly and still leave the actual identifiable tune undescribed. The
    repeated figure is usually the thing a listener would call "the melody".
    """
    intervals, pitches = _interval_sequence(notes)
    if len(intervals) < min_len:
        return []
    seq = _notes_sorted(notes)

    found = {}
    n = len(intervals)
    for length in range(min_len, min(max_len, n) + 1):
        seen = {}
        for i in range(n - length + 1):
            pat = tuple(intervals[i:i + length])
            # A run of identical pitches is not a motif.
            if all(v == 0 for v in pat):
                continue
            seen.setdefault(pat, []).append(i)
        for pat, positions in seen.items():
            # Only count non-overlapping occurrences.
            kept = []
            for p in positions:
                if not kept or p - kept[-1] >= length:
                    kept.append(p)
            if len(kept) >= 2:
                found[pat] = kept

    if not found:
        return []

    # Prefer longer figures that recur often; a 5-note figure heard 3 times is
    # more characteristic than a 3-note fragment heard 4 times.
    scored = sorted(
        found.items(),
        key=lambda kv: (len(kv[0]) * len(kv[1]), len(kv[0])),
        reverse=True,
    )

    results = []
    claimed = set()
    for pat, positions in scored:
        span = set()
        for p in positions:
            span.update(range(p, p + len(pat) + 1))
        # Skip figures that are just sub-patterns of one already reported.
        if len(span & claimed) > 0.6 * len(span):
            continue
        claimed.update(span)
        first = positions[0]
        motif_notes = seq[first:first + len(pat) + 1]
        results.append({
            "intervals": list(pat),
            "count": len(positions),
            "first_onset": float(motif_notes[0].get("onset", 0.0)) if motif_notes else 0.0,
            "notes": motif_notes,
            "span": len(pat) + 1,
        })
        if len(results) >= max_motifs:
            break
    return results


def _describe_intervals(intervals):
    """Turn an interval pattern into plain musical language."""
    names = {
        0: "repeat", 1: "semitone up", -1: "semitone down",
        2: "whole step up", -2: "whole step down",
        3: "minor 3rd up", -3: "minor 3rd down",
        4: "major 3rd up", -4: "major 3rd down",
        5: "4th up", -5: "4th down",
        7: "5th up", -7: "5th down",
        12: "octave up", -12: "octave down",
    }
    parts = []
    for iv in intervals:
        if iv in names:
            parts.append(names[iv])
        else:
            parts.append("%d semitones %s" % (abs(iv), "up" if iv > 0 else "down"))
    return ", ".join(parts)


def _motif_phrase(motif):
    """Render one motif as a short quotable figure, e.g.
    'G3-A3-C4 (up a whole step, then a minor 3rd), heard 4x from 0:31'."""
    seq = motif.get("notes") or []
    if not seq:
        return ""
    try:
        names = [librosa.hz_to_note(float(n["frequency"]), unicode=False) for n in seq]
    except Exception:
        try:
            names = [librosa.hz_to_note(float(n["frequency"])) for n in seq]
        except Exception:
            return ""
    shape = _describe_intervals(motif.get("intervals") or [])
    return "%s (%s), recurs %dx from %s" % (
        "-".join(names), shape, int(motif.get("count") or 0),
        _seconds_to_mmss(float(motif.get("first_onset") or 0.0)),
    )


def _rhythmic_profile(notes, bpm=None):
    """Note density and typical note length, in musical units when BPM is known."""
    seq = _notes_sorted(notes)
    if len(seq) < 3:
        return ""
    try:
        span = float(seq[-1].get("offset", seq[-1].get("onset", 0.0))) - float(
            seq[0].get("onset", 0.0)
        )
    except Exception:
        return ""
    if span <= 0.5:
        return ""
    density = len(seq) / span
    durations = []
    for n in seq:
        try:
            d = float(n.get("duration",
                            float(n.get("offset", 0.0)) - float(n.get("onset", 0.0))))
            if d > 0:
                durations.append(d)
        except Exception:
            continue
    if not durations:
        return ""
    med_dur = float(np.median(durations))

    desc = "note density %.1f notes/sec" % density
    if bpm and float(bpm) > 0:
        beat = 60.0 / float(bpm)
        in_beats = med_dur / beat
        if in_beats >= 1.75:
            unit = "half notes or longer"
        elif in_beats >= 0.85:
            unit = "quarter notes"
        elif in_beats >= 0.42:
            unit = "eighth notes"
        elif in_beats >= 0.21:
            unit = "sixteenth notes"
        else:
            unit = "faster than sixteenths"
        desc += "; typical note length around %s" % unit
    else:
        desc += "; median note length %.2fs" % med_dur

    sustained = sum(1 for d in durations if d >= 0.6)
    if sustained / len(durations) > 0.4:
        desc += "; many sustained notes"
    return desc


def _contour_shape(notes):
    """Describe the arc of a line from its actual pitch trajectory.

    Reported over thirds of the line rather than a single first-half /
    second-half median comparison, so an arch (rise then fall) and a steady
    climb are no longer described identically.
    """
    seq = _notes_sorted(notes)
    pitches = [_note_midi_number(n.get("frequency")) for n in seq]
    pitches = [p for p in pitches if p is not None]
    if len(pitches) < 4:
        return "short line"
    arr = np.array(pitches, dtype=float)
    third = max(1, len(arr) // 3)
    a = float(np.median(arr[:third]))
    b = float(np.median(arr[third:2 * third]))
    c = float(np.median(arr[2 * third:]))

    up_ab, up_bc = (b - a) > 1.0, (c - b) > 1.0
    dn_ab, dn_bc = (a - b) > 1.0, (b - c) > 1.0

    if up_ab and up_bc:
        return "climbs steadily"
    if dn_ab and dn_bc:
        return "falls steadily"
    if up_ab and dn_bc:
        return "arches up then falls back"
    if dn_ab and up_bc:
        return "dips then rises"
    if abs(c - a) <= 1.0 and float(np.std(arr)) < 2.0:
        return "stays around one pitch centre"
    return "moves up and down without a single overall direction"


def _select_monophonic_line(notes):
    if not notes:
        return []

    # Sort by onset time first to ensure we process chronologically
    notes = sorted(notes, key=lambda x: x["onset"])
    
    line = []
    i = 0
    while i < len(notes):
        cluster = [notes[i]]
        j = i + 1
        
        # Group notes that are very close in time (within 50ms) as a "cluster"
        # This handles vibrato and slight pitch tracking jitter
        while j < len(notes) and notes[j]["onset"] - notes[i]["onset"] <= 0.05:
            cluster.append(notes[j])
            j += 1
            
        if not cluster:
            i = j
            continue

        # Strategy for Monophonic (Vocals/Bass):
        # Instead of just picking the loudest, pick the note with the longest duration 
        # within the cluster. This usually represents the sustained pitch better than a transient peak.
        best_note = max(cluster, key=lambda x: x["duration"])
        
        # Optional: If there's a huge amplitude difference, maybe stick to amplitude?
        # But for vocals, duration is often a better proxy for "the note being sung".
        
        line.append(best_note)
        i = j

    return line

def _lowest_line(notes):
    if not notes:
        return []

    line = []
    i = 0
    while i < len(notes):
        cluster = [notes[i]]
        j = i + 1
        while j < len(notes) and notes[j]["onset"] - notes[i]["onset"] <= 0.20:
            cluster.append(notes[j])
            j += 1
        line.append(min(cluster, key=lambda x: x["frequency"]))
        i = j

    return line


# --- Melody theory helpers ---------------------------------------------
# These turn raw transcribed notes into the kind of vocabulary a musician
# would actually use (steps vs leaps, scale-degree/tonal-center emphasis)
# WITHOUT inventing anything: every claim here is derived arithmetically
# from the same note events already in evidence, never guessed.

_MAJOR_SCALE_DEGREES = {
    0: "1 (tonic)", 1: "b2", 2: "2", 3: "b3 (blue/minor 3rd)", 4: "3",
    5: "4", 6: "#4/b5", 7: "5 (dominant)", 8: "b6", 9: "6",
    10: "b7", 11: "7 (leading tone)",
}
_MINOR_SCALE_DEGREES = {
    0: "1 (tonic)", 1: "b2", 2: "2", 3: "b3", 4: "3 (major 3rd, borrowed)",
    5: "4", 6: "#4/b5", 7: "5 (dominant)", 8: "b6", 9: "6 (natural 6, borrowed)",
    10: "b7", 11: "7 (leading tone, borrowed)",
}
_NOTE_LETTER_PC = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}

# --- Modal inflection detection --------------------------------------------
# Essentia's KeyExtractor (and therefore _parse_key_root_quality) only ever
# emits major/minor, so a Dorian track lands on "minor" and a Mixolydian one on
# "major". The transcribed notes usually still SAY which mode it is: what
# separates Dorian from natural minor is a natural 6th where the b6 would be,
# and Mixolydian from major is a b7 where the leading tone would be.
#
# This is deliberately a characteristic-degree test rather than full seven-note
# template matching. Templates score badly here because all these modes share
# six of seven notes, so the shared tones swamp the one degree that actually
# decides it. Comparing the deciding pair directly is both more reliable and
# easier to state as evidence.
#
# Nothing else reads this: _parse_key_root_quality, reconcile_key, the
# RECOMMENDED KEY block and the saved JSON schema are all untouched, and the
# detector returns "" whenever the evidence is thin or ambiguous, in which case
# output is byte-identical to before.
#
# quality -> (mode, parent name, characteristic semitone, contrasting semitone,
#             plain-language name for the characteristic degree)
_MODAL_INFLECTION_TESTS = {
    "minor": [
        ("Dorian", "natural minor", 9, 8, "natural 6th"),
        ("Phrygian", "natural minor", 1, 2, "flat 2nd"),
    ],
    "major": [
        ("Mixolydian", "major", 10, 11, "flat 7th"),
        ("Lydian", "major", 6, 5, "sharp 4th"),
    ],
}

# Conservative gates: a wrong modal claim is far worse than a missing one, so
# the detector stays silent unless the deciding degree is unambiguous.
# (MODAL_DETECTION_MIN_NOTES moved to the USER CONFIGURATION section near the top of this file.)
# (MODAL_DETECTION_MIN_SHARE moved to the USER CONFIGURATION section near the top of this file.)
# (MODAL_DETECTION_MIN_RATIO moved to the USER CONFIGURATION section near the top of this file.)


_FLAT_NOTE_NAMES = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"]


def _pc_duration_shares(notes):
    """(12 duration shares, note count) for a stem's note dicts."""
    h = [0.0] * 12
    n = 0
    for x in notes or []:
        try:
            pc = _hz_to_pitch_class(x.get("frequency"))
            d = float(x.get("offset", 0.0)) - float(x.get("onset", 0.0))
        except Exception:
            continue
        if pc is None or not (d > 0):
            continue
        h[pc % 12] += d
        n += 1
    t = sum(h)
    return ([v / t for v in h] if t > 0 else h), n


def _key_centre_reading(stem_notes, key_text):
    """Mixolydian on the fifth, when a MAJOR key's music centres on its fifth.

    Essentia matches the notes against major and minor templates only, so a
    song in D with a C chord (D Mixolydian: D E F# G A B C) is named G major,
    the major key with exactly those notes. The transcribed notes still show
    where the music sits. All of these must hold:

      - the low part (bass stem, KEY_CENTRE_MIN_NOTES notes or more) and the
        vocal line (the same) both use the fifth more than any other note,
        each KEY_CENTRE_MIN_RATIO times as much as the reported root;
      - the chord parts (guitar, piano, other) use the fifth at least as much
        as the root;
      - the fifth's own flat 7th (the reported key's 4th) carries at least
        KEY_CENTRE_FLAT7_MIN_SHARE of the chord parts and KEY_CENTRE_FLAT7_RATIO
        times its leading tone, so it is not simply the key a fifth up.

    Of 36 saved scans this fires on one (an acoustic country song in D, named
    G major); songs whose bass alone sits on the fifth (A1, the dance-pop test track) are kept
    by the vocal test. Returns None, or a dict with the new key and evidence."""
    if not KEY_CENTRE_CHECK or not stem_notes or not key_text:
        return None
    if not re.search(r"\bmajor\b", str(key_text), re.I):
        return None
    parsed = _parse_key_root_quality(key_text)
    if not parsed or parsed[1] != "major":
        return None
    root = parsed[0]
    fifth = (root + 7) % 12
    flat7, lead = (root + 5) % 12, (root + 6) % 12
    bass, nb = _pc_duration_shares(stem_notes.get("bass"))
    voc, nv = _pc_duration_shares(stem_notes.get("vocals"))
    if nb < KEY_CENTRE_MIN_NOTES or nv < KEY_CENTRE_MIN_NOTES:
        return None
    chord = [0.0] * 12
    for st in ("guitar", "piano", "other"):
        sh, n_ = _pc_duration_shares(stem_notes.get(st))
        if n_:
            chord = [a + b for a, b in zip(chord, sh)]
    tc = sum(chord)
    if tc <= 0:
        return None
    chord = [v / tc for v in chord]
    r = float(KEY_CENTRE_MIN_RATIO)
    for sh in (bass, voc):
        if max(range(12), key=lambda i: sh[i]) != fifth or sh[fifth] < r * sh[root]:
            return None
    if chord[fifth] < chord[root]:
        return None
    if chord[flat7] < float(KEY_CENTRE_FLAT7_MIN_SHARE) or chord[flat7] < float(KEY_CENTRE_FLAT7_RATIO) * chord[lead]:
        return None
    names = _FLAT_NOTE_NAMES if re.match(r"\s*[A-G](?:b|\u266d|\s*flat)", str(key_text), re.I) else NOTE_NAMES
    c, k, f7, ld = names[fifth], names[root], names[flat7], names[lead]
    parent = f"{k} major"
    return {
        "key": f"{c} Mixolydian",
        "display": f"{c} Mixolydian (the notes of {parent}, centred on {c})",
        "note": (
            f"KEY CENTRE CHECK: the key detector named {parent}, whose notes {c} Mixolydian shares; "
            f"it can only choose between major and minor keys. The music centres on {c}: it is the "
            f"most-used note in the low part ({bass[fifth] * 100:.0f}% against {bass[root] * 100:.0f}% "
            f"for {k}) and in the vocal line ({voc[fifth] * 100:.0f}% against {voc[root] * 100:.0f}%), "
            f"the chord parts use it at least as much as {k}, and {f7} natural is played "
            f"({chord[flat7] * 100:.0f}% of the chord parts) where {c} major would have {ld} "
            f"({chord[lead] * 100:.0f}%). So the song is in {c} with a flattened seventh ({f7}): "
            f"{c} Mixolydian. In plain terms say it is in {c}; mention that it uses {f7} rather than "
            f"{ld} (the {k} major scale) when the scale comes up. Scale degrees in the melody blocks "
            f"count from {c}; chord-root degrees in the stem report above count from {k}. "
            f"The detector's own reading follows: "
        ),
    }


def _apply_key_centre_check(revised, final_key, stem_notes):
    """(revised, final_key) with the RECOMMENDED KEY block rewritten when
    _key_centre_reading finds the music centred on the key's fifth; else
    both unchanged."""
    try:
        kc = _key_centre_reading(stem_notes, final_key)
        if not kc:
            return revised, final_key
        pat = re.compile(r"(?m)^RECOMMENDED KEY FOR DISCUSSION: " + re.escape(str(final_key)) + r"\. Reasoning: ")
        if not pat.search(revised):
            return revised, final_key
        revised = pat.sub(lambda _m: "RECOMMENDED KEY FOR DISCUSSION: " + kc["display"] + ". Reasoning: "
                          + kc["note"], revised, count=1)
        return revised, kc["key"]
    except Exception:
        return revised, final_key


# Krumhansl-Kessler major / minor key profiles, tonic first.
_KK_MAJOR_PROFILE = (6.35, 2.23, 3.48, 2.33, 4.38, 4.09, 2.52, 5.19, 2.39, 3.66, 2.29, 2.88)
_KK_MINOR_PROFILE = (6.33, 2.68, 3.52, 5.38, 2.60, 3.53, 2.54, 4.75, 3.98, 2.69, 3.34, 3.17)
_KEY_NOTE_STEMS = ("bass", "guitar", "piano", "other", "vocals")


def _profile_correlation(a, b):
    ma, mb = sum(a) / 12.0, sum(b) / 12.0
    num = sum((x - ma) * (y - mb) for x, y in zip(a, b))
    da = math.sqrt(sum((x - ma) ** 2 for x in a))
    db = math.sqrt(sum((y - mb) ** 2 for y in b))
    return num / (da * db) if da > 0 and db > 0 else 0.0


def _key_note_fits(stem_notes):
    """({(root pc, 'major'|'minor'): fit}, note count): how well each of the
    24 major/minor keys fits the transcribed notes of the pitched stems
    (duration-weighted pitch classes against the Krumhansl-Kessler profiles,
    Pearson correlation)."""
    hist = [0.0] * 12
    n = 0
    for st in _KEY_NOTE_STEMS:
        sh, k = _pc_duration_shares((stem_notes or {}).get(st))
        if k:
            hist = [a + b for a, b in zip(hist, sh)]
            n += k
    if n <= 0 or sum(hist) <= 0:
        return {}, n
    fits = {}
    for r in range(12):
        for q, prof in (("major", _KK_MAJOR_PROFILE), ("minor", _KK_MINOR_PROFILE)):
            fits[(r, q)] = _profile_correlation(hist, [prof[(i - r) % 12] for i in range(12)])
    return fits, n


_KEY_NOTE_REASON_RE = re.compile(
    r"(?m)^RECOMMENDED KEY FOR DISCUSSION: (?P<final>[^\n]+?)\. Reasoning: "
    r"(?P<lm>MOSS-Music|the listening model|MF) said (?P<x>[^,\n]+?), Essentia said (?P<y>[^(\n]+?) "
    r"\(strength=(?P<s>[\d.]+|n/a), (?P<side>above|below/no) confidence threshold\) — "
    r"[^\n]*?(?:mention the disagreement is possible if asked\.|hedge appropriately\.)")


def _key_note_reading(text, final_key, stem_notes):
    """dev18 KEY NOTE CHECK. When the RECOMMENDED KEY block records a
    listening-model key and an Essentia key that disagree, and the
    transcribed notes fit Essentia's key well (KEY_NOTE_GOOD_FIT, within
    KEY_NOTE_NEAR_BEST of the best of the 24 keys) and the listening model's
    key badly (below KEY_NOTE_POOR_FIT, KEY_NOTE_MARGIN or more behind),
    returns {'span', 'key', 'line'}: the block's text to replace and the key
    to report. Otherwise None, and the block stays as it is."""
    if not KEY_NOTE_CHECK or not stem_notes or not final_key:
        return None
    m = _KEY_NOTE_REASON_RE.search(str(text or ""))
    if not m or m.group("final").strip() != str(final_key).strip():
        return None
    x, y = m.group("x").strip(), m.group("y").strip()
    px, py = _parse_key_root_quality(x), _parse_key_root_quality(y)
    if not px or not py or px == py:
        return None
    if not re.search(r"(?i)\b(?:major|minor)\b", x) or not re.search(r"(?i)\b(?:major|minor)\b", y):
        return None
    fits, n = _key_note_fits(stem_notes)
    if not fits or n < KEY_NOTE_MIN_NOTES:
        return None
    fx, fy, best = fits[px], fits[py], max(fits.values())
    if not (fx < KEY_NOTE_POOR_FIT and fy >= KEY_NOTE_GOOD_FIT and fy - fx >= KEY_NOTE_MARGIN
            and fy >= best - KEY_NOTE_NEAR_BEST):
        return None
    s = m.group("s")
    lm = m.group("lm")
    if lm == "MF":
        lm = "the listening model"
    lm_cap = lm[:1].upper() + lm[1:]
    tail = ("KEY NOTE CHECK: the transcribed notes of every pitched part fit "
            f"{y} (fit {fy:.2f} of 1) and do not fit {x} (fit {fx:.2f}).")
    if m.group("side") == "above":
        line = (f"RECOMMENDED KEY FOR DISCUSSION: {final_key}. Reasoning: Essentia measured {y} "
                f"(strength={s}) and the transcribed notes agree. {lm_cap}'s own answer, {x}, is set "
                f"aside: {tail} Treat {y} as a clear reading; do not offer {x} as an alternative.")
        return {"span": m.span(), "key": final_key, "line": line}
    line = (f"RECOMMENDED KEY FOR DISCUSSION: {y}. Reasoning: {lm} said {x} and Essentia said {y} "
            f"(strength={s}, under its confidence threshold), so {x} was first preferred. {tail} "
            f"So {y} is used, and {x} is set aside. Treat {y} as moderately confident. Chord-root "
            f"degrees in the stem report above count from {x}; the melody blocks count from {y}.")
    return {"span": m.span(), "key": y, "line": line}


_KEY_FIT_LINE_RE = re.compile(r"(?m)^RECOMMENDED KEY FOR DISCUSSION: (?P<final>[^\n]+?)\. Reasoning: [^\n]*")
_SCALE_STEPS = {"major": (0, 2, 4, 5, 7, 9, 11), "minor": (0, 2, 3, 5, 7, 8, 10)}


def _key_fit_reading(text, final_key, stem_notes):
    """KEY_FIT_CHECK (see the setting): {'span', 'key', 'line'} when the
    transcribed notes clearly fit a neighbouring key (one scale note apart)
    whose tonic the bass sits on most; else None."""
    if not KEY_FIT_CHECK or not stem_notes or not final_key:
        return None
    t = str(text or "")
    m = _KEY_FIT_LINE_RE.search(t)
    if not m or m.group("final").strip() != str(final_key).strip():
        return None
    if re.search(r"KEY (?:FIT|CENTRE) CHECK|Mixolydian|Dorian|Lydian|Phrygian", m.group(0)):
        return None
    po = _parse_key_root_quality(final_key)
    if not po or not re.search(r"(?i)\b(?:major|minor)\b", str(final_key)):
        return None
    fits, n = _key_note_fits(stem_notes)
    if not fits or n < KEY_NOTE_MIN_NOTES:
        return None
    best = max(fits, key=lambda k: fits[k])
    fo, fb = fits[po], fits[best]
    if best == po or fb < KEY_NOTE_GOOD_FIT or fb - fo < float(KEY_FIT_MARGIN):
        return None
    so = {(po[0] + i) % 12 for i in _SCALE_STEPS[po[1]]}
    sb = {(best[0] + i) % 12 for i in _SCALE_STEPS[best[1]]}
    if len(so - sb) > 1:
        return None
    bass, nb = _pc_duration_shares(stem_notes.get("bass"))
    if nb < KEY_CENTRE_MIN_NOTES or max(range(12), key=lambda i: bass[i]) != best[0]:
        return None
    names = _FLAT_NOTE_NAMES if re.match(r"\s*[A-G](?:b|\u266d)", str(final_key)) else NOTE_NAMES
    new = f"{names[best[0]]} {best[1]}"
    sm = re.search(r"strength=([\d.]+)", m.group(0))
    det = f"named {final_key}" + (f" (strength={sm.group(1)})" if sm else "")
    line = (f"RECOMMENDED KEY FOR DISCUSSION: {new}. Reasoning: KEY FIT CHECK: the key detector {det}, "
            f"but it matches the notes against major and minor templates only, and {final_key} shares all "
            f"but one of its notes with {new}. The transcribed notes of every pitched part fit {new} better "
            f"(fit {fb:.2f} of 1, against {fo:.2f} for {final_key}), and the bass sits on {names[best[0]]} "
            f"more than on any other note ({bass[best[0]] * 100:.0f}% of its note time). So the song is in "
            f"{new}; treat it as moderately confident and do not present {final_key} as the key. Chord-root "
            f"degrees in the stem report above, and chords marked outside the measured key, count from "
            f"{final_key}. This is the primary key to report to the user unless the reasoning above marks it "
            f"uncertain.")
    return {"span": m.span(), "key": new, "line": line}


def _apply_key_fit_check(revised, final_key, stem_notes):
    """(revised, final_key) with the RECOMMENDED KEY line rewritten when
    _key_fit_reading finds a better-fitting neighbouring key; else unchanged."""
    try:
        kf = _key_fit_reading(revised, final_key, stem_notes)
        if not kf:
            return revised, final_key
        a, b = kf["span"]
        return revised[:a] + kf["line"] + revised[b:], kf["key"]
    except Exception:
        return revised, final_key


def _key_scale_pooled_shares(stem_notes):
    """Per pitch class, the mean of each pitched stem's duration share (every
    stem with 30+ notes counts equally, so one busy part cannot decide)."""
    tot, m = [0.0] * 12, 0
    for st in _KEY_NOTE_STEMS:
        sh, n_ = _pc_duration_shares((stem_notes or {}).get(st))
        if n_ >= 30:
            tot = [a + b for a, b in zip(tot, sh)]
            m += 1
    return ([x / m for x in tot] if m else None), m


def _key_scale_reading(text, final_key, stem_notes):
    """dev26 KEY_SCALE_CHECK (see the setting): {'span', 'key', 'line'} when
    the reported key's own scale is contradicted by the transcribed notes and
    a key a fifth away (one sharp or flat apart) fits them; else None."""
    if not KEY_SCALE_CHECK or not stem_notes or not final_key:
        return None
    t = str(text or "")
    m = _KEY_FIT_LINE_RE.search(t)
    if not m or m.group("final").strip() != str(final_key).strip():
        return None
    if re.search(r"KEY (?:CENTRE|SCALE) CHECK|Mixolydian|Dorian|Lydian|Phrygian|Locrian", m.group(0)):
        return None
    po = _parse_key_root_quality(final_key)
    if not po or not re.search(r"(?i)\b(?:major|minor)\b", str(final_key)):
        return None
    fits, n = _key_note_fits(stem_notes)
    if not fits or n < KEY_NOTE_MIN_NOTES:
        return None
    h, nst = _key_scale_pooled_shares(stem_notes)
    if not h or nst < 2:
        return None
    steps = (0, 2, 4, 5, 7, 9, 11)
    scale = lambda r_: {(r_ + i) % 12 for i in steps}
    s0 = po[0] if po[1] == "major" else (po[0] + 3) % 12       # its key signature (relative major)
    hit = None
    for step in (7, 5):     # one sharp more (the 4th raised) / one flat more (the 7th lowered)
        s1 = (s0 + step) % 12
        x = next(iter(scale(s0) - scale(s1)))     # the reported key's own note
        y = next(iter(scale(s1) - scale(s0)))     # the neighbouring key's note instead
        if h[y] >= float(KEY_SCALE_PRESENT_MIN) and h[x] <= float(KEY_SCALE_ABSENT_RATIO) * h[y]:
            if hit is None or h[x] / max(1e-9, h[y]) < hit[4]:
                hit = (step, s1, x, y, h[x] / max(1e-9, h[y]))
    if hit is None:
        return None
    step, s1, x, y, _r = hit
    pick = max(((s1, "major"), ((s1 + 9) % 12, "minor")), key=lambda c: fits[c])
    s2 = (s1 + step) % 12
    p2 = max(((s2, "major"), ((s2 + 9) % 12, "minor")), key=lambda c: fits[c])
    if fits[p2] >= fits[pick] + float(KEY_SCALE_NEXT_MARGIN):
        pick = p2
    if pick == po or fits[pick] < float(KEY_NOTE_GOOD_FIT):
        return None
    # The old tonic still rules the bass and the chord parts: the song keeps
    # its centre and borrows the note (a Mixolydian / Dorian colour), so the
    # reported key stays.
    bass, nb = _pc_duration_shares(stem_notes.get("bass"))
    chord = [0.0] * 12
    for st in ("guitar", "piano", "other"):
        sh, n_ = _pc_duration_shares(stem_notes.get(st))
        if n_:
            chord = [a + b for a, b in zip(chord, sh)]
    g = float(KEY_SCALE_GUARD_RATIO)
    if nb and bass[po[0]] >= g * bass[pick[0]] and chord[po[0]] >= g * chord[pick[0]]:
        return None
    _flat_sig = (pick[0] if pick[1] == "major" else (pick[0] + 3) % 12) in (5, 10, 3, 8, 1)
    names = (_FLAT_NOTE_NAMES if (re.match(r"\s*[A-G](?:b|\u266d)", str(final_key)) or _flat_sig)
             else NOTE_NAMES)
    new = f"{names[pick[0]]} {pick[1]}"
    sm = re.search(r"strength=([\d.]+)", m.group(0))
    det = f"named {final_key}" + (f" (strength={sm.group(1)})" if sm else "")
    line = (f"RECOMMENDED KEY FOR DISCUSSION: {new}. Reasoning: KEY SCALE CHECK: the key detector {det}, "
            f"but {final_key}'s own {names[x]} is all but absent from the transcribed notes of the pitched parts "
            f"({h[x] * 100:.1f}% of their note time) while {names[y]}, which {final_key} does not have, is clearly "
            f"played ({h[y] * 100:.1f}%). That is the scale of a key a fifth away, and of the keys with that scale "
            f"the notes fit {new} best (fit {fits[pick]:.2f} of 1; {final_key}'s {fits[po]:.2f} comes from the notes the "
            f"two keys share). So the song is in "
            f"{new}; treat it as moderately confident and do not present {final_key} as the key. Chord-root "
            f"degrees in the stem report above, and chords marked outside the measured key, count from "
            f"{final_key}. This is the primary key to report to the user unless the reasoning above marks it "
            f"uncertain.")
    return {"span": m.span(), "key": new, "line": line}


def _key_change_reading(stem_notes, duration=None):
    """dev28 KEY_CHANGE_CHECK: (key before, key after, time, semitones) when
    the transcribed notes show the song moving to a new key for its last
    part -- the notes before some point fit one key (KEY_CHANGE_MIN_FIT or
    more) and the notes after it fit that same key moved by 1 to 4 semitones
    up or 1 to 2 down (as well), each side holding KEY_NOTE_MIN_NOTES/2 notes
    or more, the change in the second half of the song and at least
    KEY_CHANGE_MIN_TAIL_S before its end, and the notes of the whole song
    fitting no single key as well. Else None."""
    if not stem_notes:
        return None
    spans = []
    for st in _KEY_NOTE_STEMS:
        for n_ in (stem_notes or {}).get(st) or []:
            sp = _sx_note_span(n_) if isinstance(n_, dict) else None
            if sp:
                spans.append((float(sp[0]), st, n_))
    if len(spans) < KEY_NOTE_MIN_NOTES:
        return None
    end = float(duration or max(t for t, _s, _n in spans))
    whole, _n = _key_note_fits(stem_notes)
    if not whole:
        return None
    w_best = max(whole.values())

    def _fits(t0, t1):
        sub = {}
        for t, st, n_ in spans:
            if t0 <= t < t1:
                sub.setdefault(st, []).append(n_)
        return _key_note_fits(sub)
    best = None
    t = 0.5 * end
    while t <= end - float(KEY_CHANGE_MIN_TAIL_S):
        fa, na = _fits(0.0, t)
        fb, nb_ = _fits(t, end + 1.0)
        if fa and fb and na >= KEY_NOTE_MIN_NOTES // 2 and nb_ >= KEY_NOTE_MIN_NOTES // 2:
            ka = max(fa, key=lambda k: fa[k])
            kb = max(fb, key=lambda k: fb[k])
            shift = (kb[0] - ka[0]) % 12
            if kb[1] == ka[1] and shift in (1, 2, 3, 4, 10, 11):
                sc = min(fa[ka], fb[kb])
                if best is None or sc > best[0]:
                    best = (sc, ka, kb, t, shift if shift <= 4 else shift - 12)
        t += 2.0
    if best is None:
        return None
    sc, ka, kb, t, k = best
    if sc < float(KEY_CHANGE_MIN_FIT) or sc - w_best < float(KEY_CHANGE_MIN_GAIN):
        return None
    return ka, kb, t, k


def _apply_key_change_check(revised, final_key, stem_notes):
    """dev28 KEY_CHANGE_CHECK: (revised, final_key) with the RECOMMENDED KEY
    line rewritten to the key the song starts in, naming the key change,
    when _key_change_reading finds one; else unchanged."""
    try:
        if not KEY_CHANGE_CHECK or not final_key:
            return revised, final_key
        m = _KEY_FIT_LINE_RE.search(str(revised or ""))
        if not m or m.group("final").strip() != str(final_key).strip() or "KEY CHANGE CHECK" in m.group(0):
            return revised, final_key
        kc = _key_change_reading(stem_notes)
        if not kc:
            return revised, final_key
        ka, kb, t, k = kc

        def _nm(key):
            sig = key[0] if key[1] == "major" else (key[0] + 3) % 12
            names = _FLAT_NOTE_NAMES if sig in (5, 10, 3, 8, 1) else NOTE_NAMES
            return f"{names[key[0]]} {key[1]}"
        a_, b_ = _nm(ka), _nm(kb)
        way = "up" if k > 0 else "down"
        n_st = abs(int(k))
        step = {1: "a semitone", 2: "a whole tone", 3: "three semitones", 4: "four semitones"}.get(n_st, f"{n_st} semitones")
        mm = f"{int(t // 60)}:{int(t % 60):02d}"
        prev = f"named {final_key}" if final_key != a_ else f"also named {final_key}"
        line = (f"RECOMMENDED KEY FOR DISCUSSION: {a_}. Reasoning: KEY CHANGE CHECK: the song changes key -- "
                f"it is in {a_} and moves {way} {step} to {b_} at about {mm} for its last part (the transcribed "
                f"notes before that point fit {a_}, those after it fit {b_}, each better than any single key fits "
                f"the whole song). The key detector, which measures the whole song at once, {prev}. Report {a_} as "
                f"the song's key and say that it modulates {way} to {b_} near the end; treat it as moderately "
                f"confident. Chord-root degrees in the stem report above count from {final_key}. This is the "
                f"primary key to report to the user unless the reasoning above marks it uncertain.")
        a0, b0 = m.span()
        return revised[:a0] + line + revised[b0:], a_
    except Exception:
        return revised, final_key


def _apply_key_scale_check(revised, final_key, stem_notes):
    """(revised, final_key) with the RECOMMENDED KEY line rewritten when
    _key_scale_reading finds the reported key's scale contradicted; else
    unchanged."""
    try:
        ks = _key_scale_reading(revised, final_key, stem_notes)
        if not ks:
            return revised, final_key
        a, b = ks["span"]
        return revised[:a] + ks["line"] + revised[b:], ks["key"]
    except Exception:
        return revised, final_key


def _apply_key_note_check(revised, final_key, stem_notes):
    """(revised, final_key) with the RECOMMENDED KEY block rewritten when
    _key_note_reading sets the listening model's key aside; else both
    unchanged."""
    try:
        kn = _key_note_reading(revised, final_key, stem_notes)
        if not kn:
            return revised, final_key
        a, b = kn["span"]
        return revised[:a] + kn["line"] + revised[b:], kn["key"]
    except Exception:
        return revised, final_key


def _detect_modal_inflection(notes, key_text):
    """Report a diatonic mode when the transcribed notes clearly show one.

    Weights each pitch class by note duration (a long natural 6th is stronger
    evidence than a passing one), then compares the single degree that
    distinguishes the mode from its parent major/minor. Returns "" unless the
    evidence is unambiguous, so this can only ever ADD a line.
    """
    try:
        parsed = _parse_key_root_quality(key_text)
        if not parsed or not notes:
            return ""
        root_pc, quality = parsed

        weights = {}
        total = 0.0
        counted = 0
        for n in notes:
            try:
                pc = _hz_to_pitch_class(n.get("frequency"))
            except Exception:
                pc = None
            if pc is None:
                continue
            try:
                w = float(n.get("offset", 0.0)) - float(n.get("onset", 0.0))
            except Exception:
                w = 0.0
            if not (w > 0):
                w = 1.0  # durations missing/degenerate: fall back to counting
            deg = (pc - root_pc) % 12
            weights[deg] = weights.get(deg, 0.0) + w
            total += w
            counted += 1

        if counted < MODAL_DETECTION_MIN_NOTES or total <= 0:
            return ""

        findings = []
        for mode, parent, char_deg, rival_deg, label in _MODAL_INFLECTION_TESTS.get(quality, []):
            c = weights.get(char_deg, 0.0)
            o = weights.get(rival_deg, 0.0)
            if (c + o) / total < MODAL_DETECTION_MIN_SHARE:
                continue
            if c <= o * MODAL_DETECTION_MIN_RATIO:
                continue
            findings.append((c, mode, parent, label, o))

        if not findings:
            return ""

        findings.sort(key=lambda f: -f[0])
        c, mode, parent, label, o = findings[0]
        root_name = NOTE_NAMES[root_pc % 12]
        out = (
            f"modal reading: the notes fit {root_name} {mode} rather than plain "
            f"{root_name} {parent} — the {label} carries {c / total * 100:.0f}% "
            "of the note weight"
        )
        if o <= 0:
            out += ", and the contrasting degree never appears"
        else:
            out += f" against {o / total * 100:.0f}% for the {parent} form"
        return out
    except Exception:
        return ""


def _parse_key_root_quality(key_text):
    """Parse a 'C major' / 'A minor' / 'F# Major' style key string into
    (root_pitch_class, quality). Returns None if it can't be parsed --
    callers must treat that as "no key available", not fall back to a guess."""
    if not key_text:
        return None
    m = re.match(
        r"\s*([A-Ga-g])[\s\-]*(#|b(?=$|[^a-z]|m(?:$|[^a-z]|in|aj))|sharp|flat|\u266f|\u266d)?\s*(major|minor|maj|min|m(?![a-z]))?(?![a-z])",
        str(key_text),
        re.IGNORECASE,
    )
    if not m or not m.group(1):
        return None
    base = _NOTE_LETTER_PC.get(m.group(1).upper())
    if base is None:
        return None
    accidental = (m.group(2) or "").lower()
    if accidental in ("#", "sharp", "\u266f"):
        base += 1
    elif accidental in ("b", "flat", "\u266d"):
        base -= 1
    quality_raw = (m.group(3) or "major").lower()
    quality = "minor" if (quality_raw.startswith("min") or quality_raw == "m") else "major"
    if not m.group(3):
        # A modal key ("D Dorian", "A Aeolian") used to fall through to major,
        # so scale degrees were labelled against a major scale for modes
        # whose third is minor. Map each mode onto its major/minor family.
        _rest = str(key_text)[m.end():].lower()
        if re.search(r"\b(dorian|phrygian|aeolian|locrian)\b", _rest):
            quality = "minor"
    return (base % 12, quality)


def _scale_degree_label(pitch_class, root_pc, quality):
    interval = (pitch_class - root_pc) % 12
    table = _MINOR_SCALE_DEGREES if quality == "minor" else _MAJOR_SCALE_DEGREES
    return table.get(interval, f"chromatic ({interval} semitones from tonic)")


def _scale_degree_summary(notes, key_text):
    """Which scale degrees (relative to the track's own recommended key)
    this note set actually emphasizes, e.g. 'centers on 1 and 5 (tonic and
    dominant)'. Grounded entirely in the transcribed pitch classes -- this
    is descriptive statistics on real notes, not inferred harmony."""
    parsed = _parse_key_root_quality(key_text)
    if not parsed or not notes:
        return ""
    root_pc, quality = parsed
    counts = {}
    for n in notes:
        pc = _hz_to_pitch_class(n["frequency"])
        if pc is None:
            continue
        deg = _scale_degree_label(pc, root_pc, quality)
        counts[deg] = counts.get(deg, 0) + 1
    total = sum(counts.values())
    if total < 4:
        return ""
    top = sorted(counts.items(), key=lambda kv: -kv[1])[:3]
    chromatic_ct = sum(c for d, c in counts.items() if d.startswith("chromatic"))
    desc = "emphasizes scale degree" + ("s " if len(top) > 1 else " ") + ", ".join(
        f"{d}" for d, _c in top
    )
    if chromatic_ct / total > 0.3:
        desc += "; notable chromatic content outside the estimated key"
    return desc


def _melodic_interval_profile(notes):
    """Characterize consecutive-note movement (step vs leap, direction bias)
    from the ACTUAL transcribed interval sequence -- computed once here so
    the writer never has to eyeball a note-name string and guess."""
    if not notes or len(notes) < 3:
        return ""
    ordered = sorted(notes, key=lambda n: n["onset"])
    steps = leaps = same = up = down = 0
    leap_max = 0
    for a, b in zip(ordered, ordered[1:]):
        fa, fb = float(a.get("frequency") or 0), float(b.get("frequency") or 0)
        if fa <= 0 or fb <= 0:
            continue
        semis = int(round(12 * np.log2(fb / fa)))
        absv = abs(semis)
        if absv == 0:
            same += 1
        elif absv <= 2:
            steps += 1
        else:
            leaps += 1
            leap_max = max(leap_max, absv)
        if semis > 0:
            up += 1
        elif semis < 0:
            down += 1
    total = steps + leaps + same
    if total < 3:
        return ""
    step_pct = steps / total * 100
    leap_pct = leaps / total * 100
    if step_pct >= 65:
        motion = "mostly stepwise motion"
    elif leap_pct >= 50:
        motion = "leap-heavy, wide-interval motion"
    else:
        motion = "a mix of stepwise motion and leaps"
    desc = f"melodic motion: {motion} ({step_pct:.0f}% steps, {leap_pct:.0f}% leaps"
    if leap_max >= 5:
        desc += f", widest leap ~{leap_max} semitones"
    desc += ")"
    if up + down >= 4:
        if up > down * 1.5:
            desc += "; more upward movement than downward"
        elif down > up * 1.5:
            desc += "; more downward movement than upward"
    return desc


def _summarize_melody(notes, max_notes=None, key_text=None, bpm=None,
                      include_motifs=True):
    """Describe a melodic line from the real transcribed notes.

    Reports, all computed arithmetically from the note events themselves:
    the opening figure as heard (contiguous, not a sample scattered across the
    line), the arc of the line, practical and absolute pitch range, step/leap
    motion, scale-degree emphasis against this track's own measured key,
    rhythmic density, and any repeated motif.

    The note sequence shown is now the START of the line rather than notes
    sampled evenly across it. An evenly-sampled sequence is not a thing anyone
    ever heard -- printing every fifth note of a phrase produces a series of
    pitches in an order that never occurred, which is exactly the kind of
    detail a language model then repeats back as if it were the tune.
    """
    if not notes:
        return ""

    if max_notes is None:
        max_notes = STEM_MIDI_MELODY_LINE_NOTES

    seq_notes = _notes_sorted(notes)
    freqs = np.array(
        [float(n["frequency"]) for n in seq_notes if float(n.get("frequency", 0)) > 0],
        dtype=float,
    )
    if freqs.size == 0:
        return ""

    # Contiguous opening figure -- an order that was actually played.
    head = seq_notes[:max_notes]
    seq = [_hz_to_note_name(float(n["frequency"])) for n in head]

    direction = _contour_shape(seq_notes)

    lo_abs = _hz_to_note_name(float(np.min(freqs)))
    hi_abs = _hz_to_note_name(float(np.max(freqs)))
    # Practical range trims transcription outliers at both ends.
    if freqs.size >= 8:
        lo_p = _hz_to_note_name(float(np.percentile(freqs, 5)))
        hi_p = _hz_to_note_name(float(np.percentile(freqs, 95)))
        range_note = "%s-%s (practical), %s-%s (absolute)" % (lo_p, hi_p, lo_abs, hi_abs)
    else:
        range_note = "%s-%s" % (lo_abs, hi_abs)

    if len(seq_notes) > len(seq):
        lead = "melodic line (%d notes total; opens %s)" % (len(seq_notes), " ".join(seq))
    else:
        lead = "melodic line (%d notes): %s" % (len(seq), " ".join(seq))

    out = "%s; contour: %s; pitch range: %s" % (lead, direction, range_note)

    interval_desc = _melodic_interval_profile(seq_notes)
    if interval_desc:
        out += "; " + interval_desc
    degree_desc = _scale_degree_summary(seq_notes, key_text)
    if degree_desc:
        out += "; " + degree_desc
    modal_desc = _detect_modal_inflection(seq_notes, key_text)
    if modal_desc:
        out += "; " + modal_desc
    rhythm_desc = _rhythmic_profile(seq_notes, bpm=bpm)
    if rhythm_desc:
        out += "; " + rhythm_desc

    if include_motifs:
        motifs = _extract_motifs(seq_notes)
        if motifs:
            phrase = _motif_phrase(motifs[0])
            if phrase:
                out += "; repeated figure: " + phrase
    return out


def _evenly_sample_notes(notes, max_notes):
    """Return up to max_notes events spread evenly across the FULL list
    (by index, which is chronological), instead of just the earliest ones.
    This matters once transcription covers an entire song: naively slicing
    notes[:max_notes] would silently drop everything after the intro on
    any long or note-dense track. Always keeps the first and last event."""
    if max_notes is None or len(notes) <= max_notes:
        return list(notes)
    if max_notes <= 1:
        return notes[:1]
    step = (len(notes) - 1) / (max_notes - 1)
    idxs = sorted({round(i * step) for i in range(max_notes)})
    return [notes[i] for i in idxs]


def _notes_to_event_log(notes, max_notes=STEM_MIDI_EVENT_LOG_MAX_NOTES):
    """Serialize filtered note events for optional inclusion in the report.
    Sampled evenly across the whole track so full-song coverage survives
    the per-stem event cap. Prefer the compact string form when
    STEM_MIDI_COMPACT_EVENT_FORMAT is True (much smaller than JSON objects)."""
    if not notes:
        return ""
    sampled = _evenly_sample_notes(notes, max_notes)
    if STEM_MIDI_COMPACT_EVENT_FORMAT:
        parts = []
        for n in sampled:
            try:
                name = librosa.hz_to_note(float(n["frequency"]))
            except Exception:
                name = f"{float(n['frequency']):.1f}Hz"
            onset = round(float(n["onset"]), 2)
            offset = round(float(n["offset"]), 2)
            parts.append(f"{name}@{onset}-{offset}")
        return ", ".join(parts)
    rows = []
    for n in sampled:
        try:
            name = librosa.hz_to_note(float(n["frequency"]))
        except Exception:
            name = f"{n['frequency']:.1f}Hz"
        rows.append({
            "onset": round(float(n["onset"]), 3),
            "offset": round(float(n["offset"]), 3),
            "freq_hz": round(float(n["frequency"]), 2),
            "note": name,
            "amp": round(float(n.get("amplitude", 1.0)), 3),
        })
    return json.dumps(rows)


def _drum_events_to_event_log(notes, max_notes=STEM_MIDI_EVENT_LOG_MAX_NOTES):
    """Serialize drum/onset hit events for optional inclusion in the report.
    'drum_type' names the actual class of hit (kick/snare/hihat/tom/cymbal)
    for the Omnizart drums stem. It is not a pitch — the writer model
    should read it as which drum was struck, not as melodic content. The
    'other' stem's onset-detection fallback has no real drum_type, so it
    falls back to a rough low/mid/high register label from the onset's
    band-centre frequency. Sampled evenly across the whole track (see
    _evenly_sample_notes) so full-song coverage survives the event cap."""
    if not notes:
        return ""
    sampled = _evenly_sample_notes(notes, max_notes)
    if STEM_MIDI_COMPACT_EVENT_FORMAT:
        parts = []
        for n in sampled:
            drum_type = n.get("drum_type") or _drum_band_label(float(n.get("frequency", 300.0)))
            onset = round(float(n["onset"]), 2)
            parts.append(f"{drum_type}@{onset}")
        return ", ".join(parts)
    rows = []
    for n in sampled:
        drum_type = n.get("drum_type") or _drum_band_label(float(n.get("frequency", 300.0)))
        rows.append({
            "onset": round(float(n["onset"]), 3),
            "duration": round(float(n["duration"]), 3),
            "velocity": round(float(n.get("amplitude", 1.0)), 3),
            "drum_type": drum_type,
        })
    return json.dumps(rows)
      
        
def _notes_to_full_log(notes):
    """Return a compact string of all filtered notes: 'note_name@onset-offset (amp=...)', separated by commas."""
    if not notes:
        return ""
    parts = []
    for n in notes:
        try:
            name = librosa.hz_to_note(float(n["frequency"]))
        except Exception:
            name = f"{float(n['frequency']):.1f}Hz"
        onset = round(float(n["onset"]), 2)
        offset = round(float(n["offset"]), 2)
        amp = round(float(n.get("amplitude", 1.0)), 3)
        parts.append(f"{name}@{onset}-{offset} (amp={amp})")
    return ", ".join(parts)

def _drum_events_to_full_log(notes):
    """Return a compact string of all drum hits: 'drum_type@onset', separated by commas."""
    if not notes:
        return ""
    parts = []
    for n in notes:
        drum_type = n.get("drum_type") or _drum_band_label(float(n.get("frequency", 300.0)))
        onset = round(float(n["onset"]), 2)
        parts.append(f"{drum_type}@{onset}")
    return ", ".join(parts)
    
    
def _stem_notes_to_json(stem_notes, max_per_stem=None):
    """Serialise raw per-stem transcribed MIDI for the saved song .json.

    Compact keys keep the file to a sane size while remaining fully
    self-describing:
      t   onset seconds
      d   duration seconds
      m   MIDI note number
      n   note name
      v   normalised amplitude / velocity proxy
      k   drum type (percussive stems only)

    This is what makes a saved song reusable: without the note events, a
    reloaded track could only ever be discussed through whatever prose summary
    happened to be written at analysis time, and any melody question asked
    later had nothing underneath it. With FULL_MIDI_TRANSCRIPTION on, every
    detected note in every stem is stored.
    """
    if not stem_notes:
        return {}
    out = {}
    for stem, notes in (stem_notes or {}).items():
        if not notes:
            continue
        seq = _notes_sorted(notes)
        if max_per_stem and len(seq) > max_per_stem:
            seq = _evenly_sample_notes(seq, max_per_stem)
        rows = []
        for n in seq:
            try:
                onset = round(float(n.get("onset", 0.0)), 3)
                freq = float(n.get("frequency", 0.0))
            except Exception:
                continue
            dur = n.get("duration")
            if dur is None:
                try:
                    dur = float(n.get("offset", onset)) - onset
                except Exception:
                    dur = 0.0
            row = {
                "t": onset,
                "d": round(float(dur or 0.0), 3),
                "v": round(float(n.get("amplitude", 1.0) or 1.0), 3),
            }
            drum_type = n.get("drum_type")
            if drum_type:
                row["k"] = str(drum_type)
                if "structure_legacy_keep" in n:
                    row["sl"] = bool(n["structure_legacy_keep"])
            else:
                midi_num = _note_midi_number(freq)
                if midi_num is not None:
                    row["m"] = midi_num
                    row["n"] = _hz_to_note_name(freq)
                else:
                    row["hz"] = round(freq, 2)
            rows.append(row)
        if rows:
            out[stem] = rows
    return out


def _json_notes_to_stem_notes(saved):
    """Inverse of _stem_notes_to_json: rebuild the internal note dicts from a
    saved song file so a reloaded track supports the same melodic analysis as a
    freshly scanned one."""
    if not saved or not isinstance(saved, dict):
        return {}
    out = {}
    for stem, rows in saved.items():
        if not isinstance(rows, list):
            continue
        notes = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            try:
                onset = float(r.get("t", 0.0))
                dur = float(r.get("d", 0.0))
            except Exception:
                continue
            if "m" in r:
                try:
                    freq = 440.0 * (2.0 ** ((float(r["m"]) - 69) / 12.0))
                except Exception:
                    continue
            elif "hz" in r:
                try:
                    freq = float(r["hz"])
                except Exception:
                    continue
            else:
                freq = 0.0
            note = {
                "onset": onset,
                "offset": onset + dur,
                "duration": dur,
                "frequency": freq,
                "amplitude": float(r.get("v", 1.0) or 1.0),
            }
            if r.get("k"):
                note["drum_type"] = r["k"]
                if isinstance(r.get("sl"), bool):
                    note["structure_legacy_keep"] = r["sl"]
            notes.append(note)
        if notes:
            out[stem] = notes
    return out


_HM_HEAD = "HARMONY AND MELODY BY SECTION"
_HM_ACC_STEMS = ("guitar", "piano", "other")


def _hm_midi(n):
    try:
        f = float(n.get("frequency") or 0.0)
        return 69.0 + 12.0 * math.log2(f / 440.0) if f > 0 else None
    except Exception:
        return None


def _hm_pitched(notes):
    """Notes with a pitch and no drum type (drum hits never count)."""
    out = []
    for n in notes or []:
        if n.get("drum_type"):
            continue
        m = _hm_midi(n)
        if m is None:
            continue
        try:
            on = float(n.get("onset"))
        except Exception:
            continue
        d = n.get("duration")
        if d is None:
            try:
                d = float(n.get("offset", on)) - on
            except Exception:
                d = 0.0
        out.append((on, max(0.05, float(d or 0.0)), m))
    return out


def _hm_avg_poly(notes):
    """Average number of notes sounding at each note onset (1 = a single line)."""
    if not notes:
        return 0.0
    tot = 0
    for on, _d, _m in notes:
        tot += sum(1 for o2, d2, _ in notes if o2 <= on < o2 + d2)
    return tot / float(len(notes))


def _hm_section_chords(stem_notes, a, b, key):
    counts = {}
    for stem in _HM_ACC_STEMS:
        sec = [n for n in (stem_notes.get(stem) or []) if not n.get("drum_type")
               and a <= float(n.get("onset", -1) or -1) < b]
        if len(sec) < 4:
            continue
        try:
            found = _detect_common_chords(sec, max_count=8)
        except Exception:
            continue
        for label, cnt in found:
            mm = re.match(r"([A-G]#?) (major|minor)$", label)
            if mm:
                k = (_CHD_PC[mm.group(1)], "m" if mm.group(2) == "minor" else "")
                counts[k] = counts.get(k, 0) + cnt
                continue
            mm = re.match(r"([A-G]#?)\+([A-G]#?)$", label)
            if mm:
                x, y = _CHD_PC[mm.group(1)], _CHD_PC[mm.group(2)]
                root = x if (y - x) % 12 == 7 else (y if (x - y) % 12 == 7 else None)
                if root is not None:
                    counts[(root, "5")] = counts.get((root, "5"), 0) + cnt
    triad_roots = {r for (r, q) in counts if q in ("", "m")}
    items = sorted(((c, k) for k, c in counts.items() if not (k[1] == "5" and k[0] in triad_roots)),
                   key=lambda x: -x[0])
    if not items:
        return []
    top = items[0][0]
    names = _CHD_FLAT if (key and key[3]) else _CHD_SHARP
    return [names[k[0]] + k[1] for c, k in items if c >= max(2, 0.25 * top)][:4]


def _hm_vocal_absent(text):
    """Section time ranges ("m:ss-m:ss") where INTENSITY BY SECTION (vocals
    stem) says the voice is not playing or quiet / mostly absent."""
    t = str(text or "")
    i = t.find("INTENSITY BY SECTION (vocals stem")
    if i < 0:
        return set()
    e = t.find("\n\n", i)
    out = set()
    for m in re.finditer(r"(?m)^\s+.+? \((\d+:\d\d)-(\d+:\d\d)\): (not playing|quiet)", t[i:e if e >= 0 else len(t)]):
        out.add(f"{m.group(1)}-{m.group(2)}")
    return out


def _hm_lead(pitched, a, b, instrumental, vocal_absent=None):
    """(stem, notes) carrying the lead line in [a, b): the voice when it has
    8+ notes there, else the most melody-like single-note part among guitar,
    piano and other (8+ notes, near-single-line, highest), else (None, [])."""
    if not instrumental and f"{_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}" not in (vocal_absent or set()):
        v = [x for x in pitched.get("vocals", []) if a <= x[0] < b]
        if len(v) >= 8:
            return "vocals", v
    best = None
    for stem in _HM_ACC_STEMS:
        sec = [x for x in pitched.get(stem, []) if a <= x[0] < b]
        if len(sec) < 8:
            continue
        if _hm_avg_poly(sec) > 1.6:
            continue
        med = float(np.median([x[2] for x in sec]))
        if best is None or med > best[0]:
            best = (med, stem, sec)
    return (best[1], best[2]) if best else (None, [])


def _hm_name(m):
    try:
        return _hz_to_note_name(440.0 * (2.0 ** ((float(m) - 69.0) / 12.0)))
    except Exception:
        return "?"


def _hm_octaves_above_bass(d):
    """A lead-to-bass gap in semitones, in words (nearest half octave)."""
    try:
        d = float(d)
    except Exception:
        return ""
    if d < 0:
        return "below the bass"
    if d < 9:
        return "less than an octave above the bass"
    halves = int(round(d / 6.0))
    whole, half = divmod(halves, 2)
    if whole == 0:
        return "about half an octave above the bass"
    words = {1: "an octave", 2: "two octaves", 3: "three octaves", 4: "four octaves"}
    if half:
        n = {1: "one", 2: "two", 3: "three", 4: "four"}.get(whole, str(whole))
        return f"about {n} and a half octaves above the bass"
    return f"about {words.get(whole, str(whole) + ' octaves')} above the bass"


def _build_harmony_melody_by_section(sections, stem_notes, key=None, instrumental=False, context_text=""):
    """See HARMONY_MELODY_BY_SECTION. "" when there is nothing to say."""
    if not HARMONY_MELODY_BY_SECTION or not sections or not stem_notes:
        return ""
    try:
        kk = _chd_key(f"RECOMMENDED KEY FOR DISCUSSION: {key}." if key else "")
        pitched = {s_: _hm_pitched(stem_notes.get(s_)) for s_ in ("vocals", "bass") + _HM_ACC_STEMS}
        vocal_absent = _hm_vocal_absent(context_text)
        lines = []
        for sec in sections:
            try:
                a, b = float(sec["start"]), float(sec["end"])
            except Exception:
                continue
            name = str(sec.get("name") or "").strip() or "Section"
            if b - a < 3.0 or name.lower().startswith("silence"):
                continue
            chords = _hm_section_chords(stem_notes, a, b, kk)
            parts = ["chords " + (", ".join(chords) + _chd_outside_note(chords, kk) if chords else "none clear")]
            lead_stem, lead = _hm_lead(pitched, a, b, instrumental, vocal_absent)
            if not lead:
                parts.append("no clear lead line")
            else:
                lm = [x[2] for x in lead]
                lo, hi = np.percentile(lm, 10), np.percentile(lm, 90)
                med = float(np.median(lm))
                who = "the voice" if lead_stem == "vocals" else f"the {lead_stem} stem"
                parts.append(f"lead line: {who}, {_hm_name(lo)}-{_hm_name(hi)}")
                acc = [x for st in _HM_ACC_STEMS if st != lead_stem for x in pitched.get(st, []) if a <= x[0] < b]
                if len(acc) >= 8:
                    d = med - float(np.median([x[2] for x in acc]))
                    rel = ("well above the chords" if d >= 7 else "just above the chords" if d >= 2
                           else "inside the chords' range" if d > -2 else "below the chords")
                    parts.append(rel if HM_PLAIN_FIGURES else f"{rel} ({d:+.0f} semitones)")
                bass = [x for x in pitched.get("bass", []) if a <= x[0] < b]
                if len(bass) >= 8 and lead_stem != "bass":
                    _db = med - float(np.median([x[2] for x in bass]))
                    parts.append(_hm_octaves_above_bass(_db) if HM_PLAIN_FIGURES
                                 else f"{_db:.0f} semitones above the bass")
                support = [x for st in ("bass",) + _HM_ACC_STEMS if st != lead_stem for x in pitched.get(st, [])
                           if a <= x[0] < b]
                hits = tot = 0
                for on, dur, m in lead:
                    pcs = {int(round(y[2])) % 12 for y in support if y[0] <= on + 0.05 < y[0] + y[1]}
                    if not pcs:
                        continue
                    tot += 1
                    hits += int(int(round(m)) % 12 in pcs)
                if tot >= 8:
                    share = hits / float(tot)
                    desc = ("mostly on notes the accompaniment is playing (sits inside the harmony)" if share >= 0.6
                            else "a mix of notes the accompaniment is playing and notes it is not "
                                 "(passing or colour notes)" if share >= 0.35
                            else "mostly on notes the accompaniment is not playing at that moment "
                                 "(moves independently of the chords, or adds tension)")
                    parts.append(desc if HM_PLAIN_FIGURES
                                 else f"{share * 100:.0f}% of its notes match the accompaniment -- {desc}")
            lines.append(f"  {name} ({_seconds_to_mmss(a)}-{_seconds_to_mmss(b)}): " + "; ".join(parts))
        if not lines:
            return ""
        return (f"{_HM_HEAD} (measured from this recording's transcribed notes; drums are never counted; chords "
                "are the ones heard most in each section, ranked, not an exact progression; the lead line is the "
                "voice where it sings, otherwise the most melody-like single-note part -- never the bass; "
                "transcription is probabilistic, so treat these as tendencies):\n" + "\n".join(lines))
    except Exception:
        return ""


def build_melody_understanding_block(sections, stem_notes, bpm=None, key=None):
    """Top-level melodic evidence block assembled purely from raw stem MIDI.

    Header states the provenance explicitly so the writing model treats it as
    measurement of this recording rather than as something it could substitute
    background knowledge for.
    """
    if not stem_notes:
        return ""
    body = _build_melody_per_section(sections or [], stem_notes, bpm=bpm, key=key)
    if not body:
        return ""
    header = (
        "=== MELODIC ANALYSIS (measured from this recording's raw stem MIDI) ===\n"
        "Every pitch, interval, contour, motif and range below was computed "
        "arithmetically from the transcribed note events of this specific "
        "recording. It is not derived from the reference database, file tags, "
        "or any prior knowledge of the song, and must not be replaced or "
        "'corrected' by those sources. Transcription is probabilistic, so treat "
        "isolated short notes with caution -- but the contour, range, motion and "
        "recurring-figure statements are direct measurements.\n"
    )
    return header + body


def _confirmed_vocal_onset(notes, min_notes=5, window_seconds=3.0, max_range_semitones=12,
                            max_gap_seconds=1.0, min_distinct_pitches=3):
    """The literal earliest onset in a transcribed vocal stem is not always
    the true entrance. A sustained harmonic or percussive element bleeding
    into the vocal stem from elsewhere in the mix (a ringing cymbal, a guitar
    harmonic) can register as one or more notes before the real voice ever
    starts, and it does not look like a sung phrase once you look at what
    surrounds it: either the same pitch repeated many times with no melodic
    movement, or a scatter of notes leaping by huge, non-melodic intervals.
    A genuine sung entrance instead shows several notes close together in
    time, moving in a fairly narrow pitch range with real (but not wild)
    variation -- confirmed against a real case where the reported onset
    (an isolated note followed by a two-octave leap) was ~16 seconds early.

    Walks the notes in onset order and returns the first one that begins a
    window meeting all of: enough notes close together in time (no gap
    bigger than max_gap_seconds), a tight overall pitch range (a real
    melodic phrase does not span more than an octave in a few seconds), and
    genuine pitch movement (not one repeated tone). Falls back to the literal
    earliest onset if nothing in the stem satisfies this -- reporting a
    possibly-noisy true earliest note is better than reporting nothing, and
    this matched the literal-earliest onset exactly on every other track
    checked, so it only moves the answer when the leading note actually
    looks unlike a sung phrase.
    """
    try:
        ordered = sorted(notes, key=lambda n: n["onset"])
        for i in range(len(ordered)):
            t0 = ordered[i]["onset"]
            win = [n for n in ordered[i:] if n["onset"] < t0 + window_seconds]
            if len(win) < min_notes:
                continue
            gaps = [win[j + 1]["onset"] - win[j]["onset"] for j in range(len(win) - 1)]
            if gaps and max(gaps) > max_gap_seconds:
                continue
            midi_pitches = [
                69 + 12 * math.log2(max(1.0, float(n.get("frequency", 0) or 0)) / 440.0)
                for n in win
            ]
            pitch_range = max(midi_pitches) - min(midi_pitches)
            if pitch_range > max_range_semitones:
                continue
            if len({round(p) for p in midi_pitches}) < min_distinct_pitches:
                continue  # a single held/repeated tone, not a sung phrase
            return float(ordered[i]["onset"])
    except Exception:
        pass
    return float(min(n["onset"] for n in notes)) if notes else 0.0


def summarize_stem_midi(stem, raw_notes, filtered, removed, preset, stem_rms=None, bpm=None,
                         sections=None, section_rms=None, key=None, stem_path=None):
    """Build a compact per-stem summary. Returns (text, meta_dict) where meta
    holds activity stats used for the cross-stem prominence ranking.

    `stem_path` (optional): the separated stem's own audio file. Required for
    the drum production/timbre analysis, which measures how the kit SOUNDS
    rather than what it plays. That analysis referenced an undefined `stems`
    name, so every call raised NameError into a bare except and the whole
    drum-sound block -- kick weight, snare decay and room, hat character, bus
    compression, programmed-vs-played -- was silently dropped from every scan
    ever produced. Nothing described drum tone, so tone questions were answered
    from genre habit.

    `stem_rms` is now the WHOLE-TRACK energy reading (see _stem_rms /
    _stem_rms_by_section) -- it used to silently only cover the first ~60s.
    `section_rms` (optional): per-section RMS list from _stem_rms_by_section,
    used to render an INTENSITY BY SECTION block for every stem, not just
    drums. `key` (optional): track key string, used for scale-degree framing
    in melodic-line summaries.
    """
    lines = [f"[{stem.upper()} stem]"]
    meta = {
        "stem": stem,
        "rms": float(stem_rms) if stem_rms is not None else None,
        "note_count": len(filtered) if filtered else 0,
        "density": 0.0,
        "is_drums": stem == "drums",
        "silent": False,
    }

    if stem_rms is not None:
        lines.append(f"stem energy (RMS, whole track): {float(stem_rms):.5f}")

    intensity_block = _format_intensity_by_section(stem, section_rms) if section_rms else ""
    if intensity_block:
        lines.append(intensity_block)

    if not raw_notes:
        lines.append("No reliable MIDI notes detected.")
        meta["silent"] = True
        return "\n".join(lines), meta

    # raw_notes already contains the removed notes (filtered = raw - removed).
    # Adding `removed` again understated the removal ratio.
    total_raw = len(raw_notes)
    removed_ratio = removed / total_raw if total_raw > 0 else 0.0

    quality = "medium"
    if len(filtered) < 10 or removed_ratio > 0.6:
        quality = "low"
    elif len(filtered) >= 30 and removed_ratio < 0.25:
        quality = "high"

    # This rating is how many notes survived the range/length/level filters
    # and how many there are -- it says nothing about whether the transcriber
    # got the notes right, so it must not be worded as transcription confidence.
    lines.append(
        f"note count after filtering: {len(filtered)} (raw {len(raw_notes)}, filtered out {removed}); "
        f"filter retention: {quality} (how much of the transcription survived the range/"
        "length/level filters -- not a measure of transcription accuracy)"
    )

    if stem == "drums" and any(n.get("detected_from") == "onset-band fallback" for n in (raw_notes or [])):
        lines.append(
            "NOTE: Omnizart returned no drum hits for this track, so the hits below come from a "
            "band-split onset detector. 'kick'/'snare'/'hihat' here mean low/mid/high-band hits "
            "(mid can include toms); treat the kit labels and grid families as approximate."
        )
    if stem == "drums":
        lines.append(
            "Drum/percussion stem: Omnizart drum transcription (not pitched MIDI). "
            "Use hit-type breakdown, per-type spacing, and the pattern sample below "
            "for rhythm/groove discussion. IMPORTANT LIMIT: this transcription model "
            "resolves only three classes -- kick, snare and hi-hat. Toms, crashes, "
            "rides, shakers, claps and other percussion are NOT detectable here and "
            "will be silently folded into those three or missed entirely, so the "
            "breakdown below is a partial view of the kit, not a complete inventory. "
            "Never state or imply that a track has no toms, no cymbals or no "
            "percussion on the strength of this list, and do not present the three "
            "classes as the full kit; if the whole-mix or drum-stem instrument tags "
            "name cymbals, tambourine or other percussion, believe those instead."
        )

    if not filtered:
        lines.append("No notes remained after filtering.")
        meta["silent"] = True
        return "\n".join(lines), meta

    if stem == "vocals":
        # Measured directly from the transcribed vocal stem's note onsets --
        # not a guess. Surfaced as its own explicit line (rather than left
        # buried in the full note list) because the listening model has no
        # reliable temporal grounding and defaults to assuming an
        # instrumental intro unless told otherwise, even when the vocal
        # stem shows a note starting within the first few seconds.
        _first_vocal_onset = _confirmed_vocal_onset(filtered)
        lines.append(
            f"EARLIEST VOCAL ONSET: {_seconds_to_mmss(_first_vocal_onset)} "
            f"({_first_vocal_onset:.1f}s) -- measured directly from the transcribed vocal "
            "stem, not an impression. If this is only a few seconds into the track, vocals "
            "are present at or near the very start -- do NOT describe the opening/intro as "
            "purely instrumental, or say vocals 'enter later' / 'after an instrumental intro', "
            "when this measured value is small. Trust this measurement over any general "
            "assumption that songs typically open with an instrumental intro before the voice. "
            "Exception: when the vocal pass reports VOCALS_PRESENT=no, this onset is separation "
            "residue (instruments leaking into the vocals stem), not a voice."
        )

    if stem == "drums":
        # Percussion has no real pitch — report type breakdown, density, and
        # a compact rhythm description instead of full hit lists.
        type_counts = {}
        for n in filtered:
            drum_type = n.get("drum_type", "other")
            type_counts[drum_type] = type_counts.get(drum_type, 0) + 1
        type_summary = ", ".join(
            f"{drum_type} ({count})" for drum_type, count in sorted(type_counts.items(), key=lambda kv: -kv[1])
        )
        lines.append(f"hit breakdown by drum type: {type_summary}")

        onset_times = [n["onset"] for n in filtered]
        offsets = sorted(n["offset"] for n in filtered)
        j = 0
        total_active = 0
        max_poly = 0
        for i, t in enumerate(onset_times):
            while j < len(offsets) and offsets[j] <= t:
                j += 1
            active = (i + 1) - j
            if active > max_poly:
                max_poly = active
            total_active += active
        avg_poly = total_active / len(filtered) if filtered else 0.0
        lines.append(f"average simultaneous hits: {avg_poly:.1f}; maximum simultaneous hits: {max_poly}")

        min_onset = float(np.min(onset_times))
        max_offset = float(np.max([n["offset"] for n in filtered]))
        dur = max(0.1, max_offset - min_onset)
        density = len(filtered) / dur * 60.0 if dur > 0 else 0.0
        meta["density"] = density
        lines.append(f"hit density: {density:.1f} hits/min")

        for rhythm_line in _summarize_drum_rhythm(
            filtered, max_pattern_hits=STEM_MIDI_DRUM_PATTERN_HITS, bpm=bpm
        ):
            lines.append(rhythm_line)

        # When the kit enters, drops out, and changes shape. Independent of the
        # section map, so it still answers "when do the drums come in" on
        # tracks whose structure is unlabelled or generically named.
        if sections:
            section_blocks = _summarize_drum_rhythm_by_section(
                filtered, sections, bpm, max_pattern_hits=max(8, STEM_MIDI_DRUM_PATTERN_HITS // 2)
            )
            if section_blocks:
                lines.append(
                    "Per-section groove (from this track's own STRUCTURE boundaries; use these, "
                    "not the whole-track pattern, when asked about the groove in a specific "
                    "section like the verse or chorus):"
                )
                lines.extend(section_blocks)

        if stem_rms is not None:
            band, dens_name = _stem_activity_label(stem_rms, density, is_drums=True)
            lines.append(f"activity/prominence: {band} (from RMS + {dens_name})")

        # Recover cymbal onsets from the audio and add them as an extra
        # drum_type. Everything downstream (grids, arrangement timeline,
        # section grooves) then gets a cymbal row for free, and the
        # transcribed kick/snare/hat data is left exactly as measured.
        try:
            _cym = detect_cymbal_onsets(
                stem_path, _structure_stem_evidence({"drums": filtered})["drums"])
            if _cym:
                filtered = list(filtered) + [
                    {"onset": t, "duration": 0.25, "amplitude": 0.5,
                     "drum_type": "cymbal", "detected_from": "audio"}
                    for t in _cym
                ]
                filtered.sort(key=lambda n: float(n.get("onset") or 0.0))
                # Hand the augmented list back so section grids, the arrangement
                # timeline and the saved MIDI all include the cymbal row. It was
                # previously local to this function only.
                meta["augmented_notes"] = filtered
                lines.append(
                    f"CYMBALS (detected from the drums-stem audio, not from the note "
                    f"transcription, which cannot represent them): {len(_cym)} cymbal "
                    "hits located by high-band sustain. These appear as a 'cymbals' row "
                    "in the beat grids and arrangement timeline below. Treat their "
                    "TIMING as measured but their exact type (crash vs ride vs open "
                    "hat) as undetermined. KNOWN LIMIT: this finds ACCENTED cymbals -- "
                    "crashes marking a section or an accent -- because it works by "
                    "spotting a hit whose top end rings on above the track's usual "
                    "level. A ride or hat pattern played continuously RAISES that usual "
                    "level, so a steady ride is generally NOT captured here. A missing "
                    "cymbals row therefore means no accented cymbal was found, never "
                    "that the track has no cymbals; if the ADDITIONAL PERCUSSION block "
                    "reports sustained cymbals, believe that for presence and use this "
                    "row only for placement."
                )
        except Exception as e:
            print(f"  (cymbal onset detection skipped: {e})")

        # Kit entry/exit timeline, built after cymbal detection so the
        # 'cymbals' row the note above promises is really there.
        try:
            lines.extend(_summarize_drum_entry_timeline(filtered, bpm=bpm))
        except Exception:
            pass

        # One representative grid for the track as a whole, so a beat diagram
        # can still be given when no section map exists.
        try:
            _grid = build_beat_grid_diagram(filtered, bpm, label="representative bars")
            if _grid:
                lines.append(_grid)
        except Exception:
            pass

        # Kit pieces the three-class transcription cannot see at all.
        try:
            _extras = _format_drum_extras(_drum_extras_probe(stem_path))
            if _extras:
                lines.append(_extras)
        except Exception:
            pass

        # How the kit SOUNDS, measured from the separated drums audio itself.
        # The rest of this block covers what is played; nothing described the
        # tone, so drum production was previously answered from genre habit.
        try:
            _drum_sound = build_drum_production_report(
                stem_path, filtered, bpm=bpm
            )
            if _drum_sound:
                lines.append("")
                lines.append(_drum_sound)
        except Exception as e:
            # Loud on purpose: this block failed silently for a long time.
            print(f"  (drum sound analysis skipped: {e})")

        if quality == "low" or removed_ratio > 0.5:
            lines.append("Caution: this stem contains likely spurious/erratic onsets; treat only broad rhythmic tendencies as reliable.")

        # --- Drum event inclusion ---
        if FULL_MIDI_TRANSCRIPTION:
            # True full transcription: every filtered hit, not an evenly
            # sampled subset (that would just be a bigger "limited" mode).
            log = _drum_events_to_full_log(filtered)
            if log:
                lines.append(
                    f"full hit list ({len(filtered)} hits): {log}"
                )
        elif STEM_MIDI_INCLUDE_EVENT_LOGS:
            event_log = _drum_events_to_event_log(filtered, max_notes=STEM_MIDI_EVENT_LOG_MAX_NOTES)
            if event_log:
                label = "hit events (compact)" if STEM_MIDI_COMPACT_EVENT_FORMAT else "hit events (rhythm-JSON)"
                lines.append(f"{label}: {event_log}")

        return "\n".join(lines), meta
        

    # --- Pitched stems (vocals/bass/guitar/piano/other) ---
    if stem == "other" and (
        all(n.get("detected_from") == "onset-band fallback" for n in filtered)
        or not any(
            preset.get("min_frequency", 0) <= n["frequency"] <= preset.get("max_frequency", 100000)
            for n in filtered
        )
    ):
        # Onset-fallback mode: report hit density only, skip pitch stats. The
        # fallback's "frequency" is a band proxy, not a pitch, so this must key
        # on the explicit flag -- the pitch-range test alone never fired.
        onset_times = [n["onset"] for n in filtered]
        min_onset = float(np.min(onset_times)) if onset_times else 0
        max_offset = float(np.max([n["offset"] for n in filtered])) if filtered else 0
        dur = max(0.1, max_offset - min_onset)
        density = len(filtered) / dur * 60.0 if dur > 0 else 0.0
        meta["density"] = density
        lines.append(f"onset/hit density: {density:.1f} events/min (no reliable pitched content detected)")
        if stem_rms is not None:
            band, dens_name = _stem_activity_label(stem_rms, density, is_drums=False)
            lines.append(f"activity/prominence: {band} (from RMS + {dens_name})")
        # --- Note event inclusion ---
        if FULL_MIDI_TRANSCRIPTION:
            # True full transcription: every filtered event, not a capped sample.
            log = _notes_to_full_log(filtered)
            if log:
                lines.append(
                    f"full note list ({len(filtered)} notes): {log}"
                )
        elif STEM_MIDI_INCLUDE_EVENT_LOGS:
            event_log = _notes_to_event_log(filtered, max_notes=STEM_MIDI_EVENT_LOG_MAX_NOTES)
            if event_log:
                label = "note events (compact)" if STEM_MIDI_COMPACT_EVENT_FORMAT else "note events (MIDI-JSON)"
                lines.append(f"{label}: {event_log}")
        return "\n".join(lines), meta

    freqs = np.array([n["frequency"] for n in filtered], dtype=float)
    # Absolute min/max often pick up octave errors, harmonics, or bleed.
    # Prefer a percentile "practical" range for discussion, especially vocals.
    f_min = float(np.min(freqs))
    f_max = float(np.max(freqs))
    p10 = float(np.percentile(freqs, 10))
    p90 = float(np.percentile(freqs, 90))
    lines.append(
        f"pitch range (absolute): {_hz_to_note_name(f_min)} ({round(f_min, 1)} Hz) "
        f"to {_hz_to_note_name(f_max)} ({round(f_max, 1)} Hz)"
    )
    lines.append(
        f"practical pitch range (10–90%): {_hz_to_note_name(p10)} ({round(p10, 1)} Hz) "
        f"to {_hz_to_note_name(p90)} ({round(p90, 1)} Hz) — prefer this for main range; "
        f"absolute extremes often include harmonics/octave errors"
    )

    med = float(np.median(freqs))
    lines.append(f"median pitch: {med:.1f} Hz (~{_hz_to_note_name(med)})")

    pc_counts = {}
    for n in filtered:
        pc = _hz_to_pitch_class(n["frequency"])
        if pc is not None:
            name = NOTE_NAMES[pc]
            pc_counts[name] = pc_counts.get(name, 0) + 1

    top_pitches = ", ".join(f"{p} ({c})" for p, c in sorted(pc_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:8])
    lines.append(f"most common pitch classes: {top_pitches}")

    onset_times = [n["onset"] for n in filtered]
    offsets = sorted(n["offset"] for n in filtered)
    j = 0
    total_active = 0
    max_poly = 0

    for i, t in enumerate(onset_times):
        while j < len(offsets) and offsets[j] <= t:
            j += 1
        active = (i + 1) - j
        if active > max_poly:
            max_poly = active
        total_active += active

    avg_poly = total_active / len(filtered) if filtered else 0.0
    lines.append(f"average simultaneous notes: {avg_poly:.1f}; maximum polyphony: {max_poly}")

    chords = _detect_common_chords(filtered, max_count=5)
    if chords:
        parsed_key = _parse_key_root_quality(key)
        chord_parts = []
        for label, count in chords:
            part = f"{label} x{count}"
            if parsed_key:
                m = re.match(r"([A-G]#?)\s+(major|minor)", label)
                if m:
                    letter = m.group(1)
                    root_pc = _NOTE_LETTER_PC.get(letter[0].upper())
                    if root_pc is not None:
                        if len(letter) > 1 and letter[1] == "#":
                            root_pc += 1
                        deg = _scale_degree_label(root_pc % 12, parsed_key[0], parsed_key[1])
                        part += f" [chord root = scale degree {deg}]"
            chord_parts.append(part)
        lines.append("common harmonic clusters: " + "; ".join(chord_parts))
    else:
        lines.append("no stable harmonic clusters detected")

    # Monophonic stems (vocals/bass) get the full melodic-line budget;
    # dense poly stems get half — their "lowest line" is less reliable and
    # the long note lists are a common source of token bloat.
    melody_budget = STEM_MIDI_MELODY_LINE_NOTES
    if not preset.get("monophonic"):
        melody_budget = max(12, STEM_MIDI_MELODY_LINE_NOTES // 2)

    if preset.get("monophonic"):
        line_notes = _select_monophonic_line(filtered)
        mel = _summarize_melody(line_notes, max_notes=melody_budget, key_text=key, bpm=bpm)
        if mel:
            # Tag stem so the writer can talk about "the vocal line" vs "the bass line"
            lines.append(f"{stem} line: {mel}")
    else:
        low_notes = _lowest_line(filtered)
        mel = _summarize_melody(low_notes, max_notes=melody_budget, key_text=key, bpm=bpm)
        if mel:
            label = (
                f"{stem} lowest-line contour (supporting/inner line, not necessarily the tune)"
                if FULL_MIDI_TRANSCRIPTION
                else "lowest-line contour (not necessarily melody)"
            )
            lines.append(f"{label}: {mel}")

        # Full MIDI only: also sample a higher line so poly stems aren't only "bass of the chord"
        if FULL_MIDI_TRANSCRIPTION and len(filtered) >= 8:
            try:
                # Highest note in small time buckets ≈ upper voice sketch
                high_notes = sorted(filtered, key=lambda n: (-float(n["frequency"]), float(n["onset"])))
                # Re-sort chronologically after taking a frequency-biased sample
                high_sample = _evenly_sample_notes(
                    sorted(high_notes[: max(24, len(filtered) // 3)], key=lambda n: float(n["onset"])),
                    max(8, melody_budget // 2),
                )
                high_mel = _summarize_melody(high_sample, max_notes=max(8, melody_budget // 2),
                                             key_text=key, bpm=bpm)
                if high_mel:
                    lines.append(
                        f"{stem} upper-line sketch (approx top voice): "
                        + high_mel.replace("melodic line", "line", 1)
                    )
            except Exception:
                pass

    min_onset = float(np.min([n["onset"] for n in filtered]))
    max_offset = float(np.max([n["offset"] for n in filtered]))
    dur = max(0.1, max_offset - min_onset)
    density = len(filtered) / dur * 60.0 if dur > 0 else 0.0
    meta["density"] = density
    lines.append(f"note density: {density:.1f} notes/min")

    if stem_rms is not None:
        band, dens_name = _stem_activity_label(stem_rms, density, is_drums=False)
        lines.append(f"activity/prominence: {band} (from RMS + {dens_name})")

    if quality == "low" or stem == "other" or removed_ratio > 0.5:
        lines.append("Caution: this stem contains likely hallucinated/erratic notes; use only broad melodic/harmonic tendencies.")

    # --- Note/hit event inclusion ---
    if FULL_MIDI_TRANSCRIPTION:
        # True full transcription: every filtered event, not a capped sample.
        # (For monophonic stems we still select just the monophonic line --
        # that's picking the right notes, not limiting how many of them we
        # report -- and then report all of it.)
        if stem == "drums":
            log = _drum_events_to_full_log(filtered)
            if log:
                lines.append(
                    f"full hit list ({len(filtered)} hits): {log}"
                )
        else:
            if preset.get("monophonic"):
                pub_src = _select_monophonic_line(filtered) or filtered
            else:
                pub_src = filtered
            log = _notes_to_full_log(pub_src)
            if log:
                lines.append(
                    f"full note list ({len(pub_src)} notes): {log}"
                )
    elif STEM_MIDI_INCLUDE_EVENT_LOGS:
        # Original sampled event log (unchanged)
        if stem == "drums":
            event_log = _drum_events_to_event_log(filtered, max_notes=STEM_MIDI_EVENT_LOG_MAX_NOTES)
        else:
            event_log = _notes_to_event_log(filtered, max_notes=STEM_MIDI_EVENT_LOG_MAX_NOTES)
        if event_log:
            label = "hit events (compact)" if STEM_MIDI_COMPACT_EVENT_FORMAT else "hit events (rhythm-JSON)"
            lines.append(f"{label}: {event_log}")

    return "\n".join(lines), meta


_INSTRUMENT_TAGGER = None
_INSTRUMENT_TAGGER_LABELS = None
INSTRUMENT_TAGGER_IMPORT_ERROR = ""

# Raw per-window AudioSet probability matrices, keyed by file + window params
# (see _panns_cache_key). Lets the whole-mix instrument, genre, mood and
# production-effect passes share one set of network forward passes instead of
# each re-decoding and re-inferring the same audio.
_PANNS_WINDOW_CACHE = {}
_PANNS_WINDOW_CACHE_ORDER = []
# Separate insertion order for the (tiny) persistence-stats table, so it can
# outlive the probability matrices it was derived from.
_PANNS_TAG_STATS_ORDER = []
# Per-label persistence stats (hits / coverage / median prob) recorded by the
# most recent tagging pass. Held here rather than widened into the returned
# tuples so existing 3-tuple unpacking is untouched.
_PANNS_TAG_STATS = {}
# working-copy path (abs) -> original file to decode instead, for tagging.
_PANNS_SOURCE_OVERRIDE = {}


def register_panns_source(working_path, original_path):
    """Tag `original_path`'s audio whenever `working_path` is passed to the
    PANNs passes (cache keys and stats lookups keep using working_path)."""
    try:
        if (working_path and original_path
                and not str(original_path).startswith(("http://", "https://"))
                and os.path.exists(str(original_path))):
            _PANNS_SOURCE_OVERRIDE[os.path.abspath(str(working_path))] = str(original_path)
    except Exception:
        pass

# AudioSet's 527 classes include lots of non-instrument sounds (crowd noise,
# applause, silence, etc). Map the musically relevant subset down to a small
# set of musician-facing labels; everything else is dropped. Several AudioSet
# labels can map to the same displayed tag (e.g. "Organ"/"Electronic organ"),
# which is intentional -- their probabilities are shown separately below.
#
# NOTE: this is a hard allowlist, not a threshold -- a raw label with no
# entry here is dropped no matter how confident the tagger is. The mallet
# percussion / hand percussion / bell / drone-instrument families below were
# previously entirely absent, so those instruments could never surface
# regardless of how clearly audible they were.
_INSTRUMENT_LABEL_MAP = {
    "electric guitar": "electric guitar", "acoustic guitar": "acoustic guitar",
    "guitar": "guitar (type uncertain)", "bass guitar": "bass guitar",
    "electric bass guitar": "bass guitar", "double bass": "upright bass",
    "piano": "piano", "electric piano": "electric piano", "keyboard (musical)": "keyboard/synth",
    "synthesizer": "synth", "sampler": "sampler/synth",
    "organ": "organ", "electronic organ": "organ", "hammond organ": "organ",
    "violin, fiddle": "strings (violin/fiddle)", "cello": "strings (cello)",
    "string section": "string section", "viola": "strings (viola)",
    "bowed string instrument": "strings (bowed, unspecified)",
    "pizzicato": "strings (pizzicato)",
    "trumpet": "brass (trumpet)", "trombone": "brass (trombone)",
    "brass instrument": "brass", "french horn": "brass (french horn)",
    "saxophone": "saxophone", "flute": "flute", "clarinet": "clarinet",
    "wind instrument, woodwind instrument": "woodwind (unspecified)",
    "harmonica": "harmonica", "accordion": "accordion",
    "drum kit": "drum kit", "drum": "drums", "drum machine": "drum machine",
    "snare drum": "snare", "bass drum": "kick", "hi-hat": "hi-hat", "cymbal": "cymbal",
    "timpani": "timpani", "percussion": "percussion (unspecified)",
    "tambourine": "tambourine", "harp": "harp", "banjo": "banjo",
    "mandolin": "mandolin", "ukulele": "ukulele", "sitar": "sitar",
    "zither": "zither", "plucked string instrument": "plucked strings (unspecified)",
    "steel guitar, slide guitar": "slide/steel guitar", "electric organ": "organ",
    # Mallet / tuned percussion -- previously entirely unmapped.
    "marimba, xylophone": "marimba/xylophone", "glockenspiel": "glockenspiel",
    "vibraphone": "vibraphone", "steelpan": "steelpan/steel drum",
    "tubular bells": "tubular bells/chimes", "mallet percussion": "mallet percussion (unspecified)",
    # Hand/world percussion -- previously entirely unmapped.
    "tabla": "tabla", "gong": "gong", "wood block": "wood block",
    "maraca": "maraca/shaker", "rattle (instrument)": "shaker/rattle",
    # Bells -- previously entirely unmapped.
    "bell": "bell", "church bell": "church bell", "jingle bell": "jingle bells",
    "chime": "chimes", "wind chime": "wind chimes", "tuning fork": "tuning fork",
    # Drone / world / other melodic instruments -- previously entirely unmapped.
    "bagpipes": "bagpipes", "didgeridoo": "didgeridoo", "shofar": "shofar",
    "theremin": "theremin", "singing bowl": "singing bowl",
    "harpsichord": "harpsichord",
    "orchestra": "orchestra/large ensemble",
    "scratching (performance technique)": "turntable scratching",
    "beatboxing": "beatboxing",
    # Guitar performance techniques -- AudioSet scores these separately from
    # the instrument itself, and they are strong positive evidence that a real
    # played guitar is present rather than a synth patch that merely sounds
    # guitar-ish, which is exactly the confusion the guitar threshold exists
    # to guard against.
    "strum": "strummed chords (guitar family)",
    "tapping (guitar technique)": "guitar technique (tapping)",
    # Kit detail the drum map was missing.
    "rimshot": "rimshot",
    "drum roll": "drum roll",
    "cowbell": "cowbell",
    # Vocal-as-arrangement-texture only. Deliberately excludes singing /
    # male singing / female singing / child singing: lead-vocal identity,
    # gender and age are decided by the dedicated vocal pipeline (F0 analysis
    # + vocal audit + identity resolution), and duplicating those judgements
    # from a coarse AudioSet class would create a second, weaker opinion that
    # could contradict it. These four are arrangement details that pipeline
    # does not cover.
    "choir": "choir/vocal ensemble",
    "chant": "chant",
    "humming": "humming",
    "whistling": "whistling",
}

# Production / signal-character AudioSet classes. These are NOT instruments,
# so they are kept out of _INSTRUMENT_LABEL_MAP (where they would compete for
# the instrument top-k and get reported as if they were parts in the
# arrangement). They feed the production analysis block instead: audible
# distortion, obvious reverb or echo, and noise-floor character are the kind
# of mix evidence TIMBRE and the era estimate ask for but nothing measured.
# Labels absent from this checkpoint's AudioSet vocabulary are simply never
# matched, so listing an uncertain name here is harmless.
_PRODUCTION_LABEL_MAP = {
    "distortion": "audible distortion/saturation",
    "reverberation": "audible reverb",
    "echo": "audible echo/delay",
    "chorus effect": "chorus/modulation effect",
    "effects unit": "outboard/effects processing",
    "wah-wah": "wah-wah",
    "sound effect": "sound effects/production FX",
    "noise": "broadband noise",
    "white noise": "white noise",
    "pink noise": "pink noise",
    "static": "static/crackle",
    "hum": "hum",
    "mains hum": "mains hum (50/60 Hz)",
    "sine wave": "pure tone/sine",
    "vibration": "low-frequency rumble",
}

# Genre-adjacent AudioSet classes -- a broad, YouTube-metadata-derived taxonomy,
# not a music-critic's genre ontology. Kept intentionally coarse; multiple
# entries can and do co-fire on the same track (e.g. "Electronic music" and
# "House music"), which is expected and left visible rather than collapsed.
